  var withNum = /^(\S.*?[A-Za-z].*?)\s+([0-9][0-9\s\u00a0\u202f.,]*)$/.exec(key)
    || /^([0-9][0-9\s\u00a0\u202f.,]*?)\s+(\S.*?[A-Za-z].*)$/.exec(key);
  if (withNum) {
    var numFirst = /^[0-9]/.test(withNum[1]);
