  if (root.nodeType !== 1 && root.nodeType !== 9 && root.nodeType !== 11) return;
  if (root.nodeType === 1 && I18N_BOXES[root.tagName]) {
    if (!i18nAttrsSkip(root)) i18nAttrs(root, true);
    return;
