<script nonce="<?= h($nonce) ?>">
(function () {
  var form = document.getElementById('signin-form');
  var said = document.getElementById('in-said');
  var go = document.getElementById('in-go');
  /* One short sentence, with the whole of it under the pointer. Both are
     put in with textContent: whatever a directory says comes back through
     this page word for word, and a directory is a place somebody else can
     write into. */
  function sayBad(words, detail) {
    said.className = 'said bad';
    said.textContent = '';
    said.removeAttribute('tabindex');
    said.appendChild(document.createTextNode(String(words || 'that did not work')));
    if (!detail || String(detail) === String(words)) return;
    said.className = 'said bad why';
    said.setAttribute('tabindex', '0');
    /* The box below and nothing else: a `title` as well would put the
       browser's own white tooltip on top of it. */
    var box = document.createElement('div');
    box.className = 'whybox';
    box.textContent = String(detail);
    said.appendChild(box);
  }
  form.addEventListener('submit', function (e) {
    e.preventDefault();
    said.className = 'said';
    said.textContent = '';
    said.removeAttribute('title');
    said.removeAttribute('tabindex');
    go.disabled = true;
    /* Only the words change: replacing the whole button takes its icon with
       them and the button jumps about while it is working. */
    var words = go.querySelector('span');
    if (words) words.textContent = 'Signing in…'; else go.textContent = 'Signing in…';
    fetch('?api=login', {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({
        name: document.getElementById('in-name').value,
        password: document.getElementById('in-pass').value
      })
    }).then(function (r) { return r.json().then(function (d) { return {ok: r.ok, d: d}; }); })
      .then(function (got) {
        if (got.ok && got.d && got.d.ok !== false) {
          said.className = 'said good';
          said.textContent = 'Welcome back.';
          location.reload();
          return;
        }
        sayBad((got.d && got.d.error) || 'that did not work',
               (got.d && got.d.detail) || '');
        go.disabled = false;
        if (words) words.textContent = 'Sign in'; else go.textContent = 'Sign in';
        document.getElementById('in-pass').value = '';
        document.getElementById('in-pass').focus();
      })
      .catch(function (e) {
        sayBad('this dashboard could not be reached',
               'the browser could not reach ' + location.host + ': ' + (e && e.message ? e.message : e));
        go.disabled = false;
        if (words) words.textContent = 'Sign in'; else go.textContent = 'Sign in';
      });
  });
  document.getElementById('in-name').focus();
}());
</script>
</body>
</html>
