<script nonce="<?= h($nonce) ?>">
'use strict';
/* ==========================================================================
   The page's own state. Everything drawn comes out of here, and everything
   here comes out of the daemon: the page works nothing out for itself, so
   what it shows and what the daemon would do can never drift apart.
   ========================================================================== */
var ME = <?= json_encode($me, JSON_UNESCAPED_UNICODE | JSON_HEX_TAG | JSON_HEX_AMP) ?>;
var STATUS = <?= $initial
    ? json_encode($initial, JSON_UNESCAPED_UNICODE | JSON_HEX_TAG | JSON_HEX_AMP)
    : 'null' ?>;
var ADMIN = ME && ME.role === 'fulladmin';
/* Whether the PHP running this page is safe from php2shell, as it says of
   itself (1.10.218); only an administrator is told. */
var PHP_SAFETY = <?= ($me && ($me['role'] ?? '') === 'fulladmin')
    ? json_encode(isemon_php_safety(), JSON_HEX_TAG | JSON_HEX_AMP) : 'null' ?>;
(function phpSafety() {
  var box = document.getElementById('phpsafety');
  var s = PHP_SAFETY;
  if (!box || !s || (s.patched && s.guarded)) return;
  if (s.patched) return;
