  EE:'Estonia',EG:'Egypt',EH:'Western Sahara',ER:'Eritrea',ES:'Spain',ET:'Ethiopia',
  EU:'the European Union',FI:'Finland',FJ:'Fiji',FK:'the Falkland Islands',FM:'Micronesia',
  FO:'Faroe Islands',FR:'France',GA:'Gabon',GB:'the United Kingdom',GD:'Grenada',GE:'Georgia',
  GF:'French Guiana',GG:'Guernsey',GH:'Ghana',GI:'Gibraltar',GL:'Greenland',GM:'the Gambia',
  GN:'Guinea',GP:'Guadeloupe',GQ:'Equatorial Guinea',GR:'Greece',GS:'South Georgia',
  GT:'Guatemala',GU:'Guam',GW:'Guinea-Bissau',GY:'Guyana',HK:'Hong Kong',
  HM:'Heard and McDonald Islands',HN:'Honduras',HR:'Croatia',HT:'Haiti',HU:'Hungary',
  IC:'the Canary Islands',ID:'Indonesia',IE:'Ireland',IL:'Israel',IM:'Isle of Man',IN:'India',
  IO:'the British Indian Ocean Territory',IQ:'Iraq',IR:'Iran',IS:'Iceland',IT:'Italy',
  JE:'Jersey',JM:'Jamaica',JO:'Jordan',JP:'Japan',KE:'Kenya',KG:'Kyrgyzstan',KH:'Cambodia',
