  MF:'Saint Martin',MG:'Madagascar',MH:'the Marshall Islands',MK:'North Macedonia',ML:'Mali',
  MM:'Myanmar',MN:'Mongolia',MO:'Macao',MP:'the Northern Mariana Islands',MQ:'Martinique',
  MR:'Mauritania',MS:'Montserrat',MT:'Malta',MU:'Mauritius',MV:'Maldives',MW:'Malawi',
