/** The country's own name, or the two letters when it has none here. */
function countryWords(cc) {
  var two = String(cc || '').toUpperCase();
  if (!two) return 'every country';
  var said = COUNTRY_NAME[two];
  if (!said) return two;
  /* "the Netherlands" reads properly inside a sentence and badly as a label,
     so the label gets it back the other way up. */
  return said.charAt(0).toUpperCase() + said.slice(1);
}

/** Turn a plain <select> of two-letter codes into a country picker.

    The select stays where it is and goes on being the value: everything
    that reads `.value`, fills it with `fillOnce` or listens for `change`
    carries on working, and what somebody sees is a flag, a name and a
    number instead of two letters. Called again on the same select does
    nothing, so a page that redraws its filters cannot stack them up. */
function asCountryPick(select, counts) {
  if (!select) return null;
  if (select._ccpick) { select._ccpick.counts = counts || select._ccpick.counts; 
                        select._ccpick.paint(); return select._ccpick; }
  var wrap = el('span', 'ccpick');
  var button = el('button', 'ccbtn');
  button.type = 'button';
  var panel = el('div', 'ccpanel');
  var find = el('input');
  find.type = 'search';
  find.placeholder = 'Germany, DE\u2026';
  find.autocomplete = 'off';
  var body = el('div', 'ccbody');
  panel.appendChild(find);
  panel.appendChild(body);
  select.parentNode.insertBefore(wrap, select);
  wrap.appendChild(button);
  wrap.appendChild(panel);
  select.hidden = true;
  select.style.display = 'none';
  var me = {counts: counts || null, at: 0};

  function codes() {
    return Array.prototype.slice.call(select.options, 1)
      .map(function (o) { return String(o.value || '').toUpperCase(); }).filter(Boolean);
  }
  function label() {
    clear(button);
    var now = String(select.value || '').toUpperCase();
    if (!now) {
      /* Not muted: the selects beside it say "every device" and "both
         nodes" in the ordinary colour, and one filter of the five being
         dimmer than the rest reads as one being switched off. */
      button.appendChild(el('span', '', 'every country'));
      return;
    }
    button.appendChild(countryBadge(now));
    button.appendChild(el('span', '', countryWords(now)));
  }
  function rows() {
    var want = find.value.trim().toLowerCase();
    var all = codes().filter(function (cc) {
      if (!want) return true;
      return cc.toLowerCase().indexOf(want) === 0
        || String(COUNTRY_NAME[cc] || '').toLowerCase().indexOf(want) >= 0;
    });
    all.sort(function (a, b) {
      return countryWords(a).localeCompare(countryWords(b));
    });
    return all;
  }
  function pick(cc) {
    select.value = cc;
    label();
    shut();
    select.dispatchEvent(new Event('change', {bubbles: true}));
  }
  function paint() {
    clear(body);
    var found = rows();
    var here = [''].concat(found);
    if (!found.length) {
      body.appendChild(el('div', 'ccnone', find.value.trim()
        ? 'No country here is called \u201c' + find.value.trim() + '\u201d'
        : 'Nothing has a country yet'));
      return;
    }
    here.forEach(function (cc, i) {
      var row = el('div', 'ccitem' + (i === me.at ? ' on' : ''));
      if (cc) {
        row.appendChild(countryBadge(cc));
        row.appendChild(el('span', 'ccname', countryWords(cc)));
        if (me.counts && me.counts[cc] !== undefined) {
          row.appendChild(el('span', 'ccn', num(me.counts[cc])));
        }
      } else {
        row.appendChild(el('span', 'ccname muted', 'every country'));
      }
      row.onmousedown = function (e) { e.preventDefault(); pick(cc); };
      body.appendChild(row);
    });
  }
  function shut() {
    wrap.classList.remove('open');
    document.removeEventListener('mousedown', away, true);
    window.removeEventListener('resize', placePanel);
  }
  function away(e) { if (!wrap.contains(e.target)) shut(); }
  /* Which side of the button this hangs from.

     It is 290px wide and the button it belongs to is the last thing in a
     toolbar, hard against the right edge of a card. Anchored at the
     button's left - which is the ordinary way to write a dropdown - the
     panel ends 290px further right than the button starts, which is off the
     end of the window. Nothing clips it: the document simply becomes that
     much wider, a horizontal scrollbar appears, and the whole page slides
     sideways the moment somebody opens a filter. That is what this is for.

     So the side is chosen when it opens, from where the button really is,
     and only then - the panel has no width at all while it is display:none.
     Right of the button if it fits, left of it if that fits instead, and
     where neither fits, pinned inside whatever is holding it.

     And what is holding it is not always the window. The same picker is on
     the filters inside a popup, and a popup is its own scrolling box: a
     panel that runs past ITS right edge makes THAT box wider, and the
     popup slides sideways exactly the way the page used to. Measuring the
     window there says the panel fits, because as far as the window is
     concerned it does. So every box between this button and the page that
     clips or scrolls is measured, and the panel is kept inside all of
     them. */
  function holdingBox() {
    /* The narrowest of the window and every box on the way up that does not
       let its contents hang out of it. `overflow` anything but `visible` -
       `auto`, `hidden`, `scroll` - is such a box: the first two scroll and
       so slide, the third clips and so swallows the panel. */
    var room = document.documentElement.clientWidth;
    var box = {left: 0, right: room};
    for (var node = wrap.parentNode;
         node && node.nodeType === 1 && node !== document.body;
         node = node.parentNode) {
      var how = window.getComputedStyle(node);
      if (how.overflowX === 'visible' && how.overflowY === 'visible') continue;
      var at = node.getBoundingClientRect();
      if (!at.width) continue;
      box.left = Math.max(box.left, at.left);
      box.right = Math.min(box.right, at.right);
    }
    if (box.right - box.left < 180) box = {left: 0, right: room};
    return box;
  }
  function placePanel() {
    /* `auto`, not empty. Emptying the inline style only puts the rule in
       the stylesheet back, and that one says `left:0` - so a panel moved to
       the right edge would have both sides set at once, and in that
       argument `left` wins and nothing appears to have happened. Each side
       is therefore said explicitly, every time. */
    panel.style.left = 'auto';
    panel.style.right = 'auto';
    panel.style.width = '';
    panel.style.maxWidth = '';
    var at = button.getBoundingClientRect();
    var box = holdingBox();
    var wide = panel.offsetWidth || 290;
    /* A floor under the whole thing: whatever side it ends up on, it may
       not be wider than the box it is in. The stylesheet says this against
       the window, which is the right answer only when the window is what
       is holding it. */
    panel.style.maxWidth = Math.max(180, box.right - box.left - 16) + 'px';
    if (at.left + wide <= box.right - 8) {
      panel.style.left = '0';
    } else if (at.right - wide >= box.left + 8) {
      panel.style.right = '0';
    } else {
      panel.style.left = (box.left + 8 - at.left) + 'px';
      panel.style.width = Math.max(180, box.right - box.left - 16) + 'px';
    }
  }
  function open() {
    me.at = 0;
    find.value = '';
    paint();
    wrap.classList.add('open');
    placePanel();
    document.addEventListener('mousedown', away, true);
    window.addEventListener('resize', placePanel);
    /* Focused without being scrolled to. A browser brings a focused box
       into view by scrolling whatever is holding it, and inside a popup
       whose lists are wider than it is - which is most of them - that is
       the popup sliding sideways under somebody's hand the moment the
       filter opens. The panel has already been put somewhere it can be
       seen; there is nothing to scroll to. */
    setTimeout(function () {
      try { find.focus({preventScroll: true}); } catch (e) { find.focus(); }
    }, 0);
  }
  button.onclick = function (e) {
    e.preventDefault();
    if (wrap.classList.contains('open')) shut(); else open();
  };
  find.addEventListener('input', function () { me.at = 0; paint(); });
  find.addEventListener('keydown', function (e) {
    var many = rows().length + 1;
    if (e.key === 'Escape') { e.stopPropagation(); shut(); button.focus(); return; }
    if (e.key === 'ArrowDown') { me.at = Math.min(many - 1, me.at + 1); paint(); e.preventDefault(); }
    if (e.key === 'ArrowUp') { me.at = Math.max(0, me.at - 1); paint(); e.preventDefault(); }
    if (e.key === 'Enter') {
      var found = [''].concat(rows());
      if (found.length > me.at) pick(found[me.at]);
      e.preventDefault();
    }
  });
  explain(button, select.getAttribute('title')
    || 'Show only the rows from one country. Search it by name or by its two letters; '
       + '<b>ZZ</b> is what the country database says about an address that belongs to '
       + 'nobody in particular - a private range, a reserved block, something unallocated.');
  select.removeAttribute('title');
  me.paint = label;
  select._ccpick = me;
  label();
  return me;
}

/* ---- a country, as a flag and two letters ------------------------------- */
function countryBadge(cc) {
  var box = el('span', 'cc');
  if (!cc) { box.appendChild(el('span', 'muted', '–')); return box; }
  var two = String(cc).toUpperCase();
  var img = document.createElement('img');
  img.className = 'flag';
  img.src = 'flags/' + two.toLowerCase() + '.svg';
  img.alt = '';
  img.loading = 'lazy';
  img.onerror = function () { img.remove(); };
  box.appendChild(img);
  box.appendChild(el('span', '', two));
  /* ZZ is not a country. It is what the country database says about an
     address that belongs to nobody in particular - a private range, a
     reserved block, something not allocated - and saying so is kinder than
     a blank flag nobody can place. */
  if (two === 'ZZ') {
    explain(box, 'Not a country: the country database has no place for this address. It is '
      + 'usually a private range (10.x, 172.16\u201331.x, 192.168.x), a reserved block, or '
      + 'something not allocated to anybody. Nothing is judged by a country either way.');
  }
  return box;
}

/* ==========================================================================
   What an address is called
   --------------------------------------------------------------------------
   The reverse zone knows things no record does: `10.20.30.40` is
   `nb-novak.example.loc`, and that is the first thing anybody reading a page of
   addresses wants. It is shown over the address rather than in a column of
   its own, because a column would change the shape of every table on this
   page and a name is not what anybody is scanning down.

   Nothing here ever waits. The daemon answers with the names it already
   has, puts the rest in a queue of its own, and this asks again a few
   seconds later for whatever was not ready. An address with a name gets a
   dotted underline, so that hovering is worth doing rather than a guess.

   A name is asked for as it was AT THE TIME of the row it sits on: a DHCP
   lease moves, so one address is one machine this morning and another this
   afternoon, and yesterday's refusals labelled with today's names would be
   a page telling a lie about every row on it.
   ========================================================================== */
var PTR = {};          /* address -> what it is called now */
var PTR_THEN = {};     /* "address|second" -> what it was called then */
var PTR_ADDS = 0;
var PTR_WANT = [];     /* the bits of page waiting to be told */
var PTR_SOON = null;   /* the timer that asks */
var PTR_AGAIN = null;  /* ...and the one that asks again for what was queued */
var PTR_ON = null;     /* whether the daemon is looking at all, once it has said */

function ptrKnown(ip, ts) {
  if (ts) {
    var then = PTR_THEN[ip + '|' + Math.round(ts)];
    if (then) return then;
  }
  return PTR[ip] || null;
}

/* Put the name on something already drawn. Called again whenever an answer
   arrives, so a row drawn before the name was known is not left behind. */
function ptrSay(node, ip, ts) {
  var got = ptrKnown(ip, ts);
  if (!node || !got) return;
  /* Asked, and there is no name. Said out loud rather than left blank: an
     address with nothing under it looked exactly like an address nobody had
     got round to asking about, and on a page of foreign scanners - which
     mostly have no reverse record at all - that reads as the whole feature
     being broken. "Nothing in the zone" is an answer and is worth showing.
     An address nobody has asked about yet is not in the answer at all and
     still says nothing, because there is nothing yet to say. */
  if (!got.name) {
    if (!got.known || node.dataset.ptrnone) return;
    node.dataset.ptrnone = '1';
    var none = 'The reverse zone has no name for this address. It was asked for and the '
      + 'name servers under Settings, Names of addresses, answered that there is none '
      + '— which is the ordinary answer for an address outside this site.';
    if (node._explained && node._explainHtml) {
      node._explainHtml = node._explainHtml
        + '<div class="k"><span class="more">' + richText(none) + '</span></div>';
    } else {
      explain(node, none);
      node._explainHtml = '<div>' + richText(none) + '</div>';
    }
    return;
  }
  if (node.dataset.ptr === got.name) return;
  node.dataset.ptr = got.name;
  node.classList.add('named');
  ptrInline(node, got.name);
  var when = got.then === false
    ? '\n\nThe nearest name known for it, rather than the one it had at that moment \u2014 '
      + 'nobody had asked about this address yet when this happened.'
    : '';
  var head = '<div class="host">' + richText(got.name) + '</div>';
  var said = 'What the reverse zone calls this address'
    + (ts ? ', as at the time of this record' : '') + '.' + when
    + '\n\nA lease moves, so this is what it was called then and not necessarily what it '
    + 'is called now. Open the address for every name it has had.';
  /* Something that already had words of its own keeps them and gets the
     name underneath. Replacing them would mean the name arriving a second
     later took away whatever that cell was there to explain. */
  if (node._explained && node._explainHtml) {
    node._explainHtml = node._explainHtml
      + '<div class="k">' + head + '<span class="more">' + richText(said) + '</span></div>';
    return;
  }
  explain(node, said);
  node._explainHtml = head + '<div>' + richText(said) + '</div>';
}

/* On the Traffic page's rows the name is written out above the address,
   where a FortiGate's own host name goes, not only in the popup. FortiGate
   writes the name that was asked for into most of its lines; FTD writes
   none, so its rows were bare addresses where the same session through a
   FortiGate had a name. Where the firewall named the host itself, that is
   what stays: it is what was asked for, and the reverse zone's name is in
   the popup as everywhere else. */
function ptrInline(node, name) {
  if (!node || !node.dataset || !node.dataset.ptrinline || !name) return;
  var box = node.closest ? node.closest('.t-addr') : null;
  var cell = box && box.parentNode;
  if (!cell || !cell.insertBefore) return;
  var had = cell.querySelector('.t-host');
  if (had && !had.classList.contains('t-ptr')) return;
  if (had) {
    had.textContent = name;
    return;
  }
  var line = el('div', 'mono t-host t-ptr', name);
  explain(line, 'What the reverse zone calls this address (a PTR record, asked of the name '
    + 'servers under Settings, Names of addresses) — the firewall itself wrote no name '
    + 'for it.');
  /* Above the address, smaller and quieter than it: the address stays the
     line that is read, with where it is and which way it came under it as
     before - the name is an addition, not a replacement. */
  cell.insertBefore(line, box);
}

/* This bit of page would like the name of this address. */
function wantsName(node, ip, ts) {
  if (!ip || PTR_ON === false) return;
  ptrSay(node, ip, ts);
  PTR_WANT.push({node: node, ip: ip, ts: ts || 0});
  if (PTR_SOON) return;
  /* Gathered for a moment first: a table of two hundred rows is one
     question rather than two hundred. */
  PTR_SOON = setTimeout(askNames, 120);
}

function askNames() {
  PTR_SOON = null;
  var want = PTR_WANT;
  PTR_WANT = [];
  if (!want.length) return;
  var seen = {}, list = [], later = [];
  want.forEach(function (one) {
    var key = one.ts ? one.ip + '@' + Math.round(one.ts) : one.ip;
    if (seen[key]) {
      if (seen[key] === 2) later.push(one);
      return;
    }
    if (list.length < 400) {
      seen[key] = 1;
      list.push(key);
    } else {
      /* Past four hundred, asked in the next question rather than never
         (1.10.187): a page of firewall lines is two addresses a row, and
         the last rows of it never had names. */
      seen[key] = 2;
      later.push(one);
    }
  });
  want = want.filter(function (one) {
    var key = one.ts ? one.ip + '@' + Math.round(one.ts) : one.ip;
    return seen[key] === 1;
  });
  if (later.length) {
    PTR_WANT = PTR_WANT.concat(later);
    if (!PTR_SOON) PTR_SOON = setTimeout(askNames, 300);
  }
  api('ptr', {ips: list}).then(function (d) {
    PTR_ON = !!d.on;
    /* Started afresh past twenty thousand (1.10.175): a list refreshing all
       day in a tab left open added a key for every address and second it
       ever drew, and none ever went. What is on the page is asked again. */
    PTR_ADDS += Object.keys(d.names || {}).length + Object.keys(d.then || {}).length;
    if (PTR_ADDS > 20000) { PTR = {}; PTR_THEN = {}; PTR_ADDS = 0; }
    Object.keys(d.names || {}).forEach(function (ip) { PTR[ip] = d.names[ip]; });
    Object.keys(d.then || {}).forEach(function (key) { PTR_THEN[key] = d.then[key]; });
    want.forEach(function (one) { ptrSay(one.node, one.ip, one.ts); });
    /* Whatever the daemon had to go and ask about is asked for again in a
       moment, once rather than in a loop: the answers land in the table
       without anybody pressing anything, and if they are still not there
       the next draw picks them up. */
    if (d.asking && !PTR_AGAIN) {
      PTR_AGAIN = setTimeout(function () {
        PTR_AGAIN = null;
        want.forEach(function (one) { wantsName(one.node, one.ip, one.ts); });
      }, 4000);
    }
  }).catch(function () { /* a name is never worth an error on the page */ });
}

/* Is this text, on its own, an address? Strict on purpose: a VLAN, a MAC, a
   version number and a port are all digits and dots and colons too, and a
   name popped up over one of those is a popup about nothing. A range - an
   address with a prefix on it - is left alone as well: a reverse zone has
   nothing to say about a whole street. */
var IS_V4 = /^(25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)(\.(25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)){3}$/;
function textIsAddress(said) {
  var text = String(said || '').trim();
  if (!text || text.indexOf('/') >= 0) return '';
  if (IS_V4.test(text)) return text;
  /* IPv6, by its shape: eight groups of up to four hex digits, or fewer
     with one `::` standing for the rest. "Two colons and hex" was also every
     clock on the page - 09:29:58 - and every MAC written with colons, and
     each of them was sent off to be asked its name, every five seconds. */
  if (!/^[0-9a-f:]+$/i.test(text) || text.indexOf(':') < 0) return '';
  var halves = text.split('::');
  if (halves.length > 2) return '';
  var groups = function (part) { return part ? part.split(':') : []; };
  var all = groups(halves[0]).concat(halves.length === 2 ? groups(halves[1]) : []);
  if (!all.every(function (g) { return /^[0-9a-f]{1,4}$/i.test(g); })) return '';
  if (halves.length === 2 ? all.length > 7 : all.length !== 8) return '';
  return text.toLowerCase();
}

/* ---- who made the machine behind a MAC ----------------------------------
   The same idea as the names over addresses and the same rules: asked for
   after something has been drawn, held once it is known, and never anything
   a page waits on. This one does not even leave the machine - the registers
   are fetched with the country database and answered out of the table. */
var MACS = {};          /* bare hex -> who made it */
var MACS_ADDS = 0;
var MAC_WANT = [];
var MAC_SOON = null;
var MAC_ON = null;

function macKey(said) {
  var bare = String(said || '').replace(/[-:.\s]/g, '').toUpperCase();
  return (bare.length === 12 && /^[0-9A-F]+$/.test(bare)) ? bare : '';
}

/** The panel this bit of text is already inside, if it is inside one.

    A row that says everything about itself on hover - the door cards, the
    domain's own rows - is one panel, and a hardware address sitting in it is
    not a reason to open a second one on top of the first. What somebody sees
    when both are there is two boxes fighting over the same corner of the
    screen, which is what this is here to stop. */
function nearestPanel(node) {
  /* Near, and not merely above: a cell, a row, a line. A panel four steps
     up the page is a card or a whole tab, and the maker of one machine does
     not belong in what a card says about itself. */
  var up = node && node.parentNode;
  for (var deep = 0; up && up.nodeType === 1 && deep < 4; deep += 1) {
    if (up === document.body) return null;
    if (up._explained) return up;
    up = up.parentNode;
  }
  return null;
}

function macSay(node, key) {
  var vendor = MACS[key];
  if (!node || !vendor) return;
  if (node.dataset.mac === vendor) return;
  node.dataset.mac = vendor;
  node.classList.add('named');
  /* `explain` below knows what to do when this is already inside a panel:
     the maker becomes a line of THAT panel rather than a second one on top
     of it. It is the same rule for everything on this page. */
  /* The maker is the answer, so it is the first thing in the panel and on a
     line of its own - not a name buried in the middle of a sentence and
     broken across two lines by a rule meant for session ids. */
  var head = '<div class="maker">' + richText(vendor) + '</div>';
  var said = 'The first half of this address is an assignment out of the IEEE\u2019s own '
    + 'registers. It says who made the machine \u2014 or who made the card in it \u2014 '
    + 'and nothing else. Nothing here is ever judged by it.';
  if (node._explained && node._explainHtml) {
    node._explainHtml = node._explainHtml
      + '<div class="k">' + head + '<span class="more">' + richText(said) + '</span></div>';
    return;
  }
  /* The maker's NAME goes with the sentence rather than after it, so that
     wherever this ends up - a panel of its own, or a line joined onto the
     panel of the row it is inside - the answer is in it. Written the other
     way round the name was put on afterwards and only ever reached a panel
     of its own. */
  explain(node, 'Made by ' + vendor, '<div class="k">' + richText(said) + '</div>');
  if (node._explained) {
    node._explainHtml = head + '<div>' + richText(said) + '</div>';
  }
}

function wantsVendor(node, key) {
  if (!key || MAC_ON === false) return;
  macSay(node, key);
  MAC_WANT.push({node: node, key: key});
  if (MAC_SOON) return;
  MAC_SOON = setTimeout(askVendors, 120);
}

function askVendors() {
  MAC_SOON = null;
  var want = MAC_WANT;
  MAC_WANT = [];
  if (!want.length) return;
  var seen = {}, list = [];
  want.forEach(function (one) {
    if (seen[one.key] || MACS[one.key] !== undefined) return;
    seen[one.key] = 1;
    if (list.length < 400) list.push(one.key);
  });
  if (!list.length) {
    want.forEach(function (one) { macSay(one.node, one.key); });
    return;
  }
  api('macs', {macs: list}).then(function (d) {
    MAC_ON = !!d.on;
    MACS_ADDS += list.length;
    if (MACS_ADDS > 20000) { MACS = {}; MACS_ADDS = 0; }
    list.forEach(function (key) { MACS[key] = (d.vendors || {})[key] || ''; });
    want.forEach(function (one) { macSay(one.node, one.key); });
  }).catch(function () { /* a maker's name is never worth an error on the page */ });
}

/** Every MAC on a bit of page that has just been drawn, given its maker.

    The MAC columns, the endpoint popups, the eduroam rows, the find box -
    all of them, by looking rather than by every one of them remembering to
    ask. */
function nameTheMakers(where) {
  var host = where || document;
  var all = host.querySelectorAll('td, span, b, a, code, div.v, li');
  Array.prototype.forEach.call(all, function (node) {
    if (node.dataset.macwatch) return;
    if (node.children.length) return;
    var key = macKey(node.textContent);
    if (!key) return;
    node.dataset.macwatch = '1';
    wantsVendor(node, key);
  });
}

/** Every address on a bit of page that has just been drawn, given its name.

    `addrLine` covers the ones this page draws as addresses on purpose - the
    column in the two big lists, the cards, the popups. It does not cover
    the ones that are just text in a cell: where the packet came from, the
    box that asked the token server, the address a machine was given, the
    node that answered. Those are addresses to whoever is reading them and
    there was no reason for them to be the one kind without a name.

    So after anything is drawn, whatever is an address in it is found by
    looking, and asked about as at the moment of the row it is sitting in.
    Done once per element: the mark on it says so. */
function nameTheAddresses(where) {
  var host = where || document;
  var all = host.querySelectorAll('td, span, b, a, code, div.v, li');
  Array.prototype.forEach.call(all, function (node) {
    if (node.dataset.ptrwatch) return;
    if (node.children.length) return;              // it holds other things, not text
    var ip = textIsAddress(node.textContent);
    if (!ip) return;
    node.dataset.ptrwatch = '1';
    var row = node.closest ? node.closest('tr, .findcard, .kv, .card') : null;
    var when = row && row.querySelector ? row.querySelector('[data-ts]') : null;
    wantsName(node, ip, when ? Number(when.dataset.ts) : 0);
  });
}

/* An address, written so it can be clicked to ask about it. */
function addrLine(ip, kind, ts) {
  var a = el('span', 'addr mono', ip);
  a.style.cursor = 'pointer';
  a.title = 'Everything known about ' + ip;
  a.onclick = function (e) { e.stopPropagation(); lookUp(ip); };
  /* Asked about here, with the moment of the row it belongs to - so the
     sweep over everything else that looks like an address leaves it alone
     rather than asking a second time with no moment at all. */
  a.dataset.ptrwatch = '1';
  wantsName(a, ip, ts);
  return a;
}

/** The cell that says what this address IS to us: the name somebody gave it
    in Settings, or that a sign-in came from somewhere else entirely. It is a
    cell rather than something tacked on to the address, so that a column of
    them lines up down the page instead of following the end of an address
    that is a different length on every row. */
function placeCell(ip, tacacs) {
  var td = el('td', 'placecell');
  /* Both of the things this cell can say come from one setting - <i>Where
     TACACS sign-ins come from</i> - and that setting is about signing in to
     a switch and about nothing else. A name out of it beside a VPN login is
     a name for somebody's jump box put on a stranger's address, and
     "elsewhere" beside one is an alarm about a rule that was never meant to
     apply: everybody on the VPN comes from elsewhere. So off a TACACS row
     this cell says nothing at all, and keeps its column for the rows where
     it does. */
  if (!ip || !tacacs) return td;
  var name = aliasFor(ip);
  if (name) {
    var tag = el('span', 'alias', name);
    explain(tag, 'This address has a name in Settings: <b>' + name + '</b>.');
    td.appendChild(tag);
    return td;
  }
  if (tacacs && placeIsUsual(ip) === false) {
    var odd = el('span', 'tag warn oddmark');
    odd.innerHTML = iconMarkup('pin', 13) + '<span>elsewhere</span>';
    explain(odd, 'This sign-in did not come from one of the addresses under <b>Where TACACS '
      + 'sign-ins come from</b> in Settings. That is not wrong and nothing has been blocked — '
      + 'somebody working from another machine looks exactly like this — but it is the row to '
      + 'read first.');
    td.appendChild(odd);
  }
  return td;
}

/** The address, the name of the place it is, and its country - three cells
    so that each stays in its own column down the list, but tight against one
    another so they read as one thing.

    They belong to the address and were sitting a third of the table away from
    it: the address column stretched to fill whatever the table had spare, and
    the tag and the flag were pushed off to the right where they looked like
    they belonged to the next column along. All three hug their contents now,
    and the slack goes to a column that has words in it. */
function addrPlaceCountry(tr, ip, country, tacacs, ts) {
  var a = el('td', 'addrcell');
  if (ip) a.appendChild(addrLine(ip, '', ts)); else a.textContent = '\u2013';
  tr.appendChild(a);
  tr.appendChild(placeCell(ip, tacacs));
  var cc = el('td', 'cccell');
  cc.appendChild(countryBadge(country));
  tr.appendChild(cc);
  return tr;
}

/** What the machine calls itself, as one tight cell.

    AnyConnect's own word for the machine, passed on by the head end and
    written down by ISE. Nothing checks it and nothing here judges it: two
    machines may call themselves the same thing and a machine may call
    itself anything at all. It is here because it is the only thing in a
    VPN record that says WHICH machine - everything else is an address, and
    an address is wherever somebody happens to be sitting. */
function machineCell(said) {
  var td = el('td', 'placecell');
  if (said) {
    /* Plain words, not a mark. A mark is for something worth the eye going
       to it first - a name somebody gave an address, a session that was
       refused - and a machine's own name is neither: it is one more fact
       about the row, read when the row is read. */
    var mark = el('span', '', said);
    explain(mark, 'What the machine called itself when it dialled in \u2014 AnyConnect tells '
      + 'the head end and ISE writes it down. It is the machine\u2019s own word for itself: '
      + 'nothing checks it, nothing is judged on it, and two machines may well say the same.');
    td.appendChild(mark);
  } else {
    td.appendChild(el('span', 'muted', '\u2013'));
  }
  return td;
}

/** The three headers those three cells sit under. */
function addrHeads(words) {
  return [{words: words || 'Address', cls: 'addrcell'},
          {words: '', cls: 'placecell'},
          {words: '', cls: 'cccell'}];
}

/* What the daemon worked out about the addresses on the page being drawn:
   which named place each one is in, and whether it is one at all. A place
   may be a whole range - 172.22.22.0/24=VLAN500 - and whether an address is
   inside one is a question with an answer the page cannot work out for
   itself, so it is asked for with the rows. */
var PLACES_NOW = {};
function notePlaces(d) {
  PLACES_NOW = (d && d.places) || {};
}

/** The name somebody gave this address in Settings, if it has one. */
function aliasFor(ip) {
  if (!ip) return '';
  var said = PLACES_NOW[ip];
  if (said) return said.name || '';
  var places = (STATUS && STATUS.places) || {};
  return places[ip] ? places[ip] : '';
}

/** Whether a sign-in from here came from one of the usual places.
    Null when nobody has said what the usual places are. */
function placeIsUsual(ip) {
  if (!STATUS || !STATUS.places_mark) return null;
  var said = PLACES_NOW[ip];
  if (said && said.usual !== undefined && said.usual !== null) return said.usual;
  return Object.prototype.hasOwnProperty.call(STATUS.places || {}, ip);
}

/* ==========================================================================
   Which addresses are being kept out, said in every list that shows one
   --------------------------------------------------------------------------
   A Ban button beside an address that is already banned is a wrong offer and
   a missing answer at the same time. Every list that draws an address asks
   here instead: it says whether the address is out, whether for good or on a
   clock, how much of the clock is left - ticking, because a countdown that
   does not move is a number nobody trusts - and which buttons make sense.

   The daemon answers with the state of exactly the addresses on the page, so
   this is what those answers are kept in.
   ========================================================================== */
var BANNED = {};
/* The user names that never existed, as Settings names them. Kept for the
   whole page: every list marks them and they change only when somebody edits
   that setting. */
var BOGUS = [];
var BAN_SKEW = 0;               /* the daemon's clock, less this browser's */
var TICKING = [];

/** Take in the ban states that came with a list, and forget the ones the
    same answer says are no longer banned. */
function noteBanned(d) {
  if (!d) return d;
  if (typeof d.now === 'number') BAN_SKEW = d.now * 1000 - Date.now();
  /* ...and which of the addresses in this answer are one of the places
     TACACS sign-ins normally come from. Every list that draws an address
     already passes its answer through here. */
  if (d.places) notePlaces(d);
  /* The names that never existed, kept for the whole page: every list marks
     them, and they change only when somebody edits a setting. */
  if (d.bogus_names) BOGUS = d.bogus_names;
  var got = d.banned;
  if (!got) return d;
  /* Only the addresses whose state moved are drawn again (1.10.176): every
     poll rebuilt every ban cell of every list on the page, the hidden ones
     too, to draw the same thing. */
  var moved = {};
  (d.rows || d.attackers || []).forEach(function (r) {
    var ip = r && r.ip;
    if (ip && !got[ip] && BANNED[ip]) { delete BANNED[ip]; moved[ip] = true; }
  });
  Object.keys(got).forEach(function (k) {
    if (JSON.stringify(BANNED[k]) !== JSON.stringify(got[k])) moved[k] = true;
    BANNED[k] = got[k];
  });
  /* Cells drawn by an earlier answer are told about this one, so a ban made
     somewhere else - by the counting, or by somebody at another desk -
     appears on a list that is already open rather than at its next redraw. */
  if (Object.keys(moved).length) repaintBans(moved);
  return d;
}

/** The one sentence that answers "what is that red bar?", said wherever a
    ban mark is explained so nobody has to go looking for it. */
var STRIPE_SAYS = 'The red bar down the left of a row means the same thing: '
  + 'that address is being kept out at this moment. A row with no bar is not '
  + 'banned.';

function banStateOf(ip) { return ip ? BANNED[ip] : null; }
function banNow_() { return Date.now() + BAN_SKEW; }

/** How much of a temporary ban is left, as words. */
function leftWords(until) {
  var s = Math.max(0, Math.round((until * 1000 - banNow_()) / 1000));
  var h = Math.floor(s / 3600), m = Math.floor((s % 3600) / 60), x = s % 60;
  return (h ? h + ':' + pad2(m) + ':' + pad2(x) : m + ':' + pad2(x));
}

/** The mark for one address: nothing at all when it is not banned, a red
    "for good", or a clock counting down. */
function banMark(ip, compact) {
  var state = banStateOf(ip);
  if (!state) return null;
  if (state.carried === false) {
    /* A ban no firewall carries (1.10.197): its source only watched, or
       switched off. It is there, and it keeps nobody out - drawn as one
       that did, it said the address could not reach the VPN when it can. */
    var idle = el('span', 'tag ' + (state.watched ? 'warn' : 'dim') + ' banmark');
    idle.innerHTML = iconMarkup('eye', 13)
      + (compact ? '<span></span>' : '<span>' + (state.watched ? 'only watched' : 'not carried')
         + '</span>');
    explain(idle, 'This address has a ban, but <b>no firewall carries it</b>: '
      + (state.watched ? 'its source is only watched' : 'its every source is switched off')
      + ' under Settings \u2192 Banning \u2192 Where the bans come from. It can still reach '
      + 'the VPN.\n' + (state.why || ''));
    return idle;
  }
  if (state.forever) {
    var perma = el('span', 'tag crit banmark');
    perma.innerHTML = iconMarkup('ban', 13)
      + (compact ? '<span></span>' : '<span>for good</span>');
    explain(perma, 'This address is kept out <b>for good</b>' + throughWords(state)
      + '. It stays out until somebody takes it off.\n' + (state.why || '')
      + '\n' + STRIPE_SAYS);
    return perma;
  }
  var clock = el('span', 'tag warn banmark');
  clock.innerHTML = iconMarkup('clock', 13) + '<span>' + leftWords(state.until) + '</span>';
  clock.dataset.until = state.until;
  explain(clock, 'This address is kept out until <b>' + stamp(state.until) + '</b>'
    + throughWords(state) + ', and comes back by itself then.\n' + (state.why || '')
    + '\n' + STRIPE_SAYS);
  TICKING.push(clock);
  return clock;
}

function throughWords(state) {
  return state && state.through ? ', through the subnet ' + state.through : '';
}

/* One timer for every countdown on the page, and nodes that have been drawn
   over are dropped rather than ticked for ever. */
setInterval(function () {
  if (!TICKING.length) return;
  TICKING = TICKING.filter(function (node) {
    if (!node.isConnected) return false;
    var until = Number(node.dataset.until || 0);
    var inner = node.querySelector('span');
    if (inner) inner.textContent = leftWords(until);
    return true;
  });
}, 1000);

/** The buttons that make sense for this address, in a row of a list.

    `compact` draws them as icons alone, for a card too narrow to carry the
    words. The words are then in the tooltip, which is where they were going
    to be read anyway. */
function banButtons(ip, why, after, compact) {
  var out = [];
  if (!CAN_BAN || !ip) return out;
  var state = banStateOf(ip);
  var done = function () {
    if (after) after();
    tick();
  };
  var make = function (words, icon, cls) {
    var b = compact ? iconButton(icon, words) : cmdButton(words, icon, 'small ' + cls);
    if (compact && cls) b.classList.add(cls);
    b.dataset.does = words;
    return b;
  };
  if (!state) {
    var ban = make('Ban', 'ban', 'danger');
    explain(ban, 'Keep ' + ip + ' out <b>for good</b>, now, without waiting for it to reach '
      + 'the bar. The router is told at once.');
    ban.onclick = function (e) { e.stopPropagation(); banNow(ip, 0, why, done); };
    out.push(ban);
    return out;
  }
  if (!state.forever) {
    var forgood = make('For good', 'ban', 'danger');
    explain(forgood, ip + ' is on a clock. This takes the clock off and keeps it out until '
      + 'somebody says otherwise.');
    forgood.onclick = function (e) { e.stopPropagation(); banNow(ip, 0, why, done); };
    out.push(forgood);
  }
  if (state.through) {
    /* Kept out by a range, not by a ban of its own (1.10.175): "Let in" sent
       the address, the daemon found no ban of it, and the page said so in
       red while the address stayed out. What lets it in is the range. */
    var range = make('Let the range in', 'undo', '');
    explain(range, ip + ' is kept out because the range ' + htmlText(state.through)
      + ' is banned. Letting it go lets in every address of it with no ban of its own; the ones it was folded from, if any, stay banned as themselves.');
    range.onclick = function (e) {
      e.stopPropagation();
      confirmThen('Let the range in', htmlText(ip) + ' has no ban of its own: it is kept out '
        + 'because <b>' + htmlText(state.through) + '</b> is. Letting it go lets in every address of it with no ban of its own; the ones it was folded from, if any, stay banned as themselves.', 'Let ' + state.through + ' in', function () {
          api('blocked', {remove: state.through}).then(function (d) {
            if (d && d.ok === false) { oops(new Error(d.error || 'not let in')); return; }
            toast(state.through + ' may come back', 'good');
            done();
          }).catch(oops);
        }, false);
    };
    out.push(range);
    return out;
  }
  var free = make('Let in', 'undo', '');
  explain(free, 'Let ' + ip + ' back in now. It comes off the router at once; the ban stays in '
    + 'the history, and the ladder still counts it if it comes back.');
  free.onclick = function (e) {
    e.stopPropagation();
    api('blocked', {remove: ip}).then(function () {
      delete BANNED[ip];
      repaintBans(ip);
      toast(ip + ' may come back', 'good');
      done();
    }).catch(oops);
  };
  out.push(free);
  return out;
}

/** Three cells rather than one, because a mark and two buttons crammed into
    a single cell sit in a different place on every row - the address above is
    short here and long there - and a column of marks that is not a column
    cannot be read down. So: what it is, what makes it harder, what lets it
    back in. Each always in the same place, empty when there is nothing to
    put there.

