  /* NPS's four: each only where NPS has answered something through that
     door, the same rule its buttons follow. */
  var npsHas = function (kinds) {
    return !!s.nps_on && (s.nps_doors || []).some(function (k) {
      return kinds.indexOf(k) >= 0;
    });
  };
  ['leg-nps-vpn-bad', 'leg-nps-vpn-good'].forEach(function (id) {
    var node = $(id);
    if (node) node.hidden = !npsHas(['nps-vpn']);
  });
  ['leg-nps-net-bad', 'leg-nps-net-good'].forEach(function (id) {
    var node = $(id);
    if (node) node.hidden = !npsHas(['nps-dot1x-lan', 'nps-dot1x-wifi', 'nps-mab-lan',
                                     'nps-mab-wifi', 'nps-other']);
  });
  /* ...and a FreeRADIUS of the site's own, the same way (1.10.203). */
  var radHas = function (kinds) {
    return !!s.radius_on && (s.radius_doors || []).some(function (k) {
      return kinds.indexOf(k) >= 0;
    });
  };
  ['leg-rad-vpn-bad', 'leg-rad-vpn-good'].forEach(function (id) {
    var node = $(id);
    if (node) node.hidden = !radHas(['radius-vpn']);
  });
  ['leg-rad-net-bad', 'leg-rad-net-good'].forEach(function (id) {
    var node = $(id);
    if (node) node.hidden = !radHas(['radius-dot1x-lan', 'radius-dot1x-wifi', 'radius-mab-lan',
                                     'radius-mab-wifi', 'radius-other']);
  });
  ['leg-edu-bad', 'leg-edu-good'].forEach(function (id) {
    var node = $(id);
    if (node) node.hidden = !s.eduroam_on;
  });
  /* ...and the domain's two, which only exist where a controller is writing
     its log here. */
  ['leg-dom-bad', 'leg-dom-good'].forEach(function (id) {
    var node = $(id);
    if (node) node.hidden = !s.winsec_on;
  });
  /* ...and the whole Domain page, which is about a system this installation
     may have nothing to do with. A tab standing for a log nobody reads is a
     tab that answers nothing. */
  var domainTab = document.querySelector('.tabs button[data-tab="windows"]');
  if (domainTab) {
    domainTab.hidden = !s.winsec_on;
    if (!s.winsec_on && TAB === 'windows') showTab('overview');
  }
  /* ...and the firewall's traffic, there only while its log is read. */
  var trafficTab = document.querySelector('.tabs button[data-tab="traffic"]');
  if (trafficTab) {
    trafficTab.hidden = !s.fwlog_on;
    if (!s.fwlog_on && TAB === 'traffic') showTab('overview');
  }
  /* Which modules are on decides which doors the two lists offer. The first
     answer usually arrives after a list has already been drawn from what
     the page assumed, and a module switched in Settings changes it later:
     either way, the list somebody is looking at is drawn again, once, with
     the doors it really has. */
  var doorsNow = [s.ise_on, s.tacplus_on, s.winsec_on, s.otp_on, s.eduroam_on,
                  s.nps_on, s.radius_on].join('|');
  if (doorsNow !== DOORS_SEEN) {
    var first = DOORS_SEEN === null;
    DOORS_SEEN = doorsNow;
    if (TAB === 'failed' && (!first || doorToShow(FKIND) !== FKIND)) showFailedKind(FKIND);
    if (TAB === 'logins' && (!first || doorToShow(PKIND) !== PKIND)) passedTab(PKIND);
  }
  var logs = $('ov-logs').querySelector('tbody');
  /* Out of sight and no different: left as it is. Drawn again on every
     poll, a hundred rows were made and thrown away every five seconds on
     a page nobody was looking at. In sight it is drawn every time, for the
     "seconds ago" in it. */
  var logsSaid = JSON.stringify(s.logs || []) + '|' + Object.keys(LOGS_OPEN).join(',');
  var redrawLogs = logs._said !== logsSaid || !!$('ov-logs').getClientRects().length;
  logs._said = logsSaid;
  if (redrawLogs) clear(logs);
  /* A firewall filed a file per kind of message is one row per folder, its
     files added up; pressing it shows them. A file with trouble keeps a row
     of its own. The same folding as `isemon --status` (1.10.161). */
  (redrawLogs ? logRowsGrouped(s.logs || [], s.now || Date.now() / 1000,
                               86400 * (s.fw_keep_days || 14)) : []).forEach(function (l) {
    if (l.files) {
      logs.appendChild(logFolderRow(l));
      if (LOGS_OPEN[l.folder]) l.members.forEach(function (m) { logs.appendChild(logRow(m, true)); });
      return;
    }
    logs.appendChild(logRow(l, false));
