  /* Which machine has been doing the work. On a pair one node is quiet at
     any moment and which one changes without warning; the quiet one looks
     exactly like a node that has stopped sending, and the thing that tells
     them apart is whether the other one picked the work up. */
  var busy = {}, tables = (s.nodes || {}), spelt = {};
  /* The folder a file lives in is how the syslog server names the machine;
     the record carries the name the machine gives itself, and NPS writes
     `DC03` where the folder is `dc03`. One machine, so folded into one - it
     read "DC03 613 · dc03 0" - and shown the way the folder spells it. */
  (s.logs || []).forEach(function (l) {
    var folder = String(l.path || '').split('/').slice(-2)[0];
    if (folder) spelt[folder.toLowerCase()] = folder;
  });
  ['failed', 'passed'].forEach(function (t) {
    Object.keys(tables[t] || {}).forEach(function (name) {
      var key = String(name).toLowerCase();
      busy[key] = (busy[key] || 0) + Number(tables[t][name] || 0);
    });
  });
  Object.keys(busy).forEach(function (n) { if (!busy[n]) delete busy[n]; });
  (s.logs || []).forEach(function (l) {
    /* Only a folder whose file is really there. One that is configured and
       has never appeared is not a machine standing by. */
    var folder = String(l.path || '').split('/').slice(-2)[0].toLowerCase();
    /* ...and not a domain controller's. What it writes is never a sign-in
       in these two tables; its own day is in the column beside its file. */
    if (l.source === 'winsec' || l.source === 'fwlog') return;
    if (l.there && folder && busy[folder] === undefined) busy[folder] = 0;
  });
  var who = $('ov-busy');
  if (who) {
    var names = Object.keys(busy).sort();
    clear(who);
    if (names.length > 1) {
      var total = names.reduce(function (a, n) { return a + busy[n]; }, 0);
      var every = names.map(function (n) { return (spelt[n] || n) + ' ' + num(busy[n]); });
      /* A handful fits along the heading. Past that it is one line of totals
         and the whole list behind it, rather than a heading longer than the
         card is wide - the column beside each file has every number anyway. */
      if (names.length <= 6) {
        names.forEach(function (name, i) {
          if (i) who.appendChild(el('span', 'dim', ' · '));
          var one = el('span', busy[name] ? '' : 'muted', (spelt[name] || name) + ' ');
          one.appendChild(el('b', busy[name] ? '' : 'muted', num(busy[name])));
          who.appendChild(one);
        });
      } else {
        var quiet = names.filter(function (n) { return !busy[n]; }).length;
        who.appendChild(el('span', '', names.length + ' machines · '));
        who.appendChild(el('b', '', num(total)));
        who.appendChild(el('span', '', ' in 24 h'));
        if (quiet) who.appendChild(el('span', 'muted', ' · ' + quiet + ' quiet'));
      }
      explain(who, 'How much each machine that writes one of these logs has written in the '
        + 'last 24 hours. On a pair of ISE nodes one of them is doing the authenticating at '
        + 'any moment and which one changes without warning — so a node at nought beside one '
        + 'carrying its usual total is a failover, which is ordinary. What is not ordinary is '
        + 'every node at nought, or the total falling when one of them goes quiet: that is a '
        + 'node that has stopped sending to this machine.'
        + (names.length > 6 ? '\n' + every.join(' · ') : '')
        + (total ? '' : ' Nothing at all has arrived in the last day.'));
    }
  }

  document.title = (s.blocked.now ? '(' + s.blocked.now + ') ' : '')
    + (s.site || 'isemon') + ' — ' + s.host;

  /* The header and everything under it is redrawn here rather than by any of
     the functions that sweep what they have just drawn, so the sweep is asked
     for from here - and at the END of it, once the log rows above actually
     exist. Two things it puts right: a browser tooltip put back on the health
     pill and on the clock every five seconds, which then sat under our own
     panel saying the same thing in a different place; and anything explained
     BEFORE it was put on the page, which neither direction of the folding can
     see at the time. Over the whole page when something moved; over the
     header alone on a poll that brought nothing new - the whole page was
     four walks of every cell every five seconds for a page that had not
     changed. */
  explainWhatWasDrawn(quiet ? (document.querySelector('header') || document) : document);
}

/* ---- what a readonly account may not touch --------------------------------
   Belt and braces. The daemon refuses every one of these anyway - it is the
   only thing that decides - but a button that looks pressable and then says
   "no" is a worse way to be told. */
if (!ADMIN) {
  Array.prototype.forEach.call(document.querySelectorAll('.admin-only'), function (node) {
    node.hidden = true;
  });
}
if (!CAN_BAN) {
  Array.prototype.forEach.call(document.querySelectorAll('.ban-only'), function (node) {
    node.hidden = true;
  });
}

$('signout').onclick = function () {
  api('logout', {}).then(function () { location.reload(); }).catch(function () {
    location.reload();
  });
};
</script>
<script nonce="<?= h($nonce) ?>">
'use strict';
/* ==========================================================================
   Overview
   ========================================================================== */
var SERIES_FROM = 0;
var DASH_ASKED = 0;
var DASH_FLYING = 0;
function loadDashboard() {
  var hours = Number($('ov-hours').value || 24);
  /* The page's own refresh does not ask again while the last one is still
     out (1.10.184): a month or a year can take longer than the five seconds
     between ticks, and each tick added one more of the same question. */
  if (QUIET_TICK && DASH_FLYING && Date.now() - DASH_FLYING < 60000) return;
  DASH_FLYING = Date.now();
  /* Only the newest question's answer is drawn: a week asked for and then a
     day, the week's slower answer arrived second and drew a week under a
     selector that said a day. */
  var mine = ++DASH_ASKED;
  /* Somebody choosing another window stops the one asked before, on the
     daemon too (1.10.187): a year asked for and then a day kept the
     daemon counting the year for nobody. The page's own refresh is left
     out of it, so it goes on refreshing as it always has. */
  api('dashboard&hours=' + hours, undefined,
      QUIET_TICK ? undefined : {lane: 'ov-dashboard'}).then(function (d) {
    if (mine === DASH_ASKED) DASH_FLYING = 0;
    if (mine !== DASH_ASKED) return;
    noteBanned(d);
    /* Where the chart's window really starts: the first bar is only the part
       of its hour that is inside the window, and pressing it has to open
       that part and not the whole hour. */
    SERIES_FROM = d.now ? Math.floor(Number(d.now) - hours * 3600) : 0;
    drawSeries(d.series, hours);
    drawAttackers(d.attackers);
    drawFailingNames(d.users_failed);
    drawCountries(d.countries);
    ovDoorTabs(d.series);
    /* ...and the door that is open, kept live like everything else on this
       page - without the "counting" line, which on a poll is a flash of
       nothing every few seconds. */
    ovLoadDoor(false);
    explainWhatWasDrawn($('tab-overview'));
  }).catch(function (e) { if (mine === DASH_ASKED) DASH_FLYING = 0; oops(e); });
}
$('ov-hours').onchange = function () { loadDashboard(); ovLoadDoor(true); };

/* ==========================================================================
   The doors under the chart
   --------------------------------------------------------------------------
   This page has always been about the VPN, because the VPN is the only thing
   that is ever banned. But a site with a token server and a visitors' network
   has two more whole systems in here, and all anybody could see of them was
   two colours in one chart. Same rows, same window, different question: which
   institutions are arriving, which access points, what the token server keeps
   saying no to, which switch has been refusing machines all morning.

   The VPN keeps the four cards it has always had and stays the door this page
   opens on. The others are built from what the daemon counts behind them, so
   a door that fills a column somewhere this one does not needs no new card
   here - see `DOOR_FACETS` and `FACET_WORDS` there.
   ========================================================================== */
var OV_DOOR = 'vpn';
var OV_DOOR_ASKED = 0;

/* Which doors are worth a tab: the VPN always, a module that is switched on
   whether or not anything came through it yet, and anything else that has
   something behind it in this window. A tab standing for nothing is a tab in
   the way; a module switched on with a quiet night behind it is not nothing,
   because its emptiness is the answer. */
function ovDoorsWorth(series) {
  var sums = {};
  (series || []).forEach(function (b) {
    ['tacacs', 'tacplus', 'network', 'otp', 'eduroam', 'npsvpn', 'npsnet', 'radvpn', 'radnet']
      .forEach(function (k) {
      sums[k] = (sums[k] || 0) + (b['failed_' + k] || 0) + (b['passed_' + k] || 0);
    });
  });
  var on = STATUS || {};
  /* A door is offered when its module is switched on, whether or not anything
     came through it in this window: a quiet night at a door is an answer, and
     a tab that comes and goes with the hours is a tab nobody can rely on.
