  }
  /* The door being looked at is not offered any more - a module switched
     off, or the page opening on the VPN at a site that reads no ISE: it
     moves to the first one that is, cards and all. */
  if (!want.some(function (one) { return one.door === OV_DOOR; })) {
    ovShowDoor(want[0].door);
