      b.appendChild(ic);
    }
    b.appendChild(el('span', '', one.words));
    if (one.n) b.appendChild(el('span', 'n', num(one.n)));
    b.dataset.door = one.door;
    explain(b, OV_DOOR_SAYS[one.door] || '');
    b.onclick = function () { ovShowDoor(one.door); };
