     has a summary of its own here, counts and all, put there by the card
     underneath; the words alone would take it away. */
  if (OV_DOOR === 'vpn' || !$('ov-doorsays').firstChild) {
    $('ov-doorsays').textContent = OV_DOOR_SAYS[OV_DOOR] || '';
  }
}

function ovShowDoor(door) {
  OV_DOOR = door;
  $('ov-door-vpn').hidden = door !== 'vpn';
  $('ov-door-other').hidden = door === 'vpn';
