      if (mine !== OV_DOOR_ASKED) return;
      clear(host);
      host.appendChild(el('p', 'center bad', String((e && e.message) || e)));
    });
    return;
  }
  api('door&door=' + encodeURIComponent(OV_DOOR) + '&hours=' + overHours())
    .then(function (d) {
      if (mine !== OV_DOOR_ASKED || OV_DOOR === 'vpn') return;   /* they moved on */
      ovDrawDoor(d);
    }).catch(function (e) {
      if (mine !== OV_DOOR_ASKED) return;
      clear(host);
      host.appendChild(el('p', 'center bad', String((e && e.message) || e)));
    });
}

/** The domain's own card on the front page.

    Three things, in the order somebody asks them: what is worth looking at,
    who has been locked out and from where, and who the domain has been
    turning away. Everything else about it is a tab of its own, and the last
    line says so. All of it is drawn by the Domain page's own functions, so
    there is one card of each kind on this installation rather than two that
    slowly stop agreeing. */
function ovDrawDomain(d) {
  var host = $('ov-door-other');
  if (sameAsDrawn(host, d) && host.firstChild) return;
  steady(host);
  clear(host);
  var line = el('div', 'doorsettled');
  var size = (d.counts || {});
  var many = Object.keys(size).reduce(function (n, k) { return n + (size[k] || 0); }, 0);
  line.textContent = many
    ? (num(many) + ' event(s) from the controllers in this window. None of it is judged '
       + 'and none of it can earn anybody a ban.')
    : 'Nothing has arrived from the controllers in this window.';
  host.appendChild(line);

  var worth = (d.incidents || []);
  if (worth.length) {
    var card = el('div', 'card full');
    card.style.marginTop = '14px';
    card.appendChild(el('h2', '', 'Worth looking at'));
    var box = el('div');
    worth.slice(0, 6).forEach(function (one) { box.appendChild(winIncidentLine(one)); });
    card.appendChild(box);
    host.appendChild(card);
  }

  var locks = (d.lockouts || []);
  if (locks.length) {
    var lc = el('div', 'card full');
    lc.style.marginTop = '14px';
    lc.appendChild(el('h2', '', 'Accounts the domain locked'));
    lc.appendChild(el('p', 'note', 'Which machine, which program, and how many refusals '
      + 'came before it. Press one for the whole story.'));
    var wrap = el('div', 'scroll');
    var table = el('table', 'rows');
    var head = el('thead');
    var hr = el('tr');
    [['When', ''], ['Account', ''], ['From', ''], ['Through', 'throughcell'],
     ['Refusals before it', 'num'], ['How it ended', ''], ['Controller', '']]
      .forEach(function (one) { hr.appendChild(el('th', one[1], one[0])); });
    head.appendChild(hr);
    table.appendChild(head);
    var body = el('tbody');
    var few = locks.slice(0, 10);
    few.forEach(function (r) { body.appendChild(winLockRow(r)); });
    winLockThrough(table, few);
    table.appendChild(body);
    wrap.appendChild(table);
    lc.appendChild(wrap);
    host.appendChild(lc);
  }

  var views = (d.views || []).filter(function (v) {
    return v.key === 'people' || v.key === 'machines';
  });
  if (views.length) {
    var grid = el('div', 'grid halves');
    grid.style.marginTop = '14px';
    views.forEach(function (v) { grid.appendChild(winViewCard(v)); });
    host.appendChild(grid);
  }
  if (!worth.length && !locks.length && !views.length) {
    var none = el('div', 'card full');
    none.style.marginTop = '14px';
    none.appendChild(el('p', 'center muted',
      'Nothing from the domain controllers in the window above.'));
    host.appendChild(none);
  }
  var on = el('p', 'center');
  on.style.marginTop = '12px';
  var go = el('button', 'btn small');
  go.textContent = 'Everything the domain saw';
  go.onclick = function () { showTab('windows'); };
  on.appendChild(go);
  host.appendChild(on);
  explainWhatWasDrawn(host);
  settle(host);
}

function ovDrawDoor(d) {
  var host = $('ov-door-other');
  /* The line under the strip first and always: it lives outside this card,
     so "nothing has changed here" is no reason to leave it as somebody else
     left it. */
  ovDoorSummary(d);
  if (sameAsDrawn(host, d) && host.firstChild) return;
  steady(host);
  clear(host);
  /* No row of tiles here. The four along the top of the page are about the
     whole installation; four more saying the same four things about one door
     is a second row of big numbers pushing the cards that actually answer
     something below the fold. What is worth keeping out of them - how many,
     both ways, and when the last one was - goes on the one line under the
     door strip, where it is read in passing rather than stared at. */
  if (!(d.views || []).length) {
    var none = el('div', 'card full');
    none.style.marginTop = '14px';
    none.appendChild(el('p', 'center muted',
      'Nothing has come through this door in the window above.'));
    host.appendChild(none);
    return;
  }
  var grid = null;
  (d.views || []).forEach(function (view, n) {
    if (n % 2 === 0) {
      grid = el('div', 'grid halves');
      grid.style.marginTop = '14px';
      host.appendChild(grid);
    }
    grid.appendChild(ovViewCard(d, view));
  });
  explainWhatWasDrawn(host);
  settle(host);
}

/* ==========================================================================
   One card of a door
   --------------------------------------------------------------------------
   A row is one SUBJECT - a machine, a person, a switch, an answer - and
   everything about it that a person would otherwise have to go and look up is
   on the row: where it was, why it was refused, how often, when. The first
   shape of this was four lists of disconnected columns, and a list of sockets
   saying "GigabitEthernet1/0/41 - 1,152" answers nothing at all: it does not
   say which machine, or what it wanted, or why it did not get it, and every
   one of those is on the same row in the database.

   Three ways in, on every row: the row says it, the hover says all of it, and
   pressing it opens the records themselves.
   ========================================================================== */

/** What one row of each shape of card is called, and what is drawn beside it. */
function ovRowParts(view, row) {
  var got = row.newest || {};
  var out = {name: String(row.said), mono: true, mac: '', where: '', why: '', who: ''};
  if (view.key === 'machines') {
    /* A machine is a hardware address, or the name a supplicant gave. Both
       are the machine; which one is there depends on how it asked. */
    out.mac = macKey(row.said);
    out.name = out.mac ? said2mac(row.said) : String(row.said);
    out.where = [deviceWords(got.device, got.nad),
                 got.port || got.ssid].filter(Boolean).join(' · ');
    out.why = got.reason || '';
    out.who = got.machine || shortName(got.username === row.said ? '' : got.username);
  } else if (view.key === 'places') {
    /* How many different machines it is refusing is the number that says
       whether it is one machine on one socket or the whole cupboard. The
       name of the last one is on the hover; here it would only push the
       reason off the row. */
    /* The subject IS the device here, so its own address belongs on the
       row rather than three clicks inside it. */
    out.where = [got.nad || '',
                 row.names ? (num(row.names) + ' machine(s)') : ''
                ].filter(Boolean).join(' \u00b7 ');
    out.why = got.reason || '';
    out.who = '';
  } else if (view.key === 'people') {
    out.where = [deviceWords(got.device, got.nad),
                 got.port || got.ssid || got.realm].filter(Boolean).join(' · ');
    if (!out.where && got.server) out.where = got.server;
    out.why = got.reason || '';
    out.mac = macKey(got.mac || '');
  } else if (view.key === 'realms') {
    out.where = row.names ? (num(row.names) + ' account(s)') : '';
    out.why = got.reason || '';
    out.who = got.username || '';
  } else if (view.key === 'reasons') {
    out.mono = false;
    out.who = got.username || '';
    out.where = [deviceWords(got.device, got.nad), got.server].filter(Boolean).join(' · ');
  }
  return out;
}

/** Everything known about one row, for the hover. */
function ovRowSays(d, view, row) {
  var got = row.newest || {};
  var said = [];
  said.push('<div class="maker">' + richText(String(row.said)) + '</div>');
  var pairs = [
    ['Refused', row.failed ? num(row.failed) + ' time(s)' : 'never'],
    ['Let through', row.passed ? num(row.passed) + ' time(s)' : 'never'],
    ['Last one', row.last ? shortStamp(row.last) : ''],
    ['Different machines', view.key === 'places' && row.names ? num(row.names) : ''],
    ['Different addresses', row.places > 1 ? num(row.places) : ''],
    ['Different devices', view.key !== 'places' && row.devices > 1 ? num(row.devices) : '']
  ];
  /* ...and what the newest attempt actually was. This is the half that was
     missing: the person, the machine, the socket, the radio, the switch and
     the words the server answered with. */
  [['Account', got.username], ['Machine', got.machine], ['Hardware address', got.mac],
   ['Institution', got.realm], ['Device', deviceWords(got.device, got.nad)],
   ['Where on it', portWords(got.port, got.device, got.nad)],
   ['Network', got.ssid], ['Address', got.ip], ['Answered by', got.server],
   ['How it asked', got.kind ? (doorWords(got.kind)) : ''],
   ['Why', got.reason]].forEach(function (one) { pairs.push(one); });
  pairs.forEach(function (one) {
    if (!one[1]) return;
    said.push('<div class="k"><b>' + richText(one[0]) + ':</b> '
              + richText(String(one[1])) + '</div>');
  });
  return said.join('');
}

function ovViewCard(d, view) {
  var card = el('div', 'card facet');
  card.appendChild(el('h2', '', view.name));
  if (view.says) card.appendChild(el('p', 'note', view.says));
  var rows = view.rows || [];
  var top = rows.reduce(function (m, r) {
    return Math.max(m, (r.failed || 0) + (r.passed || 0));
  }, 1);
  var table = el('table');
  var body = el('tbody');
  rows.forEach(function (r) {
    var parts = ovRowParts(view, r);
    var tr = el('tr');

    var first = el('td', 'said');
    var name = el('span', parts.mono ? 'mono' : '');
    name.textContent = parts.name;
    first.appendChild(name);
    /* The second line is what the row is actually about: where it was and
       why. Under the name rather than beside it, because a switch name and a
       socket and a reason side by side is a row nobody can read. */
    /* ...and where the row covers more than one of something, how many, with
       what follows marked as the newest rather than as the whole. The count
       at the end of the row belongs to the row; a single name under it is
       otherwise read as the name that count belongs to. Said the same way
       here as on the Domain page, because it is the same mistake. */
    var wide = [];
    /* ...except where the card already says it in its own words: a card of
       switches says how many machines each is refusing, and saying it twice
       is worse than not saying it at all. */
    var counted = (view.key === 'places' || view.key === 'realms');
    if (view.key !== 'people' && !counted && r.names > 1) {
      wide.push(num(r.names) + ' accounts');
    }
    if (!counted && r.devices > 1) wide.push(num(r.devices) + ' devices');
    if (r.places > 1) wide.push(num(r.places) + ' addresses');
    var said = [parts.who, parts.where, parts.why].filter(Boolean);
    if (wide.length && said.length) said = wide.concat(['newest: ' + said.join(' · ')]);
    else if (wide.length) said = wide;
    var under = said.join(' · ');
    if (under) {
      var sub = el('div', 'sub');
      sub.textContent = under;
      first.appendChild(sub);
    }
    tr.appendChild(first);

    var mid = el('td', 'barcell');
    var bar = el('div', 'bar' + (r.failed ? '' : ' good'));
    var fill = el('span');
    fill.style.width = Math.round(100 * ((r.failed || 0) + (r.passed || 0)) / top) + '%';
    bar.appendChild(fill);
    mid.appendChild(bar);
    tr.appendChild(mid);

    /* Both sides, side by side: "refused 1,152, got in twice" is a different
       machine from "refused 1,152, never got in". */
    var counts = el('td', 'n');
    if (r.failed) {
      var bad = el('span', 'bad');
      bad.textContent = num(r.failed);
      counts.appendChild(bad);
    }
    if (r.failed && r.passed) counts.appendChild(el('span', 'muted', ' / '));
    if (r.passed) {
      var good = el('span', 'good');
      good.textContent = num(r.passed);
      counts.appendChild(good);
    }
    tr.appendChild(counts);
    tr.appendChild(el('td', 'n when muted', r.last ? shortStamp(r.last) : ''));

    /* The words are put on afterwards rather than by `opensWith`, because
       what this row has to say is a panel of facts and not one sentence. */
    opensWith(tr, '', function () { ovPeekRow(d, view, r); });
    explain(tr, 'Press it for the records themselves.', ovRowSays(d, view, r));
    /* After the row's own panel and not before it: the maker is a line of
       that panel, and a line cannot be added to a panel that is not there
       yet. Asked the other way round it opened a second panel of its own. */
    if (parts.mac) wantsVendor(name, parts.mac);
    body.appendChild(tr);
  });
  table.appendChild(body);
  card.appendChild(table);
  return card;
}

/** A machine account written short. ISE writes a machine's own name as a
    Kerberos principal - `host/NB-EXAMPLE-4.example.int` - and on a row
    beside a switch and a socket there is no room for the domain twice. */
function shortName(said) {
  var name = String(said || '');
  if (name.slice(0, 5).toLowerCase() === 'host/') name = name.slice(5);
  var dot = name.indexOf('.');
  if (dot > 0 && !/@/.test(name)) name = name.slice(0, dot);
  return name;
}

/** A hardware address as this page writes them. */
function said2mac(said) {
  var bare = macKey(said);
  if (!bare) return String(said);
  return bare.match(/../g).join('-');
}

/* Which column of a record each shape of row is a value of, so that pressing
   one asks for exactly the records it was drawn from. A column with a filter
   of its own uses it; the rest go through the same search box the page's own
   search does, which on each door already looks in that door's own columns. */
/* Which column each card is grouped by, and the name to ask for it by.

   `username` asks exactly rather than through the search box's LIKE: a card
   counted the rows where the name IS that name, and pressing it has to open
   those and no others. The three that were missing - a hardware address, an
   institution, an answer - fell through to a free-text search over five
   columns, which opened a list that was not the one the row had counted and
   put a different number at the top of it. */
var OV_ROW_FILTER = {'username': 'username', 'ip': 'ip', 'device': 'device',
                     'server': 'server', 'country': 'country', 'mac': 'mac',
                     'realm': 'realm', 'reason': 'reason'};

function ovPeekRow(d, view, row) {
  var h = overHours();
  var said = String(row.said);
  var filter = OV_ROW_FILTER[view.by];
  /* A machine is a hardware address OR the name a supplicant gave - the
     daemon groups those two into one column, so which one this row is
     decides which of them to ask for. */
  if (view.by === 'mac' && !macKey(said)) filter = 'username';
  var where = filter ? ('&' + filter + '=' + encodeURIComponent(said))
                     : ('&q=' + encodeURIComponent(said));
  /* The side with something on it. A row that was only ever refused opens the
     refusals; one that only ever got in opens the sign-ins. */
  var side = row.failed ? 'failed' : 'passed';
  var got = row.newest || {};
  /* A card of what never got on counted only those refusals, so only those
     are opened: pressing a switch on it listed every MAB half of every PC
     that joined through it a second later as well. */
  if (view.settled && side === 'failed') where += '&settled=' + encodeURIComponent(view.settled);
  peek(ovRowTitle(view) + ' \u201c' + said + '\u201d',
    function () {
      return api(side + '&hours=' + h + '&limit=250&kind=' + encodeURIComponent(d.door)
                 + where).then(noteBanned);
    },
    function (body, answer) {
      body.appendChild(peekFacts([
        [ovRowTitle(view), said],
        ['Refused', row.failed ? num(row.failed) : 'never'],
        ['Let through', row.passed ? num(row.passed) : 'never'],
        ['Last one', row.last ? shortStamp(row.last) : '–']
      ]));
      /* ...and the newest attempt written out, so the popup opens with the
         answer rather than with a table to read. */
      var more = [['Account', got.username], ['Machine', got.machine],
                  ['Hardware address', got.mac ? said2mac(got.mac) : ''],
                  ['Institution', got.realm],
                  ['Device', deviceWords(got.device, got.nad)],
                  ['Where on it', portWords(got.port, got.device, got.nad)],
                  ['Network', got.ssid],
                  ['Address', got.ip], ['Answered by', got.server],
                  ['How it asked', got.kind ? (doorWords(got.kind)) : ''],
                  ['Why', got.reason]].filter(function (one) { return one[1]; });
      if (more.length) {
        body.appendChild(el('p', 'note', 'The newest of them:'));
        body.appendChild(peekFacts(more));
      }
      if (view.says) body.appendChild(el('p', 'note', view.says));
      body.appendChild(side === 'passed'
        ? peekPassedRows(answer.rows, 'peek-door')
        : peekFailedRows(answer.rows, 'peek-door'));
    },
    {tab: side === 'passed' ? 'logins' : 'failed',
     words: side === 'passed' ? 'Open the logins' : 'Open the failed attempts',
     icon: side === 'passed' ? 'person' : 'cancel'});
}

function ovRowTitle(view) {
  return {'machines': 'Machine', 'places': 'Device', 'people': 'Account',
          'realms': 'Institution', 'reasons': 'Answer'}[view.key] || 'Row';
}

/** The one line under the door strip: what that door is, and how much of it
    there is. Pressing either count opens the records it stands for. */
function ovDoorSummary(d) {
  var host = $('ov-doorsays');
  clear(host);
  host.appendChild(document.createTextNode(OV_DOOR_SAYS[d.door] || ''));
  var t = d.totals || {};
  var bad = (t.failed || {}).n || 0;
  var good = (t.passed || {}).n || 0;
  var last = (t.failed || {}).last || (t.passed || {}).last || 0;
  if (!bad && !good) return;
  host.appendChild(document.createTextNode(' \u00b7 '));
  function count(n, words, side, cls) {
    var one = el('b', cls);
    one.textContent = num(n) + ' ' + words;
    opensWith(one, 'Every record this counts, newest first.', function () {
      ovPeekDoor(d, side);
    });
    host.appendChild(one);
  }
  if (bad) count(bad, 'refused', 'failed', 'bad');
  if (bad && good) host.appendChild(document.createTextNode(', '));
  if (good) count(good, 'let through', 'passed', 'good');
  if (last) host.appendChild(document.createTextNode(', newest ' + ago(last)));
  /* ...and how much of that is the ordinary way a PC joins rather than
     anything wrong. Every PC offers its hardware address first, is refused
     because that address is in no list, and authenticates with its
     certificate a second later: on a site of two thousand desks that is two
     thousand refusals a morning and not one of them is a fault. */
  var settled = d.settled;
  if (settled && settled.settled) {
    var line = el('div', 'doorsettled');
    line.textContent = num(settled.settled) + ' of the ' + num(settled.machines)
      + ' machines refused here got on to the network anyway \u2014 a PC is refused by '
      + 'MAB and then authenticates with its certificate, which is the ordinary way one '
      + 'joins. The card below leaves those out.';
    host.appendChild(line);
  }
}

/** Everything at one door, from the line under the door strip. */
function ovPeekDoor(d, side) {
  var h = overHours();
  peek(d.name + ' \u2014 ' + (side === 'passed' ? 'let through' : 'refused'),
    function () {
      return api(side + '&hours=' + h + '&limit=250&kind=' + encodeURIComponent(d.door))
        .then(noteBanned);
    },
    function (body, answer) {
      body.appendChild(peekFacts([
        ['Door', d.name],
        [side === 'passed' ? 'Let through' : 'Refused', num(answer.total)],
        ['Window', overWindowWords()]
      ]));
      body.appendChild(side === 'passed'
        ? peekPassedRows(answer.rows, 'peek-door-all')
        : peekFailedRows(answer.rows, 'peek-door-all'));
    },
    {tab: side === 'passed' ? 'logins' : 'failed',
     words: side === 'passed' ? 'Open the logins' : 'Open the failed attempts',
     icon: side === 'passed' ? 'person' : 'cancel'});
}

/* One chart, drawn as SVG by hand. Two series of counts over time, which is
   the whole of what this page needs - a charting library would be two hundred
   kilobytes to draw eleven lines, and this page loads nothing from anywhere. */
function drawSeries(series, hours) {
  var host = $('ov-chart');
  var tip = host.querySelector('.tip');
  clear(host);
  host.appendChild(tip);
  if (!series || !series.length) {
    host.appendChild(el('div', 'empty', 'Nothing has been read yet'));
    return;
  }
  /* How wide one bar is in seconds, taken from the series itself rather than
     worked out again from the hours: it is the daemon that decides, and one
     bar standing for a different span than the popup asks for would list the
     wrong records. */
  var bucket = series.length > 1 ? Math.max(60, Math.round(series[1].ts - series[0].ts))
                                 : (hours > 6 ? 3600 : 300);
  var W = host.clientWidth || 700, H = host.clientHeight || 230;
  /* Where the domain is being read there is a second scale on the right, and
     its numbers need room to be written in. */
  var domainOn = !!(STATUS && STATUS.winsec_on) || series.some(function (p) {
    return (p.failed_domain || 0) || (p.passed_domain || 0);
  });
  var padL = 44, padR = domainOn ? 46 : 12, padT = 12, padB = 26;
  var w = Math.max(10, W - padL - padR), h = Math.max(10, H - padT - padB);
  /* The scale on the left is this site's own doors and nothing else. */
  var top = Math.max(1, series.reduce(function (m, p) {
    return Math.max(m, p.failed, p.passed);
  }, 0));
  /* A refusal is a refusal whoever wrote it down, and the two are the same
     order of size - a few dozen an hour on a controller against a few
     hundred at the doors - so what the domain turned away is drawn against
     that same scale, where it can be read against them.

     What the domain LET THROUGH is not: one person signing in once writes a
     Kerberos ticket, an NTLM validation and a logon on a controller, and
     every service they open writes another. On one real site that is thirty
     thousand an hour against nine hundred refusals at the doors. Drawn on
     one scale the doors would be an inch of red at the bottom of a wall of
     blue and the chart this page exists for would be unreadable, so it has
     a scale of its own on the right and the legend says so. */
  var topDom = Math.max(1, series.reduce(function (m, p) {
    return Math.max(m, p.passed_domain || 0);
  }, 0));
  /* Each bar is drawn in parts, VPN underneath and TACACS on top of it.
     Stacked rather than side by side: the height of a bar goes on meaning
     what it meant - everything refused in this hour - and the split is read
     off the colours inside it. */
  var PARTS = [
    ['failed', -1, [['vpn', '#f85149'], ['tacacs', '#ffa657'], ['tacplus', '#bf8700'],
                    ['network', '#d2a8ff'], ['otp', '#f778ba'], ['eduroam', '#ff9f68'],
                    ['npsvpn', '#a40e26'], ['npsnet', '#6e40c9'],
                    ['radvpn', '#ff7b72'], ['radnet', '#bc8cff']]],
    ['passed', 1, [['vpn', '#3fb950'], ['tacacs', '#58d3f7'], ['tacplus', '#1f6feb'],
                   ['network', '#a371f7'], ['otp', '#e3b341'], ['eduroam', '#2dd4bf'],
                   ['npsvpn', '#196c2e'], ['npsnet', '#7ee787'],
                   ['radvpn', '#aff5b4'], ['radnet', '#0e8a8a']]]
  ];
  /* The bar is everything that was somebody knocking; the named bands are
     cut out of it and what is left over is the VPN. Cut rather than added up
     so that the height goes on meaning the whole hour even if a door nobody
     has thought of yet turns up in the data. */
  function halves(p, which) {
    var all = Math.max(0, Number(p[which]) || 0);
    var got = {};
    var left = all;
    /* Every band but the VPN is a number of its own, taken out of the bar in
       turn; the VPN is what is left. A door missing from this list would be
       drawn as the VPN - which is the one door the banning weighs, and the
       last place anything belongs by accident. */
    /* tac_plus is one of them. Left off this list it was drawn as the VPN -
       every sitting on a switch through a site's own daemon in green, as
       somebody getting on to the VPN, which is the last place anything
       belongs by accident. */
    /* ...and so are NPS's two, for the same reason, and FreeRADIUS's. */
    ['tacacs', 'tacplus', 'network', 'otp', 'eduroam', 'npsvpn', 'npsnet', 'radvpn', 'radnet']
      .forEach(function (band) {
      var n = Math.max(0, Math.min(left, Number(p[which + '_' + band]) || 0));
      got[band] = n;
      left -= n;
    });
    got.vpn = Math.max(0, left);
    /* The domain is not one of the bands and is not cut out of the bar,
       because it was never in it: a refusal on a controller is not a RADIUS
       attempt and is counted where it happened. It is a bar of its own, on
       the scale on the right. */
    got.domain = Math.max(0, Number(p[which + '_domain']) || 0);
    got.all = all;
    return got;
  }
  /* A round ceiling rather than the exact maximum: gridlines at 0, 25, 50
     read; gridlines at 0, 23, 46 do not. */
  function ceilingOf(n) {
    var mag = Math.pow(10, Math.floor(Math.log(n) / Math.LN10));
    var out = Math.ceil(n / (mag / 2)) * (mag / 2);
    return (!isFinite(out) || out <= 0) ? 1 : out;
  }
  var ceil = ceilingOf(top);
  var ceilDom = ceilingOf(topDom);

  var svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  svg.setAttribute('viewBox', '0 0 ' + W + ' ' + H);
  svg.setAttribute('preserveAspectRatio', 'none');
  function make(kind, attrs) {
    var n = document.createElementNS('http://www.w3.org/2000/svg', kind);
    for (var k in attrs) if (attrs.hasOwnProperty(k)) n.setAttribute(k, attrs[k]);
    return n;
  }
  /* The two scales share the gridlines, so one set of rules is read twice:
     this site's doors on the left, the controllers on the right, each in the
     colour of the bars it belongs to. */
  var DOM_AXIS = '#79c0ff';
  for (var g = 0; g <= 4; g++) {
    var y = padT + h - (h * g / 4);
    svg.appendChild(make('line', {x1: padL, x2: W - padR, y1: y, y2: y,
                                  stroke: '#262c37', 'stroke-width': 1}));
    var label = make('text', {x: padL - 8, y: y + 4, fill: '#5b6472', 'font-size': 11,
                              'text-anchor': 'end'});
    label.textContent = Math.round(ceil * g / 4);
    svg.appendChild(label);
    if (domainOn) {
      var right = make('text', {x: W - padR + 8, y: y + 4, fill: DOM_AXIS,
                                'font-size': 11, 'text-anchor': 'start',
                                opacity: 0.75});
      right.textContent = Math.round(ceilDom * g / 4);
      svg.appendChild(right);
    }
  }
  /* Four bars to a bucket where the domain is being read, two where it is
     not: refused and let in at this site's doors, and the same two as the
     controllers saw them. Laid out around the middle of the bucket with the
     domain's pair on the inside, so the red and the green stay where they
     have always been and the blue reads as the pair that belongs together. */
  var HOW = domainOn
    ? [['failed', 'doors'], ['failed', 'domain'], ['passed', 'domain'], ['passed', 'doors']]
    : [['failed', 'doors'], ['passed', 'doors']];
  var step = w / Math.max(1, series.length);
  var barW = Math.max(1, Math.min(domainOn ? 11 : 18, step * (domainOn ? 0.2 : 0.38)));
  /* Where each bar sits, in bar widths from the middle. */
  var WHERE = domainOn ? [-2, -1, 0, 1] : [-1, 0];
  var DOM_COLOUR = {failed: '#8b9dff', passed: '#79c0ff'};
  series.forEach(function (p, i) {
    var x = padL + step * i + step / 2;
    HOW.forEach(function (one, at) {
      var split = halves(p, one[0]);
      var left = x + WHERE[at] * (barW + 0.6) + 0.3;
      if (one[1] === 'domain') {
        if (!split.domain) return;
        /* Refusals against the doors' own scale, sign-ins against theirs. */
        var against = one[0] === 'failed' ? ceil : ceilDom;
        /* ...never past the top of the chart (1.10.200): more refusals at
           the domain than at the doors drew a bar many times the plot's
           height over everything above it. */
        var dh = Math.min(h, Math.max(1, h * (split.domain / against)));
        svg.appendChild(make('rect', {
          x: left, y: padT + h - dh, width: barW, height: dh,
          fill: DOM_COLOUR[one[0]], rx: 2, opacity: 0.8}));
        return;
      }
      if (!split.all) return;
      var bottom = padT + h;
      (one[0] === 'failed' ? PARTS[0][2] : PARTS[1][2]).forEach(function (part) {
        var v = split[part[0]];
        if (!v) return;
        var bh = Math.max(1, h * (v / ceil));
        svg.appendChild(make('rect', {
          x: left, y: bottom - bh,
          width: barW, height: bh, fill: part[1], rx: 2, opacity: 0.88}));
        bottom -= bh;
      });
    });
  });
  /* Times along the bottom, thinned so they never run into each other. */
  var every = Math.max(1, Math.ceil(series.length / Math.max(3, Math.floor(w / 72))));
  series.forEach(function (p, i) {
    if (i % every) return;
    var x = padL + step * i + step / 2;
    var d = new Date(p.ts * 1000);
    var t = make('text', {x: x, y: H - 8, fill: '#5b6472', 'font-size': 11,
                          'text-anchor': 'middle'});
    t.textContent = hours > 48 ? pad2(d.getDate()) + '-' + pad2(d.getMonth() + 1)
                                : clockWords(d, false);
    svg.appendChild(t);
  });
  /* One invisible column per bucket, so the pointer finds a bucket rather
     than having to land on a bar that may be one pixel wide. */
  series.forEach(function (p, i) {
    var hit = make('rect', {x: padL + step * i, y: padT, width: step, height: h,
                            fill: 'transparent'});
    /* ...the domain's half included: a bar that is only the domain is a bar
       with something under it all the same. */
    var any = p.failed || p.passed || p.failed_domain || p.passed_domain;
    hit.style.cursor = any ? 'pointer' : 'crosshair';
    if (any) {
      /* The bar is a window on to its own span of time, like every other
         count on this page. */
      hit.addEventListener('click', function () { peekSpan(p, bucket); });
    }
    hit.addEventListener('mousemove', function (e) {
      var box = host.getBoundingClientRect();
      var bad = halves(p, 'failed'), good = halves(p, 'passed');
      var said = function (colour, n, what) {
        return n ? '<span style="color:' + colour + '">' + num(n) + ' ' + what
                   + '</span><br>' : '';
      };
      /* What is not drawn is still said. The bars are attempts; the rest are
         records ISE wrote about its own packet handling, and a line naming
         them is the difference between a number that is missing and a number
         that was never there. */
      var left = (p.failed_other || 0) + (p.passed_other || 0);
      /* Said on every line that belongs to it, because the two numbers above
         and below it are drawn against a different ruler. */
      var DOM_NOTE = ' <span style="opacity:.6">(right-hand scale)</span>';
      tip.innerHTML = '<b>' + shortStamp(p.ts) + '</b><br>'
        + said('#f85149', bad.vpn, 'failed \u00b7 VPN')
        + said('#ffa657', bad.tacacs, 'failed \u00b7 TACACS')
        + said('#bf8700', bad.tacplus, 'failed \u00b7 TAC_Plus')
        + said('#d2a8ff', bad.network, 'failed \u00b7 802.1X / MAB')
        + said('#f778ba', bad.otp, 'failed \u00b7 one-time password')
        + said('#ff9f68', bad.eduroam, 'failed \u00b7 eduroam')
        + said('#a40e26', bad.npsvpn, 'failed \u00b7 NPS VPN')
        + said('#6e40c9', bad.npsnet, 'failed \u00b7 NPS 802.1X / MAB')
        + said('#ff7b72', bad.radvpn, 'failed \u00b7 FreeRADIUS VPN')
        + said('#bc8cff', bad.radnet, 'failed \u00b7 FreeRADIUS 802.1X / MAB')
        + said('#8b9dff', bad.domain, 'refused \u00b7 the domain')
        + said('#3fb950', good.vpn, 'passed \u00b7 VPN')
        + said('#58d3f7', good.tacacs, 'passed \u00b7 TACACS')
        + said('#1f6feb', good.tacplus, 'passed \u00b7 TAC_Plus')
        + said('#a371f7', good.network, 'passed \u00b7 802.1X / MAB')
        + said('#e3b341', good.otp, 'passed \u00b7 one-time password')
        + said('#2dd4bf', good.eduroam, 'passed \u00b7 eduroam')
        + said('#196c2e', good.npsvpn, 'passed \u00b7 NPS VPN')
        + said('#7ee787', good.npsnet, 'passed \u00b7 NPS 802.1X / MAB')
        + said('#aff5b4', good.radvpn, 'passed \u00b7 FreeRADIUS VPN')
        + said('#0e8a8a', good.radnet, 'passed \u00b7 FreeRADIUS 802.1X / MAB')
        + said('#79c0ff', good.domain, 'signed in \u00b7 the domain' + DOM_NOTE)
        + said('#8b949e', left, 'not an attempt')
        + (!bad.all && !good.all && !left
           ? '<span style="color:#8b949e">nothing</span>'
           : '<span style="color:#8b949e">press to open</span>');
      tip.style.display = 'block';
      var left = e.clientX - box.left + 12;
      if (left + tip.offsetWidth > box.width) left = e.clientX - box.left - tip.offsetWidth - 12;
      tip.style.left = Math.max(0, left) + 'px';
      tip.style.top = Math.max(0, e.clientY - box.top - 12) + 'px';
    });
    hit.addEventListener('mouseleave', function () { tip.style.display = 'none'; });
    svg.appendChild(hit);
  });
  host.appendChild(svg);
}

function drawAttackers(rows) {
  var body = $('ov-attackers').querySelector('tbody');
  clear(body);
  $('ov-attackers-empty').hidden = !!(rows && rows.length);
  (rows || []).forEach(function (r) {
    var tr = el('tr');
    opensWith(tr, '', function () { lookUp(r.ip); });
    addrPlaceCountry(tr, r.ip, r.country, false, r.last);
    tr.appendChild(el('td', 'num', num(r.tries)));
    tr.appendChild(el('td', 'num', num(r.users)));
    tr.appendChild(stampCell(r.last));
    markOnto(tr, r.ip);
    body.appendChild(tr);
  });
}

function drawFailingNames(rows) {
  var body = $('ov-users').querySelector('tbody');
  clear(body);
  $('ov-users-empty').hidden = !!(rows && rows.length);
  (rows || []).forEach(function (r) {
    var tr = el('tr');
    /* One name from many addresses is the shape of a password spray, and it
       is worth saying so rather than leaving it to be noticed. It goes in a
       column of its own: beside the name it sat in a different place on
       every row, and a mark that is not in a column cannot be scanned. */
    var mark = el('td', 'past-mark');
    if (r.addresses >= 5) {
      var icon = el('span', 'past-icon on');
      icon.innerHTML = iconMarkup('spray', 15);
      explain(icon, 'A password spray: this one name has been tried from '
        + r.addresses + ' different addresses. Somebody is trying one password against '
        + 'many places rather than many passwords against one.');
      mark.appendChild(icon);
    }
    tr.appendChild(mark);
    var td = el('td');
    td.appendChild(el('span', 'mono', r.username));
    tr.appendChild(td);
    tr.appendChild(el('td', 'num', num(r.tries)));
    tr.appendChild(el('td', 'num', num(r.addresses)));
    tr.appendChild(stampCell(r.last));
    /* The card counts the VPN's refusals of exactly this name, so that is
       what it opens: not every door, and not every name with it inside. */
    opensWith(tr, 'Everything this name has tried, and whether it has ever got in.',
              function () { peekName(Object.assign({kind: 'vpn'}, r)); });
    body.appendChild(tr);
  });
}

function drawCountries(rows) {
  var host = $('ov-countries');
  clear(host);
  $('ov-countries-empty').hidden = !!(rows && rows.length);
  if (!rows || !rows.length) return;
  var top = rows.reduce(function (m, r) { return Math.max(m, r.tries); }, 1);
  rows.forEach(function (r) {
    var line = el('div', 'kv');
    var k = el('span', 'k');
    k.appendChild(countryBadge(r.country));
    line.appendChild(k);
    var mid = el('span', '');
    mid.style.flex = '1';
    mid.style.display = 'flex';
    mid.style.alignItems = 'center';
    mid.style.gap = '10px';
    var bar = el('div', 'bar');
    var fill = el('span');
    fill.style.width = Math.round(100 * r.tries / top) + '%';
    fill.style.background = 'var(--crit)';
    bar.appendChild(fill);
    mid.appendChild(bar);
    line.appendChild(mid);
    var v = el('span', 'v', num(r.tries));
    v.appendChild(el('span', 'd', r.addresses + ' address(es)'));
    line.appendChild(v);
    opensWith(line, 'Everything refused from this country in the window above.',
              function () { peekCountry(r); });
    host.appendChild(line);
  });
}

/* ==========================================================================
   The front page, pressed
   --------------------------------------------------------------------------
   Every card here counts something, and a count nobody can get behind is a
   count somebody has to go and look for somewhere else. So all of them open:
   a card, a row, a country, a bar of the chart. Each opens the same kind of
   popup the address rows have always opened - what it is counting, listed,
   searchable, paged - and each carries a button on to the page that holds
   all of it rather than only the last hundred.
   ========================================================================== */
var PEEK = 0;

/** Make one thing pressable: pointer, highlight, keyboard, tooltip. */
function opensWith(node, words, go) {
  node.classList.add('tappable');
  node.setAttribute('role', 'button');
  node.setAttribute('tabindex', '0');
  if (words) explain(node, words);
  node.onclick = function (e) {
    /* A button drawn inside a pressable row is its own answer. */
    if (e && e.target && e.target.closest && e.target.closest('button,a,select,input')) return;
    go();
  };
  node.onkeydown = function (e) {
    if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); go(); }
  };
  return node;
}

/** The same, for one of the four cards along the top. */
function cardOpens(id, words, go) {
  var card = $(id);
  if (!card) return;
  if (!card.querySelector('.goes')) {
    var arrow = el('span', 'goes');
    arrow.innerHTML = iconMarkup('next', 16);
    card.appendChild(arrow);
  }
  opensWith(card, words, go);
}

/** A popup that asks for something, then draws it. `jump` is the page this
    is a window on to, so nobody is left in a popup at a dead end. */
function peek(title, ask, draw, jump) {
  var mine = ++PEEK;
  var buttons = [{words: 'Close', close: true}];
  /* ...but not when it is the page they are already on. Pressing it there
     closed the popup and did nothing whatever, which reads as a button that
     is broken rather than as one that had nowhere to go. */
  if (jump && jump.tab !== TAB) {
    buttons.unshift({words: jump.words, cls: 'primary', icon: jump.icon, close: true,
                     go: function () { showTab(jump.tab); }});
  }
  modal(title, function (body) {
    body.appendChild(el('p', 'center muted', 'Asking…'));
  }, buttons);
  var ticket = modalTicket();
  Promise.resolve(ask()).then(function (d) {
    if (mine !== PEEK || !modalStill(ticket)) return;  /* they moved on */
    var body = $('modal-body');
    clear(body);
    draw(body, d);
    explainWhatWasDrawn(body);
  }).catch(function (e) {
    if (mine !== PEEK || !modalStill(ticket)) return;
    var body = $('modal-body');
    clear(body);
    body.appendChild(el('p', 'center bad', String((e && e.message) || e)));
  });
}

/** The line of plain facts a popup opens with. */
function peekFacts(pairs) {
  var box = el('div', 'facts');
  pairs.forEach(function (one) {
    if (!one) return;
    var cell = el('div', 'fact');
    cell.appendChild(el('span', 'k', one[0]));
    var v = el('span', 'v');
    if (one[1] && one[1].nodeType) v.appendChild(one[1]); else v.textContent = one[1];
    cell.appendChild(v);
    box.appendChild(cell);
  });
  return box;
}

/** Failed attempts, listed the way the Failed page lists them. */
function peekFailedRows(rows, key) {
  return listView({
    key: key, rows: rows || [], per: 25, barFrom: 6,
    placeholder: 'an address, a name, a reason…',
    empty: 'Nothing was refused in this window',
    hay: function (r) {
      return [r.ip, r.username, r.reason, r.country, r.device, r.tunnel].join(' ');
    },
    countryOf: function (r) { return r.country; },
    draw: function (page, host) {
      host.appendChild(listTable(
        ['When', addrHeads(), 'Name', 'Why'].concat(banHeads()), page,
        function (r) {
          var tr = el('tr');
          tr.appendChild(stampCell(r.ts, 'dim'));
          addrPlaceCountry(tr, r.ip, r.country, false, r.ts);
          tr.appendChild(el('td', '', r.username || '–'));
          tr.appendChild(el('td', 'dim', (r.reason || '').slice(0, 70)));
          banOnto(tr, r.ip, 'banned from the overview');
          opensWith(tr, '', function () { lookUp(r.ip); });
          return tr;
        }, 'plain'));
    }
  });
}

/** Successful logins, the same way. */
function peekPassedRows(rows, key) {
  return listView({
    key: key, rows: rows || [], per: 25, barFrom: 6,
    placeholder: 'a name, an address, a profile…',
    empty: 'Nobody got in during this window',
    hay: function (r) { return [r.username, r.ip, r.profile, r.device, r.tunnel].join(' '); },
    countryOf: function (r) { return r.country; },
    draw: function (page, host) {
      host.appendChild(listTable(
        ['When', 'Name', addrHeads(), 'Profile', 'Device'], page,
        function (r) {
          var tr = el('tr');
          tr.appendChild(stampCell(r.ts, 'dim'));
          tr.appendChild(el('td', '', r.username || '–'));
          /* Only a sign-in to a switch is judged against where TACACS
             sign-ins come from. This list holds both kinds at once, so it
             is asked of each row rather than of the list. */
          addrPlaceCountry(tr, r.ip, r.country, (r.kind || 'vpn') === 'tacacs', r.ts);
          tr.appendChild(el('td', '', r.profile || '–'));
          tr.appendChild(deviceCell(r));
          opensWith(tr, '', function () { lookUp(r.ip); });
          return tr;
        }, 'plain'));
    }
  });
}

function overHours() { return Number($('ov-hours').value || 24); }
/* The window said in the words the select itself uses, so the popup and the
   thing that chose it never disagree. */
function overWindowWords() {
  var sel = $('ov-hours');
  var chosen = sel && sel.options[sel.selectedIndex];
  return chosen ? chosen.textContent.trim() : 'the last 24 hours';
}

/* ---- the four cards along the top --------------------------------------- */
function peekFailedCard() {
  /* The card says "last 24 hours" whatever the chart below it is set to, so
     that is the window it opens - not the chart's. A card reading 6 over a
     popup reading 20,000 was the chart's year answering for the card's day. */
  var h = 24;
  peek('Refused \u2014 the last 24 hours',
    function () { return api('failed&hours=' + h + '&limit=250').then(noteBanned); },
    function (body, d) {
      var s = STATUS || {};
      body.appendChild(peekFacts([
        ['Refused in this window', num(d.total)],
        ['Refused ever', num(((s.totals || {}).failed || {}).rows)],
        ['Addresses ever', num(((s.totals || {}).failed || {}).addresses)],
        ['Kept out now', num((s.blocked || {}).now)]
      ]));
      body.appendChild(el('p', 'note', 'Every authentication refused in the last 24 hours, at '
        + 'every door, newest first. This is what the counting is made of: an address that reaches '
        + 'the bar inside the span in Settings is the one the router is told about. Press a row '
        + 'for everything known about that address.'));
      body.appendChild(peekFailedRows(d.rows, 'peek-failed'));
    },
    {tab: 'failed', words: 'Open the failed attempts', icon: 'cancel'});
}

function peekPassedCard() {
  var h = 24;
  peek('Let through \u2014 the last 24 hours',
    function () { return api('passed&hours=' + h + '&limit=250').then(noteBanned); },
    function (body, d) {
      var c = d.counts || {};
      body.appendChild(peekFacts([
        ['Let through in this window', num(d.total)],
        ['AnyConnect logins ever', num(c.vpn)],
        ['TACACS sign-ins ever', num(c.tacacs)],
        ['Commands ever', num(c['tacacs-cmd'])],
        ['Firewall lists handed down', num(c.dacl)]
      ]));
      body.appendChild(el('p', 'note', 'Everybody who got on in the last 24 hours, at every '
        + 'door. The firewall list handed to a session and the commands run on a switch are not logins, '
        + 'so they are not listed here — they are shown inside the login they belong to, on '
        + 'the Logins page.'));
      body.appendChild(peekPassedRows(d.rows, 'peek-passed'));
    },
    {tab: 'logins', words: 'Open the logins', icon: 'person'});
}

function peekBlockedCard() {
  peek('Kept out now',
    function () { return api('blocked&limit=1&parts=bans'); },
    function (body, d) {
      /* Only what is carried (1.10.198): a ban only watched, or one whose
         every source is off, keeps nobody out and is not what the router is
         told to drop. The Banned page lists them, apart. */
      var rows = (d.blocked || []).filter(function (r) { return !r.src_off; });
      var forever = rows.filter(function (r) { return r.forever; }).length;
      body.appendChild(peekFacts([
        ['On the list', num(rows.length)],
        ['For good', num(forever)],
        ['On a clock', num(rows.length - forever)]
      ]));
      /* The rules are a sentence, not a number, so they read as one rather
         than being squeezed into a box beside three counts. */
      var how = el('p', 'note');
      how.innerHTML = 'What earns a ban: <b>' + richText(d.trigger || '–') + '</b>. How long '
        + 'it lasts: <b>' + richText(d.lengths || '–') + '</b>.';
      body.appendChild(how);
      body.appendChild(el('p', 'note', 'Everything the router is being told to drop. Press one '
        + 'for its whole story: what it tried, which public lists name it, and when it comes '
        + 'back in.'));
      body.appendChild(listView({
        key: 'peek-blocked', rows: rows, per: 25, barFrom: 6,
        placeholder: 'an address, a reason…', empty: 'Nobody is kept out',
        hay: function (r) { return [r.ip, r.why, r.country].join(' '); },
        countryOf: function (r) { return r.country; },
        draw: function (page, host) {
          host.appendChild(listTable(['Address', '', 'Why', 'Since', 'Until'], page,
            function (r) {
              var tr = el('tr');
              var a = el('td');
              a.appendChild(el('span', 'mono', r.ip));
              tr.appendChild(a);
              var cc = el('td');
              cc.appendChild(countryBadge(r.country));
              tr.appendChild(cc);
              tr.appendChild(el('td', 'dim', (r.why || '').slice(0, 80)));
              tr.appendChild(stampCell(r.since, 'dim'));
              var till = el('td');
              if (r.forever) {
                till.appendChild(el('span', 'tag crit', 'for good'));
              } else {
                till.appendChild(el('span', '', span(r.left || 0) + ' left'));
              }
              tr.appendChild(till);
              opensWith(tr, '', function () { lookUp(r.ip); });
              return tr;
            }, 'plain'));
        }
      }));
    },
    {tab: 'bans', words: 'Open the banned', icon: 'ban'});
}

function peekRouterCard() {
  var r = (STATUS && STATUS.mikrotik) || {};
  var g = (STATUS && STATUS.geolist) || {};
  peek('The firewall',
    function () { return Promise.resolve(null); },
    function (body) {
      body.appendChild(peekFacts([
        ['Address', r.host || 'none set'],
        ['The ban list', r.list || '–'],
        ['Written', r.at ? shortStamp(r.at) : 'never'],
        ['Carrying', !r.at ? 'never read' : num(r.on || 0) + ' of ours, when last read'],
        g.on ? ['The country list', g.name || '–'] : null,
        g.on ? ['Countries', (g.countries || []).join(', ') || 'none chosen'] : null
      ]));
      if (!r.ready) {
        body.appendChild(el('p', 'note', 'No router is set up. Give it an address, a user and a '
          + 'list name under Settings, and everything banned here starts being dropped there.'));
      } else if (r.trouble) {
        var bad = el('p', 'note bad');
        bad.textContent = 'Out of step: ' + r.trouble;
        body.appendChild(bad);
        body.appendChild(el('p', 'note', 'The Router page reads the list as it stands and says '
          + 'which addresses are banned here but not being dropped there. “Put the list on it” '
          + 'settles both lists in one press.'));
      } else {
        body.appendChild(el('p', 'note', 'The list on the router says what this says. The Router '
          + 'page reads it as it stands, entry by entry, and carries the buttons that write to '
          + 'it — including “Put the list on it”, which settles the ban list and the country '
          + 'list in one press.'));
      }
    },
    {tab: 'router', words: 'Open the router', icon: 'router'});
}

/* ---- one name, one country, one file, one bar --------------------------- */
function peekName(r) {
  var h = overHours();
  var name = r.username || '';
  peek('The name “' + name + '”',
    function () {
      /* The name exactly - `user` is the search box's "anywhere inside",
         which on `jan` opened jana, jan.novak and bojan as well. */
      return Promise.all([
        api('failed&hours=' + h + '&limit=250&username=' + encodeURIComponent(name)
            + (r.kind ? '&kind=' + encodeURIComponent(r.kind) : ''))
          .then(noteBanned),
        api('passed&limit=25&username=' + encodeURIComponent(name))
      ]);
    },
    function (body, both) {
      var bad = both[0], good = both[1];
      /* Opened from a list, the counts come with the row. Opened from a name
         somewhere else - a record, the directory card - there is no row, so
         they are counted out of what came back rather than shown as nought. */
      var tries = r.tries === undefined ? bad.total : r.tries;
      var places = r.addresses === undefined
        ? Object.keys((bad.rows || []).reduce(function (all, one) {
            if (one.ip) all[one.ip] = 1;
            return all;
          }, {})).length
        : r.addresses;
      var last = r.last === undefined
        ? ((bad.rows || [])[0] || {}).ts || ((good.rows || [])[0] || {}).ts || 0
        : r.last;
      body.appendChild(peekFacts([
        ['Refused in this window', num(tries)],
        ['Different addresses', num(places)],
        ['Last tried', last ? shortStamp(last) : 'not in this window'],
        ['Has ever got in', good.total ? num(good.total) + ' time(s)' : 'never']
      ]));
      r = {username: name, tries: tries, addresses: places, last: last};
      body.appendChild(el('p', 'note', r.addresses >= 5
        ? 'One name tried from ' + r.addresses + ' different addresses is the shape of a '
          + 'password spray: one password against many places rather than many passwords '
          + 'against one. A name that has never got in here may be a name that does not exist.'
        : 'Every attempt this name has made in the window, and whether it has ever got in. '
          + 'Press a row for everything known about the address behind it.'));
      if (good.total) {
        var got = el('h3', 'peek-h', 'It has got in');
        body.appendChild(got);
        body.appendChild(peekPassedRows(good.rows, 'peek-name-in'));
        body.appendChild(el('h3', 'peek-h', 'It has been refused'));
      }
      body.appendChild(peekFailedRows(bad.rows, 'peek-name'));
      /* ...and what the domain itself saw, which is the other half of every
         one of these. A VPN refusal says the password was wrong; the domain
         says whether the account was locked, from which machine the wrong one
         came, and which program had it saved. */
      winBeside(body, name);
    },
    {tab: 'failed', words: 'Open the failed attempts', icon: 'cancel'});
}

/** One name, asked for by name rather than clicked in a list. */
function lookUpUser(name) {
  if (!name) return;
  peekName({username: name});
}

function peekCountry(r) {
  var h = overHours();
  var cc = String(r.country || '').toUpperCase();
  peek('Coming from ' + cc,
    function () {
      return api('failed&hours=' + h + '&limit=250&country=' + encodeURIComponent(cc))
        .then(noteBanned);
    },
    function (body, d) {
      var flag = countryBadge(cc);
      body.appendChild(peekFacts([
        ['Country', flag],
        ['Refused in this window', num(r.tries)],
        ['Different addresses', num(r.addresses)]
      ]));
      body.appendChild(el('p', 'note', 'A country is only ever shown here, never judged: it is '
        + 'not something an address chooses, and a scanner in Rotterdam looks exactly like an '
        + 'employee in Rotterdam. The country list under Settings is the place to act on one, '
        + 'and it drops a whole country before anybody has failed anything.'));
      body.appendChild(peekFailedRows(d.rows, 'peek-country'));
    },
    {tab: 'failed', words: 'Open the failed attempts', icon: 'cancel'});
}

/* What one followed file holds, in one place: the tag on the Overview, the
   words beside it and the line at the top of the row when it is opened. Four
   kinds of file are followed and only two of them are ISE's, so "refusals"
   and "logins" between them do not cover it. */
/* What is in each file, in the words `isemon --status` uses for it. */
var LOG_HOLDS_WORDS = {failed: 'refusals', passed: 'logins',
                       winsec: 'what a domain controller saw',
                       fwlog: 'what crossed the firewall', otp: 'one-time passwords',
                       'otp-detail': 'what the token server was asked',
                       eduroam: 'eduroam sign-ins', 'eduroam-detail': 'eduroam sessions'};

function logHolds(l) {
  var source = l.source || 'ise';
  if (source === 'otp') return {
    words: 'one-time passwords', tone: 'violet',
    whole: 'every one-time password the token server answered, accepted and refused alike',
    says: 'This file is a token server\u2019s, not ISE\u2019s. One line is one attempt and '
      + 'the line says whether it worked, so both halves come out of the one file. None of it '
      + 'is ever judged.'
  };
  if (source === 'otp-detail') return {
    words: 'what the token server was asked', tone: 'violet',
    whole: 'the RADIUS packets that caused those token attempts \u2014 who was asking, from '
      + 'where, on what machine and through which door',
    says: 'This file is the RADIUS server\u2019s beside the token software, and it makes no '
      + 'rows of its own: one VPN sign-in is one token attempt, and counting the packet as '
      + 'well would count it twice. What it holds is shown beside each token attempt \u2014 '
      + 'the person\u2019s own address, which the token log has not. It is shipped by a '
      + 'script once a minute, so it runs a little behind the token log by design.'
  };
  if (source === 'eduroam') return {
    words: 'eduroam sign-ins', tone: 'violet',
    whole: 'every eduroam sign-in and refusal, in FreeRADIUS\u2019s own words',
    says: 'This file is the visitors\u2019 network\u2019s own RADIUS server, not ISE. One '
      + 'line is one attempt and the line says whether it worked. The only address on such a '
      + 'line is the wireless controller the request came through, so none of it is ever '
      + 'judged.'
  };
  if (source === 'eduroam-nps') return {
    words: 'eduroam, through NPS', tone: 'violet',
    whole: 'every eduroam sign-in and refusal a Windows NPS answered, and its accounting',
    says: 'This file is a Windows NPS server\u2019s own log, read as eduroam\u2019s: one '
      + 'request and its answer make one sign-in, and the accounting in the same file says '
      + 'where the machine was and what address it was given. None of it is ever judged.'
  };
  if (source === 'eduroam-detail') return {
    words: 'eduroam sessions', tone: 'violet',
    whole: 'the accounting records: where each eduroam session actually was',
    says: 'The accounting file the wireless controller writes, which is where the access '
      + 'point, the network, the VLAN and the address the machine was given actually are. It '
      + 'makes no rows of its own \u2014 it is joined to the sign-ins by the machine\u2019s '
      + 'MAC.'
  };
  if (source === 'fwlog') return {
    words: 'firewall traffic', tone: 'violet',
    whole: 'every session the firewall let through or refused, what its web filter did and '
      + 'what it said about itself',
    says: 'This file is the firewall\u2019s own log as its syslog server writes it. One line '
      + 'is one thing that happened, and what is read is shown on the Traffic tab. None of it '
      + 'is ever judged and none of it can earn anybody a ban.'
  };
  if (source === 'winsec') return {
    words: 'domain events', tone: 'violet',
    whole: 'everything one Windows domain controller wrote into its Security log',
    says: 'This file is a Windows domain controller\u2019s Security log, not ISE\u2019s. '
      + 'It holds sign-ins, refusals, lockouts and every change made to the directory, and '
      + 'NONE of it is ever judged: a sign-in checked against the directory is one attempt '
      + 'and it is already counted at the door it came through. The Domain tab is where it '
      + 'is read.'
  };
  if (l.kind === 'failed') return {
    words: 'refusals', tone: 'info',
    whole: 'the authentications ISE refused',
    says: 'This file holds the authentications ISE refused. It is what the banning is made of.'
  };
  return {
    words: 'logins', tone: 'ok',
    whole: 'the authentications ISE let through',
    says: 'This file holds the authentications ISE let through \u2014 the VPN logins and the '
      + 'TACACS sign-ins to switches.'
  };
}

function peekLog(l) {
  peek(l.path,
    function () { return Promise.resolve(null); },
    function (body) {
      body.appendChild(peekFacts([
        ['Holds', logHolds(l).whole],
        ['Records read', num(l.records)],
        ['Read up to', bytes(l.offset || 0) + ' of ' + bytes(l.size || 0)],
        ['Behind', l.behind ? bytes(l.behind) : 'nothing'],
        ['Last read', l.at ? shortStamp(l.at) : 'not yet'],
        ['There', l.there ? 'yes' : 'no'],
        l.error ? ['Trouble', l.error] : null,
        l.ahead ? ['Dated ahead', span(l.ahead) + ' into the future'] : null
      ]));
      if (l.ahead) body.appendChild(el('p', 'note bad', l.ahead_says || ''));
      body.appendChild(el('p', 'note', !l.there
        ? 'This file does not exist. On a pair where one node has been quiet that is ordinary — '
          + 'ISE writes the log when it has something to write. It only matters when no node '
          + 'has one.'
        : 'Where this file has been read up to is kept in the database, so a restart carries on '
          + 'from here rather than reading the whole file again — and if logrotate moves the '
          + 'file aside while the daemon is stopped, the part that was written before the move '
          + 'is read off the rotated copy. The count survives a restart for the same reason.'));
      body.appendChild(el('p', 'note', 'Nothing read twice is ever stored twice: every record '
        + 'is kept under the session id ISE gave it, so “Go back over every log” can read every '
        + 'file from the beginning and only what was missing is added.'));
    },
    {tab: l.kind === 'failed' ? 'failed' : 'logins',
     words: l.kind === 'failed' ? 'Open the failed attempts' : 'Open the logins',
     icon: l.kind === 'failed' ? 'cancel' : 'person'});
}

function peekSpan(p, step) {
  var from = Math.max(Math.floor(p.ts), SERIES_FROM || 0);
  var to = Math.floor(p.ts) + Math.max(60, step || 3600);
  var clock = function (at) { return clockWords(new Date(at * 1000), false); };
  peek(dayWords(new Date(from * 1000)) + ' ' + clock(from) + ' – ' + clock(to),
    function () {
      return Promise.all([
        /* The doors the bar is drawn from and no others: ISE's own packet
           handling and the commands on a switch are counted beside the
           chart and never drawn in it, so they are not listed under it. */
        api('failed&limit=250&kind=drawn&from=' + from + '&to=' + to).then(noteBanned),
        api('passed&limit=250&kind=drawn&from=' + from + '&to=' + to)
      ]);
    },
    function (body, both) {
      body.appendChild(peekFacts([
        ['Refused', num(p.failed)],
        ['Let through', num(p.passed)],
        (p.failed_domain || p.passed_domain)
          ? ['The domain', num(p.failed_domain || 0) + ' refused \u00b7 '
             + num(p.passed_domain || 0) + ' signed in'] : null,
        /* Moments, so said as moments: "From" is where an address came
           from everywhere else on the page, and is translated as that. */
        ['Since', shortStamp(from)],
        ['Until', shortStamp(to)]
      ]));
      body.appendChild(el('p', 'note', 'Exactly what is under that bar of the chart — not the '
        + 'last hour, but that hour.'));
      if (both[0].total) {
        body.appendChild(el('h3', 'peek-h', 'Refused'));
        body.appendChild(peekFailedRows(both[0].rows, 'peek-span-failed'));
      }
      if (both[1].total) {
        body.appendChild(el('h3', 'peek-h', 'Let through'));
        body.appendChild(peekPassedRows(both[1].rows, 'peek-span-passed'));
      }
      /* ...and the domain's half of the same bar, which is not rows of
         these lists: opened as the Domain page opens it, over exactly this
         span. */
      if (p.failed_domain || p.passed_domain) {
        var row = el('div', 'btnrow');
        var dom = function (n, words, kinds) {
          if (!n) return;
          var b = cmdButton(num(n) + ' ' + words, 'shield', '');
          b.onclick = function () {
            winPeekEvents('The domain \u2014 ' + words, {kind: kinds, from: String(from),
                                                          to: String(to)}, '', '',
                          {hours: 0, words: shortStamp(from) + ' \u2013 ' + shortStamp(to)});
          };
          row.appendChild(b);
        };
        dom(p.failed_domain, 'refused by the domain',
            'logon-failed,kerberos-failed,ntlm-failed,lockout');
        dom(p.passed_domain, 'signed in at the domain', 'logon,kerberos,ntlm,explicit');
        body.appendChild(row);
      }
      if (!both[0].total && !both[1].total && !p.failed_domain && !p.passed_domain) {
        body.appendChild(el('p', 'center muted', 'Nothing was reported in this span'));
      }
    },
    {tab: 'failed', words: 'Open the failed attempts', icon: 'cancel'});
}

/* The four cards are wired once: they are in the page from the start and
   what they open reads STATUS, which is replaced under them every few
   seconds. */
cardOpens('card-failed', 'Everything refused in the last 24 hours, listed.', peekFailedCard);
cardOpens('card-passed', 'Everybody who got in during the last 24 hours, listed.',
          peekPassedCard);
cardOpens('card-blocked', 'Everything the router is being told to drop, listed.', peekBlockedCard);
cardOpens('card-router', 'What the firewall is, and what it is carrying. Where there is a '
  + 'pair, whether the two of them are carrying the same thing.', peekRouterCard);

/* ==========================================================================
   Everything known about one address
   ========================================================================== */
function lookUp(ip) {
  if (!ip) return;
  modal(ip, function (body) { body.appendChild(el('p', 'center', 'Asking…')); }, [
    {words: 'Close', close: true}
  ]);
  var ticket = modalTicket();
  api('address&ip=' + encodeURIComponent(ip)).then(function (d) {
    if (!modalStill(ticket)) return;            /* they moved on */
    if (d.error) {
      /* "that is not an address", said as that - not as the JavaScript
         error the half-empty answer used to throw a line later. */
      modal(ip, function (body) {
        body.appendChild(el('p', 'center bad', String(d.error)));
      }, [{words: 'Close', close: true}], true);
      return;
    }
    var buttons = [{words: 'Close', close: true}];
    if (CAN_BAN) {
      if (d.blocked && d.through) {
        /* Kept out by a range, not by a ban of its own (1.10.198): "Let it
           back in" sent the address and was told it was not on the list. */
        buttons.unshift({words: 'Let the range in', cls: 'danger', close: true, go: function () {
          confirmThen('Let the range in', htmlText(d.ip) + ' has no ban of its own: it is kept '
            + 'out because <b>' + htmlText(d.through) + '</b> is. Letting it go lets in every address of it with no ban of its own; the ones it was folded from, if any, stay banned as themselves.',
            'Let ' + d.through + ' in', function () {
              api('blocked', {remove: d.through}).then(function (r) {
                if (r && r.ok === false) { oops(new Error(r.error || 'not let in')); return; }
                toast(d.through + ' may come back', 'good'); loadBans(); tick();
              }).catch(oops);
            }, false);
        }});
      } else if (d.blocked && String(d.ip).indexOf('/') >= 0) {
        /* A subnet, which letting go takes apart (1.10.200): the addresses
           it was folded from stay banned as themselves - said, and asked
           first, rather than "may come back". */
        buttons.unshift({words: 'Let the range go', cls: 'danger', close: true, go: function () {
          confirmThen('Let the range go', 'Letting <b>' + htmlText(d.ip) + '</b> go lets in '
            + 'every address of it with no ban of its own; the ones it was folded from, if any, '
            + 'stay banned as themselves.', 'Let ' + d.ip + ' go', function () {
              api('blocked', {remove: d.ip}).then(function () {
                toast(d.ip + ' was let go', 'good'); loadBans(); tick();
              }).catch(oops);
            }, false);
        }});
      } else if (d.blocked) {
        buttons.unshift({words: 'Let it back in', cls: 'danger', close: true, go: function () {
          api('blocked', {remove: d.ip}).then(function () {
            delete BANNED[d.ip];
            repaintBans(d.ip);
            toast(d.ip + ' may come back'); loadBans(); tick();
          }).catch(oops);
        }});
      } else if (!d.spared) {
        buttons.unshift({words: 'Ban it for good', cls: 'danger', close: true, go: function () {
          banNow(d.ip, 0, 'banned after looking it up');
        }});
      }
    }
    modal(d.ip + (d.country ? ' · ' + d.country : ''), function (body) {
      drawStory(body, d);
    }, buttons);
  }).catch(function (e) {
    if (!modalStill(ticket)) return;
    modal(ip, function (body) {
      body.appendChild(el('p', 'note', String(e.message || e)));
    }, [{words: 'Close', close: true}], true);
  });
}

/** The names offered from an address, with how many times each.

    Whether one name was tried four hundred times or four hundred names were
    tried once is the difference between somebody guessing a password and
    somebody working through a list of accounts, and it is the first thing
    anybody wants to know about an address. Reading it off the last twenty
    rows does not answer it; this is counted over everything recorded. */
function namesLine(names, bogus) {
  var box = el('span');
  box.style.display = 'inline-flex';
  box.style.flexWrap = 'wrap';
  box.style.gap = '5px';
  box.style.justifyContent = 'flex-end';
  var shown = names.slice(0, 12);
  shown.forEach(function (one) {
    var pill = el('span', 'tag ' + (bogusName(one.name, bogus) ? 'crit' : 'info'));
    pill.style.textTransform = 'none';
    pill.style.fontFamily = 'ui-monospace,Menlo,Consolas,monospace';
    pill.textContent = (one.name || '(no name)')
      + (one.tries > 1 ? ' ×' + num(one.tries) : '');
    explain(pill, (one.name
      ? 'The name <b>' + one.name + '</b> was offered from this address '
      : 'An attempt with no name at all was made ')
      + num(one.tries) + ' time(s), first on ' + stamp(one.first) + ' and last on '
      + stamp(one.last) + '.'
      + (bogusName(one.name, bogus)
         ? '\nThis is one of the names under <b>a name that does not exist</b> in Settings — '
           + 'nobody has ever had it, so every attempt offering it is somebody guessing rather '
           + 'than somebody mistyping. It is what this application bans hardest on.'
         : ''));
    box.appendChild(pill);
  });
  if (names.length > shown.length) {
    var more = el('span', 'muted small', '+' + (names.length - shown.length) + ' more');
    explain(more, namesSaid(names.slice(shown.length), bogus,
      'The other ' + num(names.length - shown.length) + ' name(s) tried from this address, '
      + 'with how many times each:'));
    box.appendChild(more);
  }
  return box;
}

/** Every one of a set of names, written out for a tooltip.

    Nothing is left behind a "+8 more" that cannot be read: what is shown is
    the twelve worst because twelve is what fits on a line, and the rest are
    here in full, in the same order, with the same counts, and with the ones
    that never existed marked the same way. */
function namesSaid(names, bogus, lead) {
  var out = lead ? [lead, ''] : [];
  names.forEach(function (one) {
    out.push('<code>' + (one.name || '(no name)') + '</code>  \u00d7' + num(one.tries)
      + (bogusName(one.name, bogus) ? '   \u2014 a name that never existed' : ''));
  });
  return out.join('\n');
}

/** Whether a name is one of the ones Settings says never existed.

    The list comes with the answer being drawn rather than from whichever tab
    was open last: this popup opens from six different places and only one of
    them has ever loaded the counting. */
function bogusName(name, says) {
  return (says || BOGUS).indexOf(String(name || '').trim().toLowerCase()) >= 0;
}

function drawStory(body, d) {
  var head = el('div');
  head.style.marginBottom = '16px';
  function kv(k, v, d2) {
    var line = el('div', 'kv');
    line.appendChild(el('span', 'k', k));
    var value = el('span', 'v');
    if (v instanceof Node) value.appendChild(v); else value.textContent = v;
    if (d2) value.appendChild(el('span', 'd', d2));
    line.appendChild(value);
    head.appendChild(line);
  }
  var state = el('span');
  if (d.spared) {
    state.appendChild(el('span', 'tag info', 'never kept out'));
    state.appendChild(document.createTextNode(' ' + d.spared));
  } else if (!d.blocked) {
    state.appendChild(el('span', 'tag ok', 'not banned'));
  } else if (d.carried === false) {
    /* Banned, and carried by no firewall (1.10.197). */
    state.appendChild(el('span', 'tag ' + (d.watched ? 'warn' : 'dim'),
                         d.watched ? 'banned, only watched' : 'banned, not carried'));
    state.appendChild(document.createTextNode(' \u00b7 it can reach the VPN'));
  } else if (d.forever) {
    state.appendChild(el('span', 'tag crit', 'banned for good'));
  } else {
    state.appendChild(el('span', 'tag warn', 'banned'));
    state.appendChild(document.createTextNode(' · ' + span(d.until - Date.now() / 1000)
                                              + ' left'));
  }
  kv('Right now', state, d.why || '');
  if (d.how) kv('How long, and why', d.how);
  if (d.since) kv('Banned since', stamp(d.since), d.hits ? 'turned away ' + d.hits + '×' : '');
  kv('Country', countryBadge(d.country));
  /* What the reverse zone calls it - and what it called it before, which is
     the half nothing else on this page can show. An address handed out by
     DHCP is one machine this morning and another this afternoon, so a list
     of the names it has had, each with the days it had them, is a fact
     about this address and about nothing else. */
  if ((d.ptr || []).length) {
    var was = el('div', 'ptrwas');
    d.ptr.forEach(function (one) {
      var line = el('div', 'one');
      line.appendChild(el('span', 'n', one.name || 'no name in the reverse zone'));
      var when = one.first && Math.abs(one.last - one.first) > 90
        ? shortStamp(one.first) + ' \u2192 ' + shortStamp(one.last)
        : shortStamp(one.last);
      line.appendChild(el('span', 'when', when));
      if (one.server) {
        var who = el('span', 'when', '\u00b7 ' + one.server);
        explain(who, 'The name server that answered. The servers are asked in the order '
          + 'they are written in Settings, and the first one with a name for the address '
          + 'is the one that answers.');
        line.appendChild(who);
      }
      was.appendChild(line);
    });
    kv(d.ptr.length > 1 ? 'What it has been called' : 'What it is called', was,
       d.ptr.length > 1 ? 'newest first' : '');
  } else if (d.ptr_on) {
    kv('What it is called', 'nobody has asked yet \u2014 in a moment');
  }
  kv('On public lists', d.feeds.length ? d.feeds.join(', ') : 'none of the ones switched on');
  kv('Banned before', d.before + ' time(s)',
     'which is what the ladder counts from');
  /* Counted off the doors, so that this line and the chips under it agree.
     The two tables alone leave the token attempts out - a token row carries
     the token server's own address, not the person's - and this line used
     to be one short of what the rest of the popup shows. */
  var doors = (d.doors || []).filter(function (x) { return x.failed || x.passed; });
  var sum = doors.reduce(function (m, x) {
    return {failed: m.failed + x.failed, passed: m.passed + x.passed};
  }, {failed: 0, passed: 0});
  if (!doors.length) sum = {failed: d.failed_total || 0, passed: d.passed_total || 0};
  kv('Here it has', num(sum.failed) + ' failed attempt(s)',
     num(sum.passed) + ' successful login(s)');
  if (doors.length) {
    kv('Where it has been seen', doorChips(d.ip, doors),
       'press one to open that list on this address, over all of time');
  }
  if (d.last && d.last.ts) kv('Last seen', lastSeenLine(d.last, true));
  /* What the firewall's own log says it did in the last day, where that log
     is read: one line, and a press into the Traffic page on this address. */
  if (d.firewall && !d.firewall.none) {
    var fw = el('span', 'cc-row');
    [['src', 'started'], ['dst', 'reached']].forEach(function (side) {
      var one = d.firewall[side[0]] || {};
      var said = T_ORDER.filter(function (v) { return one[v]; }).map(function (v) {
        return num(one[v]) + ' ' + T_VERDICTS[v].words;
      }).join(', ');
      if (!said) return;
      var chip = el('button', 'chip', side[1] + ': ' + said);
      chip.type = 'button';
      chip.onclick = function () {
        closeAllModals();
        showTab('traffic');
        /* Every line, not only the sessions: the chip counts the failed
           sign-ins and what the firewall said too. (1.10.166) */
        tOpen((side[0] === 'src' ? 'srcip:' : 'dstip:') + d.ip, 'all');
      };
      fw.appendChild(chip);
    });
    kv('On the firewall', fw, 'the last ' + (d.firewall.hours || 24) + ' h'
       + (d.firewall.bytes ? ' \u00b7 ' + bytes(d.firewall.bytes) + ' carried' : '')
       + (d.firewall.last ? ' \u00b7 last in the hour from ' + shortStamp(d.firewall.last) : '')
       + ' \u2014 press one for those lines on the Traffic page');
  } else if (d.firewall && d.firewall.none) {
    kv('On the firewall', 'nothing in the last ' + (d.firewall.hours || 24) + ' h');
  }
  if ((d.names || []).length) {
    kv('Names it tried', namesLine(d.names, d.bogus),
       (d.names.length === 1
        ? 'one name, every time'
        : d.names.length + ' different name(s), the most tried first'));
  }
  if ((d.names_in || []).length) {
    kv('Names that got in', namesLine(d.names_in, d.bogus),
       'these signed in successfully from this address');
  }
  body.appendChild(head);

  if ((d.proof || []).length) {
    body.appendChild(el('h4', '', 'What earned the ban'));
    var p = el('p', 'note');
    p.textContent = 'The very attempts it was judged on, kept with the ban. The window holds '
      + 'only the last few minutes, so without this there would be nothing left to show an hour '
      + 'later.';
    body.appendChild(p);
    body.appendChild(rowsTable(['When', 'Name', 'Tunnel', 'Why it failed'],
      d.proof.map(function (r) {
        return [shortStamp(r.ts), r.user || '–', r.tunnel || '–', r.reason || ''];
      })));
  }
  if (d.failed_total) {
    body.appendChild(el('h4', '', 'Everything it has failed at'));
    body.appendChild(el('p', 'note', 'Every failed attempt from this address, newest first — '
      + 'not the last few. Search it, filter it, and page through it; it is read from the '
      + 'server a page at a time, so the length of it costs nothing.'));
    body.appendChild(serverList({
      key: 'story-failed:' + d.ip, api: 'failed', params: {ip: d.ip},
      placeholder: 'a name, a reason, a tunnel group\u2026',
      empty: 'Nothing has failed from this address',
      filters: [{name: 'device', from: 'devices', words: 'every device'},
                {name: 'server', from: 'servers', words: 'both nodes'}],
      /* A door of its own, because this list is no longer one door's: the
         token attempts made from this address are in it too, and those
         have no tunnel and no device to tell them apart by. */
      heads: ['When', {words: 'Door', cls: 'placecell'}, 'Name', 'Tunnel', 'Device', 'Node',
              'Why it failed'],
      row: function (r) {
        var tr = el('tr');
        tr.appendChild(stampCell(r.ts));
        tr.appendChild(doorCell(r.kind));
        tr.appendChild(nameCell(r.username));
        tr.appendChild(el('td', '', r.tunnel || '\u2013'));
        tr.appendChild(deviceCell(r));
        tr.appendChild(el('td', '', r.server || '\u2013'));
        tr.appendChild(el('td', '', r.reason || ''));
        return tr;
      }}));
  }
  if (d.passed_total) {
    body.appendChild(el('h4', '', 'Everything that did get in from it'));
    body.appendChild(el('p', 'note', 'Every successful login from this address. On an address '
      + 'that is otherwise failing, this is the list to read first.'));
    body.appendChild(serverList({
      key: 'story-passed:' + d.ip, api: 'passed', params: {ip: d.ip, kind: 'all'},
      placeholder: 'a name, a profile, a device\u2026',
      empty: 'Nobody has ever got in from this address',
      filters: [{name: 'device', from: 'devices', words: 'every device'}],
      heads: ['When', {words: 'Door', cls: 'placecell'}, 'Name', 'Profile', 'Device', 'Node'],
      row: function (r) {
        var tr = el('tr');
        tr.appendChild(stampCell(r.ts));
        tr.appendChild(doorCell(r.kind));
        tr.appendChild(nameCell(r.username));
        tr.appendChild(el('td', '', r.profile || r.subtype || '\u2013'));
        tr.appendChild(deviceCell(r));
        tr.appendChild(el('td', '', r.server || '\u2013'));
        return tr;
      }}));
  }
  if ((d.asked || []).length) {
    body.appendChild(el('h4', '', 'What the token server was asked from it'));
    body.appendChild(el('p', 'note', 'The RADIUS packets that carried a one-time password '
      + 'from this address. They are in neither list above and cannot be: a token attempt\u2019s '
      + 'own row carries the token server\u2019s loopback, because that is who asks the token '
      + 'software \u2014 the person\u2019s address is only ever on the packet. '
      + 'None of it is ever judged and none of it can earn anybody a ban.'));
    body.appendChild(rowsTable(['When', 'Account', 'What the server answered',
                                'The box that asked', 'VPN group', 'The machine', 'Server'],
      d.asked.map(function (r) {
        return [shortStamp(r.ts), r.username || '\u2013',
                r.verdict === 'accept' ? 'accepted'
                  : (r.verdict ? 'refused' + (r.said ? ' \u00b7 ' + r.said : '') : '\u2013'),
                r.nas || '\u2013', r.tunnel || '\u2013', r.device || '\u2013',
                r.server || '\u2013'];
      })));
  }
  if ((d.story || []).length) {
    body.appendChild(el('h4', '', 'Its story'));
    body.appendChild(rowsTable(['When', 'What', 'Why', 'By'],
      d.story.map(function (r) {
        return [shortStamp(r.ts), r.what, r.why || '',
                r.by ? accountWords(r.by) : (r.auto ? 'the counting' : '')];
      })));
  }
  /* ...and what the domain controllers saw from this same address, where
     they are being read. An address that fails at the VPN and fails against
     the domain from the same machine is one story, not two. */
  winBesideAddress(body, d.ip);
}

/** What the domain saw from one address, folded into the address popup. */
function winBesideAddress(body, ip) {
  if (!(STATUS || {}).winsec_on || !ip) return;
  var where = el('div');
  body.appendChild(where);
  api('win-events&hours=168&limit=60&machines=1&choices=0&ip=' + encodeURIComponent(ip))
    .then(function (d) {
      if (!d.total) return;
      where.appendChild(el('h4', '', 'What the domain saw from it'));
      where.appendChild(el('p', 'note', 'Events the domain controllers wrote down about '
        + 'this address in the last week. Nothing here is judged and nothing here banned '
        + 'it.'));
      where.appendChild(winRowsTable(d.rows, 'peek-addr-win'));
    }).catch(function () { /* the story above is the answer; this is extra */ });
}

/** An account's name, as it is: never a word to translate. An account
    called "service" read "služba" in Czech. (1.10.159) */
function accountWords(name) {
  return noI18n(el('span', '', String(name || '')));
}

function rowsTable(headers, rows) {
  var wrap = el('div', 'scroll');
  wrap.style.margin = '6px 0 18px';
  var table = el('table', 'plain');
  var thead = el('thead'), tr = el('tr');
  headers.forEach(function (hh) { tr.appendChild(el('th', '', hh)); });
  thead.appendChild(tr);
  table.appendChild(thead);
  var body = el('tbody');
  rows.forEach(function (r) {
    var line = el('tr');
    /* A cell is words, or a node drawn already - a name kept as it is. */
    r.forEach(function (cell) {
      if (cell && cell.nodeType) {
        var td = el('td');
        td.appendChild(cell);
        line.appendChild(td);
      } else {
        line.appendChild(el('td', '', cell));
      }
    });
    body.appendChild(line);
  });
  table.appendChild(body);
  wrap.appendChild(table);
  return wrap;
}

$('look-go').onclick = function () { lookUp($('look-ip').value.trim()); };
$('look-ip').addEventListener('keydown', function (e) {
  if (e.key === 'Enter') lookUp($('look-ip').value.trim());
});
</script>
<script nonce="<?= h($nonce) ?>">
'use strict';
/* ==========================================================================
   The banned list
   ========================================================================== */
var BANS_AT = 0;
var BANS_ASKED = 0;
function loadBans() {
  /* Which sources are on, for striking the ones that are off (1.10.195). */
  /* ...asked again once a minute (1.10.197): changed at another desk or by
     the command line, the Source cells went on striking the old ones. */
  if ((!SOURCES || Date.now() - (SOURCES_AT || 0) > 60000)
      && typeof loadSources === 'function') loadSources(true);
  /* The list of who is kept out, without the history under it: that is
     `loadPast`'s, and asked for here as well it was counted twice a poll. */
  /* The counting's rows only while its fold is open: a thousand of them,
     with every poll, were most of what this page fetched. (1.10.168) */
  var soon = $('soon-fold');
  /* Unchanged since it was drawn: the daemon says so in a line. The whole
     list is asked for again once a minute anyway, for the counts in it -
     every twenty seconds was two megabytes three times a minute on a site
     with two thousand bans. (1.10.168, 1.10.178) */
  var ask = 'blocked&limit=1&parts=bans&counting=' + (soon && soon.open ? 1000 : 0);
  if (BANS && BANS.stamp && Date.now() - BANS_AT < 60000) {
    ask += '&if=' + encodeURIComponent(BANS.stamp);
  }
  /* Only the newest asking is drawn (1.10.176): a poll that left before an
     Unban and came back after it put the address back as banned. */
  var mine = ++BANS_ASKED;
  api(ask).then(function (d) {
    if (mine !== BANS_ASKED) return;
    if (d && d.same) return;
    BANS_AT = Date.now();
    BANS = noteBanned(d) || d;
    $('bans-rule').textContent = d.on
      ? (d.trigger + ' earns a ban · ' + d.lengths)
      : 'banning is switched off';
    paintBans();
  }).catch(oops);
}

/* A ban is made, and the page catches up. The one thing that must not happen
   is the list redrawing from a poll that started before the change landed, so
   every one of these asks for the list again itself. */
function banChange(body, words) {
  api('blocked', body).then(function () {
    if (words) toast(words, 'good');
    /* Whatever this changed, every row on every open list showing that
       address says so at once rather than at its next redraw. */
    var who = body.remove || body.add;
    if (who) {
      if (body.remove) delete BANNED[who];
      repaintBans(who);
    } else {
      repaintBans();
    }
    loadBans();
    loadPast();
    tick();
  }).catch(oops);
}

function banNow(ip, minutes, why, after) {
  api('blocked', {add: ip, minutes: Number(minutes) || null, why: why || 'banned by hand'})
    .then(function (d) {
      toast(ip + ' is banned ' + (d.until ? 'until ' + stamp(d.until) : 'for good'), 'good');
      /* Remembered here as well as reloaded, so every list already drawn says
         so on its next paint rather than on its next fetch. */
      BANNED[ip] = {ip: ip, until: d.until || null, forever: !d.until,
                    why: why || 'banned by hand', auto: false, through: ''};
      /* Every row on the page showing this address, wherever it is drawn. */
      repaintBans(ip);
      loadBans();
      if (after) after(); else tick();
    }).catch(oops);
}

/* ---- who is counting up, and how far they have to go -------------------
   A bar per address rather than a number, because "3" means nothing without
   "of 5" beside it, and because the eye reads a row of bars in one pass and
   a column of fractions in several. Whichever rule would fire first is the
   one drawn: an address three attempts from the ordinary bar and one attempt
   from the harder one is one attempt away, and saying "3 of 5" about it
   would be true and misleading. */
function paintCounting() {
  var host = $('soon-body');
  if (!host || !BANS) return;
  var says = BANS.counting || {rows: []};
  var rows = says.rows || [];
  var clear_ = $('soon-clear');
  if (clear_) clear_.disabled = !ADMIN || !rows.length;
  var line = $('soon-from');
  if (line) {
    line.hidden = !says.from;
    if (says.from) {
      line.textContent = 'The counting was last started again on ' + stamp(says.from)
        + '. Nothing before that moment counts towards a ban; every record of it is still '
        + 'here, on the Failed attempts page.';
    }
  }
  /* The true count, not the length of the list: the page is given the
     nearest of them (a thousand at most), and a list cut at its limit used
     to say two hundred as though that were everybody. */
  var total = Math.max(rows.length, Number(says.total) || 0);
  var many = says.total_is_floor ? 'more than ' + num(total) : num(total);
  var cut = total > rows.length;
  /* Folded shut, the rows were not asked for: the number is all there is. */
  if (says.rows_cut && !rows.length && total) {
    $('soon-count').textContent = many + ' address(es) counting, in a window of '
      + base_words_js(says.window_min);
    $('soon-n').textContent = many + ' address(es)';
    if (clear_) clear_.disabled = !ADMIN;
    return;
  }
  $('soon-count').textContent = rows.length
    ? many + ' address(es) counting, in a window of '
      + base_words_js(says.window_min)
      + (cut ? ' \u2014 the ' + num(rows.length) + ' nearest to a ban are listed' : '')
    : 'nobody is counting up right now';
  $('soon-n').textContent = rows.length
    ? (cut ? num(rows.length) + ' of ' + many : num(rows.length)) + ' address(es)' : 'none';
  clear(host);
  if (!rows.length) {
    host.appendChild(el('p', 'note', 'Nothing has failed inside the window. The window is '
      + base_words_js(says.window_min) + ' and the bar is ' + num(says.bar)
      + ' failed login(s); both are in Settings.'));
    return;
  }
  var lead = el('p', 'note');
  lead.innerHTML = '<b>' + num(says.bar) + '</b> failed login(s) inside '
    + base_words_js(says.window_min) + ' earns a ban'
    + (says.bogus_bar ? ', and <b>' + num(says.bogus_bar) + '</b> of them offering a name that '
       + 'does not exist (' + (says.bogus_names || []).map(richText).join(', ')
       + ') goes out for good at '
       + 'once' : '')
    + '. The bar below each address is whichever of those it will reach first.';
  host.appendChild(lead);
  host.appendChild(listView({
    key: 'counting', rows: rows, per: 25, barFrom: 6,
    placeholder: 'an address, a country\u2026',
    empty: 'Nobody is counting up right now',
    hay: function (r) {
      return [r.ip, r.country, r.nearest].concat((r.src || []).map(function (k) {
        return k + ' ' + (BAN_SOURCE_WORDS[k] || '');
      })).join(' ');
    },
    countryOf: function (r) { return r.country; },
    draw: function (page, into) {
      into.appendChild(listTable(
        [addrHeads(), {words: 'How close', cls: 'num'}, '',
         {words: 'Names', cls: 'num'}, 'Source', 'Last tried'].concat(banHeads()), page,
        function (r) {
          var tr = el('tr');
          addrPlaceCountry(tr, r.ip, r.country, false, r.last);
          /* How many it has made against how many it may make. */
          var against = r.nearest === 'the counting' ? r.bar : r.bogus_bar;
          var made = r.nearest === 'the counting' ? r.tries : r.bogus;
          var n = el('td', 'num');
          n.appendChild(el('span', '', num(made) + ' of ' + num(against)));
          tr.appendChild(n);
          var barcell = el('td', 'soon-bar');
          var bar = el('div', 'bar');
          var fill = el('span');
          var share = Math.max(4, Math.min(100, Math.round(100 * made / Math.max(1, against))));
          fill.style.width = share + '%';
          fill.style.background = r.left <= 1 ? 'var(--crit)'
            : (r.left <= 2 ? 'var(--warn)' : 'var(--info)');
          bar.appendChild(fill);
          barcell.appendChild(bar);
          /* Over the bar is not the same as at it, and a row that says
             "6 of 3" while nothing happens is the page promising something
             the daemon is not doing. It can only be one of three things -
             whitelisted, on a device nothing watches, or a moment away from
             the pass that fetches it - and each of them says which. */
          var words = el('span', 'soon-left', !r.left
            ? (made > against ? 'over the bar \u2014 going out' : 'at the bar')
            : (r.left === 1 ? 'one more' : num(r.left) + ' more'));
          if (r.nearest !== 'the counting') words.textContent += ' · a name that does not exist';
          if (r.spared) {
            words.textContent = 'never kept out';
            fill.style.background = 'var(--ok)';
          } else if (r.watched === false) {
            words.textContent = 'not a watched device — counted by nothing';
            fill.style.background = 'var(--tx-mut)';
          }
          explain(words, r.spared
            ? 'This address is on the whitelist, so it is recorded and never banned however '
              + 'many times it fails.'
            : (r.watched === false
               ? 'Every one of these came from a device that is not in <b>watch_devices</b>, so '
                 + 'none of them is counted towards a ban. It is here because it is happening, '
                 + 'not because it is about to earn anything.'
               : 'It has made <b>' + num(r.tries) + '</b> failed login(s) inside the window, '
                 + (r.bogus ? '<b>' + num(r.bogus) + '</b> of them offering a name that does '
                    + 'not exist, ' : '')
                 + 'and is <b>' + (r.left || 'no') + '</b> more away from a ban.'
                 + (made > against
                    ? ' It is already past the bar, so it is going out at the next pass '
                      + '\u2014 within a minute. An address is only counted from the end of '
                      + 'its last ban, so what is here it has not been banned for yet.' : '')));
          barcell.appendChild(words);
          tr.appendChild(barcell);
          tr.appendChild(el('td', 'num', r.users ? num(r.users) : '\u2013'));
          tr.appendChild(banSourceCell(r.src || []));
          if ((r.src || []).length && !(r.src_on || []).length) {
            /* Its source only watched: a ban made here is carried nowhere
               (1.10.196); switched off, it earns nothing. */
            words.textContent = (r.src_watch || []).length
              ? words.textContent + ' \u00b7 only watched: carried nowhere'
              : 'its source is off \u2014 earns nothing';
            fill.style.background = (r.src_watch || []).length ? 'var(--warn)' : 'var(--tx-mut)';
          }
          tr.appendChild(stampCell(r.last, 'dim'));
          banOnto(tr, r.ip, 'banned before it reached the bar', loadBans, true);
          opensWith(tr, '', function () { lookUp(r.ip); });
          return tr;
        }, 'plain'));
    }
  }));
}

/** "10 min", "1 h", said the way the daemon says it. */
function base_words_js(minutes) {
  minutes = Math.max(0, Math.round(Number(minutes) || 0));
  if (minutes < 60) return minutes + ' min';
  if (minutes % 1440 === 0) return (minutes / 1440) + (minutes === 1440 ? ' day' : ' days');
  if (minutes % 60 === 0) return (minutes / 60) + (minutes === 60 ? ' hour' : ' hours');
  return minutes + ' min';
}

function paintBans() {
  var host = $('bans-list');
  if (!BANS) return;
  /* Nothing to let back in, nothing to press - as the counting's own Clear
     all is. It offered "all 0 address(es)". (1.10.160) */
  if ($('ban-clear')) $('ban-clear').disabled = !ADMIN || !(BANS.blocked || []).length;
  paintCounting();
  clear(host);
  var rows = BANS.blocked || [];
  $('bans-note').textContent = rows.length
    ? (rows.length + ' address(es) on the list')
    : '';
  if (!BANS.on) {
    var off = el('p', 'note');
    off.style.color = 'var(--warn)';
    off.textContent = 'Banning is switched off. Nothing is being enforced and nothing of ours is '
      + 'left on the router. The ' + rows.length + ' address(es) below are kept as they are, and '
      + 'switching it back on in Settings fills the router again from them.';
    host.appendChild(off);
  }
  if (!rows.length) {
    host.appendChild(el('p', 'btnhelp', 'Nobody is banned.'));
    return;
  }
  /* Three folds, and a row belongs to the first that is true of it, so
     nothing appears twice: what somebody else's list already knew, what was
     put there by hand, and what this machine worked out on its own. Each will
     be long in time, and a hundred rows above the handful that matter buries
     them. */
  /* ...and a fourth, first (1.10.193): what no source switched on stands
     behind, kept here and carried nowhere. */
  var watched = rows.filter(function (r) { return r.src_off && (r.src_watch || []).length; });
  var off = rows.filter(function (r) { return r.src_off && !(r.src_watch || []).length; });
  var carried = rows.filter(function (r) { return !r.src_off; });
  var listed = carried.filter(function (r) {
    return (r.on_feeds || []).length || r.from_feed;
  });
  var byHand = carried.filter(function (r) {
    return !((r.on_feeds || []).length || r.from_feed) && !r.auto;
  });
  var own = carried.filter(function (r) {
    return !((r.on_feeds || []).length || r.from_feed) && r.auto;
  });
  /* Closed to begin with, all of them. On a busy morning each of these is
     hundreds of rows, and a page that opens as a mile of addresses buries
     the counts and the buttons above it. Whatever somebody opens stays open
     while they are on the page. */
  if (own.length) host.appendChild(bansFold(own, 'own', 'Caught by the counting', false));
  if (listed.length) host.appendChild(bansFold(listed, 'listed', 'On a public list', false));
  if (byHand.length) host.appendChild(bansFold(byHand, 'hand', 'Put here by hand', false));
  if (watched.length) {
    host.appendChild(bansFold(watched, 'watched', 'Only watched: what they would keep out',
                              false));
  }
  if (off.length) {
    host.appendChild(bansFold(off, 'off', 'Not carried: their source is switched off', false));
  }
  explainWhatWasDrawn(host);
}

/* How each group is being looked at: what is typed in its search box, how
   many rows it shows at a time and which page of them. Kept out here so that
   the list redrawing itself every few seconds does not throw away what
   somebody is in the middle of reading. */
var FOLD_VIEW = {};

/* What each group of bans is, and how an address ends up in it. */
var FOLD_SAYS = {
  own: 'Addresses this daemon banned by counting: they failed often enough inside the window '
    + 'to reach the bar, or offered a name that was never an account. The bar and the window '
    + 'are under Settings \u2192 Banning.',
  listed: 'Addresses a public blacklist already names, which then failed here at all. That is '
    + 'two things rather than one \u2014 somebody else\u2019s list of known-bad <b>and</b> a '
    + 'knock on this door \u2014 which is why one failure is enough. Switched on and off with '
    + '<i>A public list is enough</i> under Settings \u2192 Public lists.',
  hand: 'Addresses somebody put here themselves, with the box at the bottom of this card or '
    + 'with <code>isemon --ban</code>. Nothing the counting does ever takes one of these off.',
  watched: 'Bans made by a source that is only watched under Settings \u2192 Banning \u2192 '
    + 'Where the bans come from: counted and made as if it banned, and carried nowhere. They '
    + 'are what that source would keep out; switched on, every one of them still running is '
    + 'carried at once.',
  off: 'Bans whose every source is switched off under Settings \u2192 Banning \u2192 Where '
    + 'the bans come from. They are kept and run out as they would, but no firewall, no '
    + 'published list and no access list carries them; switched on again, they are carried '
    + 'again.'
};

/* What each source of a ban is called (1.10.193). */
var BAN_SOURCE_WORDS = {ise: 'the VPN through ISE', nps: 'the VPN through NPS',
                        radius: 'the VPN through FreeRADIUS',
                        tacacs: 'logins to network devices', fw: 'logins at the firewall',
                        win: 'domain logons from outside', manual: 'by hand'};
/** A cell naming where a ban came from: each source by its words, one
    switched off struck through (1.10.195). `old` marks a ban from before
    the sources were written down. */
function banSourceCell(keys, old) {
  var td = el('td', 'small');
  var on = (SOURCES && SOURCES.sources) ? SOURCES.sources.filter(function (x) { return x.on; })
    .map(function (x) { return x.key; }) : null;
  if (!keys.length) {
    td.appendChild(el('span', 'dim', old ? 'the counting' : '\u2013'));
    return td;
  }
  var watching = (SOURCES && SOURCES.sources) ? SOURCES.sources.filter(function (x) {
    return x.mode === 'watch';
  }).map(function (x) { return x.key; }) : [];
  keys.forEach(function (k, i) {
    if (i) td.appendChild(document.createTextNode(', '));
    var w = watching.indexOf(k) >= 0;
    var off = on && on.indexOf(k) < 0 && !w;
    td.appendChild(el(off ? 's' : (w ? 'i' : 'span'), off || w ? 'dim' : '',
                      (BAN_SOURCE_WORDS[k] || k) + (w ? ' (only watched)' : '')));
  });
  explain(td, 'What made this ban. A source switched off under Settings \u2192 Banning is '
    + 'struck through.');
  return td;
}
function banSourcesText(one) {
  return (one.src || []).map(function (k) { return BAN_SOURCE_WORDS[k] || k; }).join(', ');
}

/* The fields of a ban, for the boxes over the groups of them. */
var BAN_QF = [
  ['ip', 'the address, or the range', '45.9.*'],
  ['country', 'the country, as two letters', 'CN,RU'],
  ['why', 'why it was banned', '*INVALID*'],
  ['how', 'how long, in words', ''],
  ['by', 'who banned it', ''],
  ['list', 'the public list that names it', 'firehol*'],
  ['member', 'an address folded into it', ''],
  ['hits', 'how many times it was turned away since', '>10'],
  ['source', 'where the ban came from: ise, nps, radius, tacacs, fw, win, manual', 'win'],
  ['name', 'a name offered from it', 'admin']
];
var BAN_QKNOWN = {};
BAN_QF.forEach(function (f) { BAN_QKNOWN[f[0]] = true; });
function banMembers(one) {
  return (one.members || []).map(function (m) {
    return m && typeof m === 'object' ? (m.ip || '') : String(m || '');
  }).join(' ');
}
function banField(one, field) {
  if (field === 'list') return (one.on_feeds || []).concat(one.from_feed ? [one.from_feed] : []).join(' ');
  /* The addresses folded into it, as the row shows them - each one is
     {ip, why, since}, and joined as they were they read "[object Object]",
     so `member:` found nothing at all. (1.10.166) */
  if (field === 'member') return banMembers(one);
  if (field === 'name') {
    return (one.names || []).map(function (n) { return n && n.name || ''; }).join(' ');
  }
  if (field === 'hits') return one.hits ? String(one.hits) : '';
  if (field === 'source') return (one.src || []).join(' ') + ' ' + banSourcesText(one);
  return one[field] === undefined || one[field] === null ? '' : String(one[field]);
}

function bansFold(rows, key, title, open) {
  var view = FOLD_VIEW[key] || (FOLD_VIEW[key] = {q: '', per: 25, page: 0});
  var box = el('details', 'fold');
  box.open = FOLD_OPEN[key] === undefined ? !!open : FOLD_OPEN[key];
  box.addEventListener('toggle', function () { FOLD_OPEN[key] = box.open; });
  var sum = el('summary', '', title);
  var n = el('span', 'n');
  sum.appendChild(n);
  explain(sum, FOLD_SAYS[key] || 'Press to open or close this group.');
  box.appendChild(sum);

  var bar = el('div', 'fold-bar');
  var find = el('input');
  find.type = 'search';
  find.placeholder = 'an address, a country, a reason, a name\u2026';
  find.value = view.q;
  explain(find, 'Searches this group only, and all of it rather than the page in front of '
    + 'you \u2014 the address, the country, why it was banned, how long it is for and who '
    + 'did it. Case does not matter.');
  var per = el('select');
  [10, 25, 50, 100, 250].forEach(function (x) {
    var o = document.createElement('option');
    o.value = String(x);
    o.textContent = x + ' a page';
    per.appendChild(o);
  });
  per.value = String(view.per);
  explain(per, 'How many of this group to show at a time.');
  /* ...and by country, which two letters in a search box could never do
     properly: typing CZ finds every Czech address and also every name
     ending .cz. Picked, it is the country and nothing else. */
  var counts = {};
  rows.forEach(function (one) {
    var cc = String(one.country || '').toUpperCase();
    if (cc) counts[cc] = (counts[cc] || 0) + 1;
  });
  var pick = el('select');
  var any = document.createElement('option');
  any.value = '';
  any.textContent = 'every country';
  pick.appendChild(any);
  Object.keys(counts).sort().forEach(function (cc) {
    var o = document.createElement('option');
    o.value = cc;
    o.textContent = cc;
    pick.appendChild(o);
  });
  pick.value = view.cc || '';
  pick.onchange = function () { view.cc = pick.value; view.page = 0; paint(); };
  var found = el('span', 'found');
  bar.appendChild(find);
  bar.appendChild(per);
  bar.appendChild(pick);
  bar.appendChild(found);
  box.appendChild(bar);
  /* ...and by field, as every other box (1.10.163). */
  qSuggest(find, {fields: BAN_QF, values: function (field, typed) {
    return qLocalValues(rows, banField, field, typed);
  }});
  setTimeout(function () { asCountryPick(pick, counts); }, 0);

  var body = el('div', 'body');
  box.appendChild(body);
  var pager = el('div', 'fold-pager');
  box.appendChild(pager);

  /* Everything about one row that somebody might type into the box, as one
     lower-case string, worked out once per row rather than once per key. */
  function haystack(one) {
    if (one._hay === undefined) {
      one._hay = [one.ip, one.country, one.why, one.how, one.by,
                  one.forever ? 'for good permanent forever' : '',
                  one.spared ? 'let through whitelist spared' : '',
                  (one.on_feeds || []).join(' '), one.from_feed || '',
                  banMembers(one), banField(one, 'name'), banField(one, 'source')]
        .filter(Boolean).join(' ').toLowerCase();
    }
    return one._hay;
  }

  function paint() {
    var words = view.q.trim().toLowerCase().split(/\s+/).filter(Boolean);
    var only = String(view.cc || '').toUpperCase();
    var parsed = qLocalParse(view.q, BAN_QKNOWN);
    var shown = rows.filter(function (one) {
      if (only && String(one.country || '').toUpperCase() !== only) return false;
      if (parsed) {
        return qLocalTest(parsed, function (f) { return banField(one, f); },
                          function () { return haystack(one); });
      }
      if (!words.length) return true;
      var hay = haystack(one);
      return words.every(function (w) { return hay.indexOf(w) >= 0; });
    });
    var pages = Math.max(1, Math.ceil(shown.length / view.per));
    if (view.page >= pages) view.page = pages - 1;
    if (view.page < 0) view.page = 0;
    var from = view.page * view.per;
    var page = shown.slice(from, from + view.per);

    n.textContent = (words.length || only)
      ? num(shown.length) + ' of ' + num(rows.length) + ' address(es)'
      : num(rows.length) + ' address(es)';
    found.textContent = shown.length
      ? (shown.length > view.per
         ? num(from + 1) + '\u2013' + num(from + page.length) + ' of ' + num(shown.length)
         : num(shown.length) + ' shown')
      : '';
    clear(body);
    if (!shown.length) {
      body.appendChild(el('div', 'fold-none', words.length
        ? 'Nothing in this group matches \u201c' + view.q.trim() + '\u201d'
        : 'Nothing in this group'));
    } else {
      page.forEach(function (one) { body.appendChild(banRow(one)); });
    }
    clear(pager);
    if (pages > 1) {
      var step = function (label, icon, to, on) {
        var b = cmdButton(label, icon, 'small');
        b.disabled = !on;
        explain(b, pageSays(label, view.page, pages));
        b.onclick = function (e) {
          e.preventDefault();
          view.page = to;
          paint();
        };
        return b;
      };
      pager.appendChild(step('First', 'first', 0, view.page > 0));
      pager.appendChild(step('Back', 'prev', view.page - 1, view.page > 0));
      pager.appendChild(explain(el('span', 'muted',
        'page ' + (view.page + 1) + ' of ' + pages),
        'Which page of this list is on show, and how many there are. How many rows go on a '
        + 'page is set in the box above; searching narrows the list first, so the number of '
        + 'pages changes as you type.'));
      pager.appendChild(step('Next', 'next', view.page + 1, view.page < pages - 1));
      pager.appendChild(step('Last', 'last', pages - 1, view.page < pages - 1));
    }
    explainWhatWasDrawn(body);
    explainWhatWasDrawn(pager);
  }

  find.addEventListener('input', debounce(function () {
    view.q = find.value;
    view.page = 0;
    paint();
  }, 180));
  per.onchange = function () {
    view.per = Number(per.value) || 25;
    view.page = 0;
    paint();
  };
  paint();
  return box;
}

/** The names tried from an address, on one line of a list.

    A row that says an address failed eleven times does not say what it was
    failing at, and that is the thing somebody reading the list actually
    wants: one name eleven times is a password being guessed, eleven names
    once each is somebody working through a list of accounts, and a name that
    never existed is a scanner. It is the same summary the address popup
    shows, small enough to sit under the address. */
function namesRow(names, bogus, cut) {
  var line = el('span', 'muted small namesrow');
  var who = el('span', 'muted small');
  who.textContent = '\uD83D\uDC64 ';
  line.appendChild(who);
  names.slice(0, 4).forEach(function (one) {
    var pill = noI18n(el('span', 'tag ' + (bogusName(one.name, bogus) ? 'crit' : 'info')
      + ' namepill'));
    pill.textContent = (one.name || '(no name)') + (one.tries > 1 ? ' \u00d7' + num(one.tries) : '');
    explain(pill, (one.name
      ? 'The name <b>' + one.name + '</b> was offered from this address '
      : 'An attempt with no name at all was made ')
      + num(one.tries) + ' time(s). Press the address for every one of them.'
      + (bogusName(one.name, bogus)
         ? '\nIt is one of the names under <b>a name that does not exist</b> in Settings: '
           + 'nobody has ever had it, so this is guessing rather than mistyping.'
         : ''));
    line.appendChild(pill);
  });
  if (names.length > 4) {
    var more = el('span', 'muted small');
    more.textContent = '+' + (names.length - 4) + ' more';
    /* The daemon hands a row up to twenty-five names; past that the tooltip
       says so rather than pretending the list is the whole of it. */
    var rest = names.slice(4);
    /* `cut`: the Banned list is handed only the first six of each ban's
       names (1.10.178) - twenty-five for two thousand bans were most of a
       two-megabyte answer - and the popup has the rest. */
    var all = rest.length <= 20 && !cut;
    explain(more, namesSaid(rest.slice(0, 20), bogus,
      (all ? 'The other ' + num(rest.length) + ' name(s) tried from this address, with how '
             + 'many times each:'
           : 'The next ' + num(20) + ' names tried from this address. There are more than '
             + 'fit here \u2014 press the address for every one of them:')));
    line.appendChild(more);
  }
  return line;
}

/** A user name in a table cell: in the typeface a name is written in, and
    marked when it is one that never existed. */
function nameCell(name) {
  var td = el('td');
  if (!name) { td.textContent = '\u2013'; return td; }
  var box = el('span', 'mono');
  box.textContent = name;
  if (bogusName(name)) {
    box.style.color = 'var(--crit)';
    explain(box, 'The name <b>' + name + '</b> is one of those under <b>a name that does not '
      + 'exist</b> in Settings. Nobody has ever had it, so an attempt offering it is '
      + 'somebody guessing rather than somebody mistyping — which is what this application '
      + 'bans hardest on.');
  }
  td.appendChild(box);
  return td;
}

function banRow(one) {
  var row = el('div', 'appr-row');
  if (one.spared) row.classList.add('spared');
  var marks = el('div', 'appr-marks');
  row.appendChild(marks);
  /* A row of fixed slots, one per thing that can be true of an address, and a
     slot stays empty rather than closing up when its thing is not. That is
     what makes the marks line up down the list: the book is always in the
     same column, so a glance down the page reads as a column rather than as
     a jumble. Each one says what it means when the pointer rests on it. */
  function slot(node, why) {
    var box = el('span', 'appr-slot');
    if (node) {
      node.className = 'appr-icon' + (node.className ? ' ' + node.className : '');
      if (why) explain(node, why);
      box.appendChild(node);
    }
    marks.appendChild(box);
  }
  slot(el('span', '', one.spared ? '🕊️' : (one.auto ? '🤖' : '✋')),
       one.spared
         ? 'Let through anyway: this address is under "never kept out", so the ban is written '
           + 'down and not applied.'
         : (one.auto
            ? 'Put here by the counting, by itself: this address failed often enough inside the '
              + 'window. A hand always beats the counting.'
            : 'Put here by hand — from this page or from the command line.'));
  if (one.from_feed || (one.on_feeds || []).length) {
    slot(el('span', '', '📕'),
         'A list somebody else keeps — ' + ((one.on_feeds || []).join(', ')
           || one.from_feed) + ' — already had this address on it. Nothing is banned for '
           + 'being on a list alone; this one was banned because it is on one AND it failed a '
           + 'login here.');
  } else { slot(null); }
  if ((one.members || []).length) {
    slot(el('span', '', '🧩'),
         'A subnet, folded from ' + one.members.length + ' separate addresses that were all '
         + 'banned in it. One line here and one rule on the router instead of '
         + one.members.length + '. Open it below to see who is in it, or press × to take '
         + 'it apart again.');
  } else { slot(null); }
  if (one.spared) {
    slot(el('span', '', '⛔'),
         'Written down but not applied: this address is under "never kept out" in Settings, so '
         + 'nothing here bans it and nothing of it is ever sent to the router.');
  } else { slot(null); }
  if (one.router) {
    var mark = el('span', one.router === 'yes' ? 'on' : 'off',
                  one.router === 'yes' ? '🛡️' : '⚠️');
    slot(mark, (one.router === 'yes'
      ? 'The router is dropping this one as well: it is on the address list there.'
      : 'The router is not carrying this one, so only this machine knows about it.')
      + (one.router_at ? ' As it stood ' + ago(one.router_at) + '.'
         : ' The router has not been read yet.')
      + (one.router_trouble ? ' The last read failed: ' + one.router_trouble : ''));
    if (one.router_trouble) mark.classList.add('sick');
  } else { slot(null); }
  if (one.country) {
    var cc = el('span', 'appr-slot');
    cc.appendChild(countryBadge(one.country));
    cc.style.width = 'auto';
    cc.style.marginLeft = '4px';
    marks.appendChild(cc);
  }

  var what = el('div', 'appr-what');
  what.appendChild(addrLine(one.ip));
  if ((one.on_feeds || []).length > 1) {
    var lists = el('span', 'muted small',
                   '📕 on ' + one.on_feeds.length + ' lists: ' + one.on_feeds.join(', '));
    what.appendChild(lists);
  }
  if ((one.src || []).length) {
    /* Where it came from, a source switched off struck through (1.10.193). */
    var from = el('span', 'muted small');
    from.appendChild(document.createTextNode('from '));
    (one.src || []).forEach(function (k, i) {
      if (i) from.appendChild(document.createTextNode(', '));
      var isWatched = (one.src_watch || []).indexOf(k) >= 0;
      var tag = el((one.src_on || []).indexOf(k) >= 0 ? 'span' : (isWatched ? 'i' : 's'), '',
                   (BAN_SOURCE_WORDS[k] || k) + (isWatched ? ' (only watched)' : ''));
      from.appendChild(tag);
    });
    if ((one.carried_as || []).length) {
      from.appendChild(document.createTextNode(' · carried as ' + one.carried_as.length
        + ' address(es) of it: the others\u2019 source is off'));
    }
    explain(from, 'What made this ban. A source switched off under Settings \u2192 Banning is '
      + 'struck through; the ban is carried while any of its sources is on.');
    what.appendChild(from);
  }
  what.appendChild(el('span', 'muted small',
    (one.spared ? 'let through anyway — ' + one.spared + ' is never kept out · ' : '')
    + (one.why || '')
    + ' · since ' + stamp(one.since)
    + (one.hits ? ' · turned away ' + one.hits + '× since then' : '')
    + (one.by ? ' · by ' + one.by : '')));
  if ((one.names || []).length) {
    what.appendChild(namesRow(one.names, undefined, one.names_cut));
  }
  if (one.how) {
    var how = el('span', 'muted small', '⏱ ' + one.how
      + (one.before ? ' · banned ' + one.before + '× before' : ''));
    how.title = 'How long this one lasts and why. Settings → Banning sets the ladder and '
      + 'how far back it looks.';
    what.appendChild(how);
  }
  if ((one.members || []).length) {
    var fold = el('details', 'appr-folded');
    fold.open = !!FOLD_OPEN['members:' + one.ip];
    fold.addEventListener('toggle', function () {
      FOLD_OPEN['members:' + one.ip] = fold.open;
    });
    fold.appendChild(el('summary', 'muted small',
                        '🧩 folded from ' + one.members.length + ' address(es)'));
    one.members.forEach(function (m) {
      var line = el('div', 'muted small');
      line.style.marginLeft = '14px';
      line.style.wordBreak = 'break-word';
      line.appendChild(el('span', 'mono', m.ip));
      line.appendChild(document.createTextNode('  ' + String(m.why || '').slice(0, 150)
        + (m.since ? ' · since ' + shortStamp(m.since) : '')));
      fold.appendChild(line);
    });
    what.appendChild(fold);
  }
  row.appendChild(what);

  row.appendChild(el('span', 'appr-left' + (one.forever && !one.spared ? ' soon' : ''),
    one.spared ? 'let through'
      : (one.forever ? 'until taken off' : Math.max(1, Math.ceil(
        /* From the moment it ends, so that a list kept unchanged still
           counts down. (1.10.168) */
        (one.until ? Math.max(0, one.until - banNow_() / 1000) : one.left) / 60)) + ' min')));

  if (CAN_BAN) {
    var off = iconButton('cancel', (one.members || []).length
      ? 'Unfold this subnet' : 'Let this address back in');
    off.onclick = (one.members || []).length
      ? function () {
          confirmThen('Unfold ' + one.ip,
            'The subnet comes off the list, and the <b>' + one.members.length + '</b> address(es) '
            + 'it was folded from go back on as they were — each with its own reason and its '
            + 'own end. Nobody in it is let in who was kept out before.',
            'Unfold it', function () { banChange({remove: one.ip}, one.ip + ' was unfolded'); });
        }
      : function () {
          confirmThen('Let ' + one.ip + ' back in',
            'It may reach the VPN again from the moment this is done, and the router is told so '
            + 'at once. It stays in the history below.',
            'Let it back in', function () {
              banChange({remove: one.ip}, one.ip + ' may come back');
            });
        };
    row.appendChild(off);
  }
  return row;
}

$('ban-add').onclick = function () {
  var ip = $('ban-ip').value.trim();
  if (!ip) { toast('type an address or a subnet first', 'bad'); return; }
  var minutes = Number($('ban-for').value || 0);
  /* Busy while it is asked: Enter pressed twice was the same ban sent
     twice. (1.10.160) */
  if ($('ban-add').disabled) return;
  busy($('ban-add'), true);
  api('blocked', {add: ip, minutes: minutes || null, why: 'banned by hand'}).then(function (d) {
    $('ban-ip').value = '';
    toast(ip + ' is banned ' + (d.until ? 'until ' + stamp(d.until) : 'for good'), 'good');
    loadBans();
    tick();
  }).catch(oops).then(function () { busy($('ban-add'), false); });
};
$('ban-ip').addEventListener('keydown', function (e) {
  if (e.key === 'Enter' && CAN_BAN) $('ban-add').click();
});

$('ban-clear').onclick = function () {
  /* Asked by source first (1.10.195): a switch for each source that has
     bans, all of them on; with every one of them on it is everybody, as it
     always was. */
  api('ban-sources').then(function (d) {
    SOURCES = d;
    var withBans = (d.sources || []).filter(function (x) { return x.bans > 0; });
    if (withBans.length < 2) { banClearAll(); return; }
    var picked = {};
    withBans.forEach(function (x) { picked[x.key] = true; });
    modal('Let them back in \u2014 from which sources', function (body) {
      body.appendChild(el('p', 'note', 'Every ban of each source switched on here is let go. An '
        + 'address banned by another source as well stays, for that one. With every source on, '
        + 'everybody is let back in.'));
      withBans.forEach(function (x) {
        var item = el('div', 'set-item set-bool');
        item.appendChild(el('label', '', x.words + ' \u2014 ' + num(x.bans) + ' ban(s)'));
        var wrap = el('label', 'sw');
        var box = document.createElement('input');
        box.type = 'checkbox';
        box.checked = true;
        box.onchange = function () { picked[x.key] = box.checked; };
        wrap.appendChild(box);
        wrap.appendChild(el('span', 'knob'));
        item.appendChild(wrap);
        body.appendChild(item);
      });
    }, [{words: 'Cancel', close: true},
        {words: 'Let them back in\u2026', cls: 'danger', close: true, go: function () {
          var keys = withBans.filter(function (x) { return picked[x.key]; })
            .map(function (x) { return x.key; });
          if (!keys.length) { toast('no source was chosen'); return; }
          if (keys.length === withBans.length) { banClearAll(); return; }
          var words = withBans.filter(function (x) { return picked[x.key]; })
            .map(function (x) { return x.words + ' (' + num(x.bans) + ')'; }).join(', ');
          confirmThen('Let the bans of these sources go',
            'Every ban of <b>' + htmlText(words) + '</b> is let go. An address banned by '
            + 'another source as well stays, for that one. They stay in the history.',
            'Let them go', function () {
              var chain = Promise.resolve();
              keys.forEach(function (k) {
                chain = chain.then(function () { return api('ban-sources', {release: k}); });
              });
              chain.then(function () {
                toast('the bans of ' + keys.length + ' source(s) were let go', 'good');
                repaintBans();
                loadBans();
                loadSources();
              }).catch(oops);
            });
        }}]);
  }).catch(function () { banClearAll(); });
};
function banClearAll() {
  var n = ((BANS || {}).blocked || []).length;
  confirmThen('Let everybody back in',
    'All <b>' + n + '</b> address(es) come off the list at once, and the router is emptied of '
    + 'ours. Every one of them stays in the history, and anything that goes on failing logins '
    + 'will earn its way back on by itself — at the bottom of the ladder, not where it left '
    + 'off, because the ladder counts bans and these all just ended.',
    'Let them all back in', function () {
      banChange({clear: true}, 'everybody was let back in');
    });
}

/* ---- folding ------------------------------------------------------------- */
$('ban-fold').onclick = function () {
  api('fold').then(function (d) {
    var plan = d.plan;
    modal('Fold addresses into subnets', function (body) {
      var p = el('p', 'note');
      p.innerHTML = 'Attacks arrive from whole streets: this VPN sees thirty-two tries each from '
        + 'a dozen addresses in one /24. Folding turns those into one line, so the router carries '
        + 'one rule instead of a dozen and the list stays readable.<br><br>'
        + 'A subnet is only made where <b>two or more</b> banned addresses fall inside it, and '
        + 'never where it would swallow anything under <i>never kept out</i>. Everything kept '
        + 'about each address stays under its own name, and any folding can be undone on its own '
        + 'afterwards.';
      body.appendChild(p);
      if (!plan.groups.length) {
        body.appendChild(el('p', 'center', 'There is nothing to fold: no two banned addresses '
                                           + 'share a subnet this wide.'));
      } else {
        var sum = el('p', 'note');
        sum.innerHTML = '<b>' + plan.folded + '</b> address(es) would become <b>'
          + plan.subnets + '</b> subnet(s). The list goes from ' + plan.before + ' line(s) to '
          + plan.after + '.';
        body.appendChild(sum);
        plan.groups.forEach(function (g) {
          var box = el('details', 'fold');
          var s = el('summary', '', g.net + (g.existing ? ' (already banned)' : ''));
          s.appendChild(el('span', 'n', g.members.length + ' address(es)'
            + (g.lists.length ? ' · named whole by ' + g.lists.join(', ') : '')));
          box.appendChild(s);
          var inner = el('div', 'body');
          inner.appendChild(rowsTable(['Address', 'Country', 'Why'],
            g.members.map(function (m) {
              return [m.ip, m.country || '–', (m.why || '').slice(0, 80)];
            })));
          box.appendChild(inner);
          body.appendChild(box);
        });
      }
      if ((d.versions || []).length) {
        body.appendChild(el('h4', '', 'Foldings already made'));
        var undoable = d.versions.filter(function (v) { return !v.undone; });
        if (!undoable.length) {
          body.appendChild(el('p', 'btnhelp', 'None that can still be undone.'));
        }
        d.versions.forEach(function (v) {
          var line = el('div', 'kv');
          line.appendChild(el('span', 'k', stamp(v.ts) + ' · /' + v.widest
            + ' · ' + v.before + ' → ' + v.after + ' line(s)'));
          var right = el('span', 'v');
          if (v.undone) {
            right.appendChild(el('span', 'tag dim', 'undone ' + ago(v.undone)));
          } else if (ADMIN) {
            var b = cmdButton('Undo this one', 'undo', 'small');
            explain(b, 'Take this folding apart: the subnet comes off and every address it was '
              + 'made from goes back on as it was, with its own reason and its own end.');
            b.onclick = function () {
              api('fold', {undo: v.id}).then(function (r) {
                toast(r.restored + ' address(es) back on the list', 'good');
                closeModal();
                loadBans();
                tick();
              }).catch(oops);
            };
            right.appendChild(b);
          }
          line.appendChild(right);
          body.appendChild(line);
        });
      }
    }, plan.groups.length ? [
      {words: 'Not now', close: true},
      {words: 'Fold them', cls: 'primary', admin: true, close: true, go: function () {
        api('fold', {apply: true, widest: plan.widest}).then(function (r) {
          watchJob(r.job, 'Folding into subnets', function () { loadBans(); tick(); });
        }).catch(oops);
      }}
    ] : [{words: 'Close', close: true}]);
  }).catch(oops);
};

/* ---- the history --------------------------------------------------------- */
/* The four ways a ban ends, each with a mark that says which without being
   read. They are the same four the story column names in words, so the mark
   and the words never disagree. */
/* How a ban came to be over, as the daemon writes it down: listed here so
   that each is a phrase the page knows and says in its own language - the
   ones written only by the daemon were shown as they were. (1.10.159) */
var BAN_HOW = {'taken off': 'taken off', 'unfolded': 'unfolded',
               'the folding was undone': 'the folding was undone',
               'ran out': 'ran out', 'written over': 'written over'};
function banEnding(r) {
  var how = String(r.how || '').toLowerCase();
  if (!r.ended) {
    /* A ban no source that bans stands behind keeps nobody out (1.10.197):
       "cannot reach the VPN" said of one only watched was not true. */
    var keys = r.src ? String(r.src).split(',') : [];
    var all = (SOURCES && SOURCES.sources) || null;
    if (all && keys.length) {
      var modes = keys.map(function (k) {
        var one = all.filter(function (x) { return x.key === k; })[0];
        return one ? (one.mode || (one.on ? 'on' : 'off')) : 'on';
      });
      if (modes.indexOf('on') < 0) {
        var watched = modes.indexOf('watch') >= 0;
        return {icon: 'eye', cls: 'ran', words: watched ? 'still on, only watched'
                  : 'still on, not carried',
                says: 'Still there, and carried by no firewall: '
                  + (watched ? 'its source is only watched' : 'its every source is switched off')
                  + '. This address can reach the VPN.'};
      }
    }
    return {icon: 'ban', cls: 'on', words: 'still on',
            says: 'Still in force. This address cannot reach the VPN now.'};
  }
  if (/ran out|expired|time/.test(how)) {
    return {icon: 'clock', cls: 'ran', words: 'ran out',
            says: 'It ran out by itself: the ban reached its end and the address was let '
                  + 'back in with nobody having to do anything.'};
  }
  if (/fold|subnet/.test(how) && !/unfold|undone|taken apart/.test(how)) {
    return {icon: 'fold', cls: 'fold', words: 'folded into a subnet',
            says: 'Folded away: this address was swallowed by a subnet that covers it, so '
                  + 'the subnet keeps it out and this row was closed.'};
  }
  if (/written over/.test(how)) {
    return {icon: 'ban', cls: 'on', words: 'written over',
            says: 'A newer ban of the same address took over from this one - by hand, or '
                  + 'the counting reaching a higher rung - so this line was closed and the '
                  + 'newer one carries on.'};
  }
  if (/whitelist|never|spared/.test(how)) {
    return {icon: 'shield', cls: 'spared', words: 'whitelisted',
            says: 'Let back in because the address was put on the whitelist, which nothing '
                  + 'in this daemon may overrule.'};
  }
  return {icon: 'undo', cls: 'back', words: 'let back in',
          says: 'Somebody let it back in' + (r.by ? ' \u2014 ' + r.by : '') + '.'};
}

var PAST_AT = 0, PAST_STAMP = null;
function loadPast() {
  PAST_AT = Date.now();
  PAST_STAMP = BANS && BANS.stamp;
  var q = $('past-q').value.trim();
  var where = $('past-country').value;
  api('blocked&parts=history&limit=25&offset=' + (PAGE.past * 25)
      + (sortArgs(SORTS.past) ? '&' + sortArgs(SORTS.past) : '')
      + (q ? '&q=' + encodeURIComponent(qRewrite(q, qMaps('history'))) : '')
      + (where ? '&country=' + encodeURIComponent(where) : ''), undefined,
      {lane: 'past'}).then(function (d) {
    var body = $('past-table').querySelector('tbody');
    serverSortHeads($('past-table').tHead.rows[0], SORTS.past, PAST_SORT_KEYS, function () {
      PAGE.past = 0;
      loadPast();
    });
    clear(body);
    var rows = d.history || [];
    $('past-empty').hidden = !!rows.length;
    /* A search that found nothing is not a history that is empty. */
    $('past-empty').textContent = (q || where) ? 'Nothing matches'
      : 'Nobody has ever been banned';
    $('past-count').textContent = d.history_capped
      ? 'more than ' + num(Math.min(d.history_total, 20000)) + ' in all'
      : num(Math.min(d.history_total, 20000)) + ' in all';
    fillOnce($('past-country'), Object.keys(d.history_countries || {}).sort());
    asCountryPick($('past-country'), d.history_countries);
    rows.forEach(function (r) {
      var tr = el('tr');
      tr._rec = r;
      opensWith(tr, '', function () { lookUp(r.ip); });
      /* How it ended, as one mark in a column of its own. It was a word
         beside the address before, which put it in a different place on
         every row - the eye cannot read a column that is not a column. */
      var ending = banEnding(r);
      var mark = el('td', 'past-mark');
      var icon = el('span', 'past-icon ' + ending.cls);
      icon.innerHTML = iconMarkup(ending.icon, 15);
      explain(icon, ending.says);
      mark.appendChild(icon);
      tr.appendChild(mark);
      tr.appendChild(stampCell(r.ts, 'dim'));
      /* Drawn as the start beside it is - the same stamp, the same "ago"
         on pointing - rather than a shorter form of its own. (1.10.160) */
      var end = r.ended ? stampCell(r.ended, 'dim') : el('td');
      if (!r.ended) {
        var on = el('span', 'tag crit', 'still on');
        explain(on, 'This ban has not ended. It is either for good, or on a clock that has '
          + 'not run out — the list at the top of this page says which, and carries the '
          + 'button that lets it back in.');
        end.appendChild(on);
      }
      tr.appendChild(end);
      var td = el('td');
      td.appendChild(el('span', 'mono', r.ip));
      tr.appendChild(td);
      tr.appendChild(el('td', '', (r.why || '').slice(0, 90)));
      /* Where it came from (1.10.195): written with the ban since 1.10.193;
         before that, what it was - the counting's or somebody's by hand. */
      tr.appendChild(banSourceCell(r.src
        ? String(r.src).split(',') : [r.auto ? '' : 'manual'].filter(Boolean), r.src ? null : true));
      /* "still on" was written here as well as in the column beside it.
         What belongs here is how a ban that is over came to be over. */
      tr.appendChild(el('td', r.ended ? '' : 'dim',
                        r.ended ? (BAN_HOW[r.how] || r.how || ending.words) : '\u2013'));
      tr.appendChild(el('td', 'num', r.hits ? num(r.hits) : ''));
      if (r.by) {
        var byCell = el('td');
        byCell.appendChild(accountWords(r.by));
        tr.appendChild(byCell);
      } else {
        tr.appendChild(el('td', '', r.auto ? 'the counting' : ''));
      }
      body.appendChild(tr);
    });
    optColumns($('past-table'), OPT_PAST);
    pager('past-pager', PAGE.past, 25, d.history_total, function (page) {
      PAGE.past = page;
      loadPast();
    }, d.history_capped);
  }).catch(oops);
}
$('past-q').addEventListener('input', debounce(function () { PAGE.past = 0; loadPast(); }, 350));
$('past-country').addEventListener('change', function () { PAGE.past = 0; loadPast(); });
/* Clear: the search, the country and the order back to how the page
   opens - newest first. Erasing the history itself lives in Settings,
   under "Erase the collected data", away from a button pressed every day. */
$('past-clear').onclick = function () {
  $('past-q').value = '';
  $('past-country').value = '';
  if ($('past-country')._ccpick) $('past-country')._ccpick.paint();
  PAGE.past = 0;
  sortReset(SORTS.past);
  loadPast();
};
$('past-forget').onclick = function () {
  confirmThen('Erase the ban history',
    'Every closed ban and every line of every address’s story goes. Whoever is banned right '
    + 'now stays banned — but the ladder counts this history, so everybody starts again at '
    + 'the bottom step afterwards. This cannot be undone.',
    'Erase it', function () {
      api('blocked', {forget_history: true}).then(function () {
        toast('the history was erased');
        loadPast();
      }).catch(oops);
    });
};

/* ==========================================================================
   One list, searched and paged
   --------------------------------------------------------------------------
   Every list in this page grows: a month of events is thousands of rows, a
   router carries hundreds of entries, a whitelist fills up, and a list that
   can only be shown whole is a list nobody opens twice. Rather than five
   bespoke filter bars that behave five slightly different ways, this is one:
   a search box, a page size, a count and a pager, over an array that is
   already here.

   What somebody has typed and which page they are on live in VIEWS, keyed by
   name, so that a list redrawing itself every few seconds does not throw away
   what they were in the middle of reading.
   ========================================================================== */
var VIEWS = {};

/** A list the server pages, for the whole of something rather than the end
    of it.

    `listView` next door holds every row in the browser and pages what it was
    given. That is right for a list somebody has already been handed whole,
    and wrong for the attempts of one address, which was being shown as "the
    last twenty" with no way to reach the twenty-first. This asks the API for
    a page at a time — the same endpoints the Failed attempts and Logins
    pages use, with the same searching and the same filters — so the list is
    complete however long it is, and a hundred thousand rows cost the same as
    twenty.

    opts: {key, api, params, heads, row, empty, placeholder, explain, filters}
      api      the endpoint name, e.g. 'failed'
      params   what identifies the list, e.g. {ip: '1.2.3.4'}
      heads    the column headers, as listTable takes them
      row      one record, drawn as a <tr>
      filters  [{name, from, words}] to offer as select boxes, filled from
               the answer's own lists */
function serverList(opts) {
  var view = VIEWS[opts.key]
    || (VIEWS[opts.key] = {q: '', per: opts.per || 25, page: 0, pick: {}});
  var box = el('div', 'list-view');
  var bar = el('div', 'fold-bar');
  var find = el('input');
  find.type = 'search';
  find.placeholder = opts.placeholder || 'search this list\u2026';
  find.value = view.q;
  explain(find, opts.explain || ('Narrow this list as you type. It is searched on the '
    + 'server, over every record there is rather than over the page in front of you — the '
    + 'address, the name tried, the reason it failed, the tunnel group and the device. '
    + 'Empty it to see everything again.'));
  var per = el('select');
  [10, 25, 50, 100, 250].forEach(function (x) {
    var o = document.createElement('option');
    o.value = String(x);
    o.textContent = x + ' a page';
    per.appendChild(o);
  });
  per.value = String(view.per);
  explain(per, 'How many rows to show at a time.');
  bar.appendChild(find);
  bar.appendChild(per);
  /* Fields, as in every search box, where the daemon reads them for this
     list (1.10.163). */
  var qList = {failed: 'failed', passed: 'passed', 'win-events': 'win'}[opts.api];
  if (qList) {
    qSuggest(find, {fields: QF[qList], lane: 'list-' + opts.key,
      values: qServerValues(qList, function () {
        var p = opts.params || {};
        return p.kind ? 'kind=' + encodeURIComponent(p.kind) : '';
      })});
  }

  var picks = {};
  (opts.filters || []).forEach(function (f) {
    var sel = el('select');
    var none = document.createElement('option');
    none.value = '';
    none.textContent = f.words;
    sel.appendChild(none);
    sel.value = view.pick[f.name] || '';
    explain(sel, f.says || ('Show only the rows with this ' + f.words.toLowerCase() + '.'));
    sel.onchange = function () {
      view.pick[f.name] = sel.value;
      view.page = 0;
      fetch_();
    };
    picks[f.name] = {select: sel, from: f.from, filled: false};
    bar.appendChild(sel);
  });

  var found = el('span', 'found');
  bar.appendChild(found);
  var body = el('div', 'list-body');
  var pager = el('div', 'fold-pager');
  box.appendChild(bar);
  box.appendChild(body);
  box.appendChild(pager);

  var busy_ = false;
  /* A change made while a request is out is not dropped: it was, and the
     list went on showing the answer for "ab" under a box reading "abc". It
     is asked the moment the one in flight comes back, and that one's
     answer - about what is no longer asked - is not drawn. */
  var again_ = false;

  function fetch_() {
    if (busy_) { again_ = true; return; }
    busy_ = true;
    found.textContent = 'reading\u2026';
    var bits = ['limit=' + view.per, 'offset=' + (view.page * view.per)];
    Object.keys(opts.params || {}).forEach(function (k) {
      if (opts.params[k]) bits.push(k + '=' + encodeURIComponent(opts.params[k]));
    });
    if (view.q.trim()) {
      bits.push('q=' + encodeURIComponent(qList ? qRewrite(view.q.trim(), qMaps(qList,
        (opts.params || {}).kind || '')) : view.q.trim()));
    }
    Object.keys(view.pick).forEach(function (k) {
      if (view.pick[k]) bits.push(k + '=' + encodeURIComponent(view.pick[k]));
    });
    api(opts.api + '&' + bits.join('&'), undefined, {lane: 'list-' + opts.key}).then(function (d) {
      busy_ = false;
      if (again_) { again_ = false; fetch_(); return; }
      noteBanned(d);
      var rows = d.rows || [];
      var total = Number(d.total || 0);
      found.textContent = (d.capped ? 'more than ' : '') + num(total) + ' in all';
      explain(found, d.capped
        ? 'There are more than ' + num(total) + ' rows. Counting past that point means '
          + 'reading every record there has ever been, so it stops there and says so.'
        : 'How many rows there are in all — not on this page, and not only the recent ones. '
          + 'Narrowing the search changes it.');
      /* The filter boxes are filled from the answer, once: the values are
         whatever this list actually holds. */
      Object.keys(picks).forEach(function (k) {
        var one = picks[k];
        if (one.filled) return;
        var values = d[one.from] || [];
        if (!values.length) { one.select.hidden = true; return; }
        one.filled = true;
        values.forEach(function (v) {
          var o = document.createElement('option');
          o.value = v;
          o.textContent = v;
          one.select.appendChild(o);
        });
        one.select.value = view.pick[k] || '';
      });
      clear(body);
      if (!rows.length) {
        body.appendChild(el('div', 'fold-none', view.q.trim()
          ? 'Nothing here matches \u201c' + view.q.trim() + '\u201d'
          : (opts.empty || 'Nothing here')));
      } else {
        body.appendChild(listTable(opts.heads, rows, opts.row, opts.cls || 'plain'));
      }
      var pages = Math.max(1, Math.ceil(total / view.per));
      if (view.page >= pages) { view.page = pages - 1; }
      clear(pager);
      if (pages > 1) {
        var step = function (label, icon, to, on) {
          var b = cmdButton(label, icon, 'small');
          b.disabled = !on;
          explain(b, pageSays(label, view.page, pages));
          b.onclick = function (e) { e.preventDefault(); view.page = to; fetch_(); };
          return b;
        };
        pager.appendChild(step('First', 'first', 0, view.page > 0));
        pager.appendChild(step('Back', 'prev', view.page - 1, view.page > 0));
        pager.appendChild(explain(el('span', 'muted',
          'page ' + (view.page + 1) + ' of ' + num(pages)),
          'Which page is on show, and how many there are. This list is paged by the server, '
          + 'so it is the whole of it rather than the most recent few.'));
        pager.appendChild(step('Next', 'next', view.page + 1, view.page < pages - 1));
        pager.appendChild(step('Last', 'last', pages - 1, view.page < pages - 1));
      }
      explainWhatWasDrawn(box);
    }).catch(function (e) {
      busy_ = false;
      if (again_) { again_ = false; fetch_(); return; }
      clear(body);
      body.appendChild(el('div', 'fold-none', String(e.message || e)));
    });
  }

  find.addEventListener('input', debounce(function () {
    view.q = find.value;
    view.page = 0;
    fetch_();
  }, 250));
  per.onchange = function () {
    view.per = Number(per.value) || 25;
    view.page = 0;
    fetch_();
  };
  fetch_();
  return box;
}

/* ==========================================================================
   field:value in every search box
   --------------------------------------------------------------------------
   The Traffic page's search box has always understood `srcip:10.1.2.3
   -dstport:443` and offered, as somebody typed, the fields there are and
   what each one holds, busiest first. Every other search box on the page
   does the same now (1.10.163): the refusals, the sign-ins, the domain's
   events, the daemon's own events, the ban history, every list in a popup
   and every list on a card. A box with no field typed into it searches
   exactly as it always did.

   The lists the daemon searches send what was typed and the daemon reads
   it (`ListQuery`); the lists held in the page are read here, a field being
   a column of the table by the words of its heading.
   ========================================================================== */
var QF = {
  failed: [
    ['ip', 'the address it came from', '10.1.2.3, 10.1.*, 10.1.0.0/16'],
    ['user', 'the name offered', 'novak, adm*'],
    ['reason', 'why it was refused', '*password*'],
    ['device', 'the device that asked', ''],
    ['server', 'the node that wrote it', ''],
    ['tunnel', 'the VPN tunnel group', ''],
    ['country', 'the country, as two letters', 'CN,RU'],
    ['mac', 'the machine’s MAC, written any way', '98:fc:84:*'],
    ['port', 'the switch port', ''],
    ['ssid', 'the wireless network', ''],
    ['machine', 'what the machine calls itself', ''],
    ['client', 'the address the machine had', ''],
    ['realm', 'the institution, on eduroam', ''],
    ['code', 'the failure’s number', ''],
    ['nad', 'the address the device asked from', ''],
    ['service', 'the access service', ''],
    ['protocol', 'the protocol', ''],
    ['door', 'which door: vpn, tacacs, dot1x-lan, mab-wifi…', '']
  ],
  passed: [
    ['ip', 'the address it came from', '10.1.2.3, 10.1.*'],
    ['user', 'the name', 'novak'],
    ['profile', 'the authorisation or shell profile', ''],
    ['policy', 'the policy set', ''],
    ['group', 'one of the directory groups', ''],
    ['acl', 'the downloadable ACL', ''],
    ['device', 'the device that asked', ''],
    ['server', 'the node that wrote it', ''],
    ['tunnel', 'the VPN tunnel group', ''],
    ['country', 'the country, as two letters', 'CZ'],
    ['mac', 'the machine’s MAC, written any way', ''],
    ['port', 'the switch port', ''],
    ['ssid', 'the wireless network', ''],
    ['vlan', 'the VLAN it was put in', ''],
    ['machine', 'what the machine calls itself', ''],
    ['client', 'the address the machine had', ''],
    ['realm', 'the institution, on eduroam', ''],
    ['command', 'a command run on a switch', 'conf*'],
    ['step', 'the TACACS+ step', ''],
    ['verdict', 'what was decided', ''],
    ['service', 'the access service', ''],
    ['nad', 'the address the device asked from', ''],
    ['door', 'which door: vpn, tacacs, dot1x-lan, mab-wifi…', '']
  ],
  /* In the order the domain's columns stand (1.10.166): What happened,
     Account, From, Through, Why, Controller - and then what is behind them. */
  win: [
    ['what', 'What happened', 'signed in, locked out'],
    ['event', 'the Windows event number', '4625, 4740, 4768-4771'],
    ['account', 'Account', 'novak, *$'],
    ['domain', 'the domain of the account', ''],
    ['by', 'who did it, where that is somebody else', ''],
    ['from', 'From — the machine, or the address where there is none', 'PC-01, 10.1.*'],
    ['logon', 'the logon type', 'over the network, 3'],
    ['through', 'Through — the program', 'lsass.exe'],
    ['why', 'Why — what the domain said, or what was changed', ''],
    ['controller', 'Controller', ''],
    ['machine', 'the machine it came from', ''],
    ['ip', 'the address it came from', ''],
