    if (document.activeElement !== input) { drop.hidden = true; st.items = []; return; }
    st.items = items;
    st.at = items.length ? 0 : -1;
    st.moved = false;
    if (!items.length) { drop.hidden = true; return; }
    var head = el('div', 't-sug-head', title);
    if (about) {
      head.appendChild(document.createTextNode(' \u2014 '));
      head.appendChild(el('span', '', about));
    }
    drop.appendChild(head);
    items.forEach(function (it, n) {
      var row = el('div', 't-sug' + (n === 0 ? ' on' : ''));
      row.appendChild(noI18n(el('span', 't-sug-val' + (it.mono === false ? '' : ' mono'),
                                it.show)));
      var note = el('span', 't-sug-note', it.note || '');
      if (it.data && !it.words) noI18n(note);
      if (it.ex) {
        /* What to type, as it is typed: never translated. */
        note.appendChild(document.createTextNode(' '));
        note.appendChild(noI18n(el('span', 'mono qs-ex', it.ex)));
      }
      row.appendChild(note);
      if (it.n !== undefined) row.appendChild(el('span', 't-sug-n', num(it.n)));
      row.onmousedown = function (e) { e.preventDefault(); take(n); };
      row.onmousemove = function () { mark(n); };
      drop.appendChild(row);
    });
    /* The box's own explanation would sit on top of what it offers. */
    if (typeof hideHelp === 'function') hideHelp();
    /* The syntax as it is typed, never translated; the words between it are. */
    var foot = el('div', 't-sug-foot');
    [['field:a,b', 'any of them'], ['-field:value', 'not'], ['*', 'anything'],
     ['(a OR b)', 'either']].forEach(function (p) {
      foot.appendChild(noI18n(el('code', 'qs-syn', p[0])));
      foot.appendChild(el('span', 'qs-syn-says', p[1]));
    });
    foot.appendChild(el('span', '', '↑ ↓ and Tab or Enter take one · Esc closes'));
    drop.appendChild(foot);
    drop.hidden = false;
    wrap.classList.add('qs-open');
  }
  function take(n) {
    var it = st.items[n];
    if (!it) return;
    var text = input.value;
    var before = text.slice(0, it.from), after = text.slice(it.to);
    var put = it.put;
    var at = before.length + put.length;
    if (it.done && !/^\s/.test(after)) { put += ' '; at += 1; }
    input.value = before + put + after.replace(/^"/, '');
    input.focus();
    try { input.setSelectionRange(at, at); } catch (e) { /* not a text box */ }
    close();
    /* Whatever the box does when somebody types, it does now. */
    input.dispatchEvent(new Event('input', {bubbles: true}));
    if (!it.done) offer();
  }
  function offer() {
    if (st.hold || document.activeElement !== input) return;
    var where = caret();
    var mine = ++st.asked;
    if (where.field) {
      if (where.op !== ':' && where.op !== '=' && where.op !== '~' && where.op !== '!=') {
        close();
        return;
      }
      var about = fields().filter(function (f) { return f[0] === where.field; })[0] || [];
      Promise.resolve(cfg.values(where.field, where.typed || '')).then(function (got) {
        if (mine !== st.asked) return;
        st.values = true;
        var items = (got || []).map(function (v) {
          var quoted = /[\s(),"]/.test(v.val) || where.quoted;
          return {show: v.val, note: v.note || '', data: true, words: !!v.words, n: v.n,
                  put: quoted ? '"' + String(v.val).replace(/"/g, '') + '"' : v.val,
                  from: where.valueAt - (where.quoted ? 1 : 0), to: where.end, done: true};
        });
        draw('What ' + where.field + ' holds, most first', items.slice(0, 30), about[1]);
      }).catch(function () { close(); });
      return;
    }
    var typed = where.body.toLowerCase();
    st.typed = !!typed;
    if (/["]/.test(typed) || /[^a-z_-]/.test(typed)) { close(); return; }
    var items = [];
    var offerOne = function (f) {
      items.push({show: f[0] + ':', note: f[1], ex: f[2] || '',
                  put: where.lead + f[0] + ':', from: where.start, to: where.end, done: false});
    };
    /* A card's own columns first; once a letter is typed, also whatever
       else its rows hold (the columns that can be switched on). */
    var all = fields();
    if (typed && cfg.more) {
      var ownNames = {};
      all.forEach(function (f) { ownNames[f[0]] = true; });
      all = all.concat((cfg.more() || []).filter(function (f) { return !ownNames[f[0]]; }));
    }
    all.forEach(function (f) { if (!typed || f[0].indexOf(typed) === 0) offerOne(f); });
    all.forEach(function (f) { if (typed && f[0].indexOf(typed) > 0) offerOne(f); });
    if (!items.length) { close(); return; }
    draw(typed ? 'Fields' : (cfg.card ? 'The columns of this card — or type a word to find '
                             + 'it anywhere' : 'Fields — or type a word to find it anywhere'),
         items);
  }
  var soon = debounce(offer, 120);
  input.addEventListener('input', function () { st.hold = false; soon(); });
  input.addEventListener('focus', function () {
    st.hold = false;
    soon();
    if (!said.hidden && typeof hideHelp === 'function') setTimeout(hideHelp, 0);
  });
  input.addEventListener('click', function () { st.hold = false; soon(); });
  input.addEventListener('blur', function () { setTimeout(close, 150); });
  input.addEventListener('keydown', function (e) {
    var open = !drop.hidden && st.items.length;
    if (!open) return;
    if (e.key === 'ArrowDown') {
      e.preventDefault(); st.moved = true;
      mark(Math.min(st.items.length - 1, st.at + 1));
    } else if (e.key === 'ArrowUp') {
      e.preventDefault(); st.moved = true;
      mark(Math.max(0, st.at - 1));
    } else if (e.key === 'Tab' && (st.moved || st.typed || st.values)) {
      /* Only when something is being typed or chosen: tabbing through the
         filters past an empty box moves on, as it always did. */
      e.preventDefault();
      take(st.at < 0 ? 0 : st.at);
    } else if (e.key === 'Enter' && st.moved) {
      e.preventDefault(); e.stopImmediatePropagation();
      take(st.at);
    } else if (e.key === 'Enter') {
      st.hold = true;
      close();
    } else if (e.key === 'Escape') {
      e.preventDefault(); e.stopPropagation();
      close();
    }
  }, true);
  return me;
}

/** The values one field of a list the daemon searches holds. `extra` gives
    what else narrows them: the door, the window. */
function qServerValues(list, extra) {
  return function (field, typed) {
    var more = extra ? extra() : '';
    return api('suggest&list=' + list + '&field=' + encodeURIComponent(field)
               + '&typed=' + encodeURIComponent(typed || '') + (more ? '&' + more : ''))
      .then(function (d) {
        /* A country by its name beside its two letters, and a value a
           column shows in words with those words beside it (1.10.166). */
        var says = qValueWords(list, field);
        return (d.values || []).map(function (v) {
          if (field === 'country' && typeof countryWords === 'function') {
            return {val: v.val, n: v.n, note: countryWords(v.val), words: true};
          }
          var w = says ? says(v.val) : '';
          return w && String(w).toLowerCase() !== String(v.val).toLowerCase()
            ? {val: v.val, n: v.n, note: w, words: true} : v;
        });
      });
  };
}

/** How a column says a kept value, where it says it in words. */
function qValueWords(list, field) {
  if (list === 'win' && (field === 'what' || field === 'kind')) return winKindWords;
  if (list === 'win' && (field === 'logon' || field === 'logon_type')) return winLogonWords;
  if ((list === 'passed' || list === 'failed') && (field === 'door' || field === 'kind')) {
    return function (v) { return (DOOR_SAYS[v] || {}).words || ''; };
  }
  if (list === 'passed' && (field === 'how' || field === 'step')) return tokenWords;
  if (list === 'events' && field === 'kind') return eventKindWords;
  if (list === 'history' && field === 'how') return function (v) { return BAN_HOW[v] || ''; };
  return null;
}

/** The values one field holds in rows the page already has, most first. */
function qLocalValues(rows, valueOf, field, typed) {
  var count = {}, low = String(typed || '').toLowerCase();
  rows.forEach(function (r) {
    var v = valueOf(r, field);
    if (Array.isArray(v)) v = v[v.length - 1];       /* as it is shown */
    v = String(v || '').trim();
    if (!v || (low && v.toLowerCase().indexOf(low) < 0)) return;
    count[v] = (count[v] || 0) + 1;
  });
  return Object.keys(count).sort(function (a, b) {
    var sa = low && a.toLowerCase().indexOf(low) === 0, sb = low && b.toLowerCase().indexOf(low) === 0;
    if (sa !== sb) return sa ? -1 : 1;
    return count[b] - count[a] || (a < b ? -1 : 1);
  }).slice(0, 30).map(function (v) { return {val: v, n: count[v]}; });
}

function listView(opts) {
  /* opts: {key, rows, hay, draw, empty, per, host, sizes} where `hay` turns
     one row into the text its search box looks through, and `draw` turns one
     row into whatever it is drawn as. */
  var view = VIEWS[opts.key] || (VIEWS[opts.key] = {q: '', per: opts.per || 25, page: 0});
  var box = el('div', 'list-view');
  var bar = el('div', 'fold-bar');
  var find = el('input');
  find.type = 'search';
  find.placeholder = opts.placeholder || 'search this list\u2026';
  find.value = view.q;
  explain(find, opts.explain || ('Narrow this list as you type. It looks through what is '
    + 'drawn in the rows below — an address, a country, a name, a reason — and shows only '
    + 'the rows holding what you type. It searches the whole list, not only the page on '
    + 'show; empty it to see everything again.'));
  var per = el('select');
  (opts.sizes || [10, 25, 50, 100, 250]).forEach(function (x) {
    var o = document.createElement('option');
    o.value = String(x);
    o.textContent = x + ' a page';
    per.appendChild(o);
  });
  per.value = String(view.per);
  explain(per, 'How many to show at a time.');
  var found = el('span', 'found');
  bar.appendChild(find);
  bar.appendChild(per);
  /* Its columns are its fields: `why:password`, `country:CZ` (1.10.163). */
  var rowsAll = opts.rows || [];
  var qHeads = null, qRowOf = typeof Map === 'function' ? new Map() : null, qCell = null;
  function qHeadsNow() {
    if (qHeads) return qHeads;
    qHeads = [];
    if (!rowsAll.length) return qHeads;
    var probe = el('div');
    try { opts.draw(rowsAll.slice(0, 1), probe); } catch (e) { return qHeads; }
    var t = probe.querySelector('table');
    if (!t || !t.tHead || !t._cell) return qHeads;
    qCell = t._cell;
    var head = t.tHead.rows[t.tHead.rows.length - 1];
    var seen = {};
    Array.prototype.forEach.call(head.cells, function (th, at) {
      var words = String(colsLabel(th) || srcText(th) || '').replace(/[⇅▲▼]/g, '').trim();
      var name = qSlug(words);
      if (!name || seen[name] || th.colSpan > 1) return;
      seen[name] = true;
      qHeads.push({name: name, words: words, col: colOf(th, at)});
    });
    return qHeads;
  }
  function qValueOf(r, name) {
    var h = qHeadsNow().filter(function (x) { return x.name === name; })[0];
    if (!h || !qCell) return '';
    var tr = qRowOf ? qRowOf.get(r) : null;
    if (!tr) {
      try { tr = qCell(r, 0); } catch (e) { tr = null; }
      if (qRowOf && tr) qRowOf.set(r, tr);
    }
    var td = tr && tr.nodeType === 1 ? cellOf(tr, h.col) : null;
    if (!td) return '';
    var kept = String(srcText(td) || '').replace(/\s+/g, ' ').trim();
    var shown = String(td.textContent || '').replace(/\s+/g, ' ').trim();
    return shown && shown !== kept ? [kept, shown] : kept;
  }
  qSuggest(find, {
    fields: function () {
      return qHeadsNow().map(function (h) { return [h.name, h.words, '']; });
    },
    values: function (field, typed) {
      return qLocalValues(rowsAll, qValueOf, field, typed);
    }
  });
  /* Every list that knows what country its rows are in can be narrowed to
     one, by name rather than by two letters. It is the same picker the
     server-side pages use, so there is one way of asking the question
     wherever it is asked. */
  var pick = null;
  if (opts.countryOf) {
    var counts = {};
    (opts.rows || []).forEach(function (r) {
      var cc = String(opts.countryOf(r) || '').toUpperCase();
      if (cc) counts[cc] = (counts[cc] || 0) + 1;
    });
    pick = el('select');
    var any = document.createElement('option');
    any.value = '';
    any.textContent = 'every country';
    pick.appendChild(any);
    Object.keys(counts).sort().forEach(function (cc) {
      var o = document.createElement('option');
      o.value = cc;
      o.textContent = cc;
      pick.appendChild(o);
    });
    pick.value = view.cc || '';
    pick.onchange = function () {
      view.cc = pick.value;
      view.page = 0;
      paint();
    };
    bar.appendChild(pick);
    setTimeout(function () { asCountryPick(pick, counts); }, 0);
  }
  if (opts.extra) opts.extra.forEach(function (n) { bar.appendChild(n); });
  bar.appendChild(found);
  var body = el('div', 'list-body');
  var pager = el('div', 'fold-pager');
  box.appendChild(bar);
  box.appendChild(body);
  box.appendChild(pager);

  var rows = opts.rows || [];
  var hay = [];
  /* What each row is ordered by is read off it once per drawing of the list,
     and forgotten with it: new rows are new values. */
  var rowAt = typeof Map === 'function' ? new Map() : null;
  if (rowAt) rows.forEach(function (r, i) { rowAt.set(r, i); });
  view.sortCache = {};

  function text(i) {
    if (hay[i] === undefined) {
      hay[i] = String(opts.hay ? opts.hay(rows[i]) : JSON.stringify(rows[i])).toLowerCase();
    }
    return hay[i];
  }

  function paint() {
    var words = view.q.trim().toLowerCase().split(/\s+/).filter(Boolean);
    var only = String(view.cc || '').toUpperCase();
    var keep = [];
    var known = {};
    if (/[:~=<>]/.test(view.q)) {
      qHeadsNow().forEach(function (h) { known[h.name] = true; });
    }
    var parsed = qLocalParse(view.q, known);
    for (var i = 0; i < rows.length; i++) {
      if (only && String((opts.countryOf ? opts.countryOf(rows[i]) : '') || '').toUpperCase()
          !== only) { continue; }
      if (parsed) {
        var row_ = rows[i], at_ = i;
        if (qLocalTest(parsed, function (f) { return qValueOf(row_, f); },
                       function () { return text(at_); })) keep.push(row_);
        continue;
      }
      if (!words.length) { keep.push(rows[i]); continue; }
      var h = text(i);
      var all = true;
      for (var w = 0; w < words.length; w++) {
        if (h.indexOf(words[w]) < 0) { all = false; break; }
      }
      if (all) keep.push(rows[i]);
    }
    /* Ordered whole, before it is cut into pages: by the column pressed,
       read the way that column is drawn. */
    if (view.sort && view.cell) {
      var col = view.sort.col, cache = view.sortCache || (view.sortCache = {});
      var keyOf = function (r) {
        var at = rowAt ? rowAt.get(r) : rows.indexOf(r);
        var k = col + '/' + at;
        if (!(k in cache)) {
          var tr = view.cell(r, 0);
          cache[k] = cellSortValue(tr && tr.cells ? tr.cells[col] : null);
        }
        return cache[k];
      };
      keep = keep.map(function (r, i) { return {r: r, i: i, v: keyOf(r)}; });
      keep.sort(function (a, b) {
        var c = compareSortValues(a.v, b.v);
        if (c && view.sort.desc && a.v !== null && a.v !== '' && b.v !== null && b.v !== '') {
          c = -c;
        }
        return c || a.i - b.i;
      });
      keep = keep.map(function (k) { return k.r; });
    }
    var pages = Math.max(1, Math.ceil(keep.length / view.per));
    if (view.page >= pages) view.page = pages - 1;
    if (view.page < 0) view.page = 0;
    var from = view.page * view.per;
    var page = keep.slice(from, from + view.per);
    found.textContent = !rows.length ? ''
      : (keep.length > view.per
         ? num(from + 1) + '\u2013' + num(from + page.length) + ' of ' + num(keep.length)
         : (words.length ? num(keep.length) + ' of ' + num(rows.length)
            : num(keep.length) + ' shown'));
    bar.hidden = rows.length <= (opts.barFrom || 8) && !view.q && !view.cc;
    clear(body);
    if (!keep.length) {
      body.appendChild(el('div', 'fold-none', words.length
        ? ('Nothing here matches \u201c' + view.q.trim() + '\u201d'
           + (only ? ' in ' + countryWords(only) : ''))
        : (only ? 'Nothing here is in ' + countryWords(only)
           : (opts.empty || 'Nothing here'))));
    } else {
      opts.draw(page, body);
      var drawn = body.querySelector('table');
      if (drawn && drawn._cell && drawn.tHead) {
        view.cell = drawn._cell;
        drawn.dataset.listSort = '1';
        var head = drawn.tHead.rows[drawn.tHead.rows.length - 1];
        Array.prototype.forEach.call(head.cells, function (th, at) {
          var col = colOf(th, at);
          if (!String(th.textContent || '').trim() || th.colSpan > 1) return;
          sortMark(th, view.sort && view.sort.col === col
            ? (view.sort.desc ? 'desc' : 'asc') : 'none');
          var press = function () {
            view.sort = view.sort && view.sort.col === col
              ? {col: col, desc: !view.sort.desc}
              : {col: col, desc: sortsDownFirst(drawn, col)};
            view.page = 0;
            paint();
          };
          th.onclick = press;
          th.onkeydown = function (e) {
            if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); press(); }
          };
        });
      }
    }
    clear(pager);
    if (pages > 1) {
      var step = function (label, icon, to, on) {
        var b = cmdButton(label, icon, 'small');
        b.disabled = !on;
        explain(b, pageSays(label, view.page, pages));
        b.onclick = function (e) { e.preventDefault(); view.page = to; paint(); };
        return b;
      };
      pager.appendChild(step('First', 'first', 0, view.page > 0));
      pager.appendChild(step('Back', 'prev', view.page - 1, view.page > 0));
      pager.appendChild(explain(el('span', 'muted',
        'page ' + (view.page + 1) + ' of ' + pages),
        'Which page of this list is on show, and how many there are. How many rows go on a '
        + 'page is set in the box above; searching narrows the list first, so the number of '
        + 'pages changes as you type.'));
      pager.appendChild(step('Next', 'next', view.page + 1, view.page < pages - 1));
      pager.appendChild(step('Last', 'last', pages - 1, view.page < pages - 1));
    }
    explainWhatWasDrawn(box);
  }

  find.addEventListener('input', debounce(function () {
    view.q = find.value;
    view.page = 0;
    paint();
  }, 180));
  per.onchange = function () {
    view.per = Number(per.value) || 25;
    view.page = 0;
    paint();
  };
  paint();
  return box;
}

/* A table built from an array, for the lists that are tables. */
/** What a paging button does, said once for all of the lists that draw their
    own. They are drawn as their icons, so what they are has to be said
    somewhere, and a bare arrow with no explanation is the commonest thing on
    a page for somebody to have to guess at. */
function pageSays(label, page, pages) {
  var where = ' You are on page ' + (page + 1) + ' of ' + pages + '.';
  if (label === 'First' || label === 'Newest') {
    return 'Back to the first page of this list.' + where;
  }
  if (label === 'Back') return 'The page before this one.' + where;
  if (label === 'On' || label === 'Next') return 'The next page of this list.' + where;
  return 'The last page of this list.' + where;
}

/** Headers into cells: words, or {words, cls} for a column that is not drawn
    flush left, or an array of either for a run of columns that belong
    together - an address, its name, its flag - handed in as one so that the
    headers and the cells can never drift apart. */
function headCells(headers) {
  var flat = [];
  (headers || []).forEach(function (h) {
    if (Array.isArray(h)) { flat.push.apply(flat, h); } else { flat.push(h); }
  });
  return flat.map(function (h) {
    return h && h.cls ? el('th', h.cls, h.words || '') : el('th', '', h);
  });
}

/* ==========================================================================
   Ordering any list by its headings
   --------------------------------------------------------------------------
   Every table with headings can be ordered by pressing one: once for that
   column, again for the other way round. Three kinds of list, one way of
   pressing:

   * the long lists the server pages through - the refusals, the logins,
     the domain's events, the ban history, the daemon's own events and the
     traffic - are ordered BY THE SERVER, over every row that matches and
     not only the page on show (`serverSortHeads`);
   * a list the page holds whole and pages itself (`listView`) is ordered
     whole, before it is cut into pages;
   * every other table is ordered where it stands, and stays ordered when
     it is drawn again a moment later.
   ========================================================================== */
var SORT_ARROW = {none: '⇅', desc: '▼', asc: '▲'};

function sortMark(th, state) {
  var on = state === 'desc' || state === 'asc';
  var arrow = SORT_ARROW[state] || SORT_ARROW.none;
  var aria = state === 'desc' ? 'descending' : (state === 'asc' ? 'ascending' : 'none');
  var old = th.querySelector(':scope > .t-sort');
  /* Nothing touched where nothing changed. Taken off and put back every
     time, the arrow was a change to the page, the sweep that names what
     was drawn woke up for it and marked the headings again - eight times a
     second, on every tab, for as long as the page was open. */
  if (old && old === th.lastElementChild && old.textContent === arrow
      && old.classList.contains('on') === on) {
    if (th.getAttribute('aria-sort') !== aria) th.setAttribute('aria-sort', aria);
    if (!th.classList.contains('t-sortable')) th.classList.add('t-sortable');
    if (!th.hasAttribute('tabindex')) th.setAttribute('tabindex', '0');
    return;
  }
  if (old) old.remove();
  th.appendChild(el('span', 't-sort' + (on ? ' on' : ''), arrow));
  th.setAttribute('aria-sort', aria);
  th.classList.add('t-sortable');
  if (!th.hasAttribute('tabindex')) th.setAttribute('tabindex', '0');
}

/** The value a cell is ordered by: its moment, a size, a number, an
    address, or its words - in that order of preference. */
/* Counts, sizes and times read best biggest and newest first, so the first
   press on such a heading orders them that way - as the headings the daemon
   orders already do. Words and addresses start from the top of the alphabet.
   (1.10.160) */
function sortsDownFirst(table, col) {
  var body = table && table.tBodies && table.tBodies[0];
  if (!body) return false;
  var looked = 0;
  for (var i = 0; i < body.rows.length && looked < 12; i++) {
    var tr = body.rows[i];
    if (tr.classList.contains('sub') || tr.classList.contains('detailrow')) continue;
    var td = cellOf(tr, col);
    if (!td) continue;
    if (td.dataset && td.dataset.ts) return true;
    var t = String(srcText(td) || '').trim();
