  var out = [];
  var names = [];
  Array.prototype.forEach.call(($(prefix + '-picks') || {children: []}).children,
    function (box) {
      names.push(box.dataset.pick);
      if (box.value) out.push('pick_' + box.dataset.pick + '=' + encodeURIComponent(box.value));
    });
  if (names.length) out.push('picks=' + names.join(','));
  return out;
}

/** The choices, out of what is behind the door. A choice that is no longer
    among them - a port of the switch that was just un-picked - is let go,
    and the list is asked for again without it. */
function fillPicks(prefix, d, again) {
  var dropped = false;
  Array.prototype.forEach.call(($(prefix + '-picks') || {children: []}).children,
    function (box) {
      var pairs = ((d && d.picks) || {})[box.dataset.pick];
      if (!Array.isArray(pairs)) return;
      /* By what was written, not what is shown: translated, the shown
         words never matched and the list was drawn again every poll. */
      var have = Array.prototype.slice.call(box.options, 1).map(function (o) {
        return o.value + '\u0000' + (o.dataset.label !== undefined ? o.dataset.label
                                                                   : o.textContent);
      });
      var want = pairs.map(function (p) { return p[0] + '\u0000' + p[1]; });
      if (String(have) === String(want)) return;
      var was = box.value;
      while (box.options.length > 1) box.remove(1);
      pairs.forEach(function (p) {
        var o = document.createElement('option');
        o.value = p[0];
        o.textContent = p[1];
        o.dataset.label = p[1];
        o.setAttribute('data-no-i18n', '');        /* a name, never words to translate */
        box.appendChild(o);
      });
      /* An empty answer is the list still being worked out behind the
         request, not a list with nothing in it: the choice stays. */
      if (!pairs.length && was) {
        var keep = document.createElement('option');
        keep.value = was;
        keep.textContent = was;
        box.appendChild(keep);
      }
      box.value = was;
      if (was && box.value !== was) dropped = true;
    });
  if (dropped && again) again();
}

function clearPicks(prefix) {
  Array.prototype.forEach.call(($(prefix + '-picks') || {children: []}).children,
    function (box) { box.value = ''; });
}

function showFailedKind(kind) {
  FKIND = doorToShow(DOOR_SAYS[kind] ? kind : 'vpn');
  drawDoors($('f-kinds'), FCOUNTS, FKIND, showFailedKind, FDOORS);
  $('f-note').textContent = FAILED_NOTES[FKIND] || FAILED_NOTES.other;
  $('f-note').classList.remove('open');
  $('f-note').dataset.cuts = '';
  $('f-q').placeholder = FKIND === 'domain'
    ? 'an account, a machine, an address\u2026'
    : isNetworkKind(FKIND)
    ? 'a MAC, an address, a name\u2026'
    : (isShellKind(FKIND) ? 'an address, a name, a reason\u2026'
       : (FKIND === 'otp' ? 'a name, or what it said\u2026'
          : (FKIND === 'eduroam' ? 'a name, an institution, a MAC\u2026'
             : 'an address, a name, a reason\u2026')));
  PAGE.failed = 0;
  sortReset(SORTS.failed);
  holdTheTallOnes();
  if (TAB === 'failed') writeHash();
  return loadFailed();
}

function loadFailed() {
  /* Opened on a door whose module is off - which is every first visit on a
     site that reads no ISE, because the list opens on the VPN - and it moves
     to one that is on, notes, search box and all, rather than drawing an
     empty list under a door that is not there. */
  if (doorToShow(FKIND) !== FKIND) return showFailedKind(FKIND);
  var domain = FKIND === 'domain';
  /* The columns change for this one door, because what is behind it is a
     different system - but the card does not. Same table, same search box,
     same pager: a tab that brings its own search box and its own pager with
     it is two of each on one card, and two scrollbars with them. */
  fitFilters('f', FKIND);
  drawPicks('f', domain ? '' : FKIND);
  if (domain) return loadFailedDomain();
  var per = Number($('f-limit').value || 100);
  var q = [
    'limit=' + per, 'offset=' + (PAGE.failed * per), 'kind=' + FKIND, sortArgs(SORTS.failed),
    windowArgs('f-hours'),
    $('f-q').value.trim() ? 'q=' + encodeURIComponent(qRewrite($('f-q').value.trim(),
                                                               qMaps('failed', FKIND))) : '',
    $('f-device').value ? 'device=' + encodeURIComponent($('f-device').value) : '',
    $('f-server').value ? 'server=' + encodeURIComponent($('f-server').value) : '',
    $('f-country').value ? 'country=' + encodeURIComponent($('f-country').value) : ''
  ].concat(pickArgs('f')).filter(Boolean).join('&');
  /* Which question this answer belongs to. Two doors pressed quickly are
     two requests, and the slower one used to land last and be drawn with
     the newer door's columns and row shape - an attacker's address under a
     heading that says it is the token server's own. */
  var mine = (FASKED = (FASKED || 0) + 1);
  var asked = FKIND;
  /* Handed back, so that whoever sent somebody here can wait for the rows
     to exist before looking for one of them. */
  return api('failed&' + q, undefined, {lane: 'failed'}).then(function (d) {
    if (mine !== FASKED || asked !== FKIND) return;
    noteBanned(d);
    fillOnce($('f-device'), d.devices);
    fillOnce($('f-server'), d.servers);
    fillOnce($('f-country'), d.countries);
    asCountryPick($('f-country'), d.country_counts);
    fillPicks('f', d, function () { PAGE.failed = 0; loadFailed(); });
    if (d.counts && (countsAreReal(d) || !Object.keys(FCOUNTS).length)) {
      FCOUNTS = d.counts;
      FDOORS = d.doors || d.counts;
      drawDoors($('f-kinds'), FCOUNTS, FKIND, showFailedKind, FDOORS);
      /* The counts behind those tabs are worked out behind whoever asked,
         so the first page drawn after a restart can arrive before they are
         ready - and a tab with no number, or a door missing entirely, is
         not something anybody would think to reload. Asked again once,
         quietly, which is all it takes. */
      askAgainForCounts(d, 'failed', function (counts) {
        FCOUNTS = counts;
        FDOORS = counts;
        drawDoors($('f-kinds'), FCOUNTS, FKIND, showFailedKind, FDOORS);
      });
    }
    sayHowMany($('failed-count'), d);
    var head = $('f-head');
    clear(head);
    headCells(isWifiKind(FKIND) ? FHEADS.wifi
              : (isNetworkKind(FKIND) ? FHEADS.network
                 : (FHEADS[FKIND] || FHEADS.plain)))
      .forEach(function (th) { head.appendChild(th); });
    serverSortHeads(head, SORTS.failed, authSortKeys(FKIND), function () {
      PAGE.failed = 0;
      loadFailed();
    });
    var body = $('f-table').querySelector('tbody');
    clear(body);
    $('f-empty').hidden = !!d.rows.length;
    if (!d.rows.length) {
      sayWhyEmpty('f-empty', FKIND, FCOUNTS, FDOORS, $('f-hours').value, function () {
        $('f-hours').value = '0';
        PAGE.failed = 0;
        loadFailed();
      });
    }
    d.rows.forEach(function (r) {
      var tr = el('tr');
      tr._rec = r;
      /* Which record this row is. Nothing on the page needed it until
         something could send somebody to one particular row and make it
         stand out; the click already knew, but only inside its own closure. */
      tr.dataset.session = r.session || '';
      opensWith(tr, '', function () { showRecord('failed', r.session); });
      if (isNetworkKind(FKIND)) {
        networkRow(tr, r, FKIND, false);
        body.appendChild(tr);
        return;
      }
      if (FKIND === 'otp') {
        tokenRow(tr, r, false);
        body.appendChild(tr);
        return;
      }
      if (FKIND === 'eduroam') {
        eduroamRow(tr, r, false);
        body.appendChild(tr);
        return;
      }
      if (FKIND === 'tacplus') {
        tacplusRow(tr, r);
        body.appendChild(tr);
        return;
      }
      tr.appendChild(stampCell(r.ts));
      addrPlaceCountry(tr, r.ip, r.country, FKIND === 'tacacs', r.ts);
      var user = el('td');
      user.appendChild(el('span', 'mono', r.username || '–'));
      whoIsIt(user, r.username, r.realm);
      tr.appendChild(user);
      var why = el('td');
      why.appendChild(el('span', '', r.reason || ''));
      if (r.code) {
        var code = el('span', 'muted small', ' ' + r.code);
        why.appendChild(code);
      }
      tr.appendChild(why);
      if (FKIND === 'vpn') tr.appendChild(machineCell(r.machine));
      tr.appendChild(el('td', '', r.tunnel || '–'));
      tr.appendChild(deviceCell(r));
      tr.appendChild(el('td', '', r.server || '–'));
      banOnto(tr, r.ip, 'banned from the failed attempts', loadFailed);
      body.appendChild(tr);
    });
    optColumns($('f-table'), OPT_AUTH);
    holdTheTallOnes();
    pager('f-pager', PAGE.failed, per, d.total, function (page) {
      PAGE.failed = page;
      loadFailed();
    }, d.capped);
    explainWhatWasDrawn($('tab-failed'));
  }).catch(oops);
}

/* Two lists, not one. A VPN login and somebody typing `enable` on a switch
   have almost nothing in common - not the columns worth showing, not the
   questions asked of them - and the rows of one drown the other: on a busy
   day one person's session on a switch writes forty Authorization records.
   The tabs also keep the downloadable ACLs out of both, which is where they
   belong: they are shown inside the login they were handed down for. */
var PKIND = 'vpn';
var PCOUNTS = {};
var FCOUNTS = {};
/* ...and how many each door holds over all time, which is what decides
   whether the door is drawn and what an empty list is measured against. */
var PDOORS = {};
var FDOORS = {};
/** Whether an answer's counts are the real ones.

    They are worked out behind whoever asked, and the first page after a
    restart - which is the same moment the reader is writing thousands of
    records - can arrive before they are ready. The daemon says so; older
    ones did not, so all-noughts over rows that exist counts as well. */
function countsAreReal(d) {
  if (!d || !d.counts) return false;
  if (d.counts_ready === false) return false;
  var any = Object.keys(d.counts).some(function (k) { return Number(d.counts[k]) > 0; });
  return any || !Number(d.total || 0);
}
/** Keep asking, backing off, until they are. */
var COUNTS_AGAIN = {};
function askAgainForCounts(d, what, then, tries) {
  tries = tries || 0;
  /* Given up on, or answered: either way this stops and may start again
     the next time the page is drawn. Left set, it shut the asking off for
     the rest of the browser's life. */
  if (countsAreReal(d) || tries > 5) { COUNTS_AGAIN[what] = 0; return; }
  if (!tries && COUNTS_AGAIN[what]) return;       // one chain at a time
  COUNTS_AGAIN[what] = tries + 1;
  setTimeout(function () {
    /* Nobody is looking at that list any more: this is about the numbers on
       its tabs, and it can wait until somebody is. */
    if (TAB !== (what === 'failed' ? 'failed' : 'logins')) {
      COUNTS_AGAIN[what] = 0;
      return;
    }
    /* ...over the window the list is showing. Asked without it, the tabs
       of a list of the last 24 hours were given counts of everything ever
       read - the very thing the counts are narrowed to the window to
       avoid. */
    var hours = windowArgs(what === 'failed' ? 'f-hours' : 'p-hours');
    api(what + '&limit=1' + (hours ? '&' + hours : ''))
      .then(function (fresh) {
      if (countsAreReal(fresh)) {
        COUNTS_AGAIN[what] = 0;
        then(fresh.counts);
        return;
      }
      askAgainForCounts(fresh, what, then, tries + 1);
    }).catch(function () { COUNTS_AGAIN[what] = 0; });
  }, 1200 + tries * 2500);
}
/* One line under the buttons, saying what this list is. Written out per door
