];
var DOOR_SAYS = {};
DOORS.forEach(function (d) { DOOR_SAYS[d.kind] = d; });
var NETWORK_KINDS = ['dot1x-lan', 'dot1x-wifi', 'mab-lan', 'mab-wifi',
                     'nps-dot1x-lan', 'nps-dot1x-wifi', 'nps-mab-lan', 'nps-mab-wifi',
                     'radius-dot1x-lan', 'radius-dot1x-wifi', 'radius-mab-lan',
                     'radius-mab-wifi'];
/* Whether a kind is one a Windows NPS answered rather than ISE. */
function isNpsKind(kind) { return String(kind || '').indexOf('nps-') === 0; }
/* ...or a FreeRADIUS of the site's own (1.10.203). */
function isRadiusKind(kind) { return String(kind || '').indexOf('radius-') === 0; }

function isNetworkKind(kind) { return NETWORK_KINDS.indexOf(kind) >= 0; }
/* Somebody at a switch prompt, whichever daemon answered. The two are kept
   apart everywhere a row is counted or filed - they are two systems - and
   drawn the same everywhere a row is READ, because what somebody wants from
   both is the same: who sat down where, coming from where, and what they
   then ran. */
function isShellKind(kind) { return kind === 'tacacs' || kind === 'tacplus'; }
function isWifiKind(kind) {
  return kind === 'dot1x-wifi' || kind === 'mab-wifi'
    || kind === 'nps-dot1x-wifi' || kind === 'nps-mab-wifi'
    || kind === 'radius-dot1x-wifi' || kind === 'radius-mab-wifi';
}

/** The buttons along the top of a list, one per door that has anything in
    it. A door with nothing behind it is not drawn - on a VPN-only
    installation there is no wireless and never was - but the one being
    looked at always is, so pressing it does not make it vanish. */
/** Why a list is empty, where the page can tell.

    "Nothing matches" under a tab whose number is not nought is the page
    keeping a secret it knows: the records are there, they are simply older
    than the window somebody chose, or behind a filter they forgot. */
function sayWhyEmpty(where, kind, counts, doors, hours, note) {
  var box = $(where);
  if (!box) return;
  clear(box);
  var ever = Number((doors || {})[kind] || 0);
  var here = Number((counts || {})[kind] || 0);
  /* The window is the reason only when the window really holds nothing.
     Where it holds something and the page is still empty, what is hiding
     them is the search or the filters - and saying "widen the window" then
     sends somebody to a page that is just as empty. */
  if (!here && ever && String(hours) !== '0') {
    box.appendChild(document.createTextNode('Nothing in this window. '));
    var said = el('span', '', 'This door holds ' + num(ever) + ' in all. ');
    box.appendChild(said);
    var wider = el('button', 'btn small', 'look at everything');
    wider.onclick = function () { note(); };
    box.appendChild(wider);
    return;
  }
  box.appendChild(document.createTextNode(
    ever ? 'Nothing matches. This door holds ' + num(ever)
           + ' \u2014 the search or the filters beside it are keeping them out.'
         : 'Nothing here yet.'));
}

/* The doors that are ISE's own. They have no switch of their own - they are
   what ISE writes - so they follow the one that says whether ISE is read at
   all. A site whose switches answer to a tac_plus of its own and which reads
   no ISE whatever was shown VPN and TACACS on both lists anyway, and opened
   on the VPN one: an empty list, under a door to a system it does not have. */
var DOORS_SEEN = null;
var ISE_DOORS = ['vpn', 'tacacs', 'dot1x-lan', 'dot1x-wifi', 'mab-lan', 'mab-wifi',
                 'other'];

/** Whether a door's module is switched off, as far as the daemon has said.

    Nothing is hidden before the daemon has said anything at all: a page that
    has not heard yet keeps drawing what it always drew, rather than hiding
    the VPN from a site that reads it for the second the first answer takes. */
function doorSwitchedOff(kind) {
  var s = STATUS;
  if (!s) return false;
  if (ISE_DOORS.indexOf(kind) >= 0) return s.ise_on === false;
  if (kind === 'tacplus') return !s.tacplus_on;
  if (isNpsKind(kind)) return !s.nps_on;
  if (isRadiusKind(kind)) return !s.radius_on;
  if (kind === 'domain') return !s.winsec_on;
  if (kind === 'otp') return s.otp_on === false;
  if (kind === 'eduroam') return s.eduroam_on === false;
  return false;
}

/** The door a list should be on: the one asked for, unless its module is
    switched off - then the first door that is on. Where nothing at all is,
    the one asked for, so that the page still says something. */
function doorToShow(kind) {
  if (!doorSwitchedOff(kind)) return kind;
  for (var i = 0; i < DOORS.length; i += 1) {
    if (!doorSwitchedOff(DOORS[i].kind)
        && ISE_DOORS.indexOf(DOORS[i].kind) < 0) return DOORS[i].kind;
  }
  return kind;
}

function drawDoors(host, counts, now, go, have) {
  clear(host);
  /* `counts` is the window the list is showing and is what the number on
     the tab says. `have` is everything ever, and decides which tabs exist
     at all: a door that vanished because nothing came through it in the
     last hour is a door nobody can find, and its records are still there. */
  var ever = have || counts || {};
  DOORS.forEach(function (d) {
    var many = Number((counts || {})[d.kind] || 0);
    /* A module switched off offers no door, on either list - whatever it
       left behind in the database. Its records are still there: the box that
       finds anything finds them, and switching it back on shows them again.
       The one being looked at stays, where nothing else is on at all. */
    if (doorSwitchedOff(d.kind) && !(d.kind === now && doorToShow(now) === now)) return;
    /* The domain is offered whenever its logs are read, and never otherwise:
       it has no count in these tallies because it is not made of them. */
    if (d.kind === 'tacplus') {
      /* Offered whenever its logs are read, whether or not anything came
         through it today - and never when they are not. Its own count is
         used, because a site that has just switched it on has a window
         with nothing in it and a door with five years behind it. */
      if (!(STATUS || {}).tacplus_on) return;
    } else if (d.kind === 'domain') {
      /* On both lists now: a refusal at the domain and a sign-in at the
         domain are both worth a tab, and both are counted by the daemon
         rather than out of this page's tallies - the domain is a different
         system and none of it is ever judged here. */
      if (!(STATUS || {}).winsec_on) return;
      many = Number((((STATUS || {}).winsec_counts) || {})[
        host.id === 'p-kinds' ? 'passed' : 'failed'] || 0);
    } else if (!many && !Number(ever[d.kind] || 0)
        && d.kind !== now && d.kind !== 'vpn' && d.kind !== 'tacacs') return;
    /* ...and ISE's own two are offered whenever ISE is read, quiet or not,
       which is what the line above says and still says. */
    var b = document.createElement('button');
    b.dataset.kind = d.kind;
    b.dataset.icon = d.icon;
    b.className = d.kind === now ? 'on' : '';
    b.setAttribute('aria-selected', d.kind === now ? 'true' : 'false');
    b.appendChild(document.createTextNode(d.words));
    explain(b, d.says);
    b.onclick = function () { go(d.kind); };
    host.appendChild(b);
    /* The icon is put on from the words, and the count goes on after it -
       the other way round and the count ends up inside the label and is
       drawn twice, which reads as a number nobody can explain. */
    dressButtons(host);
    b.appendChild(el('span', 'n', many ? num(many) : ''));
  });
}

/* The refusals have two shapes as well: one about somebody at a door with
   an address, and one about a machine on a socket. */
var FHEADS = {
  plain: ['When', addrHeads(), 'Name', 'Why it failed', 'Tunnel', 'Device', 'Node',
