  'nps-other': ['When', addrHeads(), 'Name', 'Why it failed', 'Tunnel', 'Device', 'Server',
                {words: '', cls: 'mark'}, {words: '', cls: 'act'}, {words: '', cls: 'act'}],
  otp: ['When', 'Name', {words: 'Why it was refused', cls: 'placecell'},
        {words: '', cls: 'placecell'},
        {words: 'Where from', cls: 'addrcell'}, {words: '', cls: 'cccell'},
        {words: 'The machine', cls: 'placecell'},
        {words: 'VPN group', cls: 'placecell'},
        {words: 'The box that asked', cls: 'addrcell'}, {words: '', cls: 'placecell'},
        'Token server'],
  eduroam: ['When', 'Name', 'Institution', 'Why it was refused', 'Endpoint',
            'Controller', 'Server']
};
var PHEADS = {
  vpn: ['When', 'Name', addrHeads(), {words: 'The machine', cls: 'placecell'},
        'Profile', 'Device', 'Tunnel', 'Firewall', 'Node', ''],
  tacacs: ['When', 'Name', addrHeads('From'), 'Device', 'Commands', 'Shell profile', 'Policy',
           'Node', ''],
  /* The same columns TACACS+ has, because it is the same question asked of
