  tacplus: ['When', 'Name', addrHeads('From'), 'Device', 'Commands', 'Privilege',
            'Service', 'Server', ''],
  network: ['When', 'Endpoint', 'Address', 'Name', 'Switch', 'Port', 'Profile', 'VLAN',
            'Node'],
  wifi: ['When', 'Endpoint', 'Address', 'Name', 'Controller', 'Access point', 'Network',
         'Profile', 'VLAN', 'Node'],
  otp: ['When', 'Name', {words: 'How it was accepted', cls: 'placecell'},
        {words: '', cls: 'placecell'},
        'The whole account',
        {words: 'Where from', cls: 'addrcell'}, {words: '', cls: 'cccell'},
        {words: 'The machine', cls: 'placecell'},
        {words: 'VPN group', cls: 'placecell'},
        {words: 'The box that asked', cls: 'addrcell'}, {words: '', cls: 'placecell'},
        'Token server'],
  eduroam: ['When', 'Name', 'Institution', 'Endpoint', 'Address', 'Access point',
            'Network', 'VLAN', 'Controller', 'Server'],
  /* Tunnel and Firewall as well: the row drawn for these doors carries
     both (it is the VPN's row without the machine), and without their
     headings every row ran two cells past the end of the heading. */
  other: ['When', 'Name', addrHeads(), 'Profile', 'Device', 'Tunnel', 'Firewall', 'Node', ''],
  /* NPS's own, drawn by the same row as the VPN's: the network policy that
     let them in stands where ISE's authorisation profile does. */
  'nps-vpn': ['When', 'Name', addrHeads(), 'Policy', 'Device', 'Tunnel', 'Firewall',
              'Server', ''],
  'nps-other': ['When', 'Name', addrHeads(), 'Policy', 'Device', 'Tunnel', 'Firewall',
                'Server', '']
};
/* A FreeRADIUS of the site's own (1.10.203): drawn as NPS's are. */
FHEADS['radius-vpn'] = FHEADS['nps-vpn'];
FHEADS['radius-other'] = FHEADS['nps-other'];
PHEADS['radius-vpn'] = PHEADS['nps-vpn'];
PHEADS['radius-other'] = PHEADS['nps-other'];
function headsFor(kind) {
  if (isWifiKind(kind)) return PHEADS.wifi;
  if (isNetworkKind(kind)) return PHEADS.network;
  return PHEADS[kind] || PHEADS.other;
}
function passedTab(kind) {
  PKIND = doorToShow(DOOR_SAYS[kind] ? kind : 'vpn');
  drawDoors($('p-kinds'), PCOUNTS, PKIND, passedTab, PDOORS);
  $('p-note').textContent = LOGIN_NOTES[PKIND] || LOGIN_NOTES.other;
  $('p-note').classList.remove('open');
  $('p-note').dataset.cuts = '';
  $('p-q').placeholder = PKIND === 'domain'
    ? 'an account, a machine, an address\u2026'
    : isNetworkKind(PKIND)
    ? 'a MAC, an address, a name\u2026'
    : (PKIND === 'vpn' ? 'a name, an address, a profile\u2026'
       : (PKIND === 'otp' ? 'a name, or what it said\u2026'
          : (PKIND === 'eduroam' ? 'a name, an institution, a MAC\u2026'
             : 'a name, a switch, a shell profile\u2026')));
  /* The ACLs belong to the VPN half: a sign-in to a switch is not handed
     one, and a card about them under that list would be a card about
     nothing. */
  /* The access lists belong to the VPN half: a sign-in to a switch is not
     handed one. Behind a button now rather than in a card of its own, so
     the logins are alone on this page and may take the window. */
  $('acls-bar').hidden = PKIND !== 'vpn';
  if (TAB === 'logins') writeHash();
  PAGE.passed = 0;
  sortReset(SORTS.passed);
  /* The access lists come and go with the door, and whether this card is
     alone on its page goes with them: alone, it may take the window. */
