/** Which downloadable ACLs the logins were given, and whether the rules are
    here to be read.

    It exists because of a question this page could not answer: a login says
    which firewall it was handed, opens, and shows no rules. Nothing is
    broken - the device downloads an ACL only when it does not already hold
    it, so the one the busiest group uses all day may have been fetched once
    long before these logs and never again. Said out loud in a list, with how
    many logins are waiting on each, it stops being a puzzle. */
/* The access lists, kept for the button that opens them. They were a second
   card under the logins, and a second card is what stopped the logins taking
   the window: the head, the filters and the pager of a hundred thousand rows
   are worth more than a table nobody had scrolled to. */
var ACLS = null;

function loadAcls() {
  api('acls').then(function (d) {
    ACLS = d;
    var rows = d.acls || [];
    $('acls-bar').hidden = PKIND !== 'vpn';
    $('acls-count').textContent = rows.length ? num(rows.length) : '';
    $('acls-open').disabled = !rows.length;
  }).catch(function () { /* the page is still the page without them */ });
}

function drawAcls(host, d) {
    clear(host);
    var rows = (d && d.acls) || [];
    if (!rows.length) {
      host.appendChild(el('p', 'note', 'No login here has been handed a downloadable ACL '
        + 'yet.'));
      return;
    }
    if (d.waiting) {
      var said = el('p', 'btnhelp');
      said.innerHTML = '<b>' + num(d.waiting) + '</b> of these have not been downloaded '
        + 'while these logs have been read, so the <b>' + num(d.logins_waiting)
        + '</b> login(s) that were handed them show no rules. That is the device not '
        + 'needing to fetch what it already holds — it appears the next time it has '
        + 'to, which an edit to the ACL on ISE brings about at once.';
      host.appendChild(said);
    }
    host.appendChild(listView({
      key: 'acls', rows: rows, per: 25, barFrom: 8,
      placeholder: 'a name\u2026',
      empty: 'Nothing here',
      hay: function (r) { return [r.short, r.acl, r.downloaded ? 'read known' : 'waiting']
        .join(' '); },
      draw: function (page, into) {
        into.appendChild(listTable(
          ['Access list', {words: 'Logins', cls: 'num'}, {words: 'Rules', cls: 'num'},
           'Last downloaded', 'Its rules'], page,
          function (r) {
            var tr = el('tr');
            var name = el('td');
            name.appendChild(el('span', 'mono', r.short));
            explain(name, 'ISE calls it <code>' + r.acl + '</code>. '
              + 'The characters on the end are its version: edit the ACL and they change, '
              + 'so the same list under two names is the same list before and after an edit.');
            tr.appendChild(name);
            tr.appendChild(el('td', 'num', num(r.logins)));
            tr.appendChild(el('td', 'num', r.downloaded
              ? num(r.rules) + (r.rules ? ' \u00b7 ' + num(r.permits) + ' permit \u00b7 '
                 + num(r.denies) + ' deny' : '') : '\u2013'));
            tr.appendChild(r.downloaded ? stampCell(r.downloaded, 'dim')
                           : el('td', 'dim', 'not while these logs have been read'));
            var state = el('td');
            if (r.downloaded) {
              state.appendChild(el('span', 'tag ok', 'read from the log'));
            } else {
              var wait = el('span', 'tag warn', 'not downloaded here');
              explain(wait, 'The logins say they were handed this one, but no device has '
                + 'downloaded it while these logs have been read — so its rules cannot '
                + 'be shown under them.<br><br>A device fetches an ACL only when it does not '
                + 'already hold it: this one it has held throughout. It will appear after a '
                + 'reload of the device, after its cache drops it, or as soon as the ACL is '
                + 'edited on ISE, which changes its name and forces a fresh download.');
              state.appendChild(wait);
            }
            tr.appendChild(state);
            return tr;
          }, 'plain'));
      }
    }));
    explainWhatWasDrawn(host);
}

/** Every downloadable ACL the logins were given, in a popup of its own. */
function peekAcls() {
  peek('The firewalls handed down',
    function () { return ACLS ? Promise.resolve(ACLS) : api('acls'); },
    function (body, d) {
      ACLS = d;
      body.appendChild(el('p', 'note', 'Every downloadable ACL the logins were given, and '
        + 'whether its rules can be read here.'));
      var host = el('div');
      body.appendChild(host);
      drawAcls(host, d);
    });
}

var P_DOMAIN_ASKED = 0;

/** The domain's own successful sign-ins, on the page where somebody asks.

    Drawn into this page's own table with this page's own search and pager,
    for the reason the refusals are: a tab that brings a second search box
    and a second pager with it is two of each on one card. */
function loadPassedDomain() {
  var mine = ++P_DOMAIN_ASKED;
  var per = Number($('p-limit').value || 100);
  var hours = windowArgs('p-hours');
  var q = qRewrite($('p-q').value.trim(), qMaps('win'));
  var ask = 'win-events&kind=logon,kerberos,ntlm,explicit&choices=0'
    + '&limit=' + per + '&offset=' + (PAGE.passed * per)
    + (sortArgs(SORTS.passed) ? '&' + sortArgs(SORTS.passed) : '')
    + (hours ? '&' + hours : '')
    + (q ? '&q=' + encodeURIComponent(q) : '');
  return api(ask, undefined, {lane: 'passed'}).then(function (d) {
    if (mine !== P_DOMAIN_ASKED || PKIND !== 'domain') return;
    sayHowMany($('passed-count'), d);
    winRowsInto($('p-head'), $('p-table'), $('p-empty'), d.rows || []);
    serverSortHeads($('p-head'), SORTS.passed, WIN_SORT_KEYS, function () {
      PAGE.passed = 0;
      loadPassedDomain();
    });
    pager('p-pager', PAGE.passed, per, d.total, function (page) {
      PAGE.passed = page;
      loadPassedDomain();
    }, d.capped);
    nameTheMakers($('p-table'));
    explainWhatWasDrawn($('p-table'));
    holdTheTallOnes();
  }).catch(oops);
}

function loadPassed() {
  if (doorToShow(PKIND) !== PKIND) return passedTab(PKIND);
  fitFilters('p', PKIND);
  drawPicks('p', PKIND === 'domain' ? '' : PKIND);
  if (PKIND === 'domain') return loadPassedDomain();
  var per = Number($('p-limit').value || 100);
  var q = [
    'limit=' + per, 'offset=' + (PAGE.passed * per), 'kind=' + PKIND, sortArgs(SORTS.passed),
    windowArgs('p-hours'),
    $('p-q').value.trim() ? 'q=' + encodeURIComponent(qRewrite($('p-q').value.trim(),
                                                               qMaps('passed', PKIND))) : '',
    $('p-device').value ? 'device=' + encodeURIComponent($('p-device').value) : '',
    $('p-server').value ? 'server=' + encodeURIComponent($('p-server').value) : '',
    $('p-country').value ? 'country=' + encodeURIComponent($('p-country').value) : ''
  ].concat(pickArgs('p')).filter(Boolean).join('&');
  var mine = (PASKED = (PASKED || 0) + 1);
  var asked = PKIND;
  return api('passed&' + q, undefined, {lane: 'passed'}).then(function (d) {
    if (mine !== PASKED || asked !== PKIND) return;
    noteBanned(d);
    fillOnce($('p-device'), d.devices);
    fillOnce($('p-server'), d.servers);
    fillOnce($('p-country'), d.countries);
    asCountryPick($('p-country'), d.country_counts);
    fillPicks('p', d, function () { PAGE.passed = 0; loadPassed(); });
    sayHowMany($('passed-count'), d);
    CMDCOUNT = d.commands || {};
    if (d.counts && (countsAreReal(d) || !Object.keys(PCOUNTS).length)) {
      PCOUNTS = d.counts;
      PDOORS = d.doors || d.counts;
      drawDoors($('p-kinds'), PCOUNTS, PKIND, passedTab, PDOORS);
      askAgainForCounts(d, 'passed', function (counts) {
        PCOUNTS = counts;
        PDOORS = counts;
        drawDoors($('p-kinds'), PCOUNTS, PKIND, passedTab, PDOORS);
      });
    }
    var head = $('p-head');
    clear(head);
    headCells(headsFor(PKIND)).forEach(function (th) { head.appendChild(th); });
    serverSortHeads(head, SORTS.passed, authSortKeys(PKIND), function () {
      PAGE.passed = 0;
      loadPassed();
    });
    var body = $('p-table').querySelector('tbody');
    clear(body);
    $('p-empty').hidden = !!d.rows.length;
    if (!d.rows.length) {
      sayWhyEmpty('p-empty', PKIND, PCOUNTS, PDOORS, $('p-hours').value, function () {
        $('p-hours').value = '0';
        PAGE.passed = 0;
        loadPassed();
      });
    }
    d.rows.forEach(function (r) {
      var tr = el('tr');
      tr._rec = r;
      tr.dataset.session = r.session || '';
      opensWith(tr, '', function () { showRecord('passed', r.session); });
      if (isNetworkKind(PKIND)) {
        networkRow(tr, r, PKIND, true);
        body.appendChild(tr);
        return;
      }
      if (PKIND === 'otp') {
        tokenRow(tr, r, true);
        body.appendChild(tr);
        return;
      }
      if (PKIND === 'eduroam') {
        eduroamRow(tr, r, true);
        body.appendChild(tr);
        return;
      }
      tr.appendChild(stampCell(r.ts));
      var user = el('td');
      user.appendChild(el('span', 'mono', r.username || '\u2013'));
      whoIsIt(user, r.username, r.realm);
      tr.appendChild(user);
      /* People reach the switches from one machine on most sites, so a
         sign-in from anywhere else is the row worth reading first. Nothing
         is blocked and nobody is judged: the row is marked, and that is all
         it is - it is switched on, and the usual places named, in Settings. */
      if (isShellKind(PKIND) && r.ip && placeIsUsual(r.ip) === false) {
        tr.classList.add('odd-place');
      }
      addrPlaceCountry(tr, r.ip, r.country, isShellKind(PKIND), r.ts);
      if (isShellKind(PKIND)) {
        tr.appendChild(deviceCell(r));
        /* What they did once they were in. ISE writes one record per command;
           they belong to this session and are shown inside it, not as forty
           more rows of the same name. */
        var did = el('td');
        var count = (CMDCOUNT || {})[r.session] || {n: 0, denied: 0};
        if (count.n) {
          var pill = el('span', 'tag ' + (count.denied ? 'crit' : 'info'),
                        num(count.n) + (count.n === 1 ? ' command' : ' commands'));
          explain(pill, count.denied
            ? count.denied + ' of them refused. Click the row to read them.'
            : 'Every one of them allowed. Click the row to read them.');
          did.appendChild(pill);
          if (count.denied) {
            var bad = el('span', 'tag crit', num(count.denied) + ' refused');
            bad.style.marginLeft = '6px';
            did.appendChild(bad);
          }
        } else {
          did.appendChild(el('span', 'muted small',
            PKIND === 'tacplus' ? 'nothing was run' : 'signed in only'));
        }
        tr.appendChild(did);
        tr.appendChild(el('td', '', r.profile || '\u2013'));
        tr.appendChild(el('td', '', r.policy || '\u2013'));
      } else {
        if (PKIND === 'vpn') tr.appendChild(machineCell(r.machine));
        tr.appendChild(el('td', '', r.profile || '\u2013'));
        tr.appendChild(deviceCell(r));
        tr.appendChild(el('td', '', r.tunnel || '\u2013'));
        /* Whether this session was handed a downloadable ACL, and its short
           name. The rules themselves are in the record popup. */
        var fw = el('td');
        if (r.acl) {
          var mark = el('span', 'acl-mark');
          mark.innerHTML = iconMarkup('wall', 14);
          mark.appendChild(el('span', '', aclShort(r.acl)));
          explain(mark, 'This session was handed a downloadable ACL \u2014 the firewall rules '
            + 'that decide where it may go once it is on. Click the row to read them.',
            '<span class="k">' + richText(r.acl) + '</span>');
          fw.appendChild(mark);
        } else {
          fw.textContent = '\u2013';
        }
        tr.appendChild(fw);
      }
      tr.appendChild(el('td', '', r.server || '\u2013'));
      var act = el('td');
      /* "let in" rather than "in": a word of its own, so that it can be
         said in another language without saying "in" everywhere. */
      var got = el('span', 'tag ok', 'let in');
      if (isNpsKind(PKIND)) {
        explain(got, 'A Windows NPS server let this one through \u2014 not ISE. It is written '
          + 'down and shown, and never judged.');
      } else if (isRadiusKind(PKIND)) {
        explain(got, 'A FreeRADIUS server of this site\u2019s own let this one through \u2014 '
          + 'not ISE. It is written down and shown.');
      } else if (PKIND === 'tacplus') {
        explain(got, 'The site\u2019s own TACACS+ daemon let this one through \u2014 not '
          + 'ISE, which has nothing to do with this door. What is drawn here is what '
          + 'tac_plus wrote down: a sitting at a switch prompt, and every command run '
          + 'during it. None of it is ever judged.');
      } else
      explain(got, 'ISE let this one through. Everything on this page did: a refusal is on '
        + 'the Failed attempts tab. It is here so a row can be told apart at a glance when '
        + 'this page is read beside that one.');
      act.appendChild(got);
      tr.appendChild(act);
      body.appendChild(tr);
    });
    optColumns($('p-table'), OPT_PASSED);
    holdTheTallOnes();
    pager('p-pager', PAGE.passed, per, d.total, function (page) {
      PAGE.passed = page;
      loadPassed();
    }, d.capped);
    explainWhatWasDrawn($('tab-logins'));
  }).catch(oops);
}
/* #ACSACL#-IP-AnyConnect_OLYMPUS-6913329c is the whole name and none of it is
   worth a column. What somebody reads is the middle. */
function aclShort(name) {
  var m = /^#ACSACL#-IP-(.*?)-[0-9a-f]{6,10}$/i.exec(String(name || ''));
  return m ? m[1] : String(name || '').replace(/^#ACSACL#-(IP-)?/i, '');
}
Array.prototype.forEach.call(document.querySelectorAll('#p-kinds button'), function (b) {
  b.onclick = function () { passedTab(b.dataset.kind); };
});
Array.prototype.forEach.call(document.querySelectorAll('#f-kinds button'), function (b) {
  b.onclick = function () { showFailedKind(b.dataset.kind); };
});

['f-q', 'p-q'].forEach(function (id) {
  $(id).addEventListener('input', debounce(function () {
    PAGE[id[0] === 'f' ? 'failed' : 'passed'] = 0;
    if (id[0] === 'f') loadFailed(); else loadPassed();
  }, 350));
});
['f-hours', 'f-device', 'f-server', 'f-country', 'f-limit'].forEach(function (id) {
  $(id).onchange = function () { PAGE.failed = 0; loadFailed(); };
});
['p-hours', 'p-device', 'p-server', 'p-country', 'p-limit'].forEach(function (id) {
  $(id).onchange = function () { PAGE.passed = 0; loadPassed(); };
});
$('f-clear').onclick = function () {
  ['f-q', 'f-device', 'f-server', 'f-country'].forEach(function (id) {
    $(id).value = '';
    if ($(id)._ccpick) $(id)._ccpick.paint();
  });
  clearPicks('f');
  if (typeof windowSet === 'function') windowSet('f-hours', null);   /* its dates go too */
  $('f-hours').value = '24';
  PAGE.failed = 0;
  sortReset(SORTS.failed);
  loadFailed();
};
$('p-clear').onclick = function () {
  ['p-q', 'p-device', 'p-server', 'p-country'].forEach(function (id) {
    $(id).value = '';
    if ($(id)._ccpick) $(id)._ccpick.paint();
  });
  clearPicks('p');
  if (typeof windowSet === 'function') windowSet('p-hours', null);   /* its dates go too */
  $('p-hours').value = '24';
  PAGE.passed = 0;
  sortReset(SORTS.passed);
  loadPassed();
};

/* ==========================================================================
   One record, whole
   --------------------------------------------------------------------------
   ISE writes seventy or so fields about every authentication and there is no
   way to know in advance which of them is the one somebody needs. The table
   above shows the eight that are nearly always the answer; this shows all of
   them, in the order ISE wrote them, with the few that matter pulled out on
   top so nobody has to go looking.
   ========================================================================== */
var HEADLINE = ['UserName', 'Calling-Station-ID', 'FailureReason', 'NetworkDeviceName',
  'CVPN3000/ASA/PIX7x-Tunnel-Group-Name', 'SelectedAccessService',
  'SelectedAuthorizationProfiles', 'SelectedShellProfile', 'AuthenticationMethod',
  'AuthenticationIdentityStore', 'ISEPolicySetName', 'IdentityPolicyMatchedRule',
  'AuthorizationPolicyMatchedRule', 'AD-User-Resolved-Identities', 'AD-Groups-Names',
  'Called-Station-ID', 'Device IP Address', 'NAS-IP-Address', 'AcsSessionID', 'Response',
  /* ...and NPS's, which spells a few of the same things its own way. */
  'What it said', 'User-Name', 'Fully-Qualified-User-Name', 'Calling-Station-Id',
  'Client-Friendly-Name', 'Client-IP-Address', 'Switch port', 'NAS-Port', 'Port kind',
  'Asked for', 'Make of the device', 'Checked by', 'Answered by NPS at',
  'Domain (MS-CHAP)', 'Session limit',
  'Authenticated with', 'EAP-Friendly-Name', 'Policy-Name', 'Proxy-Policy-Name',
  'Reason-Code', 'Tunnel-Pvt-Group-ID', 'Framed-IP-Address', 'Computer-Name'];

/* ---- the firewall a VPN session was handed -------------------------------
   ISE writes it as one field, like this:

     {Class=CACS:2ee3…; cisco-av-pair=ip:inacl#1=remark DNS;
      cisco-av-pair=ip:inacl#2=permit udp any host 172.25.1.10 eq 53; …}

   which is a firewall written as a paragraph. Nobody can read a paragraph and
   say what a session is allowed to reach. So it is drawn as what it is: rules
   in order, with the remarks as headings over the rules they were written
   for, permit in green and deny in red, and the address and port each rule is
   about in their own columns. */
function aclPanel(acl) {
  var box = el('details', 'fold acl');
  box.open = true;
  var sum = el('summary');
  var mark = el('span', 'acl-ico');
  mark.innerHTML = iconMarkup('wall', 15);
  sum.appendChild(mark);
  sum.appendChild(document.createTextNode('The firewall this session was handed'));
  var n = el('span', 'n');
  if (acl.have) {
    n.textContent = acl.rules.length + ' rule(s) \u00b7 ' + acl.permits + ' permit \u00b7 '
      + acl.denies + ' deny';
  } else {
    n.textContent = 'not in the log';
  }
  sum.appendChild(n);
  box.appendChild(sum);
  var inner = el('div', 'body');

  var name = el('div', 'acl-name');
  name.appendChild(el('span', 'mono', acl.name || '(unnamed)'));
  if (acl.matched === 'name' || acl.matched === 'name-later') {
    var byName = el('span', 'tag warn', 'matched by name');
    explain(byName, 'This session\u2019s own download of the ACL is not in what is kept, so the '
      + 'rules shown come from a download of an ACL of <b>this same name</b>'
      + (acl.matched === 'name'
         ? ' \u2014 the newest one recorded at or before this login, which is the version that '
           + 'was in force when it signed in.'
         : ', recorded <b>after</b> this login, because no copy of it from before is kept any '
           + 'more. It is the nearest thing there is rather than a reading of this session.')
      + ' ISE writes the version into the name itself \u2014 the eight characters on the end '
      + 'change whenever the ACL is edited \u2014 so a name that matches is the same rules, '
      + 'and an ACL edited since this login carries a different name and is not shown here.');
    name.appendChild(byName);
  } else if (acl.have) {
    var exact = el('span', 'tag ok', 'this session');
    explain(exact, 'Read from the download record belonging to this very session \u2014 they '
      + 'are exactly the rules this session was given, as they were at that moment. Editing '
      + 'the ACL on ISE afterwards changes what the next login is handed and nothing about '
      + 'this one: every download is kept as it happened, so an old login goes on showing the '
      + 'old rules and a new login shows the new ones.');
    name.appendChild(exact);
  }
  if (acl.at) {
    var when = el('span', 'muted small', 'downloaded ' + shortStamp(acl.at)
      + (acl.server ? ' \u00b7 ' + acl.server : ''));
    name.appendChild(when);
  }
  inner.appendChild(name);

  if (!acl.have) {
    inner.appendChild(el('p', 'btnhelp',
      'The device was told to use this ACL, but the download itself is not among the records '
      + 'kept here \u2014 which is usual: the firewall only downloads an ACL it has not already '
      + 'got, so one download serves every session after it until ISE changes the rules. The '
      + 'rules appear here as soon as a download of this ACL is read.'));
    box.appendChild(inner);
    return box;
  }

  var table = el('table', 'acl-rules');
  var head = el('tr');
  ['#', '', 'Protocol', 'From', 'To', 'Port'].forEach(function (x) {
    head.appendChild(el('th', '', x));
  });
  var thead = el('thead');
  thead.appendChild(head);
  table.appendChild(thead);
  var body = el('tbody');
  acl.rules.forEach(function (rule) {
    var tr = el('tr', 'acl-' + rule.kind);
    if (rule.kind === 'remark') {
      /* A remark is a heading the network team wrote over the rules that
         follow it, so it is drawn as a heading rather than as a rule. */
      var one = el('td');
      one.colSpan = 6;
      one.className = 'acl-remark';
      one.textContent = rule.note || rule.text;
      tr.appendChild(one);
      body.appendChild(tr);
      return;
    }
    tr.appendChild(el('td', 'acl-n', String(rule.n)));
    var act = el('td');
    var tag = el('span', 'tag ' + (rule.kind === 'permit' ? 'ok' : 'crit'), rule.kind);
    act.appendChild(tag);
    tr.appendChild(act);
    tr.appendChild(el('td', 'mono', (rule.proto || '').toLowerCase() || '\u2013'));
    tr.appendChild(aclWhere(rule.src, rule.src_port));
    tr.appendChild(aclWhere(rule.dst));
    var port = el('td', 'mono', aclPortWords(rule.dst_port) || 'any');
    if (rule.extra) {
      var extra = el('span', 'tag', rule.extra);
      extra.style.marginLeft = '7px';
      port.appendChild(extra);
    }
    tr.appendChild(port);
    explain(tr, 'As the log wrote it', '<span class="k mono">' + richText(rule.text)
      + '</span>');
    body.appendChild(tr);
  });
  table.appendChild(body);
  var scroll = el('div', 'scroll');
  scroll.appendChild(table);
  inner.appendChild(scroll);

  var copy = cmdButton('Copy the rules', 'list', 'small');
  copy.onclick = function (e) {
    e.preventDefault();
    e.stopPropagation();
    var text = acl.rules.map(function (r) { return r.text; }).join('\n');
    copyText(text, 'the rules are on the clipboard');
  };
  var bar = el('div', 'btnrow');
  bar.appendChild(copy);
  inner.appendChild(bar);
  box.appendChild(inner);
  return box;
}
/* "host 172.25.1.10" is how a router writes one address and "any" is how it
   writes all of them; neither is worth making somebody decode. */
function aclWhere(where, port) {
  var td = el('td');
  var text = String(where || '').trim();
  if (!text || /^any4?6?$/i.test(text)) {
    var any = el('span', 'acl-any', 'anywhere');
    explain(any, 'Any address at all \u2014 the rule does not care where it comes from.');
    td.appendChild(any);
  } else if (/^host\s+/i.test(text)) {
    td.appendChild(addrLine(text.replace(/^host\s+/i, '')));
  } else if (/^object-group\s+/i.test(text)) {
    var group = el('span', 'mono', text.replace(/^object-group\s+/i, ''));
    explain(group, 'A named group of addresses kept on the device itself. What is in it is not '
      + 'in the log \u2014 the device knows.');
    td.appendChild(group);
  } else {
    td.appendChild(el('span', 'mono', text));
  }
  if (port) {
    var p = el('span', 'muted small', ' ' + aclPortWords(port));
    td.appendChild(p);
  }
  return td;
}
var ACL_PORT_NAMES = {'53': 'DNS', '80': 'HTTP', '443': 'HTTPS', '22': 'SSH', '23': 'Telnet',
  '25': 'SMTP', '3389': 'RDP', '389': 'LDAP', '636': 'LDAPS', '445': 'SMB', '139': 'NetBIOS',
  '88': 'Kerberos', '123': 'NTP', '161': 'SNMP', '1433': 'MSSQL', '3306': 'MySQL',
  '5432': 'PostgreSQL', '5985': 'WinRM', '5986': 'WinRM/TLS', '8080': 'HTTP alt',
  '8443': 'HTTPS alt', '135': 'RPC', '20': 'FTP data', '21': 'FTP', '514': 'syslog',
  '1812': 'RADIUS', '49': 'TACACS+', '67': 'DHCP', '68': 'DHCP', '5060': 'SIP', '5061': 'SIPS'};
function aclPortWords(port) {
  var text = String(port || '').trim();
  if (!text) return '';
  var m = /^eq\s+(\S+)$/i.exec(text);
  if (m) {
    var name = ACL_PORT_NAMES[m[1]];
    return m[1] + (name ? ' (' + name + ')' : '');
  }
  m = /^range\s+(\S+)\s+(\S+)$/i.exec(text);
  if (m) return m[1] + '\u2013' + m[2];
  return text.replace(/^neq\s+/i, 'not ').replace(/^lt\s+/i, 'under ')
    .replace(/^gt\s+/i, 'over ');
}

/* ---- what somebody did once they were on a switch ------------------------
   ISE writes one record for the sign-in and one more for every command after
   it, and a list that shows all of them is a list of the same name forty
   times over. They belong to the session they were typed in, so they are
   drawn inside it - in order, with the ones ISE refused in red, the way the
   firewall rules of a VPN session are drawn inside that. */
function commandPanel(c, login) {
  var box = el('details', 'fold acl');
  box.open = true;
  var sum = el('summary');
  var mark = el('span', 'acl-ico');
  mark.innerHTML = iconMarkup('terminal', 15);
  sum.appendChild(mark);
  sum.appendChild(document.createTextNode('What was done in this session'));
  var n = el('span', 'n');
  if (!c.have) {
    n.textContent = 'nothing was recorded';
  } else {
    n.textContent = num(c.ran) + (c.ran === 1 ? ' command' : ' commands')
      + (c.denied ? ' \u00b7 ' + num(c.denied) + ' refused' : ' \u00b7 all allowed');
  }
  sum.appendChild(n);
  box.appendChild(sum);
  var inner = el('div', 'body');

  var head = el('div', 'acl-name');
  head.appendChild(el('span', 'muted small',
    'on ' + (login.device || 'the device') + (login.ip ? ' from ' + login.ip : '')));
  if (c.open) {
    var still = el('span', 'tag info', 'no later sign-in');
    explain(still, 'Nothing after this says the session ended, so everything this person did '
      + 'from here on is under this one until they sign in again. Commands are matched to a '
      + 'session by who, which device, which line of it and where from \u2014 TACACS+ gives '
      + 'nothing better, because ISE writes a different session id on every single record.');
    head.appendChild(still);
  } else if (c.ended) {
    head.appendChild(el('span', 'muted small', 'until they signed in again '
      + shortStamp(c.ended)));
  }
  inner.appendChild(head);

  if (!c.have) {
    inner.appendChild(el('p', 'btnhelp', c.why
      ? ('No commands can be matched to this one: ' + c.why + '.')
      : 'They signed in and ISE was not asked about a single command afterwards \u2014 either '
        + 'they did nothing, or this device does not ask ISE about commands at all. Command '
        + 'authorisation has to be switched on per device for any of it to be recorded.'));
    box.appendChild(inner);
    return box;
  }

  var table = el('table', 'acl-rules cmd-rules');
  var thead = el('thead'), hr = el('tr');
  ['', 'When', '', 'Command', 'Allowed by'].forEach(function (x) {
    hr.appendChild(el('th', '', x));
  });
  thead.appendChild(hr);
  table.appendChild(thead);
  var body = el('tbody');
  var nth = 0;
  c.commands.forEach(function (one) {
    var tr = el('tr', 'acl-' + (one.verdict === 'denied' ? 'deny' : 'permit'));
    if (one.shell) tr.classList.add('cmd-shell');
    tr.appendChild(el('td', 'acl-n', one.shell ? '' : String(++nth)));
    tr.appendChild(stampCell(one.ts, 'dim'));
    var verdict = el('td');
    var tag = el('span', 'tag ' + (one.verdict === 'denied' ? 'crit' : 'ok'),
                 one.verdict === 'denied' ? 'refused' : 'allowed');
    explain(tag, one.verdict === 'denied'
      ? 'ISE told the device not to run this. The device is what enforces that; ISE only '
        + 'answers.'
      : 'ISE told the device this was allowed. Whether it then worked is the device\u2019s '
        + 'own business \u2014 a command can be allowed and still fail.');
    verdict.appendChild(tag);
    tr.appendChild(verdict);
    var what = el('td');
    if (one.shell) {
      var shell = el('span', 'muted small', 'the shell itself was granted');
      explain(shell, 'The first thing ISE is asked after somebody signs in: may this person '
        + 'have a shell at all, and at what privilege level. It is not something they typed.');
      what.appendChild(shell);
    } else {
      what.appendChild(el('span', 'mono cmd-text', one.cmd));
    }
    tr.appendChild(what);
    tr.appendChild(el('td', 'dim', one.set || '\u2013'));
    body.appendChild(tr);
  });
  table.appendChild(body);
  var scroll = el('div', 'scroll');
  scroll.appendChild(table);
  inner.appendChild(scroll);

  /* Somebody went into configuration mode and nothing they typed there is in
     the list. That is not something lost here: the device asks about a
     command typed in configuration mode only when it is told to
     (`aaa authorization config-commands`), and a TACACS+ server writes one
     down only with command accounting at that level. Said beside the list,
     because "configure terminal" followed by nothing reads as somebody who
     changed nothing. */
  var EXEC_VERBS = /^(show|configure|conf|write|wr|copy|exit|end|logout|quit|ping|traceroute|trace|terminal|term|enable|disable|clear|debug|undebug|no debug|dir|more|reload|verify|test|telnet|ssh)\b/i;
  var real = c.commands.filter(function (x) { return !x.shell; });
  var configured = real.some(function (x) { return /^conf(igure)?\b/i.test(String(x.cmd || '')); });
  var onlyExec = real.every(function (x) { return EXEC_VERBS.test(String(x.cmd || '').trim()); });
  if (configured && onlyExec) {
    inner.appendChild(el('p', 'btnhelp',
      'Nothing typed inside configure terminal is in this list \u2014 not because it was lost '
      + 'here, but because the device never sent it. A Cisco device asks the TACACS+ server '
      + 'about commands typed in configuration mode only with '
      + '\u201caaa authorization config-commands\u201d, and a tac_plus server writes them down '
      + 'only with \u201caaa accounting commands 15 default start-stop group tacacs+\u201d. '
      + 'Without either, what was changed is not recorded anywhere.'));
  }
  var copy = cmdButton('Copy the commands', 'list', 'small');
  copy.onclick = function (e) {
    e.preventDefault();
    e.stopPropagation();
    var text = c.commands.filter(function (x) { return !x.shell; })
      .map(function (x) { return x.cmd; }).join('\n');
    copyText(text, 'the commands are on the clipboard');
  };
  var bar = el('div', 'btnrow');
  bar.appendChild(copy);
  inner.appendChild(bar);
  box.appendChild(inner);
  return box;
}

/* What one record is, in the words that go at the top of it when it is
   opened. The door it came through decides, and a record from before the
   doors were told apart - which has no door written on it - falls back to
   the protocol, which is what this used to read for all of them. */
var RECORD_WORDS = {
  vpn: 'VPN login',
  tacacs: 'device login',
  'tacacs-cmd': 'command on a switch',
  tacplus: 'sitting on a switch, through tac_plus',
  'tacplus-cmd': 'command on a switch, through tac_plus',
  'dot1x-lan': '802.1X login on the LAN',
  'dot1x-wifi': '802.1X login on Wi-Fi',
  'mab-lan': 'MAB on the LAN',
  'mab-wifi': 'MAB on Wi-Fi',
  'nps-vpn': 'VPN login, through NPS',
  'nps-dot1x-lan': '802.1X login on the LAN, through NPS',
  'nps-dot1x-wifi': '802.1X login on Wi-Fi, through NPS',
  'nps-mab-lan': 'MAB on the LAN, through NPS',
  'nps-mab-wifi': 'MAB on Wi-Fi, through NPS',
  'nps-other': 'sign-in through NPS',
  'radius-vpn': 'VPN login, through FreeRADIUS',
  'radius-dot1x-lan': '802.1X login on the LAN, through FreeRADIUS',
  'radius-dot1x-wifi': '802.1X login on Wi-Fi, through FreeRADIUS',
  'radius-mab-lan': 'MAB on the LAN, through FreeRADIUS',
  'radius-mab-wifi': 'MAB on Wi-Fi, through FreeRADIUS',
  'radius-other': 'sign-in through FreeRADIUS',
  otp: 'one-time password',
  eduroam: 'eduroam login',
  other: 'record'
};
function recordWords(r) {
  var kind = String((r && r.kind) || '');
  if (RECORD_WORDS[kind]) return RECORD_WORDS[kind];
  return (r && r.protocol) === 'Tacacs' ? 'device login' : 'VPN login';
}

function showRecord(table, session) {
  modal('Loading…', function (body) {
    body.appendChild(el('p', 'center', 'Fetching the record…'));
  });
  /* The ticket: an answer arriving after this popup was closed, or after
     another was opened over it, is dropped rather than drawn. */
  var ticket = modalTicket();
  api('detail&table=' + table + '&session=' + encodeURIComponent(session)).then(function (d) {
    if (!modalStill(ticket)) return;
    var r = d.row;
    var buttons = [{words: 'Close', close: true}];
    if (r.ip) {
      /* Not `close`: the buttons are pressed first and closed after, so
         the address's own popup was opened and at once closed again - and
         its answer thrown away. Opening it replaces this one. (1.10.168) */
      buttons.unshift({words: 'Everything about ' + r.ip, go: function () {
        lookUp(r.ip);
      }});
      if (CAN_BAN && r.story && !r.story.blocked && !r.story.spared) {
        buttons.unshift({words: 'Ban ' + r.ip, cls: 'danger', close: true, go: function () {
          banNow(r.ip, 0, 'banned from a record');
        }});
      }
    }
    /* What the record is, out of the record. It used to be read off the
       protocol alone - TACACS or "VPN" - so every 802.1X login, every MAB
       refusal, every token and every change of authorisation opened under a
       heading saying it was a VPN login. Each heading one sentence with its
       pieces in it, so that it is said in the page's language as well.
       (1.10.160) */
    var whose = r.kind === 'dacl' ? aclShort(r.username || r.acl) : recordWords(r);
    var when = shortStamp(r.ts);
    var heading = table === 'failed' ? 'A refused ' + whose + ' · ' + when
      : r.kind === 'dacl' ? 'A downloadable ACL · ' + whose + ' · ' + when
      : r.kind === 'tacplus' ? 'One ' + whose + ' · ' + when
      : 'A successful ' + whose + ' · ' + when;
    modal(heading, function (body) {
      var head = el('div');
      head.style.marginBottom = '18px';
      function kv(k, v) {
        if (v === undefined || v === null || v === '') return;
        var line = el('div', 'kv');
        line.appendChild(el('span', 'k', k));
        var value = el('span', 'v');
        if (v instanceof Node) value.appendChild(v); else value.textContent = v;
        line.appendChild(value);
        head.appendChild(line);
      }
      kv('When', stamp(r.ts) + '  ·  read from ' + (r.server || 'an ISE node'));
      if (r.username) {
        var who = el('span');
        who.appendChild(el('span', 'mono', r.username));
        whoIsIt(who, r.username, r.realm);
        kv('Name', who);
      }
      if (r.ip) {
        var addr = el('span');
        addr.appendChild(addrLine(r.ip));
        if (r.country) {
          addr.appendChild(document.createTextNode(' '));
          addr.appendChild(countryBadge(r.country));
        }
        if (r.story && r.story.blocked) {
          /* Not "banned" where nobody carries it (1.10.198). */
          var t = r.story.carried === false
            ? el('span', 'tag ' + (r.story.watched ? 'warn' : 'dim'),
                 r.story.watched ? 'only watched' : 'not carried')
            : el('span', 'tag crit', 'banned');
          t.style.marginLeft = '8px';
          addr.appendChild(t);
        }
        kv('From', addr);
      }
      if (table === 'failed') kv('Why it failed', (r.reason || '')
        + (r.code ? '  (' + r.code + ')' : ''));
      else kv('Given', r.profile);
      if (r.subtype) kv('What it was', String(r.subtype).replace('|', '  \u00b7  '));
      kv('Device', deviceWords(r.device, r.nad));
      /* The socket, and what it is a socket ON. A port number on its own is
         not a place: there is a GigabitEthernet1/0/16 on every switch in
         the building. */
      if (r.port) kv('Where on it', portWords(r.port, r.device, r.nad));
      /* The same words as on the token record, which shows it out of the
         RADIUS packet: one thing has one name here wherever it is shown. */
      if (r.machine) kv('The machine', r.machine);
      kv('Tunnel group', r.tunnel);
      kv('Access service', r.service);
      kv('Policy set', r.policy);
      kv('Protocol', r.protocol);
      if (r.groups) kv('Directory groups', r.groups);
      if (r.story) {
        kv('This address here', num(r.story.failed_total) + ' failed · '
           + num(r.story.passed_total) + ' passed · banned '
           + r.story.before + '× before');
      }
      body.appendChild(head);

      /* A token attempt, and what the RADIUS server in front of the token
         software was asked to get it. None of it is in the token log. */
      if (r.kind === 'otp') body.appendChild(askedPanel(r));

      /* The firewall this session was handed, if it was handed one. It came
         down the same log as a record of its own; this is where it belongs. */
      if (r.acl_rules) body.appendChild(aclPanel(r.acl_rules));
      /* And, for a switch, what they did once they were in. */
      if (r.commands) body.appendChild(commandPanel(r.commands, r));

      var fields = r.fields || {};
      var names = Object.keys(fields);
      var headline = HEADLINE.filter(function (n) { return names.indexOf(n) >= 0; });
      if (headline.length) {
        body.appendChild(el('h4', '', 'The fields that usually matter'));
        body.appendChild(fieldList(fields, headline));
      }
      var rest = names.filter(function (n) { return headline.indexOf(n) < 0; });
      var more = el('details', 'fold');
      var sum = el('summary', '', r.kind === 'otp' ? 'Every field the token log wrote'
        : r.kind === 'eduroam' ? (String(r.session || '').indexOf('edu/nps/') === 0
                                  ? 'Every field NPS wrote, request and answer'
                                  : 'Every field FreeRADIUS wrote')
        : (r.kind === 'tacplus' || r.kind === 'tacplus-cmd')
          ? 'Every field tac_plus wrote'
        : isNpsKind(r.kind) ? 'Every field NPS wrote, request and answer'
        : isRadiusKind(r.kind) ? 'Every field FreeRADIUS wrote'
        : 'Every field ISE wrote');
      sum.appendChild(el('span', 'n', names.length + ' field(s)'));
      more.appendChild(sum);
      var inner = el('div', 'body');
      inner.appendChild(fieldList(fields, rest));
      more.appendChild(inner);
      body.appendChild(more);

      var copy = cmdButton('Copy the whole record', 'list', 'small');
      copy.style.marginTop = '12px';
      copy.onclick = function () {
        var text = names.map(function (n) {
          var v = fields[n];
          return n + ' = ' + (Array.isArray(v) ? v.join(' | ') : v);
        }).join('\n');
        /* The one copier every button uses, which also works over plain HTTP
           where the browser keeps the modern clipboard away. (1.10.160) */
        copyText(text, 'the record is on the clipboard');
      };
      body.appendChild(copy);
    }, buttons);
  }).catch(function (e) {
    if (!modalStill(ticket)) return;
    modal('That record', function (body) {
      body.appendChild(el('p', 'note', String(e.message || e)));
    }, [{words: 'Close', close: true}], true);
  });
}

/* What the RADIUS server in front of the token software was asked.
   ---------------------------------------------------------------------------
   The token log answers one question - was the number right - and the packet
   that caused it answers all the others: whose address it really was, what
   machine they were on, which door they came through, and the session id ISE
   wrote about the other half of the very same sign-in.

   It is shipped by a script on a minute's timer, so for the newest attempts
   it is not here yet. That is said out loud rather than drawn as a blank,
   because "not yet" and "the script has stopped" look identical otherwise. */
var ASKED_TLV = [
  ['computer-name', 'What the machine calls itself'],
  ['device-platform', 'Platform'],
  ['device-platform-version', 'Platform version'],
  ['device-type', 'Model'],
  ['device-mac', 'Its MAC'],
  ['device-public-mac', 'The MAC it shows outside'],
  ['ac-user-agent', 'The client software'],
  ['device-uid', 'Device id'],
  ['device-uid-global', 'Device id (global)'],
  ['audit-session-id', 'ISE session id'],
  ['ip:source-ip', 'The address it says it has'],
  ['coa-push', 'Change of authorisation']
];
var ASKED_VERDICTS = {
  accept: ['ok', 'let in', 'The RADIUS server answered Access-Accept: this half of the '
    + 'sign-in finished, and the VPN head end was told to let them through.'],
  reject: ['crit', 'refused', 'The RADIUS server answered Access-Reject. The token line '
    + 'beside it says which of the reasons it was.'],
  challenge: ['warn', 'asked for more', 'The server answered Access-Challenge: it wanted '
    + 'another round before it would decide, which is what a token prompt is.'],
  start: ['info', 'the session started', 'An accounting record: the session this belongs to '
    + 'was opened.'],
  alive: ['info', 'the session is still going', 'An accounting record sent while the session '
    + 'is open, which is how the head end says it has not ended.'],
  stop: ['info', 'the session ended', 'An accounting record: the session this belongs to was '
    + 'closed.']
};

function askedPanel(r) {
  var wrap = el('div');
  wrap.appendChild(el('h4', '', 'What the RADIUS server was asked'));
  var a = r.asked;
  if (!a) {
    var none = el('p', 'note');
    if (!(STATUS && STATUS.otp_detail_on)) {
      none.innerHTML = 'The token log says whether the number was right and nothing else \u2014 '
        + 'the address on one of its lines is the token server\u2019s own, because it is asked '
        + 'over the loopback by whatever stands in front of it. Switch on <b>the RADIUS log '
        + 'beside it</b> under Settings \u2192 The OTP logs and every attempt here shows the '
        + 'person\u2019s own address, the machine they were on, the door they came through and '
        + 'the session id ISE wrote about the other half of the same sign-in.';
    } else {
      var behind = r.asked_behind;
      none.innerHTML = 'Nothing beside this one yet. These are shipped by a script that runs '
        + 'once a minute, so an attempt from the last minute or two normally has nothing here '
        + '\u2014 open it again shortly.';
      if (behind && behind.behind >= 0) {
        var says = el('p', 'note');
        says.innerHTML = 'The newest packet read arrived <b>'
          + Math.round(behind.behind) + ' second(s)</b> after it happened, at '
          + shortStamp(behind.at) + '. Much more than a couple of minutes and the script on '
          + 'the token server is worth a look.';
        wrap.appendChild(none);
        wrap.appendChild(says);
        return wrap;
      }
    }
    wrap.appendChild(none);
    return wrap;
  }
  var facts = [];
  var who = a.verdict && ASKED_VERDICTS[a.verdict];
  if (who) {
    var tag = el('span', 'tag ' + who[0], who[1]);
    explain(tag, who[2]);
    facts.push(['What it answered', tag]);
  }
  if (a.ip) {
    var addr = el('span');
    addr.appendChild(addrLine(a.ip));
    if (r.asked_country) {
      addr.appendChild(document.createTextNode(' '));
      addr.appendChild(countryBadge(r.asked_country));
    }
    facts.push(['The person\u2019s own address', addr]);
  }
  if (a.code_by) {
    /* The second window (otp 1.0.76): how the code came, and where to. */
    var by = el('span');
    var byTag = el('span', 'tag info', CODE_BY_WORDS[a.code_by] || a.code_by);
    explain(byTag, codeBySays(a));
    by.appendChild(byTag);
    if (a.code_to) {
      var to = el('span', 'mono small', a.code_to);
      to.style.marginLeft = '8px';
      by.appendChild(to);
    }
    facts.push(['How the code came', by]);
  }
  if (a.tunnel) facts.push(['Tunnel group', a.tunnel]);
  if (a.nas) {
    var box = el('span');
    box.appendChild(el('span', 'mono', a.nas));
    var place = r.asked_place || {};
    if (place.name) {
      var named = el('span', 'tag');
      named.textContent = place.name;
      named.style.marginLeft = '8px';
      box.appendChild(named);
    } else if (place.usual === false) {
      var odd = el('span', 'tag warn', 'not a usual door');
      odd.style.marginLeft = '8px';
      explain(odd, 'This box is not on the list under Settings \u2192 The OTP logs \u2192 '
        + 'Where OTP sign-ins come from.');
      box.appendChild(odd);
    }
    facts.push(['The box that asked', box]);
  }
  if (a.device) facts.push(['The machine', a.device]);
  if (a.session) facts.push(['Session id', el('span', 'mono small', a.session)]);
  if (a.at && a.ts) {
    var late = Math.max(0, Math.round(a.at - a.ts));
    facts.push(['Read here', shortStamp(a.at) + (late ? '  \u00b7  ' + late + 's later' : '')]);
  }
  wrap.appendChild(peekFacts(facts));
  /* How this packet was decided to be this attempt's. The two logs are
     written by two programs with nothing in common to join on, so it is
     done by who, where and when - and where that could not be certain, it
     is better to say so than to let a guess read as a fact. */
  if (a.sure === false) {
    var doubt = el('p', 'note bad');
    doubt.innerHTML = '<b>This one is not certain.</b> Another packet was exactly as close '
      + 'to this attempt and fitted it exactly as well, and nothing in either log says which '
      + 'of the two caused it. The nearer one is shown. Everything above comes from that '
      + 'packet, so treat it as the likely one rather than the known one.';
    wrap.appendChild(doubt);
  } else if (a.by === 'the id both logs carry') {
    var exact = el('p', 'note good');
    exact.textContent = 'Matched by the id both logs carry, so this is the packet that caused '
      + 'this attempt and not one that merely fits: the token server was told which RADIUS '
      + 'request it was being asked about, and wrote it down.';
    wrap.appendChild(exact);
  } else if (a.by === 'the name without its realm') {
    var loose = el('p', 'note');
    loose.textContent = 'Matched on the name without its realm: one of the two logs did not '
      + 'write one. On a site with more than one realm in front of one token server that is '
      + 'worth knowing about.';
    wrap.appendChild(loose);
  }
  if (a.said) {
    /* Its own words, put in as text rather than as markup: this is a
       sentence a RADIUS module wrote and it is not this page's to trust. */
    var reply = el('p', 'note');
    reply.appendChild(document.createTextNode('It sent back: '));
    reply.appendChild(el('code', '', a.said));
    wrap.appendChild(reply);
  }
  /* The machine, as AnyConnect described it to the head end. Worth its own
     block: on a refusal it is the one thing that says which machine to go
     and look at. */
  var more = a.more || {};
  var tlv = [];
  ASKED_TLV.forEach(function (one) {
    var v = more['tlv:' + one[0]];
    if (v) tlv.push([one[1], v]);
  });
  if (tlv.length) {
    var dl = el('dl', 'fields');
    tlv.forEach(function (one) {
      dl.appendChild(el('dt', '', one[0]));
      var dd = el('dd');
      dd.textContent = one[1];
      dl.appendChild(dd);
    });
    var fold = el('details', 'fold');
    var sum = el('summary', '', 'The machine it was asked from');
    sum.appendChild(el('span', 'n', tlv.length + ' thing(s)'));
    fold.appendChild(sum);
    var inner = el('div', 'body');
    inner.appendChild(dl);
    fold.appendChild(inner);
    wrap.appendChild(fold);
  }
  /* ...and the packet itself, whole, for somebody who knows RADIUS. */
  var names = Object.keys(more).filter(function (n) { return n.indexOf('tlv:') !== 0; });
  if (names.length) {
    var all = el('details', 'fold');
    var s2 = el('summary', '', 'Every attribute on the packet');
    s2.appendChild(el('span', 'n', names.length + ' attribute(s)'));
    all.appendChild(s2);
    var box2 = el('div', 'body');
    box2.appendChild(fieldList(more, names));
    all.appendChild(box2);
    wrap.appendChild(all);
  }
  return wrap;
}

function fieldList(fields, names) {
  var dl = el('dl', 'fields');
  names.forEach(function (n) {
    dl.appendChild(el('dt', '', n));
    var dd = el('dd');
    var v = fields[n];
    if (Array.isArray(v)) {
      /* ISE repeats a field name rather than joining its values, and some of
         them repeat thirty times. A list, so thirty Steps do not become one
         unreadable line. */
      var ul = el('ul');
      v.forEach(function (one) { ul.appendChild(el('li', '', one)); });
      dd.appendChild(ul);
    } else {
      dd.textContent = v;
    }
    dl.appendChild(dd);
  });
  return dl;
}

/* ==========================================================================
   Events, and the daemon's own log
   ========================================================================== */
var EV_ASKED = 0;
function loadEvents() {
  /* Paged in the database: this table only ever grows, and a year of it is
     hundreds of thousands of rows. Sending all of them so the page can show
     fifty is the kind of thing that works for a week. */
  var per = Number($('ev-limit').value || 100);
  var q = ['limit=' + per, 'offset=' + (PAGE.events * per),
           $('ev-kind').value ? 'kind=' + $('ev-kind').value : '',
           $('ev-q').value.trim() ? 'q=' + encodeURIComponent(
             qRewrite($('ev-q').value.trim(), qMaps('events'))) : '',
           sortArgs(SORTS.events)]
    .filter(Boolean).join('&');
  /* Which question this answer belongs to: typing in the search asks again
     as it goes, and a slower answer to an older word used to land last and
     be drawn under the newer one. */
  var mine = ++EV_ASKED;
  api('events&' + q, undefined, {lane: 'events'}).then(function (d) {
    if (mine !== EV_ASKED) return;
    var body = $('ev-table').querySelector('tbody');
    serverSortHeads($('ev-table').tHead.rows[0], SORTS.events, EVENT_SORT_KEYS, function () {
      PAGE.events = 0;
      loadEvents();
    });
    clear(body);
    $('ev-empty').hidden = !!d.events.length;
    $('ev-empty').textContent = ($('ev-q').value.trim() || $('ev-kind').value)
      ? 'Nothing matches'
      : 'Nothing yet';
    $('ev-count').textContent = (d.capped ? 'more than ' : '') + num(d.total || 0) + ' in all';
    pager('ev-pager', PAGE.events, per, d.total || 0, function (page) {
      PAGE.events = page;
      loadEvents();
    }, d.capped);
    d.events.forEach(function (r) {
      var tr = el('tr');
      tr._rec = r;
      tr.appendChild(stampCell(r.ts));
      var kind = el('td');
      /* Named the way the "kind" box above names it - "bans", not
         "block" - so the tag and the filter that picks it say the same.
         A kind the box does not list keeps the daemon's own name. (1.10.160) */
      var called = eventKindWords(r.kind);
      var mark = el('span', 'tag ' + (r.level === 'warn' ? 'warn'
        : (r.level === 'error' ? 'crit' : 'dim')), called || r.kind);
      mark.dataset.kind = r.kind || '';
      explain(mark, EVENT_SAYS[r.kind] || 'One kind of thing this daemon does.',
        '<div class="same">' + (r.level === 'error' ? 'Something went wrong.'
          : (r.level === 'warn' ? 'Worth reading: something changed, or somebody was kept '
             + 'out.' : 'Ordinary \u2014 it happened and nothing was wrong with it.'))
        + '</div>');
      /* The kind is a name the daemon files it under, and who is somebody's
         account: neither is a word to translate. An account called
         "service" read "služba" in Czech. */
      if (!called) noI18n(mark);
      kind.appendChild(mark);
      tr.appendChild(kind);
      tr.appendChild(noI18n(el('td', '', r.who || '')));
      /* What happened, as the daemon wrote it down: a record, like a line of
         a log, and kept in the words it was written in. Matched piece by
         piece, a few came out in Czech and most did not - "admin
         přihlášeno z" beside "the account x was removed". */
      tr.appendChild(noI18n(el('td', '', r.detail || '')));
      body.appendChild(tr);
    });
    optColumns($('ev-table'), OPT_EVENTS);
  }).catch(oops);
}
$('ev-q').addEventListener('input', debounce(function () {
  PAGE.events = 0;
  loadEvents();
}, 350));
$('ev-kind').onchange = function () { PAGE.events = 0; loadEvents(); };
$('ev-clear').onclick = function () {
  $('ev-q').value = '';
  $('ev-kind').value = '';
  PAGE.events = 0;
  sortReset(SORTS.events);
  loadEvents();
};
/** What the "kind" box calls a kind of event, in the words it was written
    in (the translation is the page's to do), or '' when it does not list it. */
var EVENT_KIND_WORDS = null;
function eventKindWords(kind) {
  if (!EVENT_KIND_WORDS) {
    EVENT_KIND_WORDS = {};
    Array.prototype.forEach.call($('ev-kind').options, function (o) {
      if (o.value) EVENT_KIND_WORDS[o.value] = String(srcText(o) || o.text).trim();
    });
  }
  return Object.prototype.hasOwnProperty.call(EVENT_KIND_WORDS, kind || '')
    ? EVENT_KIND_WORDS[kind] : '';
}
$('ev-limit').onchange = function () { PAGE.events = 0; loadEvents(); };

$('log-read').onclick = function () {
  busy($('log-read'), true);
  api('log&limit=' + $('log-lines').value).then(function (d) {
    var host = $('log-out');
    clear(host);
    d.lines.forEach(function (line) { host.appendChild(el('div', '', line)); });
    host.scrollTop = host.scrollHeight;
  }).catch(oops).then(function () { busy($('log-read'), false); });
};

/* ==========================================================================
   Work that is watched rather than waited for
   --------------------------------------------------------------------------
   Filling a country list on a router is forty thousand lines over ssh: a
   request that waited for it would be cut off by the web server long before
   it finished. So the daemon answers at once with an id, does the work on a
   thread of its own, and this follows it.
   ========================================================================== */
function watchJob(jid, title, done, words) {
  var bar, said, lines, seen = 0, missed = 0;
  modal(title, function (body) {
    var p = el('p', 'note');
    p.textContent = words || ('This is happening on the router now. You can close this and it '
      + 'carries on; what it did ends up in Events either way.');
    body.appendChild(p);
    bar = el('div', 'prog idle');
    bar.appendChild(el('span'));
    body.appendChild(bar);
    said = el('p', 'btnhelp', 'starting…');
    said.style.fontWeight = '600';
    body.appendChild(said);
    lines = el('div', 'joblines');
    body.appendChild(lines);
  }, [{words: 'Close', close: true}]);

  /* Closing the popup stops the drawing, not the watching (1.10.176): the
     popup says the job carries on, and what comes after it - the country
     list after the ban list, the page drawn again after an erase - was
     never started once somebody had closed it. */
  var shut = false;
  MODAL_CLOSE = function () { shut = true; };

  function poll() {
    api('job&id=' + encodeURIComponent(jid), undefined, {quiet: shut}).then(function (d) {
      var job = d.job;
      missed = 0;                          /* one that worked wipes the slate */
      if (job.total > 0) {
        bar.className = 'prog' + (job.done ? (job.ok ? ' done' : ' bad') : '');
        bar.firstChild.style.width =
          Math.min(100, Math.round(100 * job.done_n / job.total)) + '%';
      } else if (job.done) {
        bar.className = 'prog' + (job.ok ? ' done' : ' bad');
        bar.firstChild.style.width = '100%';
      }
      /* Never "14 000 of 10 306": a count past its own total is a total
         that was wrong, and saying it anyway makes the job look broken when
         it is not. Past the end, only the count is said. */
      said.textContent = (job.total && job.done_n <= job.total
        ? num(job.done_n) + ' of ' + num(job.total) + ' · '
        : (job.done_n ? num(job.done_n) + ' · ' : '')) + job.last;
      (job.lines || []).slice(seen).forEach(function (one) {
        var div = el('div');
        div.appendChild(el('b', '', shortStamp(one.at)));
        div.appendChild(document.createTextNode(' ' + one.words));
        lines.appendChild(div);
      });
      seen = (job.lines || []).length;
      lines.scrollTop = lines.scrollHeight;
      if (!job.done) { setTimeout(poll, shut ? 2000 : 900); return; }
      if (!shut) MODAL_CLOSE = null;
      if (job.ok) {
        toast((job.result && job.result.message) || 'done', 'good');
      } else {
        toast(job.error || 'it did not work', 'bad');
      }
      if (done) done(job);
      tick();
    }).catch(function (e) {
      /* One poll failing is not the job failing. The relay's socket to the
         daemon times out, that one answer comes back 503, and the job goes
         on and finishes perfectly well a few seconds later - but this
         stopped asking on the first one, so the bar sat red and frozen over
         work that had succeeded. It says so and keeps asking, and gives up
         only after a run of them. */
      missed += 1;
      if (missed < 10) {
        said.textContent = 'the daemon did not answer just then \u2014 still asking';
        setTimeout(poll, 2000);
        return;
      }
      said.textContent = String(e.message || e);
      bar.className = 'prog bad';
    });
  }
  setTimeout(poll, 400);
}
</script>
<script nonce="<?= h($nonce) ?>">
'use strict';
/* ==========================================================================
   The router
   ========================================================================== */
/* ---- are the two lists in sync, and if not, where ----------------------
   The ban list and the country list are written by different jobs, at
   different times, for different reasons, and either can be out of sync on
   its own. Reading that off two paragraphs and a table is work; this says it
   in two cards with a colour, a sentence and the numbers behind it. */
function syncCard(one, kind) {
  var known = one.known !== false;
  var state = one.in_sync;
  var off = (kind === 'geo' && !one.on);
  var mood = off ? 'dim' : (!known ? 'warn' : (state ? 'ok' : 'crit'));
  var card = el('div', 'synccard ' + mood);

  var top = el('div', 'sync-top');
  var name = el('span', 'sync-name');
  name.appendChild(el('span', '', kind === 'geo' ? 'The country list' : 'The banned list'));
  if (one.list) name.appendChild(el('span', 'mono sync-which', one.list));
  top.appendChild(name);
  var tag = el('span', 'tag ' + (off ? 'dim' : (!known ? 'warn' : (state ? 'ok' : 'crit'))));
  tag.innerHTML = iconMarkup(off ? 'cancel' : (!known ? 'info' : (state ? 'check' : 'ban')), 13)
    + '<span>' + (off ? 'switched off'
       : (!known ? 'cannot be told' : (state ? 'in sync' : 'out of sync'))) + '</span>';
  tag.classList.add('banmark');
  top.appendChild(tag);
  card.appendChild(top);

  var says = el('p', 'sync-says');
  if (off) {
    says.textContent = 'No country list is switched on, so nothing of ours is expected on the '
      + 'router for it and nothing is compared.';
  } else if (one.trouble) {
    says.textContent = one.trouble;
  } else if (!known && kind === 'geo') {
    says.textContent = one.want === null || one.want === undefined
      ? 'Nothing here has filled this list yet, so there is nothing to compare what is on the '
        + 'router against. Press “Put the lists on it” once and this starts answering.'
      : 'The router would not say how many entries this list holds, so it cannot be compared. '
        + 'That is not the same as the list being empty.';
  } else if (state) {
    says.textContent = kind === 'geo'
      ? 'Every entry the chosen countries come to is on the router, and no more.'
      : 'Every address banned here is on the router, and nothing of ours is on it that is not '
        + 'banned here.';
  } else {
    var bits = [];
    if (one.missing) bits.push(num(one.missing) + ' banned here but not on the router');
    if (one.extra) bits.push(num(one.extra) + ' of ours on the router that nothing bans');
    var noneChosen = kind === 'geo' && !(one.countries || []).length;
    if (kind === 'geo' && one.on_router !== one.want) {
      bits.push(num(one.on_router) + ' on the router against ' + num(one.want) + ' expected');
    }
    says.textContent = (bits.join(' · ') || 'the two do not match')
      + (noneChosen
        ? '. No country is chosen, so nothing is filled: “Empty it on the router…” under '
          + 'Settings → GeoIP takes what is left there off.'
        : '. Pressing “Put the lists on it” settles it.');
  }
  card.appendChild(says);

  var facts = el('div', 'sync-facts');
  var fact = function (k, v) {
    if (v === undefined || v === null || v === '') return;
    var one2 = el('div', 'sync-fact');
    one2.appendChild(el('span', 'k', k));
    one2.appendChild(el('span', 'v', v));
    facts.appendChild(one2);
  };
  if (kind === 'geo') {
    fact('On the router', one.on_router === null || one.on_router === undefined
      ? 'could not be counted' : num(one.on_router));
    fact('Expected', one.want === null || one.want === undefined
      ? 'nothing filled it yet'
      : (!(one.countries || []).length ? '0 \u2014 no country chosen' : num(one.want)));
    fact('Countries', (one.countries || []).join(', ') || 'none chosen');
    fact('Filled', one.at ? shortStamp(one.at) : 'never');
  } else {
    fact('On the router', num(one.on_router));
    fact('Banned here', num(one.want));
    fact('Not reached it', num(one.missing));
    fact('Ours, nothing bans', num(one.extra));
    fact('Theirs, left alone', num(one.theirs));
    fact('Written', one.at ? shortStamp(one.at) : 'never');
  }
  card.appendChild(facts);
  if (one.extra_few && one.extra_few.length) {
    var extra = el('p', 'sync-extra mono');
    extra.textContent = one.extra_few.join(', ')
      + (one.extra > one.extra_few.length ? ' and ' + (one.extra - one.extra_few.length)
         + ' more' : '');
    explain(extra, 'These carry this daemon’s mark on the router but nothing here bans them '
      + 'any more — a ban that ran out or was lifted while the router could not be reached. '
      + 'The next sync takes them off.');
    card.appendChild(extra);
  }
  return card;
}

/** The pair, and whether they are saying the same thing.

    On two firewalls in high availability this is the question the page
    exists to answer: whichever of them takes the traffic next has to already
    hold every address the other does, so one of them being behind is one of
    them about to let somebody in. */
function pairCard(d) {
  var card = el('div', 'card synccard');
  var head = el('div', 'fline');
  head.style.cssText = 'display:flex;gap:10px;align-items:center;flex-wrap:wrap';
  var title = el('h3', '', 'The pair');
  title.style.margin = '0';
  head.appendChild(title);
  if (d.agree === true) {
    head.appendChild(el('span', 'tag ok', 'both carrying the same'));
  } else if (d.agree === false) {
    head.appendChild(el('span', 'tag crit', num(d.differs_n) + ' address(es) differ'));
  } else {
    head.appendChild(el('span', 'tag warn', 'one of them could not be read'));
  }
  card.appendChild(head);
  var says = el('p', 'note');
  says.innerHTML = d.agree === true
    ? 'Both firewalls are carrying exactly the same addresses of ours. Whichever of them takes '
      + 'the traffic is already dropping everything the other is.'
    : (d.agree === false
       ? 'The two are <b>not</b> carrying the same addresses of ours, so whichever takes the '
         + 'traffic next may let through what the other is dropping. <i>Put the lists on it</i> '
         + 'puts it right; if it keeps happening, one of them is refusing and the line below '
         + 'says why.'
       : 'One of them could not be read just now, so the two cannot be compared. What is below '
         + 'is what each of them last said.');
  card.appendChild(says);

  var wrap = el('div', 'scroll');
  var table = el('table', 'plain');
  var thead = el('thead'), tr = el('tr');
  headCells(['Which firewall', 'Address', {words: 'Ours on it', cls: 'num'},
             {words: 'Theirs', cls: 'num'}, {words: 'Behind by', cls: 'num'},
             'Last written', 'Right now'])
    .forEach(function (th) { tr.appendChild(th); });
  thead.appendChild(tr);
  table.appendChild(thead);
  var body = el('tbody');
  (d.firewalls || []).forEach(function (w) {
    var line = el('tr');
    line.appendChild(el('td', '', w.words));
    var addr = el('td');
    addr.appendChild(el('span', 'mono', w.host || '–'));
    line.appendChild(addr);
    line.appendChild(el('td', 'num', w.on_router === null || w.on_router === undefined
                        ? '–' : num(w.on_router)));
    line.appendChild(el('td', 'num', w.theirs === null || w.theirs === undefined
                        ? '–' : num(w.theirs)));
    var behind = el('td', 'num');
    if (w.missing_n === null || w.missing_n === undefined) {
      behind.textContent = '–';
    } else if (w.missing_n) {
      var n = el('span', 'tag crit', num(w.missing_n));
      explain(n, 'This firewall is missing ' + num(w.missing_n) + ' address(es) that this '
        + 'machine says should be on it'
        + ((w.missing || []).length ? ': ' + w.missing.join(', ')
           + (w.missing_n > w.missing.length ? ', and more' : '') : '')
        + '. A sync puts them on.');
      behind.appendChild(n);
    } else {
      behind.appendChild(el('span', 'tag ok', 'none'));
    }
    line.appendChild(behind);
    line.appendChild(w.at ? stampCell(w.at) : el('td', '', 'never'));
    var state = el('td');
    if (!w.reached) {
      var bad = el('span', 'tag crit', 'could not be read');
      explain(bad, w.trouble || 'It did not answer.');
      state.appendChild(bad);
    } else if (w.trouble) {
      var warn = el('span', 'tag warn', 'trouble');
      explain(warn, w.trouble);
      state.appendChild(warn);
    } else {
      state.appendChild(el('span', 'tag ok', 'answering'));
    }
    line.appendChild(state);
    body.appendChild(line);
  });
  table.appendChild(body);
  wrap.appendChild(table);
  card.appendChild(wrap);

  if (d.agree === false && (d.differs || []).length) {
    var which = el('p', 'btnhelp');
    which.innerHTML = 'On one but not the other: <span class="mono">'
      + d.differs.map(richText).join('</span>, <span class="mono">') + '</span>'
      + (d.differs_n > d.differs.length
         ? ' <span class="muted">and ' + num(d.differs_n - d.differs.length)
           + ' more</span>' : '');
    card.appendChild(which);
  }
  return card;
}

function syncState(state) {
  var box = el('div', 'syncgrid');
  box.appendChild(syncCard(state.blocked || {}, 'blocked'));
  box.appendChild(syncCard(state.geo || {}, 'geo'));
  return box;
}

/** The access list is made out of the bans, so it is only offered when
    there is banning to make one out of - and that is a setting somebody can
    change while this tab is open. */
function sayIfTheAclIsOffered() {
  var acl = $('router-ios');
  if (acl) acl.hidden = !(STATUS && STATUS.blacklist_on);
}

/* How long the last read of the firewall took, so the bar on the page can
   say how far along this one probably is. The firewall says nothing while it
   answers, so the bar is an estimate from that: it walks to nine tenths of
   the last time and then creeps, and it is never shown as finished until
   the answer is actually here. With no earlier read to go by it simply
   sweeps. Shown on the page, across the card, and not in a popup. */
var ROUTER_TOOK = 0;
var ROUTER_GOING = null;
function routerGoing(on) {
  var box = $('router-going');
  if (!box) return;
  var fill = box.querySelector('.bar span');
  var says = box.querySelector('.says');
  if (ROUTER_GOING) { clearInterval(ROUTER_GOING.timer); clearTimeout(ROUTER_GOING.show); }
  if (!on) {
    var was = ROUTER_GOING;
    ROUTER_GOING = null;
    if (!was || box.hidden) { box.hidden = true; return; }
    fill.classList.remove('creeping');
    fill.style.width = '100%';
    says.textContent = 'Read.';
    setTimeout(function () { if (!ROUTER_GOING) box.hidden = true; }, 450);
    return;
  }
  var started = Date.now();
  var expect = ROUTER_TOOK;
  function paint() {
    var gone = Date.now() - started;
    var secs = Math.round(gone / 1000);
    if (expect > 0) {
      fill.classList.remove('creeping');
      var share = gone < expect * 0.9 ? gone / expect
        : 0.9 + 0.09 * (1 - Math.exp(-(gone - expect * 0.9) / Math.max(2000, expect)));
      fill.style.width = Math.min(99, Math.round(100 * share)) + '%';
    } else {
      fill.classList.add('creeping');
    }
    says.textContent = 'Reading what the firewall is carrying\u2026 ' + secs + ' s'
      + (expect > 0 ? ' (the last read took ' + Math.max(1, Math.round(expect / 1000)) + ' s)'
                    : '');
    says.title = says.textContent;
  }
  ROUTER_GOING = {
    timer: setInterval(paint, 250),
    /* Not for an answer the daemon already holds: that one is back before
       a bar could be seen, and a bar that flashes is worse than none. */
    show: setTimeout(function () {
      fill.style.width = '0';
      paint();
      box.hidden = false;
    }, 300)
  };
}

function readRouter(fresh) {
  var host = $('router-out');
  sayIfTheAclIsOffered();
  if (!STATUS || !STATUS.mikrotik.ready) {
    clear(host);
    host.appendChild(el('p', 'center', 'No firewall is set up. Give it an address and a list '
                                       + 'name under Settings.'));
    return;
  }
  busy($('router-read'), true);
  $('router-note').textContent = '';
  routerGoing(true);
  /* Numbered (1.10.187): a press and the read after a sync could overlap,
     and whichever answered last was drawn - the older one as often as not -
     while the first to finish hid the bar of the one still going. */
  var mine = ++ROUTER_ASKED;
  /* What the router holds is kept by the daemon for a few seconds; the
     button asks it afresh (an administrator's press does). */
  api(fresh === true ? 'router&fresh=1' : 'router').then(function (d) {
    if (mine !== ROUTER_ASKED) return;
    $('router-when').textContent = 'read ' + ago(d.at) + ' · took ' + d.read_in_ms + ' ms';
    if (Number(d.read_in_ms) > 0) ROUTER_TOOK = Number(d.read_in_ms);
    $('router-note').textContent = d.trouble ? '' : '';
    clear(host);
    if (d.trouble) {
      var bad = el('div', 'offline');
      bad.textContent = 'The last read failed: ' + d.trouble;
      host.appendChild(bad);
    }
    var ours = d.carrying.filter(function (r) { return r.ours; });
    var theirs = d.carrying.filter(function (r) { return !r.ours; });

    /* Both lists, side by side, answering the one question somebody opens
       this page for: is what the router is carrying what this says it should
       be carrying - and if not, which one and by how much. */
    if ((d.firewalls || []).length > 1) host.appendChild(pairCard(d));
    host.appendChild(syncState(d.state || {}));

    var head = el('p', 'note');
    head.innerHTML = '<b>' + ours.length + '</b> entr' + (ours.length === 1 ? 'y' : 'ies')
      + ' of ours on <span class="mono">' + richText(d.list) + '</span>'
      + (theirs.length ? ', and <b>' + theirs.length + '</b> somebody else put there, which are '
         + 'never touched' : '')
      + (d.not_carried.length ? '. <b>' + (d.not_carried_n || d.not_carried.length)
         + '</b> banned here have not reached it.' : '.');
    host.appendChild(head);

    if (d.not_carried.length) {
      var warn = el('details', 'fold');
      warn.open = true;
      var s = el('summary', '', '⚠️ Banned here, but the firewall is not dropping them');
      explain(s, 'Addresses this machine says are banned that were not on the list when it was '
        + 'last read. Until a sync puts them on, they reach the VPN exactly as if they had '
        + 'never been banned. On a pair, an address missing from only one of the two is in the '
        + 'table above instead.');
      s.appendChild(el('span', 'n', num(d.not_carried_n || d.not_carried.length)
                                    + ' address(es)'));
      warn.appendChild(s);
      var inner = el('div', 'body');
      var why = el('p', 'note');
      why.textContent = 'Either the router has not been written to since these were banned, or '
        + 'writing to it failed. Pressing \u201cPut the lists on it\u201d settles both.';
      inner.appendChild(why);
      /* Searched and paged like the router's own tables (1.10.187): after
         the list on the router was emptied this was every ban there is,
         thousands of rows put on the page at once. */
      if ((d.not_carried_n || 0) > d.not_carried.length) {
        inner.appendChild(el('p', 'note', 'The first ' + num(d.not_carried.length)
          + ' of them are shown.'));
      }
      inner.appendChild(listView({
        key: 'router-missing',
        rows: d.not_carried,
        per: 50,
        placeholder: 'an address, a country, a reason\u2026',
        hay: function (r) {
          return [r.address, r.country, r.why, r.family].filter(Boolean).join(' ');
        },
        draw: function (page, where) {
          where.appendChild(rowsTable(['Address', 'Country', 'Why', 'Since'],
            page.map(function (r) {
              return [r.address, r.country || '–', (r.why || '').slice(0, 70),
                      r.since ? shortStamp(r.since) : ''];
            })));
        }
      }));
      warn.appendChild(inner);
      host.appendChild(warn);
    }

    host.appendChild(routerTable('Ours, on the router', ours, true));
    if (theirs.length) {
      host.appendChild(routerTable('Somebody else’s, left exactly as they are', theirs,
                                   false));
    }
    if (d.geo) host.appendChild(geoCarrying(d.geo));
    explainWhatWasDrawn(host);
  }).catch(function (e) {
    if (mine !== ROUTER_ASKED) return;
    clear(host);
    var bad = el('div', 'offline');
    bad.textContent = String(e.message || e);
    host.appendChild(bad);
  }).then(function () {
    if (mine !== ROUTER_ASKED) return;
    busy($('router-read'), false);
    routerGoing(false);
  });
}
var ROUTER_ASKED = 0;

/* The second list on the same router: whole countries, kept apart from the
   banning and touched by nothing in it. It is counted rather than read back -
   a country is tens of thousands of lines and reading them all to say how
   many there are would take minutes and tell nobody anything. */
function geoCarrying(g) {
  var box = el('details', 'fold');
  box.open = true;
  var s = el('summary', '', 'The country list, on the same firewall');
  explain(s, 'The other address list this daemon keeps: whole countries, filled from the '
    + 'country database and pointed at by a rule you write yourself. It is counted on the '
    + 'firewall rather than read back, because a country list is tens of thousands of lines '
    + 'and the number is the only part anybody needs.');
  var n = el('span', 'n');
  if (!g.on) {
    n.textContent = 'switched off';
  } else if (g.trouble) {
    n.textContent = 'could not be counted';
  } else if (g.total !== undefined) {
    n.textContent = num(g.total) + ' entr' + (g.total === 1 ? 'y' : 'ies');
  }
  s.appendChild(n);
  box.appendChild(s);
  var body = el('div', 'body');

  if (!g.on) {
    body.appendChild(el('p', 'btnhelp',
      'The country list is switched off, so nothing of it is on the router. Switch it on '
      + 'under Settings \u2192 GeoIP, choose the countries, and it is filled from the '
      + 'country database.'));
    box.appendChild(body);
    return box;
  }
  if (!g.list) {
    body.appendChild(el('p', 'btnhelp', 'It has no name yet, so there is nothing to fill. '
      + 'Give it one under Settings \u2192 GeoIP \u2014 it must not be the same name as the '
      + 'blocked list.'));
    box.appendChild(body);
    return box;
  }

  var head = el('div', 'kv-block');
  function kv(k, v) {
    var line = el('div', 'kv');
    line.appendChild(el('span', 'k', k));
    var val = el('span', 'v');
    if (v instanceof Node) val.appendChild(v); else val.textContent = v;
    line.appendChild(val);
    head.appendChild(line);
  }
  kv('The list on the router', el('span', 'mono', g.list));
  if (g.trouble) {
    kv('Trouble', explain(el('span', 'tag crit', g.trouble),
      'What went wrong the last time this asked the firewall about the country list. It is '
      + 'whatever the router or ssh said, whole. Nothing is known about the list while this is '
      + 'here — which is not the same as the list being empty.'));
  } else if (g.carrying) {
    kv('It is carrying', num(g.carrying.v4 || 0) + ' IPv4 \u00b7 '
       + num(g.carrying.v6 || 0) + ' IPv6');
    /* What is on it against what the last fill put there. Entries against
       entries: the database holds ranges, and a range hardly ever falls on a
       single prefix boundary, so one range becomes several lines on the
       router. Comparing ranges with lines said "more than expected" about a
       list that was exactly right. */
    var want = g.should_be_entries;
    var have = g.total || 0;
    var gap = el('span');
    if (!g.should_be) {
      gap.textContent = 'no countries are chosen, so nothing should be on it';
    } else if (want === null || want === undefined) {
      gap.appendChild(el('span', 'tag dim', 'never filled from here'));
      gap.appendChild(document.createTextNode(' the chosen countries come to '
        + num(g.should_be) + ' range(s), which become rather more lines than that '
        + 'on the router'));
    } else if (have >= want * 0.98) {
      gap.appendChild(el('span', 'tag ok', 'in sync'));
      gap.appendChild(document.createTextNode(' the last fill put ' + num(want)
        + ' line(s) on it'));
    } else {
      gap.appendChild(el('span', 'tag ' + (have ? 'warn' : 'crit'),
                         have ? 'behind' : 'empty'));
      gap.appendChild(document.createTextNode(' the last fill sent ' + num(want)
        + ' line(s) and ' + (have ? 'only ' + num(have) + ' are there' : 'none are there')
        + ' \u2014 press Fill it under Settings \u2192 GeoIP'));
    }
    kv('Against the last fill', gap);
    if (g.trouble_filling) {
      kv('The last fill said', explain(el('span', 'tag crit', g.trouble_filling),
        'What went wrong the last time this tried to put the country list on. The ranges here '
        + 'are unchanged; what is on the firewall is whatever was there before the attempt.'));
    }
  }
  var flags = el('span', 'cc-row');
  (g.countries || []).forEach(function (c) {
    var one = el('span', 'cc-one');
    one.appendChild(countryBadge(c.cc));
    one.appendChild(el('span', 'muted small', num((c.v4 || 0) + (c.v6 || 0))));
    flags.appendChild(one);
  });
  kv('Countries', (g.countries || []).length ? flags : 'none are chosen');
  kv('Last filled', g.at ? (stamp(g.at) + '  \u00b7  ' + ago(g.at)) : 'never');
  kv('The country database here', g.geo_rows
    ? (num(g.geo_rows) + ' range(s), fetched ' + (g.geo_at ? ago(g.geo_at) : 'never'))
    : 'not fetched yet');
  body.appendChild(head);
  body.appendChild(el('p', 'btnhelp',
    'Nothing in the banning touches this list, and nothing in this list touches the banning. '
    + 'What the router does with it \u2014 accept, drop, mangle \u2014 is the router\u2019s '
    + 'business; this only keeps it filled. It is filled and emptied under '
    + 'Settings \u2192 GeoIP.'));
  box.appendChild(body);
  return box;
}

function routerTable(title, rows, ours) {
  var box = el('details', 'fold');
  box.open = ours;
  var s = el('summary', '', title);
  s.appendChild(el('span', 'n', num(rows.length) + ' entr' + (rows.length === 1 ? 'y' : 'ies')));
  explain(s, ours
    ? 'Every entry on the list that carries this daemon’s own mark, read from the firewall '
      + 'rather than remembered, with what is known here about each address beside it. These '
      + 'are the ones a sync adds and removes.'
    : 'Entries on the same list that somebody else put there. Nothing here ever adds, changes '
      + 'or removes one of them — they are shown so that the numbers add up and so that an '
      + 'address being dropped for a reason this machine knows nothing about is not a mystery.');
  box.appendChild(s);
  var inner = el('div', 'body');
  if (!rows.length) {
    inner.appendChild(el('p', 'center', 'Nothing.'));
  } else {
    /* A busy router carries hundreds of these, so the list is searched and
       paged rather than poured onto the page whole. */
    inner.appendChild(listView({
      key: 'router-' + (ours ? 'ours' : 'theirs'),
      rows: rows,
      per: 50,
      placeholder: 'an address, a country, a reason\u2026',
      explain: 'Searches every entry in this group, not the page in front of you \u2014 the '
        + 'address, the country, why it is there and the comment on the router.',
      countryOf: function (r) { return r.country; },
      hay: function (r) {
        return [r.address, r.country, r.why, r.comment, r.family,
                r.forever ? 'for good' : ''].filter(Boolean).join(' ');
      },
      draw: function (page, host) { host.appendChild(routerRows(page, ours)); }
    }));
  }
  box.appendChild(inner);
  return box;
}

function routerRows(rows, ours) {
  var wrap = el('div', 'scroll');
  var table = el('table', ours ? 'rows' : 'plain');
  var thead = el('thead'), tr = el('tr');
  ['Address', 'Family', 'Country', ours ? 'Why it is there' : 'Comment', 'Left', ''].forEach(
    function (hh) { tr.appendChild(el('th', '', hh)); });
  thead.appendChild(tr);
  table.appendChild(thead);
  var body = el('tbody');
  (function () {
    rows.forEach(function (r) {
      var line = el('tr');
      if (ours) line.onclick = function () { lookUp(r.address.split('/')[0]); };
      var td = el('td');
      td.appendChild(el('span', 'mono', r.address));
      if ((r.members || []).length) {
        var tag = el('span', 'tag violet', 'folded ×' + r.members.length);
        tag.style.marginLeft = '7px';
        td.appendChild(tag);
      }
      line.appendChild(td);
      line.appendChild(el('td', '', r.family));
      var cc = el('td');
      cc.appendChild(countryBadge(r.country));
      line.appendChild(cc);
      line.appendChild(el('td', '', ours ? (r.why || r.comment || '')
                          : (r.comment || '(no comment)')));
      line.appendChild(el('td', '', !r.known ? '–'
        : (r.forever ? 'for good' : span(r.left))));
      var act = el('td');
      if (ours && !r.known) {
        var tag2 = el('span', 'tag warn', 'not ours any more');
        tag2.title = 'The router is carrying this with our mark on it, but nothing here knows '
          + 'about it. The next sync takes it off.';
        act.appendChild(tag2);
      }
      line.appendChild(act);
      body.appendChild(line);
    });
  })();
  table.appendChild(body);
  wrap.appendChild(table);
  return wrap;
}

$('router-read').onclick = function () { readRouter(true); };
$('router-sync').onclick = function () { syncRouter(); };
explain($('router-sync'), 'Puts <b>everything</b> this daemon carries on to the router in one '
  + 'press: first the banned addresses, so the list there says exactly what this says, and then '
  + 'the country list when one is switched on. Only entries carrying this daemon\u2019s mark are '
  + 'touched; anything you put on either list by hand stays.');
$('router-purge').onclick = function () { purgeRouter(); };
$('router-ios').onclick = function () { iosAcl(); };
/* ...and the same thing from the settings page, where the ending is typed:
   what somebody has just written, in the file it is going to end up in. */
if ($('ios-show')) $('ios-show').onclick = function () { iosAcl(); };

/* ---- an access list for a router this machine does not talk to ----------
   The Mikrotik is kept in step over ssh, second by second. A Cisco somebody
   else looks after is not something to sign in to from here, so what it gets
   is a file: made at the moment it is asked for, out of the addresses that
   are out for good, and pasted by a person who is looking at it.

   Only the permanent ones on purpose. A ban on a clock has minutes left by
   the time anybody has pasted it, and nothing here ever goes back to that
   router to take one off again. */
function iosAcl() {
  api('iosacl').then(function (d) { showIosAcl(d); }).catch(oops);
}

function showIosAcl(d) {
  modal('An access list for a Cisco router', function (body) {
    var p = el('p', 'note');
    p.innerHTML = d.family === 'ipv6'
      ? 'The <b>' + num((d.ranges || 0) + (d.singles || 0)) + '</b> IPv6 address(es) banned '
        + '<b>for good</b> right now, as an IPv6 access list.'
      : 'The <b>' + num((d.ranges || 0) + (d.singles || 0)) + '</b> address(es) banned '
        + '<b>for good</b> right now, as an IOS extended access list \u2014 '
        + num(d.ranges || 0) + ' range(s) and ' + num(d.singles || 0) + ' single '
        + 'address(es). Addresses on a clock are left out on purpose: they lapse here, and '
        + 'nothing ever goes back to that router to take one off. The list\u2019s name, and '
        + 'what ends it, are in Settings \u2192 Reaching the firewall.';
    body.appendChild(p);
    if (d.skipped) {
      var also = el('p', 'note');
      also.innerHTML = '<b>' + num(d.skipped) + '</b> address(es) of the other family are not '
        + 'in this one \u2014 a router keeps IPv4 and IPv6 in two different access lists. '
        + 'The button below writes the other.';
      body.appendChild(also);
    }
    var ends = el('p', 'note');
    ends.innerHTML = 'The last <b>' + num((d.tail || []).length) + '</b> line(s) are yours, '
      + 'out of Settings \u2192 Reaching the firewall. Everything above them is made afresh '
      + 'here every time this is asked for.';
    body.appendChild(ends);
    if ((d.faults || []).length) {
      /* Only reachable by editing config.json by hand, because the page and
         the command line both refuse a line like this before it is saved.
         Said loudly all the same: it is going into a router. */
      var bad = el('p', 'note');
      bad.style.color = 'var(--crit)';
      bad.textContent = 'Careful: ' + d.faults.length + ' line(s) of that ending are not '
        + 'something a router will take \u2014 line ' + d.faults[0].n + ', '
        + d.faults[0].why;
      body.appendChild(bad);
    }
    var box = el('pre', 'acltext');
    box.textContent = d.text || '';
    body.appendChild(box);
  }, [
    {words: 'Save it as a file', cls: 'primary', icon: 'download',
     go: function () { saveText((d.name || 'access-list') + '.txt', d.text || ''); }},
    {words: 'Copy it', icon: 'copy', go: function () { copyAcl(d.text || ''); }},
    {words: d.family === 'ipv6' ? 'The IPv4 one' : 'The IPv6 one', icon: 'globe',
     go: function () {
       api('iosacl&family=' + (d.family === 'ipv6' ? 'ipv4' : 'ipv6'))
         .then(function (other) { showIosAcl(other); }).catch(oops);
     }},
    {spacer: true}, {words: 'Close', close: true}
  ]);
}

function copyAcl(text) {
  copyText(text, 'the access list is on the clipboard');
}

/** A file the browser writes itself, out of text this page already has.
    Everything between here and the daemon hands back JSON, so a file that
    came the other way would arrive as JSON and could not be pasted. */
function saveText(name, text) {
  try {
    var blob = new Blob([text], {type: 'text/plain;charset=utf-8'});
    var url = URL.createObjectURL(blob);
    var a = document.createElement('a');
    a.href = url;
    a.download = name;
    document.body.appendChild(a);
    a.click();
    setTimeout(function () { URL.revokeObjectURL(url); a.remove(); }, 400);
  } catch (e) {
    oops('this browser would not save the file: ' + e);
  }
}

/* One press, everything this daemon puts on the router: the banned addresses
   first and the countries after them. Settling half of it is what leaves
   somebody looking at an empty country list beside a perfectly correct ban
   list and no button that fixes it. */
function syncRouter() {
  var button = $('router-sync');
  if (button && button.disabled) return;
  if (button) busy(button, true);
  api('mikrotik', {sync: true}).then(function (d) {
    watchJob(d.job, 'Putting everything on the router', function () {
      readRouter(true);
    });
  }).catch(oops).then(function () { if (button) busy(button, false); });
}

/* Taking ours off, and only ours. The words matter here more than anywhere
   else on the page: somebody pressing this is about to change a firewall. */
function purgeRouter() {
  var which = 'both';
  modal('Take our address lists off the router', function (body) {
    var p = el('p', 'note');
    p.innerHTML =
      'This removes the entries this daemon put on the router and <b>nothing else</b>. It finds '
      + 'them by the comment it writes on every one of them, so:'
      + '<ul>'
      + '<li>an address you added to the same list by hand has no such comment and <b>stays</b>;'
      + '</li>'
      + '<li>every other address list on the router is never named in the commands and is '
      + '<b>untouched</b>;</li>'
      + '<li>your firewall rules, filters, routes and settings are <b>not touched at all</b> — '
      + 'a rule pointed at the list goes on working and simply matches nothing;</li>'
      + '<li>a list that ends up with no entries stops being listed on RouterOS by itself. That '
      + 'is how address lists work there, not something this does to it — the next sync '
      + 'brings it back.</li>'
      + '</ul>'
      + 'The bans themselves stay here. Pressing <i>Put the lists on it</i> afterwards puts '
      + 'them all back — the countries with them.';
    body.appendChild(p);
    var pick = el('div', 'set-item');
    pick.appendChild(el('label', '', 'Which of ours'));
    var select = el('select');
    [['both', 'both lists — the banned addresses and the countries'],
     ['blocked', 'only the banned addresses ('
       + ((STATUS && STATUS.mikrotik.list) || 'the ban list') + ')'],
     ['geo', 'only the country list ('
       + ((STATUS && STATUS.geolist.name) || 'the country list') + ')']].forEach(function (one) {
      var o = document.createElement('option');
      o.value = one[0];
      o.textContent = one[1];
      select.appendChild(o);
    });
    select.onchange = function () { which = select.value; };
    pick.appendChild(select);
    body.appendChild(pick);
  }, [
    {words: 'No, leave the router alone', close: true},
    {words: 'Take ours off', cls: 'danger', close: true, admin: true, go: function () {
      api('mikrotik', {purge: true, which: which}).then(function (d) {
        watchJob(d.job, 'Taking our address lists off the router', function () {
          readRouter(true);
          loadBans();
        });
      }).catch(oops);
    }}
  ]);
}
</script>
<script nonce="<?= h($nonce) ?>">
'use strict';
/* ==========================================================================
   The domain
   --------------------------------------------------------------------------
   What the Windows domain controllers wrote down. A different system from
   everything else on this page: nothing here is ever judged, nothing here can
   earn anybody a ban, and none of it is an authentication in the sense the
   rest of this dashboard means.

   It is here because half of what a VPN refusal means is written on a domain
   controller and nowhere else. "The VPN refused them four times" and "the
   domain locked the account at 08:12, from NB-NOVAK, through Outlook, because
   the password saved there is the old one" are the same morning, and only one
   of them is in an ISE log.
   ========================================================================== */
var WIN = null;
var WIN_ASKED = 0;

var WKIND = '';                  /* which group of events the list is showing */
var WPAGE = 0;
var WCOUNTS = {};
var WLIST = 0;

/* The window the cards at the top are counted over. The list underneath has
   a window of its own, because they are two questions: "what has been going
   on lately" and "find me this event". */
/* Which of the domain's two pages is open. The overview by default: it is
   what somebody opens this tab to see, and the events are where they go
   next. */
var WPAGE_SHOWN = 'over';

function winShowPage(which) {
  WPAGE_SHOWN = which === 'events' ? 'events' : 'over';
  $('w-page-over').hidden = WPAGE_SHOWN !== 'over';
  $('w-page-events').hidden = WPAGE_SHOWN !== 'events';
  Array.prototype.forEach.call($('w-pages').children, function (b) {
    var mine = b.dataset.page === WPAGE_SHOWN;
    b.classList.toggle('on', mine);
    b.setAttribute('aria-selected', String(mine));
  });
  /* The list is only asked for when it is being looked at - it is a page of
     the database, and drawing it behind a card nobody is reading is a query
     a minute for nothing. */
  if (typeof holdTheTallOnes === 'function') holdTheTallOnes();
  /* The overview holds the bar, so opening it asks for where the job has
     got to rather than waiting for the next round of the clock. */
  if (WPAGE_SHOWN === 'over') loadWindows();
  if (WPAGE_SHOWN === 'events') loadWinEvents();
  if (TAB === 'windows') writeHash();
  window.scrollTo({top: 0, behavior: 'smooth'});
}
Array.prototype.forEach.call(document.querySelectorAll('#w-pages button'),
  function (b) { b.onclick = function () { winShowPage(b.dataset.page); }; });

function winHours() { return Number($('w-window').value || 24); }

/* While a long job is going, ask again soon whatever else the page is
   doing - five seconds after the last answer came, not five seconds after
   it was asked for (1.10.187). Armed on the asking, a re-read of a big
   domain had four of the dearest answer the daemon gives running at once,
   each thrown away as the next arrived, and the list of events under it
   was started again every five seconds and never finished. */
var WIN_FLYING = 0;
function winAskSoon() {
  clearTimeout(window._goingSoon);
  window._goingSoon = setTimeout(function () {
    /* Only while this page is the one being looked at - the job is the
       daemon's and carries on alone. */
    if ((WIN_GOING || Date.now() < WIN_WATCH_UNTIL) && TAB === 'windows'
        && !document.hidden) loadWindows(true);
  }, 5000);
}
function loadWindows(again) {
  again = again === true;
  clearTimeout(window._goingSoon);
  /* The page's own asking again, while the last one is still out: that one
     is waited for. Somebody pressing something is never made to wait. */
  if (again && WIN_FLYING && Date.now() - WIN_FLYING < 120000) {
    winAskSoon();
    return;
  }
  var mine = ++WIN_ASKED;
  WIN_FLYING = Date.now();
  api('windows&hours=' + winHours()).then(function (d) {
    if (mine !== WIN_ASKED) return;
    WIN = d;
    drawWindows(d);
  }).catch(oops).then(function () {
    if (mine !== WIN_ASKED) return;
    WIN_FLYING = 0;
    winAskSoon();
  });
  /* ...and the list under it, asked again quietly: a search still going
     is waited for rather than stopped and begun again. */
  if (WPAGE_SHOWN === 'events') loadWinEvents(again);
}
$('w-window').onchange = function () { loadWindows(); };
['w-hours', 'w-event', 'w-server', 'w-limit'].forEach(function (id) {
  $(id).onchange = function () { WPAGE = 0; loadWinEvents(); };
});
$('w-machines').onchange = function () { WPAGE = 0; loadWinEvents(); };
$('w-q').oninput = function () {
  clearTimeout(window._winSoon);
  window._winSoon = setTimeout(function () { WPAGE = 0; loadWinEvents(); }, 250);
};
$('w-clear').onclick = function () {
  $('w-q').value = '';
  if (typeof windowSet === 'function') windowSet('w-hours', null);   /* its dates go too */
  $('w-hours').value = '24';
  $('w-event').value = '';
  $('w-server').value = '';
  $('w-machines').checked = false;
  WKIND = '';
  WPAGE = 0;
  sortReset(SORTS.win);
  loadWinEvents();
};

/** How far along whatever the daemon is doing has got.

    Drawn from the daemon's own answer, which is why it is still there after
    a reload, still there on another tab, and there on somebody else's screen
    at the same time. While something is going the page asks more often, and
    stops as soon as it is done. */
var WIN_GOING = false;

/* What the directory itself said, under the list it weighs.

   A reading that is quietly not happening looks exactly like a domain where
   nothing is wrong, so this says four things whatever the answer is: whether
   the question is being asked, of whom, when it was last answered and how
   much came back. Counts and never names - which accounts a domain's
   administrators are is the domain's business and stays on the domain's side
   of the wire. */
/** The band across the top of every page while the directory has moved.

    Drawn from the status, which every page asks for anyway, so it is there
    on whichever tab somebody happens to have open and on the other person's
    screen as well. It goes when the watching is switched off or somebody
    remembers what the directory says now - and "Take it off the page" hides
    it for whoever pressed it and for nobody else, until something else
    changes, because a band nobody can put down is a band people learn to
    read past. */
var DIR_ALARM_HIDDEN = '';
try {
  DIR_ALARM_HIDDEN = window.sessionStorage.getItem('isemon-dir-alarm') || '';
} catch (e) { DIR_ALARM_HIDDEN = ''; }

function drawDirectoryAlarm(said) {
  var band = $('dir-alarm');
  if (!band) return;
  said = said || {};
  var rows = said.rows || [];
  /* The moment of the newest change is what "hidden" is pinned to: hiding
     the band says "I have seen these", not "never show me this again". */
  var key = String(said.n || 0) + '@' + Math.round(said.at || 0);
  if (!rows.length || DIR_ALARM_HIDDEN === key) {
    band.hidden = true;
    return;
  }
  band.hidden = false;
  var what = $('dir-alarm-says');
  clear(what);
  what.appendChild(document.createTextNode(
    'What the directory says has changed since it was remembered \u2014 '
    + num(said.n) + ' value(s), the newest ' + ago(said.at) + '.'));
  what.appendChild(el('span', 'sub', rows.map(function (one) {
    return one.words + ': ' + one.says;
  }).join(' \u00b7 ') + (said.n > rows.length
    ? ' \u00b7 and ' + num(said.n - rows.length) + ' more' : '')));
  $('dir-alarm-hide').onclick = function () {
    DIR_ALARM_HIDDEN = key;
    try { window.sessionStorage.setItem('isemon-dir-alarm', key); } catch (e) { }
    band.hidden = true;
  };
  $('dir-alarm-open').onclick = function () {
    /* The Domain page, where every value that moved is red and says what it
       was. The card there is the whole answer; this band is the nudge. */
    showTab('windows');
    loadWindows();
  };
}

/* What has moved since somebody pressed Remember, keyed the way the daemon
   keys it: `which|what`. Both the card and the popup over it read this, so
   the red on a number and the sentence under the pointer are the same
   answer rather than two. */
var DIR_DRIFT = {};
var DIR_WATCH = false;

/** The change against one remembered value, or nothing. */
function dirMoved(which, what) {
  return DIR_DRIFT[String(which || '') + '|' + String(what || '')] || null;
}

/** ...and the same where the card has folded two domains into one number. */
function dirMovedAny(what) {
  var want = '|' + String(what || '');
  var found = null;
  Object.keys(DIR_DRIFT).forEach(function (key) {
    if (key.slice(-want.length) === want && !found) found = DIR_DRIFT[key];
  });
  return found;
}

/** Paint a fact red where it has moved, and say what moved on hover. */
function dirMark(node, which, what) {
  var one = node && dirMoved(which, what);
  if (!one) return node;
  node.classList.add('moved');
  /* `explain` escapes what it is given and keeps the handful of tags that
     mean something in a sentence, so what the domain said goes in as text. */
  explain(node, 'Changed since this was remembered \u2014 <b>'
    + String(one.says || 'it changed') + '</b>. First seen ' + ago(one.at)
    + '. It stays marked until the watching is switched off or somebody '
    + 'remembers what the directory says now.');
  return node;
}

function drawWinDirectory(d) {
  var box = $('w-directory');
  if (!box) return;
  clear(box);
  d = d || {};
  DIR_WATCH = !!d.watch;
  DIR_DRIFT = {};
  (d.drift || []).forEach(function (one) {
    if (one && one.key) DIR_DRIFT[one.key] = one;
  });
  box.classList.toggle('off', !(d.on && d.asked));
  if (!d.any) {
    box.appendChild(el('div', '', 'No directory is set up, so there is nothing to ask. '
      + 'With one, this page can weigh an alarm by what the account actually is.'));
    box.title = 'Settings \u2192 The directory';
    return;
  }
  if (!d.on) {
    box.appendChild(el('div', '', 'The directory is not being asked about these accounts. '
      + 'Settings \u2192 The domain controllers \u2192 "Ask the directory about the '
      + 'accounts in these logs".'));
    return;
  }
  var head = el('div', 'dirhead');
  var said = el('span', 'line');
  said.appendChild(el('span', 'who', 'What the directory says'));
  said.appendChild(document.createTextNode(
    d.asked
      ? '  \u00b7  asked ' + (d.where || []).map(function (w) {
          return w.name + (w.host ? ' (' + w.host + ')' : '');
        }).join(', ')
        + (d.at ? ', last answered ' + ago(d.at) : '')
        + '  \u00b7  again every ' + num(d.every_h) + ' h'
      : '  \u00b7  switched on \u2014 it is asked behind this page, on the '
        + 'daemon\u2019s own clock, and nothing has come back yet'
        + (d.trouble ? '. ' + d.trouble : '')));
  head.appendChild(said);
  box.appendChild(head);
  /* ...and what went wrong with the last attempt, even when an older answer
     is being shown. "It answered on Tuesday and has not been reachable
     since" is a different state from "it answered", and the difference is
     the whole reason anybody looks at this line. */
  if (d.asked && d.trouble) {
    var bad = el('div', 'bad');
    bad.style.marginTop = '4px';
    bad.textContent = 'The last attempt did not get through \u2014 ' + d.trouble
      + '. What is below is the answer before it.';
    box.appendChild(bad);
  }
  /* Nothing has answered: the four counts below would be four noughts, and
     four noughts read as "the domain has no service accounts and nobody
     runs it" rather than as "nobody has answered". */
  if (!d.asked) {
    box.classList.add('off');
    return;
  }
  /* The four facts, each with what it is FOR beside it: a number with no
     reason is a number nobody can act on, and every one of these changes
     how an alarm above is weighed. */
  /* Per domain, not folded together. A site can read the controllers of two
     domains into one of these, and two domains that both hold an account
     called the same thing hold two accounts. Folded, the numbers were a sum
     of two things nobody asked for. */
  if ((d.where || []).length > 1) {
    var each = el('div', 'grouplist');
    each.style.marginTop = '6px';
    d.where.forEach(function (w) {
      var row = el('div', 'one');
      row.appendChild(el('span', 'nm mono', w.host || w.name));
      row.appendChild(el('span', 'dn small',
        num(w.service || 0) + ' service \u00b7 ' + num(w.nopreauth || 0)
        + ' no pre-auth \u00b7 ' + num(w.disabled || 0) + ' switched off \u00b7 '
        + num(w.privileged || 0) + ' run the domain'
        + (w.trouble ? ' \u00b7 ' + w.trouble : '')));
      each.appendChild(row);
    });
    box.appendChild(each);
  }
  var counts = el('div', 'counts');
  [['service', 'accounts a service runs as',
    'A ticket asked for in RC4 is kerberoasting against one of these and an old '
    + 'application against anything else.'],
   ['nopreauth', 'with pre-authentication off',
    'A ticket asked for without pre-authentication is ordinary against one of these '
    + 'and is somebody trying every account in turn against the rest.'],
   ['disabled', 'switched off',
    'Something still trying one of these is something nobody told.'],
   ['privileged', 'in the groups that run the domain',
    'Followed through groups inside groups. An account being hammered is weighed by '
    + 'what it could actually do if somebody got it.']
  ].forEach(function (one) {
    var cell = el('span');
    cell.appendChild(el('b', '', num(d[one[0]] || 0)));
    cell.appendChild(document.createTextNode(' ' + one[1]));
    explain(cell, one[2]);
    /* Red where it is not what it was when somebody pressed Remember. */
    var moved = dirMovedAny('counts/' + one[0]);
    if (moved) {
      cell.classList.add('moved');
      explain(cell, 'Changed since this was remembered \u2014 <b>'
        + String(moved.says || 'it changed') + '</b>. First seen ' + ago(moved.at) + '.');
    }
    counts.appendChild(cell);
  });
  box.appendChild(counts);

  /* ...and everything else it read, which is the half that turns a line in a
     controller's log into something somebody can act on: after how many
     wrong passwords this domain locks an account, what it will accept as
     encryption, which other domains it trusts, which machines are its
     controllers and who is in each group that runs it. Four counts on a line
     is what it knows; this is what it says. */
  var open = el('button', 'btn small');
  open.style.marginTop = '8px';
  open.dataset.icon = 'shield';
  open.textContent = 'What it read from the directory';
  open.onclick = function () { peekDirectoryShape(d); };
  box.appendChild(open);
}

/** The switch that watches what the directory says, and what it has caught.

    Off, nothing is kept and nothing is compared. On, and with somebody
    having pressed Remember, everything the domain says about itself is
    weighed against what it said at that moment - and what has moved since
    is red here, on the page behind this, and on a band across the top of
    every other page until it is switched off or remembered again.

    Read only, like the rest of this: what is remembered is written into
    THIS database. Active Directory is never written to. */
function dirWatchSwitch(d) {
  /* The same switch the settings use: one thing to look at rather than two
     words to read. */
  var row = el('span', 'swrow dirsw');
  var sw = el('label', 'sw small');
  var box = el('input');
  box.type = 'checkbox';
  box.checked = !!d.watch;
  box.disabled = !ADMIN;
  sw.appendChild(box);
  sw.appendChild(el('span', 'knob'));
  row.appendChild(el('span', 'swlbl', 'Watch it for changes'));
  row.appendChild(sw);
  explain(row, 'Keeps what the domain says about ITSELF \u2014 who is in the groups that '
    + 'run it, the password and lockout rules, which machines are its controllers, which '
    + 'domains it trusts \u2014 and weighs every later reading against it. The day\u2019s '
    + 'work is not watched: accounts made and deleted, people joining ordinary groups, how '
    + 'many administrators there are. Nothing is ever written to the directory: what is '
    + 'remembered is written here.');
  box.onchange = function () {
    var want = box.checked;
    box.disabled = true;
    api('win-dirwatch', {on: want ? 1 : 0}).then(function (got) {
      toast(want ? 'watching what the directory says' : 'not watching it any more', 'good');
      if (want && !(got.memory || {}).at) {
        toast('press Remember to keep what it says now', 'good');
      }
      dirWatchAgain(got);
      tick();
    }).catch(function (e) { box.checked = !want; oops(e); })
      .then(function () { box.disabled = !ADMIN; });
  };
  return row;
}

/** The whole of the watching, on the foot of the popup it is about.

    Here rather than on the Domain page: what is being watched is what this
    popup holds - who is in the groups that run the domain, the rules, the
    controllers, the trusts - and a switch three cards away from the values
    it marks red is a switch nobody connects to them. */
function dirWatchBar(d) {
  var bar = el('div', 'dirwatch left');
  bar.appendChild(dirWatchSwitch(d));
  if (d.watch) {
    bar.appendChild(dirWatchRow(d));
  } else {
    bar.appendChild(el('span', 'small muted',
      'Off \u2014 nothing is being weighed against anything'));
  }
  return bar;
}

/** Everything above, drawn again from a fresh answer: the card behind, the
    red on the values, and the foot of this popup. */
function dirWatchAgain(got) {
  drawWinDirectory(got);
  peekDirectoryShape(got);
}

/** ...and, once it is on, the button that decides WHAT it is weighed
    against, with what was remembered beside it. */
function dirWatchRow(d) {
  var row = el('span', 'dirwatch');
  if (!d.watch) return row;
  var go = el('button', 'btn small');
  go.dataset.icon = 'save';
  go.textContent = (d.memory || {}).at ? 'Remember it again' : 'Remember';
  go.disabled = !ADMIN;
  explain(go, 'Keep what the directory says AT THIS MOMENT as the answer everything '
    + 'later is weighed against. Pressing it again takes today\u2019s answer as the new '
    + 'one and clears everything marked red.');
  go.onclick = function () {
    go.disabled = true;
    api('win-dirwatch', {act: 'remember'}).then(function (got) {
      toast('what the directory says was remembered', 'good');
      dirWatchAgain(got);
      tick();
    }).catch(oops).then(function () { go.disabled = !ADMIN; });
  };
  row.appendChild(go);
  var when = el('span', 'small muted');
  when.textContent = (d.memory || {}).at
    ? 'remembered ' + ago(d.memory.at) + ((d.memory.by) ? ' by ' + d.memory.by : '')
      + ' \u00b7 ' + num(d.memory.n || 0) + ' value(s)'
    : 'nothing remembered yet \u2014 nothing is being weighed against anything';
  row.appendChild(when);
  if ((d.drift || []).length) {
    /* Named rather than counted: "3 value(s) have changed" sends somebody
       hunting up the page for the red, and the red is what they came for. */
    var bad = el('span', 'bad small');
    bad.textContent = num(d.drift.length) + ' changed: '
      + d.drift.slice(0, 3).map(function (one) { return one.words; }).join(' \u00b7 ')
      + (d.drift.length > 3 ? ' \u00b7 \u2026' : '');
    explain(bad, d.drift.slice(0, 8).map(function (one) {
      return one.words + ': ' + one.says + ' (' + ago(one.at) + ')';
    }).join('\n'));
    row.appendChild(bad);
  }
  return row;
}

/** The names behind one of the counts, each of them pressable.

    Nothing is shortened here. "and 23 more" is the number somebody wanted to
    read, and a list that stops before it is a list they have to go and get
    another way. */
function peekDirectoryNames(w, what, words) {
  modal(words + ' \u00b7 ' + (w.host || w.name), function (body) {
    body.appendChild(el('p', 'center muted', 'Asking\u2026'));
  }, [{words: 'Back', close: true}]);
  var ticket = modalTicket();
  api('dir-names&which=' + encodeURIComponent(w.which)
      + '&what=' + encodeURIComponent(what)).then(function (d) {
    var body = $('modal-body');
    if (!body || !modalStill(ticket)) return;
    clear(body);
    body.appendChild(peekFacts([
      [words, num(d.total)],
      ['Domain', d.domain || d.name],
      ['Read', d.at ? ago(d.at) : 'not yet']
    ]));
    if (d.shown < d.total) {
      body.appendChild(el('p', 'note muted', 'The first ' + num(d.shown)
        + ' of them. This domain has ' + num(d.total)
        + ', which is more than is carried for matching \u2014 the number above is '
        + 'the domain\u2019s own.'));
    }
    body.appendChild(el('p', 'note', 'Press a name for what the directory holds '
      + 'about it.'));
    body.appendChild(dirNameSet(words, d.names || [], d.which));
    explainWhatWasDrawn(body);
  }).catch(function (e) {
    var body = $('modal-body');
    if (!body || !modalStill(ticket)) return;
    clear(body); body.appendChild(el('p', 'center bad', String(e.message || e)));
  });
}

/** One name out of the directory, as something to press.

    These were pressable before and did not look it: a bare word in a run of
    thirty-five other bare words, with nothing to say it opened anything. */
function dirNamePill(name, which) {
  var pill = el('span', 'tag namepill opens', String(name || ''));
  opensWith(pill, 'What the directory holds about this account \u2014 who it belongs '
    + 'to, which groups it is in, whether it is switched off, locked or expired. '
    + 'Read only.', function () { showPerson(String(name || ''), which || ''); });
  return pill;
}

/** A set of names under a heading of its own, rather than beside one.

    Thirty-five names beside a heading wrap into four ragged lines and read
    as one wall of text. Under their own heading they are a list. */
function dirNameSet(title, names, which, says, more) {
  var box = el('div', 'nameset');
  var head = el('div', 'h');
  head.appendChild(el('span', 'nm', title));
  head.appendChild(el('span', 'n', num((names || []).length + (more || 0))));
  if (says) head.appendChild(el('span', 'says', says));
  box.appendChild(head);
  var row = el('div', 'namesrow');
  (names || []).forEach(function (one) {
    row.appendChild(which === null ? el('span', 'tag namepill flat', String(one))
                                   : dirNamePill(one, which));
  });
  if (more > 0) {
    row.appendChild(el('span', 'muted small', 'and ' + num(more) + ' more'));
  }
  if (!(names || []).length) row.appendChild(el('span', 'muted small', 'none'));
  box.appendChild(row);
  return box;
}

/** Everything the directory was asked, per domain, as it answered. */
function peekDirectoryShape(d) {
  var shown = modal('What the directory says', function (body) {
    body.appendChild(el('p', 'note',
      'Read from Active Directory, never written to it. None of this is a log: it is '
      + 'what the domain itself says it is, and it is what the patterns above are '
      + 'weighed against \u2014 a hundred refusals against one account means one thing '
      + 'where the domain locks after five and quite another where it never locks.'));
    (d.where || []).forEach(function (w) {
      var box = el('div', 'card facet');
      box.style.marginTop = '12px';
      var h = el('h2', '', w.name);
      if (w.host) h.appendChild(el('span', 'alias', w.host));
      box.appendChild(h);
      if (w.trouble) {
        box.appendChild(el('p', 'note bad', w.trouble));
      }
      var sh = w.shape || {};
      var facts = [];
      /* Each fact remembers which remembered value it IS, so that the one
         that has moved since somebody pressed Remember can be made red and
         say what moved. */
      var keys = [];
      function fact(key, words, value) {
        facts.push([words, value]);
        keys.push(key);
      }
      if (sh.base) fact('shape/base', 'Where it looks', sh.base);
      if (sh.level_words) fact('shape/level_words', 'Running as', sh.level_words);
      if (sh.made) fact('', 'Domain made', shortStamp(sh.made));
      if (sh.lock_after !== undefined && sh.lock_after !== null) {
        fact('shape/lock_after', 'Locks after', sh.lock_after
          ? num(sh.lock_after) + ' wrong password(s)' : 'never \u2014 lockout is off');
      }
      if (sh.lock_for_s) {
        fact('shape/lock_for_s', 'Stays locked',
             sh.lock_for_s < 0 ? 'until somebody unlocks it' : span(sh.lock_for_s));
      }
      if (sh.lock_window_s) {
        fact('shape/lock_window_s', 'Counted over', span(sh.lock_window_s));
      }
      if (sh.password_least) {
        fact('shape/password_least', 'Shortest password', num(sh.password_least));
      }
      if (sh.password_age_s) {
        fact('shape/password_age_s', 'Passwords last',
             sh.password_age_s < 0 ? 'for ever' : span(sh.password_age_s));
      }
      if (sh.password_history) {
        fact('shape/password_history', 'Old passwords kept', num(sh.password_history));
      }
      if (sh.password_complex !== undefined) {
        fact('shape/password_complex', 'Complexity',
             sh.password_complex ? 'required' : 'not required');
      }
      if (sh.password_reversible) {
        fact('shape/password_reversible', 'Reversible encryption',
             'ON \u2014 passwords are recoverable');
      }
      if (sh.machines_each !== undefined && sh.machines_each !== null) {
        fact('shape/machines_each', 'Machines each account may join', num(sh.machines_each));
      }
      var shown = peekFacts(facts);
      keys.forEach(function (key, at) {
        if (key && shown.children[at]) dirMark(shown.children[at], w.which, key);
      });
      box.appendChild(shown);
      /* The accounts, counted as the domain really has them rather than as
         many as were carried: on a big domain the names stop at a cap and
         the count does not. */
      var c = w.counts || {};
      box.appendChild(el('h3', 'peek-h', 'The accounts, as this domain has them'));
      box.appendChild(el('p', 'note', 'Counted by the domain itself rather than by '
        + 'anything here. Press any of these to read the names behind it.'));
      var counted = peekFacts([
        ['A service runs as', num(c.service || 0)],
        ['Pre-authentication off', num(c.nopreauth || 0)],
        ['Switched off', num(c.disabled || 0)],
        ['In the groups that run it', num(w.privileged || 0)],
        ['Had the keys at some point', num(c.was_admin || 0)],
        ['Password never expires', num(c.never_expires || 0)],
        ['No password needed', num(c.no_password || 0)],
        ['May act as anybody (unconstrained)', num(c.delegating || 0)],
        ['May act as anybody, any protocol', num(c.delegating_any || 0)],
        ['Smart card required', num(c.smartcard || 0)]
      ]);
      /* A number nobody can open is a number nobody can act on. Each of
         these opens the names behind it, and each of THOSE opens what the
         directory holds about that account. */
      ['service', 'nopreauth', 'disabled', 'privileged', 'was_admin',
       'never_expires', 'no_password', 'delegating', 'delegating_any',
       'smartcard'].forEach(function (what, at) {
        var cell = counted.children[at];
        if (!cell) return;
        dirMark(cell, w.which, 'counts/' + what);
        var n = what === 'privileged' ? (w.privileged || 0) : (c[what] || 0);
        if (!n) return;
        opensWith(cell, '', function () {
          peekDirectoryNames(w, what, cell.querySelector('.k').textContent);
        });
      });
      box.appendChild(counted);
      if ((w.cut || []).length) {
        box.appendChild(el('p', 'note muted',
          'More of these than are carried: the counts above are the domain\u2019s own, '
          + 'and the names kept for matching stop at the first few thousand \u2014 '
          + w.cut.join(', ') + '.'));
      }
      if ((sh.controllers || []).length) {
        box.appendChild(dirMark(el('h3', 'peek-h', 'The controllers the domain names'),
                                w.which, 'controllers'));
        box.appendChild(el('p', 'note', 'Every machine that answers for this domain. '
          + 'Press one for what the directory holds about it.'));
        var cl = el('div', 'grouplist');
        sh.controllers.forEach(function (c) {
          var row = el('div', 'one');
          var name = el('span', 'nm mono', c.name);
          /* A controller is an account like any other, and what the
             directory holds about it is one press away. */
          opensWith(name, '', function () {
            showPerson(String(c.name).split('.')[0] + '$', w.which);
          });
          row.appendChild(name);
          row.appendChild(el('span', 'dn mono small',
            [c.os, c.last ? 'last seen ' + shortStamp(c.last) : ''].filter(Boolean)
              .join(' \u00b7 ')));
          cl.appendChild(row);
        });
        box.appendChild(cl);
      }
      if ((sh.trusts || []).length) {
        box.appendChild(dirMark(el('h3', 'peek-h', 'Other domains it trusts'),
                                w.which, 'trusts'));
        box.appendChild(el('p', 'note', 'A name from one of these can sign in here, which '
          + 'is why a name nobody here has heard of is not by itself wrong.'));
        var tl = el('div', 'grouplist');
        sh.trusts.forEach(function (t) {
          var row = el('div', 'one');
          row.appendChild(el('span', 'nm mono', t['with']));
          var marks = [t.way, t.kind];
          if (t.forest) marks.push('across the forest');
          if (t.outside) marks.push('treated as outside');
          if (t.filtered) marks.push('SIDs filtered');
          if (t.rc4_only) marks.push('RC4 only');
          row.appendChild(el('span', 'dn small', marks.join(' \u00b7 ')));
          tl.appendChild(row);
        });
        box.appendChild(tl);
      }
      var groups = w.groups || {};
      var gcount = w.group_counts || {};
      var names = Object.keys(groups);
      if (names.length) {
        box.appendChild(el('h3', 'peek-h', 'Who is in each group that runs the domain'));
        box.appendChild(el('p', 'note', 'Following groups inside groups, so somebody who '
          + 'is an administrator through three nested groups is here under the group '
          + 'that matters. Press a name for what the directory holds about it.'));
        names.sort().forEach(function (g) {
          var all = gcount[g] || groups[g].length;
          var set = dirNameSet(g, groups[g], w.which, '',
                               Math.max(0, all - groups[g].length));
          /* The one change this whole card exists for: a name that was not
             in the group that runs the domain yesterday. */
          var head = set.firstChild;
          if (head && head.nodeType === 1) dirMark(head, w.which, 'group/' + g);
          /* ...and WHICH name is new, which is the thing somebody is
             looking for the moment the heading goes red. */
          var moved = dirMoved(w.which, 'group/' + g);
          if (moved && (moved.added || []).length) {
            var came = {};
            moved.added.forEach(function (one) { came[String(one).toLowerCase()] = true; });
            Array.prototype.forEach.call(set.querySelectorAll('.namepill'),
              function (pill) {
                if (!came[String(pill.textContent || '').toLowerCase()]) return;
                pill.classList.add('came');
                explain(pill, 'Not in this group when this was remembered \u2014 added '
                  + 'since, first seen ' + ago(moved.at) + '.');
              });
          }
          box.appendChild(set);
        });
      }
      /* Where the domain thinks its addresses are. An address in a log is a
         number until this turns it into a place. */
      if ((sh.subnets || []).length || (sh.sites || []).length) {
        box.appendChild(el('h3', 'peek-h', 'Sites, and the addresses that belong to them'));
        box.appendChild(el('p', 'note', 'Which is what turns an address in a log into a '
          + 'place.'));
        var sl = el('div', 'grouplist');
        (sh.subnets || []).slice(0, 60).forEach(function (one) {
          var row = el('div', 'one');
          row.appendChild(el('span', 'nm mono', one['range']));
          row.appendChild(el('span', 'dn small',
            [one.site, one.where].filter(Boolean).join(' \u00b7 ')));
          sl.appendChild(row);
        });
        box.appendChild(sl);
        if ((sh.subnets || []).length > 60) {
          box.appendChild(el('p', 'note muted',
            'and ' + num(sh.subnets.length - 60) + ' more range(s)'));
        }
        if ((sh.sites || []).length) {
          box.appendChild(dirNameSet('The sites themselves', sh.sites, null));
        }
      }
      if ((sh.extra_policies || []).length) {
        box.appendChild(el('h3', 'peek-h', 'Password policies for SOME accounts'));
        box.appendChild(el('p', 'note', 'Rather than for all of them \u2014 the rule above '
          + 'is not true of an account one of these covers.'));
        var pl = el('div', 'grouplist');
        sh.extra_policies.forEach(function (one) {
          var row = el('div', 'one');
          row.appendChild(el('span', 'nm mono', one.name));
          row.appendChild(el('span', 'dn small',
            'locks after ' + (one.lock_after || '?') + ' \u00b7 shortest '
            + (one.least || '?') + ' \u00b7 covers ' + num(one.covers || 0)));
          pl.appendChild(row);
        });
        box.appendChild(pl);
      }
      if ((sh.top || []).length) {
        box.appendChild(el('h3', 'peek-h', 'The top of the tree'));
        box.appendChild(el('p', 'note', 'Which is what a distinguished name in a log is '
          + 'read against: the object in an event says cn=someone,OU=\u2026 and these '
          + 'are the OUs it can end in.'));
        box.appendChild(dirNameSet('Where accounts live', sh.top, null));
      }
      body.appendChild(box);
    });
    if (!(d.where || []).length) {
      body.appendChild(el('p', 'center muted',
        'Nothing has come back from a directory yet.'));
    }
    explainWhatWasDrawn(body);
  }, [{words: 'Close', close: true}]);
  /* The switch and the Remember button live on the foot of this popup,
     beside Close: what they watch is everything above them, and the red
     they put on a value is red HERE. */
  if ((d.where || []).length) {
    shown.foot.insertBefore(dirWatchBar(d), shown.foot.firstChild);
  }
}

/* Until when to go on asking whether something is going, whatever the
   answers say. Set when the button is pressed and cleared the moment a job
   is seen to start - from there the job's own presence keeps the asking up,
   and its absence ends it. */
var WIN_WATCH_UNTIL = 0;
var WIN_WATCH_FOR = 180000;
/* When to come back for the half of the page that was not ready yet. */
var WIN_SOON = null;

/** The Domain page's answers being counted ahead of time, behind the
    daemon or at a terminal: the same card the Traffic page shows while its
    overview is worked out (1.10.154). Returns whether it is drawn. */
function drawWinCounting(d) {
  var c = d.counting || {};
  var job = null;
  Object.keys(d.going || {}).forEach(function (k) {
    if (k.indexOf('db-roll') === 0) job = job || d.going[k];
  });
  if (!job && !c.busy) { bgCard('w-counting', 'w-working', null); return false; }
  var lines = [];
  if (job && job.total) {
    lines.push(Math.round(Number(job.part || 0) * 100) + '% \u2014 ' + num(job.done)
      + ' of ' + num(job.total) + ' day(s) counted.');
  }
  if (job && job.began) lines.push('Started ' + ago(job.began) + '.');
  if (job && job.left_s) lines.push('About ' + span(job.left_s) + ' left.');
  if (!job) lines.push('It is going in another process - a terminal, most likely.');
  lines.push(c.ready
    ? 'Until it is done, the page goes on using what was counted before.'
    : 'Until it is done and proved, the cards here are worked out from the events '
      + 'themselves each time, which is slower on a big domain; the page switches over '
      + 'by itself.');
  bgCard('w-counting', 'w-working', {
    title: 'Counting the domain events ahead of time\u2026',
    part: job && job.total ? Number(job.part || 0) : null,
    lines: lines});
  /* ...and the page keeps asking while it goes, as it does for any job. */
  WIN_GOING = true;
  return true;
}

function drawWinGoing(going, counting) {
  /* Two bars, one job: the Domain page watches, the settings pane where the
     button is watches too, and both are drawn off the daemon's own answer so
     they say the same thing at the same moment. */
  /* The counting ahead of time has a card of its own on this page (see
     `drawWinCounting`), so the bar across the top leaves it out here. */
  var one = drawGoing('w-going', going, null, counting ? 'db-roll' : null);
  drawGoing('winsec-going', going);
  /* The button is in the settings pane now, and it is the one that goes
     dead while a walk is going. */
  if ($('winsec-reread')) $('winsec-reread').disabled = !!one;
  if ($('winsec-dirread')) $('winsec-dirread').disabled = !!one;
  WIN_GOING = !!one || !!counting;
  /* Once a job has been SEEN, the watch is over: from here it is the job
     itself that keeps the page asking, and when it goes the page stops. */
  if (one) WIN_WATCH_UNTIL = 0;
}

/** One bar, for whatever long job is going on, wherever it is drawn.

    Said once and used twice: the domain page draws the walks of its own
    table, and the database pane draws the copies, dumps, restores and
    tidies somebody presses a button for. Both are the same thing - a job
    that takes minutes and from outside looks exactly like a daemon that has
    stopped - and both read it off the daemon rather than out of the
    browser, so it survives a reload and a second person watching. */
function drawGoing(where, going, only, skip) {
  var box = $(where);
  if (!box) return null;
  var one = null;
  Object.keys(going || {}).forEach(function (k) {
    if (only && k.indexOf(only) !== 0) return;
    if (skip && k.indexOf(skip) === 0) return;
    one = one || (going || {})[k];
  });
  box.hidden = !one;
  if (!one) return null;
  var part = Number(one.part || 0);
  var fill = box.querySelector('.bar span');
  /* A job that has not said how many there are yet gets a bar that moves
     rather than a bar stuck at nought, because nought looks like stuck. */
  /* No total, but a guess at one: a dump says how big the last one came
     out, and the bar fills against that - never to the end, because the
     guess is not a promise, and the words say what it is measured against. */
  var guess = !one.total && Number(one.expect) > 0;
  var guessed = guess ? Math.min(0.97, Number(one.done || 0) / Number(one.expect)) : 0;
  fill.classList.toggle('creeping', !one.total && !guess);
  fill.style.width = one.total ? Math.max(2, Math.round(part * 100)) + '%'
    : (guess ? Math.max(2, Math.round(guessed * 100)) + '%' : '');
  var took = Math.max(0, (one.now || 0) - (one.began || 0));
  /* Some of these count rows and some count BYTES - a dump says how far
     along it is by how big the file it is writing has got, and
     "418,446,336" is a number somebody has to count the digits of. */
  var much = one.size ? bytes : num;
  box.querySelector('.says').textContent = one.total
    ? (one.what + ': ' + Math.round(part * 100) + '% \u2014 ' + much(one.done)
       + ' of ' + much(one.total) + (took > 4 ? ', ' + span(took) + ' so far' : ''))
    : (one.what + ': ' + much(one.done) + ' so far'
       + (guess ? ' \u2014 the last one came out at ' + much(one.expect) : '')
       + (took > 4 ? ', ' + span(took) : ''));
  /* One line; where the screen is too narrow for it, all of it on hover. */
  box.querySelector('.says').title = box.querySelector('.says').textContent;
  return one;
}

function drawWindows(d) {
  /* Who the controllers are, before anything is drawn with them. */
  dcLearn(d.controllers);
  sayWhyNoDc(d.controllers);
  /* Not everything was ready. The page draws what there is and says so, and
     keeps asking until it is all there. */
  if ($('w-working')) $('w-working').hidden = !d.working;
  if (d.working) {
    clearTimeout(WIN_SOON);
    /* Only while this page is the one looked at (1.10.176): it went on
       asking every three seconds from every other tab and hidden window. */
    WIN_SOON = setTimeout(function () {
      if (TAB === 'windows' && !document.hidden) loadWindows(true);
    }, 3000);
  }
  drawWinGoing(d.going, drawWinCounting(d));
  drawWinDirectory(d.directory);
  /* The strip says how many events are behind the second page before
     anybody opens it, out of the answer the overview already has. */
  var counts = d.counts || {};
  var all = Object.keys(counts).reduce(function (n, k) { return n + (counts[k] || 0); }, 0);
  if ($('w-pages-n') && WPAGE_SHOWN !== 'events') {
    $('w-pages-n').textContent = all ? num(all) : '';
  }
  var locked = counts.lockout || 0;
  var refused = (counts['logon-failed'] || 0) + (counts['kerberos-failed'] || 0)
              + (counts['ntlm-failed'] || 0);
  var changed = (counts.account || 0) + (counts.group || 0) + (counts.unlock || 0);
  /* The four numbers on one line, each of them still opening what it counts.
     The same shape the doors on the front page use, and for the same reason:
     a row of tiles is four big numbers where four small ones would do, and
     the cards that answer something start four hundred pixels lower. */
  var tally = $('w-tally');
  clear(tally);
  var count = function (n, words, says, tone, ask) {
    if (tally.firstChild) tally.appendChild(document.createTextNode(' \u00b7 '));
    var b = el('b', tone || '', num(n) + ' ' + words);
    opensWith(b, says, ask);
    tally.appendChild(b);
  };
  count(locked, locked === 1 ? 'account locked' : 'accounts locked',
        'Every lockout in this window.', 'bad',
        function () { winPeekEvents('The accounts the domain locked', {kind: 'lockout'}); });
  count(refused, 'refused', 'Every refusal in this window.', 'bad', function () {
    winPeekEvents('What the domain turned away',
                  {kind: 'logon-failed,kerberos-failed,ntlm-failed'});
  });
  count(changed, 'accounts and groups changed',
        'Every account and group change in this window.', '', function () {
    winPeekEvents('Accounts and groups changed', {kind: 'account,group,unlock'});
  });
  count(all, 'events read', 'Everything read from the controllers.', 'good', function () {
    winPeekEvents('Everything the controllers wrote', {});
  });
  tally.appendChild(document.createTextNode(
    d.newest ? (', newest ' + ago(d.newest)
                + (d.machines_shown ? '' : ' \u00b7 the machine accounts are counted apart'))
             : ', nothing has been read yet'));
  /* ...and where this window really begins. It starts on the hour, so
     "last 24 hours" was rounder than every number underneath it, and two
     people looking a minute apart could not reproduce each other's figures.
     Everything since that moment is here, including what arrived a second
     ago. */
  if (d.since) {
    var from = el('span', 'muted', ' \u00b7 since ' + shortStamp(d.since));
    opensWith(from, 'Where this window begins, to the hour. Every number on this page '
      + 'covers exactly from here to now \u2014 including whatever arrived a moment '
      + 'ago \u2014 so two people looking at once see the same figures, and the same '
      + 'window an hour from now is a window somebody can reproduce.',
      /* Pressed, it opens what it is the start of: everything read since. It
         had no action at all, and pressing it was an error in the page. */
      function () { winPeekEvents('Everything since ' + shortStamp(d.since), {}); });
    tally.appendChild(from);
  }

  drawWinIncidents(d.incidents || []);
  drawWinLocks(d.lockouts || []);
  drawWinViews(d.views || []);

  explainWhatWasDrawn($('tab-windows'));
}

/* ---- the patterns worth looking at --------------------------------------- */
function drawWinIncidents(rows) {
  var host = $('w-incidents');
  if (sameAsDrawn(host, rows) && host.firstChild) {
    $('w-incidents-none').hidden = !!rows.length;
    return;
  }
  steady(host);
  clear(host);
  $('w-incidents-none').hidden = !!rows.length;
  rows.forEach(function (one) { host.appendChild(winIncidentLine(one)); });
  settle(host);
}

/** One thing worth looking at, as a line. Its own function because the front
    page draws the same lines in its own card and two copies of this would
    drift apart within a version. */
function winIncidentLine(one) {
    var line = el('div', 'incident ' + (one.level || 'info'));
    var head = el('div', 'head');
    var dot = el('span', 'lvl');
    dot.innerHTML = iconMarkup(one.level === 'crit' ? 'ban'
                               : (one.level === 'warn' ? 'shield' : 'info'), 16);
    head.appendChild(dot);
    head.appendChild(el('span', 'words', one.words));
    var n = el('span', 'n');
    n.textContent = num(one.n);
    head.appendChild(n);
    if (one.last) head.appendChild(el('span', 'when', ago(one.last)));
    line.appendChild(head);
    if (one.more) line.appendChild(el('div', 'more', one.more));
    /* ...and what to do about it, on the alarm itself. An alarm that says
       only what happened is an alarm somebody has to go and work on; the
       first line of the reading is the same fact with the answer in it. */
    (one.reads || []).slice(0, 1).forEach(function (w) {
      line.appendChild(el('div', 'more reads', w));
    });
    (one['next'] || []).slice(0, 1).forEach(function (w) {
      line.appendChild(el('div', 'more go', w));
    });
    explain(line, one.says, one.who
      ? '<div class="k"><b>The newest was:</b> ' + richText(one.who) + '</div>' : '');
    opensWith(line, '', function () { winPeekIncident(one); });
    /* ...and the account it is about, where it names one: what the
       directory says about it is half of what somebody needs to decide
       whether this matters, and it was nowhere on this page. */
    if (one.who && (STATUS || {}).directory_on) {
      var ask = el('span', 'askdir');
      ask.appendChild(winWho(one.who, one.domain, 'mono small'));
      line.appendChild(ask);
    }
    return line;
}

/** What one pattern is made of: the events themselves. */
function winPeekIncident(one) {
  var where = one.where || {};
  var ask = {};
  /* EVERY filter the daemon counted with, not a list of the ones this
     function happens to know about.
     It used to copy six names by hand, so a card counted with a seventh
     opened something else entirely: the machine-account alarms counted the
     machines and the popup hid them (crit "an account asked to replicate",
     press it, no events at all), and the spray, brute-force and dead-account
     cards counted only the REFUSALS while their popups opened every event
     about that name - a card reading 147 over a popup reading 8,432. Each
     of those was one filter the daemon knew and this did not. So it passes
     what it is given: they are all names `/api/windows/events` understands,
     and a filter it does not understand is one it ignores rather than one
     that silently changes the question. */
  Object.keys(where).forEach(function (k) {
    if (where[k] !== '' && where[k] !== null && where[k] !== undefined) {
      ask[k] = String(where[k]);
    }
  });
  /* ...including whether the machine accounts are counted, which is not a
     filter on the rows but a tick box on the page. */
  var over = ask.machines === '1' ? {machines: true} : null;
  delete ask.machines;
  winPeekEvents(one.words, ask, one.says, '', over);
}

/* ---- the lockouts, which are the headline question ----------------------- */
function drawWinLocks(rows) {
  var body = $('w-locks').querySelector('tbody');
  if (sameAsDrawn(body, rows) && body.firstChild) return;
  clear(body);
  $('w-locks-none').hidden = !!rows.length;
  $('w-locks-n').textContent = rows.length ? (num(rows.length) + ' in this window') : '';
  rows.forEach(function (r) { body.appendChild(winLockRow(r)); });
  winLockThrough($('w-locks'), rows);
}

/** Hide the "Through" column where not one row has an answer for it.

    That column says which PROGRAM used the password, and it is the best
    answer a lockout has — when Windows fills it in. On a domain controller
    it usually does not: a lockout carries no process of its own, and the
    refusals before it are Kerberos and NTLM events, which name a machine and
    not a program. A column that is a dash all the way down is a column of
    noise, and it takes width away from one that is saying something. So it
    is drawn when the data has it and left out when it does not, rather than
    being deleted outright — where a workstation logs it, it is the answer. */
function winLockThrough(table, rows) {
  if (!table) return;
  var any = (rows || []).some(function (r) { return !!shortProcess(r.process); });
  table.classList.toggle('nothrough', !any);
}

/** One lockout, as a row - here rather than inside the draw above, because
    the front page's domain card draws the same rows. */
function winLockRow(r) {
    var tr = el('tr');
    tr.appendChild(stampCell(r.ts));
    var who = el('td');
    who.appendChild(winWho(r.account, r.domain));
    tr.appendChild(who);
    var from = el('td');
    from.appendChild(r.machine ? winMachineWho(r.machine, r.domain, r.ip)
                               : winAddr(r.ip));
    if (r.machine && r.ip) from.appendChild(el('span', 'sub', r.ip));
    tr.appendChild(from);
    tr.appendChild(el('td', 'throughcell', shortProcess(r.process) || '\u2013'));
    tr.appendChild(el('td', 'num', num((r.before || []).length)));
    var end = el('td', 'small');
    end.appendChild(winFreedWords(r.freed));
    tr.appendChild(end);
    tr.appendChild(winWroteCell(r.server));
    opensWith(tr, 'The whole story of this lockout: what was tried, from where, '
                + 'through what, why — and who unlocked it.',
              function () { winPeekLock(r); });
    return tr;
}

/** An account name that opens everything known about it.

    Every account anywhere on this page has two halves nobody could reach
    from here. One is its LIFE: who made it, who changed it, who unlocked it,
    who deleted it, in order — which is all in what the controllers wrote
    down. The other is what the DIRECTORY says about it right now: who the
    person is, which groups they are in, whether it is switched off, locked
    or expired, when the password was last set.

    The life comes first, and the directory is a press away inside it. That
    way round because the account somebody is most likely to be chasing is
    one that no longer exists — and a deleted account has a long life and
    nothing whatever in the directory. It is pressable even with no directory
    configured at all, because the life needs none.

    Asked by the DOMAIN the row carries, because a site with two of them has
    two directories and `EXAMPLE` and `CORPNET` are two different places to
    look. */
/* ---- the domain's own controllers ---------------------------------------
   Which machines and addresses on this page are the domain's OWN
   controllers, out of what the domain itself answered when it was asked.
   A controller is the one machine where a page full of refusals means the
   directory doing its work rather than an old password saved somewhere, and
   telling them apart by eye means knowing the site's naming by heart. Blue
   and two letters: enough to find, not enough to shout. */
var WIN_DC = {};
var WIN_DC_IP = {};

/** A machine written the one way two of them can be compared.

    `DC01$`, `dc01.example.int` and `EXAMPLE\DC01$`
    are one machine written three ways, and all three turn up in a Security
    log. The same folding the daemon does, so the two agree. */
function winShort(said) {
  var name = String(said || '').trim().toLowerCase();
  if (!name) return '';
  if (name.indexOf('\\') >= 0) name = name.split('\\').pop();
  if (name.indexOf('host/') === 0) name = name.slice(5);
  name = name.split('@')[0].split('.')[0];
  return name.replace(/\$+$/, '').trim();
}

function winIsDC(name, ip) {
  var short = winShort(name);
  if (short && WIN_DC[short]) return true;
  var at = String(ip || '').trim().toLowerCase();
  return !!(at && WIN_DC_IP[at]);
}

/** Mark a name or an address as a controller, where it is one.

    The node itself goes blue and carries two letters after it. Nothing is
    added where it is not a controller, which is almost everywhere: this is
    a mark to find, not a column. */
var DC_WHY = 'A domain controller \u2014 the domain itself named this machine as one '
  + 'of its own when it was asked. Refusals and tickets in and out of a controller are '
  + 'usually the directory doing its work rather than a password saved on a desk.';

function winDCMark(node, name, ip) {
  if (!node || !winIsDC(name, ip)) return node;
  node.classList.add('is-dc');
  /* `explain`, never a title attribute: the browser draws its own white
     tooltip for one of those, and this page already has a dark panel
     saying the same thing. Two boxes over one word is what somebody sees.
     Inside a row that explains itself, `explain` folds this into that
     row's panel rather than opening a second one. */
  explain(node, DC_WHY);
  return node;
}

/** The "Controller" cell: the machine that wrote the line down.

    A controller by definition - it is a controller's Security log - so this
    is marked wherever the domain's own answer knows the name. */
function winWroteCell(said) {
  var td = el('td', 'mono small');
  var many = Array.isArray(said) ? said.filter(Boolean) : (said ? [said] : []);
  many.forEach(function (one, i) {
    if (i) td.appendChild(document.createTextNode(' \u00b7 '));
    td.appendChild(winDCMark(el('span', 'mono', String(one)), one, ''));
  });
  if (many.length > 1) {
    explain(td, 'Both of these controllers wrote this lockout down. A domain records a '
      + 'lockout on the controller that saw the last wrong password AND on the one '
      + 'holding the PDC emulator role, because lockouts are its business \u2014 so one '
      + 'lockout is two events, or more, and this is one row for the one thing that '
      + 'happened.');
  }
  return td;
}

/* ---- ...and the same mark, everywhere else on this dashboard ------------
   A controller's name and address turn up on every page here: in the line
   under a card's row, in the Failed attempts table, over an address on the
   front page, in every popup, in the box people type into. Teaching each of
   the dozens of functions that draw those would be dozens of places to
   forget, so this watches what is drawn instead and marks what it
   recognises. Nothing is added to the page as WORDS - the two letters are
   drawn by the stylesheet - so what a row says when it is read back out,
   searched or copied is exactly what it was. */
var DC_MARKING = false;

/** Is this one word a controller? The same folding the daemon uses, so a
    name written five ways is one machine. */
function dcWord(said) {
  var word = String(said || '').trim();
  if (word.length < 2) return false;
  if (WIN_DC_IP[word.toLowerCase()]) return true;
  var short = winShort(word);
  return !!(short && WIN_DC[short]);
}

/* What a distinguished name looks like: an attribute, an equals sign, and
   a value - `DC=`, `CN=`, `OU=`. Anywhere one of those appears, the text is
   a place in the directory rather than a sentence about a machine. */
var IS_DN = /(^|[,;=\s])(dc|cn|ou|uid)=/i;

/** Is this word a step in a PATH rather than a machine doing something?

    `/var/log/remote/dc01/WinSecurity.log` says where a controller's log
    file lives; the machine is not doing anything in it, and two letters in
    the middle of a path make the path hard to read. A slash on both sides is
    what tells them apart - `host/dc01@EXAMPLE.INT` has one on one
    side only, and that is a machine being talked about. */
function dcInPath(bits, at) {
  var before = at > 0 ? String(bits[at - 1] || '') : '';
  var after = at + 1 < bits.length ? String(bits[at + 1] || '') : '';
  if (before.indexOf('/') < 0) return false;
  return after.indexOf('/') >= 0 || after === '';
}

/** Mark every controller named anywhere under this node. */
function dcSweep(root) {
  if (!root || DC_MARKING || !DC_KNOWN) return root;
  if (root.nodeType !== 1 && root.nodeType !== 11) return root;
  /* Somewhere that has said it does not want this: a controller's name in a
     file path is where its log lives, not a controller turning up in a
     record. */
  if (root.closest && root.closest('[data-nodc]')) return root;
  DC_MARKING = true;
  try {
    var walk = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, null, false);
    var found = [];
    var text;
    while ((text = walk.nextNode())) {
      var up = text.parentNode;
      if (!up || up.nodeType !== 1) continue;
      var tag = up.tagName;
      if (tag === 'SCRIPT' || tag === 'STYLE' || tag === 'TEXTAREA'
          || tag === 'OPTION' || tag === 'TITLE') continue;
      /* Already marked, whether by this or by one of the few places that
         mark a cell as they draw it. */
      if (up.classList && up.classList.contains('is-dc')) continue;
      if (up.closest && up.closest('[data-nodc]')) continue;
      var said = text.nodeValue;
      if (!said || said.length > 400 || !/[A-Za-z0-9]/.test(said)) continue;
      /* A distinguished name is where an object LIVES in the directory, not
         a machine doing something: `DC=DC03,DC=example.int,
         cn=MicrosoftDNS,...` is one DNS record, and a mark in the middle of
         it turns a path that is already hard to read into a puzzle. */
      if (IS_DN.test(said)) continue;
      /* One machine may be written `DC02`, `DC02$`,
         `EXAMPLE\DC02`, `dc02.example.int` or as its
         address, so the separators are everything none of those contain. */
      var bits = said.split(/([^0-9A-Za-z.:$\\_-]+)/);
      var any = false;
      for (var i = 0; i < bits.length; i += 2) {
        if (dcWord(bits[i]) && !dcInPath(bits, i)) { any = true; break; }
      }
      if (any) found.push([text, bits]);
    }
    found.forEach(function (one) {
      var text = one[0];
      var bits = one[1];
      var up = text.parentNode;
      if (!up) return;
      var out = document.createDocumentFragment();
      var marks = [];
      bits.forEach(function (bit, at) {
        if (at % 2 === 1 || !dcWord(bit) || dcInPath(bits, at)) {
          if (bit) out.appendChild(document.createTextNode(bit));
          return;
        }
        var mark = el('span', 'is-dc', bit);
        marks.push(mark);
        out.appendChild(mark);
      });
      up.replaceChild(out, text);
      /* Explained once it is IN the row, not before. In the fragment it had
         no panel around it to join, so it opened one of its own - inside a
         row that already explains itself, two boxes over one word.
         The page's own panel, and only that one: a `title` here would be the
         browser's white box drawn on top of it. */
      marks.forEach(function (mark) { explain(mark, DC_WHY); });
    });
  } catch (e) {
    /* A mark is never worth an exception on a page somebody is reading. */
  }
  DC_MARKING = false;
  return root;
}

/** Whatever is drawn from here on, marked as it appears.

    One observer rather than a call at the end of every draw: pages are
    redrawn from thirty places, a popup builds itself, and a row that came
    back on the next poll would otherwise lose its mark. */
var DC_KNOWN = false;
var DC_WATCHER = null;
function dcWatch() {
  if (DC_WATCHER || typeof MutationObserver !== 'function') return;
  DC_WATCHER = new MutationObserver(function (list) {
    if (DC_MARKING || !DC_KNOWN) return;
    list.forEach(function (m) {
      Array.prototype.forEach.call(m.addedNodes || [], function (node) {
        /* What this put there itself needs no second look. */
        if (node.nodeType === 1) {
          if (!node.classList || !node.classList.contains('is-dc')) dcSweep(node);
        } else if (node.nodeType === 3 && node.parentNode
                   && node.parentNode.nodeType === 1
                   && !node.parentNode.classList.contains('is-dc')) {
          dcSweep(node.parentNode);
        }
      });
    });
  });
  DC_WATCHER.observe(document.body, {childList: true, subtree: true});
}

/** Who the controllers are, from whichever answer brought them. */
/* ...and, when there are none, why. A page that marks no controllers looks
   exactly like a domain with nothing to mark, and the difference between
   "this domain has none" and "nobody has ever managed to ask it" was
   nowhere on the page at all. The marking knows a controller from five
   directions; only one of them is the domain's own word for it, so that is
   the one worth naming when it is empty. */
function sayWhyNoDc(dc) {
  var host = $('w-nodc');
  if (!host) return;
  dc = dc || {};
  var named = (dc.from_directory || []).length;
  var any = (dc.names || []).length;
  host.hidden = !!named;
  if (named) return;
  clear(host);
  if (!dc.any_directory) {
    host.appendChild(el('p', 'note',
      'The controllers are not marked anywhere on this page. This program marks one '
      + 'out of what the DOMAIN says is one \u2014 a computer account whose primary '
      + 'group is Domain Controllers \u2014 and Active Directory is not switched on '
      + 'here, so nobody has been asked.'
      + (any ? ' The ' + num(any) + ' worked out from the log folders and the '
             + 'servers that have written lately are marked; nothing else is.' : '')));
    return;
  }
  host.appendChild(el('p', 'note bad',
    'Active Directory is switched on, but it has never named any of its own '
    + 'controllers, so the marking has only the log folders and the servers that have '
    + 'written lately to go on. The question asked is for computer accounts whose '
    + 'primary group is Domain Controllers, under the base in Settings \u2192 Active '
    + 'Directory \u2014 an answer of none almost always means the base does not '
    + 'contain them, or that the account may not read computer objects. It is asked '
    + 'again every half hour, so putting it right shows here without a restart.'));
}

function dcLearn(said) {
  said = said || {};
  var names = said.names || [];
  var ips = said.ips || [];
  var key = names.join(',') + '|' + ips.join(',');
  if (key === DC_KEY) return;
  DC_KEY = key;
  WIN_DC = {};
  WIN_DC_IP = {};
  names.forEach(function (one) {
    var short = winShort(one);
    if (short) WIN_DC[short] = true;
  });
  ips.forEach(function (one) {
    var at = String(one || '').trim().toLowerCase();
    if (at) WIN_DC_IP[at] = true;
  });
  DC_KNOWN = !!(names.length || ips.length);
  if (!DC_KNOWN) return;
  dcWatch();
  /* The page is already full of them by the time the first answer lands. */
  dcSweep(document.body);
}
var DC_KEY = '';

/** The Device column: the name, with the address it answered from on the
    hover. Inline here would double the width of a column that is already the
    widest on the page; a hover is one movement away and says the whole of
    it. */
function deviceCell(r) {
  var td = el('td');
  /* A device's name as ISE knows it - "default" is a name, not "výchozí". */
  td.appendChild(noI18n(el('span', '', String((r || {}).device || '\u2013'))));
  if (r && r.device && r.nad) {
    explain(td, 'It answered from <b>' + wordsIn(r.nad) + '</b> \u2014 the name '
      + 'is what somebody typed into ISE, the address is what is on the network.');
  }
  return td;
}

/** A switch, a controller or a firewall, with the address it answered from.

    ISE writes both down - the name it knows the device by and the address
    the packet came from - and the name alone is half an answer: two sites
    name their switches the same way, a name is what somebody typed into ISE
    and the address is what is actually on the network. So wherever one of
    these is named here, its address is beside it. */
function deviceWords(name, at) {
  var said = String(name || '').trim();
  var ip = String(at || '').trim();
  if (!said) return ip;
  return ip && ip !== said ? said + '  \u00b7  ' + ip : said;
}

/** ...and the same for a socket, which is a socket ON something. */
function portWords(port, name, at) {
  var said = String(port || '').trim();
  if (!said) return '';
  var where = deviceWords(name, at);
  /* Two facts, two lines. `GigabitEthernet1/0/16 · on sw1rco8np · 172.29.2.38`
     on one line is wrapped by the browser wherever it runs out of room, and
     where it ran out was the middle of the address. */
  return where ? said + '\non ' + where : said;
}

/** An address on this page, marked where it is a controller's. */
function winAddr(ip, cls) {
  var said = String(ip || '');
  return winDCMark(el('span', cls || 'mono', said || '\u2013'), '', said);
}

/* An "account" that is not one: a client putting its authentication token
   where the user name goes. Two at-signs and a couple of hundred characters
   of base64, refused every time, for ever - and on a card it is three lines
   of gibberish with the answer pushed off the end. Shown as what it is, with
   the whole of it under the pointer for whoever has to match it up. */
function winTokenName(said) {
  var name = String(said || '').trim();
  if (/^@@[A-Za-z0-9+/=]{16,}$/.test(name)) return true;
  return name.length > 80 && /^[A-Za-z0-9+/=]+$/.test(name);
}

function winWho(name, domain, cls, life) {
  var said = String(name || '');
  /* Whose story pressing it opens. The name as written, for an account; for
     a machine, the account the domain keeps FOR it - `C0033715$` - because
     `C0033715` or `\\ISE1` is how a refusal names the workstation, and no
     account was ever called that. */
  var whose = String(life || said);
  if (winTokenName(said)) {
    var odd = el('span', (cls || 'mono') + ' muted');
    odd.textContent = 'a token, not a name (' + said.slice(0, 12) + '\u2026)';
    explain(odd, 'Not an account. Something put an encoded blob in the user name field, '
      + 'which the domain cannot resolve to anybody \u2014 so it refuses every one of '
      + 'them and always will. There is no such account and there never will be, so this '
      + 'can never let anybody in; what is worth finding is the machine sending it.',
      '<div class="k">' + richText(said) + '</div>');
    return odd;
  }
  var span = el('span', cls || 'mono', said || '\u2013');
  if (!said || said === '-') return span;
  span.classList.add('asksdir');
  opensWith(span, 'The whole story of this account: who made it, who changed it, who '
    + 'unlocked it, who deleted it — and what the directory says about it now. '
    + 'Read only \u2014 nothing is ever written to the directory.',
    function () { winPeekLife(whose, domain || ''); });
  /* Inside a row that opens something of its own, this is its own answer. */
  span.addEventListener('click', function (e) { e.stopPropagation(); });
  return span;
}

/** ...and the same for a machine, which the domain holds as an account too. */
function winMachineWho(name, domain, ip) {
  var said = String(name || '');
  if (!said || said === '-') return el('span', 'mono', '\u2013');
  var account = said.replace(/^\\+/, '');
  if (account && !/\$$/.test(account)) account += '$';
  return winDCMark(winWho(said, domain, 'mono', account || said), said, ip);
}

/** Everything the domain ever did TO one account, in order.

    The question nobody could ask here: who made this account, who changed
    it, who unlocked it, who deleted it. It is answered out of what the
    controllers wrote and never out of the directory — the account this
    matters most about is usually one that no longer exists, and by then the
    directory has nothing to say at all. */
function winPeekLife(account, domain) {
  var said = String(account || '');
  peek('The whole story of \u201c' + said + '\u201d',
    function () { return api('win-life&account=' + encodeURIComponent(said)); },
    function (body, d) {
      /* Only the facts there ARE. Six boxes of dashes over an account
         nothing was ever done to is a page saying nothing at length. */
      body.appendChild(peekFacts([
        ['Account', said],
        ['Things done to it', num(d.n || 0)],
        d.first ? ['First of them', shortStamp(d.first)] : null,
        d.last ? ['Last of them', shortStamp(d.last)] : null,
        (d.made || {}).who ? ['Made by', d.made.who] : null,
        (d.gone || {}).who ? ['Deleted by', d.gone.who] : null
      ]));
      /* The whole reading first, in the same shape the rest of this page
         says what a table of numbers means: made when and by whom, unlocked
         how many times and by whom, deleted when — and, where it was
         deleted, that this IS the whole of what is left of it. */
      if ((d.reads || []).length) {
        var read = el('div', 'verdict');
        read.appendChild(el('div', 'who', said + ' \u2014 what happened to it'));
        (d.reads || []).forEach(function (w) { read.appendChild(el('p', '', w)); });
        body.appendChild(read);
      }
      var nothing = !(d.rows || []).length;
      if (nothing) {
        /* An account that is being REFUSED usually has no life at all:
           nobody created it inside this window, nobody changed it, nobody
           deleted it. That is an answer, not an error - but on its own it
           was a dead end, because the two ways onward were drawn after the
           rows and there were no rows. They are drawn first now. */
        body.appendChild(el('p', 'center muted', 'Nobody made, changed, unlocked or '
          + 'deleted this account in what the controllers wrote down \u2014 so there is '
          + 'no story to tell. What it has been DOING is another matter:'));
        body.appendChild(winLifeWaysOn(said, d, domain));
        explainWhatWasDrawn(body);
        return;
      }
      /* Oldest first, which is the one place on this page a list runs that
         way round: a life is read forwards. */
      var wrap = el('div', 'scroll');
      var table = el('table', 'plain');
      var head = el('thead');
      var hr = el('tr');
      ['When', 'What was done', 'By whom', 'From where', 'What it touched',
       'Controller']
        .forEach(function (w) { hr.appendChild(el('th', '', w)); });
      head.appendChild(hr);
      table.appendChild(head);
      var tb = el('tbody');
      (d.rows || []).forEach(function (r) {
        /* An account with more of these than fits gives up its middle
           rather than either end, and says so where the middle would be. */
        if (r.gap) {
          var gap = el('tr', 'gaprow');
          var cell = el('td', 'center muted small', r.words || '');
          cell.colSpan = 6;
          gap.appendChild(cell);
          tb.appendChild(gap);
          return;
        }
        var tr = el('tr');
        tr.appendChild(stampCell(r.ts));
        var what = el('td');
        what.appendChild(document.createTextNode(r.words || winKindWords(r.kind, r.event)));
        what.appendChild(el('span', 'sub', 'event ' + r.event));
        tr.appendChild(what);
        var by = el('td');
        by.appendChild(r.who ? winWho(r.who, r.domain) : el('span', 'muted', '\u2013'));
        tr.appendChild(by);
        tr.appendChild(winFromCell(r));
        tr.appendChild(winTouchedCell(r));
        tr.appendChild(winWroteCell(r.server));
        opensWith(tr, 'The event exactly as Windows wrote it.',
                  function () { winPeekEvent(r); });
        tb.appendChild(tr);
      });
      table.appendChild(tb);
      wrap.appendChild(table);
      body.appendChild(wrap);
      /* ...and what the directory says about it NOW, where there is one and
         the account is still there to ask about. */
      body.appendChild(winLifeWaysOn(said, d, domain));
      explainWhatWasDrawn(body);
    },
    {tab: 'windows', words: 'Open the domain page', icon: 'shield'});
}

/** A program by its own name rather than by where it lives on a disk. */
function shortProcess(said) {
  var name = String(said || '');
  var cut = Math.max(name.lastIndexOf('\\'), name.lastIndexOf('/'));
  return cut >= 0 ? name.slice(cut + 1) : name;
}

function winPeekLock(r) {
  peek('The lockout of “' + (r.account || '') + '”',
    function () {
      return api('win-around&account=' + encodeURIComponent(r.account || '')
                 + '&at=' + Math.round(r.ts) + '&before=3600&after=900&bad=1');
    },
    function (body, d) {
      body.appendChild(peekFacts([
        ['Account', winWho(r.account, r.domain)],
        ['Locked at', shortStamp(r.ts)],
        ['From the machine', r.machine ? winMachineWho(r.machine, r.domain, r.ip)
                                       : 'the domain did not say'],
        /* Left out rather than drawn empty. A lockout carries no program of
           its own and the refusals before it are Kerberos and NTLM events,
           which name a machine and not a program, so "Through" is usually
           nothing at all - and an empty box under a heading reads as a
           thing this page could not work out rather than a thing Windows
           never wrote down. */
        r.ip ? ['From the address', r.ip] : null,
        shortProcess(r.process) ? ['Through', shortProcess(r.process)] : null,
        ['Noticed by', r.server],
        ['How it ended', winFreedWords(r.freed)]
      ]));
      body.appendChild(el('p', 'note', 'A lockout says only that it happened. What was '
        + 'actually tried is in the refusals before it — and the machine and the '
        + 'program on them are almost always the answer: a saved password in a mail '
        + 'client, a mapped drive, a scheduled task or a phone that nobody changed.'));
      /* ...counted, before the list of them. One row per machine and
         program is what somebody can act on; twenty-five refusals in a row
         is what they would have to count by eye to get to it. */
      body.appendChild(winBlameTable(r.blame || [], 'What was holding the password'));
      body.appendChild(winRowsTable(d.rows || [], 'peek-lock'));
      var doing = el('div', 'btnrow');
      doing.style.marginTop = '10px';
      var story = cmdButton('The whole story of ' + (r.account || 'this account'),
                            'shield', '');
      explain(story, 'Who made this account, who changed it, who unlocked it and who '
        + 'deleted it \u2014 in order, out of what the controllers wrote down.');
      story.onclick = function () { winPeekLife(r.account, r.domain); };
      doing.appendChild(story);
      body.appendChild(doing);
      explainWhatWasDrawn(body);
    },
    {tab: 'windows', words: 'Open the domain page', icon: 'shield'});
}

/** The two ways on from a life: what it has been doing, and who it is.

    Drawn whether or not there is a life to show. An account nothing was
    ever done TO is the commonest case on this page — every account being
    refused is one — and a popup that said so and offered nothing was a
    door into a blank room. */
function winLifeWaysOn(said, d, domain) {
  var doing = el('div', 'btnrow');
  doing.style.marginTop = '12px';
  var every = cmdButton('Everything the controllers wrote about ' + said, 'list', '');
  explain(every, 'Every event about this account rather than only the things done TO '
    + 'it: the sign-ins, the refusals, the tickets, the lockouts.');
  every.onclick = function () {
    winPeekEvents('Account \u201c' + said + '\u201d', {account: said, routine: '0'},
      'Everything the domain controllers wrote about it.', said,
      {hours: 24 * 7, machines: /\$$/.test(said), words: 'the last 7 day(s)'});
  };
  doing.appendChild(every);
  if ((STATUS || {}).directory_on && !(d || {}).gone) {
    var ask = cmdButton('Ask the directory about ' + said, 'people', '');
    explain(ask, 'What Active Directory says about it right now: who the person is, '
      + 'which groups they are in, whether it is switched off, locked or expired. '
      + 'Read only \u2014 nothing is ever written to the directory.');
    ask.onclick = function () {
      showPerson(said, '', (d || {}).domain || domain || '');
    };
    doing.appendChild(ask);
  }
  return doing;
}

/** Where one of these was done from: which machine, which address.

    Windows writes neither on an account change — not on 4720, not on 4724,
    not on 5136. What it writes is the logon session that made it, and the
    sign-in that opened that session carries the workstation and the address,
    so the daemon joins the two. Where the sign-in is older than what is
    kept, this says nothing rather than naming the controller the change
    happened to be written on, which would be true and useless. */
function winFromCell(r) {
  var td = el('td', 'small');
  var name = String(r.from_machine || '');
  var ip = String(r.from_ip || '');
  if (!name && !ip) { td.appendChild(el('span', 'muted', '\u2013')); return td; }
  if (name) {
    td.appendChild(winMachineWho(name, r.domain, ip));
    if (ip) td.appendChild(el('span', 'sub mono', ip));
  } else {
    td.appendChild(winAddr(ip));
  }
  return td;
}

/** What one event in a life actually touched, with the useful half first.

    A directory change carries its object as `cn=x,OU=…,DC=… · attribute
    (value added)`, and the part that says what CHANGED is at the end of it —
    so a cell that simply cuts the text short shows the tree and throws away
    the answer. The attribute leads and the distinguished name goes
    underneath, where it belongs: everybody reading a life already knows
    which account it is about. */
function winTouchedCell(r) {
  var td = el('td', 'small');
  var said = String(r.object || r.said || '');
  if (!said) { td.textContent = '\u2013'; return td; }
  var at = said.lastIndexOf(' \u00b7 ');
  if (at > 0) {
    td.appendChild(el('span', 'mono', said.slice(at + 3)));
    td.appendChild(el('span', 'sub mono', said.slice(0, at)));
  } else {
    td.appendChild(el('span', 'mono', said.length > 90 ? said.slice(0, 90) + '\u2026' : said));
  }
  return td;
}

/** Whether somebody has already dealt with a lockout, and who.

    Windows writes the unlock as its own event about the same account, so the
    one that ended a given lock is the first of them after it. Without this a
    lockout that was cleared two minutes later and one that is still locked
    read exactly the same on this page — and which of the two it is is the
    first thing anybody wants to know. */
function winFreedWords(freed) {
  if (!freed || !freed.ts) {
    return el('span', 'bad', 'still locked, as far as these logs go');
  }
  /* A deletion ends a lockout as surely as an unlock does, and saying
     "still locked" about an account somebody deleted is the page arguing
     with its own data — the events two rows down name who deleted it. */
  var gone = freed.how === 'deleted';
  var box = el('span', gone ? 'muted' : '');
  box.appendChild(document.createTextNode(
    gone ? 'never unlocked \u2014 the account was deleted ' : 'unlocked '));
  box.appendChild(document.createTextNode(shortStamp(freed.ts)));
  if (freed.after) {
    box.appendChild(document.createTextNode(', ' + span(freed.after) + ' later'));
  }
  if (freed.who) {
    box.appendChild(document.createTextNode(', by '));
    box.appendChild(winWho(freed.who, ''));
  }
  return box;
}

/** What has been trying one account, by machine and by program.

    The table behind the one question a lockout leaves behind. No single
    Windows event holds the answer: the refusal says which machine and which
    address, and the explicit-credential event beside it says which program
    on that machine went and used the password. */
function winBlameTable(rows, title) {
  var box = el('div');
  if (!(rows || []).length) return box;
  box.appendChild(el('h3', 'peek-h', title || 'What was trying it'));
  var wrap = el('div', 'scroll');
  var table = el('table', 'plain');
  var head = el('thead');
  var hr = el('tr');
  ['Machine', 'Address', 'Through', 'Times', 'What the domain said', 'Last one']
    .forEach(function (w, i) { hr.appendChild(el('th', i === 3 ? 'num' : '', w)); });
  head.appendChild(hr);
  table.appendChild(head);
  var body = el('tbody');
  rows.forEach(function (one) {
    var tr = el('tr');
    var box = el('td', 'mono');
    box.appendChild(one.machine ? winMachineWho(one.machine, one.domain, one.ip)
                                : document.createTextNode('–'));
    /* Said so where it was worked out rather than written down: Windows puts
       an address on a Kerberos refusal and no name at all, and the name is
       this database answering its own question from the machine account that
       signs in from that address. Right nearly always, and a guess either
       way, so it says which it is. */
    if (one.machine_guessed) box.appendChild(el('span', 'sub', 'by its address'));
    tr.appendChild(box);
    var at = el('td', 'mono small');
    if (one.ip) at.appendChild(winAddr(one.ip, 'mono'));
    /* An NTLM refusal names the machine and never its address: this one was
       worked out from the machine's own sign-ins, and says so, the way a
       machine named by its address does just above. */
    if (one.ip && one.ip_guessed) at.appendChild(el('span', 'sub', 'by its name'));
    tr.appendChild(at);
    var how = el('td');
    how.appendChild(el('span', '', shortProcess(one.process) || '–'));
    if (one.service) how.appendChild(el('span', 'sub', one.service));
    tr.appendChild(how);
    tr.appendChild(el('td', 'num', num(one.n)));
    var why = el('td', 'small');
    why.textContent = (one.why || []).map(function (w) {
      return w.said + (w.n > 1 ? ' (' + num(w.n) + ')' : '');
    }).join(' · ');
    tr.appendChild(why);
    tr.appendChild(el('td', 'small muted', one.last ? shortStamp(one.last) : ''));
    if (one.process) {
      explain(tr, 'The program on that machine that went and used the password.',
        '<div class="k"><b>The whole path:</b> ' + richText(one.process) + '</div>');
    }
    body.appendChild(tr);
  });
  table.appendChild(body);
  wrap.appendChild(table);
  box.appendChild(wrap);
  /* ...and what all that MEANS, which is the whole reason anybody opened
     this. A table of numbers still leaves somebody working out whether a
     person is typing a password wrong or a program is holding an old one,
     and then which machine to walk to. Both are in the data; neither is in
     any single event; so they are said in words. */
  rows.forEach(function (one) {
    if (!(one.reads || []).length && !(one['next'] || []).length) return;
    var read = el('div', 'verdict');
    read.appendChild(el('div', 'who',
      (one.machine || one.ip || 'this one') + ' \u2014 what that means'));
    (one.reads || []).forEach(function (w) { read.appendChild(el('p', '', w)); });
    (one['next'] || []).forEach(function (w) { read.appendChild(el('p', 'go', w)); });
    box.appendChild(read);
  });
  return box;
}

/* ---- the cards ------------------------------------------------------------ */
function drawWinViews(views) {
  var host = $('w-views');
  if (sameAsDrawn(host, views) && host.firstChild) return;
  steady(host);
  clear(host);
  var grid = null;
  views.forEach(function (view, n) {
    if (n % 2 === 0) {
      grid = el('div', 'grid halves');
      grid.style.marginTop = '14px';
      host.appendChild(grid);
    }
    grid.appendChild(winViewCard(view));
  });
  settle(host);
}

function winViewCard(view) {
  var card = el('div', 'card facet');
  card.appendChild(el('h2', '', view.name));
  if (view.says) card.appendChild(el('p', 'note', view.says));
  var rows = view.rows || [];
  var top = rows.reduce(function (m, r) { return Math.max(m, r.n); }, 1);
  var table = el('table');
  var body = el('tbody');
  rows.forEach(function (r) {
    var got = r.newest || {};
    var tr = el('tr');
    var first = el('td', 'said');
    /* A card grouped by an account or a machine names one, and that name
       has another half in the directory. Pressing the NAME opens what the
       directory holds; pressing anything else on the row opens the events
       it was counted from, which is what it always did. */
    var name;
    if (view.by === 'account' || view.by === 'by_who') {
      name = winWho(r.said, (r.newest || {}).domain);
    } else if (view.by === 'machine') {
      name = winMachineWho(r.said, (r.newest || {}).domain, (r.newest || {}).ip);
    } else if (view.by === 'ip') {
      name = winAddr(r.said);
    } else {
      name = el('span', 'mono');
      name.textContent = String(r.said);
    }
    first.appendChild(name);
    /* How WIDE this row is, before anything about one event on it.

       The number at the end of the row belongs to the row - to this answer,
       this machine, this address - and the line under the name is the newest
       of what it counted. Drawn without saying so, the two read as one
       sentence: "the password was wrong, 65628adm, 118" is read as a hundred
       and eighteen wrong passwords for that account, and it is a hundred and
       eighteen for four different accounts of which that is simply the last.
       So a row that covers more than one of something says how many, and
       what follows is marked as the newest rather than as the whole. */
    var wide = [];
    if (view.by !== 'account' && r.names > 1) wide.push(num(r.names) + ' accounts');
    if (view.by !== 'machine' && r.machines > 1) wide.push(num(r.machines) + ' machines');
    if (view.by !== 'ip' && r.places > 1) wide.push(num(r.places) + ' addresses');
    var under = [];
    if (view.by !== 'account' && got.account) under.push(got.account);
    if (view.by !== 'machine' && got.machine) under.push(got.machine);
    if (view.by !== 'ip' && got.ip) under.push(got.ip);
    if (view.by === 'by_who' || view.by === 'object') {
      if (got.kind) under.push(winKindWords(got.kind, got.event));
    } else if (view.by !== 'said' && got.said) {
      under.push(got.said);
    }
    if (got.process && (view.by === 'account' || view.by === 'machine')) {
      under.push(shortProcess(got.process));
    }
    if (wide.length) {
      under = under.length ? ['newest: ' + under.join(' · ')] : [];
      under = wide.concat(under);
    }
    /* ...and the one line that answers it. A card that says "pdf, 120" and
       makes somebody open a popup to find out whether that is a person or a
       program is a card that has not answered anything. */
    if ((r.reads || []).length) under.push(r.reads[0]);
    if (under.length) {
      var sub = el('div', 'sub');
      sub.textContent = under.join(' · ');
      first.appendChild(sub);
    }
    tr.appendChild(first);
    var mid = el('td', 'barcell');
    var bar = el('div', 'bar');
    var fill = el('span');
    fill.style.width = Math.round(100 * r.n / top) + '%';
    bar.appendChild(fill);
    mid.appendChild(bar);
    tr.appendChild(mid);
    tr.appendChild(el('td', 'n', num(r.n)));
    tr.appendChild(el('td', 'n when muted', r.last ? shortStamp(r.last) : ''));
    opensWith(tr, '', function () { winPeekSubject(view, r); });
    explain(tr, 'Press it for the events themselves.', winRowSays(view, r));
    body.appendChild(tr);
  });
  table.appendChild(body);
  card.appendChild(table);
  return card;
}

function winRowSays(view, r) {
  var got = r.newest || {};
  var said = ['<div class="maker">' + richText(String(r.said)) + '</div>'];
  /* The whole reading, above the facts it was made from: what this is, and
     where to go about it. */
  (r.reads || []).forEach(function (w) {
    said.push('<div class="k">' + richText(w) + '</div>');
  });
  (r['next'] || []).forEach(function (w) {
    said.push('<div class="k"><b>\u2192</b> ' + richText(w) + '</div>');
  });
  [['Events', num(r.n)],
   ['Last one', r.last ? shortStamp(r.last) : ''],
   ['Different accounts', r.names > 1 ? num(r.names) : ''],
   ['Different machines', r.machines > 1 ? num(r.machines) : ''],
   ['Different addresses', r.places > 1 ? num(r.places) : ''],
   /* Everything below this line is ONE event - the newest of the ones
      counted above it - and it is said so, because a name under a count is
      otherwise read as the name the count belongs to. */
   ['The newest of them was', got.kind ? winKindWords(got.kind, got.event) : ''],
   ['Account', got.account], ['Done by', got.by_who], ['Machine', got.machine],
   ['Address', got.ip], ['How', got.logon_type ? winLogonWords(got.logon_type) : ''],
   ['Program', shortProcess(got.process)], ['Object', got.object],
   ['Why', got.said], ['Controller', got.server]
  ].forEach(function (one) {
    if (!one[1]) return;
    said.push('<div class="k"><b>' + richText(one[0]) + ':</b> '
              + richText(String(one[1])) + '</div>');
  });
  return said.join('');
}

/* Which column each card is grouped by, said once. Pressing a row has to
   open the rows that row was counted from - so the value goes back as THAT
   column and not as a search. It was a search, and a row reading "the answer
   was: the password was wrong, 118" opened a text search over nine columns:
   the list underneath was a mixture of accounts and the count above it did
   not match the one on the card. */
var WIN_BY_COLUMN = {account: 'account', machine: 'machine', ip: 'ip',
                     by_who: 'by_who', process: 'process', object: 'object',
                     said: 'said'};

function winPeekSubject(view, r) {
  /* One card is not a filter over the events at all: “accounts made, changed
     and deleted” counted what was DONE to each account, and what somebody
     pressing one of those rows is asking is the story — who made it, who
     changed it, who unlocked it, who deleted it, in order. */
  if (view.key === 'lives') { return winPeekLife(r.said, r.domain || ''); }
  var ask = {kind: (view.kinds || []).join(',')};
  /* Where the daemon counted the row with a filter of its own, that filter
     is what opens it. A row of "what is holding the old password" is one
     account FROM one machine THROUGH one program, and rebuilt from the name
     at the front of it alone it opened every refusal that account had
     anywhere. */
  if (r.ask) {
    Object.keys(r.ask).forEach(function (k) { if (r.ask[k]) ask[k] = r.ask[k]; });
  } else {
    var column = WIN_BY_COLUMN[view.by];
    if (column) ask[column] = r.said;
    else ask.q = r.said;
  }
  /* ...and the machinery this card left out is left out of the list too, or
     the two numbers cannot agree. */
  ask.routine = '0';
  /* An account gets the answer before the evidence: which machines and which
     programs have been trying it, counted, above the events they are counted
     from. It is the one question anybody has about an account being refused,
     and nobody should have to read two hundred rows to work it out. */
  winPeekEvents(winSubjectTitle(view) + ' “' + r.said + '”', ask, view.says,
                view.by === 'account' ? r.said : '');
}

function winSubjectTitle(view) {
  return {'people': 'Account', 'machines': 'Machine', 'places': 'Address',
          'holding': 'What keeps trying',
          'reasons': 'Answer', 'changes': 'Changed by', 'objects': 'What was changed',
          'lives': 'Account'
         }[view.key] || 'Row';
}

/* ---- the events themselves ------------------------------------------------ */
var WIN_KIND_WORDS = {
  'lockout': 'locked out', 'unlock': 'unlocked', 'logon': 'signed in',
  'logon-failed': 'refused', 'logoff': 'signed out', 'kerberos': 'a Kerberos ticket',
  'kerberos-failed': 'Kerberos refused it', 'ntlm': 'password checked',
  'ntlm-failed': 'password refused', 'explicit': 'credentials typed in',
  'privilege': 'administrator rights', 'account': 'an account changed',
  'group': 'a group changed', 'directory': 'the directory changed',
  'read': 'the directory was read',
  'policy': 'a policy changed', 'computer': 'a computer account',
  'process': 'a program started', 'audit': 'the auditing itself', 'other': 'something else'
};
/* What each event actually SAYS, rather than which group it belongs to.
   “an account was deleted (4726)” instead of “an account changed (4726)”,
   which is the difference between a page that reads and a page that has to be
   decoded. Kept equal to the daemon’s own table by a test, so the two can
   never drift apart. */
var WIN_EVENT_WORDS = { '1100': 'the event log service was shut down',
