  '4616': 'the system time was changed', '4624': 'an account signed in',
  '4625': 'an account failed to sign in', '4634': 'an account signed out',
  '4627': 'the groups an account signed in with',
  '4656': 'a handle to an object was asked for',
  '4658': 'a handle to an object was let go',
  '4663': 'an object was accessed', '4689': 'a program ended',
  '4647': 'somebody signed out',
  '4648': 'a sign-in with credentials typed in',
  '4657': 'a registry value was changed',
  '4662': 'an operation on a directory object',
  '4670': 'permissions on an object were changed',
  '4672': 'an administrator signed in',
  '4673': 'a privileged service was called', '4688': 'a program was started',
  '4697': 'a service was installed', '4698': 'a scheduled task was created',
  '4699': 'a scheduled task was deleted',
  '4700': 'a scheduled task was switched on',
  '4702': 'a scheduled task was changed',
  '4713': 'Kerberos policy was changed',
  '4715': 'the audit policy on an object was changed',
  '4719': 'the audit policy was changed', '4720': 'an account was created',
  '4722': 'an account was switched on',
  '4723': 'somebody changed their own password',
  '4724': 'an administrator reset a password',
  '4725': 'an account was switched off', '4726': 'an account was deleted',
  '4728': 'an account was added to a global group',
  '4729': 'an account was removed from a global group',
  '4732': 'an account was added to a local group',
  '4733': 'an account was removed from a local group',
  '4735': 'a local group was changed', '4737': 'a global group was changed',
  '4738': 'an account was changed', '4739': 'the domain policy was changed',
  '4740': 'an account was locked out',
  '4741': 'a computer account was created',
  '4742': 'a computer account was changed',
  '4743': 'a computer account was deleted',
  '4756': 'an account was added to a universal group',
  '4757': 'an account was removed from a universal group',
  '4767': 'an account was unlocked',
  '4768': 'a Kerberos ticket was asked for',
  '4769': 'a Kerberos service ticket was asked for',
  '4770': 'a Kerberos ticket was renewed',
  '4771': 'Kerberos refused a password',
  '4772': 'a Kerberos ticket request failed',
  '4773': 'a Kerberos service ticket request failed',
  '4776': 'the domain checked a password',
  '4777': 'the domain refused a password', '4781': 'an account was renamed',
  '4794': 'somebody tried to set the recovery password',
  '4798': 'somebody\u2019s group membership was listed',
  '4799': 'a group\u2019s membership was listed',
  '4964': 'a member of a watched group signed in',
  '5136': 'a directory object was changed',
  '5137': 'a directory object was created',
  '5138': 'a directory object was undeleted',
  '5139': 'a directory object was moved',
  '5141': 'a directory object was deleted',
  '5376': 'credentials were saved to Credential Manager',
  '5377': 'credentials were restored from Credential Manager'
};
function winKindWords(kind, event) {
  var exact = event ? WIN_EVENT_WORDS[String(event)] : '';
  if (exact) { return exact + ' (' + event + ')'; }
  var said = WIN_KIND_WORDS[kind] || String(kind || '');
  return event ? (said + ' (' + event + ')') : said;
}
var WIN_LOGON_WORDS = {'2': 'at the keyboard', '3': 'over the network',
  '4': 'a scheduled task', '5': 'a service starting', '7': 'unlocking the screen',
  '8': 'over the network, password in the clear', '9': 'with different credentials',
  '10': 'a remote desktop', '11': 'with cached credentials',
  '12': 'a remote desktop, cached', '13': 'unlocking, cached'};
function winLogonWords(said) {
  return WIN_LOGON_WORDS[String(said)] || ('logon type ' + said);
}

/* ---- the records themselves ----------------------------------------------
   The same page the failed attempts and the logins are: asked of the server a
   page at a time, narrowed by the same kind of filters, with tabs across the
   top for the groups of events and every row opening the whole record.
   ------------------------------------------------------------------------ */
function loadWinEvents(quietly) {
  var per = Number($('w-limit').value || 100);
  var ask = ['win-events', 'limit=' + per, 'offset=' + (WPAGE * per)];
  if (sortArgs(SORTS.win)) ask.push(sortArgs(SORTS.win));
  if (windowArgs('w-hours')) ask.push(windowArgs('w-hours'));
  if ($('w-q').value.trim()) {
    ask.push('q=' + encodeURIComponent(qRewrite($('w-q').value.trim(), qMaps('win'))));
  }
  if (WKIND) ask.push('kind=' + encodeURIComponent(WKIND));
  if ($('w-event').value) ask.push('event=' + encodeURIComponent($('w-event').value));
  if ($('w-server').value) ask.push('server=' + encodeURIComponent($('w-server').value));
  if ($('w-machines').checked) ask.push('machines=1');
  var mine = ++WLIST;
  return api(ask.shift() + '&' + ask.join('&'), undefined,
             {lane: 'win-events', quiet: quietly === true}).then(function (d) {
    if (mine !== WLIST) return;               /* two presses; this is the older */
    $('w-events-n').textContent = (d.capped ? 'more than ' : '') + num(d.total) + ' event(s)'
      + (d.sort_window && (d.capped || d.total > d.sort_window)
         ? ' \u00b7 ordered among the newest ' + num(d.sort_window) : '');
    $('w-pages-n').textContent = (d.capped ? '>' : '') + num(d.total);
    fillOnce($('w-server'), d.servers);
    fillPairs($('w-event'), (d.events || []).map(function (e) {
      return [String(e.event), e.event + ' \u00b7 ' + e.words + ' (' + num(e.n) + ')'];
    }));
    if (d.counts) {
      WCOUNTS = d.counts;
      winKindTabs(d.tabs || []);
    }
    var head = $('w-head');
    clear(head);
    headCells(['When', 'What happened', 'Account', 'From', 'Through', 'Why', 'Controller'])
      .forEach(function (th) { head.appendChild(th); });
    serverSortHeads(head, SORTS.win, WIN_SORT_KEYS, function () {
      WPAGE = 0;
      loadWinEvents();
    });
    var body = $('w-table').querySelector('tbody');
    clear(body);
    $('w-empty').hidden = !!(d.rows || []).length;
    (d.rows || []).forEach(function (r) {
      var tr = el('tr');
      tr._rec = r;
      tr.dataset.ident = r.ident || '';
      tr.appendChild(stampCell(r.ts));
      var what = el('td');
      what.appendChild(el('span', '', winKindWords(r.kind)));
      what.appendChild(el('span', 'sub', 'event ' + r.event));
      tr.appendChild(what);
      var who = el('td');
      var name = el('span', 'mono');
      name.textContent = r.account || '\u2013';
      who.appendChild(name);
      /* The same button that stands beside a name everywhere else on this
         dashboard, asking the directory that holds THIS event's domain. */
      if (r.account && !r.is_machine) whoIsIt(who, String(r.account).split('@')[0],
                                              String(r.domain || '').toLowerCase());
      if (r.domain) who.appendChild(el('span', 'sub', r.domain));
      if (r.by_who && r.by_who !== r.account) {
        who.appendChild(el('span', 'sub', 'by ' + r.by_who));
      }
      tr.appendChild(who);
      var from = el('td');
      from.appendChild(r.machine ? winDCMark(el('span', 'mono', r.machine), r.machine, r.ip)
                                 : winAddr(r.ip));
      if (r.machine && r.ip) from.appendChild(el('span', 'sub', r.ip));
      if (r.logon_type) from.appendChild(el('span', 'sub', winLogonWords(r.logon_type)));
      tr.appendChild(from);
      tr.appendChild(el('td', 'dim', shortProcess(r.process) || '\u2013'));
      var why = el('td', 'dim');
      why.textContent = String(r.said || r.object || '').slice(0, 80);
      tr.appendChild(why);
      tr.appendChild(winWroteCell(r.server));
      opensWith(tr, '', function () { winPeekEvent(r); });
      body.appendChild(tr);
    });
    optColumns($('w-table'), OPT_WIN);
    pager('w-pager', WPAGE, per, d.total, function (to) {
      WPAGE = to;
      loadWinEvents();
      /* The rows move inside the card now, so the top of the list is the
         top of the box rather than a place on the page to scroll to. */
      var box = $('w-table').parentNode;
      if (box && box.scrollTop) box.scrollTop = 0;
    }, d.capped);
    explainWhatWasDrawn($('tab-windows'));
    /* Measured again with the rows in it: an empty table and a full one are
       different heights, and the page is only as long as what is in it. */
    if (typeof holdTheTallOnes === 'function') holdTheTallOnes();
  }).catch(oops);
}

/* The groups of events, as tabs over the list. The same shape the doors on
   the failed attempts page are, and drawn from what is actually there. */
function winKindTabs(tabs) {
  var host = $('w-kinds');
  clear(host);
  var all = tabs.reduce(function (n, t) { return n + t.n; }, 0);
  function tab(key, words, n, says) {
    var b = el('button');
    b.setAttribute('role', 'tab');
    /* Both, the way every other strip on this page does it: `aria-selected`
       for whatever is reading it out, and the class the stylesheet colours.
       This one set only the first, so the chosen tab looked like the rest. */
    b.className = WKIND === key ? 'on' : '';
    b.setAttribute('aria-selected', WKIND === key ? 'true' : 'false');
    b.appendChild(el('span', '', words));
    if (n) b.appendChild(el('span', 'n', num(n)));
    if (says) explain(b, says);
    b.onclick = function () {
      WKIND = key;
      WPAGE = 0;
      loadWinEvents();
    };
    host.appendChild(b);
  }
  tab('', 'Everything', all, 'Every event read from the controllers.');
  tabs.forEach(function (t) {
    if (!t.n) return;
    tab(t.kinds.join(','), t.name, t.n, t.says);
  });
}

/** One table of events, wherever they are being shown. */
function winRowsTable(rows, key) {
  return listView({
    key: key,
    rows: rows,
    per: 25,
    empty: 'Nothing here in this window',
    hay: function (r) {
      return [r.account, r.by_who, r.machine, r.ip, r.said, r.object, r.process,
              winKindWords(r.kind, r.event), r.server].join(' ');
    },
    placeholder: 'an account, a machine, an address, a reason\u2026',
    draw: function (page, host) {
      host.appendChild(listTable(
        ['When', 'What happened', 'Account', 'From', 'Why'], page,
        function (r) {
          var tr = el('tr');
          tr.appendChild(stampCell(r.ts, 'dim'));
          tr.appendChild(el('td', '', winKindWords(r.kind, r.event)));
          var who = el('td');
          who.appendChild(winWho(r.account, r.domain));
          if (r.by_who && r.by_who !== r.account) {
            var by = el('span', 'sub');
            by.appendChild(document.createTextNode('by '));
            by.appendChild(winWho(r.by_who, r.domain, 'mono small'));
            who.appendChild(by);
          }
          tr.appendChild(who);
          var from = el('td');
          from.appendChild(r.machine ? winMachineWho(r.machine, r.domain, r.ip)
                                     : winAddr(r.ip));
          if (r.machine && r.ip) from.appendChild(el('span', 'sub', r.ip));
          tr.appendChild(from);
          tr.appendChild(el('td', 'dim', String(r.said || r.object || '').slice(0, 70)));
          opensWith(tr, 'The event exactly as Windows wrote it.',
                    function () { winPeekEvent(r); });
          return tr;
        }, 'plain'));
    }
  });
}

/** One event, every field of it — and who the account belongs to.

    The directory is asked for the account this event is about, and asked by
    the DOMAIN the event carries: a site with two of them has two directories
    here, and `EXAMPLE` and `CORPNET` are two different places to look. Where
    the domain matches neither, both are asked, which is what this program
    does everywhere else a name has no domain on it. Read only, always. */
function winPeekEvent(r) {
  peek(winKindWords(r.kind, r.event),
    function () {
      /* ...with when it is, so the database looks in that day only. */
      return api('win-event&ident=' + encodeURIComponent(r.ident)
                 + (r.ts ? '&ts=' + encodeURIComponent(r.ts) : ''));
    },
    function (body, d) {
      var got = d.event || {};
      if (got.account && (STATUS || {}).directory_on) {
        var ask = cmdButton('Ask the directory about ' + got.account, 'people', 'primary');
        explain(ask, 'What Active Directory says about this account right now: who they '
          + 'are, which groups they are in, whether the account is switched off, locked '
          + 'or expired, and when the password was last set. Asked of the directory that '
          + 'holds ' + (got.domain || 'this domain') + '; nothing here ever writes to a '
          + 'directory.');
        ask.onclick = function () {
          showPerson(String(got.account).split('@')[0], '',
                     String(got.domain || '').toLowerCase());
        };
        var row = el('div', 'btnrow');
        row.appendChild(ask);
        body.appendChild(row);
      }
      body.appendChild(peekFacts([
        ['When', shortStamp(got.ts)],
        ['What', winKindWords(got.kind, got.event)],
        ['Account', got.account],
        ['Done by', got.by_who],
        ['Machine', got.machine],
        ['Address', got.ip],
        ['How', got.logon_type ? winLogonWords(got.logon_type) : ''],
        ['Program', shortProcess(got.process)],
        ['Why', got.said],
        ['Controller', got.server]
      ].filter(function (one) { return one[1]; })));
      if (got.object) {
        body.appendChild(el('p', 'note', 'What it was about:'));
        body.appendChild(el('pre', 'wrap', got.object));
      }
      body.appendChild(el('p', 'note', 'Every field Windows wrote, as it wrote it:'));
      var table = el('table', 'plain tight');
      var tb = el('tbody');
      Object.keys(got.fields || {}).forEach(function (k) {
        var tr = el('tr');
        tr.appendChild(el('td', 'muted', k));
        var td = el('td');
        td.appendChild(el('span', 'mono small', String(got.fields[k])));
        tr.appendChild(td);
        tb.appendChild(tr);
      });
      table.appendChild(tb);
      body.appendChild(table);
      /* ...and what else happened to that account around it, which is the
         question every one of these leads to. */
      if (got.account) {
        body.appendChild(el('p', 'note', 'What else happened to that account around then:'));
        var around = el('div');
        body.appendChild(around);
        api('win-around&account=' + encodeURIComponent(got.account) + '&at='
            + Math.round(got.ts) + '&before=900&after=900').then(function (more) {
          clear(around);
          around.appendChild(winRowsTable((more.rows || []).filter(function (one) {
            return one.ident !== got.ident;
          }), 'peek-around'));
        }).catch(function () { /* the event itself is the answer; this is extra */ });
      }
    });
}

/** What the domain saw about one account, folded into somebody else's popup.
    Drawn only where the domain controllers are being read at all, and only
    where they have anything to say - an empty heading answers nothing. */
function winBeside(body, name, hours) {
  if (!(STATUS || {}).winsec_on || !name) return;
  var where = el('div');
  body.appendChild(where);
  var bare = String(name).split('@')[0].split('\\').pop();
  api('win-events&hours=' + (hours || 168) + '&limit=60&machines=1&choices=0&account='
      + encodeURIComponent(bare)).then(function (d) {
    if (!d.total) return;
    var locks = (d.rows || []).filter(function (r) { return r.kind === 'lockout'; });
    var head = el('h3', 'peek-h', 'What the domain saw');
    where.appendChild(head);
    where.appendChild(el('p', 'note', locks.length
      ? ('This account has been locked ' + num(locks.length) + ' time(s) in the last week. '
         + 'The machine and the program on the refusals below it are almost always the '
         + 'answer: a saved password in a mail client, a mapped drive, a phone.')
      : 'Everything the domain controllers wrote down about this account in the last week '
        + '\u2014 sign-ins, refusals, changes. None of it is judged here.'));
    where.appendChild(winRowsTable(d.rows, 'peek-name-win'));
  }).catch(function () { /* the rest of the popup is the answer; this is extra */ });
}

/** A list of events asked for by whatever narrows them. */
function winPeekEvents(title, ask, says, blameFor, over) {
  /* `over` is for the one caller that is not on this page: the box at the
     top of every page, which searched its own window and has to open what
     it said it found rather than whatever the Domain page happens to be set
     to. Everything else follows the page, which is what somebody looking at
     it expects. */
  over = over || {};
  /* The front page draws the domain's cards too, out of ITS window and
     without the Domain page's tick box - so a card pressed there opens the
     events of that window, not of whatever the Domain page is set to. A
     card reading 21,810 over a popup reading nought was exactly that. */
  var front = TAB === 'overview';
  var hours = over.hours !== undefined ? over.hours : (front ? overHours() : winHours());
  var words = over.words || (front ? overWindowWords()
    : $('w-window').options[$('w-window').selectedIndex].textContent.trim());
  var machines = over.machines !== undefined ? !!over.machines
    : (!front && $('w-machines').checked);
  var query = 'win-events&hours=' + hours + '&limit=250&choices=0';
  Object.keys(ask || {}).forEach(function (k) {
    if (ask[k]) query += '&' + k + '=' + encodeURIComponent(ask[k]);
  });
  if (machines) query += '&machines=1';
  peek(title,
    function () {
      if (!blameFor) return api(query).then(function (d) { return {events: d}; });
      /* Both at once: a popup that fills in twice is a popup that jumps
         under somebody's eyes while they are reading it. */
      return Promise.all([
        api(query),
        api('win-blame&account=' + encodeURIComponent(blameFor)
            + (machines ? '&machines=1' : '')
            + '&hours=' + hours).catch(function () { return {rows: []}; })
      ]).then(function (both) { return {events: both[0], blame: both[1]}; });
    },
    function (body, got) {
      var d = got.events || {};
      body.appendChild(peekFacts([['Events', (d.capped ? 'more than ' : '') + num(d.total)],
                                  ['Window', words]]));
      if (says) body.appendChild(el('p', 'note', says));
      var blame = ((got.blame || {}).rows) || [];
      if (blame.length) {
        body.appendChild(winBlameTable(blame, 'What has been trying it'));
      }
      body.appendChild(winRowsTable(d.rows || [], 'peek-win'));
    });
}
</script>
<script nonce="<?= h($nonce) ?>">
'use strict';
/* ==========================================================================
   Traffic: what crossed the firewall, out of its own log
   --------------------------------------------------------------------------
   Four pages over one window. The overview is counted ahead of time, so it
   costs the same whatever the firewall wrote; the three lists are the rows
   themselves. Nothing on any of them is judged and no button here bans
   anybody - the address popup this opens is where that is done.
   ========================================================================== */
var TRAFFIC = null;           /* the last overview answer */
var TPAGE = 'over';           /* which of the four pages is up */
var TLIST = {page: 0};        /* where the list is */
var TPICKS = {};              /* the stretch of time a bar of the chart has set */
var TASKED = 0;

/* What each verdict is called, and the colour it is drawn in everywhere on
   this page: the cards, the chart, the bars and the tags. */
var T_VERDICTS = {
  allow: {words: 'let through', tone: 'ok', fill: 'var(--ok)',
          says: 'The firewall let this session through. How it ended - closed, reset by '
            + 'one side, timed out - is what its own log said, and it is in the popup.'},
  deny: {words: 'refused', tone: 'crit', fill: 'var(--crit)',
         says: 'A policy refused it. On the firewall’s own address this is usually '
           + 'the internet knocking on a port that is not open.'},
  block: {words: 'blocked', tone: 'warn', fill: 'var(--warn)',
          says: 'The web filter (or another inspection) blocked it although a policy '
            + 'would have let the session through.'},
