/* FortiOS writes a country by its name; the page draws a flag by its two
   letters. The names it uses that are not the ones in the table here. */
var FG_COUNTRY_ALIAS = {
  'united states': 'US', 'united kingdom': 'GB', 'czech republic': 'CZ', 'czechia': 'CZ',
  'russian federation': 'RU', 'korea, republic of': 'KR', 'republic of korea': 'KR',
  'iran, islamic republic of': 'IR', 'viet nam': 'VN', 'taiwan': 'TW',
  'netherlands': 'NL', 'moldova, republic of': 'MD', 'hong kong': 'HK',
  'european union': 'EU', 'reserved': '', 'n/a': ''
};
var FG_COUNTRY = null;
function fgCountryCode(name) {
  var said = String(name || '').trim().toLowerCase();
  if (!said) return '';
  /* Two letters are already a code: what this program's own database says,
     for a firewall that writes no country of its own. */
  if (/^[a-z]{2}$/.test(said) && COUNTRY_NAME[said.toUpperCase()]) return said.toUpperCase();
  if (said in FG_COUNTRY_ALIAS) return FG_COUNTRY_ALIAS[said];
  if (!FG_COUNTRY) {
    FG_COUNTRY = {};
    Object.keys(COUNTRY_NAME).forEach(function (cc) {
      var n = String(COUNTRY_NAME[cc]).toLowerCase().replace(/^the /, '');
      FG_COUNTRY[n] = cc;
    });
  }
  return FG_COUNTRY[said.replace(/^the /, '')] || '';
}

/** A country as the firewall wrote it, as a flag where there is one. */
function fgCountry(name, cc) {
  var code = cc || fgCountryCode(name);
  if (code) return countryBadge(code);
  if (!name) return countryBadge('');
  var box = el('span', 'cc muted', name !== 'Reserved' ? name : 'private');
  if (name === 'Reserved') {
    explain(box, 'The firewall puts this address in no country: it is a private or '
      + 'reserved range - one of your own.');
  }
  return box;
}

function tVerdictTag(v) {
  var one = T_VERDICTS[v] || T_VERDICTS.info;
  var tag = el('span', 'tag ' + one.tone, one.words);
  explain(tag, one.says);
  return tag;
}

/** A row's bar, split by what was done: green let through, red refused,
    and every other colour the numbers beside it are written in.

    The bar is as long as the row's total against the longest row; the
    pieces share it by their counts, and none is ever narrower than a few
    pixels. Until 1.10.164 each piece was its own width against the longest
    row with a floor of 0.6 %: a hundred let through beside a hundred
    thousand refused was a sliver of two pixels, rounded into nothing at the
    end of the bar, so a row whose numbers said green and red was drawn red
    alone - and the floors added up past the end of the bar and pushed the
    last colour out of it. */
function tSplitBar(by, top, order) {
  var bar = el('div', 'bar t-split');
  var total = T_ORDER.reduce(function (m, v) { return m + Number((by || {})[v] || 0); }, 0);
  if (!total) return bar;
  var fill = el('div', 't-split-fill');
  fill.style.width = Math.min(100, Math.max(1.5, 100 * total / (top || total))) + '%';
  (order || T_ORDER).forEach(function (v) {
    var n = Number((by || {})[v] || 0);
    if (!n) return;
    var piece = el('span');
    piece.style.flexGrow = String(n);
    piece.style.background = T_VERDICTS[v].fill;
    fill.appendChild(piece);
  });
  /* ...and wide enough to hold every colour it has, however short. */
  fill.style.minWidth = (fill.children.length * 5 - 1) + 'px';
  bar.appendChild(fill);
  return bar;
}

/** What the disk on the database page holds, in a sentence of its own for
    each case so that each is translated whole; the names in it are names.
    (1.10.170: the server on this machine is said so, and where its files
    are, rather than "the database itself is on isemon@127.0.0.1".) */
function diskHolds(disk) {
  var p = el('p', 'btnhelp');
  var key = disk.holds_key || (disk.holds ? '' : 'none');
  var srv = disk.server || {};
  function put(text) { p.appendChild(document.createTextNode(text)); }
  function name(text) { p.appendChild(el('span', 'mono', text || '')); }
  if (key === 'file') {
    put('That disk holds the database and the copies kept beside it.');
  } else if (key === 'server') {
    put('That disk holds the copies kept on this machine; the database itself is on ');
    name(disk.server_where); put('.');
  } else if (key === 'same') {
    put('That disk holds the database and the copies kept beside it. ');
    name(srv.engine); put(' keeps its files in '); name(srv.dir); put('.');
  } else if (key === 'other') {
    put('That disk holds the copies kept on this machine. The database is on this machine '
      + 'too, on a disk of its own: ');
    name(srv.engine); put(' keeps its files in '); name(srv.dir); put('.');
  } else if (key === 'unknown') {
    put('That disk holds the copies kept on this machine. The database server is on this '
      + 'machine too (');
    name(disk.server_where);
    put('), but it does not say where it keeps its files, so how long its disk will last '
      + 'is not known here.');
  } else if (disk.holds) {
    put('That disk holds ' + disk.holds + '.');
  }
  if ((key === 'same' || key === 'other') && srv.guessed) {
    put(' ');
    put('That is its usual folder: the server itself does not tell this program.');
  }
  return p;
}

/* ==========================================================================
   A time window chosen by its dates (1.10.152)
   --------------------------------------------------------------------------
   Every list that is searched over time - the refusals, the logins, the
   domain's events, the Traffic tab - has, beside "last hour" and the rest,
   "choose dates…". It opens a picker: a bar from the first record this
   machine holds to this moment with a handle at each end, the two moments
   written out to the minute, a handful of ready-made windows, and "until
   now", which keeps the end of the window at the moment of each search
   rather than the moment it was chosen - so a list refreshed an hour later
   has the hour in it. What is asked of the daemon is `from` and `to` (no
   `to` for "until now"), which every one of these lists already takes.
   ========================================================================== */
var WINDOWS = {};                        /* select id -> {from, to}; to 0 = now */
var WINDOW_FIRST = {'f-hours': 'failed', 'p-hours': 'passed', 'w-hours': 'win',
                    't-window': 'fw'};

/** What a list asks the daemon for its window: `hours=…`, `from=…&to=…`,
    or nothing for all of it. */
function windowArgs(id) {
  var sel = $(id);
  if (!sel) return '';
  var v = sel.value;
  if (v === 'custom' && WINDOWS[id]) {
    var w = WINDOWS[id];
    return 'from=' + Math.floor(w.from) + (w.to ? '&to=' + Math.floor(w.to) : '');
  }
  if (!v || v === '0' || v === 'custom' || v === 'pick') return '';
  return 'hours=' + encodeURIComponent(v);
}

/** How many hours the window spans, for what needs a number: a chart's
    axis, what the search box offers. */
function windowHours(id, fallback) {
  var sel = $(id);
  if (!sel) return fallback || 24;
  if (sel.value === 'custom' && WINDOWS[id]) {
    var w = WINDOWS[id];
    return Math.max(1, Math.ceil(((w.to || Date.now() / 1000) - w.from) / 3600));
  }
  var n = Number(sel.value);
  return isFinite(n) && sel.value !== '' ? n : (fallback || 24);
}

function windowWords(w) {
  var short = function (t) {
    var d = new Date(t * 1000);
    return pad2(d.getDate()) + '-' + pad2(d.getMonth() + 1) + ' ' + pad2(d.getHours()) + ':'
      + pad2(d.getMinutes());
  };
  return short(w.from) + ' → ' + (w.to ? short(w.to) : 'now');
}

/** Put a chosen window on its list's drop-down. */
function windowSet(id, w) {
  var sel = $(id);
  var opt = sel.querySelector('option[value="custom"]');
  if (w) {
    WINDOWS[id] = w;
    opt.textContent = windowWords(w);
    opt.hidden = false;
    sel.value = 'custom';
  } else {
    delete WINDOWS[id];
    opt.hidden = true;
  }
}

/* A <input type=datetime-local> speaks in local time, to the minute. */
function windowLocal(t) {
  var d = new Date(t * 1000);
  return d.getFullYear() + '-' + pad2(d.getMonth() + 1) + '-' + pad2(d.getDate()) + 'T'
    + pad2(d.getHours()) + ':' + pad2(d.getMinutes());
}
function windowFromLocal(text) {
  var t = Date.parse(text);
  return isFinite(t) ? t / 1000 : 0;
}

/** The picker. `done(w)` with the window chosen, or with null if somebody
    changed their mind. */
function windowPick(id, done) {
  var now = Date.now() / 1000;
  var had = WINDOWS[id] || {from: now - 24 * 3600, to: 0};
  var state = {from: had.from, to: had.to || now, live: !had.to, first: 0};
  var finished = false;
  var finish = function (w) {
    if (finished) return;
    finished = true;
    MODAL_CLOSE = null;
    done(w);
  };
  var parts = {};
  modal('Time window', function (body) {
    var intro = el('p', 'note', 'Look at exactly the stretch you want. Drag the two ends of '
      + 'the bar, type the moments, or take one of the ready-made windows. ');
    body.appendChild(intro);
    var span = el('div', 'tw-span');
    parts.firstSaid = el('span', 'muted', 'the first record here…');
    parts.nowSaid = el('span', 'muted', 'now');
    span.appendChild(parts.firstSaid);
    span.appendChild(parts.nowSaid);
    body.appendChild(span);
    /* Two range inputs laid over one bar: each handle is a real control,
       with the keyboard and a screen reader as well as the mouse. */
    var bar = el('div', 'tw-bar');
    parts.fill = el('div', 'tw-fill');
    bar.appendChild(parts.fill);
    parts.lo = el('input');
    parts.lo.type = 'range';
    parts.lo.className = 'tw-lo';
    parts.lo.setAttribute('aria-label', 'Since');
    parts.hi = el('input');
    parts.hi.type = 'range';
    parts.hi.className = 'tw-hi';
    parts.hi.setAttribute('aria-label', 'Until');
    bar.appendChild(parts.lo);
    bar.appendChild(parts.hi);
    body.appendChild(bar);
    var ends = el('div', 'tw-ends');
    var fromBox = el('label', 'tw-end');
    fromBox.appendChild(el('span', 'small muted', 'Since'));
    parts.from = el('input');
    parts.from.type = 'datetime-local';
    fromBox.appendChild(parts.from);
    ends.appendChild(fromBox);
    var toBox = el('label', 'tw-end');
    toBox.appendChild(el('span', 'small muted', 'Until'));
    parts.to = el('input');
    parts.to.type = 'datetime-local';
    toBox.appendChild(parts.to);
    ends.appendChild(toBox);
    var live = el('label', 'tw-live swrow');
    var sw = el('label', 'sw small');
    parts.live = el('input');
    parts.live.type = 'checkbox';
    sw.appendChild(parts.live);
    sw.appendChild(el('span', 'knob'));
    live.appendChild(sw);
    live.appendChild(el('span', 'swlbl', 'until now — the end moves on with every search'));
    ends.appendChild(live);
    body.appendChild(ends);
    var presets = el('div', 'tw-presets');
    var day0 = new Date(); day0.setHours(0, 0, 0, 0);
    var today = day0.getTime() / 1000;
    var month0 = new Date(day0.getFullYear(), day0.getMonth(), 1).getTime() / 1000;
    /* Midnights as the calendar has them, not 86 400 seconds back: across a
       change of the clocks those started at 23:00 or 01:00 (1.10.176). */
    function midnight(back) {
      return new Date(day0.getFullYear(), day0.getMonth(), day0.getDate() - back)
        .getTime() / 1000;
    }
    var week0 = midnight((day0.getDay() + 6) % 7);
    [['last hour', function () { return [now - 3600, 0]; }],
     ['today', function () { return [today, 0]; }],
     ['yesterday', function () { return [midnight(1), today]; }],
     ['this week', function () { return [week0, 0]; }],
     ['last 7 days', function () { return [now - 7 * 86400, 0]; }],
     ['this month', function () { return [month0, 0]; }],
     ['last 30 days', function () { return [now - 30 * 86400, 0]; }],
     ['everything', function () { return [state.first || now - 365 * 86400, 0]; }]]
      .forEach(function (one) {
        var b = el('button', 'chip', one[0]);
        b.type = 'button';
        b.onclick = function () {
          var got = one[1]();
          state.from = got[0];
          state.live = !got[1];
          state.to = got[1] || Date.now() / 1000;
          paint();
        };
        presets.appendChild(b);
      });
    body.appendChild(presets);
    parts.said = el('p', 'tw-said');
    body.appendChild(parts.said);
  }, [
    {words: 'Cancel', close: true},
    {words: 'Use this window', cls: 'primary', icon: 'check', go: function () {
      if (!(state.from > 0) || (!state.live && state.to <= state.from)) {
        parts.said.textContent = 'The end has to come after the start.';
        return;
      }
      var w = {from: Math.floor(state.from), to: state.live ? 0 : Math.floor(state.to)};
      finish(w);
      closeModal();
