  ], 'medium');
  MODAL_CLOSE = function () { finish(null); };

  var lowest = function () {
    return Math.min(state.first || state.from, state.from, Date.now() / 1000 - 3600);
  };
  function paint() {
    var top = Date.now() / 1000, bottom = lowest();
    if (state.live) state.to = top;
    var steps = 1000;
    var at = function (t) { return Math.round((t - bottom) / Math.max(1, top - bottom) * steps); };
    parts.lo.min = parts.hi.min = 0;
    parts.lo.max = parts.hi.max = steps;
    parts.lo.value = at(state.from);
    parts.hi.value = at(state.to);
    var a = Number(parts.lo.value) / steps * 100, b = Number(parts.hi.value) / steps * 100;
    /* Two handles on top of each other: the one that can still move goes
       on top. With both at the right end - "last hour" over a year of
       records - the "To" handle took every drag, and the window shrank to
       a minute and stopped following now. (1.10.155) */
    var close = Number(parts.hi.value) - Number(parts.lo.value) < 20;
    parts.lo.style.zIndex = close && Number(parts.lo.value) > steps / 2 ? '3' : '';
    parts.hi.style.zIndex = close && Number(parts.lo.value) <= steps / 2 ? '3' : '';
    parts.fill.style.left = a + '%';
    parts.fill.style.width = Math.max(0.5, b - a) + '%';
    parts.from.value = windowLocal(state.from);
    parts.to.value = windowLocal(state.to);
    parts.to.disabled = state.live;
    parts.live.checked = state.live;
    parts.firstSaid.textContent = state.first
      ? 'first record: ' + stamp(state.first) : 'the first record here…';
    parts.nowSaid.textContent = 'now: ' + stamp(top);
    parts.said.textContent = stamp(state.from) + ' → '
      + (state.live ? 'now, whenever the list is asked' : stamp(state.to))
      + ' · ' + span(Math.max(60, (state.live ? top : state.to) - state.from));
  }
  var fromBar = function (input) {
    var top = Date.now() / 1000, bottom = lowest();
    return bottom + Number(input.value) / Number(input.max) * (top - bottom);
  };
  parts.lo.oninput = function () {
    state.from = Math.min(fromBar(parts.lo), state.to - 60);
    paint();
