  parts.hi.oninput = function () {
    var t = fromBar(parts.hi);
    /* Pulled all the way to the right is "now", and stays now. */
    state.live = Number(parts.hi.value) >= Number(parts.hi.max);
    state.to = Math.max(t, state.from + 60);
