  };
  parts.from.onchange = function () {
    var t = windowFromLocal(parts.from.value);
    if (t) state.from = t;
    paint();
  };
  parts.to.onchange = function () {
    var t = windowFromLocal(parts.to.value);
    if (t) { state.to = t; state.live = false; }
    paint();
  };
