}

/** The drop-downs: "choose dates…" opens the picker, and what was chosen
    stands in the list as its own line. Whatever the drop-down already did
    when it changed, it still does - after the window is set. */
function windowInstall(id) {
  var sel = $(id);
  if (!sel || sel._windowed) return;
  sel._windowed = true;
  var before = sel.onchange;
  var was = sel.value;
  /* What it said before it was opened - something may have set it since. */
  var note = function () { if (sel.value !== 'pick') was = sel.value; };
  sel.addEventListener('focus', note);
  sel.addEventListener('mousedown', note);
  sel.onchange = function (e) {
    if (sel.value === 'pick') {
      sel.value = was;
      windowPick(id, function (w) {
        if (!w) { sel.value = was; return; }
        windowSet(id, w);
        was = 'custom';
        if (before) before.call(sel, e);
      });
      return;
    }
    if (sel.value !== 'custom') windowSet(id, null);
    was = sel.value;
    if (before) before.call(sel, e);
  };
}

function tHours() { return windowHours('t-window', 24); }
/* The Traffic tab's window as the daemon is asked for it. */
function tWindowArgs() { return windowArgs('t-window') || 'hours=24'; }

/* ---- the four pages --------------------------------------------------- */
function tShowPage(which) {
  TPAGE = which;
  Array.prototype.forEach.call(document.querySelectorAll('#t-pages button[data-page]'),
    function (b) {
      var on = b.dataset.page === which;
      b.classList.toggle('on', on);
      b.setAttribute('aria-selected', on ? 'true' : 'false');
      if (on) b.hidden = false;
      else if (b.dataset.page === 'all') b.hidden = true;
    });
  $('t-page-over').hidden = which !== 'over';
  $('t-page-list').hidden = which === 'over' || which === 'vpn' || which === 'router';
  $('t-page-vpn').hidden = which !== 'vpn';
  $('t-page-router').hidden = which !== 'router';
  if (TAB === 'traffic') writeHash();
  if (which === 'over') { loadTraffic(); tFitSoon(); return; }
  if (which === 'vpn') { window.scrollTo(0, 0); loadVpnNow(); return; }
  if (which === 'router') { window.scrollTo(0, 0); loadRouter(); return; }
  TLIST.page = 0;
  window.scrollTo(0, 0);
  tListShape();
  tFitSoon();
  loadTrafficRows();
}
Array.prototype.forEach.call(document.querySelectorAll('#t-pages button[data-page]'),
  function (b) { b.onclick = function () { tShowPage(b.dataset.page); }; });
$('t-window').onchange = function () {
  TLIST.page = 0;
  if (TPAGE === 'over') loadTraffic(); else { loadTraffic(true); loadTrafficRows(); }
};

/* ---- which firewall --------------------------------------------------- */
/* Every question the tab asks carries it, so that switching firewall
   switches everything at once: the cards, the chart, the three lists and
   what the search box offers. Empty is all of them. Remembered in this
   browser only, as a convenience. */
var TFW = '';
var TFWS = [];
try { TFW = localStorage.getItem('isemon-traffic-fw') || ''; } catch (e) { TFW = ''; }
function tFwArg() { return TFW ? '&fw=' + encodeURIComponent(TFW) : ''; }
function tFwPick(name) {
  if (name === TFW) return;
  TFW = name || '';
  try { localStorage.setItem('isemon-traffic-fw', TFW); } catch (e) { }
  TLIST.page = 0;
  TVPN_PAGE = {c: 0, t: 0};
  T_INSIDE = null;
  drawTFws(TFWS);
  if (TPAGE === 'over') loadTraffic(); else { loadTraffic(true); loadTrafficRows(); }
}
function drawTFws(list) {
  TFWS = list || [];
  var host = $('t-fws');
  if (!host) return;
  var names = TFWS.map(function (f) { return f.name; });
  /* One firewall is not a choice; and a remembered one that is no longer
     in the settings is no longer what anybody is looking at. */
  if (TFW && names.indexOf(TFW) < 0) {
    TFW = '';
    try { localStorage.setItem('isemon-traffic-fw', ''); } catch (e) { }
  }
  host.hidden = TFWS.length < 2;
  if (host.hidden) { clear(host); return; }
  var key = names.join('\n') + '|' + TFW;
  if (host._drew === key) return;
  host._drew = key;
  clear(host);
  var icon = el('span', 't-fws-icon');
  icon.innerHTML = iconMarkup('wall', 15);
  host.appendChild(icon);
  var seg = function (name, words, says) {
    var b = el('button', name === TFW ? 'on' : '', words);
    b.type = 'button';
    b.setAttribute('role', 'radio');
    b.setAttribute('aria-checked', name === TFW ? 'true' : 'false');
    explain(b, says);
    b.onclick = function () { tFwPick(name); };
    host.appendChild(b);
  };
  seg('', 'All firewalls', 'Every firewall\u2019s lines together: the cards and the chart add '
    + 'them up, and each line in the lists says which firewall wrote it.');
  TFWS.forEach(function (f) {
    seg(f.name, f.name, 'Only <b>' + richText(f.name) + '</b> (' + richText(f.words || f.type)
      + '): the cards, the chart, the lists and the search, all of them for this one '
      + 'firewall.');
  });
}


/* ==========================================================================
   More columns, out of sight until asked for (1.10.156)
   --------------------------------------------------------------------------
   Every list can show more of what its records hold than it does: each
   field it does not show already is a column it offers, kept out of sight
   until somebody switches it on - right button on a heading, with "Edit
   the columns" on under their name - and then laid out like any other. As
   it comes, every table is exactly as it was.

   [heading, field, how it is said]. A field whose heading a table already
   has is not offered twice.
   ========================================================================== */
/* [heading, field, how it is drawn] - the kinds are those of `optCell`,
   which draws each the way the rest of the page draws it: a country with
   its flag, an address with its name, a moment as every other moment. */
var OPT_AUTH = [
  ['Address', 'ip', 'addr'], ['Name', 'username', 'name'], ['Country', 'country', 'cc'],
  ['Door', 'kind', 'door'], ['Device', 'device'], ['Device address', 'nad', 'addr'],
  ['Node', 'server'], ['Tunnel', 'tunnel'], ['Access service', 'service'],
  ['Protocol', 'protocol'], ['Failure code', 'code', 'mono'],
  ['Why it failed', 'reason', 'words'], ['MAC address', 'mac', 'mono'],
  ['Port', 'port', 'mono'], ['Network', 'ssid'], ['The machine', 'machine'],
  ['Session', 'session', 'mono']];
var OPT_PASSED = OPT_AUTH.filter(function (o) {
  return o[1] !== 'code' && o[1] !== 'reason';
}).concat([['Profile', 'profile'], ['Policy set', 'policy'], ['Groups', 'groups'],
           ['Downloadable ACL', 'acl'], ['TACACS+ step', 'subtype'], ['Verdict', 'verdict']]);
var OPT_PAST = [['Address', 'ip', 'addr'], ['Country', 'country', 'cc'],
                ['Began', 'ts', 'time'], ['Ended', 'ended', 'time'], ['Why', 'why', 'words'],
                ['How it ended', 'how', 'words'], ['By', 'by'], ['By itself', 'auto', 'yes']];
var OPT_EVENTS = [['Kind', 'kind'], ['Level', 'level', 'level'], ['Who', 'who'],
                  ['Number', 'id', 'num']];
var OPT_WIN = [['Event ID', 'event', 'mono'], ['Kind', 'kind'], ['Account', 'account', 'name'],
               ['Domain', 'domain'], ['A machine account', 'is_machine', 'yes'],
               ['Asked by', 'by_who', 'name'], ['Machine', 'machine', 'mono'],
               ['Address', 'ip', 'addr'], ['Logon type', 'logon_type', 'mono'],
               ['Program', 'process', 'mono'], ['Service', 'service'],
               ['Object', 'object', 'mono'], ['What it said', 'said', 'words'],
               ['Mark', 'mark'], ['Controller', 'server'], ['Record', 'ident', 'mono']];

/* What a field of a record is called when it is offered as a column of a
   list that does not already show it - only fields with a name here are
   offered at all. [heading, how it is said]. */
var OPT_WORDS = {
  ip: ['Address', 'addr'], country: ['Country', 'cc'], username: ['Name', 'name'],
  device: ['Device'], server: ['Node'], kind: ['Door', 'door'],
  reason: ['Why it failed', 'words'], tunnel: ['Tunnel'], mac: ['MAC address', 'mono'],
  port: ['Port', 'mono'], ssid: ['Network'], machine: ['The machine'],
  since: ['Banned since', 'time'], until: ['Banned until', 'time'], ts: ['When', 'time'],
  first: ['First seen', 'time'], last: ['Last seen', 'time'], ended: ['Ended', 'time'],
  why: ['Why', 'words'], how: ['How it ended', 'words'],
  hits: ['Attempts while banned', 'num'], by: ['By'],
  auto: ['By itself', 'yes'], tries: ['Attempts', 'num'], users: ['Names', 'num'],
  feed: ['Public list'],
  note: ['Note'], role: ['Role'], made: ['Made', 'time'], made_by: ['Made by'],
  last_in: ['Last signed in', 'time'], last_from: ['Last signed in from'],
  disabled: ['Switched off', 'yes'], realm: ['Institution'], account: ['Account', 'name'],
  domain: ['Domain'], event: ['Event ID', 'mono'], process: ['Program', 'mono'],
  service: ['Service'], protocol: ['Protocol'], profile: ['Profile'], policy: ['Policy'],
  groups: ['Groups', 'words'], session: ['Session', 'mono'], nad: ['Device address', 'addr'],
  code: ['Failure code', 'mono'], level: ['Level', 'level'], who: ['Who'],
  detail: ['What', 'words'], name: ['Name', 'name'], n: ['How many', 'num'],
  count: ['How many', 'num'], total: ['How many', 'num']
};
function optFieldsOf(rows) {
  var seen = {}, out = [];
  (rows || []).slice(0, 50).forEach(function (r) {
    if (!r || typeof r !== 'object' || Array.isArray(r)) return;
    Object.keys(r).forEach(function (k) {
      if (seen[k] || !OPT_WORDS[k]) return;
      var v = r[k];
      if (v !== null && typeof v === 'object') return;
      seen[k] = 1;
      out.push([OPT_WORDS[k][0], k, OPT_WORDS[k][1]]);
    });
  });
  return out;
}

/** One value as a cell, drawn as the rest of the page draws that kind of
    thing, so that a column switched on looks like every column beside it.
    Values are never translated; words this page writes (a door, yes and
    no, a verdict) are. */
function optCell(kind, v, r) {
  var none = v === null || v === undefined || v === '';
  var td;
  if (kind === 'time') {
    td = stampCell(Number(v) || 0);
  } else if (none) {
    td = el('td', 'muted', '\u2013');
  } else if (kind === 'cc') {
    td = el('td', 'cccell');
    td.appendChild(countryBadge(v));
  } else if (kind === 'fgcc') {
    td = el('td', 'cccell');
    td.appendChild(fgCountry(String(v)));
  } else if (kind === 'addr') {
    td = el('td', 'addrcell');
    td.appendChild(addrLine(String(v), '', r && r.ts));
  } else if (kind === 'name') {
    td = nameCell(String(v));
    if (td.firstChild && !(r && r.is_machine)) whoIsIt(td, String(v).split('@')[0], r && r.realm);
  } else if (kind === 'door') {
    td = el('td', '', doorWords(String(v)));
  } else if (kind === 'yes') {
    var yes = Number(v) || v === true || v === 'yes';
    td = el('td');
    td.appendChild(el('span', 'tag ' + (yes ? 'ok' : 'dim'), yes ? 'yes' : 'no'));
  } else if (kind === 'level') {
    td = el('td');
    td.appendChild(el('span', 'tag ' + (v === 'warn' ? 'warn' : (v === 'error' ? 'crit'
                                                                 : 'dim')), String(v)));
  } else if (kind === 'verdict') {
    td = el('td');
    td.appendChild(tVerdictTag(String(v)));
  } else if (kind === 'num') {
    td = noI18n(el('td', 'num', typeof v === 'number' ? num(v) : String(v)));
  } else if (kind === 'bytes') {
    td = el('td', 'num', bytes(Number(v) || 0));
  } else if (kind === 'span') {
    td = el('td', 'num', Number(v) ? span(Number(v)) : '\u2013');
  } else if (kind === 'port') {
    td = noI18n(el('td', 'num mono', String(v)));
  } else if (kind === 'mono') {
    td = noI18n(el('td', 'mono', String(v)));
  } else if (kind === 'words') {
    td = noI18n(el('td', 'dim', String(v)));
  } else {
    td = noI18n(el('td', '', String(v)));
  }
  return td;
}

/** The columns a table offers beyond its own, with their headings put on
    the end of its heading row, out of sight. Asked once a draw; the ones
    already there (a heading row written into the page) are not put twice. */
function optHeads(table, defs) {
  var head = colsHead(table);
  if (!head) return [];
  var have = {};
  Array.prototype.forEach.call(head.cells, function (th) {
    if (th.hasAttribute('data-cols-optional')) return;
    have[String(srcText(th) || '').replace(/[⇅▲▼]/g, '').trim()
      .toLowerCase()] = 1;
  });
  var want = defs.filter(function (d) { return !have[d[0].toLowerCase()]; });
  var there = {};
  Array.prototype.forEach.call(head.querySelectorAll('th[data-cols-optional][data-opt]'),
    function (th) { there[th.dataset.opt] = 1; });
  want.forEach(function (d) {
    if (there[d[1]]) return;
    var th = el('th', 'col-hidden', d[0]);
    th.setAttribute('data-cols-optional', '1');
    th.dataset.opt = d[1];
    head.appendChild(th);
  });
  return want;
}

/** ...and a cell for each on every row drawn with its record. */
function optCells(table, defs) {
  if (!defs.length) return;
  Array.prototype.forEach.call(table.tBodies, function (body) {
    Array.prototype.forEach.call(body.rows, function (tr) {
      if (!tr._rec || tr._opt) return;
      tr._opt = true;
      defs.forEach(function (d) {
        var td = optCell(d[2], tr._rec[d[1]], tr._rec);
        td.classList.add('col-hidden');
        td.dataset.opt = d[1];
        tr.appendChild(td);
      });
    });
  });
  /* Laid out at once where it is on the page already; one still being put
     together is laid out when it is put there. */
  if (table.isConnected) colsApply(table);
}
function optColumns(table, defs) { optCells(table, optHeads(table, defs)); }

/* ---- the overview ----------------------------------------------------- */
var T_PENDING = 0;

/** A card saying the daemon is working something out behind the page -
    the same card on the Traffic page and on the Domain page (1.10.154).
    `what` is {title, lines: [...], part: 0..1 or null}; null takes it away.
    Each line is its own paragraph, so that each is read (and translated)
    by itself. */
function bgCard(id, before, what) {
  var box = $(id);
  if (!what) { if (box) box.remove(); return null; }
  var at = $(before);
  if (!at) return null;
  if (!box) {
    box = el('div', 'card bg-card');
    box.id = id;
    box.setAttribute('role', 'status');
    at.parentNode.insertBefore(box, at);
  }
  clear(box);
  box.appendChild(el('div', 'spin-line', what.title));
  if (what.part !== undefined && what.part !== null) {
    var bar = el('div', 'bg-bar');
    var fill = el('span');
    fill.style.width = Math.max(2, Math.round(Math.min(1, what.part) * 100)) + '%';
    bar.appendChild(fill);
    box.appendChild(bar);
  }
  (what.lines || []).forEach(function (line) {
    if (line) box.appendChild(el('p', 'dim', line));
  });
  return box;
}

/** "Being worked out" over the cards, while the daemon works out a window
    for the first time; nothing at all when `d` is null. */
function tPending(d) {
  if (!d) { bgCard('t-pending', 't-cards', null); return; }
  var p = d.pending || {};
  bgCard('t-pending', 't-cards', {
    title: 'Working out the overview of ' + tWindowWords(d.hours)
      + (d.fw ? ' for ' + d.fw : '') + '\u2026',
    lines: [p.busy && p.began ? 'Started ' + ago(p.began) + '.'
              : (p.other ? 'Next in line, after the one being worked out now.' : ''),
            'It is worked out behind the daemon and kept, so this wait is only the first '
              + 'time; from then on the page opens at once and says how old what it shows is.',
            p.took ? 'The last one took ' + tTook(p.took) + '.' : '',
            'This page fills in by itself.']});
}

function tWindowWords(hours) {
  return {1: 'the last hour', 6: 'the last 6 hours', 24: 'the last 24 hours',
          72: 'the last 3 days', 168: 'the last week'}[Number(hours)]
    || 'the last ' + Number(hours || 24) + ' hours';
}

function tTook(seconds) {
  seconds = Number(seconds || 0);
  if (seconds < 60) return seconds.toFixed(seconds < 10 ? 1 : 0) + ' s';
  if (seconds < 3600) return Math.floor(seconds / 60) + ' min ' + Math.round(seconds % 60) + ' s';
  return Math.floor(seconds / 3600) + ' h ' + Math.round((seconds % 3600) / 60) + ' min';
}

var T_ASKING = 0;
var T_HELD_ASK = '';
function loadTraffic(quiet) {
  /* The page's own refresh does not start another while one is still out:
     on a busy firewall every tick is "something moved", and each new ask
     threw the one before away - a slow answer was never drawn at all.
     Somebody choosing something always asks. (1.10.155) */
  if (quiet && T_ASKING && Date.now() - T_ASKING < 60000) return;
  var mine = ++TASKED;
  T_ASKING = Date.now();
  /* A page of lines needs the numbers on the page buttons and nothing else
     of the overview. (1.10.168) */
  var countsOnly = TPAGE !== 'over';
  /* The overview already held, named, on a quiet refresh: the daemon then
     answers "the same" with only what moves (1.10.192). */
  var held = quiet && TRAFFIC && TRAFFIC.ready && TRAFFIC.ready.at
    && ('fw&' + tWindowArgs() + tFwArg()) === T_HELD_ASK ? TRAFFIC.ready.at : 0;
  var ask = 'fw&' + tWindowArgs() + tFwArg();
  api('fw&' + tWindowArgs() + tFwArg() + (countsOnly ? '&counts=1' : '')
      + (held ? '&ready_at=' + held : ''), undefined,
      quiet ? undefined : {lane: 'fw-overview'}).then(function (d) {
    if (mine === TASKED) T_ASKING = 0;
    if (mine !== TASKED) return;
    drawTFws(d.firewalls || []);
    if (d.same && TRAFFIC) {
      /* Nothing worked out has changed: the line under the chart is put
         right, and everything else stays as it is drawn. */
      TRAFFIC.newest = d.newest;
      TRAFFIC.ready = d.ready;
      TRAFFIC.firewalls = d.firewalls || TRAFFIC.firewalls;
      if (TPAGE === 'over') tChartNote(TRAFFIC);
      else if (TPAGE === 'vpn') loadVpnNow(true);
      else if (TPAGE === 'router') loadRouter(true);
      else loadTrafficRows(true);
      return;
    }
    /* The daemon says which firewall it answered for; one it does not know
       is answered for all of them, and the page follows. */
    if ((d.fw || '') !== TFW) {
      TFW = d.fw || '';
      drawTFws(d.firewalls || []);
      if (TPAGE !== 'over') loadTrafficRows();
    }
    /* Nothing worked out for this window yet - the first look after an
       upgrade, or at a window nobody has used: the daemon is on it, and the
       page says so and looks again in a moment rather than drawing zeros
       (1.10.154). What was drawn before stays. */
    if (d.pending) {
      tPending(d);
      /* What is still drawn is another window's or another firewall's:
         greyed, so it is not read as this one's. (1.10.155) */
      var other = !TRAFFIC || (TRAFFIC.fw || '') !== (d.fw || '')
        || Number(TRAFFIC.hours) !== Number(d.hours);
      $('t-page-over').classList.toggle('t-stale', other);
      clearTimeout(T_PENDING);
      T_PENDING = setTimeout(function () {
        /* ...not while nobody is looking (1.10.176); the tick asks again
           when the window is looked at. */
        if (TAB === 'traffic' && !document.hidden) loadTraffic(true);
        else if (TAB === 'traffic') RELOAD_WHEN_SEEN = true;
      }, 4000);
      return;
    }
    tPending(null);
    $('t-page-over').classList.remove('t-stale');
    /* The overview kept is the whole one: an answer of counts alone only
       puts the numbers right. Gone back to the overview meanwhile, it asks
       for the whole of it. */
    if (!d.counts_only) { TRAFFIC = d; T_HELD_ASK = ask; }
    tCounts(d);
    if (TPAGE === 'over') {
      if (d.counts_only) loadTraffic(false); else drawTraffic(d);
    }
    else if (TPAGE === 'vpn') {
      if (quiet) loadVpnNow(true);
    } else if (TPAGE === 'router') {
      if (quiet) loadRouter(true);
    } else if (quiet) loadTrafficRows(true);
  }).catch(function (e) {
    if (mine === TASKED) T_ASKING = 0;
    if (!quiet) oops(e);
  });
}

/** Whether a firewall writes the bytes of a session as one figure for both
    ways (FTD), rather than out and back apart (FortiGate). */
function tBothWays(fw) {
  var one = (TFWS || []).filter(function (f) { return f.name === fw; })[0];
  return !!(one && one.type === 'ftd');
}
/** ...and whether everything in view is such a firewall. */
function tAllBothWays(d) {
  var list = (d && d.firewalls) || TFWS || [];
  if (d && d.fw) return tBothWays(d.fw);
  return list.length > 0 && list.every(function (f) { return f.type === 'ftd'; });
}

function tTotal(d, v, what) {
  return Number((((d || {}).totals || {})[v] || {})[what || 'n'] || 0);
}

/** The numbers on the three list buttons and on the tab itself. */
function tCounts(d) {
  var refused = tTotal(d, 'deny') + tTotal(d, 'block');
  var events = (((d.tops || {}).kind || {}).busiest || []).filter(function (r) {
    return r.val.indexOf('event') === 0;
  }).reduce(function (a, r) { return a + r.n; }, 0);
  var web = (((d.tops || {}).kind || {}).busiest || []).filter(function (r) {
    return r.val.indexOf('utm') === 0;
  }).reduce(function (a, r) { return a + r.n; }, 0);
  /* By page, out of the counted buckets of the page each line is on; on a
     window counted before there were pages, the old way. */
  var areas = {};
  (((d.tops || {}).area || {}).busiest || []).forEach(function (r) { areas[r.val] = r.n; });
  var anyArea = Object.keys(areas).length > 0;
  var all = T_ORDER.reduce(function (a, v) { return a + tTotal(d, v); }, 0);
  var sessions = anyArea ? (areas.session || 0) : all;
  $('t-n-list').textContent = num(sessions);
  $('t-n-web').textContent = anyArea ? (areas.web ? num(areas.web) : '') : (web ? num(web) : '');
  $('t-n-events').textContent = events ? num(events) : '';
  $('t-n-all').textContent = all ? num(all) : '';
  [['threat', 'threat'], ['cvpn', 'client-vpn'], ['s2s', 's2s-vpn'], ['admin', 'admin'],
   ['system', 'system'], ['other', 'other'], ['nat', 'nat'], ['dhcp', 'dhcp']].forEach(function (one) {
    var n = areas[one[1]] || 0;
    var span = $('t-n-' + one[0]);
    if (span) span.textContent = n ? num(n) : '';
  });
  /* Threats only where a firewall sends any: a FortiGate without its
     security profiles logging, or an FTD whose management centre sends
     nothing, has no page of them to offer. */
  var tb = document.querySelector('#t-pages button[data-page="threat"]');
  if (tb) tb.hidden = !(areas.threat || TPAGE === 'threat');
  /* Connected now: only where a firewall writes its VPN at all. */
  var vn = d.vpn_now || {};
  var vb = document.querySelector('#t-pages button[data-page="vpn"]');
  if (vb) {
    vb.hidden = !(vn.clients || vn.tunnels || areas['client-vpn'] || areas['s2s-vpn']
                  || TPAGE === 'vpn');
    $('t-n-vpn').textContent = (vn.clients || vn.tunnels)
      ? num(vn.clients || 0) + ' \u00b7 ' + num(vn.tunnels || 0) : '';
    explain(vb, num(vn.clients || 0) + ' person(s) on the remote-access VPN and '
      + num(vn.tunnels || 0) + ' site-to-site tunnel(s) up, as the lines kept say.');
  }
  /* The router itself: only where a MikroTik is read through its API or
     over ssh (1.10.211). */
  tRouterButton();
  /* Other only where something fit no page; every line only while open. */
  var ob = document.querySelector('#t-pages button[data-page="other"]');
  if (ob) ob.hidden = !(areas.other || TPAGE === 'other');
  /* The NAT rules and the DHCP leases: only where a firewall writes them -
     and the NAT page wherever a session was translated, a FortiGate's and an
     FTD's too, counted by its kind of translation (1.10.210). */
  var natted = (((d.tops || {}).natted || {}).busiest || []).reduce(function (a, r) {
    return a + r.n; }, 0);
  if (natted) $('t-n-nat').textContent = num(natted);
  ['nat', 'dhcp'].forEach(function (one) {
    var b = document.querySelector('#t-pages button[data-page="' + one + '"]');
    if (b) b.hidden = !(areas[one] || (one === 'nat' && natted) || TPAGE === one);
  });
  var ab = document.querySelector('#t-pages button[data-page="all"]');
  if (ab) ab.hidden = TPAGE !== 'all';
  var tab = $('tabn-traffic');
  if (tab) {
    tab.textContent = refused ? num(refused) : '';
    tab.classList.toggle('hot', tTotal(d, 'fail') > 0);
  }
}

function tCard(cls, label, value, sub, says, go) {
  var card = el('div', 'card metric ' + cls);
  card.appendChild(el('div', 'label', label));
  var v = el('div', 'value');
  if (value && value.nodeType) v.appendChild(value); else v.textContent = value;
  card.appendChild(v);
  card.appendChild(el('div', 'sub', sub));
  if (go) opensWith(card, says, go); else explain(card, says);
  return card;
}

function drawTraffic(d) {
  var host = $('t-cards');
  clear(host);
  var allowed = tTotal(d, 'allow'), denied = tTotal(d, 'deny'), blocked = tTotal(d, 'block');
  var failed = tTotal(d, 'fail');
  var sent = tTotal(d, 'allow', 'sent'), rcvd = tTotal(d, 'allow', 'rcvd');
  var srcs = ((d.tops || {}).src || {}).values || 0;
  var webLines = (((d.tops || {}).kind || {}).busiest || []).filter(function (r) {
    return r.val === 'utm/webfilter';
  }).reduce(function (a, r) { return a + r.n; }, 0);
  var refusedFrom = (((d.tops || {}).src || {}).refused || []).length;
  host.appendChild(tCard('ok', 'Let through', num(allowed),
    srcs ? num(srcs) + ' address(es) behind them' : 'nothing yet',
    'Every session the firewall let through in the window, however it ended. Press for '
      + 'the list.', function () { tOpen('verdict:allow'); }));
  var bytesVal = el('span', '', bytes(sent + rcvd));
  var both = tAllBothWays(d);
  host.appendChild(tCard('info', 'Carried', bytesVal,
    both ? 'both ways together' : '↑ ' + bytes(sent) + ' out · ↓ ' + bytes(rcvd) + ' in',
    both ? 'How much the sessions it let through carried. FTD writes one figure for a '
      + 'session, both ways together, so this is not split into out and in.'
      : 'How much the sessions it let through carried, both ways: out is what the side that '
      + 'started each session sent, in is what came back.'
      + ((d.firewalls || []).some(function (f) { return f.type === 'ftd'; })
         ? ' An FTD writes one figure for both ways; its sessions are counted under out.'
         : ''), null));
  host.appendChild(tCard(denied ? 'crit' : 'ok', 'Refused', num(denied),
    refusedFrom ? 'the busiest ' + refusedFrom + ' source(s) below' : 'nothing refused',
    'Sessions a policy refused - on the firewall’s own address this is mostly the '
      + 'internet knocking on ports that are not open. Press for the list.',
    function () { tOpen('verdict:deny'); }));
  if (both) {
    /* An FTD has no web filter in its syslog: what it blocks beyond its
       policies is protocol inspection, and the management centre's file
       and intrusion policies where those are sent. */
    host.appendChild(tCard(blocked ? 'warn' : 'ok', 'Inspected and blocked', num(blocked),
      'protocol inspection, files, intrusions',
      'What inspection stopped although a policy let it through: a protocol the inspection '
        + 'engine refused, and - where the management centre sends them - the file and '
        + 'intrusion policies. Press for the list.',
      function () { tOpen('verdict:block', 'list'); }));
  } else {
    host.appendChild(tCard(blocked ? 'warn' : 'ok', 'Web blocked', num(blocked),
      webLines ? 'of ' + num(webLines) + ' web filter line(s)' : 'no web filter lines',
      'What the web filter blocked although a policy would have let it through. Press for '
        + 'the list.', function () { tOpen('verdict:block', 'web'); }));
  }
  host.appendChild(tCard(failed ? 'crit' : 'ok', 'Failed sign-ins', num(failed),
    'to the VPN and to the firewall',
    'Sign-ins to the firewall’s VPN or to the firewall itself that did not work. '
      + 'Press for them.', function () { tOpen('verdict:fail', 'events'); }));
  var vn = d.vpn_now;
  if (vn && (vn.clients || vn.tunnels)) {
    host.appendChild(tCard('info', 'Connected now', num(vn.clients || 0),
      num(vn.tunnels || 0) + ' site-to-site tunnel(s) up',
      'People on the remote-access VPN at the moment, and the site-to-site tunnels up, as the '
        + 'lines kept say. Press for them.', function () { tShowPage('vpn'); }));
  }
  tChartNote(d);
  tStored(d);
  tRouterCard();
  drawTrafficChart(d);
  drawTrafficTops(d);
  explainWhatWasDrawn($('t-page-over'));
}

/* ---- the router itself (1.10.211) -------------------------------------
   A MikroTik read through its API or over ssh: what it says about itself,
   as it stood at the last look. The page and its button are there only
   while one is read; without it the tab is the lines, as it always was. */
var TROUTERS = [];
var TROUTER = null;
function tRouterButton() {
  var b = document.querySelector('#t-pages button[data-page="router"]');
  if (!b) return;
  /* Asked at most every quarter of a minute: the counts are redrawn far
     more often than a router is switched on. */
  var show = function () {
    var mine = TFW ? TROUTERS.filter(function (n) { return n === TFW; }) : TROUTERS;
    b.hidden = !(mine.length || TPAGE === 'router');
    $('t-n-router').textContent = mine.length > 1 ? String(mine.length) : '';
  };
  if (Date.now() - (tRouterButton.at || 0) < 15000) { show(); return; }
  tRouterButton.at = Date.now();
  api('fw-router').then(function (d) {
    var had = TROUTERS.join(',');
    TROUTERS = d.routers || [];
    if (had !== TROUTERS.join(',')) {
      tRouterCard();
      /* Opened straight on the Router page, before the routers were known
         (1.10.217): drawn again now that they are. */
      if (TPAGE === 'router') loadRouter(true);
    }
    var mine = TFW ? TROUTERS.filter(function (n) { return n === TFW; }) : TROUTERS;
    b.hidden = !(mine.length || TPAGE === 'router');
    $('t-n-router').textContent = mine.length > 1 ? String(mine.length) : '';
  }).catch(function () { b.hidden = TPAGE !== 'router'; });
}
var TR_ASKED = 0;
var TR_AT = 0;
var TR_KEY = '';
function loadRouter(quiet) {
  var names = TFW ? [TFW] : TROUTERS;
  /* Not asked again within a quarter of a minute for the same routers
     (1.10.217): the router is read every half minute, and every poll of the
     tab asked it of each of them. */
  var key = names.join(',');
  if (quiet && TROUTER && key === TR_KEY && Date.now() - TR_AT < 15000) return;
  if (!quiet) {
    clear($('tr-body'));
    $('tr-body').appendChild(el('p', 'center muted', 'Reading\u2026'));
  }
  if (!names.length) {
    /* Not known yet which are read: asked, and drawn when they are. */
    tRouterButton.at = 0;
    tRouterButton();
  }
  var mine = ++TR_ASKED;
  var ask = names.length ? names : [''];
  Promise.all(ask.map(function (n) {
    return n ? api('fw-router&fw=' + encodeURIComponent(n)).then(function (d) {
      return d.router; }).catch(function () { return null; }) : Promise.resolve(null);
  })).then(function (got) {
    if (mine !== TR_ASKED) return;      /* a later question was asked */
    TROUTER = got.filter(function (r) { return r; });
    TR_AT = Date.now();
    TR_KEY = key;
    drawRouter();
  });
}
/* Narrowed as somebody types - a quarter of a second after the last key
   (1.10.217), not the whole page drawn again at every one. */
$('tr-q').oninput = function () {
  clearTimeout(window._trTyping);
  window._trTyping = setTimeout(drawRouter, 250);
};

function trBits(n) {
  n = Number(n) || 0;
  if (n >= 1e9) return (n / 1e9).toFixed(2) + ' Gb/s';
  if (n >= 1e6) return (n / 1e6).toFixed(1) + ' Mb/s';
  if (n >= 1e3) return (n / 1e3).toFixed(0) + ' kb/s';
  return Math.round(n) + ' b/s';
}
function trYes(v) { return v === 'true' || v === true; }
function trMatches(row, q) {
  if (!q) return true;
  return Object.keys(row).some(function (k) {
    return String(row[k] === undefined || row[k] === null ? '' : row[k]).toLowerCase()
      .indexOf(q) >= 0;
  });
}
/** One table of the router's: its heading, how many, and its rows. */
function trSection(host, title, says, rows, heads, cell, leftOut) {
  var q = $('tr-q').value.trim().toLowerCase();
  var shown = (rows || []).filter(function (r) { return trMatches(r, q); });
  var card = el('div', 'card full');
  card.style.marginTop = '14px';
  var h = el('h2', '', title);
  h.appendChild(el('span', 'right', num(shown.length) + (q ? ' of ' + num((rows || []).length)
    : '') + (leftOut ? ' · ' + num(leftOut) + ' not read' : '')));
  card.appendChild(h);
  card.appendChild(el('p', 'note', says));
  if (!shown.length) {
    card.appendChild(el('p', 'center muted', (rows || []).length ? 'Nothing matches'
      : (leftOut ? 'More than the router is asked for at a time, so not read.'
         : 'Nothing.')));
  } else {
    card.appendChild(listTable(heads, shown.slice(0, 500), cell));
    if (shown.length > 500) {
      card.appendChild(el('p', 'muted small', 'The first 500 — narrow it above for the rest.'));
    }
  }
  host.appendChild(card);
}
function trAddr(text) {
  var ip = String(text || '').split('/')[0];
  var box = el('span');
  if (!ip) { box.textContent = '–'; return box; }
  box.appendChild(tAddress(ip, '', '', '', true));
  if (String(text).indexOf('/') >= 0) {
    box.appendChild(el('span', 'muted mono', '/' + String(text).split('/')[1]));
  }
  return box;
}
function trTd(text, cls) { return noI18n(el('td', cls || '', text === undefined || text === null
  || text === '' ? '–' : String(text))); }

function drawRouter() {
  var host = $('tr-body');
  clear(host);
  var list = TROUTER || [];
  if (!list.length) {
    host.appendChild(el('p', 'center muted', 'No router is read through its API or over ssh '
      + 'right now. Settings → The firewall log switches it on for a MikroTik.'));
    $('tr-said').textContent = '';
    return;
  }
  $('tr-said').textContent = list.length === 1 && list[0].at ? 'as it was ' + ago(list[0].at) : '';
  list.forEach(function (r) { drawOneRouter(host, r); });
  explainWhatWasDrawn(host);
}

function is_ip_like(text) {
  return /^[0-9.]+$|:/.test(String(text || '').trim());
}

/** Who carried most since the last look: by source, by where it went, by
    service, as rates (1.10.214). */
function trBusiest(host, r) {
  var b = r.talkers;
  if (!b || !b.span) return;
  var card = el('div', 'card full');
  card.style.marginTop = '14px';
  var h = el('h2', '', 'Busiest now');
  h.appendChild(el('span', 'right', 'over the last ' + Math.round(b.span) + ' s'));
  card.appendChild(h);
  card.appendChild(el('p', 'note', 'What each source, each place it went and each service '
    + 'carried between the last two looks at its connection table, as rates. Press one for '
    + 'its sessions.'));
  var grid = el('div', 'grid top');
  [['src', 'Sources', 'srcip'], ['dst', 'Where it went', 'dstip'], ['service', 'Services',
    'service']].forEach(function (k) {
    var box = el('div');
    box.appendChild(el('h3', 'muted small', k[1]));
    var rows = b[k[0]] || [];
    if (!rows.length) {
      box.appendChild(el('p', 'muted small', 'Nothing carried.'));
    } else {
      box.appendChild(listTable(['', {words: 'Out', cls: 'num'}, {words: 'In', cls: 'num'},
        {words: 'Connections', cls: 'num'}], rows, function (x) {
        var tr = el('tr', 'tappable');
        var c = el('td');
        c.appendChild(k[0] === 'service' ? noI18n(el('span', 'mono', x.key))
          : trAddr(x.key));
        tr.appendChild(c);
        tr.appendChild(el('td', 'num', trBits(x.out)));
        tr.appendChild(el('td', 'num', trBits(x['in'])));
        tr.appendChild(el('td', 'num', num(x.conns)));
        tr.onclick = function () {
          /* Where it went is the server inside, for a dst-nat. */
          tOpen((k[0] === 'dst' ? '(dstip:' + tQuote(x.key) + ' OR tranip:' + tQuote(x.key) + ')'
                 : k[2] + ':' + tQuote(x.key)) + ' fw:' + tQuote(r.name), 'list');
        };
        return tr;
      }));
    }
    grid.appendChild(box);
  });
  card.appendChild(grid);
  host.appendChild(card);
}

/** One interface over the day, five minutes a bar: in above, out below. */
var TR_HIST = {};
var TR_HIST_DATA = {};
function trHistory(host, r) {
  var names = r.hist_names || [];
  if (!names.length) return;
  var want = TR_HIST[r.name];
  if (!want || names.indexOf(want) < 0) {
    want = (r.wan || []).filter(function (n) { return names.indexOf(n) >= 0; })[0] || names[0];
  }
  var card = el('div', 'card full');
  card.style.marginTop = '14px';
  var h = el('h2', '', 'Over the day');
  var pick = el('select');
  names.forEach(function (n) {
    var o = document.createElement('option');
    o.value = n;
    o.textContent = n;
    pick.appendChild(o);
  });
  pick.value = want;
  pick.onchange = function () { TR_HIST[r.name] = pick.value; drawRouter(); };
  var right = el('span', 'right');
  right.appendChild(noI18n(pick));
  h.appendChild(right);
  card.appendChild(h);
  card.appendChild(el('p', 'note', 'What the interface carried, five minutes a bar: in above '
    + 'the line, out below it. Kept since this began reading the router, for a day. Press an '
    + 'interface below for its own.'));
  var chart = el('div', 'tr-hist');
  chart.appendChild(el('p', 'center muted', 'Reading\u2026'));
  card.appendChild(chart);
  host.appendChild(card);
  /* Asked once for each look at the router (1.10.217): drawn again as the
     tables are narrowed, it was asked again at every key. */
  var hkey = r.name + '|' + want + '|' + (r.at || '');
  if (TR_HIST_DATA[hkey]) {
    trChart(chart, TR_HIST_DATA[hkey].hist, TR_HIST_DATA[hkey].step);
    return;
  }
  api('fw-router&fw=' + encodeURIComponent(r.name) + '&hist=' + encodeURIComponent(want))
    .then(function (d) {
      TR_HIST_DATA = {};
      TR_HIST_DATA[hkey] = {hist: d.hist || [], step: d.step || 300};
      trChart(chart, d.hist || [], d.step || 300);
    })
    .catch(function () {
      clear(chart);
      chart.appendChild(el('p', 'center muted', 'It could not be read just now.'));
    });
}
function trChart(host, rows, step) {
  clear(host);
  if (!rows.length) {
    host.appendChild(el('p', 'center muted', 'Nothing yet.'));
    return;
  }
  var most = 1;
  rows.forEach(function (x) { most = Math.max(most, x[1], x[2]); });
  var first = rows[0][0], last = rows[rows.length - 1][0];
  var n = Math.max(1, Math.round((last - first) / step) + 1);
  var w = Math.max(288, n), hgt = 120, mid = hgt / 2;
  var ns = 'http://www.w3.org/2000/svg';
  var svg = document.createElementNS(ns, 'svg');
  svg.setAttribute('viewBox', '0 0 ' + w + ' ' + hgt);
  svg.setAttribute('preserveAspectRatio', 'none');
  svg.setAttribute('class', 'tr-hist-svg');
  rows.forEach(function (x) {
    var at = Math.round((x[0] - first) / step) + (w - n);
    [[x[1], true], [x[2], false]].forEach(function (one) {
      var hh = Math.max(0.5, (one[0] / most) * (mid - 2));
      var bar = document.createElementNS(ns, 'rect');
      bar.setAttribute('x', at);
      bar.setAttribute('width', 0.85);
      bar.setAttribute('y', one[1] ? mid - hh : mid);
      bar.setAttribute('height', hh);
      bar.setAttribute('class', one[1] ? 'in' : 'out');
      var tip = document.createElementNS(ns, 'title');
      tip.textContent = stamp(x[0]) + ' \u00b7 ' + (one[1] ? 'in ' : 'out ')
        + trBits(one[0] * 8 / step);
      bar.appendChild(tip);
      svg.appendChild(bar);
    });
  });
  host.appendChild(svg);
  var under = el('div', 'tr-hist-under muted small');
  under.appendChild(el('span', '', stamp(first)));
  under.appendChild(el('span', '', 'the busiest five minutes: ' + trBits(most * 8 / step)));
  under.appendChild(el('span', '', stamp(last)));
  host.appendChild(under);
}

/** On the overview: what goes through its way out now (1.10.214). Only
    where a router is read through its API or over ssh. */
var TROUTER_CARD = {at: 0, r: null, fw: null};
function tRouterCard() {
  var host = $('t-cards');
  if (!host || TPAGE !== 'over') return;
  var names = TFW ? TROUTERS.filter(function (n) { return n === TFW; }) : TROUTERS.slice(0, 1);
  var old = $('t-card-router');
  if (!names.length) { if (old) old.remove(); return; }
  var paintIt = function (r) {
    var was = $('t-card-router');
    if (was) was.remove();
    if (!r) return;
    var wan = r.wan || [];
    var ifs = (r.interfaces || []).filter(function (i) { return wan.indexOf(i.name) >= 0; });
    var rx = 0, tx = 0;
    ifs.forEach(function (i) { rx += Number(i['rx-rate']) || 0; tx += Number(i['tx-rate']) || 0; });
    var card = tCard('info', 'Through it now', trBits(rx + tx),
      '\u2193 ' + trBits(rx) + ' in \u00b7 \u2191 ' + trBits(tx) + ' out'
        + (wan.length ? ' \u00b7 ' + wan.join(', ') : ''),
      'What goes through ' + (r.state && r.state.identity || r.name) + '\u2019s way out to the '
        + 'internet now (' + (wan.join(', ') || '?') + '), as its interfaces said at the last '
        + 'look. Press for the router.', function () { tShowPage('router'); });
    card.id = 't-card-router';
    host.appendChild(card);
  };
  if (TROUTER_CARD.r && TROUTER_CARD.fw === names[0] && Date.now() - TROUTER_CARD.at < 30000) {
    paintIt(TROUTER_CARD.r);
    return;
  }
  var asked = names[0];
  api('fw-router&fw=' + encodeURIComponent(asked)).then(function (d) {
    TROUTER_CARD = {at: Date.now(), r: d.router, fw: asked};
    /* ...only if it is still the firewall the tab is about. */
    var now = TFW ? (TROUTERS.indexOf(TFW) >= 0 ? TFW : '') : (TROUTERS[0] || '');
    if (TPAGE === 'over' && now === asked) paintIt(d.router);
  }).catch(function () { });
}

function drawOneRouter(host, r) {
  var st = r.state || {};
  var res = r.resource || {};
  var many = (TROUTER || []).length > 1;
  if (many) host.appendChild(el('h2', 't-router-name', r.name));
  var cards = el('div', 'grid top');
  var total = Number(res['total-memory']) || 0;
  var used = total ? Math.round(100 - 100 * (Number(res['free-memory']) || 0) / total) : null;
  cards.appendChild(tCard(st.connected ? 'ok' : 'crit', 'The router',
    noI18n(el('span', '', st.identity || r.name)),
    'RouterOS ' + (res.version || st.version || '?') + (res['board-name'] ? ' · '
      + res['board-name'] : ''),
    'Read ' + (r.via === 'ssh' ? 'over ssh' : 'through its API') + ' from ' + (r.host || '?')
      + (st.at ? ', last ' + ago(st.at) : '') + (st.trouble ? ' — ' + st.trouble : '')
      + '.'));
  cards.appendChild(tCard(Number(res['cpu-load']) > 85 ? 'warn' : 'info', 'CPU',
    res['cpu-load'] !== undefined ? res['cpu-load'] + ' %' : '–',
    (res['cpu-count'] ? res['cpu-count'] + ' × ' : '') + (res.cpu || res['architecture-name']
      || ''), 'How busy its processor was at the last look.'));
