     {words: 'In', cls: 'num'}, {words: 'Out', cls: 'num'}, {words: 'Errors / drops', cls: 'num'},
     {words: 'Link downs', cls: 'num'}, 'Last up', 'MAC', 'Comment'],
    function (i) {
