      return tr;
    });
}

/** The line under the chart: how new the newest line is, and how old what
    is drawn. Apart, so that a refresh that changed nothing else puts only
    it right (1.10.192). */
function tChartNote(d) {
  $('t-chart-note').textContent = (d.words || 'the firewall') + ' · newest line '
    + (d.newest ? ago(d.newest) : 'never');
  if (d.ready) {
    /* A piece of its own, so that it is read (and translated) by itself. */
    var when = el('span', 't-ready', d.ready.busy ? 'being worked out again now'
      : 'worked out ' + ago(d.ready.at));
    $('t-chart-note').appendChild(document.createTextNode(' \u00b7 '));
    $('t-chart-note').appendChild(when);
    explain(when, 'The cards, the chart and the lists of the busiest are worked '
      + 'out behind the daemon and kept, so the page opens at once: this one took '
      + tTook(d.ready.took) + ' and is worked out again every ' + tTook(d.ready.every)
      + ' at the least. The lists of lines on the other pages of this tab are always as they '
      + 'are this moment. '
      + 'Settings \u2192 The firewall log switches this off.');
  }
}

/** What is kept: how many lines since when, and where it is erased. */
function tStored(d) {
  var host = $('t-stored');
  if (!host) return;
  clear(host);
  var s = d.stored || {}, k = d.keep || {};
  /* Each piece its own sentence, so that each is said in the page's
     language: one long string with a phrase put inside it was translated
     around the phrase and left it in English. (1.10.206) */
  host.appendChild(el('span', '', s.oldest
    ? num(s.rows || 0) + ' line(s) kept, the oldest from ' + stamp(s.oldest)
    : num(s.rows || 0) + ' line(s) kept'));
  host.appendChild(document.createTextNode(' \u00b7 '));
  host.appendChild(el('span', '', num(s.buckets || 0)
    + ' counted bucket(s) behind the cards and the chart'));
  host.appendChild(document.createTextNode(' \u00b7 '));
  host.appendChild(el('span', '', k.allowed
    ? 'kept ' + (k.allowed_days || 1) + ' day(s) for what was let through and '
      + (k.days || 7) + ' day(s) for the rest'
    : 'kept without what was let through, ' + (k.days || 7) + ' day(s) for the rest'));
  var go = el('button', 'linkish', 'Sizes, and erasing it');
  go.type = 'button';
  explain(go, 'Settings \u2192 The database: how much each table holds and what the database '
    + 'weighs, and erasing the firewall\u2019s lines - all of them, or with everything else.');
  go.onclick = function () { showTab('settings'); showPane('db'); };
  host.appendChild(go);
  var how = el('button', 'linkish', 'How long they are kept');
  how.type = 'button';
  explain(how, 'Settings \u2192 The firewall log.');
  how.onclick = function () { showTab('settings'); showPane('fwlog'); };
  host.appendChild(how);
}

/* ---- the chart: let through above the line, refused below it ---------- */
function drawTrafficChart(d) {
  var host = $('t-chart');
  clear(host);
  var span = d.span || 3600;
  var buckets = {};
  (d.series || []).forEach(function (p) {
    var one = buckets[p.at] = buckets[p.at] || {at: p.at};
    one[p.verdict] = (one[p.verdict] || 0) + p.n;
  });
  /* The window's own ends when it was chosen by its dates. */
  var start = d.since ? Math.floor(d.since / span) * span
    : Math.floor((Date.now() / 1000 - tHours() * 3600) / span) * span;
  var end = Math.floor((d.until || Date.now() / 1000) / span) * span;
  var bars = [];
  for (var at = start; at <= end; at += span) bars.push(buckets[at] || {at: at});
  if (!(d.series || []).length) {
    host.appendChild(el('div', 'empty', 'Nothing has arrived in this window'));
    return;
  }
  var up = 1, down = 1;
  bars.forEach(function (b) {
    up = Math.max(up, (b.allow || 0) + (b.info || 0));
    down = Math.max(down, (b.deny || 0) + (b.block || 0) + (b.fail || 0));
  });
  var W = Math.max(320, host.clientWidth || 1000), H = 240, mid = Math.round(H * up / (up + down * 1.0));
  mid = Math.max(70, Math.min(H - 50, mid));
  var bw = W / bars.length;
  var ns = 'http://www.w3.org/2000/svg';
  var svg = document.createElementNS(ns, 'svg');
  svg.setAttribute('viewBox', '0 0 ' + W + ' ' + (H + 22));
  svg.setAttribute('preserveAspectRatio', 'none');
  var tip = el('div', 'tip');
  function rect(x, y, w, h, fill, cls) {
    var r = document.createElementNS(ns, 'rect');
    r.setAttribute('x', x); r.setAttribute('y', y);
    r.setAttribute('width', Math.max(0, w)); r.setAttribute('height', Math.max(0, h));
    r.setAttribute('fill', fill);
    if (cls) r.setAttribute('class', cls);
    svg.appendChild(r);
    return r;
  }
  var line = document.createElementNS(ns, 'line');
  line.setAttribute('x1', 0); line.setAttribute('x2', W);
  line.setAttribute('y1', mid); line.setAttribute('y2', mid);
  line.setAttribute('stroke', 'var(--line)');
  svg.appendChild(line);
  var step = Math.max(1, Math.ceil(bars.length / 8));
  bars.forEach(function (b, i) {
    var x = i * bw + bw * 0.12, w = bw * 0.76;
    var yTop = mid;
    /* A colour the hour has is never thinner than two pixels: a dozen let
       through beside a hundred thousand refused was a tenth of a pixel, and
       the hour looked as if nothing had been let through at all (1.10.164). */
    ['allow', 'info'].forEach(function (v) {
      var h = (b[v] || 0) / up * (mid - 8);
      if (h > 0) h = Math.max(2, h);
      yTop -= h;
      if (h > 0) rect(x, yTop, w, h, T_VERDICTS[v].fill).setAttribute('opacity', v === 'info' ? .5 : .85);
    });
    var yBot = mid;
    ['deny', 'block', 'fail'].forEach(function (v) {
      var h = (b[v] || 0) / down * (H - mid - 8);
      if (h > 0) h = Math.max(2, h);
      if (h > 0) rect(x, yBot, w, h, T_VERDICTS[v].fill).setAttribute('opacity', .9);
      yBot += h;
    });
    var hit = rect(i * bw, 0, bw, H, 'transparent', 'hit');
    hit.addEventListener('mousemove', function (e) {
      clear(tip);
      /* A day's bar is the firewall's day as it is counted, from midnight
         UTC, and says so (1.10.187). */
      tip.appendChild(el('b', '', stamp(b.at) + (span >= 86400
        ? ' \u2013 ' + stamp(b.at + span) + ' (a day from midnight UTC)' : '')));
      T_ORDER.forEach(function (v) {
        if (b[v]) {
          var said = el('div');
          said.appendChild(el('span', '', T_VERDICTS[v].words));
          said.appendChild(document.createTextNode(': ' + num(b[v])));
          tip.appendChild(said);
        }
      });
      var box = host.getBoundingClientRect();
      tip.style.left = Math.min(box.width - 180, e.clientX - box.left + 12) + 'px';
      tip.style.top = Math.max(0, e.clientY - box.top - 20) + 'px';
      tip.style.display = 'block';
    });
    hit.addEventListener('mouseleave', function () { tip.style.display = 'none'; });
    hit.addEventListener('click', function () {
      tOpen('', 'list', {from: b.at, to: b.at + span});
    });
    if (i % step === 0) {
      var t = document.createElementNS(ns, 'text');
      t.setAttribute('x', i * bw + bw / 2); t.setAttribute('y', H + 16);
      t.setAttribute('text-anchor', 'middle');
      t.setAttribute('class', 't-axis');
      var dd = new Date(b.at * 1000);
      /* Named after the UTC day it counts, not the local date its first
         moment falls on: west of Greenwich that was the day before. */
      t.textContent = span >= 86400 ? pad2(dd.getUTCDate()) + '-' + pad2(dd.getUTCMonth() + 1)
        : pad2(dd.getHours()) + ':00';
      svg.appendChild(t);
    }
  });
  host.appendChild(svg);
  host.appendChild(tip);
  var legend = $('t-legend');
  clear(legend);
  T_ORDER.forEach(function (v) {
    if (!tTotal(d, v)) return;
    var one = el('span');
    var dot = el('i');
    dot.style.background = T_VERDICTS[v].fill;
    one.appendChild(dot);
    /* The words and the number apart: each is said in the page's language
       on its own, where `said 26 943` together was nobody's string. */
    one.appendChild(el('span', '', T_VERDICTS[v].words));
    one.appendChild(document.createTextNode(' ' + num(tTotal(d, v))));
    legend.appendChild(one);
  });
}

/* ---- the cards of the busiest ----------------------------------------- */
/* Each card says what the search box is given when a row of it is pressed,
   so the list opened is a search somebody can read, change and keep. */
function tQuote(v) {
  v = String(v === undefined || v === null ? '' : v);
  return (!v || /[\s(),"]/.test(v)) ? '"' + v.replace(/"/g, '') + '"' : v;
}
/* ---- connected now ------------------------------------------------------
   Who is on the VPN and which tunnels are up. Not a list of lines: the
   daemon puts it together out of them, and says from how far back. */
var TVPN = null, TVPN_ASKED = 0;
/* A page of each list, filtered on the daemon (1.10.168): the whole of
   both, every few seconds, was tens of megabytes on a big head end and froze
   the browser drawing it. The daemon works them out every twenty seconds, so
   a refresh between those asks nothing; one that brings what is already
   drawn draws nothing. */
var TVPN_PER = 200, TVPN_PAGE = {c: 0, t: 0}, TVPN_AT = 0, TVPN_KEY = '';
function tvAsk() {
  return 'fw-vpn&list=1' + tFwArg() + '&q=' + encodeURIComponent($('tv-q').value.trim())
    + '&climit=' + TVPN_PER + '&coffset=' + TVPN_PAGE.c * TVPN_PER
    + '&tlimit=' + TVPN_PER + '&toffset=' + TVPN_PAGE.t * TVPN_PER;
}
function loadVpnNow(quiet) {
  var ask = tvAsk();
  if (quiet && TVPN && ask === TVPN_KEY && Date.now() - TVPN_AT < 20000) return;
  var mine = ++TVPN_ASKED;
  if (!quiet && !TVPN) {
    clear($('tv-clients'));
    $('tv-clients').appendChild(el('p', 'center muted', 'Reading…'));
  }
  api(ask).then(function (d) {
    if (mine !== TVPN_ASKED) return;
    /* Still being put together for the first time: said, and asked again
       in a few seconds, rather than every request waiting for it.
       (1.10.183) */
    if (d.building) {
      if (!TVPN) {
        clear($('tv-clients'));
        $('tv-clients').appendChild(el('p', 'center muted',
          'Putting together who is connected from the firewall\u2019s lines \u2014 on a busy '
          + 'firewall this takes a few minutes after a start.'));
      }
      clearTimeout(window._tvBuilding);
      window._tvBuilding = setTimeout(function () {
        if (TAB === 'traffic') loadVpnNow(true);
      }, 5000);
      return;
    }
    TVPN_AT = Date.now();
    /* A page that is no longer there - the list got shorter under it: the
       last one that is. */
    if (d.paged && ((TVPN_PAGE.c && TVPN_PAGE.c * TVPN_PER >= d.clients_match)
                    || (TVPN_PAGE.t && TVPN_PAGE.t * TVPN_PER >= d.tunnels_match))) {
      TVPN_PAGE.c = Math.min(TVPN_PAGE.c, Math.max(0, Math.ceil(d.clients_match / TVPN_PER) - 1));
      TVPN_PAGE.t = Math.min(TVPN_PAGE.t, Math.max(0, Math.ceil(d.tunnels_match / TVPN_PER) - 1));
      loadVpnNow(false);
      return;
    }
    var same = TVPN && ask === TVPN_KEY && d.made && d.made === TVPN.made;
    TVPN = d;
    TVPN_KEY = ask;
    if (!same) drawVpnNow();
  }).catch(function (e) { if (!quiet) oops(e); });
}
var tvFindSoon = debounce(function () {
  TVPN_PAGE = {c: 0, t: 0};
  loadVpnNow(false);
}, 300);
$('tv-q').oninput = tvFindSoon;

function tvMatches(o, q) {
  if (!q) return true;
  var hay = [o.user, o.srcip, o.inner, o.group, o.client, o.peer, o.local, o.name, o.ike,
             o.kind, o.local_ts, o.remote_ts, o.fw, o.dev, o.cc].join(' ').toLowerCase();
  return q.split(/\s+/).every(function (w) { return hay.indexOf(w) >= 0; });
}

/** Where a person or a peer is: the address with its flag, or that it is
    one of the site's own. */
function tvFrom(ip, o) {
  var box = el('span', 't-name');
  box.appendChild(el('span', 'mono', ip || '\u2013'));
  if (o.private) box.appendChild(el('span', 'tag dim', 'private'));
  else if (o.cc) box.appendChild(countryBadge(o.cc));
  return box;
}
function tvSince(o, at) {
  return (o.since_known ? '' : 'at least ') + span(Math.max(0, Date.now() / 1000 - at));
}

function drawVpnNow() {
  var d = TVPN || {};
  /* The daemon has filtered them and sent one page; an answer of an older
     daemon is the whole of both, filtered here as it always was. */
  var q = $('tv-q').value.trim().toLowerCase();
  var clients = d.paged ? (d.clients || [])
    : (d.clients || []).filter(function (c) { return tvMatches(c, q); });
  var tunnels = d.paged ? (d.tunnels || [])
    : (d.tunnels || []).filter(function (t) { return tvMatches(t, q); });
  var cAll = d.paged ? d.clients_total : (d.clients || []).length;
  var tAll = d.paged ? d.tunnels_total : (d.tunnels || []).length;
  var many = (TFWS || []).length > 1 && !d.fw;
  $('tv-c-n').textContent = num(cAll) + ' connected'
    + (d.ended_clients ? ' \u00b7 ' + num(d.ended_clients) + ' ended in the lines kept' : '');
  $('tv-t-n').textContent = num(tAll) + ' up';
  pager('tv-c-pager', TVPN_PAGE.c, TVPN_PER, d.paged ? d.clients_match : 0, function (to) {
    TVPN_PAGE.c = to;
    loadVpnNow(false);
  });
  pager('tv-t-pager', TVPN_PAGE.t, TVPN_PER, d.paged ? d.tunnels_match : 0, function (to) {
    TVPN_PAGE.t = to;
    loadVpnNow(false);
  });
  $('tv-said').textContent = d.oldest ? 'from the lines kept since ' + stamp(d.oldest)
    + ' \u2014 anything up for longer shows as \u201cat least\u201d' : 'no VPN lines kept yet';
  var ch = $('tv-clients');
  clear(ch);
  if (!clients.length) {
    ch.appendChild(el('p', 'center muted', cAll ? 'Nobody matches'
      : 'Nobody is connected, as far as the lines kept say.'));
  } else {
    var heads = ['Person', 'From', 'Inside the VPN', 'Group', 'Client', 'Connected for',
                 'Last heard', {words: 'Drops', cls: 'num'}];
    if (many) heads.splice(0, 0, 'Firewall');
    ch.appendChild(listTable(heads, clients, function (c) {
      var tr = el('tr', c.quiet ? 't-vpn-quiet' : '');
      if (many) tr.appendChild(el('td', 'muted', c.fw));
      var who = el('td');
      /* A name in the typeface every other name on the page is in, and the
         address inside the tunnel named the way the Traffic list names its
         addresses. (1.10.160) */
      who.appendChild(noI18n(el('b', 'mono', c.user || '\u2013')));
      if (c.mtu) {
        var m = el('span', 'tag warn', 'MTU');
        who.appendChild(document.createTextNode(' '));
        who.appendChild(m);
      }
      tr.appendChild(who);
      var from = el('td');
      from.appendChild(tvFrom(c.srcip, c));
      tr.appendChild(from);
      var inner = el('td');
      inner.appendChild(tAddress(c.inner || ''));
      tr.appendChild(inner);
      tr.appendChild(el('td', '', c.group || '\u2013'));
      tr.appendChild(el('td', 'muted', c.client || c.kind || '\u2013'));
      tr.appendChild(el('td', '', tvSince(c, c.started)));
      tr.appendChild(el('td', 'muted', c.quiet ? ago(c.last) + ' \u2014 perhaps gone'
        : ago(c.last)));
      tr.appendChild(el('td', 'num', c.drops ? num(c.drops) : ''));
      opensWith(tr, '<b>' + c.user + '</b> from ' + (c.srcip || '?')
        + (c.inner ? ', inside the VPN ' + c.inner : '') + '. Press for everything known '
        + 'about this session.', function () { showVpnOne(c.id); });
      return tr;
    }, 'rows'));
  }
  var th = $('tv-tunnels');
  clear(th);
  if (!tunnels.length) {
    th.appendChild(el('p', 'center muted', tAll ? 'No tunnel matches'
      : 'No tunnel is up, as far as the lines kept say.'));
  } else {
    var heads2 = ['Peer', 'Tunnel', 'IKE', 'This side', 'Up for', 'Last rekey',
                  {words: 'SAs', cls: 'num'}, 'Their networks'];
    if (many) heads2.splice(0, 0, 'Firewall');
    th.appendChild(listTable(heads2, tunnels, function (t) {
      var tr = el('tr');
      if (many) tr.appendChild(el('td', 'muted', t.fw));
      var who = el('td');
      who.appendChild(tvFrom(t.peer, t));
      if (t.resets) {
        who.appendChild(document.createTextNode(' '));
        who.appendChild(el('span', 'tag warn', 'started over ' + num(t.resets) + '\u00d7'));
      }
      tr.appendChild(who);
      tr.appendChild(el('td', '', t.name || t.group || '\u2013'));
      tr.appendChild(el('td', 'muted', t.ike || t.kind || '\u2013'));
      tr.appendChild(el('td', 'mono muted', t.local || '\u2013'));
      tr.appendChild(el('td', '', tvSince(t, t.since || t.last)));
      tr.appendChild(el('td', 'muted', t.last_rekey ? ago(t.last_rekey) : '\u2013'));
      var sas = t.sas ? t.sas.length : (t.sas_n || 0);
      var sels = t.selectors ? t.selectors.length : (t.selectors_n || 0);
      tr.appendChild(el('td', 'num', sas ? num(sas) : '\u2013'));
      tr.appendChild(el('td', 'mono muted', (t.remote_ts || '\u2013')
        + (sels > 1 ? ' +' + (sels - 1) : '')));
      opensWith(tr, 'The tunnel to <b>' + t.peer + '</b>' + (t.name || t.group
        ? ' (' + (t.name || t.group) + ')' : '') + '. Press for its networks, its SAs and '
        + 'what crossed it.', function () { showVpnOne(t.id); });
      return tr;
    }, 'rows'));
  }
  explainWhatWasDrawn($('t-page-vpn'));
}

/** One session or tunnel, everything the lines say about it. */
function showVpnOne(id) {
  modal('On the VPN now', function (body) {
    body.appendChild(el('p', 'center muted', 'Reading…'));
  }, [{words: 'Close', close: true}]);
  var ticket = modalTicket();
  api('fw-vpn&id=' + encodeURIComponent(id) + tFwArg()).then(function (d) {
    if (!modalStill(ticket)) return;
    var o = d.one;
    $('modal-title').textContent = o.what === 'client'
      ? o.user + ' on the remote-access VPN' : 'The tunnel to ' + o.peer;
    var body = $('modal-body');
    clear(body);
    if (o.what === 'client') drawVpnClient(body, o); else drawVpnTunnel(body, o);
    explainWhatWasDrawn(body);
  }).catch(function (e) {
    if (!modalStill(ticket)) return;
    var body = $('modal-body');
    clear(body);
    body.appendChild(el('p', 'center bad', String((e && e.message) || e)));
  });
}

function tvTags(o) {
  var line = el('span', 't-side-tags');
  if (o.banned) line.appendChild(el('span', 'tag crit', 'kept out here'));
  (o.feeds || []).forEach(function (feed) { line.appendChild(el('span', 'tag warn', feed)); });
  return line;
}

function tvButtons(list) {
  var row = el('div', 't-side-buttons');
  list.forEach(function (b) {
    var btn = cmdButton(b[0], b[1], 'small');
    btn.onclick = b[2];
    row.appendChild(btn);
  });
  return row;
}

function tvGo(term, page) {
  closeAllModals();
  showTab('traffic');
  tOpen(term, page);
}

function tvLines(body, lines) {
  if (!(lines || []).length) return;
  body.appendChild(el('h3', 't-vpn-h', 'Its lines, newest first'));
  body.appendChild(listTable(['When', 'What', 'What it said'], lines, function (r) {
    var tr = el('tr');
    tr.appendChild(el('td', 'muted', stamp(r.ts)));
    tr.appendChild(el('td', '', TV_ACTIONS[r.action] || FG_ACTIONS[r.action] || r.action
      || ''));
    tr.appendChild(el('td', 'muted t-wrap', r.msg || ''));
    opensWith(tr, 'Press for this line, read out.', function () { showFwLine(r.ident, r.ts); });
    return tr;
  }, 'rows'));
}

function drawVpnClient(body, c) {
  var from = el('span');
  from.appendChild(tvFrom(c.srcip, c));
  from.appendChild(tvTags(c));
  body.appendChild(peekFacts([
    ['Person', c.user],
    c.group ? ['Group (tunnel group)', c.group] : null,
    c.group_policy ? ['Group policy', c.group_policy] : null,
    c.dap ? ['DAP records', c.dap] : null,
    c.pool ? ['Address pool', c.pool] : null,
    c.dtls !== undefined ? ['DTLS (UDP)', c.dtls ? 'yes' : 'no'] : null,
    ['Connected from', from],
    ['Inside the VPN', c.inner || 'not said in the lines kept'],
    (c.client || c.kind) ? ['Client', c.client || c.kind] : null,
    ['Connected since', (c.since_known ? '' : 'at least since ') + stamp(c.started)],
    ['Connected for', tvSince(c, c.started)],
    ['Last heard of', ago(c.last) + (c.quiet ? ' \u2014 nothing for a long time; it may '
      + 'have ended without the firewall saying so' : '')],
    c.connections ? ['Connections made', num(c.connections)] : null,
    c.drops ? ['Connections dropped', num(c.drops) + (c.why_last ? ', the last: '
      + c.why_last : '')] : null,
    c.mtu ? ['Packets too large', c.mtu + ' bytes \u2014 the MTU on the way is smaller '
      + 'than the client thinks'] : null,
    (c.sent || c.rcvd) ? ['Carried so far', '\u2191 ' + bytes(c.sent) + ' \u00b7 \u2193 '
      + bytes(c.rcvd)] : null,
    ['Firewall', c.fw + (c.dev && c.dev !== c.fw ? ' \u00b7 ' + c.dev : '')]
  ]));
  var ise = c.ise;
  if (ise) {
    body.appendChild(el('h3', 't-vpn-h', 'What ISE gave them'));
    body.appendChild(peekFacts([
      ['Signed in', stamp(ise.ts) + (ise.ip ? ' from ' + ise.ip : '')],
      ise.groups ? ['Groups', ise.groups] : null,
      ise.profile ? ['Authorization profile', ise.profile] : null,
      ise.policy ? ['Policy set', ise.policy] : null,
      ise.acl ? ['Downloadable ACL', ise.acl] : null,
      ise.device ? ['Device', ise.device] : null,
      ise.client ? ['Client', ise.client] : null,
      ise.failed_day ? ['Refused by ISE, last 24 h', num(ise.failed_day)] : null
    ]));
  }
  var tr = c.traffic;
  if (tr) {
    body.appendChild(el('h3', 't-vpn-h', 'What ' + c.inner + ' did since'));
    var said = T_ORDER.filter(function (v) { return (tr.by || {})[v]; }).map(function (v) {
      return T_VERDICTS[v].words + ' ' + num(tr.by[v].n) + ' (' + bytes(tr.by[v].bytes) + ')';
    }).join(' \u00b7 ');
    body.appendChild(el('p', 'note', said || 'No session from that address in the lines kept.'));
    if ((tr.refused_by || []).length) {
      body.appendChild(peekFacts(tr.refused_by.map(function (r) {
        return ['Refused by', (r.policy || 'a policy') + ' \u2014 ' + num(r.n)];
      })));
    }
    if ((tr.to || []).length) {
      body.appendChild(listTable(['Where to', 'Service', {words: 'Sessions', cls: 'num'},
                                  {words: 'Refused', cls: 'num'}, {words: 'Data', cls: 'num'}],
        tr.to, function (r) {
          var row = el('tr');
          row.appendChild(el('td', 'mono', r.dstip + (r.dstport ? ':' + r.dstport : '')));
          row.appendChild(el('td', 'muted', r.service || ''));
          row.appendChild(el('td', 'num', num(r.n)));
          row.appendChild(el('td', 'num', r.refused ? num(r.refused) : ''));
          row.appendChild(el('td', 'num', bytes(r.bytes)));
          return row;
        }, 'rows'));
    }
  }
  body.appendChild(tvButtons([
    ['Everything about ' + c.user, 'search', function () {
      closeAllModals(); openFind(c.user); setTimeout(function () { lookUpPerson(c.user); }, 40); }],
    ['This person\u2019s VPN lines', 'list', function () {
      tvGo('user:' + tQuote(c.user) + ' kind:event/vpn', 'cvpn'); }],
    c.inner ? ['What ' + c.inner + ' did', 'list', function () {
      tvGo('srcip:' + c.inner, 'list'); }] : null
  ].filter(Boolean)));
  tvLines(body, c.lines);
}

function drawVpnTunnel(body, t) {
  var from = el('span');
  from.appendChild(tvFrom(t.peer, t));
  from.appendChild(tvTags(t));
  var nets = t.nets || {};
  body.appendChild(peekFacts([
    ['Peer', from],
    ['This side', t.local || '\u2013'],
    (t.name || t.group) ? ['Tunnel', t.name || t.group] : null,
    (t.name && t.group) ? ['Tunnel group', t.group] : null,
    (t.ike || t.kind) ? ['Kind', [t.ike, t.kind].filter(function (x, i, all) {
      return x && all.indexOf(x) === i; }).join(' \u00b7 ')] : null,
    ['Up since', (t.since_known ? '' : 'at least since ') + stamp(t.since || t.last)],
    ['Up for', tvSince(t, t.since || t.last)],
    t.last_rekey ? ['Last rekey', stamp(t.last_rekey) + ' (' + ago(t.last_rekey) + ')'] : null,
    (t.rekeys || t.sa_made) ? ['Rekeys in the lines kept', num(t.rekeys || 0) + ' of the tunnel, '
      + num(t.sa_made || 0) + ' IPsec SA(s) made, ' + num(t.sa_gone || 0) + ' deleted'] : null,
    t.resets ? ['Started over by the peer', num(t.resets) + ' time(s), the last '
      + ago(t.last_reset)] : null,
    ['Last heard of', ago(t.last)],
    (t.sent || t.rcvd) ? ['Carried', '\u2191 ' + bytes(t.sent) + ' \u00b7 \u2193 '
      + bytes(t.rcvd)] : null,
    ['Firewall', t.fw + (t.dev && t.dev !== t.fw ? ' \u00b7 ' + t.dev : '')]
  ]));
  body.appendChild(el('h3', 't-vpn-h', 'Its networks'));
  if ((t.selectors || []).length > 1) {
    body.appendChild(listTable(['This side', 'The peer\u2019s side', 'Last negotiated'],
      t.selectors, function (x) {
        var row = el('tr');
        row.appendChild(el('td', 'mono', x.local || '\u2013'));
        row.appendChild(el('td', 'mono', x.remote || '\u2013'));
        row.appendChild(el('td', 'muted', stamp(x.ts) + ' (' + ago(x.ts) + ')'));
        return row;
      }, 'rows'));
  } else if (nets.local || nets.remote) {
    body.appendChild(peekFacts([
      ['This side asks for', nets.local || '\u2013'],
      ['The peer asks for', nets.remote || '\u2013']
    ]));
  } else {
    body.appendChild(el('p', 'note', 'The lines kept do not name its networks: FTD writes '
      + 'them when the tunnel is negotiated (750001), not at a rekey. A route-based tunnel '
      + '(VTI) asks for every address, and its routes decide what goes through it.'));
  }
  if (nets.any) {
    body.appendChild(el('p', 'note', 'Every address on at least one side: a route-based '
      + 'tunnel, so which sessions crossed it cannot be told from the lines.'));
  } else if ((nets.hosts || []).length) {
    body.appendChild(el('p', 'note', 'Between the peer\u2019s networks and anywhere, the '
      + 'last 24 h: ' + num(nets.n) + ' line(s), ' + bytes(nets.bytes) + '.'));
    body.appendChild(listTable(['Address on their side', {words: 'Lines', cls: 'num'},
                                {words: 'Data', cls: 'num'}], nets.hosts, function (h) {
      var row = el('tr');
      row.appendChild(el('td', 'mono', h.ip));
      row.appendChild(el('td', 'num', num(h.n)));
      row.appendChild(el('td', 'num', bytes(h.bytes)));
      opensWith(row, 'Press for the lines of ' + h.ip + '.', function () {
        tvGo('ip:' + h.ip, 'list'); });
      return row;
    }, 'rows'));
  }
  if ((t.events || []).length) {
    body.appendChild(el('h3', 't-vpn-h', 'What happened to it'));
    body.appendChild(listTable(['When', 'What', 'Why'], t.events.slice().reverse(),
      function (e) {
        var row = el('tr');
        row.appendChild(el('td', 'muted', stamp(e.ts) + ' (' + ago(e.ts) + ')'));
        row.appendChild(el('td', '', e.what));
        row.appendChild(el('td', 'muted', e.why || ''));
        return row;
      }, 'rows'));
  }
  if ((t.sas || []).length) {
    body.appendChild(el('h3', 't-vpn-h', 'Its IPsec SAs'));
    body.appendChild(listTable(['SPI', 'Which way', 'Made'], t.sas, function (sa) {
      var row = el('tr');
      row.appendChild(el('td', 'mono', sa.spi));
      row.appendChild(el('td', '', sa.dir || ''));
      row.appendChild(el('td', 'muted', stamp(sa.ts) + ' (' + ago(sa.ts) + ')'));
      return row;
    }, 'rows'));
  }
  if ((t.fails || []).length) {
    body.appendChild(el('h3', 't-vpn-h', 'What failed with this peer, last 24 h'));
    body.appendChild(listTable(['What it said', {words: 'Times', cls: 'num'}, 'Last'],
      t.fails, function (f) {
        var row = el('tr');
        row.appendChild(el('td', 'muted t-wrap', f.msg || ''));
        row.appendChild(el('td', 'num', num(f.n)));
        row.appendChild(el('td', 'muted', ago(f.last)));
        return row;
      }, 'rows'));
  }
  body.appendChild(tvButtons([
    ['Everything about ' + t.peer, 'search', function () { lookUp(t.peer); }],
    ['This peer\u2019s lines', 'list', function () {
      tvGo('srcip:' + t.peer + ' kind:event/vpn', 's2s'); }]
  ]));
  tvLines(body, t.lines);
}

var T_SESSIONS_ONLY = ' kind:traffic';
var T_TOPS = [
  {dim: 'src', part: 'busiest', title: 'Who talks the most',
   note: 'The addresses that started the most sessions, and what the firewall did with them.',
   term: function (v) { return 'srcip:' + v; }},
  {dim: 'host', part: 'busiest', title: 'The names asked for',
   note: 'What the web filter, the SSL inspection and the DNS filter saw being asked for, '
     + 'by name.',
   term: function (v) { return 'host:' + tQuote(v); }, page: 'web'},
  {dim: 'src', part: 'refused', title: 'Refused, from',
   note: 'The addresses the firewall turned away most - on its own address this is the '
     + 'internet trying the doors. Marked where this program keeps them out already, or a '
     + 'public list names them.', refused: true,
   term: function (v) { return 'srcip:' + v; }},
  {dim: 'port', part: 'refused', title: 'Refused, at which port',
   note: 'What the refused sessions were trying to reach. A port nobody should be asking for '
     + 'is somebody looking.', refused: true,
   term: function (v) {
     var bits = String(v).split('/');
     return 'dstport:' + bits[0] + (bits[1] ? ' proto:' + bits[1] : '') + T_SESSIONS_ONLY;
   }},
  {dim: 'src', part: 'heaviest', title: 'Who moved the most data',
   note: 'The addresses whose sessions carried the most, both ways together.', bytes: true,
   term: function (v) { return 'srcip:' + v + T_SESSIONS_ONLY; }},
  {dim: 'dst', part: 'heaviest', title: 'Where the most data went',
   note: 'The addresses outside that took or gave the most.', bytes: true,
   term: function (v) { return 'dstip:' + v + T_SESSIONS_ONLY; }},
  {dim: 'service', part: 'busiest', title: 'Services',
   note: 'What the sessions were, as the firewall named them.',
   term: function (v) { return 'service:' + tQuote(v) + T_SESSIONS_ONLY; }},
  {dim: 'app', part: 'busiest', title: 'Applications',
   note: 'Where the firewall recognised the application behind a session.',
   term: function (v) { return 'app:' + tQuote(v) + T_SESSIONS_ONLY; }},
  {dim: 'dcc', part: 'busiest', title: 'Countries reached',
   note: 'Where the sessions went, by the firewall’s own country database.', country: true,
   term: function (v) { return 'dstcountry:' + tQuote(v); }},
  {dim: 'scc', part: 'refused', title: 'Countries knocking',
   note: 'Where the refused sessions came from.', country: true, refused: true,
   term: function (v) { return 'srccountry:' + tQuote(v); }},
  {dim: 'policy', part: 'busiest', title: 'Policies',
   note: 'Which of the firewall’s policies decided, and how - on an FTD the access group '
     + 'or the downloadable ACL, with the rule that matched.',
   term: function (v) {
     var first = String(v).split(' ')[0];
     return (/^\d+$/.test(first) ? 'policy:' + first : 'policyname:' + tQuote(v))
       + T_SESSIONS_ONLY;
   }},
  {dim: 'ips', part: 'busiest', title: 'Intrusions (IPS)', first: ['block', 'deny'],
   note: 'What the intrusion policy found, by signature - with how much of it was blocked '
     + 'and how much only detected.',
   term: function (v) {
     var sig = /\[([^\]]+)\]$/.exec(String(v));
     return 'kind:utm/ips' + (sig ? ' signature:' + tQuote(sig[1]) : '');
   }, page: 'threat'},
  {dim: 'malware', part: 'busiest', title: 'Malware', first: ['block', 'deny'],
   note: 'What the file and malware policy (AMP) named as malware, and what was done with it.',
   term: function (v) { return 'malware:' + tQuote(v); }, page: 'threat'},
  {dim: 'file', part: 'busiest', title: 'Files looked at',
   note: 'The files the file policy saw cross, by what the cloud said of them and by type.',
   term: function (v) { return 'file:' + tQuote(v); }, page: 'threat'},
  {dim: 'si', part: 'busiest', title: 'Security Intelligence', first: ['block', 'deny'],
   note: 'Addresses, URLs and names on one of the management centre\u2019s feeds.',
   term: function (v) { return 'si:' + tQuote(v); }, page: 'threat'},
  {dim: 'ssl', part: 'busiest', title: 'SSL decryption',
   note: 'What the decryption policy did with the sessions it touched - decrypted, resigned, '
     + 'blocked - or why it could not.',
   term: function (v) { return 'ssl:' + tQuote(v); }, page: 'web'},
  {dim: 'drop', part: 'busiest', title: 'Dropped on the way, and why', first: ['deny', 'block'],
   note: 'What the firewall dropped that no policy refused: packets of sessions it no longer '
     + 'has (a lot of RST or ACK here is asymmetric routing or a timeout set too short), '
