   term: function (v) { return 'client:' + tQuote(v); }, page: 'cvpn'},
  {dim: 'vpnend', part: 'busiest', words: true, title: 'How VPN sessions ended',
   note: 'Why remote-access sessions ended, out of the line FTD writes at the end of each: '
