   term: function (v) { return 'kind:event/vpn msg~' + tQuote(v); }, page: 'cvpn'},
  {dim: 'vpndrop', part: 'busiest', words: true, title: 'VPN connections dropped',
   note: 'A session carries on through a dropped connection and reconnects - these are the '
