function tHelp() {
  tSuggestClose();
  modal('Searching the firewall’s lines', function (body) {
    body.appendChild(el('p', 'note', 'The box searches every line that is kept, on the '
      + 'server - not the page in front of you. Case never matters. As you type it offers '
