      ex.appendChild(row);
    });
    body.appendChild(ex);
    body.appendChild(el('h3', 't-h3', 'The fields with a column — fast'));
    var grid = el('div', 't-kvgrid');
    T_QFIELDS.forEach(function (f) {
      var row = el('div', 'kv');
      var k = el('span', 'k');
      k.appendChild(el('code', '', f[0]));
      k.appendChild(el('span', 'muted', ' ' + f[1]));
      row.appendChild(k);
      row.appendChild(el('span', 'v muted mono', f[2] || ''));
      grid.appendChild(row);
    });
    body.appendChild(grid);
    var slow = el('div', 't-kvgrid');
    body.appendChild(el('h3', 't-h3', 'Every other field FortiOS writes — read out of '
      + 'each line, slower'));
    body.appendChild(slow);
    tInsideNames().then(function (inside) {
      inside.forEach(function (f) {
        var row = el('div', 'kv');
        var k = el('span', 'k');
        k.appendChild(el('code', '', f.name));
        k.appendChild(el('span', 'muted', ' ' + (FG_FIELDS[f.name] || '')));
        row.appendChild(k);
        row.appendChild(el('span', 'v muted', 'in ' + num(f.n) + ' of the newest 2,000'));
        slow.appendChild(row);
      });
      if (!inside.length) slow.appendChild(el('p', 'muted', 'None seen yet.'));
    }).catch(function () {});
    body.appendChild(el('p', 'note', 'A search that names only fields from inside the '
      + 'lines reads the newest lines one by one for a few seconds and says how far back '
      + 'it got. Put a column field beside it - an address, a port, a kind of line, a '
      + 'verdict - and the database narrows it first, so it reaches much further back.'));
  }, [{words: 'Close', close: true}]);
  explainWhatWasDrawn($('modal-body'));
}
/* ---- one line, read out ---------------------------------------------- */
function showFwLine(ident, ts) {
  modal('One line of the firewall’s log', function (body) {
    body.appendChild(el('p', 'center muted', 'Reading…'));
  }, [{words: 'Close', close: true}]);
  var ticket = modalTicket();
  /* ...with when it is, so the database looks in that day only. */
  api('fw-row&ident=' + encodeURIComponent(ident)
      + (ts ? '&ts=' + encodeURIComponent(ts) : '')).then(function (d) {
    if (!modalStill(ticket)) return;
    drawFwLine(d.row);
  }).catch(function (e) {
    if (!modalStill(ticket)) return;
    var body = $('modal-body');
    clear(body);
    body.appendChild(el('p', 'center bad', String((e && e.message) || e)));
  });
}

/** The line as one sentence: who, to where, what, and what was done. */
function fwSentence(r) {
  var f = r.fields || {};
  var who = r.srcip + (f.srcname ? ' (' + f.srcname + ')' : '');
  var where = (r.host ? r.host + ' at ' : '') + (r.dstip || '') + (r.dstport ? ':' + r.dstport : '');
  if (r.type === 'event') {
    if (f.auditscore !== undefined) {
      return 'Security Rating' + (f.auditreporttype ? ' (' + f.auditreporttype + ')' : '')
        + ': score ' + f.auditscore + ' \u2014 ' + (f.criticalcount || 0) + ' critical, '
        + (f.highcount || 0) + ' high, ' + (f.mediumcount || 0) + ' medium, '
        + (f.lowcount || 0) + ' low, ' + (f.passedcount || 0) + ' passed.';
    }
    if (f.stitch) {
      return 'The automation \u201c' + f.stitch + '\u201d ran'
        + (f.stitchaction ? ': ' + f.stitchaction : '') + '.';
    }
    var what = FG_ACTIONS[r.action] || f.logdesc || r.msg || r.action
      || 'the firewall said something';
    var why = f.reason && f.reason !== 'none' ? f.reason
      : (f.error_num || (f.status && !/^(success|logon|logout|enable)$/.test(f.status)
        ? f.status : ''));
    return what + (f.logdesc && FG_ACTIONS[r.action] ? ' (' + f.logdesc + ')' : '')
      + (r.user ? ' \u2014 ' + r.user : '') + (f.group && f.group !== 'N/A' ? ' in ' + f.group : '')
      + (r.srcip ? ', from ' + r.srcip : '') + (f.vpntunnel ? ', tunnel ' + f.vpntunnel : '')
      + (why ? ': ' + why : '') + '.';
  }
  var did = FG_ACTIONS[r.action] || r.action || '';
  return who + ' → ' + where + (tServiceOf(r) ? ' (' + tServiceOf(r) + ')' : '') + ': ' + did
    + (r.policy ? ', by policy ' + r.policy + (r.policyname ? ' “' + r.policyname + '”' : '') : '')
    + '.';
}

function fwSide(title, r, side) {
  var f = r.fields || {};
  var p = side === 'src' ? 'src' : 'dst';
  var box = el('div', 't-side');
  box.appendChild(el('div', 't-side-h', title));
  var ip = r[p + 'ip'];
  var big = el('div', 't-side-ip mono', ip || '–');
  if (r[p + 'port']) big.appendChild(el('span', 'muted', ':' + r[p + 'port']));
  box.appendChild(big);
  if (side === 'dst' && r.host) box.appendChild(el('div', 'mono t-host', r.host));
  var about = (r.about || {})[ip] || {};
  var line = el('div', 't-side-tags');
  if (about.private) line.appendChild(el('span', 'tag dim', 'private \u2014 one of your own'));
  else line.appendChild(fgCountry(r[p + 'country'], about.cc));
  if (about.banned) {
    var b = el('span', 'tag crit', 'kept out here');
    explain(b, 'This program keeps this address out.');
    line.appendChild(b);
  }
  (about.feeds || []).forEach(function (feed) {
    line.appendChild(el('span', 'tag warn', feed));
  });
  box.appendChild(line);
  var facts = [
    r[p + 'intf'] ? [p === 'src' ? 'In on' : 'Out on', r[p + 'intf']
      + (f[p + 'intfrole'] ? ' (' + f[p + 'intfrole'] + ')' : '')] : null,
    f[p + 'mac'] ? ['MAC', f[p + 'mac'] + (f[p + 'hwvendor'] || f[p === 'src' ? 'srchwvendor' : 'dsthwvendor']
      ? ' · ' + (f[p + 'hwvendor'] || '') : '')] : null,
    (p === 'src' && f.devtype) ? ['Device', f.devtype + (f.osname ? ', ' + f.osname : '')]
      : ((p === 'dst' && f.dstdevtype) ? ['Device', f.dstdevtype] : null),
    (p === 'src' && f.srcname) ? ['Calls itself', f.srcname] : null,
    (p === 'src' && r.user) ? ['Person', r.user] : null
  ];
  if (about.day) {
    var said = T_ORDER.filter(function (v) { return about.day[v]; }).map(function (v) {
      return T_VERDICTS[v].words + ' ' + num(about.day[v].n);
    }).join(' · ');
    facts.push(['Last 24 h', said]);
  }
  box.appendChild(peekFacts(facts));
  if (ip && /^[0-9a-f:.]+$/i.test(ip)) {
    var row = el('div', 't-side-buttons');
    var look = cmdButton('Everything about it', 'search', 'small');
    look.onclick = function () { lookUp(ip); };
    row.appendChild(look);
    var only = cmdButton(p === 'src' ? 'Lines from here' : 'Lines to here', 'list', 'small');
    only.onclick = function () {
      closeAllModals();
      showTab('traffic');
      tOpen((p === 'src' ? 'srcip:' : 'dstip:') + ip, TPAGE === 'over' ? 'all' : TPAGE);
    };
    row.appendChild(only);
    box.appendChild(row);
  }
  return box;
}

/** A field of the popup that finds every other line with the same value. */
function tFieldFinds(node, key, value) {
  if (value === undefined || value === null || value === '') return;
  var term = key + ':' + tQuote(value);
  opensWith(node, 'Every line where <code>' + term + '</code> \u2014 press to '
    + 'search for it.', function () {
      tSearchFor(key, value, TPAGE === 'over' ? (/^(hostname|url|catdesc|category)$/.test(key)
        ? 'web' : 'list') : null);
    });
}

/* Which fields belong to which part of the story, in the order a person
