var FG_GROUPS = [
  ['What was decided', ['action', 'utmaction', 'policyid', 'policyname', 'policytype',
    'poluuid', 'profile', 'msg', 'logdesc', 'eventtype', 'eventsubtype', 'reason', 'status',
    'crscore', 'crlevel', 'craction']],
  ['What it was', ['service', 'proto', 'app', 'appcat', 'hostname', 'url', 'referralurl',
    'catdesc', 'cat',
    'httpmethod', 'agent', 'reqtype', 'direction', 'ratemethod', 'sni', 'tlsver', 'cipher',
    'authalgo', 'kxproto', 'connectionstate', 'connectionmark', 'packetmark', 'routingmark',
    'flags', 'len']],
  ['How much', ['duration', 'sentbyte', 'rcvdbyte', 'sentpkt', 'rcvdpkt', 'sentdelta',
