  ['Automation', ['stitch', 'trigger', 'stitchaction', 'from']],
  ['The administrator', ['ui', 'script', 'method', 'cfgpath', 'cfgobj', 'cfgattr', 'cfgtid', 'act',
    'saddr', 'daddr', 'dintf', 'iptype']],
  ['The firewall', ['devname', 'logid', 'type', 'subtype', 'level', 'sessionid', 'vd']]
];

function fwValueWords(key, value, r) {
  if (key === 'sentbyte' || key === 'rcvdbyte' || key === 'sentdelta' || key === 'rcvddelta') {
    return bytes(value) + ' (' + num(value) + ')';
  }
  if (key === 'duration') return span(value);
  if (key === 'proto') return (IP_NAMES[value] || value) + ' (' + value + ')';
  if (key === 'action') return FG_ACTIONS[value] ? value + ' — ' + FG_ACTIONS[value] : String(value);
  if (key === 'audittime' && Number(value) > 1e9) return stamp(Number(value));
  if (key === 'sysuptime') return span(value);
  return String(value);
}
var IP_NAMES = {1: 'ICMP', 2: 'IGMP', 6: 'TCP', 17: 'UDP', 41: 'IPv6', 47: 'GRE', 50: 'ESP',
                51: 'AH', 58: 'ICMPv6', 89: 'OSPF', 112: 'VRRP', 132: 'SCTP'};

/* The fields of a line that are an address with a port. */
var T_END_FIELDS = {natsrc: 1, natdst: 1, natto: 1};
function drawFwLine(r) {
  /* Every field in one place: the columns and the packed rest, by FortiOS's
     own names, so the table at the end is the line exactly as written. */
  var all = {};
  Object.keys(r.fields || {}).forEach(function (k) { all[k] = r.fields[k]; });
  var cols = {srcip: r.srcip, srcport: r.srcport, srcintf: r.srcintf,
              srccountry: r.srccountry, dstip: r.dstip, dstport: r.dstport,
              dstintf: r.dstintf, dstcountry: r.dstcountry, proto: r.proto,
              service: r.service, app: r.app, policyid: r.policy, policyname: r.policyname,
              action: r.action, type: r.type, subtype: r.sub, level: r.level,
              sentbyte: r.sent, rcvdbyte: r.rcvd, duration: r.duration, sessionid: r.session,
              user: r.user, hostname: r.host, url: r.url, catdesc: r.cat, msg: r.msg,
              devname: r.dev};
  Object.keys(cols).forEach(function (k) {
    var v = cols[k];
    if (v === '' || v === null || v === undefined) return;
    /* A nought in a column the line never wrote - a DNS answer has no
       duration, an event no port - is not something it said. */
    /* ...nor on a MikroTik's line of whatever kind (1.10.207): it writes a
       packet, never a policy number, a session, its bytes or how long. */
    if ((k === 'srcport' || k === 'dstport' || k === 'policyid' || k === 'sessionid'
         || k === 'proto' || k === 'sentbyte' || k === 'rcvdbyte' || k === 'duration')
        && !Number(v) && !(k in (r.fields || {}))
        && (r.type !== 'traffic' || 'topics' in (r.fields || {}))) return;
    if (!(k in all)) all[k] = v;
  });
  /* A DHCP lease says which address went to which machine, and what it was
     called: not an address a session went to, nor a name it asked for. */
  if (r.type === 'event' && r.sub === 'dhcp') {
    if (r.dstip) all.leased = r.dstip;
    if (all.hostname) { all.leasename = all.hostname; delete all.hostname; }
    if (all.mac) all.leasemac = all.mac;
  }
  /* Said in the page's language before it is made a title (1.10.207). */
  var title = qShown((T_VERDICTS[r.verdict] || T_VERDICTS.info).words).replace(/^./, function (c) {
    return c.toUpperCase();
  }) + ' · ' + stamp(r.ts);
  var buttons = [{words: 'Close', close: true}];
  if (r.session) {
    buttons.unshift({words: 'This session in the list', icon: 'list', close: true, go: function () {
      showTab('traffic');
      tOpen('session:' + r.session, 'list');
    }});
  }
  modal(title, function (body) {
    var head = el('div', 't-head');
    head.appendChild(tVerdictTag(r.verdict));
    head.appendChild(el('span', 't-sentence', fwSentence(r)));
    body.appendChild(head);
    if (r.type !== 'event' || r.srcip) {
      var flow = el('div', 't-flow');
      flow.appendChild(fwSide(r.type === 'event' ? 'Who' : 'From', r, 'src'));
      if (r.type !== 'event') {
        var mid = el('div', 't-fw');
        mid.appendChild(el('div', 't-fw-name', r.dev || 'the firewall'));
        var pol = r.policy ? 'policy ' + r.policy : (r.sub === 'local' ? 'local-in' : '');
        if (pol) mid.appendChild(el('div', 'muted', pol));
        if (r.policyname) mid.appendChild(noI18n(el('div', 't-fw-pol', r.policyname)));
        var tag = tVerdictTag(r.verdict);
        mid.appendChild(tag);
        if ((r.fields || {}).transip) {
          mid.appendChild(el('div', 'muted mono', 'as ' + r.fields.transip
