      var facts = [['Last VPN sign-in', stamp(r.ise.ts) + (r.ise.ip ? ', from ' + r.ise.ip : '')]];
      if (r.ise.groups) facts.push(['Groups', r.ise.groups]);
      if (r.ise.profile) facts.push(['Authorisation profile', r.ise.profile]);
      if (r.ise.policy) facts.push(['Policy set', r.ise.policy]);
      if (r.ise.acl) facts.push(['Downloadable ACL', r.ise.acl
        + (r.ise.acl === r.policyname ? ' \u2014 the one this line was refused by' : '')]);
      if (r.ise.client) facts.push(['Address inside the VPN', r.ise.client]);
      if (r.ise.failed_day) facts.push(['Failed attempts, last 24 h', num(r.ise.failed_day)]);
      facts.forEach(function (one) {
        var line = el('div', 'kv');
        line.appendChild(el('span', 'k', one[0]));
        line.appendChild(el('span', 'v', one[1]));
        ise.appendChild(line);
