      var pairs = [];
      g[1].forEach(function (k) {
        if (!(k in all) || all[k] === '' || all[k] === 'N/A') return;
        shown[k] = 1;
        pairs.push([FG_FIELDS[k] ? FG_FIELDS[k].replace(/^./, function (c) {
          return c.toUpperCase(); }) : k, fwValueWords(k, all[k], r), k]);
      });
