       means beside it. Nothing the firewall wrote is left out. */
    var keys = Object.keys(all).filter(function (k) {
      return k !== 'leased' && k !== 'leasemac';     /* copies, put there to be shown */
    }).sort();
    var det = el('details', 't-all');
    det.appendChild(el('summary', '', 'Every field the firewall wrote (' + keys.length + ')'));
    var table = el('table', 'plain tight');
    var tb = el('tbody');
    keys.forEach(function (k) {
