/* ==========================================================================
   The ban list, published for other firewalls
   --------------------------------------------------------------------------
   The switch, the format and the rest are ordinary settings above. What is
   drawn here is what they add up to: the URL a firewall is given, who has
   been fetching it, and how to set each kind of firewall up. The URL follows
   the format chosen in the drop-down at once, before it is saved, so what is
   copied is always the URL for what is on the screen.
   ========================================================================== */
var BANFEED = null;

function loadBanfeed() {
  api('banfeed-state').then(function (d) { BANFEED = d; drawBanfeed(); })
    .catch(function () { /* the card says nothing rather than something wrong */ });
}

/** A setting as it stands on the screen: changed and not saved yet, or saved. */
function banfeedWant(key) {
  if (key in DIRTY) return DIRTY[key];
  var s = settingByKey(key);
  return s ? s.value : undefined;
}

function banfeedBase() {
  return location.origin + location.pathname.replace(/[^\/]*$/, '') + 'banfeed.php';
}

/** How the saved settings have a firewall prove it may fetch the list:
    none, a key in the URL, or a user name and a password. */
function banfeedAuth() { return String((BANFEED && BANFEED.auth) || 'none'); }
function banfeedSecret() { return banfeedAuth() === 'key'; }

function banfeedUrl(md5) {
  if (!BANFEED) return '';
  if (banfeedSecret() && !BANFEED.key) return '';
  var fmt = String(banfeedWant('banfeed_format') || 'ftd');
  var family = String(banfeedWant('banfeed_family') || 'both');
  return banfeedBase() + '?f=' + encodeURIComponent(fmt)
    + (family !== 'both' ? '&family=' + encodeURIComponent(family) : '')
    + (md5 ? '&md5=1' : '')
    + (banfeedSecret() ? '&k=' + encodeURIComponent(BANFEED.key) : '');
}

/** Text that goes into a guide's HTML, made safe to go there. */
function htmlText(text) {
  return String(text == null ? '' : text).replace(/&/g, '&amp;').replace(/</g, '&lt;')
    .replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
}

function banfeedWords(fmt) {
  var hit = ((BANFEED && BANFEED.formats) || []).filter(function (f) { return f.key === fmt; })[0];
  return hit ? hit.words : fmt;
}

/** Text onto the clipboard - over HTTPS the modern way, and over plain HTTP,
    where a browser keeps navigator.clipboard away, the old one. */
function copyText(text, said) {
  function old() {
    var box = el('textarea');
    box.value = text;
    box.setAttribute('readonly', '');
    box.style.cssText = 'position:fixed;top:-1000px;left:-1000px;opacity:0';
    document.body.appendChild(box);
    box.select();
    var ok = false;
    try { ok = document.execCommand('copy'); } catch (e) { ok = false; }
    document.body.removeChild(box);
    if (ok) toast(said, 'good');
    else toast('the browser refused the clipboard; select the text and copy it by hand', 'bad');
  }
  if (navigator.clipboard && window.isSecureContext) {
    navigator.clipboard.writeText(text).then(function () { toast(said, 'good'); }, old);
  } else {
    old();
  }
}

function drawBanfeed() {
  if (!$('banfeed-box')) return;
  var d = BANFEED;
  var savedOn = !!(d && d.on);
  var on = String(banfeedWant('banfeed')) === '1' || banfeedWant('banfeed') === true;
  var fmt = String(banfeedWant('banfeed_format') || 'ftd');
  $('banfeed-count').textContent = d
    ? (d.blacklist ? d.count + ' address(es) in it now' : 'the blacklist is off: it is empty')
    : '';
  $('banfeed-off').hidden = savedOn && on;
  $('banfeed-off').textContent = !on
    ? 'Switch it on above and save, and the URL appears here.'
    : 'Save the settings, and the URL appears here.';
  /* Open, the URL is nothing secret and everybody who may look at this page
     is shown it; with a key in it, only an administrator is. */
  var showUrl = savedOn && on && !!banfeedUrl(false);
  $('banfeed-on').hidden = !(savedOn && on);
  $('banfeed-readonly').hidden = showUrl || !(savedOn && on);
  $('banfeed-for').textContent = banfeedWords(fmt);
  $('banfeed-url').hidden = !showUrl;
  $('banfeed-url').textContent = showUrl ? banfeedUrl(false) : '';
  $('banfeed-md5-wrap').hidden = !(showUrl && fmt === 'ftd');
  $('banfeed-md5').textContent = showUrl && fmt === 'ftd' ? banfeedUrl(true) : '';
  $('banfeed-copy').hidden = !showUrl;
  $('banfeed-open').hidden = !showUrl;
  $('banfeed-newkey').hidden = !(ADMIN && savedOn && on && banfeedSecret());
  var basic = banfeedAuth() === 'basic';
  $('banfeed-basic-row').hidden = !basic;
  if (basic) {
    $('banfeed-basic').textContent = (d.user || '?') + ' \u00b7 '
      + (d.password_set ? 'with the password saved above, by HTTP basic authentication'
         : 'no password is saved yet');
  }
  var seen = (d && d.fetched) || [];
  var box = $('banfeed-seen');
  clear(box);
  if (!seen.length) {
    box.textContent = 'nobody yet';
  } else {
    seen.slice(0, 6).forEach(function (one) {
      var line = el('span', 'd', '');
      line.style.color = 'var(--tx)';
      line.textContent = one.from + ' · ' + ago(one.at) + ' · '
        + one.n + ' fetch(es) · ' + (one.md5 ? one.format + ', MD5' : one.format)
        + ' · ' + one.count + ' address(es)';
      box.appendChild(line);
    });
  }
  var no = d && d.refused;
  $('banfeed-refused-row').hidden = !no;
  if (no) {
    var last = d.refused_last || {};
    $('banfeed-refused').textContent = no + ' since the daemon started'
      + (last.from ? ', the last from ' + last.from + ' ' + ago(last.at) + ' (' + last.why + ')'
         : '');
  }
}

$('banfeed-url').onclick = function () {
  copyText(banfeedUrl(false), 'the URL is on the clipboard');
};
$('banfeed-md5').onclick = function () {
  copyText(banfeedUrl(true), 'the MD5 URL is on the clipboard');
};
$('banfeed-copy').onclick = function () {
  copyText(banfeedUrl(false), 'the URL is on the clipboard');
};
$('banfeed-open').onclick = function () {
  /* Shown here, not by opening the URL: with a password asked for, that
     would be the browser's own sign-in box rather than this page. */
  var fmt = String(banfeedWant('banfeed_format') || 'ftd');
  var family = String(banfeedWant('banfeed_family') || 'both');
  var ticket;
  modal('What the firewall gets: ' + banfeedWords(fmt), function (body) {
    ticket = modalTicket();
    body.appendChild(el('p', 'note', 'Asking the daemon\u2026'));
  }, [{words: 'Close', close: true}]);
  api('banfeed-preview&format=' + encodeURIComponent(fmt) + '&family='
      + encodeURIComponent(family)).then(function (d) {
    if (!modalStill(ticket)) return;
    var body = $('modal-body');
    clear(body);
    body.appendChild(el('p', 'note', d.count + ' address(es) \u00b7 MD5 ' + d.md5
      + (d.cut ? ' \u00b7 only the start of it is shown' : '')));
    body.appendChild(el('pre', 'wrap mono', d.body || '(empty: nothing is being kept out)'));
  }).catch(function (e) {
    if (!modalStill(ticket)) return;
    clear($('modal-body'));
    $('modal-body').appendChild(el('p', 'note', String(e && e.message || e)));
  });
};
$('banfeed-newkey').onclick = function () {
  confirmThen('A new key for the published list',
    'The URL changes, and <b>every firewall still fetching the old one is refused from this '
    + 'moment</b> until it is given the new one. It is what to do when the URL has been seen by '
    + 'somebody who should not have it.',
    'Make a new key', function () {
      api('banfeed-key', {}).then(function (d) {
        BANFEED = d;
        drawBanfeed();
        toast('a new key: the URL has changed', 'good');
      }).catch(oops);
    });
};
$('banfeed-forget').onclick = function () {
  confirmThen('Forget who fetched the list',
    'The lines under <b>Fetched by</b> - each address, when it last fetched and how many '
    + 'times - and the count of refusals start again from nothing. <b>Nothing changes for '
    + 'the firewalls</b>: the list, its URL and who may fetch it stay exactly as they are, and '
    + 'the next fetch from each is written down as its first.',
    'Clear them', function () {
      api('banfeed-forget', {}).then(function (d) {
        BANFEED = d;
        drawBanfeed();
        toast('who fetched the list was forgotten', 'good');
      }).catch(oops);
    });
};
$('banfeed-guide').onclick = function () { banfeedGuide(); };

/* ---- the guide -------------------------------------------------------- */

/** One step of a guide: a heading, some words, and perhaps a block to copy. */
function guideStep(body, n, title, html, code) {
  var box = el('div', 'guide-step');
  var head = el('div', 'guide-head');
  head.appendChild(el('span', 'guide-n', String(n)));
  head.appendChild(el('span', '', title));
  box.appendChild(head);
  if (html) {
    var p = el('div', 'guide-words');
    p.innerHTML = html;
    box.appendChild(p);
  }
  if (code) box.appendChild(guideCode(code));
  body.appendChild(box);
}

function guideCode(code) {
  var wrap = el('div', 'guide-code');
  var pre = el('pre', 'wrap mono', code);
  wrap.appendChild(pre);
  var b = cmdButton('Copy', 'copy', 'small');
  b.onclick = function () { copyText(code, 'on the clipboard'); };
  wrap.appendChild(b);
  return wrap;
}

function guideNote(body, html, kind) {
  var p = el('div', 'guide-note' + (kind ? ' ' + kind : ''));
  p.innerHTML = html;
  body.appendChild(p);
}

function banfeedGuide() {
  var fmt = String(banfeedWant('banfeed_format') || 'ftd');
  var secret = banfeedSecret();
  var real = !!(BANFEED && BANFEED.on && banfeedUrl(false));
  /* ...with the family chosen, as the real URL has it (1.10.192). */
  var fam = String(banfeedWant('banfeed_family') || 'both');
  var famArg = fam !== 'both' ? '&family=' + encodeURIComponent(fam) : '';
  var url = real ? banfeedUrl(false)
    : banfeedBase() + '?f=' + fmt + famArg + (secret ? '&k=KEY' : '');
  var md5 = real ? banfeedUrl(true)
    : banfeedBase() + '?f=' + fmt + famArg + '&md5=1' + (secret ? '&k=KEY' : '');
  var bare = banfeedBase();
  var key = secret ? ((BANFEED && BANFEED.key) || 'KEY') : '';
  var auth = banfeedAuth();
  var user = (BANFEED && BANFEED.user) || 'isemon';
  var host = location.hostname;
  var temporary = String(banfeedWant('banfeed_temporary')) === '1'
    || banfeedWant('banfeed_temporary') === true;
  var guides = {ftd: guideFtd, fortigate: guideFortigate, opnsense: guideOpnsenseFeed,
                pfsense: guidePfsenseFeed, plain: guideScript, json: guideScript};
  modal('Setting it up: ' + banfeedWords(fmt), function (body) {
    body.classList.add('guide');
    if (!real) {
      guideNote(body, !(BANFEED && BANFEED.on)
        ? 'Switch the list on and save first: until then the URL below answers nothing.'
        : 'Only an administrator is shown the key; <b>KEY</b> below stands for it.',
        'warn');
    }
    (guides[fmt] || guideScript)(body, {url: url, md5: md5, bare: bare, key: key, host: host,
                                        fmt: fmt, temporary: temporary, auth: auth,
                                        user: user});
  }, [{words: 'Close', close: true}]);
}

function guideFtd(body, g) {
  guideNote(body, 'The <b>FMC</b> fetches the list, not the FTD: it downloads it and hands it to '
    + 'every FTD whose access control policy uses it. An FTD managed by <b>FDM</b> (without an '
    + 'FMC) cannot use a feed of its own; cdFMC in Security Cloud Control can.');
  if (g.auth === 'basic') {
    guideNote(body, '<b>The FMC cannot send a user name and a password for a feed</b> \u2014 the '
      + 'feed has a URL and an MD5 URL and nothing else. With <i>User name and password</i> '
      + 'chosen above it is refused. For an FTD choose <i>A key in the URL</i> (or nothing); '
      + 'the steps below are written for the URL as it will then be.', 'warn');
  } else if (g.auth === 'key') {
    guideNote(body, 'The URL carries the key: whoever has it can read the list, so it goes '
      + 'into the FMC and nowhere else. <b>New key</b> on the settings page changes it, after '
      + 'which the FMC has to be given the new URL.');
  }
  guideStep(body, 1, 'Let the FMC reach this server',
    'The FMC fetches from <span class="mono">' + htmlText(g.host) + '</span> over HTTPS (TCP 443). Its '
    + 'address has to be on the web server’s allow list, and under <i>Only these may fetch '
    + 'it</i> above if that is filled in. Try it from the FMC’s own shell (expert mode):',
    'curl -sS \'' + g.url + '\' | head');
  guideStep(body, 2, 'Add the feed',
    'In the FMC: <b>Objects → Object Management → Security Intelligence → '
    + 'Network Lists and Feeds → Add Network Lists and Feeds</b>.'
    + '<ul><li><b>Name:</b> <span class="mono">isemon-bans</span></li>'
    + '<li><b>Type:</b> Feed</li>'
    + '<li><b>Feed URL:</b> the URL on the settings page</li>'
    + '<li><b>MD5 URL:</b> the MD5 URL beside it — the FMC asks it first and downloads the '
    + 'list only when it has changed. It insists on one when the list is fetched more often '
    + 'than once an hour.</li>'
    + '<li><b>Update Frequency:</b> ' + (g.temporary ? '5 or 15 minutes: the list carries bans '
      + 'on a clock, the shortest of them ten minutes long' : '30 minutes or an hour is plenty: '
      + 'only bans for good are in it') + '</li></ul>'
    + 'Save. The FMC fetches it at once; <b>Update Feeds</b> on the same page fetches it again '
    + 'by hand.');
  guideNote(body, 'The two to paste, each with its own button:', '');
  body.appendChild(guideCode(g.url));
  body.appendChild(guideCode(g.md5));
  guideStep(body, 3, 'Block it in the access control policy',
    '<b>Policies → Access Control</b> → the policy on the FTD → the <b>Security '
    + 'Intelligence</b> tab. Under <b>Networks</b> pick <span class="mono">isemon-bans</span>, '
    + 'the zone <i>Any</i>, and <b>Add to Block List</b>. The logging switch beside the block '
    + 'list writes a Security Intelligence event for every connection it stops.');
  guideStep(body, 4, 'Save and deploy',
    '<b>Deploy → Deployment</b> for the FTDs using that policy. From then on the FMC '
    + 'updates the list by itself and pushes it without another deployment.');
  guideStep(body, 5, 'Check that it works',
    'The FMC appears under <i>Fetched by</i> on the settings page within a minute. '
    + '<b>Analysis → Connections → Security Intelligence Events</b> shows what the '
    + 'list has stopped.');
  guideNote(body, '<b>The remote-access VPN itself is not covered by this.</b> Security '
    + 'Intelligence filters traffic passing <i>through</i> the FTD; a VPN session is traffic '
    + 'to the FTD itself and is handled before it. Against password spraying on the VPN '
    + 'portal, Cisco’s own answers are the threat detection for remote access VPN in '
    + 'newer FTD releases and a control-plane access list (FlexConfig), which cannot read a '
    + 'feed. The list here stops the same addresses from reaching anything behind the FTD.',
    'warn');
}

function guideFortigate(body, g) {
  guideNote(body, 'The FortiGate fetches the list itself, as an <b>external threat feed</b> of IP '
    + 'addresses, and every policy that names the feed follows it without anything being '
    + 'installed again.');
  guideStep(body, 1, 'Let the FortiGate reach this server',
    'It fetches from <span class="mono">' + htmlText(g.host) + '</span> over HTTPS (TCP 443), from its '
    + 'own address on the way here. That address has to be on the web server’s allow list, '
    + 'and under <i>Only these may fetch it</i> above if that is filled in. The FortiGate has to '
    + 'resolve the name as well.');
  var basic = g.auth === 'basic';
  guideStep(body, 2, 'Add the feed \u2014 in the GUI',
    '<b>Security Fabric \u2192 External Connectors \u2192 Create New \u2192 Threat Feeds: IP '
    + 'Address</b>.'
    + '<ul><li><b>Name:</b> <span class="mono">isemon-bans</span></li>'
    + '<li><b>URI of external resource:</b> ' + (basic
      ? '<span class="mono">' + htmlText(g.bare) + '</span> \u2014 nothing after it; the list '
        + 'comes in the format saved on the settings page'
      : 'the URL on the settings page') + '</li>'
    + (basic ? '<li><b>HTTP basic authentication:</b> on \u2014 <b>Username</b> '
      + '<span class="mono">' + htmlText(g.user) + '</span>, <b>Password</b> the one saved '
      + 'under <i>The password</i> on the settings page</li>' : '')
    + '<li><b>Refresh rate:</b> ' + (g.temporary ? '5 minutes' : '30 minutes') + '</li></ul>'
    + 'OK, then open it again and press <b>View Entries</b>: the addresses from this list are '
    + 'there.');
  var cli = 'config system external-resource\n'
    + '    edit "isemon-bans"\n'
    + '        set type address\n'
    + '        set resource "' + (g.auth === 'key' ? g.url : g.bare) + '"\n'
    + (basic ? '        set username "' + g.user + '"\n        set password PASSWORD\n' : '')
    + '        set refresh-rate ' + (g.temporary ? '5' : '30') + '\n'
    + '    next\n'
    + 'end';
  guideStep(body, 2, '\u2026or on the command line',
    (g.auth === 'key'
      ? 'The URL carries the key after a <span class="mono">?</span>, and the FortiOS command '
        + 'line takes a <span class="mono">?</span> as a call for help: type it as '
        + '<b>Ctrl+V</b> and then <b>?</b>, or paste the URL in the GUI instead.'
      : 'The address without anything after it: the FortiOS command line takes a '
        + '<span class="mono">?</span> as a call for help, and without a format in the URL '
        + 'the list comes in the format saved on the settings page \u2014 which is this one.')
    + (basic ? ' <span class="mono">PASSWORD</span> is the one saved on the settings page.' : ''),
    cli);
  if (g.auth === 'none') {
    guideNote(body, 'The URL is open. If it should not be, choose <i>User name and password</i> '
      + 'under <i>How the firewall proves it may fetch it</i>: the FortiGate sends them with '
      + 'every fetch, and the key never appears in a URL or a web server\u2019s log.');
  }
  guideStep(body, 3, 'Keep the addresses away from the SSL VPN and the FortiGate itself',
    'A <b>local-in policy</b> is what stands in front of the FortiGate’s own services, the '
    + 'SSL VPN portal and the IPsec gateway among them. <span class="mono">wan1</span> is the '
    + 'interface facing the internet; put yours.',
    'config firewall local-in-policy\n'
    + '    edit 0\n'
    + '        set intf "wan1"\n'
    + '        set srcaddr "isemon-bans"\n'
    + '        set dstaddr "all"\n'
    + '        set action deny\n'
    + '        set service "ALL"\n'
    + '        set schedule "always"\n'
    + '    next\n'
    + 'end');
  guideNote(body, 'On a version whose local-in policy does not reach the SSL VPN, the SSL VPN '
    + 'settings can refuse the feed’s addresses by themselves:', '');
  body.appendChild(guideCode('config vpn ssl settings\n'
    + '    set source-interface "wan1"\n'
    + '    set source-address "isemon-bans"\n'
    + '    set source-address-negate enable\n'
    + 'end'));
  guideStep(body, 4, 'And from everything behind it',
    'In an ordinary firewall policy from the internet side, put <span class="mono">'
    + 'isemon-bans</span> as the source of a <b>deny</b> policy at the top, or as a negated '
    + 'source of the policies that let traffic in.');
  guideStep(body, 5, 'Check that it works',
    'The FortiGate appears under <i>Fetched by</i> on the settings page within a minute of the '
    + 'refresh rate. On the FortiGate:',
    'diagnose sys external-resource stats\n'
    + 'diagnose sys external-address-resource list isemon-bans');
  guideNote(body, 'Test the local-in policy with an address of your own before relying on it: '
    + 'what it covers has changed between FortiOS releases. Each FortiGate model also has a '
    + 'ceiling on how many entries a threat feed may hold.', 'warn');
}

/* 1.10.190: the list fetched by an OPNsense or a pfSense. A pfSense cannot
   send a user name and a password with a URL alias (nor an older OPNsense),
   so the key in the URL (or the addresses allowed to fetch) is what keeps
   it to them; a recent OPNsense can, and its guide says how (1.10.191). */
function guideFeedAuth(body, g, who) {
  if (g.auth === 'basic') {
    guideNote(body, '<b>' + who + ' does not send a user name and a password when it fetches a '
      + 'URL alias.</b> With <i>User name and password</i> chosen above it is refused. Choose '
      + '<i>A key in the URL</i> (or nothing, with <i>Only these may fetch it</i> filled in); the '
      + 'steps below are written for the URL as it will then be.', 'warn');
  } else if (g.auth === 'key') {
    guideNote(body, 'The URL carries the key: whoever has it can read the list, so it goes '
      + 'into the alias and nowhere else. <b>New key</b> on the settings page changes it, after '
      + 'which the alias has to be given the new URL.');
  }
}

function guideOpnsenseFeed(body, g) {
  guideNote(body, 'The OPNsense fetches the list itself into an alias of the type <b>URL Table '
    + '(IPs)</b>, and every rule that names the alias follows it. It fetches at most once an '
    + 'hour: for bans of ten minutes, <b>Settings → Firewall</b> can instead write each ban '
    + 'to the OPNsense the moment it is made, through its API or over ssh.');
  /* An OPNsense of a recent release sends a user name and a password with a
     URL alias, as a FortiGate does (1.10.191); an older one shows no such
     fields, and then the key in the URL is the way. */
  var basic = g.auth === 'basic';
  if (basic) {
    guideNote(body, 'A recent OPNsense can sign in when it fetches a URL alias: the alias has '
      + 'an <b>authentication type</b> with a user name and a password. Choose <b>Basic</b> '
      + 'there and give it the user name and the password saved on the settings page. An older '
      + 'release that shows no such fields cannot: choose <i>A key in the URL</i> above for it '
      + 'instead.');
  } else {
    guideFeedAuth(body, g, 'OPNsense');
  }
  guideStep(body, 1, 'Let the OPNsense reach this server',
    'It fetches from <span class="mono">' + htmlText(g.host) + '</span> over HTTPS (TCP 443). Its '
    + 'address has to be on the web server’s allow list, and under <i>Only these may fetch '
    + 'it</i> above if that is filled in. Try it from its shell (option 8 on the console):',
    'curl -sS ' + (basic ? '-u \'' + g.user + ':PASSWORD\' ' : '') + '\'' + g.url + '\' | head');
  guideStep(body, 2, 'Make the alias',
    '<b>Firewall → Aliases → +</b>'
    + '<ul><li><b>Name:</b> <span class="mono">isemon_ban</span></li>'
    + '<li><b>Type:</b> URL Table (IPs)</li>'
    + '<li><b>Refresh Frequency:</b> ' + (g.temporary ? 'one hour, the shortest it takes'
      : 'a few hours: only bans for good are in it') + '</li>'
    + '<li><b>Content:</b> the URL below</li>'
    + (basic ? '<li><b>Authentication:</b> Basic \u2014 <b>user name</b> <span class="mono">'
      + htmlText(g.user) + '</span>, <b>password</b> the one saved under <i>The password</i> '
      + 'on the settings page</li>' : '')
    + '</ul>Save, then <b>Apply</b>.', g.url);
  guideStep(body, 3, 'Block it',
    '<b>Firewall → Rules → WAN</b> (and every other interface facing the internet): '
    + 'a rule at the top with <b>Action</b> Block, <b>Source</b> <span class="mono">isemon_ban'
    + '</span>, <b>Destination</b> any, the direction <i>in</i>. Save and <b>Apply changes</b>. '
    + 'A rule on WAN stands in front of the OPNsense’s own services as well, its VPNs '
    + 'among them.');
  guideStep(body, 4, 'Check that it works',
    'The OPNsense appears under <i>Fetched by</i> on the settings page. On the OPNsense, '
    + '<b>Firewall → Diagnostics → Aliases</b> shows what the alias holds; from its '
    + 'shell:', 'pfctl -t isemon_ban -T show | head');
  guideNote(body, 'A large list needs room: <b>Firewall → Settings → Advanced → '
    + 'Firewall Maximum Table Entries</b>.', '');
}

function guidePfsenseFeed(body, g) {
  guideNote(body, 'A pfSense fetches the list itself into an alias of the type <b>URL Table '
    + '(IPs)</b>. It looks at such aliases <b>once a day</b>, which is right only for the bans '
    + 'for good; the <b>pfBlockerNG</b> package fetches as often as every hour. For bans of ten '
    + 'minutes, <b>Settings → Firewall</b> can instead write each ban to the pfSense the '
    + 'moment it is made, through the REST API package or over ssh.', g.temporary ? 'warn' : '');
  guideFeedAuth(body, g, 'pfSense');
  guideStep(body, 1, 'Let the pfSense reach this server',
    'It fetches from <span class="mono">' + htmlText(g.host) + '</span> over HTTPS (TCP 443). Its '
    + 'address has to be on the web server’s allow list, and under <i>Only these may fetch '
    + 'it</i> above if that is filled in. From <b>Diagnostics → Command Prompt</b>:',
    'curl -sS \'' + g.url + '\' | head');
  guideStep(body, 2, 'Either: a URL Table alias',
    '<b>Firewall → Aliases → URLs → Add</b>'
    + '<ul><li><b>Name:</b> <span class="mono">isemon_ban</span></li>'
    + '<li><b>Type:</b> URL Table (IPs)</li>'
    + '<li><b>URL:</b> the URL below, and <b>1</b> day after the slash</li></ul>'
    + 'Save and <b>Apply Changes</b>.', g.url);
  guideStep(body, 2, '…or: pfBlockerNG, every hour',
    '<b>Firewall → pfBlockerNG → IP → IPv4</b> (and IPv6) <b>→ Add</b>: '
    + '<ul><li><b>Name:</b> <span class="mono">isemon</span></li>'
    + '<li><b>Source:</b> the URL below, <b>Format</b> Auto</li>'
    + '<li><b>Action:</b> Deny Inbound</li>'
    + '<li><b>Update frequency:</b> Every hour</li></ul>'
    + 'Save, then <b>Update → Run</b>. pfBlockerNG makes the alias and the rule itself '
    + '(<span class="mono">pfB_isemon_v4</span>).', g.url);
  guideStep(body, 3, 'Block it (the URL Table alias only)',
    '<b>Firewall → Rules → WAN</b>: a rule at the top with <b>Action</b> Block, '
    + '<b>Source</b> Single host or alias <span class="mono">isemon_ban</span>, '
    + '<b>Destination</b> any. Save and <b>Apply Changes</b>. A rule on WAN stands in front of '
    + 'the pfSense’s own services as well, its VPNs among them.');
  guideStep(body, 4, 'Check that it works',
    'The pfSense appears under <i>Fetched by</i> on the settings page. <b>Diagnostics → '
    + 'Tables</b> shows what the alias holds; from the command prompt:',
    'pfctl -t isemon_ban -T show | head');
}

function guideScript(body, g) {
  guideNote(body, g.fmt === 'json'
    ? 'JSON: every address being kept out, with when its ban began and when it ends (null for '
      + 'good). For a script, a SIEM, or a firewall that is fed by one.'
    : 'One address or range to a line, and a few lines starting with # at the top for a '
      + 'person. Most firewalls and scripts that read a list of addresses read this.');
  guideStep(body, 1, 'Fetch it',
    'Anything that can fetch a URL over HTTPS'
    + (g.auth === 'key' ? ', with the key in the URL:'
       : (g.auth === 'basic' ? ', signing in with the user name and the password saved on the '
          + 'settings page (HTTP basic authentication):' : ', with nothing to sign in with:')),
    g.auth === 'basic'
      ? 'curl -fsS -u \'' + g.user + ':PASSWORD\' \'' + g.url + '\''
      : 'curl -fsS \'' + g.url + '\'');
  guideStep(body, 2, 'Only one family',
    'Add <span class="mono">&amp;family=ipv4</span> or <span class="mono">&amp;family=ipv6'
    + '</span> to the URL.');
  guideStep(body, 3, 'Know when it has changed',
    'Add <span class="mono">&amp;md5=1</span>: the answer is the MD5 of the list, and the list '
    + 'is worth fetching again only when it is different.',
    (g.auth === 'basic' ? 'curl -fsS -u \'' + g.user + ':PASSWORD\' ' : 'curl -fsS ')
    + '\'' + g.md5 + '\'');
  guideNote(body, 'Answers: <b>200</b> the list · <b>403</b> an address not allowed to '
    + 'fetch it' + (g.auth === 'key' ? ', or a missing or wrong key' : '')
    + (g.auth === 'basic' ? ' · <b>401</b> no user name and password, or wrong ones' : '')
    + ' · <b>404</b> nothing is published.');
}

function settingByKey(key) {
  /* Before the settings are in (1.10.192): nothing, rather than a throw
     out of every button that asks. */
  return ((SETTINGS && SETTINGS.settings) || []).filter(function (s) {
    return s.key === key;
  })[0];
}

function drawSettings() {
  var shown = {};
  Object.keys(PANES).forEach(function (pane) {
    var host = $('sect-' + pane);
    if (!host) return;
    clear(host);
    var heads = PANE_HEADS[pane] || {};
    var grid = null;
    PANES[pane].forEach(function (key) {
      var s = settingByKey(key);
      if (!s) return;
      shown[key] = true;
      if (heads[key] || !grid) {
        if (heads[key]) {
          var head = el('h3', '', heads[key]);
          head.style.cssText = 'font-size:13px;font-weight:700;letter-spacing:.6px;'
            + 'text-transform:uppercase;color:var(--tx-mut);margin:18px 0 12px;'
            + 'padding-bottom:7px;border-bottom:1px solid var(--line)';
          if (!grid) head.style.marginTop = '0';
          host.appendChild(head);
        }
        grid = el('div', 'set-grid');
        host.appendChild(grid);
      }
      grid.appendChild(settingItem(s));
    });
  });
  /* A setting the daemon knows and the panes above do not: it still has to be
     reachable, or a new one is invisible until somebody remembers it. */
  SETTINGS_ELSEWHERE.forEach(function (k) { shown[k] = true; });
  var rest = (SETTINGS.settings || []).filter(function (s) { return !shown[s.key]; });
  var host = $('sect-rest');
  clear(host);
  if ($('rest-card')) $('rest-card').hidden = !rest.length;
  if (rest.length) {
    var head = el('h3', '', 'Everything else');
    head.style.cssText = 'font-size:13px;font-weight:700;letter-spacing:.6px;'
      + 'text-transform:uppercase;color:var(--tx-mut);margin:0 0 12px;padding-bottom:7px;'
      + 'border-bottom:1px solid var(--line)';
    host.appendChild(head);
    var grid = el('div', 'set-grid');
    rest.forEach(function (s) { grid.appendChild(settingItem(s)); });
    host.appendChild(grid);
  }
  applyOnlyWhen();
  explainWhatWasDrawn();
}

