function applyOnlyWhen() {
  Object.keys(ONLY_WHEN).forEach(function (key) {
    var item = document.querySelector('.set-item[data-key="' + key + '"]');
    if (!item) return;
    var rule = ONLY_WHEN[key];
    var master = $('set-' + rule[0]);
    if (!master) return;
    var now = master._get ? String(master._get())
      : (master.type === 'checkbox' ? (master.checked ? '1' : '0') : String(master.value));
    /* An empty wanted value means "only while the other one is empty" - which
       is how the ladder takes over the single length below it. */
    /* '' means "only while the other one is empty", '*' the opposite: only
       while it has been filled in at all. */
    var live = rule[1] === '' ? !now.trim()
      : (rule[1] === '*' ? !!now.trim()
         : (rule[1].slice(-4) === '-not' ? now !== rule[1].slice(0, -4) : now === rule[1]));
    item.classList.toggle('asleep', !live);
    var says = item.querySelector('.asleep-why');
    if (!live && !says) {
      var other = settingByKey(rule[0]) || {};
      var name = other.name || rule[0];
      /* Said the way the other setting is drawn: a switch is on or off, a
         choice is one of its words. "is not \u201c1\u201d" is what the code
         thinks, not what the page shows. */
      var words = isBool(other) ? (name + ' is off')
        : (name + ' is not \u201c' + ((other.choice_words && other.choice_words[rule[1]])
                                         || rule[1]) + '\u201d');
      item.appendChild(el('div', 'says asleep-why',
        rule[1] === '' ? 'Not in use: ' + name + ' is set, and that decides instead.'
          : (rule[1] === '*' ? 'Nothing to mark against until ' + name + ' is filled in.'
             : (rule[1].slice(-4) === '-not'
                ? 'Not in use while ' + name + ' is \u201c' + rule[1].slice(0, -4) + '\u201d.'
                : 'Not in use while ' + words + '.'))));
    } else if (live && says) {
      says.remove();
    }
  });
  applyFwFields();
}

/* ---- which kind of firewall each one is (1.10.190) ----------------------
   A Mikrotik, or an OPNsense or a pfSense through its API or over ssh. A
   kind's settings are only shown while it is the kind chosen - and kept
   while it is not, so switching back finds them as they were. */
var FW_KIND_PREFIX = {'mikrotik': '', 'opnsense-api': 'opn', 'opnsense-ssh': 'opnssh',
                      'pfsense-api': 'pfa', 'pfsense-ssh': 'pfssh'};
var FW_SSH_KINDS = ['mikrotik', 'opnsense-ssh', 'pfsense-ssh'];
function fwKindNow(fw) {
  var box = $('set-' + fw + '_kind');
  var said = box ? String(box.value)
    : String((SETTINGS && banfeedWant(fw + '_kind')) || 'mikrotik');
  return FW_KIND_PREFIX.hasOwnProperty(said) ? said : 'mikrotik';
}
function fwSwitchNow(fw) {
  var key = fw === 'mikrotik2' ? 'mikrotik2' : 'mikrotik1';
  var box = $('set-' + key);
  if (box && box._get) return String(box._get()) === '1';
  var v = SETTINGS ? banfeedWant(key) : 0;
  return v === true || String(v) === '1';
}
function fwIsPf(kind) { return kind !== 'mikrotik'; }
/* Of the shared settings, which kinds are in use: the first firewall's
   always, the second's while it is switched on. */
function fwKindsInUse() {
  var out = [fwKindNow('mikrotik')];
  if (fwSwitchNow('mikrotik2')) out.push(fwKindNow('mikrotik2'));
  return out;
}
/** Whether a setting is shown, for the kinds chosen; undefined for one that
    has nothing to do with a firewall's kind. */
function fwFieldShown(key) {
  var m = /^(mikrotik2?)_(host|port|user|auth|password)$/.exec(key);
  if (m) return fwKindNow(m[1]) === 'mikrotik';
  m = /^(mikrotik2?)_(opn|opnssh|pfa|pfssh)_/.exec(key);
  if (m) return FW_KIND_PREFIX[fwKindNow(m[1])] === m[2];
  var used = fwKindsInUse();
  if (key === 'mikrotik_list' || key === 'geolist_name' || key === 'mikrotik_chunk'
      || key === 'geolist_chunk') {
    return used.indexOf('mikrotik') >= 0;
  }
  if (key === 'pf_list' || key === 'pf_geolist') {
    return used.some(fwIsPf);
  }
  return undefined;
}
function applyFwFields() {
  document.querySelectorAll('.set-item[data-key]').forEach(function (item) {
    var shown = fwFieldShown(item.dataset.key);
    if (shown === undefined) return;
    item.style.display = shown ? '' : 'none';
  });
  ['mikrotik', 'mikrotik2'].forEach(function (fw) {
    var at = fw === 'mikrotik2' ? 'mt2' : 'mt';
    var kind = fwKindNow(fw);
    var title = $(at + '-title');
    if (title) title.textContent = fwCardTitle(fw, kind);
    var box = $(at + '-keybox');
    if (box) box.hidden = FW_SSH_KINDS.indexOf(kind) < 0;
    var test = $(at + '-testbox');
    if (test) test.hidden = FW_SSH_KINDS.indexOf(kind) >= 0;
  });
}
function fwCardTitle(fw, kind) {
  var second = fw === 'mikrotik2';
  if (kind === 'opnsense-api' || kind === 'opnsense-ssh') {
    return second ? 'The second firewall: an OPNsense' : 'The first firewall: an OPNsense';
  }
  if (kind === 'pfsense-api' || kind === 'pfsense-ssh') {
    return second ? 'The second firewall: a pfSense' : 'The first firewall: a pfSense';
  }
  return second ? 'The second Mikrotik' : 'The first Mikrotik';
}
/* Any change inside any setting, whatever it is. A switch is a bare checkbox
   inside a label that carries the id, so watching for ids beginning "set-"
   missed every switch there is - which is most of what these rules are
   about. */
['change', 'input'].forEach(function (what) {
  document.addEventListener(what, function (e) {
    if (!e.target || !e.target.closest || !e.target.closest('.set-item')) return;
    applyOnlyWhen();
    /* Which of the database buttons make sense depends on which engine is
       chosen up there, not on which one is in use down here. */
    if (typeof engineButtons === 'function' && ENGINE && ENGINE.engines) engineButtons();
  });
});

/** Whether a setting is really a yes-or-no. */
function isBool(s) {
  return typeof s.default === 'boolean'
    || (s.min === 0 && s.max === 1 && typeof s.default === 'number');
}

/* A source of bans (1.10.196): 'off', 'watch' or 'on', whatever older
   saves wrote for it (1, true, 0...) read the way the daemon reads it. */
function banModeOf(v) {
  var w = String(v === undefined || v === null ? '' : v).trim().toLowerCase();
  if (['1', 'on', 'true', 'yes', 'ban'].indexOf(w) >= 0) return 'on';
  if (['2', 'watch', 'watching', 'monitor'].indexOf(w) >= 0) return 'watch';
  return 'off';
}
function isBanMode(s) {
  return /^ban_from_/.test(s.key || '') && Array.isArray(s.choices)
    && s.choices.indexOf('on') >= 0 && s.choices.indexOf('off') >= 0;
}
/* The switch itself: three places for the knob, or two where the source
   cannot be only watched (a ban made by hand is meant). */
function banModeSwitch(s, onChange) {
  var modes = s.choices.filter(function (c) {
    return c === 'off' || c === 'watch' || c === 'on';
  });
  var three = modes.indexOf('watch') >= 0;
  var wrap = el('span', 'sw3wrap');
  var knob = el('span', three ? 'sw3' : 'sw3 two');
  var word = el('span', 'sw3word');
  var SAY = {off: 'off', watch: 'watching', on: 'on'};
  /* A value it does not offer read as the daemon reads it (1.10.197):
     "watch" on a source that cannot be watched is on there. */
  var fit = function (m) {
    if (modes.indexOf(m) >= 0) return m;
    return m === 'watch' && modes.indexOf('on') >= 0 ? 'on' : 'off';
  };
  var mode = fit(banModeOf(s.value));
  knob.tabIndex = ADMIN ? 0 : -1;
  knob.setAttribute('role', 'slider');
  knob.setAttribute('aria-valuemin', '0');
  knob.setAttribute('aria-valuemax', String(modes.length - 1));
  if (!ADMIN) knob.classList.add('off-limits');
  if (!three) {
    /* Two places: the narrower switch, the knob at either end. */
    knob.style.width = '44px';
  }
  function draw() {
    knob.dataset.mode = mode;
    if (!three && mode === 'on') knob.dataset.mode = 'on2';
    knob.setAttribute('aria-valuenow', String(modes.indexOf(mode)));
    knob.setAttribute('aria-valuetext', SAY[mode]);
    knob.title = (s.choice_words && s.choice_words[mode]) || SAY[mode];
    word.textContent = SAY[mode];
    word.className = 'sw3word ' + mode;
  }
  function put(m) {
    if (!ADMIN || m === mode || modes.indexOf(m) < 0) return;
    mode = m;
    draw();
    if (onChange) onChange();
  }
  /* A third of the switch each - a half each where there are two. */
  modes.forEach(function (m, i) {
    var zone = el('i');
    if (!three) {
      zone.style.width = '50%';
      zone.style.left = i ? '50%' : '0';
      zone.style.right = 'auto';
    }
    zone.addEventListener('click', function (e) {
      e.preventDefault();
      /* On a two-way switch a click anywhere turns it over, as a switch does. */
      put(three ? m : (mode === 'on' ? 'off' : 'on'));
    });
    knob.appendChild(zone);
  });
  knob.addEventListener('keydown', function (e) {
    var at = modes.indexOf(mode);
    if (e.key === 'ArrowRight' || e.key === 'ArrowUp') at = Math.min(modes.length - 1, at + 1);
    else if (e.key === 'ArrowLeft' || e.key === 'ArrowDown') at = Math.max(0, at - 1);
    else if (e.key === ' ' || e.key === 'Enter') at = (at + 1) % modes.length;
    else return;
    e.preventDefault();
    put(modes[at]);
  });
  wrap.appendChild(knob);
  wrap.appendChild(word);
  wrap._get = function () { return mode; };
  wrap._set = function (v) {
    mode = fit(banModeOf(v));
    draw();
  };
  draw();
  return wrap;
}

function settingItem(s) {
  if (isBanMode(s)) {
    s.value = banModeOf(s.value);
    if (s.value === 'watch' && s.choices.indexOf('watch') < 0) s.value = 'on';
  }
  var item = el('div', 'set-item' + (isBool(s) || isBanMode(s) ? ' set-bool' : ''));
  item.dataset.key = s.key;
  var label = el('label', '', s.name || s.key);
  label.setAttribute('for', 'set-' + s.key);
  if (NEEDS_NET[s.key]) {
    var globe = document.createElement('span');
    globe.className = 'net-mark';
    globe.innerHTML = iconMarkup('globe', 15);
    explain(globe, 'This one needs the internet. On a machine with no way out it simply never '
      + 'fetches anything, and says so rather than failing quietly.');
    label.appendChild(globe);
  }
  /* The whole story of one setting, on demand: what it does, what is running,
     what the built-in default is and whether this installation has changed
     it. The label itself carries the short words. */
  var info = el('span', 'iinfo', 'i');
  info.setAttribute('role', 'button');
  info.tabIndex = 0;
  var asText = function (v) {
    return richText(Array.isArray(v) ? v.join(', ') : String(v));
  };
  var where = s.source || (isSame(s) ? 'default' : 'saved');
  var story = '<span class="k">on the command line this one is <b>isemon --set ' + s.key
    + '=\u2026</b> \u00b7 running: ' + asText(s.value)
    + '<br><span class="' + (where === 'default' ? 'same' : 'diff') + '">'
    + (s.source_says || 'saved on this dashboard')
    + (s.saved_by ? ' (by ' + richText(s.saved_by)
        + (s.saved_at ? ', ' + ago(s.saved_at) : '') + ')' : '')
    + '</span>';
  /* What the other two layers would say, when they say something else. The
     question in front of a changed setting is always what it was before. */
  if (where === 'saved' && s.in_file) {
    story += '<br><span class="same">config.json says ' + asText(s.file) + '</span>';
  }
  if (where !== 'default' && String(s.value) !== String(s.default)) {
    story += '<br><span class="same">the built-in default is ' + asText(s.default) + '</span>';
  }
  var whole = s.says || 'No words have been written for this one yet.';
  explain(info, whole, story + '</span>');
  /* The name says it too, so pointing anywhere near a setting explains it
     rather than only pointing at the little i. */
  explain(label, whole, story + '</span>');
  label.appendChild(info);
  item.appendChild(label);

  var input;
  if (isBanMode(s)) {
    /* Off, only watched, on (1.10.196): a switch with three places rather
       than a dropdown of three sentences. */
    var three = banModeSwitch(s, function () { markDirty(item, s); });
    three.id = 'set-' + s.key;
    explain(three, whole, story + '</span>');
    item.appendChild(three);
    if (s.says) item.appendChild(saysBlock(s.says));
    return item;
  }
  if (isBool(s)) {
    /* A switch, not a dropdown reading "on / off": one thing to look at
       rather than two words to read. */
    var wrap = el('label', 'sw');
    input = document.createElement('input');
    input.type = 'checkbox';
    input.checked = (s.value === true || String(s.value) === '1');
    wrap.appendChild(input);
    wrap.appendChild(el('span', 'knob'));
    wrap._get = function () { return input.checked ? 1 : 0; };
    wrap._set = function (v) {
      input.checked = (v === true || String(v) === '1');
    };
    input.disabled = !ADMIN;
    input.addEventListener('change', function () { markDirty(item, s); });
    wrap.id = 'set-' + s.key;
    explain(wrap, whole, story + '</span>');
    item.appendChild(wrap);
    if (s.says) item.appendChild(saysBlock(s.says));
    return item;
  }
  if (s.key === 'block_ladder') {
    item.classList.add('tall');
    input = ladderEditor(s);
  } else if (s.key === 'tacacs_from' || s.key === 'otp_from') {
    item.classList.add('tall');
    input = placesEditor(s);
  } else if (s.key === 'ptr_servers') {
    /* A list with an order, one server to a row: which one is asked first
       is a decision, and a decision belongs somewhere it can be seen and
       moved rather than in the middle of a line of text. */
    item.classList.add('tall');
    input = dnsEditor(s);
  } else if (s.key === 'ios_acl_tail' || s.key === 'ios_acl_tail6') {
    /* The end of an access list is an access list: several lines of a
       router's own language, in the order they are to be pasted. A box, and
       the daemon reads it as it is typed - a line a router would refuse is
       said here, beside the box, rather than at a console halfway through. */
    item.classList.add('tall');
    input = aclEditor(s);
  } else if (s.key === 'geolist_countries' || s.key === 'never_block_countries') {
    // A wall of flags is not a field, and standing it in a row beside three
    // boxes leaves the row a hundred pixels ragged. It takes a line of its
    // own, like the ladder.
    item.classList.add('tall');
    input = countryPicker(s);
  } else if (s.key === 'acme_ca_pem') {
    /* A certificate in PEM is lines, not a line (1.10.251). */
    item.classList.add('tall');
    input = el('textarea', 'mono');
    input.rows = 5;
    input.spellcheck = false;
    input.placeholder = '-----BEGIN CERTIFICATE-----';
    input.value = s.value === null || s.value === undefined ? '' : String(s.value);
    input.disabled = !ADMIN;
  } else if (s.choices) {
    input = el('select');
    s.choices.forEach(function (c) {
      var o = document.createElement('option');
      o.value = c;
      o.textContent = (s.choice_words && s.choice_words[c]) || c;
      input.appendChild(o);
    });
    input.value = String(s.value);
  } else if (s.kind === 'fwsources') {
    /* A firewall a row: what it is called on the page, which kind of
       firewall it is, where its log is and which files there are its. */
    item.classList.add('tall');
    item.classList.add('wide');
    input = fwSourcesEditor(s);
  } else if (s.kind === 'list') {
    /* A row each and a button to add one, rather than a comma-separated line
       in a box too narrow to read it in. `ptr_servers` keeps its own editor
       above, because the ORDER of those matters and these have none. */
    item.classList.add('tall');
    input = listEditor(s);
  } else if (typeof s.min === 'number') {
    input = el('input');
    input.type = 'number';
    input.min = s.min;
    input.max = s.max;
    input.value = s.value;
  } else {
    input = el('input');
    input.type = 'text';
    input.value = s.value === null || s.value === undefined ? '' : String(s.value);
    if (s.secret) {
      input.placeholder = s.set ? 'set — leave as it is to keep it' : 'not set';
      input.autocomplete = 'off';
      /* Pressed, the dots are chosen whole: what is typed replaces them
         (1.10.217). */
      input.addEventListener('focus', function () {
        if (input.value.indexOf('\u2022') === 0) input.select();
      });
      input.title = 'Shown back by its last two letters only. Leave it alone to keep the one '
        + 'that is set; type a new one to replace it.';
    }
  }
  input.id = 'set-' + s.key;
  if (input.tagName === 'INPUT' || input.tagName === 'SELECT') input.disabled = !ADMIN;
  input.addEventListener('input', function () { markDirty(item, s); });
  input.addEventListener('change', function () { markDirty(item, s); });
  /* The field itself, so that pointing at the box somebody is about to type
     in says what typing in it will do. */
  if (!input.dataset.explains) explain(input, whole, story + '</span>');
  item.appendChild(input);
  if (s.says) item.appendChild(saysBlock(s.says));
  return item;
}

/* The firewalls as they are read now: the saved list, or - where nobody has
   saved one - the one firewall the older settings describe. */
function fwSourcesNow(s) {
  var lags = s.lags || {};
  return (s.value && s.value.length ? s.value : (s.effective || [])).map(function (one) {
    var row = fwSourceRow(one);
    row.lag = lags[row.name] || '';
    return row;
  });
}
function fwSourceRow(one) {
  var paths = Array.isArray(one.paths) && one.paths.length ? one.paths
    : String(one.path || '').split(/[,;\n]/);
  paths = paths.map(function (p) { return String(p).trim(); }).filter(function (p) { return p; });
  var row = {name: String(one.name || ''), type: String(one.type || 'fortigate'),
             paths: paths.length ? paths : [''], files: String(one.files || '*.log'),
             zone: String(one.zone || ''), lag: String(one.lag || '')};
  /* A MikroTik read through its API as well (1.10.211). */
  if (one.api) row.api = rosApiRow(one.api);
  return row;
}
function rosApiRow(a) {
  a = a || {};
  return {on: Number(a.on || 0) ? 1 : 0, host: String(a.host || ''),
          port: Number(a.port || 8729), mode: String(a.mode || 'pin'),
          user: String(a.user || 'isemon-read'), password: String(a.password || ''),
          password_set: !!a.password_set, every: Number(a.every || 30),
          auth: String(a.auth || 'key') === 'password' ? 'password' : 'key',
          tls_name: String(a.tls_name || ''),
          verify: a.verify === undefined ? 1 : (Number(a.verify) ? 1 : 0)};
}

function isSame(s) {
  if (s.kind === 'fwsources') return !(s.value && s.value.length);
  var a = Array.isArray(s.value) ? s.value.join(',') : String(s.value);
  var b = Array.isArray(s.default) ? s.default.join(',') : String(s.default);
  if (s.secret) return !s.set;
  if (typeof s.default === 'boolean') {
    return (s.value === true || String(s.value) === '1') === s.default;
  }
  return a === b;
}

function readValue(s) {
  var input = $('set-' + s.key);
  if (!input) return undefined;
  if (input._get) return input._get();
  if (s.kind === 'list') {
    return input.value.split(',').map(function (x) { return x.trim(); })
      .filter(function (x) { return x; });
  }
  /* An empty number box is empty, not nought: sent as 0 it was refused as
     "must be between 1 and 1000" about a box somebody had only cleared - or
     taken, where 0 is allowed. Sent empty, it is refused as empty. */
  if (typeof s.min === 'number' && !s.choices) {
    return String(input.value).trim() === '' ? '' : Number(input.value);
  }
  return input.value;
}

function markDirty(item, s) {
  var now = readValue(s);
  if (s.kind === 'fwsources') {
    var drawn = $('set-' + s.key);
    var moved = JSON.stringify(now) !== (drawn && drawn._initial !== undefined
      ? drawn._initial : JSON.stringify(fwSourcesNow(s)));
    item.classList.toggle('changed', moved);
    if (moved) DIRTY[s.key] = now; else delete DIRTY[s.key];
    markDirtyCount();
    return;
  }
  var was = s.kind === 'list' ? (s.value || []).join(',')
    : (isBool(s) ? ((s.value === true || String(s.value) === '1') ? '1' : '0') : String(s.value));
  var isNow = Array.isArray(now) ? now.join(',')
    : (isBool(s) ? String(now) : String(now));
  var changed = was !== isNow;
  item.classList.toggle('changed', changed);
  if (changed) DIRTY[s.key] = now; else delete DIRTY[s.key];
  markDirtyCount();
  if (/^banfeed/.test(s.key)) drawBanfeed();
  /* How to set each shape up is behind the guide button, as it is for an
     FTD and a FortiGate - not opened by choosing one (1.10.192). */
  if (s.key === 'mikrotik_kind' || s.key === 'mikrotik2_kind') {
    var fw = s.key === 'mikrotik2_kind' ? 'mikrotik2' : 'mikrotik';
    applyFwFields();
    if (MT_LAST) {
      drawFirewall('mt', 'mikrotik', MT_LAST);
      drawFirewall('mt2', 'mikrotik2', MT_LAST);
      drawPairState(MT_LAST);
    }
    /* The guide for the kind chosen is behind "How to set it up…" on the
       card, not opened by choosing it (1.10.192). */
  }
}

function markDirtyCount() {
  /* ...and a pane's own changes that are not settings (1.10.222). */
  var n = Object.keys(DIRTY).length
    + (typeof EXTRA_SAVES === 'object' ? Object.keys(EXTRA_SAVES).length : 0);
  $('set-said').textContent = n ? n + ' change(s) not saved yet' : '';
  var bar = document.querySelector('.save-bar');
  if (bar) bar.classList.toggle('dirty', n > 0);
  if (bar) bar.style.display = saveBarHere() ? '' : 'none';
}
/* The save bar on a pane where something is saved by it - a setting of the
   daemon's own, the firewall, the time servers, the console at login - and
   on no other, as otp 1.0.146 has it (1.10.234): Restart and power off does
   what it does at once and has nothing to save. A change waiting, from
   wherever it was made, keeps it there. */
var SAVE_PANES = ['fw', 'time', 'about'];
function saveBarHere() {
  if (typeof TAB !== 'undefined' && TAB !== 'settings') return true;
  var pane = $('pane-' + PANE);
  if (!pane) return true;
  if (SAVE_PANES.indexOf(PANE) >= 0 || pane.querySelector('.set-item[data-key]')) return true;
  if (Object.keys(DIRTY).length) return true;
  return typeof EXTRA_SAVES === 'object' && Object.keys(EXTRA_SAVES).length > 0;
}

$('set-save').onclick = function () {
  /* A source going from only watched to on carries every ban it made at
     once (1.10.196): asked first, with how many. */
  var going = Object.keys(DIRTY).filter(function (k) {
    return /^ban_from_/.test(k) && String(DIRTY[k]) === 'on';
  }).map(function (k) {
    var one = ((SOURCES || {}).sources || []).filter(function (x) {
      return x.setting === k;
    })[0];
    return one && one.mode === 'watch' && one.bans ? one : null;
  }).filter(Boolean);
  if (going.length && !$('set-save')._asked) {
    confirmThen('Carry what they have been watching',
      /* Each part a sentence of its own, so that each is said in the page's
         language (1.10.197): one sentence with the counts inside it was
         left in English. */
      '<span>Switched on, every ban of it still running is carried at once, the ones it '
      + 'made while only watched among them: to the firewalls, into the published list and '
      + 'into the access list.</span><br>'
      + going.map(function (x) {
        return '<b>' + num(x.bans) + '</b> \u00b7 <span>' + htmlText(x.words) + '</span>';
      }).join('<br>')
      + '<br><span>They can be looked through first on the Banned page.</span>',
      'Switch on and carry them', function () {
        $('set-save')._asked = true;
        try { $('set-save').onclick(); } finally { $('set-save')._asked = false; }
      });
    return;
  }
  var want = {};
  (SETTINGS.settings || []).forEach(function (s) {
    if (!(s.key in DIRTY)) return;
    /* A secret that still reads as its masked form was not touched, and
       sending it back would set the password to a row of dots. */
    if (s.secret && String(DIRTY[s.key]).indexOf('•') === 0) {
      /* ...and is not a change at all (1.10.192): left among the changes,
         the page went on saying one was not saved, and drew the settings
         saved over the old ones. */
      delete DIRTY[s.key];
      return;
    }
    want[s.key] = DIRTY[s.key];
  });
  /* A pane's own changes that are not settings - the firewall's - saved by
     the same button, each by its own hook (1.10.222). */
  var extras = typeof EXTRA_SAVES === 'object' && !$('set-save')._noExtras
    ? Object.keys(EXTRA_SAVES) : [];
  if (extras.length) {
    busy($('set-save'), true);
    var chain = Promise.resolve();
    extras.forEach(function (k) {
      chain = chain.then(function () { return EXTRA_SAVES[k] && EXTRA_SAVES[k].save(); });
    });
    chain.catch(oops).then(function () {
      busy($('set-save'), false);
      if (Object.keys(want).length) {
        $('set-save')._asked = true;
        $('set-save')._noExtras = true;
        try { $('set-save').onclick(); } finally {
          $('set-save')._asked = false;
          $('set-save')._noExtras = false;
        }
      }
    });
    return;
  }
  if (!Object.keys(want).length) { toast('nothing has changed'); return; }
  busy($('set-save'), true);
  Array.prototype.forEach.call(document.querySelectorAll('.set-item.refused'),
    function (n) { n.classList.remove('refused'); });
  api('settings', {settings: want}).then(function (d) {
    /* Only what was sent is taken as saved (1.10.176): a box changed while
       the save was on its way was dropped and drawn over without a word. */
    Object.keys(want).forEach(function (k) {
      /* Compared as what they are (1.10.197): a list of firewalls is objects,
         and "[object Object]" is every one of them. */
      if (JSON.stringify(DIRTY[k]) === JSON.stringify(want[k])) {
        delete DIRTY[k];
        var box = document.querySelector('.set-item.changed[data-key="' + k + '"]');
        if (box) box.classList.remove('changed');
      }
    });
    markDirtyCount();
    toast(d.message, 'good');
    /* Drawn again from what was saved, unless something was changed while
       the save was on its way, which is kept (1.10.192). */
    loadSettings(!Object.keys(DIRTY).length);
    tick();
    /* Going back switched on or off: the card shown or taken away at once. */
    if ('downgrade_offered' in want && typeof paneLive === 'function' && paneLive('upgrade')) loadUpgrade(true);
  }).catch(function (e) {
    if (e && e.stopped) return;
    /* The daemon names the setting it refused by its key; the box is marked
       and the message says the name the page gives it. (1.10.159) */
    var said = String((e && e.message) || e);
    var hit = (SETTINGS.settings || []).filter(function (one) {
      return said.indexOf(one.key + ' ') === 0 || said.indexOf(one.key + ':') === 0;
    }).sort(function (a, b) { return b.key.length - a.key.length; })[0];
    if (hit) {
      var item = document.querySelector('.set-item[data-key="' + hit.key + '"]');
      if (item) {
        item.classList.add('refused');
        if (item.getClientRects().length) item.scrollIntoView({block: 'center'});
        else if (item.closest('.ctl-pane')) {
          showPane(item.closest('.ctl-pane').id.slice(5));
          item.scrollIntoView({block: 'center'});
        }
      }
      said = '“' + (hit.name || hit.key) + '”' + said.slice(hit.key.length);
    }
    toast(said, 'bad');
  }).then(function () { busy($('set-save'), false); });
};
/* Settings changed and not saved, and the page about to go: asked first.
   A reload took them without a word. (1.10.159) */
window.addEventListener('beforeunload', function (e) {
  if ((typeof DIRTY === 'object' && Object.keys(DIRTY).length)
      || (typeof EXTRA_SAVES === 'object' && Object.keys(EXTRA_SAVES).length)) {
    e.preventDefault();
    e.returnValue = '';
  }
});
$('set-reset').onclick = function () {
  if (typeof EXTRA_SAVES === 'object') {
    Object.keys(EXTRA_SAVES).forEach(function (k) {
      var hook = EXTRA_SAVES[k];
      delete EXTRA_SAVES[k];
      if (hook && hook.reset) hook.reset();
    });
  }
  loadSettings(true);
  toast('put back as the daemon has them');
};

/* ==========================================================================
   Active Directory
   --------------------------------------------------------------------------
   Three things somebody setting this up needs and never gets: the groups
   listed rather than typed, a check that says which step failed, and a way
   to try one sign-in before signing out and finding out the hard way.
   ========================================================================== */
var DIR = null;

function loadDirectory() {
  api('directory').then(function (d) {
    DIR = d;
    drawCaState(d);
    drawCaState(d.second || {}, 'ca2');
    drawDirUsers(d.mirrored || []);
  }).catch(oops);
}

function drawCaState(d, at) {
  at = at || 'ca';
  var host = $(at + '-state');
  if (!host) return;
  clear(host);
  var says = d.ca_says;
  if (!d.ca) {
    $(at + '-when').textContent = 'none imported';
    host.appendChild(el('p', 'note', 'Nothing is imported, so the server’s certificate has '
      + 'to be signed by an authority this machine already trusts.'));
    return;
  }
  $(at + '-when').textContent = 'imported';
  var box = el('div', 'facts');
  var fact = function (k, v) {
    var one = el('div', 'fact');
    one.appendChild(el('span', 'k', k));
    one.appendChild(el('span', 'v', v));
    box.appendChild(one);
  };
  if (says) {
    fact('It is', says.subject || 'unnamed');
    fact('Signed by', says.self_signed ? 'itself (a root)' : (says.issuer || 'unnamed'));
    fact('Good until', says.until || '–');
    if (says.count > 1) fact('Certificates in it', num(says.count));
  } else {
    fact('It is', 'stored, but could not be read');
  }
  host.appendChild(box);
}

function drawDirUsers(rows) {
  var host = $('dir-users');
  if (!host) return;
  clear(host);
  $('dir-seen').textContent = rows.length ? num(rows.length) + ' so far' : 'nobody yet';
  if (!rows.length) {
    host.appendChild(el('p', 'note', 'Nobody has signed in from the directory yet.'));
    return;
  }
  host.appendChild(listView({
    key: 'dir-users', rows: rows, per: 25, barFrom: 6,
    placeholder: 'a name, a group…',
    hay: function (r) { return [r.name, r.display, r.dn, r.groups].join(' '); },
    draw: function (page, into) {
      into.appendChild(listTable(['Name', 'Who they are', 'Role', 'Last signed in', 'Groups'],
        page, function (r) {
          var tr = el('tr');
          var n = el('td');
          n.appendChild(el('span', 'mono', r.name));
          tr.appendChild(n);
          var who = el('td');
          who.appendChild(el('span', '', r.display || '–'));
          if (r.dn) who.appendChild(el('span', 'd mono', r.dn));
          tr.appendChild(who);
          var role = el('td');
          role.appendChild(el('span', 'tag ' + roleTone(r.role), roleWords(r.role)));
          tr.appendChild(role);
          tr.appendChild(r.last_in ? stampCell(r.last_in) : el('td', '', 'never'));
          tr.appendChild(el('td', 'dim', (r.groups || '').slice(0, 90)));
          return tr;
        }, 'plain'));
    }
  }));
}

/* ---- the certificate ---------------------------------------------------- */
if ($('ca-save')) {
  $('ca-save').onclick = function () {
    var pem = $('ca-pem').value.trim();
    if (!pem) { toast('paste the certificate first', 'bad'); return; }
    busy($('ca-save'), true);
    api('directory', {ca: pem}).then(function (d) {
      toast(d.message, 'good');
      $('ca-pem').value = '';
      loadDirectory();
    }).catch(oops).then(function () { busy($('ca-save'), false); });
  };
  $('ca-file').onclick = function () { $('ca-input').click(); };
  $('ca-input').onchange = function () {
    var file = this.files && this.files[0];
    if (!file) return;
    var reader = new FileReader();
    reader.onload = function () {
      $('ca-pem').value = String(reader.result || '').trim();
      toast('read ' + file.name + ' — press Import it');
    };
    reader.readAsText(file);
    this.value = '';
  };
  $('ca-drop').onclick = function () {
    confirmThen('Take the certificate authority away',
      'The directory’s certificate will then have to be signed by an authority this '
      + 'machine already trusts, or the check has to be switched off.',
      'Take it away', function () {
        api('directory', {ca: ''}).then(function (d) {
          toast(d.message, 'good'); loadDirectory();
        }).catch(oops);
      });
  };
}

/** What a check of either directory found, step by step. One renderer,
    because the two checks ask the same questions of two machines and an
    answer that looked different would read as a different question. */
function showDirCheck(d) {
  modal('Checking ' + (d.words || 'the directory'), function (body) {
    body.appendChild(peekFacts([
      ['Server', d.host + ':' + d.port],
      ['How', d.tls === 'none' ? 'plain LDAP' : d.tls],
      ['Certificate', d.tls === 'none' ? 'not used' : (d.verify ? 'checked' : 'NOT checked')],
      ['Took', num(d.took_ms) + ' ms']
    ]));
    var list = el('div', 'steps');
    (d.steps || []).forEach(function (s) {
      var row = el('div', 'step ' + (s.ok ? 'ok' : 'bad'));
      var mark = el('span', 'step-mark');
      mark.innerHTML = iconMarkup(s.ok ? 'check' : 'cancel', 15);
      row.appendChild(mark);
      var words = el('span', 'step-words');
      words.appendChild(el('b', '', s.what));
      if (s.said) words.appendChild(el('span', 'd', s.said));
      row.appendChild(words);
      list.appendChild(row);
    });
    body.appendChild(list);
    if ((d.domains || []).length) {
      var says = el('p', 'note');
      says.innerHTML = 'A name written <span class="mono">somebody@'
        + richText(d.domains[0]) + '</span> in a log is asked of this directory. '
        + 'It answers for: ' + d.domains.map(function (one) {
          return '<b>' + richText(one) + '</b>';
        }).join(', ') + '. That list is what the directory itself says, so nothing has to '
        + 'be typed here \u2014 and where it says nothing, the domains under it may be '
        + 'named by hand in the setting beside it.';
      body.appendChild(says);
    }
    if (d.ok) {
      body.appendChild(el('p', 'note', d.lookup_only
        ? 'It answered. A name the first directory does not have will be asked of this one \u2014 '
          + 'and nothing else is ever asked of it.'
        : 'Everything answered. People in the groups above can sign in with their own name '
          + 'and password.'));
    }
  }, [{words: 'Close', close: true}]);
}

/* ---- the second directory: its certificate, and trying it ---------------
   The same three buttons as the first one's, pointed at the other directory.
   Written out rather than shared because the ids differ and a shared version
   that took six of them would be harder to read than this. */
if ($('ca2-save')) {
  $('ca2-save').onclick = function () {
    var pem = $('ca2-pem').value.trim();
    if (!pem) { toast('paste the certificate first', 'bad'); return; }
    busy($('ca2-save'), true);
    api('directory', {ca: pem, which: 'directory2'}).then(function (d) {
      toast(d.message, 'good');
      $('ca2-pem').value = '';
      loadDirectory();
    }).catch(oops).then(function () { busy($('ca2-save'), false); });
  };
  $('ca2-file').onclick = function () { $('ca2-input').click(); };
  $('ca2-input').onchange = function () {
    var file = this.files && this.files[0];
    if (!file) return;
    var reader = new FileReader();
    reader.onload = function () {
      $('ca2-pem').value = String(reader.result || '').trim();
      toast('read ' + file.name + ' \u2014 press Import it');
    };
    reader.readAsText(file);
    this.value = '';
  };
  $('ca2-drop').onclick = function () {
    confirmThen('Take that certificate authority away',
      'The second directory\u2019s certificate will then have to be signed by an authority '
      + 'this machine already trusts, or its check has to be switched off.',
      'Take it away', function () {
        api('directory', {ca: '', which: 'directory2'}).then(function (d) {
          toast(d.message, 'good'); loadDirectory();
        }).catch(oops);
      });
  };
}
if ($('dir2-check')) {
  if ($('ptr-fill')) {
    $('ptr-fill').onclick = function () {
      api('ptr', {missing: true}).then(function (d) {
        var many = d.missing || 0;
        if (!many) { toast('every address in the records already has an answer', 'good'); return; }
        confirmThen('Look up the names behind ' + num(many) + ' address(es)?',
          '<p>Every address in the records that has no name written down yet is asked about, '
          + 'in the order it was seen, at the same handful a second as everything else here. '
          + 'On a database with a year in it that is a long slow trickle rather than a '
          + 'burst.</p>'
          + '<p class="ask-what"><b>' + num(many) + ' address(es)</b> with no answer yet</p>'
          + '<p>Nothing is changed but the names: no record is touched, nobody is banned or '
          + 'un-banned, and an address that turns out to have no name is written down as '
          + 'having none so it is not asked about again.</p>'
          + '<p class="muted">It runs in the background. You can close the window it opens '
          + 'and it carries on \u2014 <span class="mono">isemon --ptr-fill</span> does the '
          + 'same from the server.</p>',
          'Look them all up', function () {
            api('ptr', {fill: true}).then(function (r) {
              watchJob(r.job, 'Looking up the names behind every address', function () {
                loadSettings();
              }, 'Asking the name servers about every address that has no answer yet. You '
               + 'can close this and it carries on.');
            }).catch(oops);
          }, false);
      }).catch(oops);
    };
  }
  if ($('ptr-try')) {
    $('ptr-try').onclick = tryOneName;
    $('ptr-try-ip').onkeydown = function (e) {
      if (e.key === 'Enter') { e.preventDefault(); tryOneName(); }
    };
  }
  $('dir2-check').onclick = function () {
    busy($('dir2-check'), true);
    api('directory', {check: true, which: 'directory2'}).then(function (d) {
      showDirCheck(d);
    }).catch(oops).then(function () { busy($('dir2-check'), false); });
  };
  $('dir2-try').onclick = function () {
    var box;
    modal('Look a name up', function (body) {
      body.appendChild(el('p', 'note', 'This directory is asked, and no other \u2014 what is '
        + 'being tested here is this one. Nothing in it is changed; it is only read.'));
      var one = el('div', 'set-item');
      one.appendChild(el('label', '', 'A name out of the logs'));
      box = el('input');
      box.type = 'text';
      box.placeholder = 'jnovak, or a machine';
      one.appendChild(box);
      body.appendChild(one);
      setTimeout(function () { box.focus(); }, 60);
      box.onkeydown = function (e) {
        if (e.key === 'Enter' && box.value.trim()) showPerson(box.value.trim(), 'directory2');
      };
    }, [{words: 'Look it up', cls: 'primary', icon: 'search',
         go: function () {
           if (box.value.trim()) showPerson(box.value.trim(), 'directory2');
         }},
        {spacer: true}, {words: 'Close', close: true}]);
  };
}

/** A row about the network rather than about a person.

    What is worth knowing here is not who and from where - the name is a
    certificate or a MAC and the address is as often as not the switch's own
    - but which machine, on which socket or which radio, and what it was
    given. So the columns are those, and the address is not among them.

    `got` says whether this is a login or a refusal: the last column is what
    it was given, or why it was not. */
function networkRow(tr, r, kind, got) {
  /* Which RADIUS server answered: ISE, or a Windows NPS. The row is the same
     question asked of either, and every word of it that names the system
     names the one that really wrote the record. */
  var SYS = isNpsKind(kind) ? 'NPS' : (isRadiusKind(kind) ? 'FreeRADIUS' : 'ISE');
  tr.appendChild(stampCell(r.ts));
  /* The endpoint itself. A MAC is the name of a thing rather than of a
     person, and it is what somebody looking for "that printer" has. */
  var who = el('td');
  if (r.mac) {
    var mac = el('span', 'mono', r.mac);
    explain(mac, 'The endpoint\u2019s MAC address, as ' + SYS + ' wrote it. It is what this machine '
      + 'is known by on the network \u2014 and on MAB it is the whole of what it offered.');
    who.appendChild(mac);
  } else {
    who.appendChild(el('span', 'muted', '\u2013'));
  }
  tr.appendChild(who);
  /* The address that machine has, where the switch or the controller
     reported one. It is not the device's address - that is the column
     headed Switch, a few along - and it is not there at all on a record
     made before the machine had asked for one, which is most MAB failures
     and a good few first handshakes. A dash means the record did not carry
     it, never that the machine has no address. */
  var at = el('td');
  if (r.client) {
    var addr = el('span', 'mono small', r.client);
    explain(addr, r.client_seen
      ? 'The address this machine was given, out of the accounting the '
        + (isWifiKind(kind) ? 'controller' : 'switch') + ' sent to NPS at '
        + shortStamp(r.client_seen) + ' \u2014 the sign-in itself did not carry one, '
        + 'because the address is handed out after it.'
      : 'The address this machine has, as the '
      + (isWifiKind(kind) ? 'controller' : 'switch') + ' reported it to ' + SYS + ' '
      + '— the endpoint’s own, not the network device’s. It is written down '
      + 'when the machine already has one, so a handshake that happened before it asked '
      + 'for an address has none.');
    at.appendChild(addr);
    /* No ban button and no history beside it, on purpose. This address is
       not what knocked - it is what the machine was given on the inside of
       the network - so "what has this address been doing here" would be a
       question about somebody else's address entirely, and banning it would
       ban a desk. */
  } else {
    var none = el('span', 'muted', '–');
    explain(none, 'This record did not carry an address for the machine. ' + SYS + ' writes one '
      + 'down only when the network device reported it, which it cannot do before the '
      + 'machine has asked for one.'
      + (SYS === 'NPS'
         ? ' Behind NPS the address is in the accounting the device sends once the '
           + 'machine has one \u2014 if the ' + (isWifiKind(kind) ? 'controller' : 'switch')
           + ' sends no RADIUS accounting to NPS, there is none to show. docs/nps-logs.md '
           + 'says how to switch it on.'
         : ''));
    at.appendChild(none);
  }
  tr.appendChild(at);
  /* The name, when there is one. On MAB it is the MAC over again, which is
     worth saying rather than printing twice. */
  var name = el('td');
  var said = String(r.username || '');
  if (said && said.replace(/[-:.]/g, '').toUpperCase()
      !== String(r.mac || '').replace(/[-:.]/g, '').toUpperCase()) {
    name.appendChild(el('span', 'mono', said));
    /* A machine is in the directory too - with what it runs, when it last
       spoke to the domain, and whether its account is still enabled. */
    whoIsIt(name, said, r.realm);
  } else if (said) {
    var same = el('span', 'muted small', 'its MAC');
    explain(same, 'The only name it offered was its own MAC address, which is what MAB is: '
      + 'the endpoint has no supplicant and nothing to say for itself.');
    name.appendChild(same);
  } else {
    name.appendChild(el('span', 'muted', '\u2013'));
  }
  tr.appendChild(name);
  /* Where it came in, one fact to a column. It was one cell to begin with -
     "swje2np GigabitEthernet1/0/41" reads as one place - but a column of
     them does not line up, and the eye reading down a page for one port or
     one access point has to find the start of each of them again. */
  var place = function (said, says, mono) {
    var td = el('td');
    if (said) {
      var bit = el('span', mono === false ? '' : 'mono small', said);
      explain(bit, says);
      td.appendChild(bit);
    } else {
      td.appendChild(el('span', 'muted', '\u2013'));
    }
    tr.appendChild(td);
  };
  /* The device's own address goes with its name wherever it is said - the
     name is what somebody typed into ISE and the address is what is on the
     network, and only the second one is any use at three in the morning. */
  var atWords = r.nad ? ' It answered from <b>' + richText(String(r.nad)) + '</b>.' : '';
  place(r.device, (isWifiKind(kind)
        ? 'The wireless controller that answered for it.'
        : 'The switch it is plugged into, by the name ' + SYS + ' calls it.') + atWords, false);
  var onWords = r.device
    ? ' On <b>' + richText(String(r.device)) + '</b>'
      + (r.nad ? ' (' + richText(String(r.nad)) + ')' : '') + '.'
    : '';
  if (isWifiKind(kind)) {
    place(r.port, 'Which access point heard it. On a controller this is the only thing that '
          + 'says where in the building the machine actually was \u2014 the socket a '
          + 'controller reports is the same tunnel for the whole of it.' + onWords);
    place(r.ssid, 'The wireless network it joined, as the controller reported it.' + onWords);
  } else {
    place(r.port, 'The socket it came in on.' + onWords
          + (SYS === 'NPS' && /[0-9]+\/0\/[0-9]+$/.test(String(r.port || ''))
             ? ' Stack member, 0, port, out of the number NPS wrote down. NPS\u2019s log '
               + 'carries the switch\u2019s number for a port and never its name, so '
               + 'whether it is Gigabit, Fast or Ten Gigabit comes from Settings \u2192 '
               + 'The NPS logs \u2192 What the switches call their ports.'
             : ''));
  }
  if (got) {
    /* What it was given: the authorisation profile, and the VLAN it was put
       in - which on a network of any size is the whole answer to "why can
       this machine not reach anything". */
    tr.appendChild(el('td', '', r.profile || '\u2013'));
    var vlan = el('td');
    /* ISE says the VLAN twice and not always both times: a number in one
       av-pair and a name in the RADIUS answer, and which of them a record
       carries differs from record to record for the very same authorisation
       profile. Both are kept, so this column is the same shape down the page
       instead of a number on one line and a name on the next for one VLAN. */
    var bits = String(r.tkey || '').split('|');
    var number = bits[0] && /^[0-9]+$/.test(bits[0]) ? bits[0] : '';
    var named = (number ? bits.slice(1) : bits).filter(function (b) { return b; })[0] || '';
    /* A record that named the VLAN but did not number it: the number is
       taken from the records of this same site that said both, which is
       ISE's own answer rather than a guess, and the row says so. */
    var matched = false;
    if (!number && named && STATUS && STATUS.vlans && STATUS.vlans[named]) {
      number = STATUS.vlans[named];
      matched = true;
    }
    if (number || named) {
      if (number) {
        var tag = el('span', 'tag ' + (matched ? 'dim' : 'info'), 'VLAN ' + number);
        explain(tag, matched
          ? 'This record named the VLAN but did not number it \u2014 ' + SYS + ' writes one or the '
            + 'other and not always both. The number is the one other records here carry for '
            + '<b>' + named + '</b>, which is ' + SYS + '\u2019s own pairing and not a '
            + 'guess. It is dimmed because it was not on this record.'
          : 'The VLAN this machine was put in, by number, as the switch was told it.'
            + (named ? ' The site also names it <b>' + named + '</b>.' : ''));
        vlan.appendChild(tag);
      }
      if (named) {
        var word = el('span', number ? 'mono small muted' : 'tag info asgiven', named);
        if (number) word.style.marginLeft = '7px';
        explain(word, number
          ? 'What this site calls that VLAN. ' + SYS + ' carries the name as well as the number and '
            + 'not every record carries both.'
          : 'The VLAN this machine was put in, by the name this site gives it. This record '
            + 'carries the name only \u2014 ' + SYS + ' writes the number on some records and the '
            + 'name on others, for the same assignment.');
        vlan.appendChild(word);
      }
    } else {
      vlan.appendChild(el('span', 'muted', '\u2013'));
    }
    tr.appendChild(vlan);
  } else {
    var why = el('td');
    why.appendChild(el('span', '', r.reason || ''));
    if (r.code) why.appendChild(el('span', 'muted small', ' ' + r.code));
    tr.appendChild(why);
  }
  tr.appendChild(el('td', '', r.server || '\u2013'));
  opensWith(tr, '', function () {
    showRecord(got ? 'passed' : 'failed', r.session);
  });
  return tr;
}

/** One line of the token log.

    A different shape again, because a token attempt has no device, no
    tunnel, no profile and usually no address worth printing: what there is
    is a person, what they were shown to have, and which of the token
    servers answered. */
/* ...and what this program writes itself for otp (1.10.226), beside the three
   the handler's refusals are marked with. */
var TOKEN_MARK_OTP = {
  'before-code': ['info', 'no code was looked at',
    'The RADIUS server refused this without a token line and without saying why. otp '
    + 'does that for whatever it refuses before it checks a code \u2014 the directory '
    + 'password, an account outside the realm\u2019s groups, a code that ran out \u2014 '
    + 'and keeps the reason in its own log (otp \u2192 RADIUS) unless it is set to send '
    + 'it back (radius_reject_reason). Nothing here says anything about a token.'],
  'code-unused': ['warn', 'nothing came back',
    'The password was right, a code was sent (or asked for from the app) and the VPN '
    + 'showed its second window \u2014 and nothing was ever typed into it. The SMS or the '
    + 'mail that did not arrive, a person who gave up, or a window closed. The question '
    + 'is in the opened record, with where the code went.']
};
function tokenRow(tr, r, got) {
  tr.appendChild(stampCell(r.ts));
  var who = el('td');
  if (r.username) {
    var name = el('span', 'mono', r.username);
    /* The same name as everywhere else in this program on purpose: the
       token log writes it with a realm on the end and the VPN logs do not,
       and two spellings of one person is two people to every list, every
       search and every history here. */
    whoIsIt(name, r.username, r.realm);
    who.appendChild(name);
  } else {
    who.appendChild(el('span', 'muted', '\u2013'));
  }
  tr.appendChild(who);
  /* What the token server said. Ours in the column, its own words in the
     one beside it - the second is what somebody greps their own logs for. */
  /* Tight, like the cells to its right: the words are a mark of a fixed
     size, and a cell that takes all the slack puts the mark beside it half
     a page away from it. */
  var said = el('td', 'placecell');
  var raw = got ? r.subtype : r.reason;
  var words = got ? tokenWords(r.subtype) : (r.reason || '');
  var tone = tokenTone(got, raw);
  /* A refusal the RADIUS server made after the token server had already
     said yes. The handler in front of the token software asks it first and
     checks the directory afterwards, so an account that is not in the
     group the head end insists on is told `Valid token used` and refused
     anyway. Two different answers to two different questions, and the row
     has to carry both or it says something untrue about one of them. */
  var afterwards = !got && (r.code === 'token-ok' || r.code === 'no-token'
                            || r.code === 'token-lost' || r.code === 'before-code'
                            || r.code === 'code-unused');
  if (afterwards) {
    words = radiusWords(r.reason);
    tone = radiusTone(r.reason);
  }
  /* Every one of them wears its own mark, the ordinary "the token was
     right" in green beside "right, a step out of time" in blue. It was
     said quietly once, on the grounds that a column of a hundred bright
     marks is all anybody sees - but a quiet row and a row with nothing in
     it read the same at a glance, and this column is the one thing a token
     record is actually about. */
  var mark = el('span', 'tag ' + tone, words || '\u2013');
  explain(mark, afterwards ? radiusSays(r.reason) : tokenSays(got, raw));
  said.appendChild(mark);
  tr.appendChild(said);
  /* The second mark, in a cell of its own. Put beside the first it starts
     wherever that one happened to end, and a column of them is ragged -
     which is the same complaint the addresses had, and the same answer:
     a tight cell each, so the eye runs down one column rather than
     hunting along every line. */
  var also = el('td', 'placecell');
  if (afterwards) {
    /* ...and what the token itself made of it. Without this the row reads
       as a token that failed, and the next thing somebody does is go and
       resynchronise a token that is perfectly well - or hunt for a person
       who did nothing at all, when the token server was never asked. */
    var TOKEN_MARK = {
      'token-ok': ['ok', 'the token was right',
        'The token server accepted the number. What refused this sign-in was the RADIUS '
        + 'server in front of it, afterwards and for its own reason \u2014 so there is '
        + 'nothing wrong with the token, and resynchronising it would change nothing.'],
      'no-token': ['warn', 'the token was never asked',
        'There is no token line for this attempt anywhere, because nothing reached the thing '
        + 'that writes them. The RADIUS reply is the whole of what is known about it, and it '
        + 'is here so that a token server nobody can reach is something you can see rather '
        + 'than an empty page.'],
      'token-lost': ['info', 'no token line found',
        'This refusal happened after the token software had answered \u2014 the handler asks '
        + 'it first and checks the directory afterwards \u2014 so a token line for it exists '
        + 'somewhere and has not been matched to this. It says nothing about the number '
        + 'itself, which may well have been right.']
    };
    var how = TOKEN_MARK[r.code] || TOKEN_MARK_OTP[r.code] || TOKEN_MARK['token-ok'];
    var fine = el('span', 'tag ' + how[0]);
    fine.textContent = how[1];
    explain(fine, how[2]);
    also.appendChild(fine);
    tr.classList.add('after-token');
  } else {
    /* How the code came, where the token server asked for it in a second
       window (otp 1.0.76) - by SMS, by mail, from the app - and what it was
       typed for, where that was not signing in (1.10.226). A row that says
       neither is drawn as it always was. */
    var a2 = r.asked || {};
    if (a2.code_by && !(got && tokenKey(r.subtype).indexOf('code sent by') === 0)) {
      var byMark = el('span', 'tag info', CODE_BY_WORDS[a2.code_by] || a2.code_by);
      explain(byMark, codeBySays(a2));
      also.appendChild(byMark);
    }
    if (r.service) {
      var why2 = el('span', 'tag warn', r.service);
      explain(why2, 'Not somebody signing in: the code was typed for this. otp writes the page a '
        + 'new token is made on, an administrator\u2019s test and the like on the same line as '
        + 'a sign-in, with what it was for in the line.');
      also.appendChild(why2);
    }
  }
  tr.appendChild(also);
  if (got) {
    /* The whole account as the token server wrote it, realm and all. The
       refusals have no room for it and no need: the name is the same one. */
    var full = el('td');
    full.appendChild(el('span', 'mono small muted', r.tkey || r.username || '\u2013'));
    tr.appendChild(full);
  }
  /* Three different things, and five cells, because that is what makes a
     column of addresses line up: an address takes a tight cell of its own
     and the word beside it takes another, exactly as the TACACS rows do.
     One cell holding "NAME 10.0.0.1" puts every address at a different
     place on the line, which is what the eye picks up first. */
  var asked = r.asked || null;

  /* 1. The person's own address, and its country. The token log's own
        answer here is always the loopback, because the machine asking is
        whatever stands in front of the token server - so this is out of the
        RADIUS log beside it. */
  var from = el('td', 'addrcell');
  var cc = el('td', 'cccell');
  if (asked && asked.ip) {
    from.appendChild(addrLine(asked.ip));
    if (r.asked_country) cc.appendChild(countryBadge(r.asked_country));
  } else if (r.ip) {
    from.appendChild(addrLine(r.ip));
    if (r.country) cc.appendChild(countryBadge(r.country));
  } else {
    var here = el('span', 'muted small', 'the server itself');
    explain(here, STATUS && STATUS.otp_detail_on
      ? 'The token software was asked over the loopback, by whatever is running beside it. '
        + 'The RADIUS log beside it has the person\u2019s own address, and it is shipped by a '
        + 'script once a minute \u2014 so for the newest attempts it is simply not here yet. '
        + 'Open the record in a minute and it will be.'
      : 'The token software was asked over the loopback, by whatever is running beside it. '
        + 'There is no client address in these records, which is why nothing here is ever '
        + 'counted towards a ban. Switch on the RADIUS log beside it, under Settings '
        + '\u2192 The OTP logs, and the person\u2019s own address is shown here instead.');
    from.appendChild(here);
  }
  tr.appendChild(from);
  tr.appendChild(cc);

  /* 2. The machine the person was on, as AnyConnect named it. The token log
        has no such thing in it at all - this is out of the RADIUS packet
        beside it, exactly as the address above is. */
  tr.appendChild(machineCell(asked && asked.device));

  /* 3. The tunnel group, as the head end named it. On a site where one token
        server answers for the VPN and for the virtual desktops both, this is
        the column that says which of the two a sign-in was. */
  var via = el('td', 'placecell');
  if (asked && asked.tunnel) {
    var tag = el('span', 'alias', asked.tunnel);
    explain(tag, 'The tunnel group this came through, as the head end named it \u2014 which is '
      + 'what says the VPN from the virtual desktops when one token server answers for both.');
    via.appendChild(tag);
  } else {
    via.appendChild(el('span', 'muted', '\u2013'));
  }
  tr.appendChild(via);

  /* 4. The box that asked, and what it is called. This address is the one
        "Where OTP sign-ins come from" is matched against, and the only one:
        the person's address in the first column is wherever they happen to
        be sitting and is not a place anybody names. */
  var box = el('td', 'addrcell');
  var named = el('td', 'placecell');
  if (asked && asked.nas) {
    box.appendChild(el('span', 'mono', asked.nas));
    var place = r.place || {};
    if (place.name) {
      var mark = el('span', 'alias', place.name);
      explain(mark, 'The name given to ' + asked.nas + ' under Settings \u2192 The OTP logs '
        + '\u2192 Where OTP sign-ins come from.');
      named.appendChild(mark);
    } else if (place.usual === false) {
      var odd = el('span', 'tag warn oddmark');
      odd.innerHTML = iconMarkup('pin', 13) + '<span>elsewhere</span>';
      explain(odd, 'This box is not on the list under Settings \u2192 The OTP logs \u2192 '
        + 'Where OTP sign-ins come from. A new thing asking the token server is worth '
        + 'knowing about.');
      named.appendChild(odd);
    }
  } else {
    box.appendChild(el('span', 'muted', '\u2013'));
  }
  tr.appendChild(box);
  tr.appendChild(named);
  tr.appendChild(el('td', '', r.server || '\u2013'));
  opensWith(tr, '', function () {
    showRecord(got ? 'passed' : 'failed', r.session);
  });
  return tr;
}



/* How alarming each of FreeRADIUS's answers is, and what it means. The words
   themselves are put into English by the daemon, which is where the log is
   read; what is here is the reading of them. */
var EDU_TONE = {
  'let in': 'ok',
  'no such account here': 'crit',
  'the password was wrong': 'crit',
  'the home institution refused it': 'warn',
  'nothing was offered to check': 'info',
  'the sign-in did not finish': 'warn'
};
var EDU_SAYS = {
  'let in': 'The server accepted this sign-in. Where the account belongs to another '
    + 'institution it is that institution that said yes; this server only carried the '
    + 'question there and the answer back.',
  'no such account here': 'There is no such account on this server, and the name carried no '
    + 'institution to send the question on to. A controller testing its RADIUS server looks '
    + 'exactly like this, every few seconds, for ever — which is what the list of '
    + 'accounts to leave out under Settings → The eduroam logs is for.',
  'the password was wrong': 'The account exists here and what was offered for it did not '
    + 'match. One or two is somebody typing; the same account all day from one machine is a '
    + 'password that changed and a device that has not been told.',
  'the home institution refused it': 'The name belongs somewhere else, the question was sent '
    + 'there, and that institution said no. Nothing about it can be fixed from here — '
    + 'and nothing about it says anything about this site.',
  'nothing was offered to check': 'The request arrived with no password in it at all. This is '
    + 'what the eduroam monitoring asks, on purpose, to see whether the server answers.',
  'the sign-in did not finish': 'The conversation stopped part way through. A supplicant that '
    + 'gave up, or a machine that walked out of range mid-handshake.'
};

/** One line of an eduroam RADIUS log.

    A shape of its own again. There is no address to show - the only one on
    these lines is the wireless controller - and what a person actually
    wants is who, from which institution, on which access point, and what
    the machine was given. The second half of that is not in the sign-in
    line at all: it comes from the server's own accounting, joined to this
    row by the MAC when the page is drawn, and where it is not there yet
    the cells say so rather than standing empty. */
/* What a site's own TACACS+ daemon turned away.

   A row of its own rather than the plain one because two of the plain one's
   columns mean nothing here - there is no tunnel and no ISE node - and
   because there is no ban button on it: signing in to a switch is never
   judged, and the address on one of these lines is as often as not the jump
   host the whole of the network staff comes through. */
function tacplusRow(tr, r) {
  tr.appendChild(stampCell(r.ts));
  addrPlaceCountry(tr, r.ip, r.country, true, r.ts);
  var who = el('td');
  who.appendChild(el('span', 'mono', r.username || '\u2013'));
  whoIsIt(who, r.username, r.realm);
  tr.appendChild(who);
  var why = el('td');
  var said = String(r.reason || 'refused');
  var mark = el('span', 'tag warn', said);
  explain(mark, 'What the tac_plus daemon said about this attempt, in its own words. '
    + 'Nothing here is ever judged and nothing here can earn anybody a ban \u2014 click '
    + 'the row for the line as it was written.',
    r.subtype ? '<span class="k">' + richText(String(r.subtype)) + '</span>' : '');
  why.appendChild(mark);
  tr.appendChild(why);
  /* Which line of the device they were on: a console, a vty, the web
     interface. It is half of what tells two people at one switch apart. */
  tr.appendChild(el('td', 'mono small', r.port || '\u2013'));
  tr.appendChild(deviceCell(r));
  tr.appendChild(el('td', '', r.server || '\u2013'));
}

function eduroamRow(tr, r, got) {
  var seen = r.seen || {};
  tr.appendChild(stampCell(r.ts));
  var who = el('td');
  if (r.username) {
    var name = el('span', 'mono', r.username);
    /* The name as the server wrote it, realm and all. On eduroam the realm
       is the point: two people at two institutions may be `jk@` and `jk@`
       and be nobody alike. */
    whoIsIt(name, r.username, r.realm);
    who.appendChild(name);
  } else {
    who.appendChild(el('span', 'muted', '–'));
  }
  tr.appendChild(who);
  /* Which institution the name belongs to, which is what the whole of
     eduroam turns on: ours, or somebody else's. */
  var home = el('td');
  var realm = String(r.realm || seen.realm || '');
  if (realm) {
    var pill = el('span', 'mono small', realm);
    explain(pill, 'The institution this name belongs to — what follows the @. A name '
      + 'from another institution is checked by that institution, not here: this server '
      + 'carries the question there and the answer back, and cannot say yes or no itself.');
    home.appendChild(pill);
  } else {
    var none = el('span', 'muted small', 'none given');
    explain(none, 'The name carried no institution at all, so there was nowhere to send it '
      + 'and it could only be looked for here.');
    home.appendChild(none);
  }
  tr.appendChild(home);
  if (!got) {
    /* Why it was refused, in words, with the server's own beside it in the
       opened record. */
    var why = el('td');
    var said = String(r.reason || '');
    var tone = EDU_TONE[said] || 'warn';
    var mark = el('span', 'tag ' + tone, said || '–');
    explain(mark, EDU_SAYS[said] || 'What the RADIUS server said about this attempt.');
    why.appendChild(mark);
    tr.appendChild(why);
  }
  /* The machine. On a refusal that is as far as it goes: a session that
     never started has no accounting behind it. */
  var box = el('td');
  if (r.mac) {
    var mac = el('span', 'mono small', r.mac);
    /* The name is put in through the second argument, which is escaped
       once on the way out. Escaping it here as well - which is what
       richText does - would show somebody a machine called
       <b>Jan&amp;#39;s iPhone</b> in the tooltip. */
    explain(mac, seen.calls_itself
      ? 'The machine’s MAC address. Its own name for itself, which the controller '
        + 'passed on, is <b>' + seen.calls_itself + '</b>.'
      : 'The machine’s MAC address, as the wireless controller reported it.');
    box.appendChild(mac);
    if (got && seen.calls_itself) {
      var calls = el('span', 'muted small', ' ' + seen.calls_itself);
      explain(calls, 'What this machine calls itself — the name it asked DHCP with, '
        + 'passed on by the controller. It is whatever the phone or the laptop is called and '
        + 'is not checked by anybody, so it is a hint and never an identity.');
      box.appendChild(calls);
    }
  } else {
    box.appendChild(el('span', 'muted', '–'));
  }
  tr.appendChild(box);
  if (got) {
    /* Everything from here is the accounting half, and any of it may be
       missing on a sign-in that has only just happened. */
    var fact = function (value, says, missing) {
      var td = el('td');
      if (value) {
        var bit = el('span', 'mono small', value);
        explain(bit, says);
        td.appendChild(bit);
      } else {
        var dash = el('span', 'muted', '–');
        explain(dash, missing);
        td.appendChild(dash);
      }
      tr.appendChild(td);
    };
    var late = ' The accounting record this comes from is written by the controller after '
      + 'the sign-in, so a row that has only just appeared has not got it yet.';
    fact(seen.client, 'The address this machine was given on the visitors’ network.',
         'No accounting record for this machine yet.' + late);
    fact(seen.ap, 'The access point that heard it — which is the room it was in.',
         'Nowhere known yet.' + late);
    fact(seen.ssid, 'The wireless network it joined.', 'Not known yet.' + late);
    var vlan = el('td');
    if (seen.vlan) {
      var tag = el('span', 'tag info', 'VLAN ' + seen.vlan);
      explain(tag, 'The VLAN the controller put this machine in.');
      vlan.appendChild(tag);
    } else {
      vlan.appendChild(el('span', 'muted', '–'));
    }
    tr.appendChild(vlan);
  }
  /* Which controller the request came through, and which of the RADIUS
     servers answered it. */
  var through = el('td');
  var client = String(r.device || seen.device || '');
  if (client) {
    var box2 = el('span', 'mono small', client);
    explain(box2, 'The wireless controller the request came through, by the name the RADIUS '
      + 'server knows it as. This is the only address on one of these lines, which is why '
      + 'nothing here is ever counted towards a ban.');
    through.appendChild(box2);
  } else {
    through.appendChild(el('span', 'muted', '–'));
  }
  tr.appendChild(through);
  tr.appendChild(el('td', '', r.server || '–'));
  opensWith(tr, '', function () {
    showRecord(got ? 'passed' : 'failed', r.session);
  });
  return tr;
}

/* What the token software says, in words, and how alarming each one is. */
var TOKEN_WORDS = {
  'valid token used': ['the token was right', 'ok'],
  'valid token within window size used': ['right, a step out of time', 'info'],
  'scratch-token used': ['a one-off recovery code', 'warn'],
  'not a valid token': ['the token was wrong', 'crit'],
  'token has already been used once': ['that token was used already', 'warn'],
  'pincodes file not found!': ['nothing enrolled for this account', 'warn'],
  /* otp, the replacement for totpcgi (1.10.226), word for word out of its
     source. */
  'code sent by sms accepted': ['a code by SMS was right', 'ok'],
  'code sent by mail accepted': ['a code by mail was right', 'ok'],
  'token confirmed': ['a new token was confirmed', 'info'],
  'no token is enrolled for this account': ['nothing enrolled for this account', 'warn']
};
/* How the code came, out of the question otp asked in its second window. */
var CODE_BY_WORDS = {sms: 'by SMS', mail: 'by mail', app: 'from the app'};
function codeBySays(a) {
  var to = a && a.code_to ? ' to <code>' + wordsIn(a.code_to) + '</code>' : '';
  var how = {sms: 'The code was sent by SMS' + to + ', as otp masks the number.',
             mail: 'The code was mailed' + to + ', as otp masks the address.',
             app: 'The password was right and the code from the app was asked for in a second '
               + 'window.'}[a && a.code_by] || '';
  return how + ' Out of the question otp asked the VPN to show'
    + (a && a.code_asked ? ', at ' + shortStamp(a.code_asked) : '') + '.';
}
/* What the RADIUS server in front of the token software says when it
   refuses, and what each one means. Taken from the handler itself
   (`totpcgi-handler.pl`), which is where every one of these is written: it
   asks the token server FIRST and checks the directory afterwards, so all
   of these happen with the number already accepted. */
var RADIUS_WORDS = {
  'account does not pass ldap group filter(s)': ['not in the group that is allowed', 'crit'],
  'account does not pass ldap user filter': ['the account is not one that may', 'crit'],
  'ldap server(s) have gone away': ['the directory could not be reached', 'warn'],
  'unable to bind to ldap server': ['the directory would not let us in', 'warn'],
  'unknown error': ['refused, and it did not say why', 'warn']
};
var RADIUS_SAYS = {
  'account does not pass ldap group filter(s)': 'The number was right and the sign-in was '
    + 'refused anyway: the account is not in the group the head end insists on. This is a '
    + 'rule about who may use the VPN, not about the token — nothing was wrong with '
    + 'the token.',
  'account does not pass ldap user filter': 'The number was right and the sign-in was refused '
    + 'anyway: the account does not match the filter that says which accounts may sign in at '
    + 'all — disabled, expired, or outside the part of the directory that is allowed.',
  'ldap server(s) have gone away': 'The token was accepted and then the directory could not be '
    + 'reached to check the account against it, so the sign-in was refused. This is the '
    + 'directory being down, not the person doing anything wrong — everybody fails the '
    + 'same way while it lasts.',
  'unable to bind to ldap server': 'The token was accepted and then the token server could not '
    + 'sign in to the directory itself to ask about the account. Its own directory account or '
    + 'password is wrong, or expired. Everybody fails the same way while it lasts.',
  'unknown error': 'The handler refused without saying why. It writes this when it has '
    + 'rejected and nothing has put a reason in the reply.'
};
/* ...and the shapes that are not one fixed sentence. The handler puts
   whatever it was answered into the reply, and when it could not reach the
   token software at all that is LWP's own trouble rather than a status: an
   expired certificate, a name that will not resolve, a refused connection.
   Those matter more than any of the above - nobody can sign in at all
   while one lasts - and the words vary too much to list, so they are
   recognised by what is in them and shown with the whole of what was said
   kept in the panel behind. */
var RADIUS_LIKE = [
  [/certificate|ssl|tls handshake/i, 'the token server\u2019s certificate was refused', 'crit',
   'The handler could not make an HTTPS connection to the token software, because its '
   + 'certificate was not accepted \u2014 expired, or signed by something this machine does '
   + 'not trust, or made out to a different name. <b>Nobody can sign in at all while this '
   + 'lasts</b>, and it has nothing to do with the person or their token: the token server '
   + 'was never even asked.'],
  [/can'?t connect|connection refused|timeout|timed out|no route|resolve/i,
   'the token server could not be reached', 'crit',
   'The handler could not reach the token software at all \u2014 it is not running, or the '
   + 'name does not resolve, or something in between is in the way. <b>Nobody can sign in '
   + 'while this lasts.</b> No token line exists for this attempt anywhere, because nothing '
   + 'got as far as the thing that writes them.'],
  [/^5\d\d\b|internal server error/i, 'the token server answered with an error', 'crit',
   'The token software was reached and answered with an error of its own rather than a '
   + 'verdict. Its own error log is the place to look \u2014 on a suexec site this is most '
   + 'often the CGI being refused by suexec, which reaches here as an empty 500.'],
  [/^4\d\d\b/, 'the token server refused the request', 'warn',
   'The token software answered, and refused the request itself rather than the number.']
];
function radiusLike(said) {
  var text = String(said || '');
  for (var i = 0; i < RADIUS_LIKE.length; i++) {
    if (RADIUS_LIKE[i][0].test(text)) return RADIUS_LIKE[i];
  }
  return null;
}
function radiusKey(said) { return String(said || '').trim().toLowerCase(); }
/* What this program writes itself for otp (1.10.226), where otp sent no
   words back and wrote no token line: [words, tone, what it means]. Apart
   from the handler's own, which are the refusals FreeRADIUS can make. */
var OTP_ALONE = {
  'refused before a code was looked at': ['refused before a code was looked at', 'crit',
    'The RADIUS server said no, with no reason in the '
    + 'reply and no token line anywhere. otp refuses so whatever it refuses before it checks a '
    + 'code: a wrong directory password, an account outside the realm\u2019s groups, a code '
    + 'that ran out, too many codes sent. The reason is in otp\u2019s own log; switch on '
    + '<code>radius_reject_reason</code> there and it comes here as well.'],
  'a code by sms was sent and never typed': ['a code by SMS was sent and never typed', 'warn',
    'The directory password was right and otp sent a '
    + 'code by SMS; the VPN showed its second window and nothing ever came back into it. The '
    + 'message that did not arrive, a person who gave up, or a window closed. The number it '
    + 'went to is in the opened record.'],
  'a code by mail was sent and never typed': ['a code by mail was sent and never typed', 'warn',
    'The directory password was right and otp mailed '
    + 'a code; the VPN showed its second window and nothing ever came back into it. A mail that '
    + 'did not arrive or went to spam, a person who gave up, or a window closed. The address '
    + 'it went to is in the opened record.'],
  'the code from the app was asked for and never typed':
    ['the code from the app was asked for and never typed', 'warn',
    'The directory password was right and '
    + 'otp asked for the code from the app in a second window; nothing ever came back into it.']
};
/** What a RADIUS refusal is called, in words. Anything the handler has not
    got a line for is shown as it said it: an unknown refusal is worth more
    on the page than a blank. */
function radiusWords(said) {
  var own = OTP_ALONE[radiusKey(said)];
  if (own) return own[0];
  var got = RADIUS_WORDS[radiusKey(said)];
  if (got) return got[0];
  var like = radiusLike(said);
  return like ? like[1] : String(said || '');
}
function radiusTone(said) {
  var own = OTP_ALONE[radiusKey(said)];
  if (own) return own[1];
  var got = RADIUS_WORDS[radiusKey(said)];
  if (got) return got[1];
  var like = radiusLike(said);
  return like ? like[2] : 'crit';
}
function radiusSays(said) {
  var own = OTP_ALONE[radiusKey(said)];
  if (own) return own[2];
  var got = RADIUS_SAYS[radiusKey(said)];
  if (got) return got + '\n\nIn its own words: <code>' + (said || '') + '</code>';
  var like = radiusLike(said);
  if (like) return like[3] + '\n\nIn its own words: <code>' + (said || '') + '</code>';
  return 'The RADIUS server in front of the token software refused the sign-in, in these '
    + 'words: <code>' + (said || '') + '</code>\nThe token itself is a separate question, '
    + 'and the mark beside this says what the token server made of it.';
}

var TOKEN_SAYS = {
  'valid token used': 'The number shown matched the one expected at that moment.',
  'valid token within window size used': 'The number was right but a step early or late \u2014 '
    + 'the clock on the token has drifted, or it was typed as it changed. Ordinary on its own; '
    + 'the same person every time means their token needs resynchronising.',
  'scratch-token used': 'One of the printed one-off codes was used instead of the token. '
    + 'People use these when they have lost the thing that makes the numbers, so it is worth '
    + 'knowing who did and when \u2014 and each one works only once.',
  'not a valid token': 'The number did not match. Twice and then right is somebody typing '
    + 'while it changed; all day is a token out of step, or somebody guessing.',
  'token has already been used once': 'That exact number had been used before. The software '
    + 'refuses a repeat on purpose: it is what stops somebody replaying a number they saw.',
  'pincodes file not found!': 'This account has nothing enrolled on the token server at all. '
    + 'Not a wrong number \u2014 a person who was never set up, or was set up somewhere else.',
  'code sent by sms accepted': 'otp sent a code by SMS after the directory password, and the '
    + 'one typed into the VPN\u2019s second window was it.',
  'code sent by mail accepted': 'otp mailed a code after the directory password, and the one '
    + 'typed into the VPN\u2019s second window was it.',
  'token confirmed': 'A new token was confirmed with its first code \u2014 on otp\u2019s '
    + 'enrolment page, or by an administrator. Not a sign-in.',
  'no token is enrolled for this account': 'This account has nothing enrolled on the token '
    + 'server at all. Not a wrong number \u2014 a person who was never set up.'
};
function tokenKey(said) { return String(said || '').trim().toLowerCase(); }
function tokenWords(said) {
  var got = TOKEN_WORDS[tokenKey(said)];
  return got ? got[0] : String(said || '');
}
function tokenTone(got, said) {
  var found = TOKEN_WORDS[tokenKey(said)];
  if (found) return found[1] === 'ok' ? 'ok' : (found[1] === 'crit' ? 'crit'
             : (found[1] === 'warn' ? 'warn' : 'info'));
  return got ? 'ok' : 'crit';
}
function tokenSays(got, said) {
  return TOKEN_SAYS[tokenKey(said)]
    || (got ? 'The token server accepted this, in these words: ' + (said || '')
            : 'The token server refused it, in these words: ' + (said || ''));
}

/* ==========================================================================
   What the directory says about a name
   --------------------------------------------------------------------------
   A name in a log is a string until somebody knows whose it is. The
   directory already knows - whether the account is locked out, whether it is
   switched off, when the password expires, whose it is and which groups it
   is in - and that is the difference between "forty failures for jnovak" and
   "jnovak is locked out, which is why".

   Everything here READS. There is no write to a directory anywhere in this
   program: no password reset, no unlock, no group change, not one attribute.
   The account this signs in to the directory with needs nothing beyond the
   right to read, and if somebody gives it more this will still never use it.

   When the directory is switched off, none of this appears at all and every
   page is exactly what it was before.
   ========================================================================== */

/** A little button after a name that asks the directory about it. Draws
    nothing when there is no directory to ask. */
/* The same name in the other directory. Two domains that both hold an
   account called `jnovak` hold two accounts, not one seen twice: different
   groups, different passwords, and one of them can be locked out while the
   other signs in perfectly well. So it is drawn apart from the first, under
   its own directory's name, with what that directory says about it. */
function alsoBlock(o) {
  var box = el('div', 'alsodir');
  var head = el('div', 'alsohead');
  head.appendChild(el('b', '', o.where_words || 'the other directory'));
  if (o.domain) head.appendChild(el('span', 'alias', o.domain));
  (o.marks || []).slice(0, 3).forEach(function (m) {
    var tag = el('span', 'tag ' + (m.tone || 'info'), m.words);
    if (m.says) explain(tag, m.says);
    head.appendChild(tag);
  });
  box.appendChild(head);
  if (o.title) box.appendChild(el('div', 'fwhoname', o.title));
  /* All of them, not the first six. The directory above this one draws
     every fact it has, and two accounts in two domains drawn side by side
     with different numbers of facts are two things nobody can compare. */
  (o.facts || []).forEach(function (f) {
    var one = el('span', 'fwhofact');
    one.appendChild(el('b', '', f.words));
    var said = el('span', '');
    if (f.kind === 'when' && f.said && f.said.at) {
      said.textContent = shortStamp(f.said.at);
      explain(one, (f.says ? f.says + '\n\n' : '') + stamp(f.said.at)
              + '  \u2014 ' + ago(f.said.at));
    } else {
      said.textContent = typeof f.said === 'string' ? f.said : String(f.said);
      if (f.says) explain(one, f.says);
    }
    one.appendChild(said);
    box.appendChild(one);
  });
  if (o.group_count) {
    var groups = el('span', 'fwhofact');
    groups.appendChild(el('b', '', 'Groups'));
    groups.appendChild(el('span', '', num(o.group_count)));
    explain(groups, 'The groups this account is in <b>in that directory</b>, which are not '
      + 'the ones above:\n\n'
      + (o.groups || []).slice(0, 24).map(function (g) {
          return '<code>' + g.name + '</code>'; }).join('\n'));
    box.appendChild(groups);
  }
  return box;
}

function whoIsIt(after, name, realm) {
  if (!STATUS || !STATUS.directory_on || !name) return;
  var button = el('button', 'whobtn');
  button.type = 'button';
  button.innerHTML = iconMarkup('person', 13);
  explain(button, 'Ask the directory who this is: whether the account is locked out or '
    + 'switched off, when its password expires, and which groups it is in. It only reads \u2014 '
    + 'nothing in the directory is ever changed from here.');
  button.onclick = function (e) {
    e.stopPropagation();
    /* The record says which domain ISE resolved this person in, where it
       says anything, and that is which directory to ask - rather than
       asking every directory there is and taking the first that answers. */
    showPerson(name, '', realm);
  };
  after.appendChild(document.createTextNode(' '));
  after.appendChild(button);
}

/** Ask about one name and draw what came back.

    `only` asks one directory and no other - what the button on a
    directory's own settings page means by "look a name up". */
var WHO_ASKED = 0;
function showPerson(name, only, realm) {
  var words = only === 'directory2' ? 'the second directory' : 'the directory';
  /* A directory takes as long as it takes. Somebody who gets bored, closes
     this and carries on must not have it reappear over whatever they are
     looking at now - and two names asked about quickly must not answer in
     the wrong order. */
  var mine = ++WHO_ASKED;
  modal(only === 'directory2' ? 'The second directory' : 'The directory', function (body) {
    var wait = el('p', 'center');
    wait.appendChild(el('span', 'spin'));
    wait.appendChild(document.createTextNode(' Asking ' + words + ' about '
                                             + name + '\u2026'));
    body.appendChild(wait);
  });
  var ticket = modalTicket();
  api('who&name=' + encodeURIComponent(name)
      + (only ? '&which=' + encodeURIComponent(only) : '')
      + (realm ? '&realm=' + encodeURIComponent(realm) : '')).then(function (d) {
    if (mine !== WHO_ASKED || !modalStill(ticket)) return;
    drawPerson(name, d);
  }).catch(function (e) {
    if (mine !== WHO_ASKED || !modalStill(ticket)) return;
    modal(words.charAt(0).toUpperCase() + words.slice(1), function (body) {
      body.appendChild(el('p', 'note', 'It could not be asked: ' + e.message));
    });
  });
}

function drawPerson(name, d) {
  modal((d.title || d.name || name) + (d.machine ? ' \u00b7 a machine' : ''), function (body) {
    var lede = el('p', 'note');
    if (!d.on) {
      lede.textContent = 'Active Directory is not switched on here, so there is nothing to '
        + 'ask. It is under Settings \u2192 Active Directory.';
      body.appendChild(lede);
      return;
    }
    if (d.trouble) {
      lede.innerHTML = 'The directory could not answer: ' + richText(d.trouble);
      body.appendChild(lede);
      return;
    }
    if (!d.found) {
      lede.innerHTML = (d.asked_both ? 'Neither directory has an account called'
                        : ((d.only === 'directory2' ? 'The second directory has'
                            : 'The directory has') + ' no account called'))
        + ' <span class="mono">'
        + richText(d.name || name) + '</span> under the base it is asked about. On a failed '
        + 'attempt that is worth knowing on its own: a name that does not exist is somebody '
        + 'working through a list rather than somebody mistyping their own \u2014 or an '
        + 'account that HAS been here and was deleted, which the controllers wrote down '
        + 'even though the directory no longer holds a word of it.';
      body.appendChild(lede);
      if ((STATUS || {}).winsec_on) {
        var story = cmdButton('Was it ever here? Who made it and who deleted it',
                              'shield', '');
        story.style.marginTop = '10px';
        story.onclick = function () { winPeekLife(d.name || name, d.domain || d.realm || ''); };
        body.appendChild(story);
        explainWhatWasDrawn(body);
      }
      return;
    }
    lede.innerHTML = 'Read from ' + richText(d.where_words || 'the directory') + ' just now'
      + (d.where === 'directory2' && !d.only
         ? ' \u2014 the first one does not have this name' : '')
      + (d.only ? ', which is the only one that was asked' : '')
      + (!d.only && d.matched && d.realm
         ? ', which is where the record says this person was resolved ('
           + richText(d.realm) + ')' : '')
      + '. <b>Nothing here changes anything there</b>: this program only ever reads a '
      + 'directory.';
    body.appendChild(lede);

    /* The state first, because it is the answer to the question somebody
       opened this to ask. */
    var marks = el('div', 'personmarks');
    (d.marks || []).forEach(function (m) {
      var tag = el('span', 'tag ' + (m.tone || 'info'), m.words);
      explain(tag, m.says || '');
      marks.appendChild(tag);
    });
    body.appendChild(marks);

    var head = el('div');
    head.style.marginTop = '14px';
    (d.facts || []).forEach(function (f) {
      var line = el('div', 'kv');
      line.appendChild(el('span', 'k', f.words));
      var v = el('span', 'v');
      if (f.kind === 'when' && f.said && f.said.at) {
        v.appendChild(document.createTextNode(stamp(f.said.at)));
        var when = el('span', 'muted small', '  ' + ago(f.said.at));
        v.appendChild(when);
      } else {
        v.textContent = typeof f.said === 'string' ? f.said : String(f.said);
      }
      if (f.says) explain(line, f.says);
      line.appendChild(v);
      head.appendChild(line);
    });
    if (d.dn) {
      var where = el('div', 'kv');
      where.appendChild(el('span', 'k', 'Where in the directory'));
      var dn = el('span', 'v mono small');
      dn.textContent = d.dn;
      where.appendChild(dn);
      head.appendChild(where);
    }
    body.appendChild(head);

    var groups = d.groups || [];
    if (groups.length) {
      var fold = el('details', 'fold');
      var sum = el('summary', '', 'The groups it is in');
      sum.appendChild(el('span', 'n', num(d.group_count || groups.length) + ' group(s)'));
      fold.appendChild(sum);
      var inner = el('div', 'body');
      /* One a line, with where it lives beside it.

         Run together as pills they were a paragraph of names: "Certificate
         users Disk J - OVSU Disk Q M365_WO_booking" reads as one thing with
         spaces in it, and a group whose own name has spaces in it - which
         most of them do - cannot be told from the next one along. A line
         each also leaves room for the distinguished name, which is the half
         that says WHICH "Disk Q" this is, and which was on the hover where
         nobody would find it. */
      var list = el('div', 'grouplist');
      groups.forEach(function (g) {
        var row = el('div', 'one');
        row.appendChild(el('span', 'nm mono', g.name));
        if (g.dn) row.appendChild(el('span', 'dn mono small', g.dn));
        list.appendChild(row);
      });
      inner.appendChild(list);
      fold.appendChild(inner);
      body.appendChild(fold);
    }
    explainWhatWasDrawn(body);
  }, [
    // Not `close`: this opens a popup of its own, and closing this one
    // afterwards closed that one too - the press did nothing at all.
    {words: 'What this name has been doing here', icon: 'history',
     go: function () { lookUpUser(d.name || name); }},
    /* ...and the other half, which the directory cannot answer at all: who
       made this account, who changed it, who unlocked it, who deleted it.
       Offered even where the directory found nothing, because that is
       exactly when it is the only answer there is. */
    {words: 'Who made it, changed it, unlocked it', icon: 'shield',
     go: function () { winPeekLife(d.name || name, d.domain || d.realm || ''); }},
    {spacer: true}, {words: 'Close', close: true}
  ]);
}

/* ---- the groups, found rather than typed -------------------------------- */
function drawDirGroups(groups) {
  var host = $('dir-groups');
  clear(host);
  if (!groups.length) {
    host.appendChild(el('p', 'note', 'The directory has no groups under that base — or the '
      + 'base is not where they live.'));
    return;
  }
  var lead = el('p', 'note');
  lead.innerHTML = '<b>' + num(groups.length) + '</b> group(s). Press one to put it in a role; '
    + 'press it again to take it out. More than one group may hold a role.'
    /* A domain of five thousand groups is read by typing part of a name
       into the box, not by paging through two hundred pages - and being
       told that the list stops somewhere is the difference between doing
       that and believing the group is not there. */
    + (groups.length >= 5000
       ? ' This is as many as are fetched at once \u2014 there may be more. Type part of a '
         + 'name into <i>Find the groups</i> above to look for one by name.' : '');
  host.appendChild(lead);
  var paint = function () {
    var admin = dirWanted('directory_admin_group');
    var banner = dirWanted('directory_banadmin_group');
    var reader = dirWanted('directory_readonly_group');
    Array.prototype.forEach.call(host.querySelectorAll('.dgroup'), function (row) {
      var dn = row.dataset.dn.toLowerCase();
      var name = row.dataset.name.toLowerCase();
      row.classList.toggle('is-admin', admin.indexOf(dn) >= 0 || admin.indexOf(name) >= 0);
      row.classList.toggle('is-read', reader.indexOf(dn) >= 0 || reader.indexOf(name) >= 0);
      row.classList.toggle('is-ban', banner.indexOf(dn) >= 0 || banner.indexOf(name) >= 0);
    });
  };
  host.appendChild(listView({
    key: 'dir-groups', rows: groups, per: 25, barFrom: 8,
    placeholder: 'a group name…',
    hay: function (g) { return [g.name, g.dn, g.says].join(' '); },
    draw: function (page, into) {
      into.appendChild(listTable(['Group', 'What it is for', 'Role here'], page, function (g) {
        var tr = el('tr', 'dgroup');
        tr.dataset.dn = g.dn;
        tr.dataset.name = g.name;
        var n = el('td');
        n.appendChild(el('span', '', g.name));
        n.appendChild(el('span', 'd mono', g.dn));
        tr.appendChild(n);
        tr.appendChild(el('td', 'dim', g.says || ''));
        var pick = el('td', 'bancell act');
        if (ADMIN) {
          [['directory_admin_group', 'Full admin', 'shield'],
           ['directory_banadmin_group', 'Ban admin', 'ban'],
           ['directory_readonly_group', 'Read only', 'eye']].forEach(function (one) {
            var b = cmdButton(one[1], one[2], 'small');
            b.onclick = function (e) {
              e.stopPropagation();
              dirToggle(one[0], g.dn, g.name);
              paint();
            };
            explain(b, 'Put <b>' + g.name + '</b> in this role, or take it out of it. It is a '
              + 'change like any other on this page — nothing happens until you save.');
            pick.appendChild(b);
          });
        }
        tr.appendChild(pick);
        return tr;
      }, 'plain'));
      paint();
    }
  }));
  paint();
}

/** What a role's groups are set to right now, in the editor, lower-cased. */
function dirWanted(key) {
  var input = $('set-' + key);
  var said = input ? (input._get ? input._get() : input.value) : '';
  return String(said || '').split(/[;\n]/).map(function (x) {
    return x.trim().toLowerCase();
  }).filter(Boolean);
}

/** Put a group into a role, or take it out, in the settings editor. */
function dirToggle(key, dn, name) {
  var input = $('set-' + key);
  if (!input) { toast('open the settings above first'); return; }
  var have = String(input.value || '').split(/[;\n]/).map(function (x) { return x.trim(); })
    .filter(Boolean);
  /* The group by its DN or by its name, as the list marks it (1.10.198): a
     setting naming it by its name was not found, and the DN put in beside. */
  var same = function (one) {
    var low = one.toLowerCase();
    return low === String(dn).toLowerCase() || (name && low === String(name).toLowerCase());
  };
  var at = have.some(same) ? 0 : -1;
  if (at >= 0) have = have.filter(function (one) { return !same(one); }); else have.push(dn);
  input.value = have.join('; ');
  input.dispatchEvent(new Event('input', {bubbles: true}));
  input.dispatchEvent(new Event('change', {bubbles: true}));
  toast(at >= 0 ? 'taken out — save to keep it' : 'put in — save to keep it');
}

if ($('dir-find')) {
  $('dir-find').onclick = function () {
    busy($('dir-find'), true);
    api('directory', {groups: true, like: ''}).then(function (d) {
      drawDirGroups(d.groups || []);
      toast(num((d.groups || []).length) + ' group(s) found', 'good');
    }).catch(oops).then(function () { busy($('dir-find'), false); });
  };

  $('dir-check').onclick = function () {
    modal('Checking the directory', function (body) {
      body.appendChild(el('p', 'center muted', 'Asking\u2026'));
    }, [{words: 'Close', close: true}]);
    var ticket = modalTicket();
    api('directory', {check: true}).then(function (d) {
      if (modalStill(ticket)) showDirCheck(d);
    }).catch(function (e) {
      if (!modalStill(ticket)) return;
      var body = $('modal-body');
      clear(body);
      body.appendChild(el('p', 'center bad', String((e && e.message) || e)));
    });
  };

  $('dir-try').onclick = function () {
    var name, pass;
    modal('Try a sign-in', function (body) {
      body.appendChild(el('p', 'note', 'Nothing is signed in and no session is made. This asks '
        + 'the directory the same question a real sign-in asks, and shows the whole answer — '
        + 'including which groups came back and what role they earn.'));
      var one = el('div', 'set-item');
      one.appendChild(el('label', '', 'The name they would type'));
      name = el('input');
      name.type = 'text';
      name.placeholder = 'jnovak';
      one.appendChild(name);
      body.appendChild(one);
      var two = el('div', 'set-item');
      two.appendChild(el('label', '', 'Their password'));
      pass = el('input');
      pass.type = 'password';
      pass.autocomplete = 'off';
      two.appendChild(pass);
      body.appendChild(two);
      setTimeout(function () { name.focus(); }, 60);
    }, [{words: 'Try it', cls: 'primary', icon: 'person', go: function () {
      var ticket = modalTicket();
      api('directory', {try_name: name.value, try_password: pass.value}).then(function (d) {
        if (!modalStill(ticket)) return;
        var said = d.tried || {};
        var body = $('modal-body');
        clear(body);
        if (said.ok) {
          body.appendChild(peekFacts([
            ['They are', said.display || said.name],
            ['Role here', roleWords(said.role)],
            ['In the directory', said.dn || '']
          ]));
          var g = el('p', 'note');
          g.innerHTML = '<b>Groups the directory gave back:</b><br>'
            + richText((said.groups || []).join('\n'));
          body.appendChild(g);
        } else {
          var bad = el('p', said.missing ? 'note' : 'note bad');
          bad.textContent = said.said || 'it did not work';
          body.appendChild(bad);
          if (said.missing) {
            body.appendChild(el('p', 'note', 'That is not a fault: a name the directory has '
              + 'never heard of is looked for in the local accounts instead.'));
          }
        }
      }).catch(oops);
    }}, {words: 'Close', close: true}]);
  };
}

/* ---- the rail ------------------------------------------------------------ */
function showPane(name, quietly) {
  /* A group of settings that lives inside another pane - the second
     firewall inside the router's, the published list inside Banning - is
     shown by showing the pane it is in. */
  if (!$('pane-' + name) && $('sect-' + name)) {
    var inside = $('sect-' + name).closest('.ctl-pane');
    if (inside && inside.id) name = inside.id.replace(/^pane-/, '');
  }
  PANE = name;
  Array.prototype.forEach.call(document.querySelectorAll('#ctl-nav button[data-pane]'),
    function (b) { b.classList.toggle('on', b.dataset.pane === name); });
  Array.prototype.forEach.call(document.querySelectorAll('.ctl-pane'), function (p) {
    p.hidden = p.id !== 'pane-' + name;
  });
  writeHash();
  if (name === 'rescan') loadRescan();
  if (name === 'banning') loadBanfeed();
  if (name === 'router') loadMikrotik();
  if (name === 'geo') { loadGeo(); loadGeolist(); }
  if (name === 'white') loadWhitelist();
  if (name === 'updates') loadUpdates();
  if (name === 'lists') loadUpdates();
  if (name === 'people') loadUsers();
  if (name === 'dir' || name === 'dir2') loadDirectory();
  if (name === 'db') loadDb();
  if (name === 'fw') loadFw();
  if (name === 'tls') loadTls();
  if (name === 'acme' && typeof loadAcme === 'function') loadAcme();
  else if (typeof acPoll === 'function') acPoll(false);
  if (name === 'upgrade') loadUpgrade();
  if (name === 'network' && typeof loadNet === 'function') loadNet();
  if (name === 'time' && typeof loadNtp === 'function') loadNtp();
  if (name === 'power' && typeof loadPower === 'function') loadPower();
  if (name === 'sshkeys' && typeof loadSshKeys === 'function') loadSshKeys();
  if (name === 'otp' && typeof loadOtpTls === 'function') loadOtpTls();
  if (name === 'osup' && typeof loadOsup === 'function') loadOsup();
  else if (typeof ouPoll === 'function') ouPoll(false);
  if (name === 'backup' && typeof loadRbackup === 'function') loadRbackup();
  if (name === 'winsec') drawRollup();
  if (name === 'about') drawAbout();
  markDirtyCount();
  if (!quietly) window.scrollTo({top: 0, behavior: 'smooth'});
}
Array.prototype.forEach.call(document.querySelectorAll('#ctl-nav button[data-pane]'),
  function (b) {
    b.dataset.dressed = '1';
    setButtonIcon(b, b.dataset.icon, b.textContent.trim());
    /* the count chip goes back on after the icon rewrote the innards */
    if (b.dataset.pane === 'white') {
      var n = el('span', 'n');
      n.id = 'white-n';
      b.appendChild(n);
    }
    b.onclick = function () { showPane(b.dataset.pane); };
  });

/* Finding one setting among sixty, by name or by what it says. */
$('ctl-find').addEventListener('input', function () {
  var want = $('ctl-find').value.trim().toLowerCase();
  var box = $('ctl-found');
  clear(box);
  if (!want) { box.hidden = true; return; }
  var hits = (SETTINGS && SETTINGS.settings || []).filter(function (s) {
    return (s.key + ' ' + (s.name || '') + ' ' + (s.says || ''))
      .toLowerCase().indexOf(want) >= 0;
  }).slice(0, 14);
  if (!hits.length) {
    box.appendChild(el('div', 'ctl-none', 'Nothing matches "' + want + '".'));
    box.hidden = false;
    return;
  }
  hits.forEach(function (s) {
    var b = el('button', 'ctl-hit');
    b.type = 'button';
    b.appendChild(el('span', 'ctl-hit-t', s.name || s.key));
    b.appendChild(el('span', 'ctl-hit-w', s.key));
    b.onclick = function () {
      var pane = Object.keys(PANES).filter(function (p) {
        return PANES[p].indexOf(s.key) >= 0;
      })[0] || 'about';
      showPane(pane);
      box.hidden = true;
      $('ctl-find').value = '';
      setTimeout(function () {
        var item = document.querySelector('.set-item[data-key="' + s.key + '"]');
        if (!item) return;
        item.scrollIntoView({block: 'center', behavior: 'smooth'});
        item.style.transition = 'box-shadow .3s';
        item.style.boxShadow = '0 0 0 2px var(--info)';
        item.style.borderRadius = '10px';
        setTimeout(function () { item.style.boxShadow = ''; }, 1600);
      }, 60);
    };
    box.appendChild(b);
  });
  box.hidden = false;
});
document.addEventListener('click', function (e) {
  if (!e.target.closest || !e.target.closest('.ctl-find-wrap')) $('ctl-found').hidden = true;
});

/* ---- the ladder -----------------------------------------------------------
   "10, 60, 1440, forever" is four numbers and a word, and every one of them is
   a chance to be wrong: minutes or hours, is 1440 a day, does the word have to
   be spelt that way, and what happens to the steps after it. So it is built
   instead of typed - a ready-made ladder for the houses that want one of the
   usual four, and a step at a time for anybody who does not. What is stored is
   the same comma-separated value the daemon has always read. */
var LADDER_STEPS = [
  [5, '5 min'], [10, '10 min'], [15, '15 min'], [30, '30 min'], [60, '1 hour'],
  [180, '3 hours'], [360, '6 hours'], [720, '12 hours'], [1440, '1 day'],
  [4320, '3 days'], [10080, '1 week'], [43200, '30 days'], [0, 'for good']
];
var LADDER_PRESETS = [
  ['', 'No ladder — every block is the single length above'],
  ['10, 60, 1440, forever', 'Gentle, then final — 10 min · 1 h · 1 day · for good'],
  ['10, 60, 1440', 'Gentle — 10 min · 1 h · 1 day, then the same again'],
  ['60, 1440, 10080, forever', 'Firm — 1 h · 1 day · 1 week · for good'],
  ['1440, forever', 'Short-tempered — 1 day, then for good'],
  ['custom', 'Something else…']
];
function ladderRead(text) {
  var out = [];
  String(text || '').replace(/;/g, ',').split(',').forEach(function (piece) {
    piece = piece.trim().toLowerCase();
    if (!piece) return;
    if (/^(forever|for good|permanent|always)$/.test(piece)) { out.push(0); return; }
    var n = parseInt(piece, 10);
    if (n > 0) out.push(n);
  });
  return out;
}
function ladderWrite(steps) {
  return steps.map(function (n) { return n === 0 ? 'forever' : String(n); }).join(', ');
}
function ladderName(n) {
  var hit = LADDER_STEPS.filter(function (s) { return s[0] === n; })[0];
  return hit ? hit[1] : n + ' min';
}
var LADDER_ORDINALS = ['1st', '2nd', '3rd', '4th', '5th', '6th', '7th', '8th', '9th', '10th',
                       '11th', '12th'];
/** The ladder in words, into `box`: each ordinal and each length a piece of
    its own, so that another language says its own ordinals - one string
    of the whole was a sentence no translation could match. */
function ladderWords(steps, box) {
  clear(box);
  if (!steps.length) {
    box.textContent = 'no ladder — every block is the single length above';
    return box;
  }
  steps.forEach(function (n, i) {
    if (i) box.appendChild(document.createTextNode(' · '));
    box.appendChild(el('span', '', LADDER_ORDINALS[i] || (i + 1) + '.'));
    box.appendChild(document.createTextNode(' '));
    box.appendChild(el('span', '', ladderName(n)));
  });
  if (steps.indexOf(0) < 0) {
    box.appendChild(el('span', '', ' · then the last step again, every time after'));
  }
  return box;
}
function fillSelect(box, pairs, chosen) {
  clear(box);
  pairs.forEach(function (p) {
    var o = document.createElement('option');
    o.value = String(p[0]);
    o.textContent = p[1];
    box.appendChild(o);
  });
  box.value = String(chosen === undefined || chosen === null ? '' : chosen);
}
/* ---- the addresses people sign in from, and what they are called -------
   One line of `192.168.251.10=LogHost, 10.9.0.4=Jump2` is quick to store and
   horrible to type: the address and the name run together, and getting one
   equals sign or one comma wrong quietly turns two places into one. So it is
   a row per place - an address, a name, a way to take it away - and a button
   to add another. What it hands back is still that one line. */
function placesRead(text) {
  var out = [];
  String(text || '').split(',').forEach(function (piece) {
    piece = piece.trim();
    if (!piece) return;
    var at = piece.indexOf('=');
    out.push(at < 0 ? {ip: piece, name: ''}
      : {ip: piece.slice(0, at).trim(), name: piece.slice(at + 1).trim()});
  });
  return out;
}
function placesWrite(rows) {
  return rows.filter(function (r) { return String(r.ip || '').trim(); })
    .map(function (r) {
      var ip = String(r.ip).trim();
      var name = String(r.name || '').trim();
      return name ? ip + '=' + name : ip;
    }).join(', ');
}

function placesEditor(s) {
  var box = el('div', 'places');
  var rows = placesRead(s.value);
  var body = el('div', 'places-rows');
  var said = el('div', 'ladder-says muted small');
  var item = null;

  var settle = function () {
    var n = rows.filter(function (r) { return String(r.ip || '').trim(); }).length;
    said.textContent = !n ? 'Nobody has said where sign-ins come from, so nothing is marked.'
      : (n === 1 ? 'One place. A sign-in from anywhere else is marked.'
         : n + ' places. A sign-in from anywhere else is marked.');
    item = item || box.closest('.set-item');
    if (item) markDirty(item, s);
    applyOnlyWhen();
  };

  var paint = function () {
    clear(body);
    rows.forEach(function (one, index) {
      var row = el('div', 'places-row');
      var where = el('input');
      where.type = 'text';
      where.placeholder = '192.168.251.10';
      where.value = one.ip || '';
      where.disabled = !ADMIN;
      where.className = 'mono';
      explain(where, 'The address people reach the switches from. One address, not a range.');
      where.oninput = function () { one.ip = where.value; settle(); };
      row.appendChild(where);
      var called = el('input');
      called.type = 'text';
      called.placeholder = 'LogHost';
      called.value = one.name || '';
      called.disabled = !ADMIN;
      explain(called, 'What that machine is called. The name is shown beside the address '
        + 'wherever it appears, so a page of sign-ins says <b>LogHost</b> rather than an '
        + 'address somebody has to recognise. It may be left empty.');
      called.oninput = function () { one.name = called.value; settle(); };
      row.appendChild(called);
      var drop = iconButton('trash', 'Take this place away');
      drop.disabled = !ADMIN;
      drop.onclick = function () { rows.splice(index, 1); settle(); paint(); };
      row.appendChild(drop);
      body.appendChild(row);
    });
    if (!rows.length) {
      body.appendChild(el('div', 'fold-none', 'No place yet. Add the machine or the network '
        + 'people normally reach the switches from.'));
    }
    var add = cmdButton('Add a place', 'add', 'small');
    add.disabled = !ADMIN || rows.length >= 20;
    explain(add, 'One more place people may sign in from \u2014 an address, a subnet or a '
      + 'run of them. A sign-in from any of them is ordinary; one from anywhere else is '
      + 'marked.');
    add.onclick = function () { rows.push({ip: '', name: ''}); settle(); paint(); };
    var bar = el('div', 'btnrow');
    bar.appendChild(add);
    body.appendChild(bar);
    explainWhatWasDrawn(body);
  };

  box.appendChild(body);
  box.appendChild(said);
  box._get = function () { return placesWrite(rows); };
  box._set = function (v) { rows = placesRead(v); paint(); settle(); };
  paint();
  settle();
  return box;
}

/* The name servers, one to a row, in the order they are asked.

   The same shape as the places above, for the same reason: a list of things
   typed into one box is a list nobody can see the shape of, and this one
   has an order that matters - the first server that hands over a name is
   the answer, so which row is first is a decision rather than a detail.
   Written back out as the plain `10.0.0.1, 10.0.0.2:5353` the daemon
   reads, so nothing else has to know this editor exists. */
function dnsRead(text) {
  var out = [];
  String(text || '').split(/[,\n]+/).forEach(function (piece) {
    piece = piece.trim();
    if (!piece) return;
    var host = piece, port = '';
    if (piece.charAt(0) === '[') {
      var end = piece.indexOf(']');
      host = piece.slice(1, end < 0 ? piece.length : end);
      var rest = end < 0 ? '' : piece.slice(end + 1);
      if (rest.charAt(0) === ':') port = rest.slice(1);
    } else if ((piece.match(/:/g) || []).length === 1) {
      var at = piece.indexOf(':');
      host = piece.slice(0, at);
      port = piece.slice(at + 1);
    }
    out.push({ip: host.trim(), port: String(port || '').trim()});
  });
  return out;
}
function dnsWrite(rows) {
  return rows.filter(function (r) { return String(r.ip || '').trim(); })
    .map(function (r) {
      var ip = String(r.ip).trim();
      var port = String(r.port || '').trim();
      if (!port || port === '53') return ip.indexOf(':') >= 0 ? '[' + ip + ']' : ip;
      return (ip.indexOf(':') >= 0 ? '[' + ip + ']' : ip) + ':' + port;
    }).join(', ');
}

/* ---- the end of a Cisco access list, typed by hand ----------------------
   Everything above it in the file is this machine's: a deny line per address
   that is out for good, made afresh every time somebody asks for the file.
   What goes here is what follows them, and it is whatever a site's own lists
   end with - usually a permit, because an access list ends with an implicit
   deny and a list with no permit at the bottom stops everything.

   Read by the daemon as it is typed, not by this page: the same reading that
   refuses it on save, and the same one the command line uses, so there is
   one answer to "would a router take this" and not three. */
function aclEditor(s) {
  var six = s.key === 'ios_acl_tail6';
  var wrap = el('div', 'acledit');
  var box = document.createElement('textarea');
  box.className = 'aclbox';
  box.rows = 5;
  box.spellcheck = false;
  box.autocapitalize = 'off';
  box.autocomplete = 'off';
  box.setAttribute('aria-label', s.name || s.key);
  box.value = (s.value === null || s.value === undefined) ? '' : String(s.value);
  box.placeholder = six ? 'permit ipv6 any any'
                        : 'deny   udp any any eq snmp\npermit ip any any';
  box.disabled = !ADMIN;
  wrap.appendChild(box);
  var said = el('div', 'aclsaid');
  wrap.appendChild(said);
  var soon = null, seq = 0;

  function look() {
    var mine = ++seq;
    api('acltry', {text: box.value, family: six ? 'ipv6' : 'ipv4'}).then(function (d) {
      if (mine !== seq) return;                     // somebody typed on
      clear(said);
      var bad = d.faults || [];
      box.classList.toggle('wrong', !!bad.length);
      if (bad.length) {
        bad.slice(0, 6).forEach(function (one) {
          var row = el('div');
          row.appendChild(el('span', 'bad', 'line ' + one.n + ': '));
          row.appendChild(el('span', 'line', String(one.line || '').trim()));
          row.appendChild(document.createTextNode(' — ' + one.why));
          said.appendChild(row);
        });
        if (bad.length > 6) {
          said.appendChild(el('div', 'bad', '…and ' + (bad.length - 6) + ' more'));
        }
        said.appendChild(el('div', '', 'This will not save until every line reads as an '
          + 'access list. A router meeting one it will not take stops there, with half the '
          + 'list on it.'));
        return;
      }
      var ok = el('div');
      ok.appendChild(el('span', 'good', (d.lines || []).length + ' line(s), and every one of '
        + 'them reads as an access list. '));
      ok.appendChild(document.createTextNode('This is how the file will end, under the deny '
        + 'lines for the addresses that are out for good:'));
      said.appendChild(ok);
      var pre = el('div', 'aclpreview');
      pre.appendChild(el('span', 'mine',
        (six ? 'ipv6 access-list ' : 'ip access-list extended ') + (d.name || '') + '\n'
        + (six ? ' deny   ipv6 host 2001:db8::5 any\n' : ' deny   ip host 203.0.113.9 any\n')
        + ' …\n'));
      pre.appendChild(document.createTextNode((d.lines || []).join('\n') + '\n'));
      said.appendChild(pre);
    }).catch(function () { /* a preview is never worth an error on the page */ });
  }

  box.addEventListener('input', function () {
    clearTimeout(soon);
    soon = setTimeout(look, 400);
  });
  wrap._get = function () { return box.value; };
  wrap._set = function (v) {
    box.value = (v === null || v === undefined) ? '' : String(v);
    look();
  };
  look();
  return wrap;
}

function dnsEditor(s) {
  var box = el('div', 'places');
  var rows = dnsRead(s.value);
  var body = el('div', 'places-rows');
  var said = el('div', 'ladder-says muted small');
  var item = null;

  var settle = function () {
    var n = rows.filter(function (r) { return String(r.ip || '').trim(); }).length;
    said.textContent = !n
      ? 'No name server to ask, so no address will be turned into a name.'
      : (n === 1
         ? 'One server. It is asked, and whatever it says is all there is.'
         : n + ' servers, asked in this order. The first one that hands over a name is the '
           + 'answer; one that does not answer, refuses, or has never heard of the address '
           + 'is passed over.');
    item = item || box.closest('.set-item');
    if (item) markDirty(item, s);
    applyOnlyWhen();
  };

  var paint = function () {
    clear(body);
    rows.forEach(function (one, index) {
      var row = el('div', 'dnsrow');
      var nth = el('span', 'nth', String(index + 1) + '.');
      explain(nth, index === 0
        ? 'Asked first. On a site with one reverse zone this is the only one that ever '
          + 'answers; on a site with several it is the one most addresses are in.'
        : 'Asked when the ' + (index === 1 ? 'one' : 'ones') + ' above it did not hand over '
          + 'a name \u2014 either because they could not be reached or because they have '
          + 'never heard of that address.');
      row.appendChild(nth);
      var where = el('input');
      where.type = 'text';
      where.placeholder = '10.0.0.1';
      where.value = one.ip || '';
      where.disabled = !ADMIN;
      where.className = 'mono';
      explain(where, 'The name server\u2019s own address. An address, not a name \u2014 '
        + 'this is the thing that turns names into addresses, so it cannot be asked for '
        + 'one of its own.');
      where.oninput = function () { one.ip = where.value; settle(); };
      row.appendChild(where);
      var port = el('input');
      port.type = 'text';
      port.placeholder = '53';
      port.value = one.port || '';
      port.disabled = !ADMIN;
      port.className = 'mono';
      explain(port, 'Its port, where it is not the usual 53. Left empty it is 53.');
      port.oninput = function () { one.port = port.value; settle(); };
      row.appendChild(port);
      var up = iconButton('up', 'Ask this one earlier');
      up.disabled = !ADMIN || index === 0;
      up.onclick = function () {
        var was = rows[index - 1];
        rows[index - 1] = rows[index];
        rows[index] = was;
        settle();
        paint();
      };
      row.appendChild(up);
      var drop = iconButton('trash', 'Take this server away');
      drop.disabled = !ADMIN;
      drop.onclick = function () { rows.splice(index, 1); settle(); paint(); };
      row.appendChild(drop);
      body.appendChild(row);
    });
    if (!rows.length) {
      body.appendChild(el('div', 'fold-none', 'No name server yet. Add the one that holds '
        + 'your reverse zone \u2014 and the one that holds the DMZ\u2019s, if that is '
        + 'somewhere else.'));
    }
    var add = cmdButton('Add a name server', 'add', 'small');
    add.disabled = !ADMIN || rows.length >= 8;
    explain(add, 'One more server to ask, after the ones above it. They are asked in this '
      + 'order and the first with a name for the address wins, which is how a site whose '
      + 'DMZ zone lives on another machine gets both halves.');
    add.onclick = function () { rows.push({ip: '', port: ''}); settle(); paint(); };
    var bar = el('div', 'btnrow');
    bar.appendChild(add);
    body.appendChild(bar);
    explainWhatWasDrawn(body);
  };

  box.appendChild(body);
  box.appendChild(said);
  box._get = function () { return dnsWrite(rows); };
  box._set = function (v) { rows = dnsRead(v); paint(); settle(); };
  paint();
  settle();
  return box;
}

/* What a list setting is FOR, one row at a time: what each row is called,
   what an empty one should say, and what it looks like when it is right.
   Without this a list editor is a column of boxes with no idea what belongs
   in them, which is exactly what a comma-separated line was. */
var LIST_ROWS = {
  ise_paths: ['folder', '/var/log/remote/ise1',
              'One folder per ISE node, the way rsyslog files them.'],
  otp_paths: ['folder', '/var/log/remote/otp',
              'One folder per token server.'],
  eduroam_paths: ['folder', '/var/log/remote/eduroam',
                  'One folder per RADIUS server, or a path to the file itself.'],
  winsec_paths: ['folder', '/var/log/remote/dc01',
                 'One folder per domain controller, the way rsyslog files them.'],
  winsec_controllers: ['controller', 'dc01',
                       'The SHORT NAME is enough \u2014 \u201cdc01\u201d. '
                       + '\u201cDC01$\u201d, \u201cdc01.example.com\u201d and '
                       + '\u201cEXAMPLE\\DC01$\u201d are understood as the same machine, '
                       + 'and an address on its own is looked up here.'],
  ptr_servers: ['server', '10.0.0.1', ''],
  watch_devices: ['device', 'ftd1', 'The name ISE calls it by.'],
  passed_devices: ['device', 'ftd1', 'The name ISE calls it by.']
};

/** A list setting as a list: one row per entry, and a button to add one.

    A line reading `/var/log/remote/a, /var/log/remote/b, /var/log/remote/c`
    in a box eighty pixels wide is a list nobody can read, edit or count, and
    every one of these settings is a list of paths or names that a site adds
    to one at a time. One row each, a bin beside each, a button underneath.
    Whatever a row holds is trimmed and the empty ones are dropped, so an
    empty row left behind by somebody who changed their mind is not a setting.
*/
function listEditor(s) {
  var about = LIST_ROWS[s.key] || ['entry', '', ''];
  var box = el('div', 'places');
  var rows = (s.value || []).map(function (v) { return String(v); });
  var body = el('div', 'places-rows');
  var item = null;

  var settle = function () {
    item = item || box.closest('.set-item');
    if (item) markDirty(item, s);
    applyOnlyWhen();
  };

  var paint = function () {
    clear(body);
    rows.forEach(function (one, index) {
      var row = el('div', 'dnsrow');
      row.appendChild(el('span', 'nth', String(index + 1) + '.'));
      var field = el('input');
      field.type = 'text';
      field.className = 'mono';
      field.placeholder = about[1];
      field.value = one;
      field.disabled = !ADMIN;
      if (about[2]) explain(field, about[2]);
      field.oninput = function () { rows[index] = field.value; settle(); };
      row.appendChild(field);
      var drop = iconButton('trash', 'Take this ' + about[0] + ' away');
      drop.disabled = !ADMIN;
      drop.onclick = function () { rows.splice(index, 1); settle(); paint(); };
      row.appendChild(drop);
      body.appendChild(row);
    });
    if (!rows.length) {
      body.appendChild(el('div', 'fold-none',
        'Nothing here yet. Add the first ' + about[0] + '.'));
    }
    var add = cmdButton(/^[aeiou]/i.test(about[0]) ? 'Add an ' + about[0] : 'Add a ' + about[0],
                        'add', 'small');
    add.disabled = !ADMIN || rows.length >= 24;
    if (about[2]) explain(add, about[2]);
    add.onclick = function () {
      rows.push('');
      settle();
      paint();
      var last = body.querySelectorAll('input');
      if (last.length) last[last.length - 1].focus();
    };
    var bar = el('div', 'btnrow');
    bar.appendChild(add);
    body.appendChild(bar);
    explainWhatWasDrawn(body);
  };

  box.appendChild(body);
  /* Empty rows are not entries. Somebody who pressed the button and then
     thought better of it has left a blank box, not a folder called "". */
  box._get = function () {
    return rows.map(function (v) { return String(v).trim(); })
               .filter(function (v) { return v; });
  };
  box._set = function (v) {
    rows = (Array.isArray(v) ? v : String(v || '').split(','))
      .map(function (one) { return String(one).trim(); })
      .filter(function (one) { return one; });
    paint();
    settle();
  };
  paint();
  return box;
}

/** The firewalls whose logs are read, one row each.

    Every row is one firewall: the name the Traffic page shows it by (and
    switches between them by), which kind of firewall writes the log, the
    folder (or the one file) it is in, and which files there are its. */
/** A MikroTik's API, as part of its row of the firewalls (1.10.211): a
    switch, and once it is on how to reach the router, a way to try it, a
    certificate made for it and what to type on the router. Read-only: the
    account it signs in with may only read, and nothing is ever written to
    the router from here. Independent of the banning's own router settings. */
function rosApiPanel(one, index, rows, settle, paint, s) {
  var cfg = one.api || (one.api = rosApiRow({}));
  var name = String(one.name || '').trim();
  /* The name as it is when a button is pressed, not when this was drawn
     (1.10.217): a row named after it was drawn kept its certificate, key and
     authority under no name - or under the old one. */
  var nameNow = function () { return String(one.name || '').trim(); };
  var panelTest = null;
  var words = name ? 'the MikroTik ' + name : 'this MikroTik';
  var state = ((s.api_states || {})[name]) || null;
  var pin = (s.api_pins || {})[name] || '';
  var kept = (s.api_certs || {})[name] || null;
  /* Read over ssh (1.10.211): a key of its own, kept as the banning's is. */
  var ssh = cfg.mode === 'ssh';
  var sshKey = (s.api_keys || {})[name] || null;
  /* One section, as the banning's "Reaching the firewall" is drawn (the
     same fields, the same lines of state, the same key panel), with its
     switch at the top: off, the switch is all there is of it. */
  var card = el('div', 'card full rosapi');
  var h = el('h2');
  h.appendChild(el('span', '', ssh ? 'Reading ' + words + ' over ssh'
    : 'Reading ' + words + ' through its API'));
  var when = el('span', 'right', state && state.at ? 'read ' + ago(state.at) : '');
  h.appendChild(when);
  card.appendChild(h);
  card.appendChild(el('p', 'note', 'Its own connection, its own account that may only read, '
    + 'and its own settings: nothing here is the banning’s, and nothing is ever written '
    + 'to the router from here.'));

  /* A field the way every setting is drawn: its name with the i, the box,
     and what it does underneath. */
  var item = function (label, input, says, bool) {
    var box = el('div', 'set-item' + (bool ? ' set-bool' : ''));
    var lab = el('label', '', label);
    var info = el('span', 'iinfo', 'i');
    info.setAttribute('role', 'button');
    info.tabIndex = 0;
    explain(info, says);
    explain(lab, says);
    lab.appendChild(info);
    box.appendChild(lab);
    box.appendChild(input);
    box.appendChild(saysBlock(says));
    return box;
  };
  var grid = el('div', 'set-grid');
  var sw = el('label', 'sw');
  var tick = document.createElement('input');
  tick.type = 'checkbox';
  tick.checked = !!cfg.on;
  tick.disabled = !ADMIN;
  sw.appendChild(tick);
  sw.appendChild(el('span', 'knob'));
  tick.onchange = function () { cfg.on = tick.checked ? 1 : 0; settle(); paint(); };
  grid.appendChild(item('Read more of it through its API or over ssh', sw, 'How much went where (the bytes '
    + 'of every connection), who is on its VPN, which interfaces and tunnels are up, how the '
    + 'router is. Read-only, over one session, a few questions a minute. Off, nothing reaches '
    + 'the router and everything set here is kept for switching on again.', true));
  card.appendChild(grid);
  if (!cfg.on) return card;

  var text = function (key, holder, type) {
    var input = el('input');
    input.type = type || 'text';
    input.value = String(cfg[key] === undefined ? '' : cfg[key]);
    input.placeholder = holder;
    input.disabled = !ADMIN;
    if (key === 'password') {
      /* As every other password in Settings: shown back by its last two
         letters, left alone to keep it, typed over to replace it. */
      input.autocomplete = 'off';
      input.title = 'Shown back by its last two letters only. Leave it alone to keep the one '
        + 'that is set; type a new one to replace it.';
    }
    input.oninput = function () {
      cfg[key] = type === 'number' ? Number(input.value) : input.value;
      settle();
      /* "Try reaching it" as soon as there is an address (1.10.217). */
      if (key === 'host' && panelTest) panelTest.disabled = !ADMIN || !input.value.trim();
    };
    if (key === 'password') {
      /* Pressed, the dots are chosen whole, so what is typed replaces them
         (1.10.217) rather than being added after them and thrown away. */
      input.onfocus = function () {
        if (input.value.indexOf('\u2022') === 0) input.select();
      };
    }
    return input;
  };
  grid.appendChild(item('The router’s address', text('host', '192.0.2.1'),
    'Where this machine reaches the router’s API - its address or name. Not the '
    + 'banning’s router settings: this is a session of its own, with an account that may '
    + 'only read.'));
  var pick = el('select');
  [['pin', 'TLS, its certificate pinned (api-ssl, 8729)'],
   ['ca', 'TLS, its certificate checked by an authority (api-ssl, 8729)'],
   ['anon', 'TLS without a certificate (api-ssl, 8729)'],
   ['plain', 'Unencrypted (api, 8728)'],
   ['ssh', 'Over ssh, with a key or a password (22)']].forEach(function (o) {
    var opt = document.createElement('option');
    opt.value = o[0];
    opt.textContent = o[1];
    pick.appendChild(opt);
  });
  pick.value = cfg.mode;
  pick.disabled = !ADMIN;
  pick.onchange = function () {
    var was = cfg.mode;
    cfg.mode = pick.value;
    /* The port each way is reached on, where it was the one of the way
       before: one somebody typed is theirs. */
    var usual = function (m) { return m === 'plain' ? 8728 : (m === 'ssh' ? 22 : 8729); };
    if (!cfg.port || Number(cfg.port) === usual(was)) cfg.port = usual(cfg.mode);
    settle();
    paint();
  };
  grid.appendChild(item('How it is reached', pick, 'Pinned: the router’s api-ssl '
    + 'certificate is remembered by its fingerprint at the first connection - or made here and '
    + 'pinned before it - and a router answering with another one is refused. Without a '
    + 'certificate: encrypted, but nothing says it is that router (RouterOS speaks it when '
    + 'api-ssl has no certificate). Unencrypted: the password crosses the network in the clear '
    + '- only on a network that is yours alone. Checked by an authority: as a browser checks '
    + 'a site - signed by an authority this machine trusts, or by yours, and for the router\u2019s '
    + 'name. Over ssh: the same questions asked on its '
    + 'console, signed in with a key made here - as the banning signs in - or a password.'));
  grid.appendChild(item(ssh ? 'Its ssh port' : 'Its API port',
    text('port', ssh ? '22' : '8729', 'number'), ssh ? 'Its ssh port.' : 'The API’s port on '
    + 'the router: 8729 for api-ssl, 8728 for the plain API, or what /ip service says.'));
  grid.appendChild(item('Sign in to it as', text('user', 'isemon-read'), 'An account on the '
    + 'router in a group that may only read and use the API - "How to set it up on the '
    + 'router" says how. Never the administrator’s.'));
  if (cfg.mode === 'ca') {
    var vsw = el('label', 'sw');
    var vtick = document.createElement('input');
    vtick.type = 'checkbox';
    vtick.checked = Number(cfg.verify === undefined ? 1 : cfg.verify) !== 0;
    vtick.disabled = !ADMIN;
    vsw.appendChild(vtick);
    vsw.appendChild(el('span', 'knob'));
    vtick.onchange = function () { cfg.verify = vtick.checked ? 1 : 0; settle(); paint(); };
    var vItem = item('Check its certificate', vsw, 'On, the router\u2019s certificate has to be '
      + 'signed by an authority and carry its name, or nothing is asked of it. Off, it is still '
      + 'encrypted but any certificate is taken - and so anybody in between could answer '
      + 'instead of the router and be given its password.', true);
    if (!vtick.checked) {
      var vwhy = el('div', 'says rosapi-warn', 'Not checked: anybody in between could answer '
        + 'instead of the router.');
      vItem.appendChild(vwhy);
    }
    grid.appendChild(vItem);
    grid.appendChild(item('The name on its certificate', text('tls_name',
      cfg.host || 'gw.example.com'), 'The name the router\u2019s certificate is checked for. '
      + 'Empty, its address above - write the name here when it is reached by its address and '
      + 'the certificate carries a name (gw.example.com).'));
  }
  if (ssh) {
    var how = el('select');
    [['key', 'key'], ['password', 'password']].forEach(function (o) {
      var opt = document.createElement('option');
      opt.value = o[0];
      opt.textContent = o[1];
      how.appendChild(opt);
    });
    how.value = cfg.auth === 'password' ? 'password' : 'key';
    how.disabled = !ADMIN;
    how.onchange = function () { cfg.auth = how.value; settle(); paint(); };
    grid.appendChild(item('Sign in with', how, 'With a key this daemon holds, or with a '
      + 'password.'));
  }
  var pw = text('password', cfg.password_set ? 'set — leave as it is to keep it' : 'not set');
  var pwItem = item('Its password', pw, 'The account’s password. Kept sealed here and shown '
    + 'back by its last two letters only; leave it as it is to keep the one that is set.');
  if (ssh && cfg.auth !== 'password') {
    /* As the banning's: there, but asleep, and saying why. */
    pwItem.classList.add('asleep');
    pw.disabled = true;
    var why = el('div', 'says rosapi-warn', 'Not in use while Sign in with is not '
      + '"password".');
    pwItem.appendChild(why);
  }
  grid.appendChild(pwItem);
  grid.appendChild(item('Read it every (s)', text('every', '30', 'number'), 'How often the '
    + 'connections are read: the ones gone since the last look are the sessions that ended. '
    + 'Shorter catches more of the short ones; longer is less work for the router. The VPN and '
    + 'the interfaces are read about once a minute, how the router is every five. 10 to 600.'));

  /* ---- how it is, as the banning's router is said ---- */
  var kv = el('div', 'rosapi-state');
  var tag = el('span');
  if (!state) tag.appendChild(el('span', 'tag dim', cfg.host ? 'not saved yet' : 'not set up'));
  else if (state.connected) tag.appendChild(el('span', 'tag ok', 'connected'));
  else tag.appendChild(el('span', 'tag crit', 'trouble'));
  kvInto(kv, 'Right now', tag, state && !state.connected ? (state.trouble || '') : '',
    'Not set up means the switch is on but there is no address yet; not saved yet, that '
    + 'what is typed here has not been saved. Connected means the session is open and being '
    + 'read. Trouble means the last time this tried to reach it, it could not - the words '
    + 'beside it are what the router or the network said.');
  kvInto(kv, 'Address', cfg.host ? cfg.host + ':' + (cfg.port || '') : '–',
    state && state.connected ? (state.identity || '') + (state.version ? ', RouterOS '
      + state.version : '') + (state.board ? ' on ' + state.board : '') : '',
    'Where this machine reaches ' + words + '’s API, and what it says it is.');
  kvInto(kv, 'Signing in as', cfg.user || '–', '', 'The account it signs in with. It '
    + 'should be in a group that may read and use the API and nothing else.');
  kvInto(kv, 'Last read', state && state.at ? stamp(state.at) : 'never',
    state && state.at ? ago(state.at) : '', 'When the router’s connections were last read.');
  if (state && state.connected) {
    kvInto(kv, 'Connections', num(state.conns || 0) + ' open',
      num(state.ended || 0) + ' ended since the start' + (state.vpn !== undefined
        ? ' · ' + num(state.vpn) + ' on the VPN' : ''),
      'Open: in its table at the last look. Ended: gone from it since, written as sessions '
      + 'with their bytes.');
  }
  if (state && state.skipped) kvInto(kv, 'Left out', state.skipped);
  if (ssh) {
    kvInto(kv, 'Signing in with', cfg.auth === 'password' ? 'a password'
      : (sshKey && sshKey.key ? 'a key this machine holds' : 'a key — but there is none yet'), '',
      'A key is better: it never leaves this machine, the router holds only its public '
      + 'half, and it cannot be read out of the settings by anybody who gets this far.');
  } else if (cfg.mode === 'ca') {
    var caKept = (s.api_cas || {})[name] || null;
    kvInto(kv, 'Its certificate', Number(cfg.verify === undefined ? 1 : cfg.verify) === 0
      ? 'not checked' : (caKept ? 'checked by your authority'
      : 'checked by the authorities this machine trusts'), cfg.tls_name || cfg.host || '',
      'Signed by an authority - yours, given below, or one this machine trusts - and for '
      + 'the name it is checked for.');
  } else kvInto(kv, 'Its certificate', cfg.mode !== 'pin' ? 'not checked'
      : (kept ? 'one this machine holds' : (pin ? 'pinned at the first connection'
         : 'none yet — pinned at the first connection')), pin,
    'With "pinned", the certificate the router answers with has to be this one, by its '
    + 'fingerprint: made here, one of your own, or the one it answered with the first time.');
  card.appendChild(kv);
  explainWhatWasDrawn(kv);

  var guideRow = el('div', 'btnrow');
  guideRow.style.marginTop = '12px';
  var guide = cmdButton('How to set it up on the router…', 'info');
  explain(guide, 'How to set the router up for this, step by step, with its commands: the '
    + 'account that may only read, its certificate, and the API.');
  guide.onclick = function () { rosApiGuide(cfg, kept || pin); };
  guideRow.appendChild(guide);
  card.appendChild(guideRow);

  var test = cmdButton('Try reaching it', 'pulse', 'primary');
  test.disabled = !ADMIN || !cfg.host;
  panelTest = test;
  explain(test, 'Sign in to the router with what is typed above and ask it its name, its '
    + 'version and how many connections it holds. Nothing is written and nothing is changed.');
  var need = function () {
    if (nameNow()) return true;
    toast('name the firewall first', 'bad');
    return false;
  };
  test.onclick = function () { rosApiTry(test, cfg, nameNow(), words, need); };
  if (ssh) {
    card.appendChild(rosSshKeyPanel(cfg, nameNow, words, s, sshKey, test, need, paint));
    return card;
  }
  if (cfg.mode === 'ca') {
    card.appendChild(rosApiCaPanel(cfg, nameNow, words, s, test, need, paint));
    return card;
  }

  /* ---- the certificate, as the banning's key ---- */
  var keybox = el('div', 'subpanel');
  keybox.style.marginTop = '16px';
  var keynote = el('p', 'note');
  keynote.innerHTML = 'Made here, and its key never leaves this machine except when you '
    + 'download it. Put the <b>file</b> on the router.';
  explain(keynote, 'The router’s api-ssl certificate, made here and pinned: from the first '
    + 'connection this machine knows it is that router. Download it - the certificate and its '
    + 'key in one file - and import it on the router.');
  keybox.appendChild(keynote);
  var noPin = cfg.mode !== 'pin';
  if (noPin) {
    keybox.appendChild(el('p', 'btnhelp', 'Not in use while How it is reached is not '
      + '“pinned”.')).style.color = 'var(--warn)';
  }
  var bar = el('div', 'btnrow');
  var may = ADMIN && !noPin;
  var mk = cmdButton('Make a certificate', 'key', 'admin-only');
  var own = cmdButton('Use my own', 'upload', 'admin-only');
  var down = cmdButton('Download it', 'download', 'admin-only');
  var forget = cmdButton('Forget it', 'forget', 'danger admin-only');
  mk.disabled = !may;
  own.disabled = !may;
  down.disabled = !may || !(kept && kept.key);
  forget.disabled = !ADMIN || !(kept || pin);
  explain(mk, 'Make a fresh key and certificate here, for this router’s address. It is '
    + 'pinned at once, so until the new one is on the router this will not reach it.');
  explain(own, 'Use a certificate you already have: paste it, with its key if you want to '
    + 'download them again from here. It is pinned at once.');
  explain(down, 'Download the certificate and its key as one file, isemon-api.pem, to import on '
    + 'the router. That it was downloaded, and by whom, is written into Events.');
  explain(forget, 'Delete the certificate and the pin from this machine. The next connection '
    + 'pins whatever the router answers with.');
  [mk, own, down, forget].forEach(function (b) { bar.appendChild(b); });
  bar.appendChild(el('span', 'spacer'));
  bar.appendChild(test);
  keybox.appendChild(bar);
  var keyHost = el('div');
  keyHost.style.marginTop = '12px';
  if (kept && kept.cert) {
    /* One line, as the ssh key's public half is: what goes ON the router,
       and a click on it downloads it. */
    var file = kept.key ? 'isemon-api.pem' : 'isemon-api.crt';
    keyHost.appendChild(el('p', 'btnhelp', 'The file for the router. Click it to download.'));
    var code = el('code', 'copyme', file + ' ' + pin);
    explain(code, 'Click to download. This is the file that goes ON ' + words + ' - the '
      + 'certificate' + (kept.key ? ' and its key' : '') + ' - and its fingerprint is the one '
      + 'pinned here. On RouterOS: put it in <i>Files</i>, then <code>/certificate import '
      + 'file-name=' + file + ' passphrase=""</code> and <code>/ip service set api-ssl '
      + 'certificate=' + file + '_0</code>');
    code.onclick = function () {
      api('rosapi', {do: 'download', name: nameNow()}).then(rosApiSave).catch(oops);
    };
    keyHost.appendChild(code);
  } else if (pin) {
    keyHost.appendChild(el('p', 'btnhelp', 'Pinned at the first connection: ' + pin + '.'));
  } else {
    keyHost.appendChild(el('p', 'btnhelp', 'No certificate yet — make one, or let it pin '
      + 'the router’s own at the first connection.'));
  }
  keybox.appendChild(keyHost);
  card.appendChild(keybox);

  var after = function (d) {
    s.api_pins = s.api_pins || {};
    s.api_certs = s.api_certs || {};
    s.api_pins[nameNow()] = d.fingerprint;
    s.api_certs[nameNow()] = {cert: d.cert, key: !!d.has_key};
    paint();
  };
  mk.onclick = function () {
    if (!need()) return;
    if (!cfg.host) { toast('the router’s address first', 'bad'); return; }
    confirmThen('Make a certificate for ' + words,
      'A fresh key and certificate are made here, for <span class="mono">' + htmlText(cfg.host)
      + '</span>, and pinned.<br><br><b>Any certificate pinned for it is replaced</b>, so '
      + 'until the new one is on the router this will not reach it.',
      'Make one', function () {
        api('rosapi', {do: 'cert', name: nameNow(), host: cfg.host}).then(function (d) {
          toast('a new certificate was made — download it and put it on the router',
                'good');
          after(d);
        }).catch(oops);
      });
  };
  own.onclick = function () {
    if (!need()) return;
    modal('Use my own certificate for ' + words, function (body) {
      var p = el('p', 'note');
      p.innerHTML = 'A PEM certificate, whole, including its <span class="mono">BEGIN</span> '
        + 'and <span class="mono">END</span> lines - with its key under it if it should be '
        + 'downloadable from here again. The key is kept sealed and never shown back.';
      body.appendChild(p);
      var area = el('textarea');
      area.rows = 11;
      area.id = 'rosapi-paste-area';
      area.spellcheck = false;
      area.placeholder = '-----BEGIN CERTIFICATE-----';
      body.appendChild(area);
      setTimeout(function () { area.focus(); }, 60);
    }, [
      {words: 'Cancel', close: true},
      {words: 'Keep this certificate', cls: 'primary', close: true, go: function () {
        api('rosapi', {do: 'paste', name: nameNow(), pem: $('rosapi-paste-area').value})
          .then(function (d) {
            toast('the certificate was stored and pinned', 'good');
            after(d);
          }).catch(oops);
      }}
    ]);
  };
  down.onclick = function () {
    if (!need()) return;
    confirmThen('Download the certificate for ' + words,
      'The certificate and its <b>private key</b> leave this machine as one file, '
      + '<span class="mono">isemon-api.pem</span>. That it was downloaded, and by whom, is '
      + 'written into Events.',
      'Download it', function () {
        api('rosapi', {do: 'download', name: nameNow()}).then(rosApiSave).catch(oops);
      });
  };
  forget.onclick = function () {
    if (!need()) return;
    confirmThen('Forget the certificate for ' + words,
      'The certificate, its key and the pin are deleted from this machine. The next connection '
      + 'pins whatever the router answers with - for a certificate replaced on purpose.',
      'Forget it', function () {
        api('rosapi', {do: 'forget', name: nameNow()}).then(function () {
          if (s.api_pins) delete s.api_pins[nameNow()];
          if (s.api_certs) delete s.api_certs[nameNow()];
          toast('the certificate is gone');
          paint();
        }).catch(oops);
      });
  };
  return card;
}

/** "Try reaching it" for a router read through its API or over ssh. */
function rosApiTry(test, cfg, name, words, need) {
  if (!need()) return;
  var overSsh = cfg.mode === 'ssh';
  busy(test, true);
  api('rosapi', {do: 'test', name: name, api: cfg}).then(function (d) {
    if (!d.reached) throw new Error(d.trouble || 'it could not be reached');
    modal('It answered', function (body) {
      body.appendChild(el('p', 'note', overSsh
        ? 'This signed in to ' + words + ' over ssh, asked its name, its version and its '
          + 'connections, and came back. Nothing was written and nothing was changed.'
        : 'This signed in to ' + words + '’s API, asked its name, its version and its '
          + 'connections, and came back. Nothing was written and nothing was changed.'));
      body.appendChild(saidBox((d.identity || '?') + ', RouterOS ' + (d.version || '?')
        + (d.board ? ' on ' + d.board : '')
        + (d.connections !== null && d.connections !== undefined
           ? ' · ' + num(d.connections) + ' connection(s) in its table' : '')
        + (d.group ? ' · the account is in ' + d.group : '')
        + (d.fingerprint_words ? ' · its certificate ' + d.fingerprint_words
           + (d.pinned ? ' (the one pinned)' : ' (pinned at the first connection once it is '
              + 'saved and switched on)') : '')));
      if (d.can_write) {
        body.appendChild(el('p', 'note', 'That account’s group may change things ('
          + (d.policy || []).join(', ') + '): give it one that may only read and use the '
          + 'API.'));
      }
    }, [{words: 'Good', cls: 'primary', close: true}], true);
  }).catch(function (e) {
    modal('It did not answer', function (body) {
      body.appendChild(el('p', 'note', 'What came back when reaching ' + words + ', whole:'));
      body.appendChild(saidBox(String((e && e.message) || e)));
      body.appendChild(el('p', 'note', overSsh
        ? 'The usual causes, in the order they usually are: the public half of the key is not '
          + 'on that router yet; the account has no ssh permission; the address or port is '
          + 'wrong; or it is not reachable from this machine at all.'
        : 'The usual causes, in the order they usually are: api-ssl (or api) is not switched '
          + 'on, or not for this machine’s address; the account or its password is wrong; '
          + 'the router answers with a certificate other than the one pinned; or the address or '
          + 'port is wrong.'));
    }, [{words: 'Close', close: true}], true);
  }).then(function () { busy(test, false); });
}

/** The authority a router's certificate is checked by (1.10.213): the
    ones this machine trusts, or one of yours - the same panel as the key's. */
function rosApiCaPanel(cfg, nameNow, words, s, test, need, paint) {
  var name = nameNow();
  var box = el('div', 'subpanel');
  box.style.marginTop = '16px';
  var caKept = (s.api_cas || {})[name] || null;
  var checks = Number(cfg.verify === undefined ? 1 : cfg.verify) !== 0;
  var note = el('p', 'note');
  note.innerHTML = 'The router’s certificate is checked as a browser checks a site: by the '
    + '<b>authority</b> that signed it, and for its name.';
  explain(note, 'An authority this machine trusts already (a public one, such as Let’s '
    + 'Encrypt) needs nothing here. One of your own - a company CA, or the router’s own CA '
    + 'made with /certificate sign - is given here: its certificate, not its key.');
  box.appendChild(note);
  if (!checks) {
    box.appendChild(el('p', 'btnhelp', 'Not in use while Check its certificate is off.'))
      .style.color = 'var(--warn)';
  }
  var bar = el('div', 'btnrow');
  var own = cmdButton('Use my own authority', 'upload', 'admin-only');
  var forget = cmdButton('Forget it', 'forget', 'danger admin-only');
  own.disabled = !ADMIN || !checks;
  forget.disabled = !ADMIN || !caKept;
  explain(own, 'Paste the certificate of the authority that signed the router’s, as PEM - '
    + 'more than one if there is a chain. Only these are trusted for this router then.');
  explain(forget, 'Go back to the authorities this machine trusts.');
  bar.appendChild(own);
  bar.appendChild(forget);
  bar.appendChild(el('span', 'spacer'));
  bar.appendChild(test);
  box.appendChild(bar);
  var host = el('div');
  host.style.marginTop = '12px';
  host.appendChild(el('p', 'btnhelp', caKept
    ? 'Your authority: ' + caKept.n + ' certificate(s), ' + caKept.fingerprint + '.'
    : 'The authorities this machine trusts — or give your own.'));
  box.appendChild(host);
  own.onclick = function () {
    if (!need()) return;
    modal('Use my own authority for ' + words, function (body) {
      var p = el('p', 'note');
      p.innerHTML = 'The authority’s certificate, whole, including its <span class="mono">'
        + 'BEGIN</span> and <span class="mono">END</span> lines - not its key. Several, one '
        + 'after another, for a chain.';
      body.appendChild(p);
      var area = el('textarea');
      area.rows = 11;
      area.id = 'rosapi-ca-area';
      area.spellcheck = false;
      area.placeholder = '-----BEGIN CERTIFICATE-----';
      body.appendChild(area);
      setTimeout(function () { area.focus(); }, 60);
    }, [
      {words: 'Cancel', close: true},
      {words: 'Keep this authority', cls: 'primary', close: true, go: function () {
        api('rosapi', {do: 'ca', name: nameNow(), pem: $('rosapi-ca-area').value})
          .then(function (d) {
            toast('the authority was stored', 'good');
            s.api_cas = s.api_cas || {};
            s.api_cas[nameNow()] = d.ca;
            paint();
          }).catch(oops);
      }}
    ]);
  };
  forget.onclick = function () {
    if (!need()) return;
    confirmThen('Forget the authority for ' + words,
      'The router’s certificate is checked by the authorities this machine trusts again.',
      'Forget it', function () {
        api('rosapi', {do: 'ca-forget', name: nameNow()}).then(function () {
          if (s.api_cas) delete s.api_cas[nameNow()];
          toast('the authority is gone');
          paint();
        }).catch(oops);
      });
  };
  return box;
}

/** The key a MikroTik is read over ssh with: the banning's key panel, the
    same words and the same five buttons, for this router's own key. */
function rosSshKeyPanel(cfg, nameNow, words, s, sshKey, test, need, paint) {
  var name = nameNow();
  var keybox = el('div', 'subpanel');
  keybox.style.marginTop = '16px';
  var keynote = el('p', 'note');
  keynote.innerHTML = 'Made here, and it never leaves this machine except when you download it. '
    + 'Put the <b>public</b> half on the firewall.';
  explain(keynote, 'The key is made here and never leaves this machine except when you '
    + 'download it. Put the public half on the firewall — on RouterOS, /user ssh-keys import '
    + 'public-key-file=… user=… — and it will let this in without a password. Keep '
    + 'the private half safe: anybody holding it can sign in to the firewall as that account.');
  keybox.appendChild(keynote);
  if (!s.can_keygen && s.can_keygen !== undefined) {
    var missing = el('p', 'note', 'ssh-keygen is not on this machine, so a key cannot be made '
      + 'or read here: dnf install openssh-clients. A password still works.');
    missing.style.color = 'var(--warn)';
    keybox.appendChild(missing);
  }
  var has = !!(sshKey && sshKey.key);
  var bar = el('div', 'btnrow');
  var mk = cmdButton('Make a key', 'key', 'admin-only');
  var own = cmdButton('Use my own', 'upload', 'admin-only');
  var down = cmdButton('Download it', 'download', 'admin-only');
  var forget = cmdButton('Forget it', 'forget', 'danger admin-only');
  var canKey = s.can_keygen !== false;
  mk.disabled = !ADMIN || !canKey;
  own.disabled = !ADMIN || !canKey;
  down.disabled = !ADMIN || !has;
  forget.disabled = !ADMIN || !has;
  explain(mk, 'Make a fresh ed25519 pair here. The private half stays on this machine and the '
    + 'public half is shown below for you to put on the router. Any key already stored is '
    + 'replaced, so until the new public half is on the router this will not be able to sign '
    + 'in.');
  explain(own, 'Use a private key you already have. Paste it whole, including its BEGIN and END '
    + 'lines; its public half is worked out here so you do not have to hand that over as well.');
  explain(down, 'Download the private half as a file, for keeping somewhere safe or for using '
    + 'the same key elsewhere. It is written into Events that it was downloaded, and by whom.');
  explain(forget, 'Delete the private key from this machine. Unless the router is set to take a '
    + 'password instead, nothing here will reach it until a new key is made and put on it.');
  [mk, own, down, forget].forEach(function (b) { bar.appendChild(b); });
  bar.appendChild(el('span', 'spacer'));
  bar.appendChild(test);
  keybox.appendChild(bar);
  var keyHost = el('div');
  keyHost.style.marginTop = '12px';
  if (!sshKey || !sshKey.public) {
    keyHost.appendChild(el('p', 'btnhelp',
      'No key yet — make one, or let it sign in with a password.'));
  } else {
    keyHost.appendChild(el('p', 'btnhelp', 'The public half. Click it to copy.'));
    var code = el('code', 'copyme', sshKey.public);
    explain(code, 'Click to copy. This is the half that goes ON ' + words + '; the private half '
      + 'stays here. On RouterOS: put it in a file, then <code>/user ssh-keys import '
      + 'public-key-file=isemon-read.pub user=' + htmlText(cfg.user || 'isemon-read')
      + '</code>');
    code.onclick = function () {
      copyText(sshKey.public, 'the public key is on the clipboard');
    };
    keyHost.appendChild(code);
  }
  keybox.appendChild(keyHost);
  var kept = function (d) {
    s.api_keys = s.api_keys || {};
    if (d) s.api_keys[nameNow()] = {public: d.public, key: true};
    else delete s.api_keys[nameNow()];
    paint();
  };
  mk.onclick = function () {
    if (!need()) return;
    confirmThen('Make a key for ' + words,
      'A fresh ed25519 pair is made here. The private half stays on this machine and the public '
      + 'half is shown for you to put on that router.<br><br><b>Any key already stored for it '
      + 'is replaced</b>, so until the new public half is on it this will not be able to sign '
      + 'in.',
      'Make one', function () {
        api('rosapi', {do: 'keygen', name: nameNow()}).then(function (d) {
          toast('a new key was made — put the public half on ' + words, 'good');
          kept(d);
        }).catch(oops);
      });
  };
  own.onclick = function () {
    if (!need()) return;
    modal('Use my own key for ' + words, function (body) {
      var p = el('p', 'note');
      p.innerHTML = 'An OpenSSH private key, whole, including its <span class="mono">BEGIN</span> '
        + 'and <span class="mono">END</span> lines. It is kept in this machine’s database '
        + 'and never shown back. Its public half is worked out here, so you do not have to hand '
        + 'that over as well.';
      body.appendChild(p);
      var area = el('textarea');
      area.rows = 11;
      area.id = 'rosssh-paste-area';
      area.spellcheck = false;
      area.placeholder = '-----BEGIN OPENSSH PRIVATE KEY-----';
      body.appendChild(area);
      setTimeout(function () { area.focus(); }, 60);
    }, [
      {words: 'Cancel', close: true},
      {words: 'Keep this key', cls: 'primary', close: true, go: function () {
        api('rosapi', {do: 'key', name: nameNow(), key: $('rosssh-paste-area').value})
          .then(function (d) {
            toast('the key was stored', 'good');
            kept(d);
          }).catch(oops);
      }}
    ]);
  };
  down.onclick = function () {
    if (!need()) return;
    confirmThen('Download the private key for ' + words,
      'The private half leaves this machine as a file. Anybody holding it can sign in to that '
      + 'router as <span class="mono">' + htmlText(cfg.user || 'that account')
      + '</span>. That it was downloaded, and by whom, is written into Events.',
      'Download it', function () {
        api('rosapi', {do: 'key-download', name: nameNow()}).then(rosApiSave).catch(oops);
      });
  };
  forget.onclick = function () {
    if (!need()) return;
    confirmThen('Forget the key for ' + words,
      'The private key is deleted from this machine. Unless that router is set to take a '
      + 'password instead, nothing here will reach it until a new key is made and put on it.',
      'Forget it', function () {
        api('rosapi', {do: 'key-forget', name: nameNow()}).then(function () {
          toast('the key is gone');
          kept(null);
        }).catch(oops);
      });
  };
  return keybox;
}

/** The router's file, as the daemon handed it over, saved by the browser. */
function rosApiSave(d) {
  var a = document.createElement('a');
  a.href = URL.createObjectURL(new Blob([d.pem || ''], {type: 'application/x-pem-file'}));
  a.download = d.file || 'isemon-api.pem';
  document.body.appendChild(a);
  a.click();
  setTimeout(function () { URL.revokeObjectURL(a.href); a.remove(); }, 1000);
}

/** How to set a MikroTik up to be read through its API, as the banning's
    own guide is drawn: steps, each with its commands. */
function rosApiGuide(cfg, withCert) {
  var user = String(cfg.user || 'isemon-read');
  var me = location.hostname;
  if (cfg.mode === 'ssh') {
    modal('Setting it up: MikroTik over ssh (read-only)', function (body) {
      body.classList.add('guide');
      guideNote(body, 'This reads the router and writes nothing to it: the account it signs in '
        + 'with may read and sign in over ssh, and nothing else.');
      guideStep(body, 1, 'An account that may only read',
        'On the MikroTik, a group allowed read and ssh, and an account in it:',
        '/user group add name=isemon-read policy=read,ssh,!local,!telnet,!api,!ftp,!reboot,'
        + '!write,!policy,!test,!winbox,!password,!web,!sniff,!sensitive,!romon,!rest-api\n'
        + '/user add name=' + user + ' group=isemon-read password=SOMETHING-LONG');
      guideStep(body, 2, 'Its key',
        '<b>Make a key</b> below, copy its public half into a file on the Mikrotik '
        + '(<i>Files</i>, or scp) and import it for that account:',
        '/user ssh-keys import public-key-file=isemon-read.pub user=' + user);
      guideNote(body, 'Then, here: fill the settings in, <b>Save</b>, and <b>Try reaching it</b>. '
        + 'The connections are read from the next round on.', '');
    }, [{words: 'Close', close: true}]);
    return;
  }
  modal('Setting it up: MikroTik API (read-only)', function (body) {
    body.classList.add('guide');
    guideNote(body, 'This reads the router and writes nothing to it: the account it signs in '
      + 'with may read and use the API, and nothing else.');
    guideStep(body, 1, 'An account that may only read',
      'On the MikroTik, a group allowed read and api, and an account in it:',
      '/user group add name=isemon-read policy=read,api,!local,!telnet,!ssh,!ftp,!reboot,'
      + '!write,!policy,!test,!winbox,!password,!web,!sniff,!sensitive,!romon,!rest-api\n'
      + '/user add name=' + user + ' group=isemon-read password=SOMETHING-LONG');
    if (cfg.mode === 'plain') {
      guideStep(body, 2, 'The API',
        'The plain API, open to this machine alone:',
        '/ip service set api disabled=no address=' + me);
    } else if (cfg.mode === 'ca') {
      guideStep(body, 2, 'Its certificate',
        'The certificate the authority signed for the router - with its private key, flag '
        + '<b>K</b> in <span class="mono">/certificate print</span> - given to api-ssl, open to '
        + 'this machine alone:',
        '/ip service set api-ssl certificate=<the name of its certificate> disabled=no '
        + 'address=' + me);
    } else if (cfg.mode === 'anon') {
      guideStep(body, 2, 'The API',
        'api-ssl with no certificate, open to this machine alone:',
        '/ip service set api-ssl disabled=no certificate=none address=' + me);
    } else {
      guideStep(body, 2, 'Its certificate',
        '<b>Make a certificate</b> below (or <b>Use my own</b>), <b>Download it</b> and put '
        + '<span class="mono">isemon-api.pem</span> on the MikroTik (<i>Files</i>, or scp). '
        + 'Then import it and give it to api-ssl, open to this machine alone:',
        '/certificate import file-name=isemon-api.pem passphrase=""\n'
        + '/ip service set api-ssl certificate=isemon-api.pem_0 disabled=no address=' + me);
      if (!withCert) {
        guideNote(body, 'Without a certificate made here, the one api-ssl already has is pinned '
          + 'at the first connection.');
      }
    }
    guideNote(body, 'Then, here: fill the settings in, <b>Save</b>, and <b>Try reaching it</b>. '
      + 'The connections are read from the next round on.', '');
  }, [{words: 'Close', close: true}]);
}

function fwSourcesEditor(s) {
  var box = el('div', 'fwsrc');
  var rows = fwSourcesNow(s);
  var kinds = s.types || {fortigate: 'FortiGate'};
  var body = el('div', 'fwsrc-rows');
  var item = null;
  var settle = function () {
    item = item || box.closest('.set-item');
    if (item) markDirty(item, s);
    applyOnlyWhen();
  };
  var cell = function (row, index, key, holder, help, cls) {
    var field = el('input');
    field.type = 'text';
    if (cls) field.className = cls;
    field.placeholder = holder;
    field.value = row[key];
    field.disabled = !ADMIN;
    field.setAttribute('aria-label', help);
    explain(field, help);
    field.oninput = function () { rows[index][key] = field.value; settle(); };
    return field;
  };
  var paint = function () {
    clear(body);
    if (rows.length) {
      var head = el('div', 'fwsrc-row fwsrc-head');
      ['Name', 'Kind', 'Where its log is (a folder for each unit of a pair)',
       'Which files there are its', 'The zone of its clock', '']
        .forEach(function (w) { head.appendChild(el('span', '', w)); });
      body.appendChild(head);
    }
    rows.forEach(function (one, index) {
      var row = el('div', 'fwsrc-row');
      row.appendChild(cell(one, index, 'name', 'e.g. hq',
        'What this firewall is called here: on the Traffic page, where you switch between '
        + 'firewalls, and beside every line it sent. Letters, digits, spaces, dots, dashes '
        + 'and underscores, up to 40. Left empty, it is named after its folder.'));
      var kind = el('select');
      Object.keys(kinds).forEach(function (k) {
        var o = document.createElement('option');
        o.value = k;
        o.textContent = kinds[k];
        kind.appendChild(o);
      });
      kind.value = one.type in kinds ? one.type : Object.keys(kinds)[0];
      kind.disabled = !ADMIN;
      explain(kind, 'Which kind of firewall writes this log, because each writes its own '
        + 'shape of line.');
      /* Drawn again (1.10.217): a row made a MikroTik shows its API at
         once, and one that is no longer one stops showing it. */
      kind.onchange = function () { rows[index].type = kind.value; settle(); paint(); };
      row.appendChild(kind);
      /* One folder or several: a pair in failover is one firewall whose two
         units the syslog server files apart. */
      var where = el('div', 'fwsrc-paths');
      one.paths.forEach(function (path, pi) {
        var line = el('div', 'fwsrc-path');
        var field = el('input');
        field.type = 'text';
        field.className = 'mono';
        field.placeholder = pi ? '/var/log/remote/hq-2' : '/var/log/remote/hq';
        field.value = path;
        field.disabled = !ADMIN;
        field.setAttribute('aria-label', 'Where its log is');
        explain(field, 'The folder the syslog server files this firewall\u2019s lines in - '
          + 'or the path to one file. A pair in failover is one firewall with a folder for '
          + 'each unit: add the second with the + beside it.');
        field.oninput = function () { rows[index].paths[pi] = field.value; settle(); };
        line.appendChild(field);
        if (pi === 0) {
          var more = iconButton('add', 'Another folder for the same firewall - the other '
            + 'unit of a pair');
          more.disabled = !ADMIN || one.paths.length >= 8;
          more.onclick = function () { rows[index].paths.push(''); settle(); paint(); };
          line.appendChild(more);
        } else {
          var less = iconButton('close', 'Not this folder');
          less.disabled = !ADMIN;
          less.onclick = function () { rows[index].paths.splice(pi, 1); settle(); paint(); };
          line.appendChild(less);
        }
        where.appendChild(line);
      });
      row.appendChild(where);
      row.appendChild(cell(one, index, 'files', '*.log', 'Which files in that folder are '
        + 'this firewall’s, as a pattern. *.log takes them all; a syslog server that '
        + 'writes one file a day is followed the way the NPS files are - the newest two.',
        'mono'));
      var zone = cell(one, index, 'zone', 'as the other logs',
        'The time zone the stamps in this firewall\u2019s lines are written in. Empty reads '
        + 'them like every other log (Settings \u2192 The ISE logs, or this machine\u2019s own '
        + 'zone). An FTD writes UTC unless told otherwise, and its lines then look two hours '
        + 'old here in summer: write UTC. A stamp that carries its own zone (RFC 5424) is '
        + 'read in that zone whatever this says.');
      zone.setAttribute('list', 'fwsrc-zones');
      row.appendChild(zone);
      if (one.lag) {
        var hint = el('div', 'fwsrc-lag warn small', one.lag);
        row.appendChild(hint);
      }
      var drop = iconButton('trash', 'Stop reading this firewall');
      drop.disabled = !ADMIN;
      drop.onclick = function () { rows.splice(index, 1); settle(); paint(); };
      row.appendChild(drop);
      body.appendChild(row);
      /* A MikroTik: its API as well, read-only, on a line of its own under
         its row (1.10.211). */
      if (one.type === 'routeros') {
        body.appendChild(rosApiPanel(one, index, rows, settle, paint, s));
      }
    });
    if (!rows.length) {
      body.appendChild(el('div', 'fold-none', 'No firewall yet. Add the first one.'));
    }
    var add = cmdButton('Add a firewall', 'add', 'small');
    add.disabled = !ADMIN || rows.length >= 16;
    add.onclick = function () {
      rows.push({name: '', type: Object.keys(kinds)[0], paths: [''], files: '*.log'});
      settle();
      paint();
      var rowsNow = body.querySelectorAll('.fwsrc-row:not(.fwsrc-head)');
      var last = rowsNow.length ? rowsNow[rowsNow.length - 1].querySelector('input') : null;
      if (last) last.focus();
    };
    var bar = el('div', 'btnrow');
    bar.appendChild(add);
    body.appendChild(bar);
    explainWhatWasDrawn(body);
  };
  box.appendChild(body);
  if (!$('fwsrc-zones')) {
      var list = document.createElement('datalist');
      list.id = 'fwsrc-zones';
      ['UTC', 'Europe/Prague', 'Europe/Bratislava', 'Europe/Vienna', 'Europe/Berlin',
       'Europe/London'].forEach(function (z) {
        var o = document.createElement('option');
        o.value = z;
        list.appendChild(o);
      });
      document.body.appendChild(list);
    }
  /* A row with neither a name nor a folder is a row somebody added and then
     thought better of, not a firewall. */
  box._get = function () {
    return rows.map(function (one) {
      var paths = one.paths.map(function (p) { return String(p || '').trim(); })
        .filter(function (p) { return p; });
      var out = {name: String(one.name || '').trim(), type: one.type, path: paths[0] || '',
                 paths: paths, files: String(one.files || '').trim() || '*.log',
                 zone: String(one.zone || '').trim()};
      /* Only on a MikroTik's row, and only once somebody has touched it:
         every other row is saved as it always was. */
      if (one.type === 'routeros' && one.api) {
        out.api = {on: one.api.on ? 1 : 0, host: String(one.api.host || '').trim(),
                   port: Number(one.api.port) || (one.api.mode === 'plain' ? 8728
                     : (one.api.mode === 'ssh' ? 22 : 8729)),
                   mode: one.api.mode || 'pin', user: String(one.api.user || '').trim(),
                   /* The dots it was shown as are not a password: sent empty,
                      the one that is set is kept. */
                   password: String(one.api.password || '').indexOf('\u2022') === 0 ? ''
                     : String(one.api.password || ''),
                   every: Number(one.api.every) || 30};
        if (one.api.auth) out.api.auth = one.api.auth;
        if (one.api.tls_name) out.api.tls_name = String(one.api.tls_name).trim();
        if (one.api.mode === 'ca') out.api.verify = Number(one.api.verify) === 0 ? 0 : 1;
      }
      return out;
    }).filter(function (one) { return one.name || one.path; });
  };
  box._set = function (v) {
    rows = (Array.isArray(v) ? v : []).map(fwSourceRow);
    paint();
    settle();
  };
  paint();
  /* What it says as drawn, in its own words (1.10.197): compared with the
     saved list - which has no `path` and a `lag` - it never matched, so a
     letter typed and taken back left the page "1 change not saved". */
  box._initial = JSON.stringify(box._get());
  return box;
}

function ladderEditor(s) {
  var box = el('div', 'ladder');
  var steps = ladderRead(s.value);
  var item = null;
  var pick = el('select');
  var body = el('div', 'ladder-steps');
  var said = el('div', 'ladder-says muted small');
  pick.disabled = !ADMIN;
  explain(pick, 'A ready-made ladder, or "Something else" to build one step at a time '
    + 'underneath. Picking one here rewrites the steps.');

  var settle = function () {
    ladderWords(steps, said);
    item = item || box.closest('.set-item');
    if (item) markDirty(item, s);
  };
  var paint = function () {
    clear(body);
    steps.forEach(function (value, index) {
      var row = el('div', 'ladder-row');
      row.appendChild(el('span', 'ladder-n', (index + 1) + '.'));
      var when = el('select');
      when.disabled = !ADMIN;
      /* ...and a length none of those is - one written in the file, or by
         an earlier version of this editor - as itself, rather than an empty
         box beside a summary that names it. (1.10.159) */
      var lengths = LADDER_STEPS.map(function (x) { return [String(x[0]), x[1]]; });
      if (!LADDER_STEPS.some(function (x) { return x[0] === value; })) {
        lengths.push([String(value), ladderName(value)]);
        lengths.sort(function (a, b) {
          var x = Number(a[0]) || Infinity, y = Number(b[0]) || Infinity;
          return x - y;
        });
      }
      fillSelect(when, lengths, String(value));
      when.onchange = function () {
        steps[index] = parseInt(when.value, 10);
        /* "for good" is the end of any ladder: nothing after it can happen,
           so the steps after it are taken away rather than left to puzzle
           over. */
        if (steps[index] === 0) steps = steps.slice(0, index + 1);
        pick.value = 'custom';
        settle();
        paint();
      };
      row.appendChild(when);
      var drop = iconButton('trash', 'Take this step away');
      drop.disabled = !ADMIN;
      drop.onclick = function () {
        steps.splice(index, 1);
        pick.value = 'custom';
        settle();
        paint();
      };
      row.appendChild(drop);
      body.appendChild(row);
    });
    var add = cmdButton('Add a step', 'add', 'small');
    add.disabled = !ADMIN || steps.length >= 8 || steps.indexOf(0) >= 0;
    add.title = steps.indexOf(0) >= 0
      ? 'The ladder ends at “for good”; nothing can come after it'
      : 'One more step, taken the next time that address comes back';
    add.onclick = function () {
      /* The next length on the list, not four times the last one: 40 or
         160 minutes is no length the step's own drop-down offers. */
      var last = steps.length ? steps[steps.length - 1] : 0;
      var next = LADDER_STEPS.filter(function (x) { return x[0] > last; })[0];
      steps.push(steps.length ? (next ? next[0] : 43200) : 10);
      pick.value = 'custom';
      settle();
      paint();
    };
    var bar = el('div', 'btnrow');
    bar.appendChild(add);
    if (steps.length && steps.indexOf(0) < 0) {
      var end = cmdButton('End it with “for good”', 'ban', 'small');
      end.disabled = !ADMIN;
      end.title = 'An address that has worked through every step above is kept out '
        + 'permanently';
      end.onclick = function () {
        steps.push(0);
        pick.value = 'custom';
        settle();
        paint();
      };
      bar.appendChild(end);
    }
    if (steps.length) {
      var none = cmdButton('No ladder', 'undo', 'small');
      none.disabled = !ADMIN;
      none.title = 'Take the ladder away; every block becomes the single length set above';
      none.onclick = function () {
        steps = [];
        pick.value = '';
        settle();
        paint();
      };
      bar.appendChild(none);
    }
    body.appendChild(bar);
    explainWhatWasDrawn(body);
  };
  fillSelect(pick, LADDER_PRESETS, LADDER_PRESETS.some(function (p) {
    return p[0] === ladderWrite(steps);
  }) ? ladderWrite(steps) : (steps.length ? 'custom' : ''));
  pick.onchange = function () {
    if (pick.value === 'custom') { settle(); return; }
    steps = ladderRead(pick.value);
    settle();
    paint();
  };
  box.appendChild(pick);
  box.appendChild(body);
  box.appendChild(said);
  settle();
  paint();
  box._get = function () { return ladderWrite(steps); };
  box._set = function (v) {
    steps = ladderRead(v);
    fillSelect(pick, LADDER_PRESETS, LADDER_PRESETS.some(function (p) {
      return p[0] === ladderWrite(steps);
    }) ? ladderWrite(steps) : (steps.length ? 'custom' : ''));
    settle();
    paint();
  };
  box.addEventListener = function () {};    /* the parts inside report for it */
  return box;
}

/* ---- choosing countries ---------------------------------------------------
   A text box wanting "CZ, SK" works and is unkind: nobody remembers that
   Sweden is SE and Switzerland is CH. This offers what the country database
   actually holds, with how many ranges each has, and keeps the text box
   underneath for anybody who would rather type. */
function countryPicker(s) {
  var wrap = el('div');
  var chosen = String(s.value || '').split(',').map(function (x) {
    return x.trim().toUpperCase();
  }).filter(Boolean);
  var item = null;

  var box = el('div');
  box.style.cssText = 'max-height:210px;overflow:auto;border:1px solid var(--line);'
    + 'border-radius:10px;padding:8px 10px;background:var(--panel2);display:grid;'
    + 'grid-template-columns:repeat(auto-fill,minmax(118px,1fr));gap:2px 10px';
  var text = el('input');
  text.type = 'text';
  text.value = chosen.join(', ');
  text.placeholder = 'CZ, SK';
  text.style.marginTop = '8px';
  text.disabled = !ADMIN;

  function changed() {
    item = item || wrap.closest('.set-item');
    if (item) markDirty(item, s);
  }
  function repaint() {
    clear(box);
    var known = (SETTINGS.countries || []);
    if (!known.length) {
      box.style.display = 'block';
      box.appendChild(el('p', 'btnhelp',
        'The country database has not been fetched yet, so there is nothing to choose from. '
        + 'Fetch it on the card below, or type the codes underneath.'));
      return;
    }
    box.style.display = 'grid';
    known.forEach(function (c) {
      var label = el('label', 'check small');
      var input = document.createElement('input');
      input.type = 'checkbox';
      input.checked = chosen.indexOf(c.cc) >= 0;
      input.disabled = !ADMIN;
      input.onchange = function () {
        if (input.checked) {
          if (chosen.indexOf(c.cc) < 0) chosen.push(c.cc);
        } else {
          chosen = chosen.filter(function (x) { return x !== c.cc; });
        }
        chosen.sort();
        text.value = chosen.join(', ');
        changed();
      };
      label.appendChild(input);
      label.appendChild(countryBadge(c.cc));
      var n = el('span', 'muted small', num(c.v4 + c.v6));
      n.title = c.v4 + ' IPv4 range(s), ' + c.v6 + ' IPv6 — every one of them becomes a '
        + 'line on the router';
      label.appendChild(n);
      box.appendChild(label);
    });
    explainWhatWasDrawn(box);
  }
  text.addEventListener('input', function () {
    chosen = text.value.split(',').map(function (x) { return x.trim().toUpperCase(); })
      .filter(Boolean);
    repaint();
    changed();
  });
  repaint();
  wrap.appendChild(box);
  wrap.appendChild(text);
  wrap._get = function () { return chosen.join(', '); };
  wrap._set = function (v) {
    chosen = String(v || '').split(',').map(function (x) { return x.trim().toUpperCase(); })
      .filter(Boolean);
    text.value = chosen.join(', ');
    repaint();
  };
  wrap.addEventListener = function () {};    /* the parts inside report for it */
  return wrap;
}

/* ==========================================================================
   The whitelist
   ========================================================================== */
function loadWhitelist() {
  api('whitelist').then(function (d) {
    var rows = d.rows || [];
    $('white-empty').hidden = !!rows.length;
    /* The countries are a setting rather than rows, and they spare a great
       deal more than any row here does - so they are said above the list
       rather than left to be discovered in a field further down. */
    var homes = d.countries || [];
    var line = $('white-countries');
    if (line) {
      line.hidden = !homes.length;
      if (homes.length) {
        clear(line);
        line.appendChild(document.createTextNode('Whole countries spared: '));
        homes.forEach(function (cc) {
          line.appendChild(countryBadge(cc));
          line.appendChild(document.createTextNode(' '));
        });
        /* Built out of nodes rather than written as markup and parsed
           back: `innerHTML = textContent` turns text that was safe into
           live HTML, which is a habit worth not having even where the one
           value in it is two letters the daemon has checked. */
        var note = el('span', 'muted small',
          '\u2014 every address the country database puts in '
          + (homes.length === 1 ? countryWords(homes[0]) : 'them')
          + ' is recorded, counted and never banned. Under ');
        note.appendChild(el('i', '', 'Never ban these countries'));
        note.appendChild(document.createTextNode(' below.'));
        line.appendChild(note);
        explainWhatWasDrawn(line);
      }
    }
    $('white-count').textContent = num(rows.length) + ' entry(s)';
    var chip = $('white-n');
    if (chip) chip.textContent = rows.length || '';
    var host = $('white-list');
    clear(host);
    host.appendChild(listView({
      key: 'whitelist', rows: rows, per: 25,
      placeholder: 'an address, a range, a note, a name\u2026',
      explain: 'Searches the whole whitelist, not the page in front of you.',
      empty: 'Nothing is whitelisted yet',
      countryOf: function (r) { return r.country; },
      hay: function (r) {
        return [r.ip, r.country, r.note, r.by, r.from].filter(Boolean).join(' ');
      },
      draw: function (page, where) { where.appendChild(whiteRows(page)); }
    }));
    explainWhatWasDrawn(host);
  }).catch(oops);
}

function whiteRows(rows) {
  var wrap = el('div', 'scroll');
  var table = el('table', 'plain');
  var thead = el('thead'), hr = el('tr');
  ['Address or range', 'Country', 'What it is', 'Added', 'By', 'Where from', ''].forEach(
    function (h) { hr.appendChild(el('th', '', h)); });
  thead.appendChild(hr);
  table.appendChild(thead);
  var body = el('tbody');
  (function () {
    rows.forEach(function (r) {
      var tr = el('tr');
      var td = el('td');
      td.appendChild(el('span', 'mono', r.ip));
      if (String(r.ip).indexOf('/') >= 0) {
        var tag = el('span', 'tag info', 'range');
        tag.style.marginLeft = '7px';
        tag.title = 'Everything inside this range is spared, not only the address itself.';
        td.appendChild(tag);
      }
      tr.appendChild(td);
      var cc = el('td');
      cc.appendChild(countryBadge(r.country));
      tr.appendChild(cc);
      tr.appendChild(noI18n(el('td', '', r.note || '')));
      tr.appendChild(r.at ? stampCell(r.at) : el('td', '', '–'));
      tr.appendChild(r.by ? (function () {
        var cell = el('td');
        cell.appendChild(accountWords(r.by));
        return cell;
      })() : el('td', '', '–'));
      var from = el('td');
      from.appendChild(el('span', 'tag ' + (r.from === 'list' ? 'ok' : 'dim'),
                          r.from === 'list' ? 'this list' : 'never_block'));
      tr.appendChild(from);
      var act = el('td');
      if (ADMIN && r.from === 'list') {
        var off = iconButton('cancel', 'Take ' + r.ip + ' off the whitelist. It can be banned '
                             + 'again from that moment, by the counting like anybody else.');
        off.classList.add('danger');
        off.onclick = function () {
          confirmThen('Take ' + r.ip + ' off the whitelist',
            'From that moment it is treated like any other address: enough failed logins and it '
            + 'is banned, and the router is told. Nothing is banned by this on its own.',
            'Take it off', function () {
              api('whitelist', {remove: r.ip}).then(function () {
                toast(r.ip + ' is off the whitelist');
                loadWhitelist();
                loadSettings();
              }).catch(oops);
            });
        };
        act.appendChild(off);
      }
      tr.appendChild(act);
      body.appendChild(tr);
    });
  })();
  table.appendChild(body);
  wrap.appendChild(table);
  return wrap;
}

$('white-add').onclick = function () {
  var ip = $('white-ip').value.trim();
  if (!ip) { toast('type an address or a range first', 'bad'); return; }
  if ($('white-add').disabled) return;
  busy($('white-add'), true);
  api('whitelist', {add: ip, note: $('white-note').value.trim()}).then(function (d) {
    $('white-ip').value = '';
    $('white-note').value = '';
    toast(d.ip + ' will never be banned'
      + ((d.freed || []).length ? ' — ' + d.freed.length + ' banned address(es) were let '
         + 'back in' : ''), 'good');
    loadWhitelist();
    loadBans();
    tick();
  }).catch(oops).then(function () { busy($('white-add'), false); });
};
$('white-ip').addEventListener('keydown', function (e) {
  if (e.key === 'Enter' && ADMIN) $('white-add').click();
});
$('white-note').addEventListener('keydown', function (e) {
  if (e.key === 'Enter' && ADMIN) $('white-add').click();
});

/* ---- the public lists ------------------------------------------------------ */
/** How the name lookups are getting on, on their own card.

    A feature that works quietly behind every page needs one place that says
    whether it is working at all: how many addresses have a name, how many
    are waiting to be asked about, and what the last thing that went wrong
    was. Without it, "no names anywhere" and "this site has no reverse zone"
    look exactly alike. */
function drawNames(d) {
  var host = $('ptr-state');
  if (!host) return;
  clear(host);
  d = d || {};
  function kv(k, v, more) {
    var line = el('div', 'kv');
    line.appendChild(el('span', 'k', k));
    var value = el('span', 'v');
    if (v instanceof Node) value.appendChild(v); else value.textContent = v;
    if (more) value.appendChild(el('span', 'd', more));
    line.appendChild(value);
    host.appendChild(line);
  }
  var state = el('span');
  if (!d.on) {
    state.appendChild(el('span', 'tag', 'not looking'));
    state.appendChild(document.createTextNode(
      (d.servers || []).length ? ' \u00b7 switched off above'
                               : ' \u00b7 no name server is written down to ask'));
  } else {
    state.appendChild(el('span', 'tag ok', 'looking'));
    state.appendChild(document.createTextNode(' \u00b7 ' + (d.servers || []).join(', ')));
  }
  kv('Right now', state);
  kv('Addresses with a name', num(d.named || 0),
     num(d.addresses || 0) + ' asked about in all');
  kv('Asked since this started', num(d.asked || 0),
     num(d.answered || 0) + ' had a name \u00b7 ' + num(d.failed || 0) + ' went wrong');
  if (d.waiting) kv('Waiting to be asked', num(d.waiting));
  kv('Asked again after', num(d.every_min || 60) + ' minute(s)',
     'which is how finely the history of an address is cut');
  /* How many addresses in the records have never been asked about. It is
     the number the button underneath is about, and without it "fill in the
     ones with no name" is a button nobody can judge. */
  /* An administrator's question (a walk of three tables); a read-only
     account was answered 403 every time this pane opened. */
  if (d.on && ADMIN && $('ptr-missing')) {
    setText('ptr-missing', '');
    api('ptr', {missing: true}).then(function (said) {
      setText('ptr-missing', said.missing
        ? num(said.missing) + ' address(es) in the records have no name yet'
        : 'every address in the records has an answer');
    }).catch(function () { /* the card is worth having without it */ });
  }
  if (d.trouble) {
    var bad = el('span', 'tag warn', 'the last one went wrong');
    explain(bad, 'What the servers said: <code>' + d.trouble + '</code>');
    kv('Trouble', bad, d.trouble.slice(0, 80));
  }
  $('ptr-state-when').textContent = d.at ? shortStamp(d.at) : '';
  explainWhatWasDrawn(host);
}

/** One address, asked of every server in the list, with what each said.

    Every one of them is asked rather than stopping at the first with an
    answer: what is being set up here is the list itself, and a server that
    holds the zone and one that has never heard of the address look exactly
    alike from the outside. */
function tryOneName() {
  var box = $('ptr-try-ip');
  var out = $('ptr-out');
  var want = (box.value || '').trim();
  if (!want) { box.focus(); return; }
  clear(out);
  out.appendChild(el('div', 'muted small', 'asking\u2026'));
  busy($('ptr-try'), true);
  api('ptr', {'try': want}).then(function (d) {
    clear(out);
    if (d.trouble) {
      out.appendChild(el('div', 'tag warn', d.trouble));
      return;
    }
    var head = el('div', 'fsays');
    head.textContent = d.name
      ? d.ip + ' is ' + d.name + (d.where ? ' \u00b7 said by ' + d.where : '')
      : 'no server in the list has a name for ' + d.ip;
    out.appendChild(head);
    if (d.question) {
      var asked = el('div', 'muted small', 'asked for ' + d.question);
      out.appendChild(asked);
    }
    var was = el('div', 'ptrwas');
    was.style.marginTop = '8px';
    (d.asked || []).forEach(function (one) {
      var line = el('div', 'one');
      line.appendChild(el('span', 'tag ' + (one.name ? 'ok' : (one.trouble ? 'crit' : '')),
                          one.server));
      line.appendChild(el('span', 'n', one.name || (one.trouble || one.says || '\u2013')));
      line.appendChild(el('span', 'when', one.ms + ' ms'));
      was.appendChild(line);
    });
    out.appendChild(was);
    if (!d.on) {
      out.appendChild(el('div', 'muted small',
        'Looking up names is switched off above, so nothing is asked for on its own \u2014 '
        + 'this button asks anyway.'));
    }
  }).catch(function (e) {
    clear(out);
    out.appendChild(el('div', 'tag crit', String((e && e.message) || e)));
  }).then(function () { busy($('ptr-try'), false); });
}

/* The public lists switched on as saved, and as the switches stand now.
   A switch is a change waiting for Save the changes like every other setting
   on these pages (1.10.205): each one saved itself the moment it was flipped,
   so flipping three quickly was three saves racing one another, a page drawn
   again in the middle of them and errors. */
var FEEDS_SAVED = '';
function feedsNow() {
  var want = [];
  Array.prototype.forEach.call(document.querySelectorAll('input[data-feed]'),
    function (one) { if (one.checked) want.push(one.dataset.feed); });
  return want.join(', ');
}
function feedsMarkDirty() {
  var now = feedsNow();
  if (now !== FEEDS_SAVED) DIRTY.feeds = now; else delete DIRTY.feeds;
  Array.prototype.forEach.call(document.querySelectorAll('input[data-feed]'), function (one) {
    var row = one.closest('.kv');
    if (row) row.classList.toggle('changed', one.checked !== (one.dataset.was === '1'));
  });
  markDirtyCount();
}

function drawFeeds(feeds) {
  var host = $('feeds-list');
  clear(host);
  var on = 0, total = 0, newest = 0;
  FEEDS_SAVED = (feeds || []).filter(function (f) { return f.on; })
    .map(function (f) { return f.name; }).join(', ');
  /* Switches flipped and not saved yet stay flipped when the card is drawn
     again - another page looked at and back - as every other box does. */
  var pending = ('feeds' in DIRTY) ? String(DIRTY.feeds).split(/\s*,\s*/) : null;
  (feeds || []).forEach(function (f) {
    if (f.on) { on++; total += f.size; newest = Math.max(newest, f.at); }
    var box = el('div', 'kv');
    box.style.alignItems = 'flex-start';
    var k = el('span', 'k');
    k.style.flex = '1';
    var row = el('div', 'swrow');
    var sw = el('label', 'sw small');
    var input = document.createElement('input');
    input.type = 'checkbox';
    input.checked = pending ? pending.indexOf(f.name) >= 0 : !!f.on;
    input.disabled = !ADMIN;
    input.dataset.feed = f.name;
    input.dataset.was = f.on ? '1' : '0';
    input.onchange = feedsMarkDirty;
    sw.appendChild(input);
    sw.appendChild(el('span', 'knob'));
    row.appendChild(sw);
    var name = el('span', 'swlbl', f.short);
    name.style.fontWeight = '600';
    name.style.color = 'var(--tx)';
    row.appendChild(name);
    explain(sw, 'Switch the <b>' + f.short + '</b> list on or off. ' + f.what
      + ' When it is on, the ranges it publishes are fetched on the schedule set '
      + 'above and every address inside them is blocked at the router straight '
      + 'away, without waiting for anybody to try a password. Switching it off '
      + 'drops its ranges from the router at the next sync; nothing you have '
      + 'banned by hand is touched either way.');
    explain(name, 'Switch the <b>' + f.short + '</b> list on or off. ' + f.what
      + ' When it is on, the ranges it publishes are fetched on the schedule set '
      + 'above and every address inside them is blocked at the router straight '
      + 'away, without waiting for anybody to try a password.');
    k.appendChild(row);
    k.appendChild(el('span', 'd', f.what));
    box.appendChild(k);
    var v = el('span', 'v');
    v.style.minWidth = '150px';
    if (f.size) {
      v.appendChild(el('span', '', num(f.size) + ' range(s)'));
      v.appendChild(el('span', 'd', 'fetched ' + ago(f.at)));
    } else if (f.on) {
      v.appendChild(el('span', 'tag warn', 'not fetched yet'));
    } else {
      v.appendChild(el('span', 'muted', '–'));
    }
    if (f.error) {
      var bad = el('span', 'd');
      bad.style.color = 'var(--crit)';
      bad.textContent = f.error.words + (f.error.times > 1
        ? ' (' + f.error.times + ' times in a row)' : '');
      v.appendChild(bad);
    }
    box.appendChild(v);
    if (input.checked !== !!f.on) box.classList.add('changed');
    host.appendChild(box);
  });
  if (pending) feedsMarkDirty();
  $('feeds-when').textContent = on
    ? (on + ' switched on · ' + num(total) + ' range(s) · last fetched ' + ago(newest))
    : 'none switched on';
  explainWhatWasDrawn(host);
}

$('feeds-fetch').onclick = function () {
  api('feeds', {fetch_all: true}).then(function (d) {
    watchJob(d.job, 'Fetching the public lists', function () { loadSettings(); });
  }).catch(oops);
};
$('fold-open').onclick = function () { $('ban-fold').click(); };

/* ==========================================================================
   Automatic updates
   ========================================================================== */
/* ---- going back over every log -------------------------------------------
   A ban applied by hand to something that happened last week is a ban nobody
   can defend; a ban applied by the same rule that would have caught it at the
   time is the same ban the daemon would have made, only late. So this says
   what the rule is, what it would be weighing, and asks once. */
/* Setting the text of something that may not be on the page.

   One line of this card wrote to an element that had been taken out of the
   markup, which threw - and the throw landed in the `catch` below, so the
   whole card was left blank and the answer it had just been given was
   thrown away with it. The next press then asked "? earns ?", because
   nothing had ever been kept. A missing box is worth nothing happening in
   that box and nothing else. */
function setText(id, text) {
  var node = $(id);
  if (node) node.textContent = text;
  return !!node;
}

function rescanDraw(d) {
  RESCAN = d;
  var held = d.records || {};
  var limit = d.age_limit_h || 0;
  setText('rescan-limit', limit ? (limit >= 48 ? Math.round(limit / 24) + ' days'
    : (limit === 24 ? 'a day' : limit + ' hours')) : 'any age');
  /* The rule itself, on the card rather than only in the window that asks.
     It is the whole of what this button is about to do. */
  setText('rescan-rule', (d.trigger || '') + ' earns ' + (d.lengths || ''));
  var bits = [num(held.rows || 0) + ' failed attempt(s) recorded'];
  if (held.first) bits.push('the oldest is from ' + shortStamp(held.first));
  setText('rescan-note', bits.join(' \u00b7 '));
  var last = d.last;
  setText('rescan-when', last
    ? ('last run ' + ago(last.at) + ' \u00b7 ' + last.banned + ' banned')
    : 'never run');
  if (last && $('rescan-when')) {
    explain($('rescan-when'), 'The last time somebody went back over the logs.',
      '<span class="k">' + richText(last.said || '') + '<br>by '
      + richText(last.by || 'somebody') + ', taking '
      + (last.took || 0).toFixed(1) + ' s</span>');
  }
  /* Which logs it reads (1.10.204): every one switched on, ticked; the
     daemon says which those are, so a kind added later is here without
     the page knowing about it. */
  var place = $('rescan-logs');
  if (place) {
    var was = {};
    place.querySelectorAll('input[data-log]').forEach(function (box) {
      was[box.dataset.log] = box.checked;
    });
    clear(place);
    (d.logs || []).forEach(function (one) {
      var lab = el('label', 'check');
      lab.style.marginRight = '14px';
      var box = el('input');
      box.type = 'checkbox';
      box.dataset.log = one.log;
      box.checked = was[one.log] === undefined ? true : was[one.log];
      /* One the daemon will not read again says why, and cannot be ticked. */
      if (one.off) { box.checked = false; box.disabled = true; explain(lab, one.off); }
      lab.appendChild(box);
      lab.appendChild(document.createTextNode(one.words || one.log));
      place.appendChild(lab);
    });
    if (!(d.logs || []).length) place.textContent = 'no log is switched on';
  }
  if ($('rescan-go')) $('rescan-go').disabled = !ADMIN || !d.on;
  if (!d.on) {
    setText('rescan-note', 'the blacklist is switched off, so this would ban nothing');
  }
}

function loadRescan() {
  return api('rescan').then(rescanDraw).catch(function () {
    /* The pane is drawn before the daemon answers, and a pane that cannot
       say what it would do says so rather than saying nothing. */
    setText('rescan-rule', 'the daemon has not said yet');
    setText('rescan-note', '');
  });
}
var RESCAN = null;
$('rescan-go').onclick = function () {
  /* Asked again here rather than trusted from when the pane was drawn. What
     the window says is what is about to happen - the rule, and how many
     records it will be weighed against - and a settings page that has been
     open since this morning is a page whose numbers are from this morning.
     It is one small question, and the window waits for it rather than
     showing a rule with question marks in it. */
  busy($('rescan-go'), true);
  loadRescan().then(function () { askRescan(); })
    .then(function () { busy($('rescan-go'), false); });
};

function rescanPicked() {
  var boxes = Array.prototype.slice.call(document.querySelectorAll('#rescan-logs input[data-log]'))
    .filter(function (b) { return !b.disabled; });
  var on = boxes.filter(function (b) { return b.checked; }).map(function (b) {
    return b.dataset.log;
  });
  /* All of them is said as nothing at all: "everything switched on", which
     is what the daemon reads when it is not told. */
  return {all: on.length === boxes.length, logs: on};
}

function askRescan() {
  var days = Number($('rescan-days').value || 0);
  var picked = rescanPicked();
  if (!picked.all && !picked.logs.length) {
    toast('no log is ticked, so there is nothing to read', 'bad');
    return;
  }
  var d = RESCAN;
  if (!d) {
    toast('the daemon has not said what the rule is, so this is not being asked for', 'bad');
    return;
  }
  var held = d.records || {};
  confirmThen('Go back over every log?',
    '<p>Every log file is read from the beginning, and then every failed attempt in the '
    + 'database is weighed against the settings as they stand:</p>'
    + '<p class="ask-what"><b>' + richText(d.trigger || 'every failed attempt') + '</b> earns '
    + '<b>' + richText(d.lengths || 'a ban of the length set under Banning') + '</b></p>'
    + (d.feeds_ban
       ? '<p class="ask-what">And because <b>a listed address is banned the first time it '
         + 'fails</b> is switched on, every address in these records that is named by one of '
         + 'your public lists will be kept out <b>for good</b>, at its first failure, without '
         + 'the counting. On a month of logs that is usually most of what this finds.</p>'
       : '')
    + '<p>That is ' + num(held.rows || 0) + ' record(s) to weigh'
    + (days ? ', of which only the last ' + days + ' day(s) may earn a ban' : '')
    + '. Addresses on the whitelist are left alone, devices outside the watched ones earn '
    + 'nothing, and anything already kept out is skipped. <b>Nothing is ever un-banned by '
    + 'this.</b></p>'
    + '<p class="muted">It runs in the background. You can close the window it opens and it '
    + 'carries on.</p>',
    'Go back over it all', function () {
      api('rescan', {days: days, read_files: true,
                     logs: picked.all ? '' : picked.logs.join(',')}).then(function (r) {
        watchJob(r.job, 'Going back over every log', function () {
          loadRescan();
          tick();
        }, 'Reading every log file and weighing every failure in it. You can close this and it '
         + 'carries on; what it did ends up in Events either way.');
      }).catch(oops);
    }, false);
}

function loadUpdates() {
  api('updates').then(function (d) {
    var body = $('updates-table').querySelector('tbody');
    clear(body);
    var rows = d.rows || [];
    $('updates-empty').hidden = !!rows.length;
    var soonest = rows.map(function (r) { return r.next; })
      .filter(Boolean).sort(function (a, b) { return a - b; })[0];
    $('updates-when').textContent = soonest
      ? ('next ' + stamp(soonest))
      : 'nothing is fetched by itself';
    /* The hour only governs what is fetched daily or less often. Saying
       "at 03:30" beside a list set to every hour - which is what this used
       to do - describes something that does not happen. */
    var governs = (d.rows || []).filter(function (r) { return r.auto && r.at_applies; });
    var onTheirOwn = (d.rows || []).filter(function (r) { return r.auto && !r.at_applies; });
    $('updates-note').textContent =
      d.update_when !== 'at_time'
        ? 'each one is fetched as soon as its own interval falls due'
        : (!d.update_at
           ? 'the hour is empty, so each one is fetched as soon as it falls due'
           : (governs.length && onTheirOwn.length
              ? (num(onTheirOwn.length) + ' fetched on their own interval \u00b7 '
                 + num(governs.length) + ' at ' + d.update_at)
              : (governs.length ? 'at ' + d.update_at
                   + ', or at once when more than a day overdue'
                 : 'every one of these is wanted more often than daily, so the hour '
                   + 'cannot apply to any of them')));
    rows.forEach(function (r) {
      var tr = el('tr');
      var what = el('td');
      var name = el('span', '', r.short);
      name.style.fontWeight = '600';
      what.appendChild(name);
      if (r.kind === 'geo' || r.kind === 'macs') {
        var tag = el('span', 'tag info', r.kind === 'geo' ? 'geoip' : 'ieee');
        tag.style.marginLeft = '7px';
        if (r.kind === 'macs') {
          explain(tag, 'The IEEE\u2019s own registers of MAC assignments \u2014 three of '
            + 'them, because a block may be 24, 28 or 36 bits wide. With them here, pointing '
            + 'at any MAC on these pages says who made the machine.');
        }
        what.appendChild(tag);
      }
      /* Two pieces, each translated on its own: joined into one, only the
         first part ever matched a translation. (1.10.159) */
      var every = el('span', 'd muted small');
      every.appendChild(el('span', '', 'every '
        + (r.every >= 86400 ? Math.round(r.every / 86400) + ' day(s)'
           : Math.round(r.every / 3600) + ' h')));
      if (r.auto && !r.at_applies && d.update_at) {
        every.appendChild(document.createTextNode(' \u00b7 '));
        every.appendChild(el('span', '', 'on its own interval'));
      }
      what.appendChild(every);
      tr.appendChild(what);
      tr.appendChild(el('td', 'num', r.size ? num(r.size) : '–'));
      var last = el('td');
      last.appendChild(el('span', '', r.at ? shortStamp(r.at) : 'never'));
      if (r.at) last.appendChild(el('span', 'd muted small', ago(r.at)));
      tr.appendChild(last);
      var next = el('td');
      if (!r.auto) {
        var off = el('span', 'tag dim', 'switched off');
        explain(off, 'This one is not fetched by itself. It stays exactly as it was last '
          + 'fetched until somebody presses the button.');
        next.appendChild(off);
      } else {
        next.appendChild(el('span', '', shortStamp(r.next)));
        next.appendChild(el('span', 'd muted small',
          'in ' + span(r.next - Date.now() / 1000)
          + (d.update_at && r.at_applies ? ' \u00b7 at ' + d.update_at : '')));
      }
      tr.appendChild(next);
      var state = el('td');
      if (r.error) {
        var bad = el('span', 'tag crit', 'last fetch failed');
        explain(bad, (r.error.words || 'it did not work')
          + (r.error.times > 1 ? ' — ' + r.error.times + ' times in a row' : '')
          + '. It is tried again at the next round rather than given up on.');
        state.appendChild(bad);
      } else if (!r.at) {
        state.appendChild(el('span', 'tag warn', 'never fetched'));
      } else if (r.overdue > 3600) {
        var late = el('span', 'tag warn', 'overdue by ' + span(r.overdue));
        explain(late, 'It fell due and has not been fetched. Either the machine was switched '
          + 'off through the chosen hour, or the fetch is failing — once it is a day past '
          + 'due it is fetched whatever the clock says.');
        state.appendChild(late);
      } else {
        state.appendChild(el('span', 'tag ok', 'current'));
      }
      tr.appendChild(state);
      body.appendChild(tr);
    });
    explainWhatWasDrawn($('updates-table'));
  }).catch(function () { /* the card stays as it was */ });
}

$('updates-now').onclick = function () {
  api('updates', {fetch: true}).then(function (d) {
    watchJob(d.job, 'Fetching every list and the country database', function () {
      loadSettings();
    });
  }).catch(oops);
};

/* ==========================================================================
   The rail that hides itself
   --------------------------------------------------------------------------
   A column of icons at the left edge. It slides open under the pointer and
   shuts again, or stays open for good when pinned — and the pin is
   remembered, so somebody who wants it open never has to say so twice.

   The whole difficulty of this is in the CSS beside it: nothing inside the
   rail may move while it opens, or the icon somebody is pointing at slides
   out from under the mouse and they click the wrong one. Here there is only
   the opening and shutting, and the small delays that keep a pointer passing
   across the edge of the screen from flapping it.
   ========================================================================== */
var RAIL = {open: null, shut: null, pinned: false};

function pinRail(on) {
  RAIL.pinned = !!on;
  var nav = $('ctl-nav'), pin = $('ctl-pin'), layout = document.querySelector('.ctl-layout');
  if (nav) nav.classList.toggle('pinned', RAIL.pinned);
  if (layout) layout.classList.toggle('nav-pinned', RAIL.pinned);
  if (pin) {
    pin.setAttribute('aria-pressed', RAIL.pinned ? 'true' : 'false');
    explain(pin, RAIL.pinned
      ? 'The menu is staying open. Press again to let it hide itself at the edge of the '
        + 'screen, where it slides out when you point at it.'
      : 'The menu hides itself at the edge of the screen and slides out when you point at it. '
        + 'Press this to keep it open for good — it is remembered.');
  }
  try { localStorage.setItem('isemon-rail-pinned', RAIL.pinned ? '1' : '0'); } catch (e) { }
}

(function rail() {
  var nav = $('ctl-nav'), pin = $('ctl-pin');
  if (!nav) return;
  if (pin) {
    pin.innerHTML = iconMarkup('pin', 17);
    pin.onclick = function (e) { e.stopPropagation(); pinRail(!RAIL.pinned); };
  }
  var open = function () {
    clearTimeout(RAIL.shut);
    if (nav.classList.contains('open')) return;
    /* A short wait before it opens: a pointer crossing the left edge on its
       way somewhere else should not fling the menu out. */
    RAIL.open = setTimeout(function () { nav.classList.add('open'); }, 60);
  };
  var shut = function (after) {
    clearTimeout(RAIL.open);
    RAIL.shut = setTimeout(function () {
      /* not while somebody is typing in the find box, or reading its results */
      if (nav.contains(document.activeElement) && document.activeElement.id === 'ctl-find'
          && $('ctl-find').value) return;
      nav.classList.remove('open');
    }, after === undefined ? 260 : after);
  };
  /* A finger has no hover. Safari turns a tap into a mouseenter and never
     sends the mouseleave, so without this the rail opens on the first tap and
     stays open over the page for good. With a finger: a tap on the rail's own
     background opens or shuts it, picking a section shuts it, and a tap
     anywhere else on the page shuts it too. */
  var lastPointer = '';
  document.addEventListener('pointerdown', function (e) {
    lastPointer = e.pointerType || '';
    if (lastPointer !== 'mouse' && !RAIL.pinned && nav.classList.contains('open')
        && !nav.contains(e.target)) shut(0);
  }, true);
  var byFinger = function () {
    return lastPointer === 'touch' || lastPointer === 'pen'
      || (window.matchMedia && !window.matchMedia('(hover: hover)').matches);
  };
  nav.addEventListener('mouseenter', function () { if (!byFinger()) open(); });
  nav.addEventListener('mouseleave', function () { if (!byFinger()) shut(); });
  nav.addEventListener('focusin', function () { if (!byFinger()) open(); });
  nav.addEventListener('focusout', function () {
    if (!nav.contains(document.activeElement)) shut(120);
  });
  nav.addEventListener('click', function (e) {
    if (RAIL.pinned) return;
    if (e.target.closest && e.target.closest('button[data-pane]')) {
      if (byFinger()) shut(0);
      return;
    }
    if (!byFinger()) return;
    if (e.target.closest && e.target.closest('input, .ctl-found, .ctl-pin')) return;
    if (nav.classList.contains('open')) shut(0);
    else { clearTimeout(RAIL.shut); nav.classList.add('open'); }
  });
  var was = '0';
  try { was = localStorage.getItem('isemon-rail-pinned') || '0'; } catch (e) { }
  pinRail(was === '1');
}());
</script>
<script nonce="<?= h($nonce) ?>">
'use strict';
/* ==========================================================================
   GeoIP: the country database, and the country list on the router
   ========================================================================== */
function kvInto(host, k, v, d2, why) {
  var line = el('div', 'kv');
  var key = el('span', 'k', k);
  if (why) explain(key, why);
  line.appendChild(key);
  var value = el('span', 'v');
  if (v instanceof Node) value.appendChild(v); else value.textContent = v;
  if (d2) value.appendChild(el('span', 'd', d2));
  line.appendChild(value);
  host.appendChild(line);
  return line;
}

function loadGeo() {
  api('geo').then(function (d) {
    SETTINGS.countries = d.countries;
    $('geo-when').textContent = d.rows
      ? (num(d.rows) + ' range(s) · ' + d.countries.length + ' countries · fetched '
         + ago(d.at))
      : 'not fetched yet';
    $('geo-note').textContent = d.error || '';
    $('geo-note').style.color = d.error ? 'var(--crit)' : '';

    var host = $('geo-state');
    clear(host);
    var state = el('span');
    if (!d.rows) state.appendChild(el('span', 'tag warn', 'not fetched'));
    else state.appendChild(el('span', 'tag ok', 'in place'));
    kvInto(host, 'Right now', state, d.rows ? num(d.rows) + ' range(s)' : '',
           'The database is used whether or not the fetching is switched on: the switch only '
           + 'says whether to go and get a new one. A machine that has fetched one and then '
           + 'turned the switch off still has its flags.');
    kvInto(host, 'Countries it knows', d.countries.length || '–');
    kvInto(host, 'Last fetched', d.at ? stamp(d.at) : 'never',
           d.at ? ago(d.at) : 'no flags will be drawn until it is');
    if (d.error) {
      var bad = kvInto(host, 'Last attempt', d.error);
      bad.querySelector('.v').style.color = 'var(--crit)';
    }
    if (d.countries.length) {
      var flags = el('div');
      flags.style.cssText = 'display:flex;flex-wrap:wrap;gap:6px 12px;margin-top:12px';
      d.countries.slice(0, 260).forEach(function (c) {
        var one = countryBadge(c.cc);
        one.title = num(c.v4) + ' IPv4 range(s), ' + num(c.v6) + ' IPv6';
        flags.appendChild(one);
      });
      host.appendChild(flags);
      explainWhatWasDrawn(flags);
    }
  }).catch(function () { /* the card simply stays as it was */ });
}

$('geo-fetch').onclick = function () {
  confirmThen('Fetch the country database',
    'About a hundred megabytes, compressed, from db-ip’s free monthly list. It replaces '
    + 'everything currently held rather than adding to it, so what is left afterwards is one '
    + 'month’s answer and not several stacked up. It takes a minute or two.'
    + ((STATUS && STATUS.geolist.on)
       ? '<br><br>The router’s country list is filled again from it straight afterwards, '
         + 'because a new database is the one moment that list is certainly out of date.' : ''),
    'Fetch it', function () {
      api('geo', {fetch: true}).then(function (d) {
        watchJob(d.job, 'Fetching the country database', function () { loadSettings(); });
      }).catch(oops);
    }, false);
};

function loadGeolist() {
  api('geolist').then(function (d) {
    var host = $('geolist-state');
    clear(host);
    var plan = d.plan;
    var state = el('span');
    if (!d.on) state.appendChild(el('span', 'tag dim', 'switched off'));
    else if (!d.ready) state.appendChild(el('span', 'tag warn', 'not ready'));
    else state.appendChild(el('span', 'tag ok', 'ready'));
    kvInto(host, 'Right now', state,
           !d.on ? 'switch it on with the geolist setting above'
           : (!d.ready ? 'it needs a router, a list name and at least one country' : ''),
           'Switched off, nothing of this is sent anywhere and the setting is all there is. '
           + 'Ready means the router, the name and the countries are all in place.');
    kvInto(host, 'The list on the router', plan.list || '–', '',
           'Point your own firewall rule at this name. Nothing here writes a rule for you: what '
           + 'the list is FOR is a decision that belongs on the router, in front of somebody who '
           + 'can see the rest of it.');
    var flags = el('span');
    if (!plan.countries.length) flags.appendChild(el('span', 'muted', 'none chosen'));
    plan.countries.forEach(function (c) {
      var one = countryBadge(c.cc);
      one.style.marginLeft = '8px';
      one.title = num(c.v4 + c.v6) + ' range(s) would go on the router for this one';
      flags.appendChild(one);
    });
    kvInto(host, 'Countries', flags);
    kvInto(host, 'How many lines that is', num(plan.ranges) + ' prefix(es)',
           plan.ranges > 8000 ? 'a list this size is a minute or two of ssh' : '',
           'Every range of every chosen country becomes one address-list entry on the router. '
           + 'A single country is usually a few thousand; the whole of Europe is hundreds of '
           + 'thousands, which a small router will not thank you for.');
    kvInto(host, 'Families', (plan.families || []).map(function (f) { return 'IPv' + f; })
           .join(' and '));
    if (d.last) {
      kvInto(host, 'Last filled', stamp(d.last.at),
             num(d.last.added) + ' put on in ' + d.last.seconds + ' s'
             + (d.last.theirs ? ' · ' + d.last.theirs
                + ' of somebody else’s left alone' : ''));
    } else {
      kvInto(host, 'Last filled', 'never');
    }
    $('geolist-when').textContent = d.at ? 'filled ' + ago(d.at) : '';
    $('geolist-sync').disabled = !d.ready || !ADMIN;
    $('geolist-purge').disabled = !d.plan.list || !ADMIN;
    $('geolist-note').textContent = d.ready ? '' : 'nothing to send yet';
    explainWhatWasDrawn(host);
  }).catch(function () { /* leave it as it was */ });
}

$('geolist-sync').onclick = function () {
  api('geolist').then(function (d) {
    var plan = d.plan;
    confirmThen('Fill the country list on the router',
      '<b>' + num(plan.ranges) + '</b> prefix(es) for '
      + htmlText(plan.countries.map(function (c) { return c.cc; }).join(', ') || 'no country')
      + ' go on to <span class="mono">' + htmlText(plan.list) + '</span>.<br><br>'
      + 'Everything of ours already on that list comes off first, so it holds this month’s '
      + 'ranges and not last month’s as well. Anything on it <b>without</b> our mark is '
      + 'somebody else’s and is left alone, and no other list on the router is touched.'
      + (plan.ranges > 8000
         ? '<br><br>A list this size is a minute or two of ssh. You can close the window it '
           + 'opens and it carries on.' : ''),
      'Fill it now', function () {
        api('geolist', {sync: true}).then(function (d2) {
          watchJob(d2.job, 'Filling ' + plan.list + ' on the router', loadGeolist);
        }).catch(oops);
      }, false);
  }).catch(oops);
};

$('geolist-purge').onclick = function () {
  confirmThen('Empty the country list on the router',
    'Our country ranges come off <span class="mono">'
    + htmlText((STATUS && STATUS.geolist.name) || 'the country list')
    + '</span> and nothing else is touched: not the banned list, not any other address list, and '
    + 'not one firewall rule. A rule pointed at this list goes on working and simply matches '
    + 'nothing until it is filled again.',
    'Empty it', function () {
      api('mikrotik', {purge: true, which: 'geo'}).then(function (d) {
        watchJob(d.job, 'Taking our country ranges off the router', loadGeolist);
      }).catch(oops);
    });
};

/* ==========================================================================
   Reaching the router, and the key it signs in with
   ========================================================================== */
var MT_LAST = null;
function loadMikrotik() {
  api('mikrotik').then(function (d) {
    MT_LAST = d;
    drawFirewall('mt', 'mikrotik', d);
    drawFirewall('mt2', 'mikrotik2', d);
    drawPairState(d);
  }).catch(function () { /* leave it */ });
}

/** One firewall's card: whether it is set up, how it is reached, when it was
    last written to, and its key. Written once and drawn for each of them, so
    the second can never quietly say something the first would not. */
function drawFirewall(at, fw, d) {
  var id = function (what) { return $(at + '-' + what); };
  var host = id('state');
  if (!host) return;
  var wall = (d.walls || {})[fw] || {};
  var second = fw === 'mikrotik2';
  var words = second ? 'the second firewall' : 'the firewall';
  /* The kind chosen on the page, saved or not (1.10.190): what is drawn
     is about that kind, and its own key. */
  var kind = fwKindNow(fw);
  var saved = String(wall.kind || 'mikrotik');
  var pre = FW_KIND_PREFIX[kind] ? fw + '_' + FW_KIND_PREFIX[kind] : fw;
  var userKey = pre + '_user';
  var ssh = FW_SSH_KINDS.indexOf(kind) >= 0;
  var mine = (wall.keys || {})[kind] || {key: wall.key, public: wall.public};
  if (kind !== saved) {
    wall = Object.assign({}, wall, {trouble: '', at: 0});
  }
  wall = Object.assign({}, wall, {key: !!mine.key, public: mine.public || ''});
  var s = STATUS || {mikrotik: {}, geolist: {}};
  if (!SETTINGS) return;               /* drawn again once the settings are in */
  clear(host);
  if (kind !== saved) {
    host.appendChild(el('p', 'note', 'Not saved yet: until it is, ' + words + ' is still written '
      + 'to as it was. What was set for the kind it is now is kept, for switching back.'));
  }

  var state = el('span');
  if (!wall.switched) state.appendChild(el('span', 'tag dim', 'switched off'));
  else if (!wall.ready) state.appendChild(el('span', 'tag dim', 'not set up'));
  else if (wall.trouble) state.appendChild(el('span', 'tag crit', 'trouble'));
  else state.appendChild(el('span', 'tag ok', 'set up'));
  kvInto(host, 'Right now', state, wall.trouble || '',
         'Switched off means nothing is ever written to this firewall, while everything about '
         + 'how to reach it stays where it is. Not set up means the switch is on but there is '
         + 'no address yet. Set up means both. Trouble means the last time this tried to reach '
         + 'it, it could not — the words beside it are whatever ssh said'
         + (second ? ', and one of a pair being in trouble never stops the other being '
                     + 'written to.' : '.'));
  kvInto(host, 'Address', (kind === saved ? wall.host : banfeedWant(pre + '_host')) || '–',
         second ? '' : (s.mikrotik.sync ? 'kept in sync by itself' : 'filled only when asked'),
         (ssh ? 'Where this machine reaches ' + words + ' over ssh.'
          : 'Where this machine reaches ' + words + '’s API, over HTTPS.')
         + ' The two halves of a pair are two different machines and two different addresses.');
  kvInto(host, 'The ban list there',
         String(banfeedWant(fwIsPf(kind) ? 'pf_list' : 'mikrotik_list') || '–'), '',
         fwIsPf(kind)
           ? 'The alias this daemon fills with the banned addresses. Every entry in it is this '
             + 'machine’s: anything else put in it is taken out again at the next sync.'
           : 'The only list this daemon adds banned addresses to. Point a drop rule at this '
             + 'name. Both firewalls use the same name: it is one list kept on two machines.');
  if (s.geolist && s.geolist.on) {
    kvInto(host, 'The country list there',
           String(banfeedWant(fwIsPf(kind) ? 'pf_geolist' : 'geolist_name') || '–'));
  }
  kvInto(host, 'Last written to', wall.at ? stamp(wall.at) : 'never',
         wall.at ? ago(wall.at) : '',
         'When this last wrote the address lists to ' + words + '. On a pair the two are '
         + 'written in the same pass, so these should be seconds apart; minutes apart means '
         + 'one of them has been refusing.');
  var how = !ssh ? 'an API key'
    : (String(banfeedWant(pre + '_auth') || 'key') === 'password'
       ? 'a password' : (wall.key ? 'a key this machine holds' : 'a key — but there is none yet'));
  kvInto(host, 'Signing in with', how, '',
         'A key is better: it never leaves this machine, the router holds only its public '
         + 'half, and it cannot be read out of the settings by anybody who gets this far. '
         + 'Each firewall has its own key, so replacing one does not lock this out of both.');
  if (id('when')) id('when').textContent = wall.at ? 'written ' + ago(wall.at) : '';
  explainWhatWasDrawn(host);

  /* ---- the key panel ---- */
  var keyHost = id('key');
  if (!keyHost) return;
  clear(keyHost);
  /* A key is made before there is anywhere to send it: that is the order
     somebody sets a firewall up in - make the key, paste the public half
     into the router, then fill the address in here. */
  var may = ADMIN && (wall.on || wall.switched);
  id('download').disabled = !wall.key || !may;
  id('forget').disabled = !wall.key || !may;
  id('keygen').disabled = !d.can_keygen || !may;
  id('paste').disabled = !d.can_keygen || !may;
  /* "Try reaching it" reaches the firewall as it is saved: not while the
     card shows another kind not saved yet (1.10.192). */
  if (id('test')) id('test').disabled = !wall.host || kind !== saved;
  if (id('test2')) id('test2').disabled = !wall.host || kind !== saved;
  /* Said once, not once per redraw. The card is repainted whenever anything
     about the firewall changes, and without the id this line stacked up a
     copy of itself each time until the panel was nothing else. */
  var missing = $(at + '-nokeygen');
  if (!d.can_keygen && !missing) {
    missing = el('p', 'note');
    missing.id = at + '-nokeygen';
    missing.style.color = 'var(--warn)';
    missing.textContent = 'ssh-keygen is not on this machine, so a key cannot be made or read '
      + 'here: dnf install openssh-clients. A password still works.';
    id('keynote').after(missing);
  } else if (d.can_keygen && missing) {
    missing.remove();
  }
  if (!wall.public) {
    keyHost.appendChild(el('p', 'btnhelp',
      'No key yet — make one, or let it sign in with a password.'));
    return;
  }
  keyHost.appendChild(el('p', 'btnhelp', 'The public half. Click it to copy.'));
  var code = el('code', 'copyme', wall.public);
  explain(code, kind === 'mikrotik'
    ? 'Click to copy. This is the half that goes ON ' + words + '; the private half '
      + 'stays here. On RouterOS: put it in a file, then <code>/user ssh-keys import '
      + 'public-key-file=isemon.pub user='
      + htmlText(banfeedWant(userKey) || 'admin') + '</code>'
    : 'Click to copy. This is the half that goes ON ' + words + '; the private half stays '
      + 'here. It goes into the <b>Authorized keys</b> of the account <code>'
      + htmlText(banfeedWant(userKey) || 'root') + '</code> in the firewall’s user manager.');
  code.onclick = function () {
    copyText(wall.public, 'the public key is on the clipboard');
  };
  keyHost.appendChild(code);
}

/** Whether the pair are saying the same thing, said where somebody setting
    them up will look. It is the one question two firewalls exist to raise. */
function drawPairState(d) {
  var host = $('mt2-state');
  if (!host) return;
  var marks = d.marks || {};
  if (marks.agree === undefined || marks.agree === null) return;
  var line = el('div', 'kv');
  line.appendChild(el('span', 'k', 'The pair'));
  var v = el('span', 'v');
  if (marks.agree) {
    v.appendChild(el('span', 'tag ok', 'both carrying the same'));
  } else {
    v.appendChild(el('span', 'tag crit', num(marks.differs) + ' address(es) differ'));
  }
  explain(v, marks.agree
    ? 'Both firewalls are carrying exactly the same addresses of ours. That is what a pair is '
      + 'for: whichever of them takes the traffic is already dropping everything the other is.'
    : 'The two are not carrying the same addresses of ours, so whichever of them takes the '
      + 'traffic next may let through what the other is dropping. A sync puts it right; if it '
      + 'keeps happening, one of them is refusing and the trouble above says why.');
  line.appendChild(v);
  host.appendChild(line);
}

/** The five key buttons, wired for one firewall.

    There are two of them now and they do exactly the same things to
    different machines, so the handlers are written once and given the
    firewall they belong to. `at` is what its buttons are called on the page
    (`mt` or `mt2`); `fw` is what the daemon calls it. */
function wireFirewall(at, fw) {
  var words = fw === 'mikrotik2' ? 'the second firewall' : 'the firewall';
  var id = function (what) { return $(at + '-' + what); };
  var kindNow = function () { return fwKindNow(fw); };
  var userKey = function () {
    var pre = FW_KIND_PREFIX[kindNow()];
    return (pre ? fw + '_' + pre : fw) + '_user';
  };
  id('guide').onclick = function () { fwGuide(fw, kindNow()); };
  if (id('test2')) id('test2').onclick = function () { id('test').onclick.call(id('test2')); };

  id('test').onclick = function () {
    var pressed = this && this.id === at + '-test2' ? id('test2') : id('test');
    if (pressed.disabled) return;
    busy(pressed, true);
    api('mikrotik', {test: true, fw: fw}).then(function (d) {
      modal('It answered', function (body) {
        body.appendChild(el('p', 'note', kindNow() === 'mikrotik'
          ? 'This signed in to ' + words + ', ran /system identity print, and came back. '
            + 'Nothing was written and nothing was changed.'
          : 'This reached ' + words + ' and read its aliases. Nothing was written and '
            + 'nothing was changed.'));
        body.appendChild(saidBox(d.said || '(it said nothing, but it answered)'));
      }, [{words: 'Good', cls: 'primary', close: true}], true);
      loadMikrotik();
    }).catch(function (e) {
      modal('It did not answer', function (body) {
        body.appendChild(el('p', 'note', 'What ssh said when reaching ' + words + ', whole:'));
        body.appendChild(saidBox(String(e.message || e)));
        body.appendChild(el('p', 'note', FW_SSH_KINDS.indexOf(kindNow()) >= 0
          ? 'The usual causes, in the order they usually are: the public half of the key is '
            + 'not on that router yet; the account has no ssh permission; the address or port '
            + 'is wrong; or it is not reachable from this machine at all.'
          : 'The usual causes, in the order they usually are: the alias does not exist yet or '
            + 'is named differently; the API key or its secret is wrong, or the account it '
            + 'belongs to may not edit aliases; the certificate is not one this machine '
            + 'trusts; or the address or port is wrong.'));
      }, [{words: 'Close', close: true}], true);
    }).then(function () { busy(pressed, false); });
  };

  id('keygen').onclick = function () {
    confirmThen('Make a key for ' + words,
      'A fresh ed25519 pair is made here. The private half stays on this machine and the public '
      + 'half is shown for you to put on that router.<br><br><b>Any key already stored for it '
      + 'is replaced</b>, so until the new public half is on it this will not be able to sign '
      + 'in — which means bans stop reaching it until you do. The other firewall\u2019s key is '
      + 'not touched.',
      'Make one', function () {
        api('mikrotik', {generate_key: true, fw: fw, kind: kindNow()}).then(function () {
          toast('a new key was made — put the public half on ' + words, 'good');
          loadMikrotik();
        }).catch(oops);
      });
  };

  id('paste').onclick = function () {
    modal('Use my own key for ' + words, function (body) {
      var p = el('p', 'note');
      p.innerHTML = 'An OpenSSH private key, whole, including its <span class="mono">BEGIN</span> '
        + 'and <span class="mono">END</span> lines. It is kept in this machine\u2019s database '
        + 'and never shown back. Its public half is worked out here, so you do not have to hand '
        + 'that over as well.';
      body.appendChild(p);
      var area = el('textarea');
      area.rows = 11;
      area.id = at + '-paste-area';
      area.spellcheck = false;
      area.placeholder = '-----BEGIN OPENSSH PRIVATE KEY-----';
      body.appendChild(area);
      setTimeout(function () { area.focus(); }, 60);
    }, [
      {words: 'Cancel', close: true},
      {words: 'Keep this key', cls: 'primary', close: true, go: function () {
        api('mikrotik', {key: $(at + '-paste-area').value, fw: fw, kind: kindNow()})
          .then(function () {
          toast('the key was stored', 'good');
          loadMikrotik();
        }).catch(oops);
      }}
    ]);
  };

  id('download').onclick = function () {
    confirmThen('Download the private key for ' + words,
      'The private half leaves this machine as a file. Anybody holding it can sign in to that '
      + 'router as <span class="mono">'
      + htmlText(banfeedWant(userKey()) || 'that account')
      + '</span>. That it was downloaded, and by whom, is written into Events.',
      'Download it', function () {
        window.location = '?api=mikrotik-key-download&fw=' + encodeURIComponent(fw)
          + '&kind=' + encodeURIComponent(kindNow());
      });
  };

  id('forget').onclick = function () {
    confirmThen('Forget the key for ' + words,
      'The private key is deleted from this machine. Unless that router is set to take a '
      + 'password instead, nothing here will reach it until a new key is made and put on it — '
      + 'bans will go on being recorded here and will stop arriving there. The other '
      + 'firewall\u2019s key is not touched.',
      'Forget it', function () {
        api('mikrotik', {forget_key: true, fw: fw, kind: kindNow()}).then(function () {
          toast('the key is gone');
          loadMikrotik();
        }).catch(oops);
      });
  };
}

wireFirewall('mt', 'mikrotik');
wireFirewall('mt2', 'mikrotik2');

/* ---- how to set each kind of firewall up (1.10.190) -------------------- */
function fwGuide(fw, kind) {
  var second = fw === 'mikrotik2';
  var pre = FW_KIND_PREFIX[kind] ? fw + '_' + FW_KIND_PREFIX[kind] : fw;
  var list = String(banfeedWant(fwIsPf(kind) ? 'pf_list' : 'mikrotik_list')
                    || (fwIsPf(kind) ? 'isemon_ban' : 'isemon'));
  var geo = String(banfeedWant(fwIsPf(kind) ? 'pf_geolist' : 'geolist_name')
                   || (fwIsPf(kind) ? 'isemon_geo' : 'isemon-geo'));
  var user = String(banfeedWant(pre + '_user') || (kind === 'mikrotik' ? 'isemon' : 'root'));
  var me = location.hostname;
  var g = {fw: fw, second: second, list: list, geo: geo, user: user, me: me,
           geoOn: String(banfeedWant('geolist')) === '1' || banfeedWant('geolist') === true};
  var guides = {'mikrotik': guideFwMikrotik, 'opnsense-api': guideFwOpnApi,
                'opnsense-ssh': guideFwPfctl, 'pfsense-api': guideFwPfrest,
                'pfsense-ssh': guideFwPfctl};
  var words = (settingByKey(fw + '_kind') || {}).choice_words || {};
  modal('Setting it up: ' + (words[kind] || kind), function (body) {
    body.classList.add('guide');
    (guides[kind] || guideFwMikrotik)(body, g, kind);
    guideNote(body, 'Then, here: fill the settings in, <b>Save</b>, and <b>Try reaching it</b>. '
      + 'The first sync puts every banned address on ' + (second ? 'the second firewall'
      : 'the firewall') + '.', '');
  }, [{words: 'Close', close: true}]);
}

function guideFwMikrotik(body, g) {
  guideStep(body, 1, 'An account that may write the address lists',
    'On the Mikrotik, a group allowed ssh, read and write, and an account in it:',
    '/user group add name=isemon policy=ssh,read,write\n'
    + '/user add name=' + g.user + ' group=isemon password=SOMETHING-LONG');
  guideStep(body, 2, 'Its key',
    '<b>Make a key</b> below, copy its public half into a file on the Mikrotik '
    + '(<i>Files</i>, or scp) and import it for that account:',
    '/user ssh-keys import public-key-file=isemon.pub user=' + g.user);
  guideStep(body, 3, 'Drop what is on the list',
    'A rule at the top of the input and forward chains; the list fills itself:',
    '/ip firewall raw add chain=prerouting src-address-list=' + g.list + ' action=drop '
    + 'comment="isemon"\n/ipv6 firewall raw add chain=prerouting src-address-list=' + g.list
    + ' action=drop comment="isemon"'
    + (g.geoOn ? '\n/ip firewall raw add chain=prerouting src-address-list=' + g.geo
      + ' action=drop comment="isemon countries"' : ''));
}

function guideFwOpnApi(body, g) {
  guideNote(body, 'The OPNsense keeps the banned addresses in an alias of the type <b>External '
    + '(advanced)</b>: an alias whose content is left to whoever fills it, through its API. '
    + 'Each ban goes on the moment it is made.');
  guideStep(body, 1, 'Make the alias',
    '<b>Firewall → Aliases → +</b>: <b>Name</b> <span class="mono">'
    + htmlText(g.list) + '</span>, <b>Type</b> External (advanced). Save and <b>Apply</b>.'
    + (g.geoOn ? ' The same again for the country list, <span class="mono">' + htmlText(g.geo)
      + '</span>.' : ''));
  guideStep(body, 2, 'Block it',
    '<b>Firewall → Rules → WAN</b> (and every other interface facing the internet): a '
    + 'rule at the top with <b>Action</b> Block, <b>Source</b> <span class="mono">'
    + htmlText(g.list) + '</span>, <b>Destination</b> any. Save and <b>Apply changes</b>.');
  guideStep(body, 3, 'An account with an API key',
    '<b>System → Access → Users → +</b>: a user <span class="mono">isemon</span> '
    + 'with a long random password it will never use, and under <b>Effective Privileges</b> '
    + '<i>Firewall: Alias: Edit</i> and nothing else. Save; then, in the list of users, the '
    + '<b>API keys</b> button beside it makes a key and downloads it as a file holding '
    + '<span class="mono">key=</span> and <span class="mono">secret=</span>. Those two go into '
    + 'the settings here.');
  guideStep(body, 4, 'Its certificate',
    'This machine reaches the OPNsense over HTTPS on its web interface’s port. With the '
    + 'certificate it makes for itself, switch <i>Check its HTTPS certificate</i> off — or '
    + 'give the OPNsense a certificate this machine trusts and leave it on.');
  guideNote(body, '<b>An External alias is empty after the OPNsense restarts.</b> Its content '
    + 'lives only in the pf table. The sync here puts it back: set <i>Look at the firewall every '
    + '(min)</i> to a few minutes rather than only on a change.', 'warn');
}

function guideFwPfrest(body, g) {
  guideNote(body, 'pfSense has no API of its own. The <b>REST API package</b> from pfrest.org '
    + 'adds one; it is installed from its own release, not from the package manager. Each change '
    + 'here is written into the pfSense configuration and the filter reloaded, so what it holds '
    + 'survives a restart — and every change costs a filter reload.');
  guideStep(body, 1, 'Install the REST API package',
    'From <b>Diagnostics → Command Prompt</b> or a shell, with the release matching your '
    + 'pfSense version (see pfrest.org):',
    'pkg-static add https://github.com/jaredhendrickson13/pfsense-api/releases/latest/download/'
    + 'pfSense-2.8.1-pkg-RESTAPI.pkg');
  guideStep(body, 2, 'An API key',
    '<b>System → REST API → Settings</b>: enabled, with <i>API Key</i> among the '
    + 'authentication methods. Then <b>Keys → Add</b>, for a user allowed to edit aliases '
    + 'and apply changes. The key it shows once goes into the settings here.');
  guideStep(body, 3, 'Make the alias',
    '<b>Firewall → Aliases → IP → Add</b>: <b>Name</b> <span class="mono">'
    + htmlText(g.list) + '</span>, <b>Type</b> Network(s). If it insists on an entry, put '
    + '<span class="mono">192.0.2.1</span>; the first sync replaces it. Save and <b>Apply '
    + 'Changes</b>.' + (g.geoOn ? ' The same again for the country list, <span class="mono">'
      + htmlText(g.geo) + '</span>.' : ''));
  guideStep(body, 4, 'Block it',
    '<b>Firewall → Rules → WAN</b>: a rule at the top with <b>Action</b> Block, '
    + '<b>Source</b> Single host or alias <span class="mono">' + htmlText(g.list) + '</span>. Save '
    + 'and <b>Apply Changes</b>.');
  guideNote(body, 'A pfSense alias of tens of thousands of entries makes every apply slow. For '
    + 'a large country list, the ssh way below is lighter.', 'warn');
}

function guideFwPfctl(body, g, kind) {
  var opn = kind === 'opnsense-ssh';
  guideNote(body, 'This signs in over ssh and runs <span class="mono">pfctl</span> on the '
    + 'alias’s table, and nothing else. ' + (opn
      ? 'On an OPNsense, an alias of the type <b>External (advanced)</b> is the one meant for it.'
      : 'On a pfSense the tables are filled again from the configuration whenever the filter is '
        + 'reloaded, and what this put in them goes with it: the sync here puts it back.'));
  guideStep(body, 1, 'Switch ssh on',
    opn ? '<b>System → Settings → Administration → Secure Shell</b>: enabled, '
          + 'and <i>Permit root user login</i> if the account is root.'
        : '<b>System → Advanced → Admin Access → Secure Shell</b>: enabled, '
          + 'with <i>Public Key Only</i>.');
  guideStep(body, 2, 'The account and its key',
    '<b>Make a key</b> below and put its public half into <b>Authorized keys</b> of the account '
    + '<span class="mono">' + htmlText(g.user) + '</span> (' + (opn
      ? '<b>System → Access → Users</b>'
      : '<b>System → User Manager</b>') + '). Root, or an account allowed to run '
    + '<span class="mono">pfctl</span> through sudo — then switch <i>Through sudo</i> on '
    + 'here.' + (opn ? '' : ' sudo is the <i>sudo</i> package on a pfSense.'));
  guideStep(body, 3, 'Make the alias',
    (opn ? '<b>Firewall → Aliases → +</b>: <b>Type</b> External (advanced), '
         : '<b>Firewall → Aliases → IP → Add</b>: <b>Type</b> Network(s), ')
    + '<b>Name</b> <span class="mono">' + htmlText(g.list) + '</span>. Save and apply.'
    + (g.geoOn ? ' The same again for the country list, <span class="mono">' + htmlText(g.geo)
      + '</span>.' : ''));
  guideStep(body, 4, 'Block it',
    '<b>Firewall → Rules → WAN</b>: a rule at the top with <b>Action</b> Block, '
    + '<b>Source</b> <span class="mono">' + htmlText(g.list) + '</span>. Save and apply. From '
    + 'this machine, a try:', 'ssh ' + g.user + '@FIREWALL pfctl -t ' + g.list + ' -T show');
  guideNote(body, 'The table is emptied when the firewall restarts' + (opn ? '' : ' or reloads '
    + 'its filter') + ': set <i>Look at the firewall every (min)</i> to a few minutes rather '
    + 'than only on a change.', 'warn');
}

$('mt-sync').onclick = function () {
  var s = STATUS || {mikrotik: {}, geolist: {}};
  confirmThen('Sync every address list now',
    'The banned addresses go on to <span class="mono">' + htmlText(s.mikrotik.list || 'the ban list')
    + '</span>'
    + ((s.geolist.on && (s.geolist.countries || []).length)
       ? ', and the chosen countries on to <span class="mono">' + htmlText(s.geolist.name) + '</span>'
       : '')
    + '.<br><br>Only entries carrying our own mark are added or removed. Anything you put there '
    + 'by hand, every other address list on the router, and all of your firewall rules are left '
    + 'exactly as they are.',
    'Sync them', function () {
      api('mikrotik', {sync: true}).then(function (d) {
        watchJob(d.job, 'Putting the banned list on the router', function () {
          loadMikrotik();
          if (s.geolist.on && (s.geolist.countries || []).length) {
            api('geolist', {sync: true}).then(function (d2) {
              watchJob(d2.job, 'Filling the country list on the router', loadGeolist);
            }).catch(oops);
          }
        });
      }).catch(oops);
    }, false);
};
$('mt-purge').onclick = function () { purgeRouter(); };
</script>
<script nonce="<?= h($nonce) ?>">
'use strict';
/* ==========================================================================
   Accounts
   ========================================================================== */
function loadUsers() {
  api('users').then(function (d) {
    var rows = (d.users || []).filter(Boolean);
    var laid = Object.keys(COLS).length;
    $('cols-count').textContent = laid ? num(laid) + ' table(s) laid out by you'
      : 'every table as it comes';
    $('users-count').textContent = num(rows.length) + ' account(s)';
    var host = $('users-list');
    clear(host);
    host.appendChild(listView({
      key: 'users', rows: rows, per: 25, barFrom: 10,
      placeholder: 'a name, a role, a note\u2026',
      explain: 'Searches every account, not the page in front of you.',
      empty: 'No accounts',
      hay: function (u) {
        return [u.name, u.role, u.note, u.disabled ? 'off switched off' : 'on',
                u.must_change ? 'must change' : ''].filter(Boolean).join(' ');
      },
      draw: function (page, where) { where.appendChild(userRows(page, d)); }
    }));
    explainWhatWasDrawn(host);
  }).catch(oops);
}

function userRows(rows, d) {
  var wrap = el('div', 'scroll');
  var table = el('table', 'plain users');
  var thead = el('thead'), hr = el('tr');
  ['Name', 'Role', 'State', 'Made', 'Last signed in', 'Note', ''].forEach(
    function (h) { hr.appendChild(el('th', '', h)); });
  thead.appendChild(hr);
  table.appendChild(thead);
  var body = el('tbody');
  (function () {
    rows.forEach(function (u) {
      var tr = el('tr');
      var name = el('td');
      name.appendChild(el('span', 'mono', u.name));
      if (ME && u.name === ME.name) {
        var you = el('span', 'tag info', 'you');
        you.style.marginLeft = '7px';
        name.appendChild(you);
      }
      tr.appendChild(name);
      var role = el('td');
      var pill = el('span', 'tag ' + roleTone(u.role), roleWords(u.role));
      explain(pill, u.from_dir
        ? 'What <b>' + htmlText(u.name) + '</b> may do, worked out from their groups in the directory '
          + 'when they last signed in — not set here. Move them between the two groups named '
          + 'under Settings, Active Directory and this follows: at their next sign-in, and '
          + 'while they are already signed in, at the interval set there.'
        : (u.role === 'fulladmin'
           ? 'A full admin may change anything: ban, unban, settings, the router, accounts.'
           : (u.role === 'banadmin'
              ? 'A ban admin may look at every page, ban an address, let one back in and put '
                + 'the lists on the firewall - and change nothing else.'
              : 'A read only account may look at every page and change nothing.')));
      role.appendChild(pill);
      if (u.from_dir) {
        var from = el('span', 'tag info');
        from.style.marginLeft = '6px';
        from.textContent = 'from AD';
        explain(from, 'This account comes from the directory. Its password is the domain\u2019s '
          + 'and is never kept here; what it may do comes from its groups there, and is worked '
          + 'out afresh every time it signs in. Neither can be set on this page — the domain '
          + 'is where they are decided, and anything set here would be overwritten the next '
          + 'time they signed in.\nThis machine can still switch the account off, which stops '
          + 'it getting in whatever the domain says. That is the one lock that does not need a '
          + 'domain administrator.');
        role.appendChild(from);
      }
      tr.appendChild(role);
      var state = el('td');
      if (u.disabled) state.appendChild(el('span', 'tag crit', 'switched off'));
      else if (u.must_change) state.appendChild(el('span', 'tag warn', 'must change'));
      else state.appendChild(el('span', 'tag ok', 'on'));
      tr.appendChild(state);
      tr.appendChild(u.made ? stampCell(u.made) : el('td', '', '–'));
      /* Written as Made is, the day muted and the time plain (1.10.201). */
      var last = u.last_in ? stampCell(u.last_in) : el('td', '', 'never');
      if (u.last_in && u.last_from) {
        last.appendChild(el('span', 'muted', ' from '));
        last.appendChild(noI18n(el('span', '', u.last_from)));
      }
      tr.appendChild(last);
      tr.appendChild(noI18n(el('td', '', u.note || '')));
      var cell = el('td', 'acts');
      var act = el('div', 'rowacts');
      cell.appendChild(act);
      if (d.may_change) {
        /* An account the directory owns has its password and its role there.
           Offering either here is offering something that either cannot work
           or is undone at the next sign-in, and a button that quietly does
           nothing is worse than no button. What is left is the switch-off,
           which is local and does work. */
        if (u.from_dir) {
          var said = el('span', 'muted small');
          said.textContent = 'set in the directory';
          explain(said, 'The password for <b>' + htmlText(u.name) + '</b> is the domain\u2019s and is '
            + 'never kept here, and what they may do comes from their groups there. Change '
            + 'either in the domain: move them between the two groups named under Settings, '
            + 'Active Directory, and this page follows at their next sign-in — and, while '
            + 'they are already signed in, at the re-check interval set there. Taking them '
            + 'out of both groups stops them getting in at all.\nIf you need a way into this '
            + 'dashboard for when the domain cannot be reached, set a password on the server '
            + 'with <code>isemon --passwd ' + htmlText(u.name) + '</code>; it is used only while the '
            + 'directory is unreachable.');
          said.style.marginRight = '10px';
          act.appendChild(said);
        } else {
          var pw = cmdButton('Password', 'lock', 'small');
          explain(pw, 'Set a new password for ' + htmlText(u.name) + '. Every sign-in of that account '
            + 'ends at once and they are asked to choose their own next time.');
          pw.onclick = function () { setSomebodysPassword(u.name); };
          act.appendChild(pw);
          /* One of the three roles, picked: it was a button that swapped
             between two. (1.10.165) */
          var role2 = el('select', 'small');
          [['readonly', 'read only'], ['banadmin', 'ban admin'], ['fulladmin', 'full admin']]
            .forEach(function (one) {
              var o = document.createElement('option');
              o.value = one[0];
              o.textContent = one[1];
              role2.appendChild(o);
            });
          role2.value = u.role;
          explain(role2, 'What this account may do. <b>Read only</b> looks at every page and '
            + 'changes nothing; <b>ban admin</b> may also ban, let back in and put the lists on '
            + 'the firewall; <b>full admin</b> may change anything: settings, the router, '
            + 'accounts.');
          role2.style.marginLeft = '6px';
          role2.onchange = function () {
            api('users', {role_for: u.name, role: role2.value})
              .then(function () { toast(u.name + '’s role was changed', 'good'); loadUsers(); })
              .catch(function (e) { role2.value = u.role; oops(e); });
          };
          act.appendChild(role2);
        }
        if ((d.cols || {})[u.name]) {
          var back = cmdButton('Columns', 'undo', 'small');
          explain(back, u.name + ' has laid out ' + num(d.cols[u.name]) + ' table(s) by hand. '
            + 'Put every one of them back as it comes: the widths and the order of the '
            + 'columns. Nothing else of theirs changes.');
          back.style.marginLeft = '6px';
          back.onclick = function () {
            confirmThen('The columns of ' + u.name,
              'Every table ' + htmlText(u.name) + ' has laid out goes back as it comes. They see it '
              + 'the next time a page loads.',
              'Put them back', function () { colsReset(u.name).then(loadUsers).catch(oops); });
          };
          act.appendChild(back);
        }
        if (!ME || u.name !== ME.name) {
          var onoff = cmdButton(u.disabled ? 'Switch on' : 'Switch off',
                                u.disabled ? 'check' : 'cancel', 'small');
          explain(onoff, u.disabled
            ? ('Let this account sign in again. Nothing else about it changes.'
               + (u.from_dir ? ' The directory decides the rest: whether the password is '
                  + 'right, and what they may do once they are in.' : ''))
            : ('Stop this account signing in, without removing it. Whatever it is signed in as '
               + 'ends at once.'
               + (u.from_dir ? '\nThis is a lock on this machine and it beats the directory: '
                  + 'the domain can go on saying the account is fine and it still cannot get '
                  + 'in here. It survives the next sign-in, which is the point — it is the one '
                  + 'lock an administrator here can turn without a domain administrator.'
                  : '')));
          onoff.style.marginLeft = '6px';
          onoff.onclick = function () {
            api('users', {name: u.name, disable: !u.disabled}).then(function () {
              toast(u.name + ' was ' + (u.disabled ? 'switched on' : 'switched off'), 'good');
              loadUsers();
            }).catch(oops);
          };
          act.appendChild(onoff);
          var gone = cmdButton('Remove', 'trash', 'small danger');
          explain(gone, 'Delete this account for good. What it did stays in Events under its '
            + 'name; only the account goes.');
          gone.style.marginLeft = '6px';
          gone.onclick = function () {
            confirmThen('Remove ' + u.name,
              'The account is deleted and every sign-in of it ends at once. Nothing it did is '
              + 'removed — the events it left keep its name.',
              'Remove it', function () {
                api('users', {remove: u.name}).then(function () {
                  toast(u.name + ' is gone');
                  loadUsers();
                }).catch(oops);
              });
          };
          act.appendChild(gone);
        }
      }
      tr.appendChild(cell);
      body.appendChild(tr);
    });
  })();
  table.appendChild(body);
  wrap.appendChild(table);
  return wrap;
}

function passwordFields(body, withOld) {
  if (withOld) {
    body.appendChild(el('label', 'small muted', 'The password you use now'));
    var old = el('input');
    old.type = 'password';
    old.id = 'pw-old';
    old.autocomplete = 'current-password';
    old.style.width = '100%';
    old.style.margin = '4px 0 14px';
    body.appendChild(old);
  }
  body.appendChild(el('label', 'small muted', 'A new one, at least eight characters'));
  var one = el('input');
  one.type = 'password';
  one.id = 'pw-one';
  one.autocomplete = 'new-password';
  one.style.width = '100%';
  one.style.margin = '4px 0 12px';
  body.appendChild(one);
  body.appendChild(el('label', 'small muted', 'And again, so a typo cannot lock anybody out'));
  var two = el('input');
  two.type = 'password';
  two.id = 'pw-two';
  two.autocomplete = 'new-password';
  two.style.width = '100%';
  two.style.margin = '4px 0 4px';
  body.appendChild(two);
  var said = el('p', 'btnhelp');
  said.id = 'pw-said';
  body.appendChild(said);
}

function passwordsAgree() {
  var one = $('pw-one').value, two = $('pw-two').value;
  if (one.length < 8) { $('pw-said').textContent = 'that is shorter than eight characters'; return null; }
  if (one !== two) { $('pw-said').textContent = 'those two are not the same'; return null; }
  return one;
}


/* ==========================================================================
   Your account
   --------------------------------------------------------------------------
   The name at the top right is a button. It opens what this sign-in is:
   who, what they may do and where that comes from (the directory's groups
   for an account the domain owns), their password where it is kept here,
   and the columns of the tables - the switch that lets them be changed, and
   putting them back as they come. A read-only account gets all of it but
   the password of a directory account: the columns are their own view.
   ========================================================================== */
function meInitials(name, display) {
  var words = String(display || name || '?').replace(/[^\p{L}\p{N}\s._-]/gu, ' ')
    .split(/[\s._-]+/).filter(Boolean);
  var two = words.length > 1 ? words[0][0] + words[words.length - 1][0]
    : String(words[0] || name || '?').slice(0, 2);
  return two.toUpperCase();
}

/** A distinguished name as its parts: `CN=Jan Novak,OU=Staff,DC=corp,DC=loc`
    is [['cn','Jan Novak'], ['ou','Staff'], ['dc','corp'], ['dc','loc']].
    A comma written as `\,` inside a name is part of the name. */
function dnParts(dn) {
  var out = [], cur = '', i, c;
  dn = String(dn || '');
  for (i = 0; i < dn.length; i++) {
    c = dn[i];
    if (c === '\\' && i + 1 < dn.length) { cur += dn[i + 1]; i++; continue; }
    if (c === ',') { out.push(cur); cur = ''; continue; }
    cur += c;
  }
  if (cur) out.push(cur);
  return out.map(function (one) {
    var at = one.indexOf('=');
    return at < 0 ? ['', one.trim()] : [one.slice(0, at).trim().toLowerCase(),
                                        one.slice(at + 1).trim()];
  });
}

/** Where a distinguished name lives: its own name, the folders it is in
    from the top down, and the domain. */
function dnPlace(dn) {
  var parts = dnParts(dn);
  var name = parts.length ? parts[0][1] : '';
  var ous = [], dcs = [];
  parts.slice(1).forEach(function (p) {
    if (p[0] === 'dc') dcs.push(p[1]); else if (p[1]) ous.push(p[1]);
  });
  return {name: name, path: ous.reverse(), domain: dcs.join('.')};
}

/** The groups the directory said somebody is in, as they were written down:
    short names and whole distinguished names, one list. Each group once, by
    its name, with where it lives when that is known. */
function meGroups(said) {
  var raw = String(said || '');
  var cut = raw.length >= 3990;           /* the list was longer than is kept */
  var items = raw.split(/,\s+/).map(function (x) { return x.trim(); }).filter(Boolean);
  if (cut && items.length) items.pop();   /* the last one is cut short */
  var seen = {}, out = [];
  items.forEach(function (one) {
    var isDn = /^[a-z]+=/i.test(one);
    var place = isDn ? dnPlace(one) : {name: one, path: [], domain: ''};
    var key = place.name.toLowerCase();
    if (!key) return;
    if (seen[key]) {
      var had = seen[key];
      if (isDn && !had.dn) { had.dn = one; had.place = place; }
      return;
    }
    seen[key] = {name: place.name, dn: isDn ? one : '', place: place};
    out.push(seen[key]);
  });
  out.sort(function (a, b) { return a.name.localeCompare(b.name); });
  return {groups: out, cut: cut};
}

/** The file a person's own settings go into. One object with a mark of
    what it is, where and when it came from, and `settings` by section -
    `columns` now, more to join it later; a version that does not know a
    section leaves it alone. */
var ME_FILE_KIND = 'isemon-user-settings';

function meExport(button) {
  if (button) button.disabled = true;
  api('my-settings').then(function (d) {
    var file = {
      kind: ME_FILE_KIND,
      format: 1,
      from: location.host,
      version: d.version || '',
      user: d.name || (ME && ME.name) || '',
      exported: new Date().toISOString(),
      settings: d.settings || {}
    };
    var blob = new Blob([JSON.stringify(file, null, 2) + '\n'], {type: 'application/json'});
    var link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = 'isemon-settings-' + String(file.user || 'me').replace(/[^a-z0-9._-]/gi, '_')
      + '-' + file.exported.slice(0, 10) + '.json';
    document.body.appendChild(link);
    link.click();
    setTimeout(function () { URL.revokeObjectURL(link.href); link.remove(); }, 1500);
    var n = Object.keys((file.settings || {}).columns || {}).length;
    var f = ((file.settings || {}).search || []).length;
    toast('your settings were saved to ' + link.download + ' (' + num(n)
      + ' table layout(s), ' + num(f) + ' search(es))', 'good');
  }).catch(oops).then(function () { if (button) button.disabled = false; });
}

/* ---- the language of the page (1.10.153) ---------------------------------
   Which languages there are is whatever files are in web/lang/ (the page is
   handed the list); English is always one of them, being what the code is
   written in. The choice is the person's own, kept with their account, and
   in a cookie too so that the sign-in page is drawn in it before anybody
   has signed in. A change takes effect by drawing the page again. */
function langList() {
  var list = Array.isArray(window.ISEMON_LANGS) ? window.ISEMON_LANGS.slice() : [];
  if (!list.some(function (l) { return l && l.code === 'en'; })) {
    list.unshift({code: 'en', name: 'English', english: 'English'});
  }
  return list;
}
function langRemember(code) {
  try {
    document.cookie = 'isemon_lang=' + encodeURIComponent(code || 'en')
      + '; max-age=31536000; path=/; SameSite=Strict'
      + (location.protocol === 'https:' ? '; Secure' : '');
  } catch (e) { /* the sign-in page is in English then, nothing worse */ }
}
function langChoose(code, done) {
  code = String(code || 'en');
  return api('prefs', {prefs: {lang: code}}).then(function () {
    langRemember(code);
    if (done) done();
    if (code !== (window.ISEMON_LANG || 'en')) location.reload();
  });
}

function meImport(file) {
  if (file.size > 2 * 1024 * 1024) {
    toast('that file is far bigger than any settings file (' + bytes(file.size) + ')', 'bad');
    return;
  }
  var reader = new FileReader();
  reader.onerror = function () { toast('that file could not be read', 'bad'); };
  reader.onload = function () {
    var got;
    try { got = JSON.parse(String(reader.result || '')); } catch (e) {
      toast('that is not a settings file: it is not JSON', 'bad');
      return;
    }
    /* Our own file, or just its `settings` on their own. */
    var settings = got && got.kind === ME_FILE_KIND ? got.settings
      : (got && got.settings && typeof got.settings === 'object' ? got.settings : got);
    if (!settings || typeof settings !== 'object' || Array.isArray(settings)) {
      toast('that is not a settings file', 'bad');
      return;
    }
    var cols = settings.columns && typeof settings.columns === 'object'
      ? Object.keys(settings.columns).length : null;
    var other = Object.keys(settings).filter(function (k) {
      return k !== 'columns' && k !== 'search' && k !== 'prefs';
    });
    var whose = got.user ? ' of <b>' + richText(String(got.user)) + '</b>' : '';
    var at = got.exported ? Date.parse(String(got.exported)) : NaN;
    var when = isFinite(at) ? ', saved ' + richText(stamp(at / 1000)) : '';
    var from = got.from ? ' on ' + richText(String(got.from)) : '';
    confirmThen('Import settings',
      'This file holds the settings' + whose + from + when + ':<br>'
      + (cols !== null ? '&bull; the columns of ' + num(cols) + ' table(s)<br>' : '')
      + (Array.isArray(settings.search) ? '&bull; ' + num(settings.search.length)
        + ' search(es) of the find box<br>' : '')
      + (settings.prefs && typeof settings.prefs === 'object' && settings.prefs.lang
        ? '&bull; the language of the page<br>' : '')
      + (other.length ? '&bull; ' + richText(other.join(', '))
        + ' — not kept by this version, left alone<br>' : '')
      + '<br>They replace yours. Your password and your account are not touched.',
      'Import them', function () {
        api('my-settings', {settings: settings}).then(function (d) {
          if (settings.columns && typeof settings.columns === 'object') {
            Object.keys(COLS).forEach(function (k) { delete COLS[k]; });
            /* What the daemon kept, not what the file said: it is the same
               less whatever a layout cannot hold. */
            return api('my-settings').then(function (now) {
              var kept = (now.settings || {}).columns || {};
              Object.keys(kept).forEach(function (k) { COLS[k] = kept[k]; });
              colsApplyAll();
              return d;
            });
          }
          return d;
        }).then(function (d) {
          if (Array.isArray(settings.search)) {
            return api('finds').then(function (now) { FINDS = now.finds || []; return d; });
          }
          return d;
        }).then(function (d) {
          toast('imported: the columns of ' + num((d.took || {}).columns || 0) + ' table(s)'
            + ((d.took || {}).search !== undefined ? ', ' + num(d.took.search)
               + ' search(es)' : '')
            + ((d.ignored || []).length ? '; left alone: ' + d.ignored.join(', ') : ''), 'good');
          var lang = settings.prefs && typeof settings.prefs === 'object'
            ? String(settings.prefs.lang || '') : '';
          if (lang) {
            langRemember(lang);
            if (lang !== (window.ISEMON_LANG || 'en')
                && langList().some(function (l) { return l.code === lang; })) {
              location.reload();
              return;
            }
          }
          showMe();
        }).catch(oops);
      }, false);
  };
  reader.readAsText(file);
}


/** An account's groups, small enough to take in at a glance however many
    there are: the ones that gave the role first, as cards that say so; the
    rest as one wrapping line of names, where they live in the popup over
    each; past a couple of rows, the rest behind "and N more". */
function meDrawGroups(cell, label, found, gives, live) {
  var wants = function (list, gr) {
    return (list || []).some(function (w) {
      w = String(w).toLowerCase();
      return w === String(gr.name).toLowerCase() || (gr.dn && w === gr.dn.toLowerCase());
    });
  };
  var groups = found.groups.slice();
  groups.forEach(function (gr) {
    gr.gives = wants(gives.fulladmin, gr) ? 'fulladmin'
      : (wants(gives.banadmin, gr) ? 'banadmin'
         : (wants(gives.readonly, gr) ? 'readonly' : ''));
  });
  groups.sort(function (a, b) { return String(a.name).localeCompare(String(b.name)); });
  var key = groups.filter(function (g) { return g.gives; });
  var rest = groups.filter(function (g) { return !g.gives; });
  var total = found.total || groups.length;
  if (label) label.textContent = 'Groups (' + num(total) + ')';
  clear(cell);
  if (!groups.length) { cell.textContent = 'none that were read'; return; }
  var where = function (gr) {
    var bits = gr.place.path.slice();
    if (gr.place.domain) bits.push(gr.place.domain);
    return bits.join(' › ');
  };
  /* Plain words, and the distinguished name as markup of its own:
     `explain` escapes what it is given, so the markup that was in here was
     shown as text - "<span class="mono">CN=..." - and an "&" as "&amp;".
     (1.10.155) */
  var says = function (gr) { return where(gr) || (gr.dn ? ' ' : ''); };
  var dnOf = function (gr) {
    return gr.dn ? '<div class="mono" data-no-i18n>' + richText(gr.dn) + '</div>' : '';
  };
  if (key.length) {
    var cards = el('div', 'me-groups');
    key.forEach(function (gr) {
      var card = el('div', 'me-group gives' + (gr.gives === 'readonly' ? ' ro' : ''));
      card.appendChild(el('span', 'gwhy', gr.gives === 'fulladmin' ? 'makes you full admin'
        : (gr.gives === 'banadmin' ? 'makes you ban admin' : 'makes you read only')));
      var gname = el('span', 'gn', gr.name);
      gname.setAttribute('data-no-i18n', '');
      card.appendChild(gname);
      if (where(gr)) card.appendChild(el('span', 'gp', where(gr)));
      if (gr.dn) explain(card, says(gr), dnOf(gr));
      cards.appendChild(card);
    });
    cell.appendChild(cards);
  }
  if (rest.length) {
    var line = el('div', 'me-chips');
    var SHOW = 18;
    rest.forEach(function (gr, i) {
      var chip = el('span', 'me-chip', gr.name);
      chip.setAttribute('data-no-i18n', '');
      if (says(gr)) explain(chip, says(gr), dnOf(gr));
      if (i >= SHOW) chip.hidden = true;
      line.appendChild(chip);
    });
    if (rest.length > SHOW) {
      var more = el('button', 'me-chip me-chip-more', 'and ' + num(rest.length - SHOW)
                    + ' more');
      more.type = 'button';
      more.onclick = function () {
        Array.prototype.forEach.call(line.querySelectorAll('.me-chip[hidden]'),
          function (c) { c.hidden = false; });
        more.remove();
      };
      line.appendChild(more);
    }
    cell.appendChild(line);
  }
  if (total > groups.length) {
    cell.appendChild(el('div', 'me-more', num(total - groups.length) + ' more than are listed '
      + 'here; open the account in the find box for the whole record.'));
  } else if (found.cut) {
    cell.appendChild(el('div', 'me-more', 'More groups than were kept at sign-in; the ones '
      + 'that decide your role are always among them.'));
  }
  if (!live) cell.appendChild(el('div', 'me-more', 'As written down at your last sign-in.'));
}

function showMe() {
  if (!ME) return;
  var admin = ME.role === 'fulladmin';
  var ticket;
  modal('Your account', function (body) {
    var head = el('div', 'me-head');
    var ava = el('div', 'me-ava' + (admin ? ' admin' : ''), meInitials(ME.name, ME.display));
    ava.setAttribute('aria-hidden', 'true');
    head.appendChild(ava);
    var who = el('div', 'me-who');
    who.appendChild(el('div', 'me-n mono', ME.name));
    if (ME.display && ME.display !== ME.name) who.appendChild(el('div', 'me-d', ME.display));
    var tags = el('div', 'me-tags');
    tags.appendChild(el('span', 'tag ' + roleTone(ME.role), roleWords(ME.role)));
    tags.appendChild(el('span', 'tag info', ME.from_dir ? 'from AD' : 'local account'));
    who.appendChild(tags);
    head.appendChild(who);
    body.appendChild(head);

    /* What this account may do, and why. */
    var may = el('div', 'me-sec');
    may.appendChild(el('h3', '', 'What you may do'));
    may.appendChild(el('p', '', admin
      ? 'Anything: ban and unban, change the settings, talk to the router, make and change '
        + 'accounts.'
      : (ME.role === 'banadmin'
         ? 'Look at every page, ban an address, let one back in and put the lists on the '
           + 'firewall. Nothing else: no setting, no account, no taking ours off the firewall.'
         : 'Look at every page. Nothing can be changed from this account: no ban, no setting, '
           + 'not even a fetch. How your own tables are laid out is yours to change.')));
    var dir = el('div', 'me-kv');
    may.appendChild(dir);
    body.appendChild(may);

    /* This sign-in. */
    var now = el('div', 'me-sec');
    now.appendChild(el('h3', '', 'This sign-in'));
    var kv = el('div', 'me-kv');
    var row = function (host, k, v) {
      host.appendChild(el('div', 'k', k));
      var cell = el('div', 'v');
      if (v && v.nodeType) cell.appendChild(v); else cell.textContent = v || '–';
      host.appendChild(cell);
      return cell;
    };
    row(kv, 'Signed in', ME.made ? stamp(ME.made) : '–');
    row(kv, 'From', ME.ip || '–');
    var open = row(kv, 'Open sign-ins', '…');
    now.appendChild(kv);
    body.appendChild(now);

    /* The language of the page. */
    var tongue = el('div', 'me-sec');
    tongue.appendChild(el('h3', '', 'Language'));
    var tline = el('div', 'me-row');
    tline.appendChild(el('div', 'me-say', 'The language this page is shown in, for you alone. '
      + 'What the logs, the database and the command line say stays as it was written.'));
    var pickLang = el('select');
    pickLang.id = 'me-lang';
    pickLang.style.flex = '0 0 auto';
    pickLang.style.minWidth = '210px';
    /* Each language by its own name, never translated. */
    pickLang.setAttribute('data-no-i18n', '');
    pickLang.setAttribute('aria-label', 'Language');
    langList().forEach(function (l) {
      var o = el('option', '', l.name + (l.english && l.english !== l.name
        ? ' (' + l.english + ')' : ''));
      o.value = l.code;
      pickLang.appendChild(o);
    });
    pickLang.value = window.ISEMON_LANG || 'en';
    pickLang.onchange = function () {
      pickLang.disabled = true;
      langChoose(pickLang.value).catch(function (e) {
        pickLang.value = window.ISEMON_LANG || 'en';
        oops(e);
      }).then(function () { pickLang.disabled = false; });
    };
    tline.appendChild(pickLang);
    tongue.appendChild(tline);
    body.appendChild(tongue);

    /* The columns of the tables. */
    var cols = el('div', 'me-sec');
    cols.appendChild(el('h3', '', 'Columns of the tables'));
    var line = el('div', 'me-row');
    var say = el('div', 'me-say');
    say.innerHTML = '<b>Edit the columns</b><br>While this is on, the edge of any column’s '
      + 'heading can be dragged to size it and the heading itself to move it, and the right '
      + 'button on a heading hides a column, brings a hidden one back or adds an empty one '
      + 'for room; each change is kept the moment you let go. It is for this sign-in only: signing out, the sign-in '
      + 'running out or the service restarting turn it off again. Off, the tables are drawn '
      + 'as you left them and nothing can move them.';
    line.appendChild(say);
    var sw = el('label', 'sw');
    var box = el('input');
    box.type = 'checkbox';
    box.id = 'me-cols-edit';
    box.checked = COLS_EDIT;
    box.setAttribute('aria-label', 'Edit the columns');
    sw.appendChild(box);
    sw.appendChild(el('span', 'knob'));
    line.appendChild(sw);
    cols.appendChild(line);
    box.onchange = function () {
      var on = box.checked;
      box.disabled = true;
      api('columns', {edit: on}).then(function (d) {
        colsEditing(!!d.edit);
        box.checked = !!d.edit;
        toast(d.edit ? 'Columns can be sized and moved now — each change is kept at once'
          : 'Columns are held as they are', 'good');
      }).catch(function (e) {
        box.checked = COLS_EDIT;
        oops(e);
      }).then(function () { box.disabled = false; });
    };
    var laid = Object.keys(COLS).length;
    cols.appendChild(el('p', '', laid ? 'You have laid out ' + num(laid) + ' table(s).'
      : 'Every table is as it comes.')).style.marginTop = '10px';
    var acts = el('div', 'me-acts');
    var back = cmdButton('Put my columns back as they come', 'undo', 'small');
    back.id = 'me-cols-reset';
    explain(back, 'Every table you have laid out goes back as it comes: the widths and the '
      + 'order of the columns, on every page. Nobody else’s change.');
    back.disabled = !laid;
    back.onclick = function () {
      back.disabled = true;
      colsReset().then(function () { showMe(); }).catch(function (e) {
        back.disabled = false;
        oops(e);
      });
    };
    acts.appendChild(back);
    cols.appendChild(acts);
    body.appendChild(cols);

    /* Your own settings, to a file and back. */
    var mine = el('div', 'me-sec');
    mine.appendChild(el('h3', '', 'Your settings in a file'));
    mine.appendChild(el('p', '', 'How you have set this page up for yourself \u2014 the '
      + 'columns of the tables and your search history \u2014 saved as a JSON file, and read '
      + 'back here or on another machine running this. Never your password, your role or '
      + 'anything else about the account.'));
    var io = el('div', 'me-acts');
    var out = cmdButton('Export my settings', 'download', 'small');
    out.id = 'me-export';
    out.onclick = function () { meExport(out); };
    io.appendChild(out);
    var inn = cmdButton('Import settings…', 'upload', 'small');
    inn.id = 'me-import';
    var pick = el('input');
    pick.type = 'file';
    pick.accept = '.json,application/json';
    pick.hidden = true;
    pick.onchange = function () {
      var file = pick.files && pick.files[0];
      pick.value = '';
      if (file) meImport(file);
    };
    inn.onclick = function () { pick.click(); };
    io.appendChild(inn);
    io.appendChild(pick);
    mine.appendChild(io);
    body.appendChild(mine);

    /* What they have looked for in the find box. */
    var past = el('div', 'me-sec');
    past.appendChild(el('h3', '', 'Search history'));
    past.appendChild(el('p', '', FINDS.length
      ? 'The find box (Ctrl+K) remembers ' + num(FINDS.length) + ' of your searches and shows '
        + 'the ones you make most under its suggestions. One can be taken out there with the '
        + 'cross beside it.'
      : 'Nothing remembered. The searches you make in the find box (Ctrl+K) are shown under '
        + 'its suggestions, the ones you make most first.'));
    var pa0 = el('div', 'me-acts');
    var wipe = cmdButton('Clear my search history', 'forget', 'small');
    wipe.id = 'me-finds-clear';
    wipe.disabled = !FINDS.length;
    wipe.onclick = function () {
      wipe.disabled = true;
      api('finds', {clear: true}).then(function () {
        FINDS = [];
        toast('your search history is cleared', 'good');
        showMe();
      }).catch(function (e) { wipe.disabled = false; oops(e); });
    };
    pa0.appendChild(wipe);
    past.appendChild(pa0);
    body.appendChild(past);

    /* The password, where it is kept here. */
    var pw = el('div', 'me-sec');
    pw.appendChild(el('h3', '', 'Password'));
    if (ME.from_dir) {
      pw.appendChild(el('p', '', 'Your password is the domain’s and is never kept here. '
        + 'Change it the way you change it for everything else on the domain.'));
    } else {
      pw.appendChild(el('p', '', 'Kept on this machine, as a salted hash. Changing it ends '
        + 'every other sign-in of this account.'));
      var pa = el('div', 'me-acts');
      var change = cmdButton('Change my password', 'lock', 'small');
      change.id = 'me-password';
      change.onclick = function () { myPassword(false); };
      pa.appendChild(change);
      pw.appendChild(pa);
    }
    body.appendChild(pw);

    ticket = modalTicket();
    /* What the daemon knows about this account and its sign-ins: asked
       after the popup is up, so it opens at once. */
    api('users').then(function (d) {
      if (!modalStill(ticket)) return;
      var mine = (d.users || []).filter(function (u) { return u && u.name === ME.name; })[0];
      if (!mine) return;
      if (ME.from_dir) {
        row(dir, 'Where it comes from', 'Your groups in the directory, worked out again every '
          + 'time you sign in — not set here.');
        if (mine.dn) {
          var where = el('div');
          var place = dnPlace(mine.dn);
          var steps = el('div', 'me-place');
          var step = function (words, cls) {
            if (steps.children.length) steps.appendChild(el('span', 'sep', '\u203a'));
            steps.appendChild(el('span', 'step' + (cls ? ' ' + cls : ''), words));
          };
          if (place.domain) step(place.domain, 'dom');
          place.path.forEach(function (ou) { step(ou); });
          step(place.name || ME.name, 'me');
          where.appendChild(steps);
          where.appendChild(el('div', 'me-dn mono', mine.dn));
          row(dir, 'In the directory', where);
        }
        /* What was written down at sign-in first, then - when the directory
           answers - the directory's own list, which is whole and spelled the
           way the domain spells it. */
        var gcell = row(dir, 'Groups', '…');
        var glabel = gcell.previousSibling;
        meDrawGroups(gcell, glabel, meGroups(mine.groups), d.role_groups || {}, false);
        api('who&name=' + encodeURIComponent(ME.name)).then(function (w) {
          if (!modalStill(ticket) || !w || !(w.groups || []).length) return;
          var list = (w.groups || []).map(function (g) {
            return {name: g.name, dn: g.dn || '', place: dnPlace(g.dn || '')};
          });
          list.forEach(function (g) { if (!g.place.name) g.place.name = g.name; });
          meDrawGroups(gcell, glabel, {groups: list, cut: false,
                                       total: w.group_count || list.length},
                       d.role_groups || {}, true);
        }).catch(function () { /* what was written down stays */ });
      } else {
        /* Made when this was installed is said as such - "by install" read
           as a person called install. (1.10.159) */
        row(dir, 'Where it comes from', mine.made_by === 'install'
          ? 'Set on this machine when it was installed.'
          : 'Set on this machine' + (mine.made_by ? ', by ' + mine.made_by : '') + '.');
        if (mine.made) row(dir, 'Made', stamp(mine.made));
      }
      /* "from the directory" is what every directory account is noted as,
         and the tags above say it already. */
      if (mine.note && !(ME.from_dir && mine.note === 'from the directory')) {
        row(dir, 'Note', mine.note);
      }
    }).catch(function () { /* the rest of the popup is still worth having */ });
    api('sessions').then(function (d) {
      if (!modalStill(ticket)) return;
      var n = (d.sessions || []).filter(function (x) { return x.name === ME.name; }).length;
      open.textContent = num(n || 1) + (n > 1 ? ' — this one and ' + num(n - 1)
        + ' other(s)' : ' — only this one');
    }).catch(function () { open.textContent = '–'; });
  }, [{words: 'Close', close: true}], 'medium');
}
$('me-btn').onclick = showMe;

function myPassword(must) {
  modal('Change my password', function (body) {
    var p = el('p', 'note');
    p.textContent = must
      ? 'This password was set for you, and has to be changed before anything else here '
        + 'can be opened.'
      : 'Changing it ends every other sign-in of this account — a password '
        + 'changed because somebody may have learned it is no use if they are still signed in.';
    body.appendChild(p);
    passwordFields(body, true);
  }, [
    /* Not "Cancel" where it must be changed (1.10.200): the daemon answers
       nothing else until it is, and a closed popup left a page of dashes
       saying the daemon was not answering. */
    must ? {words: 'Sign out', go: function () {
      api('logout', {}).then(function () { location.reload(); })
        .catch(function () { location.reload(); });
    }} : {words: 'Cancel', close: true},
    {words: 'Change it', cls: 'primary', go: function () {
      var fresh = passwordsAgree();
      if (!fresh) return;
      api('password', {old: $('pw-old').value, new: fresh}).then(function (d) {
        closeModal();
        toast(d.message || 'your password was changed', 'good');
        if (must) setTimeout(function () { location.reload(); }, 800);
      }).catch(function (e) { $('pw-said').textContent = String(e.message || e); });
    }}
  ], true);
}

function setSomebodysPassword(name) {
  modal('Set the password for ' + name, function (body) {
    var p = el('p', 'note');
    p.textContent = 'Every sign-in of that account ends at once, and they are asked to choose '
      + 'their own the next time they sign in.';
    body.appendChild(p);
    passwordFields(body, false);
  }, [
    {words: 'Cancel', close: true},
    {words: 'Set it', cls: 'primary', go: function () {
      var fresh = passwordsAgree();
      if (!fresh) return;
      api('users', {password_for: name, password: fresh, must_change: true}).then(function () {
        closeModal();
        toast(name + '’s password was set', 'good');
        loadUsers();
      }).catch(function (e) { $('pw-said').textContent = String(e.message || e); });
    }}
  ], true);
}

$('cols-reset').onclick = function () {
  confirmThen('Put my columns back',
    'Every table you have laid out goes back as it comes: the widths and the order of the '
    + 'columns, on every page. Nobody else\u2019s tables change.',
    'Put them back', function () { colsReset().then(loadUsers).catch(oops); });
};
$('user-add').onclick = function () {
  modal('Make an account', function (body) {
    var p = el('p', 'note');
    p.innerHTML = 'A <b>full admin</b> may change anything here. A <b>read only</b> account may '
      + 'look at every page and change nothing — no ban, no setting, not even a fetch.';
    body.appendChild(p);
    body.appendChild(el('label', 'small muted', 'Name'));
    var name = el('input');
    name.type = 'text';
    name.id = 'nu-name';
    name.placeholder = 'letters, digits, dot, dash or underscore';
    name.autocapitalize = 'none';
    name.spellcheck = false;
    name.style.width = '100%';
    name.style.margin = '4px 0 14px';
    body.appendChild(name);
    body.appendChild(el('label', 'small muted', 'Role'));
    var role = el('select');
    role.id = 'nu-role';
    [['readonly', 'read only — may look at everything'],
     ['banadmin', 'ban admin — may also ban, let back in and sync the firewall'],
     ['fulladmin', 'full admin — may change everything']].forEach(function (one) {
      var o = document.createElement('option');
      o.value = one[0];
      o.textContent = one[1];
      role.appendChild(o);
    });
    role.style.width = '100%';
    role.style.margin = '4px 0 14px';
    body.appendChild(role);
    body.appendChild(el('label', 'small muted', 'A note, if it helps (optional)'));
    var note = el('input');
    note.type = 'text';
    note.id = 'nu-note';
    note.placeholder = 'the network team’s shared read-only account';
    note.style.width = '100%';
    note.style.margin = '4px 0 14px';
    body.appendChild(note);
    passwordFields(body, false);
  }, [
    {words: 'Cancel', close: true},
    {words: 'Make it', cls: 'primary', go: function () {
      /* Said here, beside the box, rather than "nothing to do" from the
         daemon. (1.10.159) */
      if (!$('nu-name').value.trim()) {
        $('pw-said').textContent = 'the account needs a name';
        $('nu-name').focus();
        return;
      }
      var fresh = passwordsAgree();
      if (!fresh) return;
      api('users', {add: $('nu-name').value.trim(), password: fresh,
                    role: $('nu-role').value, note: $('nu-note').value.trim()})
        .then(function () {
          closeModal();
          toast($('nu-name') ? 'the account was made' : 'made', 'good');
          loadUsers();
        }).catch(function (e) { $('pw-said').textContent = String(e.message || e); });
    }}
  ], true);
};

/* One sign-in ended, from its row (1.10.199): only "end them all" was there,
   which signs out everybody - the one doing it too - to end one forgotten on
   another desk. Ending your own is signing out, and is said so first. */
function sessionEndButton(one, after) {
  var b = cmdButton(one.mine ? 'Sign out' : 'Disconnect', 'undo', 'small danger');
  explain(b, one.mine
    ? 'This is the sign-in you are using: ending it signs you out of this page.'
    : 'End this one sign-in now. Whoever uses it is asked to sign in again; nothing else '
      + 'of the account changes, and its other sign-ins go on.');
  b.disabled = !ADMIN;
  b.onclick = function () {
    var go = function () {
      busy(b, true);
      api('sessions', {drop: one.id}).then(function (d) {
        if (d && d.ok === false) { oops(new Error(d.error || 'not ended')); return; }
        if (one.mine) { location.reload(); return; }
        toast('the sign-in of ' + one.name + ' from ' + (one.ip || 'somewhere')
              + ' was ended', 'good');
        after();
      }).catch(oops).then(function () { busy(b, false); });
    };
    if (one.mine) {
      confirmThen('Sign out', 'This is the sign-in you are using now: ending it signs you '
        + 'out of this page.', 'Sign me out', go);
    } else {
      go();
    }
  };
  return b;
}

function drawSessions(host, rows, again) {
  clear(host);
  if (!rows.length) {
    host.appendChild(el('p', 'center', 'Nobody, which cannot be right \u2014 you are.'));
    return;
  }
  host.appendChild(rowsTable(['Name', 'Role', 'From', 'Signed in', 'Last seen', ''],
    rows.map(function (one) {
      var who = el('span');
      who.appendChild(accountWords(one.name));
      if (one.mine) {
        who.appendChild(document.createTextNode(' '));
        who.appendChild(el('span', 'tag info', 'this one'));
      }
      var act = ADMIN && one.id ? sessionEndButton(one, again) : document.createTextNode('');
      return [who, roleWords(one.role), one.ip || '\u2013', stamp(one.made), ago(one.seen), act];
    })));
}

$('sessions-show').onclick = function () {
  api('sessions').then(function (d) {
    modal('Who is signed in', function (body) {
      var p = el('p', 'note');
      p.textContent = 'A sign-in ends by itself after the time in Settings, or sooner if it is '
        + 'left untouched. Disconnect ends one of them; ending them all signs everybody out, '
        + 'including you.';
      body.appendChild(p);
      var host = el('div');
      body.appendChild(host);
      var again = function () {
        api('sessions').then(function (fresh) {
          if (host.isConnected) drawSessions(host, fresh.sessions || [], again);
        }).catch(oops);
      };
      drawSessions(host, d.sessions || [], again);
    }, [
      {words: 'Close', close: true},
      {words: 'End them all', cls: 'danger', admin: true, close: true, go: function () {
        api('sessions', {drop_all: true}).then(function () { location.reload(); }).catch(oops);
      }}
    ]);
  }).catch(oops);
};

/* ==========================================================================
   The database
   ========================================================================== */
/* ---- erasing what was collected ------------------------------------------
   A destructive button with no list beside it is a button nobody presses, and
   one that erases more than it said is worse than one nobody presses. So the
   groups are drawn with how many rows are in each, what each one is for and
   what erasing it costs, and nothing happens to a group that is not ticked.
   The things that are NOT here - accounts, settings, the whitelist, the ssh
   key - are not drawn as unticked boxes either: they are not reachable. */
function loadErasable() {
  api('db-erasable').then(function (d) {
    var host = $('erase-list');
    if (!host) return;
    var was = {};
    Array.prototype.forEach.call(host.querySelectorAll('input[type=checkbox]'),
      function (b) { was[b.dataset.group] = b.checked; });
    clear(host);
    $('erase-size').textContent = bytes(d.bytes) + ' in all';
    (d.groups || []).forEach(function (g) {
      var row = el('label', 'erase-one'
                   + (g.rows || g.rereads || g.notes ? '' : ' empty'));
      var box = document.createElement('input');
      box.type = 'checkbox';
      box.dataset.group = g.key;
      box.checked = was[g.key] === undefined ? false : was[g.key];
      /* An empty group is nothing to tick — unless ticking it also makes
         its log be read again, which is a thing worth doing with nothing
         there at all, and the only way back for somebody who erased the
         records first and then found the times were wrong. */
      box.disabled = !ADMIN || !(g.rows || g.rereads || g.notes);
      box.onchange = markErase;
      explain(box, g.rows
        ? 'Tick this to include <b>' + g.name + '</b> in what gets erased — ' + g.says
          + ' Ticking it does nothing on its own: nothing goes until the button at the '
          + 'bottom of this card is pressed, and it says what it is about to erase first.'
        : (g.notes
           ? 'Tick this to erase <b>' + g.name + '</b> — ' + g.says
             + ' It is notes rather than rows, so there is no number beside it.'
           : g.rereads
           ? 'There is nothing in <b>' + g.name + '</b> to erase, but ticking it still '
             + 'forgets where those files were read up to, so what is in them is read '
             + 'again from the beginning with the clock as it is now.'
           : 'There is nothing in <b>' + g.name + '</b> to erase, so there is nothing '
             + 'to tick.'));
      row.appendChild(box);
      var words = el('div', 'erase-words');
      var top = el('div', 'erase-top');
      top.appendChild(el('span', 'erase-name', g.name));
      var how = el('span', 'tag ' + (g.rows ? 'info' : 'dim'),
                   g.rows ? num(g.rows) + ' row(s)'
                          : (g.notes ? 'notes, not rows' : 'already empty'));
      explain(how, g.rows
        ? 'How many rows would go if this is ticked. Everything here can be got again: the '
          + 'records by reading the logs, the lists by fetching them.'
        : (g.notes
           ? 'This one is not rows in a table: it is what was last read, kept beside them.'
           : 'There is nothing here to erase.'));
      top.appendChild(how);
      words.appendChild(top);
      words.appendChild(el('div', 'erase-says', g.says));
      row.appendChild(words);
      host.appendChild(row);
    });
    markErase();
  }).catch(function () { /* drawn before the daemon answers */ });
}
function erasePicked() {
  return Array.prototype.filter.call(
    document.querySelectorAll('#erase-list input[type=checkbox]'),
    function (b) { return b.checked; }).map(function (b) { return b.dataset.group; });
}
function markErase() {
  var picked = erasePicked();
  var go = $('erase-go');
  if (!go) return;
  go.disabled = !ADMIN || !picked.length;
  go.querySelector('span') && (go.querySelector('span').textContent =
    picked.length ? 'Erase ' + picked.length + ' of these…' : 'Erase what is ticked…');
}
if ($('erase-go')) {
  $('erase-go').onclick = function () {
    var picked = erasePicked();
    if (!picked.length) return;
    var names = Array.prototype.filter.call(
      document.querySelectorAll('#erase-list input[type=checkbox]'),
      function (b) { return b.checked; }).map(function (b) {
        return b.closest('.erase-one').querySelector('.erase-name').textContent;
      });
    confirmThen('Erase ' + (picked.length === 1 ? 'this' : 'these ' + picked.length) + '?',
      '<p>This erases, for good:</p><ul class="ask-list"><li>'
      + names.map(richText).join('</li><li>') + '</li></ul>'
      + '<p><b>Your accounts, every setting and the whitelist are not touched.</b></p>'
      + (picked.indexOf('bans') >= 0
         ? '<p class="ask-what">Erasing the bans lets <b>everybody</b> back in, starts every '
           + 'address at the bottom of the ladder again, and takes our entries off the '
           + 'router to match.</p>' : '')
      + '<p class="muted">A copy of the database is made first, so this can be undone by '
      + 'restoring it.</p>',
      'Erase it', function () {
        /* The copy is made before anything is erased rather than offered
           afterwards, when it would be a copy of the wrong thing - and it is
           made BY THE JOB rather than by this page.

           It used to be asked for here, waited for, and the erasing asked
           for afterwards. On a five gigabyte database that copy is four
           minutes inside one request, and nothing in the way of it waits
           four minutes: the proxy gave up, this `.then` never ran, and the
           erasing was never asked for at all. The copy appeared in the log,
           the daemon worked for four minutes, every row stayed exactly where
           it was, and there was no error anywhere to say so. One ask, and
           the bar says which half of the work it is on. */
        api('db-erase', {groups: picked, tidy: $('erase-tidy').checked,
                         copy: true}).then(function (r) {
          watchJob(r.job, 'Erasing the collected data', function () {
            loadErasable();
            loadDb();
            tick();
          }, 'A copy is made first, then what you ticked is emptied and the file rebuilt. '
           + 'You can close this and it carries on.');
        }).catch(oops);
      }, true);
  };
}

/* ---- what the disk under it has left ------------------------------------
   A database growing a megabyte a day on a partition with two hundred left
   is a fact somebody wants a month in advance, not on the morning the daemon
   stops being able to write anything down. */
function drawDisk(d) {
  var host = $('db-disk');
  if (!host) return;
  clear(host);
  var disk = d.disk || {};
  var grew = d.growth || {};
  /* The server's own cache, where it is left as installed and the database
     has outgrown it: the indexes are read off the disk for every line
     written, and the reading of the firewall's logs falls behind. (1.10.172) */
  var cache = d.cache;
  if (cache && cache.low) {
    var slow = el('p', 'note bad');
    slow.appendChild(el('b', '', cache.engine));
    slow.appendChild(document.createTextNode(' keeps '));
    slow.appendChild(el('b', '', bytes(cache.cache)));
    slow.appendChild(document.createTextNode(' of its own in memory ('));
    slow.appendChild(el('span', 'mono', cache.setting));
    slow.appendChild(document.createTextNode(') for a database of '));
    slow.appendChild(el('b', '', bytes(cache.size)));
    slow.appendChild(document.createTextNode('. '));
    slow.appendChild(document.createTextNode('Its indexes do not fit, so writing at thousands '
      + 'of lines a second waits for the disk. A quarter of the machine\u2019s memory is '
      + 'the usual setting.'));
    if (cache.ram) {
      slow.appendChild(document.createTextNode(' '));
      slow.appendChild(document.createTextNode('This machine has '));
      slow.appendChild(el('b', '', bytes(cache.ram)));
      slow.appendChild(document.createTextNode('.'));
    }
    if (cache.doc) {
      slow.appendChild(document.createTextNode(' '));
      slow.appendChild(document.createTextNode('The numbers for each size of machine: '));
      slow.appendChild(el('span', 'mono', cache.doc));
      slow.appendChild(document.createTextNode('.'));
    }
    host.appendChild(slow);
    if (ADMIN) {
      var go = cmdButton('Tune it for this machine\u2026', 'gear', 'small');
      go.onclick = openTune;
      host.appendChild(go);
    }
  }
  if (!disk.total) {
    host.appendChild(el('p', 'note', 'The disk this is on could not be measured.'));
    return;
  }
  var share = Number(disk.share || 0);
  var mood = share >= 92 ? 'crit' : (share >= 80 ? 'warn' : 'ok');
  var line = el('div', 'disk-bar ' + mood);
  var fill = el('span');
  fill.style.width = Math.max(1, Math.min(100, share)) + '%';
  line.appendChild(fill);
  host.appendChild(line);
  var says = el('p', 'note');
  says.innerHTML = '<b>' + bytes(disk.free) + '</b> free of ' + bytes(disk.total)
    + ' on <span class="mono">' + richText(disk.where || '') + '</span> '
    /* In pieces, each of which is a sentence's worth on its own, so that
       each is read - and translated - by itself. */
    + '<span>— ' + share + '% is in use</span>'
    + (grew.a_day ? '<span>, and this database has been growing <b>' + bytes(grew.a_day)
       + '</b> a day over the last ' + grew.over_days + ' day(s)</span>' : '') + '.';
  /* After a move there is only one measurement on the new engine, so there
     is no slope yet - and saying nothing at all reads as "it is not
     growing". */
  if (!grew.a_day) says.innerHTML += ' How fast it is growing is not known yet: '
    + 'the size is noted once a day, and two are needed.';
  host.appendChild(says);
  /* What that disk actually holds. On a server engine the database is not
     on it at all - the copies are - and a card that did not say so read as
     if the whole thing were still in that folder. */
  host.appendChild(diskHolds(disk));
  if (disk.days_left !== null && disk.days_left !== undefined) {
    var when = el('p', 'note ' + (disk.days_left < 45 ? 'bad' : ''));
    when.innerHTML = disk.days_left > 3650
      ? 'At that rate the disk has years left.'
      : 'At that rate the disk has about <b>' + num(disk.days_left) + ' day(s)</b> left. '
        + 'Forgetting old records, under <i>How long to keep things</i>, is what shortens it.';
    host.appendChild(when);
  }
  /* A database server on this machine whose files are on a disk of their
     own: that disk too, and how long it lasts - it is the one the database
     grows on. (1.10.170) */
  var dd = disk.db_disk;
  if (dd && dd.total) {
    host.appendChild(el('h4', '', 'The database\u2019s own disk'));
    var their = el('p', 'note' + (Number(dd.share || 0) >= 92 ? ' bad' : ''));
    their.innerHTML = '<b>' + bytes(dd.free) + '</b> free of ' + bytes(dd.total)
      + ' on <span class="mono">' + richText(dd.where || '') + '</span> '
      + '<span>— ' + dd.share + '% is in use</span>.';
    host.appendChild(their);
    if (dd.days_left !== null && dd.days_left !== undefined) {
      var lasts = el('p', 'note ' + (dd.days_left < 45 ? 'bad' : ''));
      lasts.innerHTML = dd.days_left > 3650
        ? 'At that rate the disk has years left.'
        : 'At that rate the disk has about <b>' + num(dd.days_left) + ' day(s)</b> left. '
          + 'Forgetting old records, under <i>How long to keep things</i>, is what shortens it.';
      host.appendChild(lasts);
    }
  }
  /* SQLite in WAL mode is three files. "17 MB" here and "260 MB" in du is a
     puzzle worth taking away. On a database server there are no files of
     ours at all, so the first column is not "File" there. */
  var parts = d.parts || [];
  if (parts.length) {
    var wrap = el('div', 'scroll');
    wrap.style.marginTop = '10px';
    var table = el('table', 'plain');
    var head = el('thead'), hr = el('tr');
    [(d.engine && d.engine !== 'sqlite') ? 'Where' : 'File',
     'What it is', {words: 'Size', cls: 'num'}].forEach(function (h) {
      hr.appendChild(h && h.cls ? el('th', h.cls, h.words) : el('th', '', h));
    });
    head.appendChild(hr);
    table.appendChild(head);
    var body = el('tbody');
    parts.forEach(function (one) {
      var tr = el('tr');
      var n = el('td');
      n.appendChild(el('span', 'mono', one.name));
      tr.appendChild(n);
      tr.appendChild(el('td', 'dim', one.what));
      tr.appendChild(el('td', 'num', bytes(one.bytes)));
      body.appendChild(tr);
    });
    table.appendChild(body);
    wrap.appendChild(table);
    host.appendChild(wrap);
  }
}

/* ---------- which database everything is kept in ----------------------

   Five buttons that happen in an order, and the order is the whole safety
   of it: try the address, make the database, carry everything across, and
   only then start using it. Each step refuses to be the one after it - a
   move into a database with anything in it is refused, and starting to use
   one that has nothing of ours in it is refused - so the way to lose
   anything here is not on the page.                                       */

var ENGINE = {};

function engineSetting(key) {
  /* What is in the boxes above, which may not be saved yet: trying a server
     before saving it is the right way round, because these are the settings
     that make a database unreachable when they are wrong. */
  var node = $('set-' + key);
  if (!node) return undefined;
  return node._get ? node._get()
    : (node.type === 'checkbox' ? (node.checked ? 1 : 0) : node.value);
}

function engineTyped() {
  var out = {};
  ['db_host', 'db_port', 'db_name', 'db_user', 'db_password', 'db_timeout_s']
    .forEach(function (key) {
      var v = engineSetting(key);
      if (v !== undefined) out[key] = v;
    });
  return out;
}

function engineChosen() {
  return String(engineSetting('db_engine') || ENGINE.engine || 'sqlite');
}

function engineWord(name) {
  var found = (ENGINE.engines || []).filter(function (e) { return e.name === name; })[0];
  return found ? found.words : name;
}

function engineAsk(act, extra) {
  var body = {act: act, to: engineChosen(), settings: engineTyped()};
  Object.keys(extra || {}).forEach(function (k) { body[k] = extra[k]; });
  return api('db-engine', body);
}

function loadEngine() {
  api('db-engine').then(function (d) {
    ENGINE = d;
    $('db-engine-file').textContent = d.file || 'the config file';
    $('db-engine-now').textContent = d.words + ' \u00b7 ' + d.where;
    var host = $('db-engine-says');
    clear(host);
    host.appendChild(peekFacts([
      ['In use now', d.words],
      ['Where', d.where],
      ['Holding', num((d.counts || {}).failed || 0) + ' failed attempt(s), '
        + num((d.counts || {}).passed || 0) + ' login(s)'],
      ['Room it takes', bytes(d.size || 0)]
    ]));
    /* Whether the driver for each engine is installed, said before somebody
       types an address rather than after they press the button. */
    Object.keys(d.drivers || {}).forEach(function (name) {
      var one = d.drivers[name];
      host.appendChild(el('p', 'btnhelp', engineWord(name) + ': '
        + (one.ready ? 'the driver is installed'
           : (one.says || 'no driver') + ' \u2014 install ' + one.package)));
    });

    /* A database that would not open is the one thing on this page that
       cannot wait to be noticed: nothing is being read and nobody is being
       banned until it is put right. */
    var bad = $('db-engine-trouble');
    bad.hidden = !d.trouble;
    if (d.trouble) {
      clear(bad);
      var h = el('h2', 'bad', 'The database is not there');
      bad.appendChild(h);
      bad.appendChild(el('p', 'note bad', String(d.trouble)));
      bad.appendChild(el('p', 'note', 'An empty one has been opened in its place so that '
        + 'this page can be used to put it right. Nothing is being read out of the logs and '
        + 'nobody is being banned. Correct the address below and start using it again \u2014 '
        + 'or go back to the file on this machine, which needs nothing and is always there.'));
    }
    engineButtons();
  }).catch(oops);
}

function engineButtons() {
  var chosen = engineChosen();
  var live = String(ENGINE.engine || 'sqlite');
  var file = chosen === 'sqlite';
  var same = chosen === live;
  if ($('db-engine-setup')) $('db-engine-setup').disabled = file;
  if ($('db-engine-test')) $('db-engine-test').disabled = false;
  if ($('db-engine-move')) $('db-engine-move').disabled = same;
  if ($('db-engine-empty')) $('db-engine-empty').disabled = same;
  if ($('db-engine-use')) $('db-engine-use').disabled = same && !ENGINE.trouble;
}

function engineFacts(d) {
  /* Only what there is an answer to: a server that was not reached has no
     table count, and a row saying so with nothing after it reads as a
     number that failed to load. */
  var facts = [['Reached', d.reached ? 'yes' : 'no'], ['Where', d.where || '']];
  if (d.version) facts.push(['It says it is', d.version]);
  if (d.reached) {
    facts.push(['Tables there', num(d.tables) + ', ' + num(d.ours) + ' of them ours']);
    facts.push(['Records in it', num(d.rows)]);
    facts.push(['May this account write', d.writable ? 'yes' : 'NO']);
  }
  return peekFacts(facts);
}

function wireEngine() {
  if (!$('db-engine-test')) return;
  $('db-engine-test').onclick = function (button) {
    busy($('db-engine-test'), true);
    engineAsk('test').then(function (d) {
      modal('Trying ' + d.words, function (body) {
        body.appendChild(el('p', 'note', 'Nothing was saved and nothing was written: this '
          + 'opened it, asked what it is, counted what is in it and closed it again.'));
        body.appendChild(engineFacts(d));
        if (!d.reached) {
          body.appendChild(el('p', 'note bad', String(d.trouble || '')));
        } else if (!d.writable) {
          body.appendChild(el('p', 'note bad', 'It answers, but this account may not make '
            + 'anything in it. Set it up, or give the account rights on that database.'));
        } else if (!d.ours) {
          body.appendChild(el('p', 'note', 'It is reachable and empty of ours, which is '
            + 'exactly what something to carry everything into should look like.'));
        }
      }, [{words: 'Close', close: true}]);
    }).catch(oops).then(function () { busy($('db-engine-test'), false); });
  };

  $('db-engine-setup').onclick = function () {
    var who, word;
    modal('Setting up ' + engineWord(engineChosen()), function (body) {
      body.appendChild(el('p', 'note', 'This makes the database and the account on that '
        + 'server, and gives the account rights on that one database and no other. The '
        + 'first time, it needs an administrator on the server to do it \u2014 root on '
        + 'MariaDB, postgres on PostgreSQL, or anyone who may create a database.'));
      body.appendChild(el('p', 'note', 'That administrator is used for this one connection '
        + 'and is stored nowhere: not in the settings, not in the database, not in any log.'));
      body.appendChild(el('p', 'note', 'The account this program will use is made with a '
        + 'password of its own, generated here \u2014 you do not have to invent one. It is '
        + 'written into the settings above, and shown once when this is done so you can keep '
        + 'a copy.'));
      body.appendChild(el('p', 'note', 'Press this again later and it does the other half of '
        + 'the job: if the account already gets in, nothing is made and no administrator is '
        + 'wanted \u2014 it opens the database and puts its tables right, adding whatever '
        + 'this version wants that an older one never made. Leave the two boxes empty for '
        + 'that.'));
      var one = el('div', 'set-item');
      one.appendChild(el('label', '', 'An administrator on that server'));
      who = el('input');
      who.type = 'text';
      who.autocomplete = 'off';
      who.placeholder = engineChosen() === 'postgres' ? 'postgres' : 'root';
      one.appendChild(who);
      one.appendChild(el('div', 'says', 'Only needed the first time, or if the account '
        + 'below cannot get in. Leave it empty to check over a database that is already '
        + 'there.'));
      body.appendChild(one);
      var two = el('div', 'set-item');
      two.appendChild(el('label', '', 'Its password'));
      word = el('input');
      word.type = 'password';
      word.autocomplete = 'off';
      two.appendChild(word);
      body.appendChild(two);
      setTimeout(function () { who.focus(); }, 60);
    }, [{words: 'Set it up', cls: 'primary', icon: 'key', go: function () {
      var ticket = modalTicket();
      engineAsk('setup', {admin_user: who.value, admin_password: word.value})
        .then(function (d) {
          /* The answer carries a password shown once, so it is never
             dropped: closed meanwhile, the popup is opened again for it
             rather than the answer being drawn into whatever popup is up. */
          if (!modalStill(ticket)) {
            modal('The database, set up', function () {}, [{words: 'Close', close: true}]);
          }
          var body = $('modal-body');
          clear(body);
          (d.made || []).forEach(function (line) {
            body.appendChild(el('p', d.existed ? 'note' : 'note good',
                                (d.existed ? '' : 'made ') + line));
          });
          body.appendChild(el('p', 'note', d.reached
            ? 'And the account reaches it: ' + (d.says || '')
            : 'But the account cannot reach it: ' + (d.says || '')));
          /* What the pass over the tables found and did. It is the same one
             this program makes on every start; asking for it is the point
             of pressing this a second time. */
          var shape = d.shape || {};
          var facts = [['Where', d.where || ''],
                       ['Tables there', num(shape.tables || 0)],
                       ['Indexes on them', num(shape.indexes || 0)],
                       ['Records in it', num(d.rows || 0)]];
          facts.push(['Anything missing', (shape.missing || []).length
            ? shape.missing.join(', ') : 'no']);
          body.appendChild(peekFacts(facts));
          /* The names of what was just made are a list, sometimes of
             fifteen. A line reads better than a box that tall. */
          if ((shape.added || []).length) {
            body.appendChild(el('p', 'note good',
              'Made just now: ' + shape.added.join(', ') + '.'));
          }
          if ((shape.missing || []).length) {
            body.appendChild(el('p', 'note bad', 'Those columns could not be added. The '
              + 'daemon\u2019s log says why; until they are there this database is not one '
              + 'this version can use.'));
          } else if (d.existed && !(shape.added || []).length) {
            body.appendChild(el('p', 'note good', 'Everything this version wants is there, '
              + 'with its columns and its indexes.'));
          }
          /* The one time it is shown. It is in config.json from now on and
             nowhere else, so somebody who wants a copy has to take it here. */
          if (d.password) {
            body.appendChild(el('h4', '', 'The password made for ' + (d.user || 'it')));
            var box = el('div', 'set-item');
            var pw = el('input');
            pw.type = 'text';
            pw.readOnly = true;
            pw.className = 'mono';
            pw.value = d.password;
            pw.onclick = function () { pw.select(); };
            box.appendChild(pw);
            body.appendChild(box);
            var row = el('div', 'btnrow');
            var copy = cmdButton('Copy it', 'copy', 'small');
            copy.onclick = function () {
              pw.select();
              var done = false;
              try { done = document.execCommand('copy'); } catch (e) { done = false; }
              if (!done && navigator.clipboard) {
                navigator.clipboard.writeText(d.password).then(function () {
                  toast('copied', 'good');
                }, function () { toast('press Ctrl+C \u2014 it is selected', 'warn'); });
              } else {
                toast(done ? 'copied' : 'press Ctrl+C \u2014 it is selected',
                      done ? 'good' : 'warn');
              }
            };
            row.appendChild(copy);
            body.appendChild(row);
            body.appendChild(el('p', 'note', 'It is saved in '
              + (d.kept_in || 'the config file') + ' and nowhere else, so nothing has to be '
              + 'typed in above. This is the only time it is shown \u2014 keep a copy if you '
              + 'want one, though nothing here needs it again.'));
          }
          body.appendChild(el('p', 'note', 'The address is saved. Nothing has moved yet: '
            + 'carry everything across when you are ready.'));
          loadSettings();
        }).catch(function (e) {
          var body = $('modal-body');
          clear(body);
          body.appendChild(el('p', 'note bad', String((e && e.message) || e)));
        });
    }}, {words: 'Close', close: true}]);
  };

  $('db-engine-move').onclick = function () {
    var word = engineWord(engineChosen());
    modal('Carrying everything into ' + word, function (body) {
      body.appendChild(el('p', 'note', 'Every record, every ban, every setting, every '
        + 'account and the whole story of every ban is copied into ' + word + '. On a large '
        + 'database this takes minutes; you can close this and it carries on.'));
      body.appendChild(el('p', 'note', 'What is here is not touched, and a copy of it is '
        + 'made first in any case. Nothing starts using the other database until you say '
        + 'so afterwards.'));
    }, [{words: 'Carry it across', cls: 'primary', icon: 'save', go: function () {
      engineAsk('move').then(function (d) {
        watchJob(d.job, 'Carrying everything into ' + word, function () {
          loadEngine();
          loadDb();
        }, 'This is copying the whole database. You can close this and it carries on; what '
           + 'it did ends up in Events either way.');
      }).catch(oops);
    }}, {words: 'Leave it', close: true}]);
  };

  $('db-engine-empty').onclick = function () {
    var word = engineWord(engineChosen());
    modal('Emptying ' + word, function (body) {
      body.appendChild(el('p', 'note bad', 'This throws away everything in the OTHER '
        + 'database \u2014 the ' + word + ' above, not the one in use. It is for when a '
        + 'first attempt at moving left something in it and the move will not go on.'));
      body.appendChild(el('p', 'note', 'Nothing in the database this installation is '
        + 'running on is touched, and this is refused outright if the two are the same.'));
    }, [{words: 'Empty it', cls: 'danger', icon: 'forget', go: function () {
      engineAsk('empty').then(function (d) {
        toast(num(d.tables) + ' table(s) thrown away; it is as good as new', 'good');
        loadEngine();
      }).catch(oops);
    }}, {words: 'Leave it', close: true}]);
  };

  $('db-engine-use').onclick = function () {
    var chosen = engineChosen();
    var word = engineWord(chosen);
    modal('Start using ' + word, function (body) {
      body.appendChild(el('p', 'note', 'This writes one setting into ' + (ENGINE.file || 'the '
        + 'config file') + ' and restarts the daemon, which takes a few seconds. Nothing in '
        + 'either database is touched.'));
      body.appendChild(el('p', 'note', chosen === 'sqlite'
        ? 'Everything will be read out of the file on this machine from then on, and the '
          + 'server may be uninstalled once you are happy.'
        : 'Everything will be read out of ' + word + ' from then on, and the file on this '
          + 'machine may be deleted once you are happy. Carry everything across first if '
          + 'you have not \u2014 this does not move anything.'));
    }, [{words: 'Start using it', cls: 'primary', icon: 'power', go: function () {
      engineAsk('use', {restart: true}).then(function (d) {
        if (d.restarting) {
          toast('now on ' + d.words + '; the daemon is restarting', 'good');
          setTimeout(function () { location.reload(); }, 12000);
        } else {
          toast('saved; restart the daemon to take it up: systemctl restart isemon', 'good');
        }
      }).catch(oops);
    }}, {words: 'Not yet', close: true}]);
  };
}

/* The two lists of files kept beside the database, which are the same table
   drawn twice: the copies this program makes, which go into any engine, and
   the dumps the engine makes of itself, which go back into that engine. What
   differs between them is one column, two sentences and which folder the
   daemon reads - so it is one function with the kind passed in. */
var ENGINE_SAID = {sqlite: 'the file on this machine', mariadb: 'MariaDB',
                   postgres: 'PostgreSQL'};
var DUMP_SAID = {sqlite: 'a copy of the file', mariadb: 'a MariaDB dump',
                 postgres: 'a PostgreSQL dump', copy: 'a portable copy'};

function keptTable(into, rows, opts) {
  clear(into);
  if (!into || !rows || !rows.length) return;
  var dump = opts.kind === 'dump';
  into.appendChild(el('h4', '', opts.head));
  var wrap = el('div', 'scroll');
  var table = el('table', 'plain');
  var thead = el('thead'), tr = el('tr');
  headCells(['Name', dump ? 'What it is' : 'Taken off', {words: 'Size', cls: 'num'}, 'Made',
             {words: '', cls: 'act'}])
    .forEach(function (th) { tr.appendChild(th); });
  thead.appendChild(tr);
  table.appendChild(thead);
  var body = el('tbody');
  rows.forEach(function (b) {
    var line = el('tr');
    var td = el('td');
    td.appendChild(el('span', 'mono', b.name));
    line.appendChild(td);
    /* A copy is a SQLite file whichever engine it came off - that is what
       makes one portable - so the file alone cannot say and each one is
       asked. A dump says it in its own ending, and cannot be anything else. */
    var came = (dump ? DUMP_SAID[b.kind || b.from] : ENGINE_SAID[b.from]) || '';
    var mine = !dump || b.mine !== false;
    var off = el('td', came ? (mine ? '' : 'muted') : 'muted', came || 'not said');
    if (!came) explain(off, 'This copy was made by a version that did not write down '
      + 'which database it was taken off. It is still a whole copy and still goes back '
      + 'into any of the three.');
    else if (!mine) explain(off, 'This dump was taken off a different engine from the one '
      + 'this installation is on now, so it cannot be put back here. Put that engine back '
      + 'on, or use a copy \u2014 a copy goes into any of the three.');
    else if (dump && b.kind === 'copy') explain(off, 'Made on a night when the program that '
      + 'dumps this engine was not on the machine, so a portable copy was made instead. It '
      + 'is a whole copy and goes back into any of the three, and it was taken off '
      + (ENGINE_SAID[b.from] || b.from) + '.');
    line.appendChild(off);
    line.appendChild(el('td', 'num', bytes(b.bytes)));
    line.appendChild(stampCell(b.at));
    var act = el('td', 'act');
    var take = cmdButton('Download', 'down', 'small');
    explain(take, dump
      ? 'Save this dump to the machine you are sitting at. It is what the engine\u2019s own '
        + 'program wrote, so its own tools read it: pg_restore, or the mariadb client.'
      : 'Save this copy to the machine you are sitting at. It is the whole database as it '
        + 'was when the copy was made, and it can be put back here or opened with any '
        + 'SQLite tool.');
    take.onclick = function () {
      window.location.href = '?api=db-download&name=' + encodeURIComponent(b.name)
        + (dump ? '&kind=dump' : '');
    };
    /* An administrator's: for anybody else it replaced the page with the
       refusal, as raw text. */
    if (ADMIN) act.appendChild(take);
    if (ADMIN) {
      var back = cmdButton('Restore', 'undo', 'small danger');
      explain(back, 'Put <b>this</b> one back, without downloading it and uploading it '
        + 'again: everything in the live database is replaced by what is in this file. '
        + 'You are shown what is in it and asked first, and a copy of what is being '
        + 'replaced is made before anything changes.');
      back.disabled = !mine;
      if (mine) back.onclick = function () { restoreKept(b, opts.kind); };
      act.appendChild(back);
      var gone = cmdButton('Delete', 'trash', 'small danger');
      explain(gone, 'Delete this file from the server. The live database is not touched.');
      gone.onclick = function () {
        confirmThen('Delete this ' + opts.kind + '?', 'The file <code>' + htmlText(b.name)
          + '</code> is deleted from this machine. The live database is not touched, and '
          + 'the others stay where they are.', 'Delete it', function () {
            api('db-delete', {name: b.name, kind: opts.kind}).then(function () {
              toast('the ' + opts.kind + ' was deleted');
              loadDb();
            }).catch(oops);
          });
      };
      act.appendChild(gone);
    }
    line.appendChild(act);
    body.appendChild(line);
  });
  table.appendChild(body);
  wrap.appendChild(table);
  into.appendChild(wrap);
  var where = el('p', 'btnhelp');
  where.textContent = opts.where;
  into.appendChild(where);
}

/** What the dumps card says about itself: which program will make tonight's,
    and - if that program is not on this machine - what is happening instead. */
function dumpCard(d) {
  var says = $('db-dump-says');
  if (!says) return;
  clear(says);
  var info = d.dump || {};
  var now = $('db-dump-now');
  if (now) now.textContent = info.words || '';
  var make = $('db-dump-make'), get = $('db-dump-get');
  if (make) make.disabled = !info.ready;
  if (get) get.disabled = !info.ready;
  if (info.ready) {
    var line = el('p', 'note good');
    line.innerHTML = 'Tonight\u2019s will be <b>' + richText(info.words || 'a dump') + '</b>'
      + (info.suffix ? ', written as <code>' + richText(info.suffix) + '</code>' : '') + '.';
    says.appendChild(line);
  } else {
    var bad = el('p', 'note bad');
    bad.textContent = info.why || 'A dump cannot be made on this machine.';
    says.appendChild(bad);
    var fix = el('p', 'note');
    fix.innerHTML = 'Until it is there, the nightly one is made as a <b>portable copy</b> '
      + 'instead \u2014 a whole copy, which goes back into any engine, but several times the '
      + 'size of a dump. To have dumps: <code>' + (info.install || '') + '</code>';
    says.appendChild(fix);
  }
}

function loadDb() {
  loadErasable();
  loadEngine();
  loadTune();
  api('db').then(function (d) {
    $('db-size').textContent = bytes(d.bytes) + ' · ' + (d.where || d.path);
    drawDisk(d);
    var host = $('db-counts');
    clear(host);
    /* Biggest first, because the question this card is asked is "what is
       taking the room". The domain events were not on it at all, which on a
       site that reads a domain is most of the database missing. */
    var names = {win_events: 'events from the domain controllers',
      win_rollup: 'those events, counted ahead of time for the Domain page',
      fw_events: 'lines from the firewall\u2019s own log',
      fw_roll: 'those lines, counted ahead of time for the Traffic page',
      seen_values: 'every name, machine, switch and value in the records, for the search box and the drop-downs',
                 failed: 'failed attempts', passed: 'successful logins',
                 otp_asked: 'records from the token logs',
                 eduroam_seen: 'machines seen on eduroam',
                 geo_ranges: 'country ranges',
                 feed_ranges: 'ranges from public lists',
                 ptr: 'names behind addresses',
                 mac_vendors: 'MAC vendor registers',
                 blocked: 'banned right now', blocked_log: 'bans there have ever been',
                 block_events: 'lines of story', events: 'events',
                 users: 'accounts', sessions: 'sign-ins', fold_versions: 'foldings kept'};
    Object.keys(names).forEach(function (k) {
      if (d.counts[k] === undefined) return;
      var line = el('div', 'kv');
      line.appendChild(el('span', 'k', names[k]));
      line.appendChild(el('span', 'v', num(d.counts[k])));
      host.appendChild(line);
    });
    /* ...and what is inside those two tables: one line per module that is
       read out of somebody else's log, with what each part of it holds and
       how far back it goes. Drawn only for modules that have anything, so a
       site reading nothing but ISE sees exactly what it always did. */
    var inside = $('db-inside');
    if (inside) {
      clear(inside);
      var MODULES = {
        tacplus: {words: 'from a tac_plus server of your own',
                  says: 'Sittings at a switch prompt, the commands run during them, and '
                      + 'anything the daemon\u2019s own log said it turned away. Erase '
                      + 'them under \u201cErase collected data\u201d below \u2014 they '
                      + 'have a group of their own there.'},
        tacacs:  {words: 'TACACS+ through ISE',
                  says: 'Sign-ins to switches and routers that ISE answered, and the '
                      + 'commands it authorised. Part of the ISE records.'},
        otp:     {words: 'from the token logs',
                  says: 'One-time passwords accepted and refused.'},
        eduroam: {words: 'from the eduroam logs',
                  says: 'Sign-ins and refusals on the visitors\u2019 network.'},
        nps:     {words: 'from a Windows NPS server',
                  says: 'What NPS let on and what it refused \u2014 sockets, radios and the '
                      + 'VPN. Erase them under \u201cErase collected data\u201d below '
                      + '\u2014 they have a group of their own there.'},
        radius:  {words: 'from a FreeRADIUS server of your own',
                  says: 'What it let on and what it refused \u2014 sockets, radios and the '
                      + 'VPN. Erase them under \u201cErase collected data\u201d below '
                      + '\u2014 they have a group of their own there.'}
      };
      var any = false;
      Object.keys(MODULES).forEach(function (key) {
        var said = (d.inside || {})[key];
        if (!said || !said.rows) return;
        any = true;
        var line = el('div', 'kv');
        var name = el('span', 'k', MODULES[key].words);
        explain(name, MODULES[key].says);
        line.appendChild(name);
        var what = [];
        Object.keys(said.parts || {}).forEach(function (part) {
          if (said.parts[part]) what.push(num(said.parts[part]) + ' ' + part);
        });
        var v = el('span', 'v', num(said.rows));
        line.appendChild(v);
        inside.appendChild(line);
        var note = el('div', 'muted small');
        note.style.cssText = 'margin:-6px 0 8px;padding-left:2px';
        note.textContent = what.join(' \u00b7 ')
          + (said.oldest ? ' \u00b7 ' + shortStamp(said.oldest) + ' to '
             + shortStamp(said.newest) : '');
        inside.appendChild(note);
      });
      if (!any) {
        inside.appendChild(el('p', 'muted small',
          'Nothing but the ISE records is in those two tables.'));
      }
    }
    keptTable($('db-backups'), d.backups, {
      kind: 'copy', keep: d.keep, engine: d.engine,
      head: 'Copies kept (' + d.keep + ' at most)',
      where: 'They are files on this machine, under /var/lib/isemon/backups. Copy them off '
             + 'it if they are to survive the machine.'
    });
    keptTable($('db-dumps'), d.dumps || [], {
      kind: 'dump', keep: d.keep, engine: d.engine,
      head: 'Dumps kept (' + d.keep + ' at most)',
      where: 'They are files on this machine, under ' + ((d.dump || {}).where || '')
             + '. Copy them off it if they are to survive the machine.'
    });
    dumpCard(d);
  }).catch(oops);
}

/* ---- taking a copy away, and putting one back ----------------------------
   Neither of these goes through `api()`: one answers with a file rather than
   JSON, and the other sends one. A database is bigger than anything else on
   this page by a factor of a thousand, so both are left to the browser and
   the web server to stream rather than being read into a string here. */
/** Put back a copy that is already on this machine.

    Nothing is uploaded: the file is where the daemon put it, so the daemon
    is simply told which one. The asking is the same asking as for a file
    somebody has just chosen, and it is the same asking on purpose - the two
    roads differ only in where the file is. */
function restoreKept(b, kind) {
  api('db-restore-kept', {name: b.name, kind: kind || 'copy', check: true}).then(function (d) {
    askBeforeRestoring(d.says, b.name, function (done) {
      return api('db-restore-kept', {name: b.name, kind: kind || 'copy'});
    });
  }).catch(oops);
}

/** What is in the file, what putting it back costs, and the question. One
    piece for both roads so they can never say different things. */
function askBeforeRestoring(says, what, go) {
  var n = (says && says.counts) || {};
  var kind = (says && says.kind) || '';
  var body = el('div');
  var head = el('p');
  if (kind && kind !== 'sqlite') {
    /* A dump is not opened to be counted: reading every row out of one to
       say how many there are would be most of the work of putting it back.
       What can be read without a server is what it is, how many tables are
       in it and whether anybody could sign in afterwards - and saying that,
       rather than four numbers that would be guesses, is the honest card. */
    head.innerHTML = '<code>' + richText(String(what)) + '</code> is <b>'
      + (DUMP_SAID[kind] || 'a dump') + '</b> made by this program. It holds <b>'
      + num(says.tables || 0) + '</b> table(s) and <b>' + num(n.users || 0)
      + '</b> account(s), <b>' + num(says.admins || 0) + '</b> of them full '
      + 'administrator(s). How many records are in it is not read from a dump — that is '
      + 'what putting it back is for.';
  } else {
    head.innerHTML = '<code>' + richText(String(what)) + '</code> is a database of ours. It holds <b>'
      + num(n.failed || 0) + '</b> failed attempt(s), <b>' + num(n.passed || 0)
      + '</b> successful login(s), <b>' + num(n.blocked || 0) + '</b> address(es) banned and <b>'
      + num(n.users || 0) + '</b> account(s).';
  }
  body.appendChild(head);
  /* A full backup (1.10.222): its keys go in place too. */
  if (says && (says.carried || []).length) {
    var full = el('p', 'note');
    full.innerHTML = 'It is a <b>full backup</b>: it carries ' + (says.carried || []).map(function (x) {
      return '<code>' + richText(String(x)) + '</code>';
    }).join(', ') + '. The keys are put in place with it (the ones here now are kept beside '
      + 'them), so the passwords, the routers\u2019 keys and the certificate in it open here; '
      + 'config.json is in it to read only and is not used.';
    body.appendChild(full);
  }
  var warn = el('p');
  warn.innerHTML = 'Putting it back <b>replaces everything</b> in the live database with what '
    + 'is in that file. A copy of what is being replaced is made first and kept with the '
    + 'others, so this can be undone — but everything recorded since that file was made will '
    + 'only be in that copy.';
  body.appendChild(warn);
  var out = el('p', 'btnhelp');
  out.textContent = 'You will probably be signed out: who is signed in came with the file like '
    + 'everything else. Afterwards the daemon reads the ISE logs forward from wherever that '
    + 'file says it had got to, and writes the router again.';
  body.appendChild(out);
  modal('Put this database back?', body, [
    {words: 'No, leave it', close: true},
    {words: 'Restore it', cls: 'danger', icon: 'undo', close: true, go: function () {
      go().then(function (done) {
        toast('the database was restored; what it replaced is in ' + done.safety, 'good');
        setTimeout(function () { window.location.reload(); }, 1800);
      }).catch(oops);
    }}], true);
}

/* ---- starting the counting again ---------------------------------------- */
/* Read every stored domain event again with the settings as they stand.

   What an event MEANS is worked out once, when the line is read, and kept
   beside the row - which controller wrote it, whether that account
   replicating the directory was expected. Name a controller and the rows
   already here still carry yesterday's answer. It is put right on its own
   when the settings are saved; this is the button for watching it happen. */
function rereadWindows(from) {
  var b = $(from);
  if (!b) return;
  b.disabled = true;
  /* The bar belongs to the page it is on, and the press should show at once
     rather than at the next poll. */
  api('win-reread', {}).then(function (d) {
    toast(d.message || 'going through them', 'good');
    /* Keep asking, rather than deciding from one answer.

       The bar is drawn from the daemon's own answer, and the first answer
       after the press said nothing was going - the job begins by asking two
       domain controllers about their groups, which on a real domain is a
       minute of waiting with nothing to count. The page took that one answer
       as "no job", stopped asking, and the bar turned up at the end when
       some later poll happened to catch it. So the press starts a watch that
       runs whatever the first answer says, and it is the daemon that ends
       it. */
    WIN_GOING = true;
    WIN_WATCH_UNTIL = Date.now() + WIN_WATCH_FOR;
    setTimeout(function () { loadWindows(); }, 400);
  }).catch(oops).then(function () {
    b.disabled = false;
  });
}
if ($('acls-open')) { $('acls-open').onclick = peekAcls; }
/* ---- the counting, on the page it is about -------------------------------
   Its state, and the two things somebody may ask of it. Read every time this
   pane is opened and after either button, because the state is the daemon's
   and not the browser's: it survives a reload and a second person watching. */
function drawRollup() {
  var box = $('winsec-roll');
  if (!box) return;
  api('win-rollup', {}).then(function (d) {
    box.hidden = !d.on;
    if (!d.on) return;
    var says = $('winsec-roll-says');
    clear(says);
    var many = (d.buckets && d.events)
      ? (' \u2014 ' + num(Math.round(d.events / d.buckets)) + ' events to a counted row')
      : '';
    if (d.believed) {
      says.appendChild(el('b', 'ok', 'In use.'));
      says.appendChild(document.createTextNode(
        ' The Domain page is drawn from ' + num(d.buckets) + ' counted row(s) for '
        + num(d.events) + ' event(s)' + many + '. It has agreed with the events '
        + num(d.checks) + ' time(s) since it was proved, and it is read back against '
        + 'them every hour'
        + (d.at ? ' \u2014 last ' + ago(d.at) : '') + '.'));
      /* The one thing somebody actually wants to know, said outright: this
         is not a snapshot and there is nothing to wait for. An event is in
         the counting in the same transaction that writes it down, so what
         the page shows is what the database holds, this second. */
      says.appendChild(el('span', 'muted',
        ' Nothing waits for any of this: an event is counted in the same '
        + 'transaction that writes it down, so the Domain page shows what the '
        + 'database holds this second. The counting only decides how the page '
        + 'asks, never how old its answer is.'));
    } else if (d.state === 'bad') {
      says.appendChild(el('b', 'bad', 'Put aside.'));
      says.appendChild(document.createTextNode(
        ' ' + (d.why || 'it disagreed with the events') + ' \u2014 found by '
        + (d.version || 'an older version') + ' and written down then; nothing is '
        + 'being checked while it stands. The page is asking the events themselves, '
        + 'so nothing it shows is wrong, only slower.'));
      /* ...and what to do about it, in the order worth trying. Reading it
         back is the same proof a fresh counting has to pass, so a counting
         put aside by a fault that has since been mended comes back without
         anything being counted twice. */
      says.appendChild(el('span', 'muted',
        ' Read it back against the events first: if every sum adds up it is used '
        + 'again from that moment, and nothing has to be counted twice. Count them '
        + 'all again where it does not.'));
    } else {
      says.appendChild(el('b', '', 'Not counted yet.'));
      says.appendChild(document.createTextNode(
        ' The daemon does it when it next looks around, or the button below does it '
        + 'now. Until then the page asks the events themselves.'));
    }
    if (d.newest) {
      says.appendChild(el('span', 'muted',
        ' Newest hour counted: ' + shortStamp(d.newest) + '.'));
    }
    /* ...and whether one is going on right now - which may be the daemon,
       this page, or somebody at a terminal. Two countings at once would
       each throw away what the other had just written, so the buttons wait
       while one runs. */
    if (d.busy) {
      says.appendChild(el('b', 'ok',
        ' ' + d.busy.charAt(0).toUpperCase() + d.busy.slice(1) + ' right now.'));
      says.appendChild(document.createTextNode(
        ' It may have been started here, by the daemon, or at a terminal. '
        + 'The page goes on working while it runs.'));
    }
    var pressable = !d.busy;
    if ($('winsec-rollbuild')) $('winsec-rollbuild').disabled = !pressable;
  }).catch(function () { box.hidden = true; });
}

