/** Send a chosen file to be put back. `check` asks the daemon to read it and
    say what is in it without replacing anything - which is what makes the
    warning shown afterwards a statement about this file rather than about
    files in general. The daemon reads what arrived to find out whether it is
    a copy or a dump, so nothing here has to say which. */
function dbSend(file, check) {
  /* The bar along the top while it goes, like every other wait; never a
     Stop - a database half put back is not a thing to offer. */
  var waiting = waitStart();
  /* The file itself as the body (1.10.218), not a multipart form: nothing on
     this page sends one, and a multipart body is what php2shell
     (CVE-2026-109618/-109619) comes in by - the web server refuses them. */
  var sent = fetch('?api=db-restore' + (check ? '&check=1' : ''),
               {method: 'POST', body: file, credentials: 'same-origin',
                /* A header a form on another page cannot send (1.10.176). */
                headers: {'X-Isemon-Restore': '1',
                          'Content-Type': 'application/octet-stream'}});
  sent.then(function () { waitDone(waiting); }, function () { waitDone(waiting); });
  return sent
    .then(function (r) {
      return r.json().catch(function () {
        throw new Error('the server did not answer with anything readable');
      }).then(function (d) {
        if (!r.ok || d.ok === false) {
          throw new Error(d.error || ('the server said ' + r.status));
        }
        return d;
      });
    });
}

/** Wire up one drop box: the one for copies, and the one for dumps. Both do
    exactly the same thing to whatever is dropped on them - the file is read
    before anything happens, so choosing the wrong box costs a sentence. */
function dropBox(ids, empty) {
  var held = null;
  var box = $(ids.drop);
  if (!box) return;
  function picked(file) {
    held = file || null;
    var says = $(ids.what);
    clear(says);
    says.hidden = !held;
    $(ids.go).disabled = !held;
    $(ids.says).textContent = held ? held.name + ' · ' + bytes(held.size) : empty;
    if (!held) return;
    var line = el('p', 'btnhelp');
    line.innerHTML = 'Nothing has happened yet. Press <b>Restore from this file</b> and it '
      + 'will be read first — if it is not one of ours, if it is a dump of a different '
      + 'engine, or if it has no administrator in it, it is refused and nothing here changes.';
    says.appendChild(line);
  }
  box.onclick = function () { $(ids.file).click(); };
  $(ids.file).onchange = function () { picked(this.files && this.files[0]); };
  ['dragenter', 'dragover'].forEach(function (name) {
    box.addEventListener(name, function (e) {
      e.preventDefault();
      box.classList.add('over');
    });
  });
  ['dragleave', 'drop'].forEach(function (name) {
    box.addEventListener(name, function (e) {
      e.preventDefault();
      box.classList.remove('over');
      if (name === 'drop' && e.dataTransfer && e.dataTransfer.files) {
        picked(e.dataTransfer.files[0]);
      }
    });
  });
  $(ids.go).onclick = function () {
    if (!held) return;
    busy($(ids.go), true);
    dbSend(held, true).then(function (d) {
      askBeforeRestoring(d.says, held.name, function () { return dbSend(held, false); });
    }).catch(oops).then(function () { busy($(ids.go), false); });
  };
}

dropBox({drop: 'db-drop', file: 'db-file', says: 'db-drop-says',
         what: 'db-upload-what', go: 'db-restore'},
        'Drop a database file here, or press to choose one');
