/* ---- the database server's own settings, for its machine (1.10.173) ----
   What the machine the server runs on has, the settings worked out for it
   beside what is there now, and - when somebody says so - put in. An
   administrator typed in here goes in the one request that needs it and is
   kept by nobody: not by this page once the popup is closed, not by the
   daemon, not in any log. */
var TUNE = null;

function tuneValue(kind, v) {
  if (v === null || v === undefined || v === '') return '–';
  if (kind === 'mem') return bytes(v);
  if (kind === 'time') return num(v) + ' s';
  if (kind === 'bool') return v ? 'on' : 'off';
  if (kind === 'real') return String(Math.round(Number(v) * 100) / 100).replace('.', numDecimal());
  if (kind === 'int') return num(v);
  return String(v);
}

function loadTune() {
  var host = $('db-tune-says');
  if (!host) return;
  api('db-tune').then(function (d) {
    clear(host);
    var file = d.engine === 'sqlite';
    $('db-tune').hidden = file;
    $('db-tune-undo').hidden = file || !d.last || !!d.last.undone || d.last.engine !== d.engine;
    $('db-tune-restart').hidden = true;
    if (file) {
      host.appendChild(el('p', 'note', 'The file on this machine has no server to tune: this '
        + 'program sets it up itself.'));
      return;
    }
    var last = d.last;
    if (last && last.engine === d.engine) {
      var p = el('p', 'note');
      if (last.undone) {
        p.appendChild(document.createTextNode('Put back as it was before'));
        p.appendChild(document.createTextNode(' ' + stamp(last.undone)
          + (last.undone_by ? ' · ' + last.undone_by : '') + '.'));
      } else {
        p.appendChild(document.createTextNode('Tuned for its machine'));
        p.appendChild(document.createTextNode(' ' + stamp(last.at)
          + (last.by ? ' · ' + last.by : '') + ':'));
        var set = last.set || {};
        Object.keys(set).sort().forEach(function (n, i) {
          p.appendChild(document.createTextNode(i ? ', ' : ' '));
          p.appendChild(el('span', 'mono', n + ' = ' + set[n]));
        });
      }
      host.appendChild(p);
    } else {
      host.appendChild(el('p', 'note', 'Not tuned from this page yet.'));
    }
    if ((d.pending || []).length) {
      var w = el('p', 'note bad');
      w.appendChild(document.createTextNode('Waiting for the server’s next start:'));
      d.pending.forEach(function (n, i) {
        w.appendChild(document.createTextNode(i ? ', ' : ' '));
        w.appendChild(el('span', 'mono', n));
      });
      host.appendChild(w);
      if (d.restart && d.restart.may) {
        $('db-tune-restart').hidden = false;
      } else {
        host.appendChild(el('p', 'note', 'On the server, as root:'));
        host.appendChild(guideCode('systemctl restart '
          + ((d.restart && d.restart.unit) || 'postgresql')));
      }
    }
    if ((d.lost || []).length) {
      var l = el('p', 'note bad');
      l.appendChild(document.createTextNode('MariaDB has been started again since, and these '
        + 'are back as they were:'));
      d.lost.forEach(function (n, i) {
        l.appendChild(document.createTextNode(i ? ', ' : ' '));
        l.appendChild(el('span', 'mono', n));
      });
      host.appendChild(l);
      host.appendChild(el('p', 'note', 'The file the popup gives keeps them over a restart.'));
    }
  }).catch(function () {});
}

/* The administrator's two boxes, drawn into a popup and read back. */
function tuneAdminBoxes(body, engine, already) {
  var one = el('div', 'set-item');
  one.appendChild(el('label', '', 'An administrator on that server'));
  var who = el('input');
  who.type = 'text';
  who.autocomplete = 'off';
  /* Not a sign-in of this page: no password manager is to keep it. */
  who.setAttribute('data-lpignore', 'true');
  who.setAttribute('data-1p-ignore', '');
  who.placeholder = engine === 'postgres' ? 'postgres' : (engine === 'mariadb' ? 'root' : '');
  who.value = (already && already.user) || '';
  one.appendChild(who);
  one.appendChild(el('div', 'says', 'Used for this one request and stored nowhere: not in '
    + 'the settings, not in the database, not in any log.'));
  body.appendChild(one);
  var two = el('div', 'set-item');
  two.appendChild(el('label', '', 'Its password'));
  var word = el('input');
  word.type = 'password';
  word.autocomplete = 'new-password';
  word.setAttribute('data-lpignore', 'true');
  word.setAttribute('data-1p-ignore', '');
  word.value = (already && already.pass) || '';
  two.appendChild(word);
  body.appendChild(two);
  return {who: who, word: word};
}

/* The boxes emptied and what was read out of them dropped, when the popup
   closes: a password left in a hidden box is still a password on the page. */
function tuneForget() {
  TUNE = null;
  Array.prototype.forEach.call(document.querySelectorAll('#modal-body input'),
    function (i) { i.value = ''; });
}

function openTune() {
  TUNE = {user: '', pass: '', ram: '', cpus: '', disk: '', plan: null};
  modal('Tuning the database server for its machine', function (body) {
    body.appendChild(el('p', 'note', 'Reading what the machine has and what the server is '
      + 'set to, and timing a few small writes…'));
  }, [{words: 'Close', close: true}], 'tune');
  /* The administrator, if one was typed, goes with the popup. */
  MODAL_CLOSE = tuneForget;
  tuneLook();
}

/* Asked again with what is in the boxes: the machine as typed, and the
   administrator, which may read a server on another machine itself. */
function tuneAsked() {
  var out = {};
  if (!TUNE) return out;
  if (TUNE.boxes) {
    TUNE.user = TUNE.boxes.who.value.trim();
    TUNE.pass = TUNE.boxes.word.value;
  }
  if (TUNE.hw) {
    TUNE.ram = TUNE.hw.ram.value.replace(',', '.').trim();
    TUNE.cpus = TUNE.hw.cpus.value.trim();
    TUNE.disk = TUNE.hw.disk.value;
  }
  if (TUNE.user) { out.admin_user = TUNE.user; out.admin_password = TUNE.pass; }
  if (TUNE.ram) out.ram_gb = TUNE.ram;
  if (TUNE.cpus) out.cpus = TUNE.cpus;
  if (TUNE.disk) out.disk = TUNE.disk;
  if (TUNE.sure && TUNE.sure.checked) out.confirmed = true;
  return out;
}

function tuneLook(button) {
  var ask = tuneAsked();
  ask.act = 'plan';
  var ticket = modalTicket();
  if (button) busy(button, true);
  api('db-tune', ask).then(function (d) {
    if (!modalStill(ticket)) return;
    TUNE.plan = d;
    tuneDraw(d);
  }).catch(function (e) {
    if (!modalStill(ticket)) return;
    if (button) busy(button, false);
    if (!TUNE.plan) {
      var engine = ENGINE && ENGINE.live ? ENGINE.live.engine : '';
      modal('Tuning the database server for its machine', function (body) {
        body.appendChild(el('p', 'note bad', String(e && e.message || e)));
        TUNE.boxes = tuneAdminBoxes(body, engine, TUNE);
      }, [{words: 'Read again', icon: 'refresh', go: function (b) { tuneLook(b); }},
          {words: 'Close', close: true}], 'tune');
      return;
    }
    oops(e);
  });
}

function tuneDraw(d) {
  var changes = (d.items || []).filter(function (it) { return it.change; });
  var buttons = [
    {words: 'Read again', icon: 'refresh', left: true, go: function (b) { tuneLook(b); }},
    {words: 'Close', close: true}
  ];
  if (changes.length) {
    buttons.splice(1, 0, {words: 'Put it in', cls: 'primary', icon: 'gear', admin: true,
                          go: function (b) { tuneApply(b); }});
  }
  modal('Tuning ' + d.words + ' for its machine', function (body) {
    var f = d.facts || {};
    body.appendChild(peekFacts([
      /* "PostgreSQL 16.13 (Ubuntu 16.13-0ubuntu0.24.04.1)": the package
         in brackets is not what anybody tunes for. */
      ['Server', String(d.version || d.words).replace(/\s*\(.*\)\s*$/, '')],
      ['Where', d.where],
      ['Database', bytes(d.size)],
      f.ram ? ['Memory', bytes(f.ram)] : null,
      f.avail ? ['Free now', bytes(f.avail)] : null,
      f.cpus ? ['Processors', num(f.cpus)] : null,
      ['Disk', f.disk === 'hdd' ? 'a disk that spins' : 'SSD'],
      f.commit_ms !== null && f.commit_ms !== undefined
        ? ['A write made safe in', Number(f.commit_ms).toFixed(1).replace('.', numDecimal())
           + ' ms'] : null,
      d.connections ? ['Connections allowed', num(d.connections)] : null
    ]));
    var from = {'this machine': 'Read from this machine, which the server runs on.',
                'the server, as its administrator': 'Read from the server itself, as its '
                  + 'administrator.',
                'typed': 'As typed below.'}[f.source || ''];
    if (from) body.appendChild(el('p', 'note', from));
    if (f.why && f.why !== 'chosen') {
      var dw = el('p', 'note');
      dw.appendChild(document.createTextNode('The disk:'));
      dw.appendChild(document.createTextNode(' '));
      dw.appendChild(document.createTextNode(f.why));
      body.appendChild(dw);
    }
    if (d.need_facts) {
      body.appendChild(el('p', 'note bad', 'The server is on another machine and what it has '
        + 'could not be read from here. Type its memory and processors below and press Read '
        + 'again.'));
      if (d.engine === 'postgres') {
        body.appendChild(el('p', 'note', 'Or give an administrator of PostgreSQL below: it may '
          + 'read them off the server itself.'));
      }
    }
    if ((d.others || []).length) {
      var o = el('p', 'note bad');
      o.appendChild(document.createTextNode('These are the server’s settings, not this '
        + 'database’s: they are for every database on it. On this one there are also:'));
      d.others.forEach(function (n, i) {
        o.appendChild(document.createTextNode(i ? ', ' : ' '));
        o.appendChild(el('span', 'mono', n));
      });
      body.appendChild(o);
    }

    /* The machine, as it will be worked out for - to be put right where
       it was read wrong, or typed where it could not be read at all. */
    var row = el('div', 'tune-machine');
    var hw = {};
    [['ram', 'Memory, GB', f.ram ? String(Math.round(f.ram / 1073741824 * 10) / 10) : ''],
     ['cpus', 'Processors', f.cpus ? String(f.cpus) : '']].forEach(function (one) {
      var box = el('div', 'set-item');
      box.appendChild(el('label', '', one[1]));
      var input = el('input');
      input.type = 'text';
      input.inputMode = 'decimal';
      input.value = TUNE[one[0]] || one[2];
      box.appendChild(input);
      row.appendChild(box);
      hw[one[0]] = input;
    });
    var dbox = el('div', 'set-item');
    dbox.appendChild(el('label', '', 'Disk'));
    var sel = el('select');
    [['ssd', 'SSD'], ['hdd', 'a disk that spins']].forEach(function (o) {
      var opt = el('option', '', o[1]);
      opt.value = o[0];
      sel.appendChild(opt);
    });
    sel.value = TUNE.disk || f.disk || 'ssd';
    dbox.appendChild(sel);
    row.appendChild(dbox);
    hw.disk = sel;
    body.appendChild(row);
    TUNE.hw = hw;
    body.appendChild(el('p', 'btnhelp', 'Change any of these and press Read again: the '
      + 'settings are worked out afresh for what is typed.'));

    if ((d.items || []).length) {
      body.appendChild(el('h4', '', changes.length
        ? 'What would change' : 'Nothing to change: every setting is right for this machine'));
      var table = el('table', 'plain tune-table');
      var head = el('tr');
      ['Setting', 'Now', 'For this machine', 'Takes', 'Why'].forEach(function (h) {
        head.appendChild(el('th', '', h));
      });
      var thead = el('thead');
      thead.appendChild(head);
      table.appendChild(thead);
      var tbody = el('tbody');
      var rest = el('tbody');
      (d.items || []).forEach(function (it) {
        var tr = el('tr', it.change ? 'tune-change' : 'tune-same');
        tr.appendChild(el('td', 'mono', it.name));
        tr.appendChild(el('td', '', tuneValue(it.kind, it.now)));
        tr.appendChild(el('td', it.change ? 'tune-want' : '', it.change || it.waiting
          ? tuneValue(it.kind, it.want) : 'right as it is'));
        var when = it.waiting ? 'put in: waits for the server’s next start'
          : it.other ? 'another value waits for the server’s next start'
          : (!it.change ? '' : (it.restart
            ? (d.engine === 'mariadb' ? 'at the server’s next start, from the file'
                                      : 'at the server’s next start')
            : 'at once'));
        tr.appendChild(el('td', it.restart && it.change ? 'tune-restart' : '', when));
        tr.appendChild(el('td', 'tune-why', it.why || ''));
        (it.change || it.waiting ? tbody : rest).appendChild(tr);
      });
      table.appendChild(tbody);
      if (rest.childNodes.length) {
        rest.hidden = !!changes.length;
        table.appendChild(rest);
      }
      body.appendChild(table);
      if (rest.childNodes.length && changes.length) {
        var more = el('button', 'btn small', 'Show the ' + rest.childNodes.length
          + ' that are right already');
        more.type = 'button';
        more.onclick = function () { rest.hidden = false; more.remove(); };
        body.appendChild(more);
      }
    }

    TUNE.sure = null;
    if (d.typed && changes.length) {
      /* Nothing of that machine was read: what is put in is only as right
         as what was typed, and a server given more memory than it has may
         not start again. */
      var sure = el('label', 'set-check');
      var tick = el('input');
      tick.type = 'checkbox';
      sure.appendChild(tick);
      sure.appendChild(document.createTextNode(' '));
      sure.appendChild(document.createTextNode('The memory and processors above are that '
        + 'server\u2019s - checked on it, not guessed.'));
      body.appendChild(el('p', 'note bad', 'Nothing of that machine could be read from here, '
        + 'so the settings are worked out from what is typed above.'));
      body.appendChild(sure);
      TUNE.sure = tick;
    }
    if (d.need_facts && d.engine === 'postgres' && !d.may_own) {
      body.appendChild(el('h4', '', 'An administrator, to read the machine'));
      TUNE.boxes = tuneAdminBoxes(body, d.engine, TUNE);
    }
    if (changes.length) {
      body.appendChild(el('h4', '', 'Who puts it in'));
      if (d.may_own) {
        body.appendChild(el('p', 'note good', 'This program’s own account may change the '
          + 'server’s settings: no administrator is needed.'));
        TUNE.boxes = null;
      } else {
        if (TUNE.user && !d.may) {
          body.appendChild(el('p', 'note bad', 'That account may not change the server’s '
            + 'settings.'));
        }
        body.appendChild(el('p', 'note', d.engine === 'postgres'
          ? 'This program’s account may not change the server’s settings, so an '
            + 'administrator on it is needed: postgres, or any account that is a superuser.'
          : 'This program’s account may not change the server’s settings, so an '
            + 'administrator on it is needed: root, or any account with SUPER.'));
        TUNE.boxes = tuneAdminBoxes(body, d.engine, TUNE);
        if (d.engine === 'postgres' && f.source === 'this machine') {
          /* (1.10.201) Once, on the server, and the administrator is not
             asked for again: the installer gives this program's account the
             right to these settings alone. */
          body.appendChild(el('p', 'btnhelp', 'Or, once, on this machine as root, from the '
            + 'unpacked folder - this program\u2019s account may then change these settings, and '
            + 'only these, and no administrator is asked for again (PostgreSQL 15 and newer):'));
          body.appendChild(guideCode('sudo ./install.sh --db-rights'));
        }
        if (d.engine === 'postgres') {
          body.appendChild(el('p', 'btnhelp', 'A PostgreSQL installed as it comes lets postgres '
            + 'in only on the machine itself, without a password. Give it one first, on the '
            + 'server:'));
          body.appendChild(guideCode('sudo -u postgres psql -c "\\password postgres"'));
        }
      }
      var notes = [];
      if (changes.some(function (it) { return it.restart; })) {
        notes.push(d.engine === 'postgres'
          ? 'Some take effect only when PostgreSQL is next started.'
          : 'Some take effect only when MariaDB is next started, from a file the next step gives.');
      }
      if (d.engine === 'mariadb') {
        notes.push('MariaDB keeps what is put in only until it is next started; the next step '
          + 'gives the file that keeps it for good.');
      }
      notes.push('What is there now is kept, and Put back as it was goes back to it.');
      notes.forEach(function (n) { body.appendChild(el('p', 'btnhelp', n)); });
    }
  }, buttons, 'tune');
}

function tuneApply(button) {
  var ask = tuneAsked();
  ask.act = 'apply';
  var ticket = modalTicket();
  busy(button, true);
  api('db-tune', ask).then(function (d) {
    loadTune();
    if (!modalStill(ticket)) return;
    tuneResult('The settings, put in', d, TUNE.plan ? TUNE.plan.engine : '');
  }).catch(function (e) {
    busy(button, false);
    oops(e);
  });
}

/* What was done, and what is left for a restart or for the server's own
   file. */
function tuneResult(title, d, engine, back) {
  var buttons = [{words: 'Close', close: true}];
  var pending = d.pending || [];
  if (pending.length && d.restart && d.restart.may) {
    buttons.unshift({words: 'Restart PostgreSQL now', cls: 'primary', icon: 'power',
                     go: function (b) { tuneRestart(b); }});
  }
  modal(title, function (body) {
    (d.done || []).forEach(function (n) {
      var p = el('p', 'note good');
      p.appendChild(document.createTextNode(back ? 'put back:' : 'put in:'));
      p.appendChild(document.createTextNode(' '));
      p.appendChild(el('span', 'mono', n + ((d.set || {})[n] ? ' = ' + d.set[n] : '')));
      body.appendChild(p);
    });
    (d.failed || []).forEach(function (f) {
      var p = el('p', 'note bad');
      p.appendChild(el('span', 'mono', f.name));
      p.appendChild(document.createTextNode(': '));
      p.appendChild(document.createTextNode(f.why));
      body.appendChild(p);
    });
    if (!(d.done || []).length && !(d.failed || []).length && !(d.at_start || []).length) {
      body.appendChild(el('p', 'note', 'Nothing needed changing.'));
    }
    if (pending.length) {
      var w = el('p', 'note bad');
      w.appendChild(document.createTextNode('Waiting for the server’s next start:'));
      pending.forEach(function (n, i) {
        w.appendChild(document.createTextNode(i ? ', ' : ' '));
        w.appendChild(el('span', 'mono', n));
      });
      body.appendChild(w);
      if (d.restart && d.restart.may) {
        body.appendChild(el('p', 'note', 'Restarting takes a few seconds. While PostgreSQL is '
          + 'down this program cannot write; it waits, and carries on where it was.'));
      } else {
        body.appendChild(el('p', 'note', 'Restart it when it suits, on the server, as root:'));
        body.appendChild(guideCode('systemctl restart '
          + ((d.restart && d.restart.unit) || 'postgresql')));
        if (d.restart && d.restart.unit) {
          body.appendChild(el('p', 'btnhelp', 'Or let this page do it from now on - once, on '
            + 'this machine as root, from the unpacked folder:'));
          body.appendChild(guideCode('sudo ./install.sh --db-rights'));
        } else {
          body.appendChild(el('p', 'btnhelp', 'The service may be named after its version '
            + 'there, postgresql-16 for one.'));
        }
      }
    }
    if ((d.at_start || []).length) {
      var s = el('p', 'note bad');
      s.appendChild(document.createTextNode('Only at the server’s next start, from the file '
        + 'below:'));
      d.at_start.forEach(function (n, i) {
        s.appendChild(document.createTextNode(i ? ', ' : ' '));
        s.appendChild(el('span', 'mono', n));
      });
      body.appendChild(s);
    }
    if ((d.left || []).length) {
      var kept = el('p', 'note');
      kept.appendChild(document.createTextNode('Changed since by somebody else, and left as '
        + 'it is:'));
      d.left.forEach(function (n, i) {
        kept.appendChild(document.createTextNode(i ? ', ' : ' '));
        kept.appendChild(el('span', 'mono', n));
      });
      body.appendChild(kept);
    }
    if (back && engine === 'mariadb') {
      body.appendChild(el('p', 'note', 'If the file from the popup was put on the server, take '
        + 'it away too, or MariaDB puts the settings back at its next start:'));
      body.appendChild(guideCode('rm /etc/my.cnf.d/zz-isemon-tuning.cnf'));
    }
    if (d.cnf && engine === 'mariadb') {
      body.appendChild(el('h4', '', 'To keep them for good'));
      body.appendChild(el('p', 'note', 'MariaDB keeps what was put in until it is next started. '
        + 'This file keeps it over a restart: on the server, as root (on Debian and Ubuntu the '
        + 'folder is /etc/mysql/mariadb.conf.d):'));
      body.appendChild(guideCode("cat > /etc/my.cnf.d/zz-isemon-tuning.cnf <<'EOF'\n" + d.cnf
        + "EOF\nsystemctl restart mariadb"));
    }
  }, buttons, 'tune');
}

function tuneRestart(button) {
  var ticket = modalTicket();
  busy(button, true);
  var body = $('modal-body');
  var was = body.querySelector('.tune-restarting');
  if (was) was.remove();
  body.appendChild(el('p', 'note tune-restarting', 'Restarting…'));
  api('db-tune', {act: 'restart'}).then(function (d) {
    loadTune();
    if (!modalStill(ticket)) return;
    modal(d.slow ? 'PostgreSQL, restarting' : 'PostgreSQL, restarted', function (b) {
      if (d.slow) {
        b.appendChild(el('p', 'note bad', 'It has not answered yet. This program goes on '
          + 'trying by itself; the card says when it is back.'));
        b.appendChild(el('p', 'note', d.recovery || ''));
        return;
      }
      var p = el('p', 'note good');
      p.appendChild(document.createTextNode('Restarted'));
      p.appendChild(document.createTextNode(' (' + d.unit + ', '
        + String(d.took).replace('.', numDecimal()) + ' s).'));
      b.appendChild(p);
      if ((d.pending || []).length) {
        b.appendChild(el('p', 'note bad', 'Still waiting: ' + d.pending.join(', ')));
      } else {
        b.appendChild(el('p', 'note good', 'Every setting is in.'));
      }
    }, [{words: 'Close', close: true}], 'narrow');
  }).catch(function (e) {
    busy(button, false);
    loadTune();
    if (!modalStill(ticket)) { oops(e); return; }
    var body = $('modal-body');
    body.appendChild(el('p', 'note bad', String(e && e.message || e)));
  });
}

function openTuneUndo() {
  var engine = ENGINE && ENGINE.live ? ENGINE.live.engine : '';
  var boxes = null;
  modal('Put the server’s settings back', function (body) {
    body.appendChild(el('p', 'note', 'Everything this page put in goes back to what was there '
      + 'before the first time it was used. A setting somebody has changed since is left as '
      + 'it is.'));
    body.appendChild(el('p', 'note', 'An administrator on that server is needed unless this '
      + 'program’s own account may change the server’s settings - then leave the two '
      + 'boxes empty.'));
    boxes = tuneAdminBoxes(body, engine, null);
  }, [{words: 'Put back as it was', cls: 'primary', icon: 'undo', go: function (b) {
    var ask = {act: 'undo'};
    if (boxes.who.value.trim()) {
      ask.admin_user = boxes.who.value.trim();
      ask.admin_password = boxes.word.value;
    }
    var ticket = modalTicket();
    busy(b, true);
    api('db-tune', ask).then(function (d) {
      loadTune();
      if (!modalStill(ticket)) return;
      tuneResult('The settings, put back', d, engine, true);
    }).catch(function (e) {
      busy(b, false);
      oops(e);
    });
  }}, {words: 'Close', close: true}], 'narrow');
  MODAL_CLOSE = tuneForget;
}

$('db-tune').onclick = openTune;
$('db-tune-undo').onclick = openTuneUndo;
$('db-tune-restart').onclick = function () {
  modal('Restart PostgreSQL', function (body) {
    body.appendChild(el('p', 'note', 'For the settings that take effect only at its start. '
      + 'Restarting takes a few seconds. While PostgreSQL is down this program cannot write; '
      + 'it waits, and carries on where it was.'));
  }, [{words: 'Restart PostgreSQL now', cls: 'primary', icon: 'power',
       go: function (b) { tuneRestart(b); }}, {words: 'Close', close: true}], 'narrow');
};

$('db-optimize').onclick = function () {
  busy($('db-optimize'), true);
  api('db-optimize', {}).then(function (d) {
    /* Saying "tidied" over a number that went up reads as a lie. A database
       being written to while it is rebuilt can come out the same size or
       larger, and that is worth saying rather than dressing up. */
    var saved = d.before - d.after;
    toast(saved > 0
      ? 'tidied: ' + bytes(d.before) + ' \u2192 ' + bytes(d.after)
        + ', ' + bytes(saved) + ' given back'
      : 'rebuilt: ' + bytes(d.before) + ' \u2192 ' + bytes(d.after)
        + ' \u2014 nothing to give back, it is in use while this runs',
      saved > 0 ? 'good' : '');
    loadDb();
  }).catch(oops).then(function () { busy($('db-optimize'), false); });
};
$('db-prune').onclick = function () {
  modal('Forget records older than…', function (body) {
    var p = el('p', 'note');
    p.innerHTML = 'Recorded authentications only — the refused attempts and the sign-ins — '
      + 'at an age chosen here, <b>whatever the "keep for" numbers say</b>. That is the '
      + 'difference between this and <b>Apply what is kept, now</b>, which throws away '
      + 'exactly what those numbers already say is too old.<br><br>'
      + 'Who is banned, the story of every ban, the domain events and the settings are '
      + '<b>not</b> touched — but the failed attempts that earned a ban are what its reason '
      + 'points at, so forgetting them leaves the reason without its evidence.';
    body.appendChild(p);
    body.appendChild(el('label', 'small muted', 'Forget anything older than'));
    var pick = el('select');
    pick.id = 'prune-days';
    [['7', 'a week'], ['30', 'a month'], ['90', 'three months'], ['365', 'a year']]
      .forEach(function (one) {
        var o = document.createElement('option');
        o.value = one[0];
        o.textContent = one[1];
        pick.appendChild(o);
      });
    pick.value = '90';
    pick.style.width = '100%';
    pick.style.margin = '4px 0 4px';
    body.appendChild(pick);
  }, [
    {words: 'Cancel', close: true},
    {words: 'Forget them', cls: 'danger', close: true, go: function () {
      api('db-prune', {days: Number($('prune-days').value)}).then(function (d) {
        toast(num(d.removed) + ' row(s) forgotten', 'good');
        loadDb();
        tick();
      }).catch(oops);
    }}
  ], true);
};

/* ==========================================================================
   Carrying the configuration elsewhere
   ========================================================================== */
$('cfg-export-all').onclick = function () {
  confirmThen('Download it with the passwords and keys?',
    'The file will hold the router password, the directory\u2019s service password, the '
    + 'private half of the ssh key this uses to reach the router, the domain\u2019s '
    + 'certificate, the key in the published ban list\u2019s URL and every account\u2019s '
    + 'password as it is kept here.<br><br>'
    + 'That is exactly what makes it enough to stand another machine up with nothing typed '
    + 'in by hand — and exactly what makes it a file that gets somebody into your firewall. '
    + 'Keep it where you keep passwords, and not in a ticket.',
    'Download it', function () { window.location.href = '?api=export&secrets=1'; });
};

$('cfg-export').onclick = function () { window.location = '?api=export'; };
$('cfg-import').onclick = function () {
  modal('Load a configuration', function (body) {
    var p = el('p', 'note');
    p.innerHTML = 'Paste a file made by either of the download buttons, or choose it below. '
      + 'The settings in it are checked one by one exactly as if they had been typed here, '
      + 'and a single bad value stops the whole thing rather than leaving half of it '
      + 'applied. Afterwards you are told what the file carried, and what it could not.';
    body.appendChild(p);
    var pick = el('div', 'drop', 'Drop the file here, or press to choose one');
    var file = document.createElement('input');
    file.type = 'file';
    file.accept = '.json,application/json';
    file.hidden = true;
    var read = function (f) {
      if (!f) return;
      var reader = new FileReader();
      reader.onload = function () {
        $('imp-text').value = String(reader.result || '');
        pick.textContent = f.name + ' \u2014 read, press Load it';
      };
      reader.readAsText(f);
    };
    pick.onclick = function () { file.click(); };
    file.onchange = function () { read(this.files && this.files[0]); };
    ['dragenter', 'dragover'].forEach(function (name) {
      pick.addEventListener(name, function (e) { e.preventDefault(); pick.classList.add('over'); });
    });
    ['dragleave', 'drop'].forEach(function (name) {
      pick.addEventListener(name, function (e) {
        e.preventDefault();
        pick.classList.remove('over');
        if (name === 'drop' && e.dataTransfer) read(e.dataTransfer.files[0]);
      });
    });
    explain(pick, 'Choose the JSON file rather than opening it and pasting it. Nothing is sent '
      + 'until you press Load it.');
    body.appendChild(pick);
    body.appendChild(file);
    var area = el('textarea');
    area.rows = 9;
    area.id = 'imp-text';
    area.style.marginTop = '10px';
    area.placeholder = '{ "_what": "isemon configuration", … }';
    explain(area, 'The file itself, if you would rather paste it than choose it.');
    body.appendChild(area);
    var label = el('label', 'check');
    label.style.marginTop = '12px';
    var box = document.createElement('input');
    box.type = 'checkbox';
    box.id = 'imp-blocked';
    box.checked = true;
    label.appendChild(box);
    label.appendChild(document.createTextNode('also put back who was banned'));
    explain(box, 'On, the addresses that were banned on the machine the file came from are '
      + 'banned here too, and the router is written. Off, only the settings, the accounts and '
      + 'the never-banned list come across, and this machine starts with nobody banned.');
    body.appendChild(label);
    var people = el('label', 'check');
    var box2 = document.createElement('input');
    box2.type = 'checkbox';
    box2.id = 'imp-users';
    box2.checked = true;
    people.appendChild(box2);
    people.appendChild(document.createTextNode('also put back the accounts'));
    explain(box2, 'On, the accounts in the file are made here, with whatever they may do. If '
      + 'the file was downloaded with the passwords in it they can sign in straight away; if '
      + 'it was not, they exist with no password and somebody has to set one. Off, the '
      + 'accounts already on this machine are the only ones there are.');
    body.appendChild(people);
  }, [
    {words: 'Cancel', close: true},
    {words: 'Load it', cls: 'primary', go: function () {
      var parsed;
      try { parsed = JSON.parse($('imp-text').value); }
      catch (e) { toast('that is not JSON', 'bad'); return; }
      api('import', {config: parsed, blocked: $('imp-blocked').checked,
                     users: $('imp-users').checked}).then(function (d) {
        closeModal();
        loadSettings();
        tick();
        saidWhatCameAcross(d);
      }).catch(oops);
    }}
  ]);
};

/** What the file carried, and what it could not.

    The second half is the half that matters. A plain export cannot hold a
    password, an ssh key or a certificate, and a machine built from one comes
    up unable to reach the router and unable to ask the domain anything -
    with nothing on the screen to say why unless it is said here. */
function saidWhatCameAcross(d) {
  toast(d.message, 'good');
  if (!d.missing || !d.missing.length) {
    modal('The configuration is in', function (body) {
      var p = el('p');
      p.innerHTML = 'It carried everything: <b>' + (d.done || []).map(richText).join('</b>, <b>')
        + '</b>. Nothing has to be typed in.';
      body.appendChild(p);
    }, [{words: 'Good', close: true}], true);
    return;
  }
  var says = {
    'mikrotik_password': 'the router password — Settings, the router',
    'mikrotik2_password': 'the second router’s password — Settings, the router',
    'directory_password': 'the directory’s service password — Settings, Active Directory',
    'the accounts’ passwords': 'a password for each account — Settings, who may open this',
    'whitelist': 'what is never banned — Settings, never banned',
    'the router key and the directory certificate':
      'the ssh key for the router and the domain’s certificate — Settings, the router and '
      + 'Active Directory'
  };
  modal('The configuration is in, and this is what it could not bring', function (body) {
    var p = el('p');
    p.innerHTML = 'It carried <b>' + (d.done || []).map(richText).join('</b>, <b>') + '</b>.';
    body.appendChild(p);
    var lede = el('p', 'note');
    lede.innerHTML = d.complete
      ? 'The file said it was a complete one, but these were not in it:'
      : 'This was a <b>plain</b> export, which cannot hold a password, a key or a '
        + 'certificate. Until these are set, this machine cannot do the part of its job that '
        + 'needs them:';
    body.appendChild(lede);
    var list = el('ul');
    list.style.margin = '6px 0 0 18px';
    d.missing.forEach(function (one) {
      var line = el('li');
      line.innerHTML = richText(says[one] || one);
      line.style.margin = '4px 0';
      list.appendChild(line);
    });
    body.appendChild(list);
    var tail = el('p', 'btnhelp');
    tail.innerHTML = 'A complete export — <i>Download it with the passwords and keys</i> — '
      + 'carries all of them, and so does a copy of the database.';
    body.appendChild(tail);
  }, [{words: 'I will set them', close: true}]);
}

function drawAbout() {
  var host = $('about');
  clear(host);
  var s = STATUS || {};
  /* As otp's About (1.10.234): the version as the card's heading, and what
     it is doing as tiles side by side. */
  var h = noI18n(el('h2', '', 'isemon ' + (s.version || '?')));
  h.title = 'Version';
  host.appendChild(h);
  host.appendChild(peekFacts([
    ['Running on', s.host || '–'],
    ['Up for', span(s.uptime)],
    ['Reading', (s.logs || []).length + ' log file(s) every '
      + ((SETTINGS && (settingByKey('read_every_s') || {}).value) || '?') + ' s'],
    ['Last read', (s.read_at ? ago(s.read_at) : 'not yet')
      + (s.read_ms ? ' · took ' + s.read_ms + ' ms' : '')],
    ['Newest record', s.last_record ? stamp(s.last_record) : 'none yet'],
    ['Signed in as', (ME && ME.name) + ' · '
      + roleWords(ME && ME.role)
      + (ME && ME.from_dir ? ' · out of the directory, where the password and the groups '
         + 'that decide this live' : '')]
  ]));
  drawSoftware(host);
  drawConsoleLogin();
  var cli = el('p', 'btnhelp');
  cli.innerHTML = 'The same from the server: <span class="mono">isemon --status</span> · '
    + '<span class="mono">isemon --blocked</span> · '
    + '<span class="mono">isemon --failed</span> · '
    + '<span class="mono">isemon --check</span> · '
    + '<span class="mono">isemon --help</span>';
  host.appendChild(cli);
}

/* The console when root signs in (1.10.230): the switch `isemon
   --console-at-login on|off` is, put in by root. */
function drawConsoleLogin() {
  var host = $('about-console');
  if (!host) return;
  api('console-login', undefined, {quiet: true}).then(function (d) {
    clear(host);
    if (typeof extraDone === 'function') extraDone('console');
    /* Changed here, put in by the save bar as every setting is (1.10.234) -
       not the moment the switch is pressed. */
    var row = null;
    var sw = wrSwitch(d.on, function (on) {
      if (row) row.classList.toggle('changed', on !== !!d.on);
      if (on === !!d.on) { extraDone('console'); return; }
      extraPending('console', {
        save: function () {
          return api('console-login', {on: on}).then(function (x) {
            toast(x.message, 'good');
            (x.said || []).slice(1).forEach(function (w) { toast(w, 'warn'); });
            extraDone('console');
            drawConsoleLogin();
            return true;
          }).catch(function (e) { oops(e); return false; });
        },
        reset: function () { drawConsoleLogin(); }
      });
    }, !d.may || !d.helper);
    /* The switch at the left of its words, as otp's (1.10.234). */
    row = el('div', 'con-row');
    row.appendChild(sw);
    row.appendChild(el('b', '', 'Open the console when root signs in'));
    row.appendChild(el('span', 'muted small', d.on ? 'on' : 'off'));
    host.appendChild(row);
    host.appendChild(el('p', 'muted small con-says',
      'At the server\u2019s own screen or over SSH. The same as isemon --console-at-login on|off.'));
    if (!d.helper) host.appendChild(el('p', 'note warn', 'Root’s half of this is not installed on this machine yet (isemon-web.path): run ./install.sh --upgrade once.'));
    else if (!d.profile) host.appendChild(el('p', 'note warn', 'The login script (/etc/profile.d/zz-isemon-console.sh) is not there yet: ./install.sh --upgrade puts it in. Until then the switch changes nothing.'));
    if (!d.may) host.appendChild(el('p', 'note', 'Only a full administrator may switch it.'));
    explainWhatWasDrawn(host);
  }).catch(function (e) { clear(host); host.appendChild(el('p', 'note bad', String(e.message || e))); });
}

/* What this server runs on (1.10.229), as otp's About draws it: isemon,
   Python and its modules, the libraries under them, the database, the page's
   PHP and its extensions, nginx and the rest beside it. */
var SOFTWARE = null;
function drawSoftware(host) {
  var box = el('div', 'sw-box');
  host.appendChild(box);
  box.appendChild(el('h3', 'sw-h', 'What it runs on'));
  var fill = function (d) {
    clear(box);
    box.appendChild(el('h3', 'sw-h', 'What it runs on'));
    var x = d.software || {};
    var pages = d.pages || {};
    var prog = function (k) { return (x.programs || {})[k] || ''; };
    var mod = function (k) { return (x.modules || {})[k] || ''; };
    var rows = [
      ['isemon', x.isemon],
      {group: 'Python'},
      ['Python', x.python],
      ['where', x.python_path],
      ['psycopg2 (PostgreSQL)', mod('psycopg2')],
      ['PyMySQL (MariaDB)', mod('pymysql')],
      ['colorama', mod('colorama')],
      ['OpenSSL (Python’s)', x.openssl],
      ['SQLite (library)', x.sqlite],
      {group: 'The database'},
      ['server', x.database],
      ['pg_dump', prog('pg_dump')],
      ['mariadb-dump', prog('mariadb-dump')],
      {group: 'The pages'},
      ['nginx', prog('nginx')],
      ['php-fpm', prog('php-fpm')],
      ['PHP (command line)', x.php_cli],
      {group: 'The system'},
      ['system', x.os],
      ['kernel', (x.kernel || '') + (x.arch ? ' · ' + x.arch : '')],
      ['systemd', prog('systemd')],
      ['OpenSSL (system)', prog('openssl')],
      ['rsyslog', prog('rsyslog')],
      ['chrony', prog('chrony')],
      ['NetworkManager', prog('NetworkManager')],
      ['iptables', prog('iptables')],
      ['firewalld', prog('firewalld')],
      ['OpenSSH', prog('OpenSSH')],
      ['smbclient', prog('smbclient')]
    ];
    var t = el('table', 'rows sw-table');
    var tb = el('tbody');
    var pend = null;
    rows.forEach(function (r) {
      var tr = el('tr');
      if (r.group) {
        tr.className = 'sw-group';
        var g = el('td', '', r.group);
        g.colSpan = 2;
        tr.appendChild(g);
        pend = tr;                      /* drawn only when something is under it */
        return;
      }
      if (!r[1]) return;                /* not on this machine: not shown */
      if (pend) { tb.appendChild(pend); pend = null; }
      tr.appendChild(el('td', 'k', r[0]));
      tr.appendChild(noI18n(el('td', 'mono small', r[1])));
      tb.appendChild(tr);
    });
    t.appendChild(tb);
    box.appendChild(t);
    if (pages.php) {
      box.appendChild(el('h3', 'sw-h', 'The page’s PHP (as php-fpm runs it here)'));
      box.appendChild(peekFacts([['PHP', pages.php], ['How', pages.sapi], ['OPcache', pages.opcache ? 'on' : 'off'],
                                 ['Web server', pages.server || '–']]));
      var ex = el('div', 'sw-ext');
      Object.keys(pages.extensions || {}).forEach(function (k) {
        var v = pages.extensions[k];
        ex.appendChild(noI18n(el('span', 'tag', k + (v ? ' ' + v : ''))));
      });
      box.appendChild(el('div', 'muted small', 'Its extensions (' + num(Object.keys(pages.extensions || {}).length) + '):'));
      box.appendChild(ex);
    }
    explainWhatWasDrawn(box);
  };
  if (SOFTWARE) { fill(SOFTWARE); return; }
  var wait = el('p', 'muted small', 'asking…');
  box.appendChild(wait);
  api('software').then(function (d) { SOFTWARE = d; fill(d); })
    .catch(function (e) { wait.textContent = String(e.message || e); });
}

/* ==========================================================================
   Icons, everywhere
   --------------------------------------------------------------------------
   Every button on the page carries one. They are put on here, from the
   data-icon written beside each button in the markup, rather than as inline
   SVG in the HTML: the markup stays readable, and a button that gains an icon
   later gains it by having one word added to it.
   ========================================================================== */
function dressButtons(where) {
  Array.prototype.forEach.call((where || document).querySelectorAll('button[data-icon]'),
    function (b) {
      if (b.dataset.dressed) return;
      b.dataset.dressed = '1';
      /* A tab carries a count chip that is filled in later. Putting the icon
         on rewrites the button's innards, so the chip is lifted out first and
         put back afterwards - otherwise the counter vanishes on load and
         never comes back, which looks exactly like the daemon not counting. */
      var chip = b.querySelector('.count, .n');
      setButtonIcon(b, b.dataset.icon, (b.textContent || '').trim());
      if (chip) b.appendChild(chip);
    });
  /* The ones in the header and the filter rows, which have no room for a word
     to spare and would look bare beside the rest. */
  var also = {
    'me-btn': 'person', 'signout': 'out',
    'look-go': 'search', 'ban-add': 'ban', 'ban-fold': 'fold', 'ban-clear': 'undo',
    'past-clear': 'close', 'f-clear': 'close', 'p-clear': 'close',
    /* Every Clear on the page looks the same, wherever its list is. */
    't-clear': 'close', 'w-clear': 'close',
    'router-read': 'refresh', 'router-sync': 'router', 'router-purge': 'broom',
    'router-ios': 'download',
    'log-read': 'log', 'white-add': 'shield', 'user-add': 'add', 'sessions-show': 'eye',
    'db-backup': 'save', 'db-check': 'check', 'db-optimize': 'broom', 'db-prune': 'forget',
    'cfg-export': 'download', 'cfg-import': 'upload', 'set-save': 'save', 'set-reset': 'undo',
    'feeds-fetch': 'download', 'geo-fetch': 'download', 'geolist-sync': 'globe',
    'geolist-purge': 'broom', 'fold-open': 'fold',
    'mt-test': 'pulse', 'mt-keygen': 'key', 'mt-paste': 'upload', 'mt-download': 'download',
    'mt-forget': 'forget', 'mt-sync': 'router', 'mt-purge': 'broom'
  };
  if (where) return;                      /* only the page's own, once */
  Object.keys(also).forEach(function (id) {
    var b = $(id);
    if (!b || b.dataset.dressed) return;
    b.dataset.dressed = '1';
    b.classList.add('cmd');
    setButtonIcon(b, also[id]);
  });
}
dressButtons();

