};
Object.keys(SAYS_BUTTON).forEach(function (id) {
  var node = $(id);
  if (node) explain(node, SAYS_BUTTON[id]);
});

/* ==========================================================================
   Find anything
   --------------------------------------------------------------------------
   One box for the question this dashboard is asked more than any other: is
   this address banned, what has it been doing, and take it off. Seven pages
   and three hundred addresses is no way to answer that, so the box answers
   it where it is asked - the address, its state, what it tried, and the two
   buttons, without going anywhere first.

   Everything else it finds is navigation: a page, a card, a settings pane, a
   setting by its own name. Ctrl+K from anywhere, Escape to leave.
   ========================================================================== */
var FIND = {at: 0, rows: [], seq: 0, q: ''};

/** Every page, card and setting, as things that can be gone to. Worked out
    from the page itself, so it can never fall behind what is on it. */
function findPlaces() {
  var out = [];
  /* Only what can be reached: a tab switched off (the domain's, with no
     controllers read) opened, and the next poll took it away again. */
  Array.prototype.forEach.call(document.querySelectorAll('.tabs button[data-tab]'),
    function (b) {
      if (b.hidden) return;
      out.push({icon: '\u25b8', text: b.innerText.trim().split('\n')[0], what: 'page',
                go: function () { showTab(b.dataset.tab); }});
    });
  Array.prototype.forEach.call(document.querySelectorAll('#ctl-nav button[data-pane]'),
    function (b) {
      if (b.hidden) return;
      out.push({icon: '\u2699', text: b.innerText.trim(), what: 'settings',
                go: function () { showTab('settings'); showPane(b.dataset.pane); }});
    });
  /* The pages of the Traffic tab, each a place of its own. */
  Array.prototype.forEach.call(document.querySelectorAll('#t-pages button[data-page]'),
    function (b) {
      if (b.hidden || b.dataset.page === 'over') return;
      out.push({icon: '\u25b8', text: 'Traffic \u2192 ' + b.innerText.trim().split('\n')[0],
                what: 'page', go: function () { showTab('traffic'); tShowPage(b.dataset.page); }});
    });
  Array.prototype.forEach.call(document.querySelectorAll('section.panel .card > h2'),
    function (h) {
      var panel = h.closest('section.panel');
      var pane = h.closest('.ctl-pane');
      if (!panel) return;
      var tab = panel.id.slice(4);
      var tabButton = document.querySelector('.tabs button[data-tab="' + tab + '"]');
      if (tabButton && tabButton.hidden) return;
      /* A card put away by anything but which page or pane is open - one
         for a read-only account seen by an administrator, a module that is
         off - is somewhere nobody can be taken. */
      var card = h.closest('.card');
      for (var n = card; n && n !== panel; n = n.parentElement) {
        if ((n.hidden || n.style.display === 'none') && !/^[tw]-page-/.test(n.id || '')
            && !n.classList.contains('ctl-pane')) return;
      }
      /* ...and a card on one of the Traffic or Domain pages opens that page. */
      var sub = h.closest('[id^="t-page-"],[id^="w-page-"]');
      out.push({icon: '\u25a2', text: (h.childNodes[0] || h).textContent.trim(),
                what: 'card', where: pane ? 'settings' : tab,
                go: function () {
                  showTab(tab);
                  if (pane) showPane(pane.id.slice(5));
                  if (sub && sub.id.charAt(0) === 't') {
                    var page = sub.id.slice(7);
                    tShowPage(page === 'list' ? (TPAGE && TPAGE !== 'over' && TPAGE !== 'vpn'
                                                 ? TPAGE : 'list') : page);
                  }
                  if (sub && sub.id.charAt(0) === 'w') winShowPage(sub.id.slice(7));
                  setTimeout(function () { flashAt(card); }, 120);
                }});
    });
  Array.prototype.forEach.call(document.querySelectorAll('.set-item[data-key]'),
    function (item) {
      var label = item.querySelector('label');
      var pane = item.closest('.ctl-pane');
      if (!label || !pane) return;
      out.push({icon: '\u2699', text: label.innerText.trim(), what: 'setting',
                more: item.dataset.key, where: 'settings',
                go: function () {
                  showTab('settings');
                  showPane(pane.id.slice(5));
                  setTimeout(function () { flashAt(item); }, 120);
                }});
    });
  return out;
}

/** What a door is called in a sentence. The same names the tabs use, so
    that "OTP" in the find box and "OTP" on the Logins page are the same
    thing to whoever is reading both. */
var DOOR_WORDS = {vpn: 'VPN', tacacs: 'TACACS', otp: 'OTP', eduroam: 'eduroam',
                  'dot1x-lan': '802.1X', 'dot1x-wifi': '802.1X Wi\u2011Fi',
                  'mab-lan': 'MAB', 'mab-wifi': 'MAB Wi\u2011Fi',
                  dacl: 'a firewall handed down', 'tacacs-cmd': 'a command',
                  tacplus: 'TAC_Plus', 'tacplus-cmd': 'a command, through tac_plus',
                  'nps-vpn': 'NPS VPN', 'nps-dot1x-lan': 'NPS 802.1X',
                  'nps-dot1x-wifi': 'NPS 802.1X Wi\u2011Fi', 'nps-mab-lan': 'NPS MAB',
                  'nps-mab-wifi': 'NPS MAB Wi\u2011Fi', 'nps-other': 'NPS',
                  'radius-vpn': 'FreeRADIUS VPN', 'radius-dot1x-lan': 'FreeRADIUS 802.1X',
                  'radius-dot1x-wifi': 'FreeRADIUS 802.1X Wi\u2011Fi',
                  'radius-mab-lan': 'FreeRADIUS MAB',
                  'radius-mab-wifi': 'FreeRADIUS MAB Wi\u2011Fi', 'radius-other': 'FreeRADIUS'};
function doorWords(kind) { return DOOR_WORDS[kind] || String(kind || 'somewhere'); }

/** Take somebody to a thing and let it glow, so the eye finds it on a page
    of forty others.

    A row of a table is lit differently from a card: `box-shadow` on a `tr`
    is drawn by browsers in ways that range from faint to not at all, and a
    mark nobody can see is the same as no mark. A row gets its background
    changed instead, which every browser draws. */
function flashAt(node) {
  if (!node) return;
  node.scrollIntoView({block: 'center', behavior: 'smooth'});
  var row = node.tagName === 'TR';
  var mark = row ? 'found-row' : 'found';
  node.classList.remove(mark);
  void node.offsetWidth;                 // so it runs again on the same row
  node.classList.add(mark);
  setTimeout(function () { node.classList.remove(mark); }, row ? 4000 : 2200);
}

/** Send somebody to the records behind one door, for one address or one
    name, and light the row they were sent to.

    The chips on an address say where it has been seen; this is what makes
    them worth pressing. The search box of the page being opened is filled
    with whatever that door can actually be searched by - which for the
    token log is the account, because a token row carries the token
    server's own address and not the person's, so the address would find
    nothing there. */
function goToRecords(where, door, q, session) {
  var passed = where === 'passed';
  closeFind();
  closeAllModals();
  showTab(passed ? 'logins' : 'failed');
  /* The window has to be wide enough to hold what somebody was sent to
     see, or they land on a page that says nothing matches about a record
     this page has just told them exists. */
  var hours = $(passed ? 'p-hours' : 'f-hours');
  if (hours && typeof windowSet === 'function') windowSet(hours.id, null);
  if (hours) hours.value = '0';
  var box = $(passed ? 'p-q' : 'f-q');
  if (box) box.value = q || '';
  var country = $(passed ? 'p-country' : 'f-country');
  if (country && country.value) { country.value = ''; if (country._ccpick) country._ccpick.paint(); }
  /* ...and the device and node filters, and the door's own drop-downs, for
     the same reason: a switch chosen a minute ago would hide the very row
     somebody was sent to. */
  ['device', 'server'].forEach(function (which) {
    var box = $((passed ? 'p-' : 'f-') + which);
    if (box && box.value) box.value = '';
  });
  clearPicks(passed ? 'p' : 'f');
  var drawn = passed ? passedTab(door) : showFailedKind(door);
  Promise.resolve(drawn).then(function () {
    var table = $(passed ? 'p-table' : 'f-table');
    var rows = table ? Array.prototype.slice.call(table.querySelectorAll('tbody tr')) : [];
    var want = session
      ? rows.filter(function (tr) { return tr.dataset.session === session; })[0] : null;
    flashAt(want || rows[0]);
  }).catch(function () { /* the list said why itself */ });
}

function findMatch(items, q) {
  var words = String(q || '').toLowerCase().split(/\s+/).filter(Boolean);
  if (!words.length) return [];
  var scored = [];
  items.forEach(function (it) {
    var name = String(it.text || '').toLowerCase();
    var hay = name + ' ' + String(it.more || '').toLowerCase() + ' '
      + String(it.what || '').toLowerCase() + ' ' + String(it.where || '').toLowerCase();
    if (!words.every(function (w) { return hay.indexOf(w) >= 0; })) return;
    var whole = words.join(' ');
    scored.push([name === whole ? 0 : (name.indexOf(whole) === 0 ? 1
                 : (name.indexOf(whole) >= 0 ? 2 : 3)), it]);
  });
  scored.sort(function (a, b) { return a[0] - b[0]; });
  return scored.map(function (x) { return x[1]; });
}

var FIND_FROM = null;
function openFind(seed) {
  var back = $('findback'), input = $('findinput');
  /* Where focus was, to give it back when this closes. (1.10.168) */
  if (back.hidden) FIND_FROM = document.activeElement;
  back.hidden = false;
  input.value = seed || $('findbox').value || '';
  FIND.at = 0;
  paintFind(true);
  setTimeout(function () { input.focus(); input.select(); }, 20);
}
function closeFind() {
  var was = !$('findback').hidden;
  $('findback').hidden = true;
  $('findbox').value = '';
  if (was && FIND_FROM && FIND_FROM.focus && document.contains(FIND_FROM)) {
    try { FIND_FROM.focus(); } catch (e) { /* gone meanwhile */ }
  }
  FIND_FROM = null;
}
/* Escape closes it wherever focus is inside it, and Tab goes round inside it
   rather than out to the page behind - the box alone had either. (1.10.168) */
$('findback').addEventListener('keydown', function (e) {
  if (e.key === 'Escape') {
    e.preventDefault();
    e.stopPropagation();
    closeFind();
    return;
  }
  if (e.key !== 'Tab') return;
  var all = Array.prototype.filter.call(
    $('findback').querySelectorAll('input, button, [tabindex]:not([tabindex="-1"]), a[href]'),
    function (x) { return !x.disabled && x.offsetParent !== null; });
  if (!all.length) return;
  var first = all[0], last = all[all.length - 1];
  if (e.shiftKey && document.activeElement === first) {
    e.preventDefault();
    last.focus();
  } else if (!e.shiftKey && document.activeElement === last) {
    e.preventDefault();
    first.focus();
  }
});

function findRow(it, i) {
  var row = el('div', 'finditem' + (i === FIND.at ? ' on' : ''));
  row.appendChild(el('span', 'ficon', it.icon || ''));
  var text = el('span', 'ftext');
  if (it.mono) {
    var m = el('span', 'mono');
    m.textContent = it.text;
    text.appendChild(m);
    if (it.tail) text.appendChild(el('span', 'muted small', '  ' + it.tail));
  } else {
    text.textContent = it.text;
  }
  row.appendChild(text);
  row.appendChild(el('span', 'fwhat', it.what + (it.where ? ' \u00b7 ' + it.where : '')));
  if (it.name) row.dataset.name = it.name;
  /* A name is asked about where it stands; everything else is a place, and
     pressing it goes there. */
  row.onclick = function () {
    findRemember(FIND.q, findPickOf(it));
    if (it.name) lookUpPerson(it.name); else { closeFind(); it.go(); }
  };
  FIND.rows.push(row);
  return row;
}

/** Where an address has been seen, as one pressable chip per door.

    The counts are what is pressed, not the door: "2 in" opens the sign-ins
    and "1 refused" opens the refusals, so there is never a question about
    which of the two a press meant. Each one fills that page's own search
    box, picks that door, widens the window to everything, and lights the
    row it sent somebody to. */
function doorChips(ip, doors) {
  var where = el('div', 'fdoors');
  doors.forEach(function (d) {
    var tag = el('span', 'fdoor');
    tag.appendChild(el('b', '', doorWords(d.kind)));
    var q = d.q || ip;
    var by = d.by === 'account'
      ? 'The token log has no address on its rows \u2014 it carries the token '
        + 'server\u2019s own, because that is who asks it. So this opens that log on '
        + '<b>' + q + '</b>, the account those attempts were made with.'
      : 'This opens that list on <b>' + q + '</b>, over all of time, and lights the row.';
    if (d.passed) {
      var went = el('a', 'fgo', num(d.passed) + ' in');
      explain(went, 'Open the ' + doorWords(d.kind) + ' sign-ins from here. ' + by);
      went.onclick = function (e) {
        e.preventDefault();
        goToRecords('passed', d.kind, q,
                    (LASTSEEN && LASTSEEN.kind === d.kind && LASTSEEN.ok)
                      ? LASTSEEN.session : '');
      };
      tag.appendChild(went);
    }
    if (d.passed && d.failed) tag.appendChild(el('span', 'muted', '\u00b7'));
    if (d.failed) {
      var fell = el('a', 'fgo', num(d.failed) + ' refused');
      explain(fell, 'Open the ' + doorWords(d.kind) + ' refusals from here. ' + by);
      fell.onclick = function (e) {
        e.preventDefault();
        goToRecords('failed', d.kind, q,
                    (LASTSEEN && LASTSEEN.kind === d.kind && !LASTSEEN.ok)
                      ? LASTSEEN.session : '');
      };
      tag.appendChild(fell);
    }
    where.appendChild(tag);
  });
  return where;
}

/* Which record the newest sighting was, so that pressing the door it was at
   lands on that row rather than merely on that list. */
var LASTSEEN = null;

/** One line: when this address was last seen, at which door, as whom, and
    whether it got in. Pressing it opens that record's own list and lights
    the row it is on. */
function lastSeenLine(last, quiet) {
  LASTSEEN = last;
  var seen = el('div', 'fsays');
  /* `quiet` where something above it already says "Last seen", which the
     popup's own label does. */
  if (!quiet) seen.appendChild(el('span', 'muted', 'Last seen '));
  var go = el('a', 'fgo');
  go.textContent = shortStamp(last.ts) + ' \u00b7 ' + doorWords(last.kind);
  explain(go, 'Open this one where it is recorded, and light the row.');
  go.onclick = function (e) {
    e.preventDefault();
    goToRecords(last.ok ? 'passed' : 'failed', last.kind, last.q || '', last.session || '');
  };
  seen.appendChild(go);
  seen.appendChild(el('span', 'muted', ' \u00b7 '));
  if (last.username) {
    seen.appendChild(el('span', 'mono', last.username));
    seen.appendChild(document.createTextNode(' '));
  }
  seen.appendChild(el('span', 'tag ' + (last.ok ? 'ok' : 'crit'),
                      last.ok ? 'let in' : 'refused'));
  return seen;
}

/** Whether what somebody typed is an address rather than a name. Rough on
    purpose: it only decides which of two questions to ask, and asking the
    wrong one of an address costs an answer that says nothing. */
function isAddress(said) {
  var text = String(said || '').trim();
  return /^[0-9]{1,3}(\.[0-9]{1,3}){3}(\/[0-9]{1,2})?$/.test(text)
    || (text.indexOf(':') >= 0 && /^[0-9a-f:.\/]+$/i.test(text));
}

/** Ask about one name and draw the answer in the find box, without closing
    it. Somebody who has just read the card wants to press something on it. */
function lookUpPerson(name) {
  var host = $('findlist');
  if (!host) return;
  FIND.q = '\u0000person:' + name;     // so a redraw does not undo this
  FIND.rows = [];
  clear(host);
  host.appendChild(el('div', 'center', 'Asking about \u201c' + name + '\u201d\u2026'));
  $('findsaid').textContent = '';
  api('person&name=' + encodeURIComponent(name)).then(function (d) {
    if (FIND.q !== '\u0000person:' + name) return;      // typed on
    clear(host);
    FIND.rows = [];
    noteBanned({banned: d.banned});
    host.appendChild(findNameCard(d));
    markFind();
    $('findsaid').textContent = 'that name';
    explainWhatWasDrawn(host);
  }).catch(function (e) {
    if (FIND.q !== '\u0000person:' + name) return;
    clear(host);
    host.appendChild(el('div', 'center', String((e && e.message) || e)));
  });
}

/** Everything about one person, drawn where the address card is drawn.

    Asked for on Enter rather than while somebody types: it is several
    queries and a question to somebody else's directory, and it is the
    answer to a question that has been finished rather than to half of one.
    The box stays open afterwards, because the point of it is to be read and
    then pressed. */
function findNameCard(d) {
  var card = el('div', 'findcard');
  var line = el('div', 'fline');
  var big = el('span', 'fbig');
  big.textContent = d.name;
  line.appendChild(big);
  if (isBogus(d.name)) {
    var never = el('span', 'tag crit', 'a name that never existed');
    explain(never, 'This is one of the names under <b>a name that does not exist</b> in '
      + 'Settings. Nobody has ever had it, so every attempt offering it is somebody '
      + 'guessing rather than somebody mistyping.');
    line.appendChild(never);
  }
  /* What it looks like, from the doors it has been seen at. A log gives no
     other sign: `host/PC1.example.int` and `jnovak` are both just names.
     The directory has the last word and overwrites this when it answers. */
  if (d.looks_like) {
    var what = el('span', 'tag info', d.looks_like);
    explain(what, d.looks_like === 'a machine'
      ? 'Only a machine authenticates at a socket or on the wireless with 802.1X or MAB, '
        + 'and this name has been seen at nothing else. Nothing in a log says which a name '
        + 'is \u2014 the door it came through is the sign.'
      : 'This name has been seen at a door a person signs in to. The directory, asked '
        + 'below, is the one place the difference is actually written down.');
    line.appendChild(what);
  }
  var dir = el('span', 'muted small');
  dir.id = 'find-dir-state';
  line.appendChild(dir);
  card.appendChild(line);
  /* Where the directory's answer lands. Kept beside the rest of the card
     rather than in a popup of its own: "who is this and is the account all
     right" is half of what somebody typing a name wants, and making them
     press something else for it is making them ask twice. */
  var about = el('div', 'fwho');
  about.id = 'find-dir-about';
  card.appendChild(about);

  var says = el('div', 'fsays');
  says.textContent = num(d.tries) + ' failed attempt(s), ' + num(d.signed_in)
    + ' successful login(s)';
  card.appendChild(says);
  var doors = (d.doors || []).filter(function (x) { return x.failed || x.passed; });
  if (doors.length) card.appendChild(doorChips(d.name, doors));
  if (d.last && d.last.ts) card.appendChild(lastSeenLine(d.last));
  /* What the firewall's own log saw of the same name, where it is read: the
     lines it is on, the addresses inside the VPN it had, how its last VPN
     sessions ended. */
  if (d.firewall && !d.firewall.none) {
    var fw = d.firewall;
    var chips = el('div', 'cc-row');
    T_ORDER.filter(function (v) { return (fw.by || {})[v]; }).forEach(function (v) {
      var chip = el('button', 'chip', num(fw.by[v]) + ' ' + T_VERDICTS[v].words);
      chip.type = 'button';
      explain(chip, 'The firewall\u2019s lines naming ' + wordsIn(d.name) + ' in the last '
        + (fw.hours || 24) + ' h that it ' + T_VERDICTS[v].words + '. Press for them on '
        + 'the Traffic page.');
      chip.onclick = function () {
        showTab('traffic');
        tOpen('user:' + tQuote(d.name) + ' verdict:' + v, v === 'fail' || v === 'info'
          ? 'events' : 'list');
      };
      chips.appendChild(chip);
    });
    var fwLine = el('div', 'fsays');
    fwLine.appendChild(el('b', '', 'On the firewall: '));
    fwLine.appendChild(document.createTextNode('the last ' + (fw.hours || 24) + ' h'
      + (fw.bytes ? ', ' + bytes(fw.bytes) + ' carried' : '')
      + ((fw.inner || []).length ? ', inside the VPN as ' + fw.inner.join(', ') : '')));
    card.appendChild(fwLine);
    /* ...and on the VPN this moment, pressable for everything about it. */
    (fw.vpn_now || []).forEach(function (v) {
      var now = el('div', 'fsays');
      now.appendChild(el('span', 'tag ok', 'on the VPN now'));
      now.appendChild(document.createTextNode(' ' + (v.since_known ? 'since ' : 'at least since ')
        + shortStamp(v.started) + ' from ' + (v.srcip || '?')
        + (v.inner ? ', inside as ' + v.inner : '') + (v.fw ? ' \u00b7 ' + v.fw : '')));
      opensWith(now, 'Press for everything about this session.', function () {
        closeFind();
        showTab('traffic');
        tShowPage('vpn');
        showVpnOne(v.id);
      });
      card.appendChild(now);
    });
    if (chips.firstChild) card.appendChild(chips);
    (fw.sessions || []).slice(0, 4).forEach(function (one) {
      var line = el('div', 'muted small');
      line.textContent = shortStamp(one.ts) + ' \u2014 ' + (TV_ACTIONS[one.action]
        || FG_ACTIONS[one.action] || one.action)
        + (one.msg ? ': ' + one.msg : '')
        + (one.duration ? ' \u00b7 ' + span(one.duration) : '')
        + (one.sent || one.rcvd ? ' \u00b7 \u2191 ' + bytes(one.sent) + ' \u2193 '
           + bytes(one.rcvd) : '');
      card.appendChild(line);
    });
  }

  /* Where it last authenticated on the network itself: the switch, the
     socket, the VLAN it was put into and the MAC that did it. None of that
     is in a VPN record and all of it is what somebody looking up a machine
     came for. Drawn when there is any - which is itself most of the answer
     to "is this a person or a machine", because only a machine turns up at
     a socket. */
  (d.network || []).slice(0, 2).forEach(function (n) {
    var row = el('div', 'fdoors');
    var tag = el('span', 'tag ' + (n.ok ? 'ok' : 'crit'));
    tag.textContent = n.ok ? 'let on' : 'refused';
    explain(tag, n.said || (n.ok ? 'The network let it on.' : 'The network refused it.'));
    row.appendChild(tag);
    [['at', doorWords(n.kind)], ['switch', n.switch], ['socket', n.port],
     ['network', n.ssid], ['VLAN', n.vlan], ['MAC', n.mac], ['address', n.ip],
     ['node', n.server]].forEach(function (pair) {
      if (!pair[1]) return;
      var one = el('span', 'fdoor');
      one.appendChild(el('b', '', pair[0]));
      one.appendChild(el('span', '', pair[1]));
      row.appendChild(one);
    });
    var when = el('a', 'fgo');
    when.textContent = shortStamp(n.ts);
    explain(when, 'Open this record where it is listed, and light the row.');
    when.onclick = function (e) {
      e.preventDefault();
      goToRecords(n.ok ? 'passed' : 'failed', n.kind, d.name, n.session);
    };
    row.appendChild(when);
    card.appendChild(row);
  });

  /* Where this person comes from. The token attempts are in here through
     the packets beside them: a token row carries the token server's own
     loopback, so somebody who signs in with a token would otherwise look
     as though they came from nowhere. */
  if ((d.addresses || []).length) {
    var from = el('div', 'fdoors');
    from.style.marginTop = '7px';
    d.addresses.forEach(function (a) {
      var one = el('span', 'fdoor');
      var go = el('a', 'fgo mono', a.ip);
      var called = ((d.ptr || {})[a.ip] || {}).name || '';
      explain(go, (called ? 'The reverse zone calls this address <b>' + called + '</b>.\n\n' : '')
        + 'Everything this machine knows about ' + a.ip + ': whether it is kept out '
        + 'and why, what it has tried, and who has got in from it.');
      go.onclick = function (e) { e.preventDefault(); closeFind(); lookUp(a.ip); };
      one.appendChild(go);
      if (called) one.appendChild(el('span', 'ptrname', called));
      if (a.country) one.appendChild(countryBadge(a.country));
      var state = (d.banned || {})[a.ip];
      if (state) {
        one.appendChild(state.carried === false
          ? el('span', 'tag ' + (state.watched ? 'warn' : 'dim'),
               state.watched ? 'only watched' : 'not carried')
          : el('span', 'tag crit', state.forever ? 'banned for good' : 'banned'));
      }
      one.appendChild(el('span', 'muted', num(a.tries) + '\u00d7 \u00b7 ' + shortStamp(a.last)));
      from.appendChild(one);
    });
    card.appendChild(el('div', 'fsays', 'Seen from'));
    card.appendChild(from);
  }

  var doing = el('div', 'fdo');
  var open = cmdButton('Everything about it', 'search', 'small primary');
  explain(open, 'Open the whole record for this name: every attempt, every successful '
    + 'login and every address it has come from.');
  open.onclick = function () {
    closeFind();
    peekName({username: d.name, tries: d.tries, addresses: (d.addresses || []).length,
              last: (d.last || {}).ts});
  };
  doing.appendChild(open);
  card.appendChild(doing);

  /* ...and what the directory says about the account, which is the other
     half of "who is this". Asked for separately and drawn when it answers,
     so the rest of the card is not held up by somebody else's machine.
     Nothing here writes to a directory: it is read, and only read. */
  if (d.directory) {
    dir.textContent = 'asking the directory\u2026';
    api('who&name=' + encodeURIComponent(d.name)).then(function (w) {
      /* Into THIS card's own element, not whatever element currently
         carries that id. Looked up by id, the answer to a slow lookup - a
         name that does not exist searches the whole base - landed in the
         card for the NEXT name typed, which had an element of the same id,
         and said "the directory has no such account" about a person who
         exists. */
      var where = dir;
      if (!where.isConnected) return;           // typed on, card gone
      clear(where);
      if (!w.on) { where.textContent = ''; return; }
      if (!w.found) {
        var none = el('span', 'tag warn', w.asked_both
          ? 'neither directory has such an account' : 'the directory has no such account');
        explain(none, (w.asked_both
          ? 'Neither directory answers to this name. '
          : 'Nothing in the directory answers to this name. ')
          + 'On a list of refused attempts that is the strongest thing there is to know '
          + 'about one: nobody has ever had it.'
          + (w.trouble ? '\n\nThough one of them had trouble answering: ' + w.trouble : ''));
        where.appendChild(none);
        return;
      }
      /* Whether anything is in this account's way, first: it is the
         question the name was typed to answer. */
      (w.marks || []).slice(0, 3).forEach(function (m) {
        var tag = el('span', 'tag ' + (m.tone || 'info'), m.words);
        if (m.says) explain(tag, m.says);
        tag.style.marginLeft = '6px';
        where.appendChild(tag);
      });
      /* ...and then who they are. The whole of what the directory was
         asked for, in the order it hands it over - the name, the
         department, the telephone, when the password was last set and when
         it runs out. Every one of them is read; nothing here writes to a
         directory, ever. */
      var about = $('find-dir-about');
      if (!about) return;
      clear(about);
      /* The directory knows which it is, so its word replaces the guess
         made from the doors. It is the one place the difference is written
         down rather than inferred. */
      var guess = card.querySelector('.fline .tag.info');
      if (guess && (w.machine === true || w.machine === false)) {
        guess.textContent = w.machine ? 'a machine' : 'a person';
        explain(guess, w.machine
          ? 'The directory holds this as a computer account, which is the one place the '
            + 'difference is written down rather than worked out.'
          : 'The directory holds this as a person\u2019s account.');
      }
      /* Which directory said so, drawn EXACTLY as the other one is.

         The two were different shapes: this one put the directory's name
         after the person's, with the domain at the end of it, while the
         other put the directory's name first with the domain beside it and
         the person underneath. Two accounts in two domains read side by
         side have to be the same shape or the eye cannot compare them. So
         both are now: which directory, its domain, what it says about the
         account; then the person; then the facts. */
      if (w.asked_both && w.where_words) {
        var also = w.also || [];
        var head = el('div', 'alsohead');
        head.appendChild(el('b', '', w.where_words));
        if (w.domain) head.appendChild(el('span', 'alias', w.domain));
        (w.marks || []).slice(0, 3).forEach(function (m) {
          var tag = el('span', 'tag ' + (m.tone || 'info'), m.words);
          if (m.says) explain(tag, m.says);
          head.appendChild(tag);
        });
        if (also.length) {
          var from = el('span', 'muted small', 'and in ' + also.map(function (o) {
            return o.where_words; }).join(', '));
          explain(from, 'This name is in <b>both</b> directories. They are two accounts '
            + 'and they can say different things: different groups, and one of them '
            + 'locked out while the other is not. The one shown first is '
            + (w.matched
               ? 'the domain the record named, <b>' + (w.realm || '') + '</b>.'
               : 'the one this site signs in against.')
            + ' What the other one holds is underneath.');
          head.appendChild(from);
        } else {
          explain(head, w.matched
            ? 'The record said this person was resolved in <b>' + (w.realm || '')
              + '</b>, so that directory\u2019s answer is the one shown. Every directory '
              + 'that is switched on was asked; no other one has this name.'
            : 'Every directory that is switched on was asked, at the same time. This is '
              + 'the one that has the name.');
        }
        about.appendChild(head);
      }
      if (w.title) {
        var who = el('div', 'fwhoname');
        who.textContent = w.title;
        about.appendChild(who);
      }
      (w.facts || []).forEach(function (f) {
        var one = el('span', 'fwhofact');
        one.appendChild(el('b', '', f.words));
        var said = el('span', '');
        if (f.kind === 'when' && f.said && f.said.at) {
          said.textContent = shortStamp(f.said.at);
          explain(one, (f.says ? f.says + '\n\n' : '') + stamp(f.said.at)
                  + '  \u2014 ' + ago(f.said.at));
        } else {
          said.textContent = typeof f.said === 'string' ? f.said : String(f.said);
          if (f.says) explain(one, f.says);
        }
        one.appendChild(said);
        about.appendChild(one);
      });
      if (w.group_count) {
        var groups = el('span', 'fwhofact');
        groups.appendChild(el('b', '', 'Groups'));
        groups.appendChild(el('span', '', num(w.group_count)));
        explain(groups, 'The directory groups this account is in. Open the whole record to '
          + 'read them:\n\n'
          + (w.groups || []).slice(0, 24).map(function (g) { return '<code>' + g.name + '</code>'; })
              .join('\n'));
        about.appendChild(groups);
      }
      /* ...and the same name in the other directory, where it is in both.
         A block of its own rather than more chips in the same row: they are
         two accounts in two domains, and running them together is how
         somebody reads one account's groups off the other's card. */
      (w.also || []).forEach(function (o) { about.appendChild(alsoBlock(o)); });
    }).catch(function () {
      if (dir.isConnected) dir.textContent = '';
    });
  }
  return card;
}

/** Which door a row came through, as one small mark. The lists in an
    address's own popup hold every door now, and a row with no tunnel and
    no device on it is otherwise a row with nothing to say what it is. */
function doorCell(kind) {
  var td = el('td', 'placecell');
  var tag = el('span', 'alias', doorWords(kind || 'vpn'));
  explain(tag, (DOOR_SAYS[kind] || {}).says
    || 'Which door this record came through.');
  td.appendChild(tag);
  return td;
}

/** Whether a name is one the settings say never existed. */
function isBogus(name) {
  return (BOGUS || []).indexOf(String(name || '').trim().toLowerCase()) >= 0;
}

/** The card at the top when what was typed is an address: the answer, and
    the two things somebody wants to do about it. */
function findAddressCard(a) {
  var card = el('div', 'findcard');
  var line = el('div', 'fline');
  var big = el('span', 'fbig');
  big.textContent = a.ip;
  line.appendChild(big);
  if (a.country) line.appendChild(countryBadge(a.country));
  if (a.spared) {
    line.appendChild(el('span', 'tag info', 'never kept out'));
  } else if (!a.blocked) {
    line.appendChild(el('span', 'tag ok', 'not banned'));
  } else if (a.carried === false) {
    line.appendChild(el('span', 'tag ' + (a.watched ? 'warn' : 'dim'),
                        a.watched ? 'banned, only watched' : 'banned, not carried'));
  } else if (a.forever) {
    line.appendChild(el('span', 'tag crit', 'banned for good'));
  } else {
    line.appendChild(el('span', 'tag warn', 'banned \u00b7 ' + span(a.until - Date.now() / 1000)
                        + ' left'));
  }
  card.appendChild(line);
  /* What the reverse zone calls it, said outright rather than on hover:
     this card is the answer to somebody typing an address in, and the name
     is the first thing they wanted off it. */
  if (a.ptr && a.ptr.name) {
    var named = el('div', 'ptrname');
    named.appendChild(el('b', '', a.ptr.name));
    if (a.ptr_all > 1) {
      var more = el('span', '', '  \u00b7 ' + (a.ptr_all - 1) + ' name(s) before that');
      explain(more, 'A DHCP lease moves, so this address has been more than one machine. '
        + 'Open it for each name and the days it had it.');
      named.appendChild(more);
    }
    card.appendChild(named);
  }

  /* Counted off the doors rather than off the two tables, so that the line
     and the chips under it agree. They did not: a token attempt's own row
     carries the token server's address, not the person's, so an address
     that signed in with a token was one short in the totals and present in
     the chips - the same card saying two things. */
  var doors = (a.doors || []).filter(function (d) { return d.failed || d.passed; });
  var sum = doors.reduce(function (m, d) {
    return {failed: m.failed + d.failed, passed: m.passed + d.passed};
  }, {failed: 0, passed: 0});
  if (!doors.length) { sum = {failed: a.failed_total || 0, passed: a.passed_total || 0}; }
  var says = el('div', 'fsays');
  says.textContent = num(sum.failed) + ' failed attempt(s), '
    + num(sum.passed) + ' successful login(s)'
    + (a.before ? ', banned ' + a.before + '\u00d7 before' : '')
    + (a.feeds && a.feeds.length ? ' \u00b7 on ' + a.feeds.join(', ') : '')
    + (a.why ? ' \u00b7 ' + a.why : '');
  card.appendChild(says);
  /* Which doors it has been at, and the last time it was seen at any of
     them. Two short lines, because the question behind typing an address
     into this box is nearly always one of two: is it banned, and where does
     it turn up. The totals above answer neither - eleven sign-ins over a
     VPN, a wireless network and a token server are three facts about a
     person and one number about none of them. */
  if (doors.length) card.appendChild(doorChips(a.ip, doors));
  if (a.last && a.last.ts) card.appendChild(lastSeenLine(a.last));
  if ((a.names || []).length) {
    var who = namesRow(a.names);
    who.style.marginTop = '6px';
    card.appendChild(who);
  }

  var doing = el('div', 'fdo');
  var open = cmdButton('Everything about it', 'search', 'small primary');
  explain(open, 'Open the whole record for this address: every attempt, every successful '
    + 'login, every ban it has ever had and why.');
  open.onclick = function () { closeFind(); lookUp(a.ip); };
  doing.appendChild(open);
  if (CAN_BAN && !a.spared) {
    if (a.blocked) {
      if (!a.forever) {
        var hard = cmdButton('Ban for good', 'ban', 'small danger');
        explain(hard, 'Take the clock off and keep this address out until somebody says '
          + 'otherwise. The router is told at once.');
        hard.onclick = function () {
          banNow(a.ip, 0, 'banned from the find box', function () { findAgain(); });
        };
        doing.appendChild(hard);
      }
      var free = cmdButton(a.through ? 'Let the range in' : 'Let it back in', 'undo', 'small');
      explain(free, a.through
        ? 'This address is kept out because the range ' + htmlText(a.through) + ' is banned. '
          + 'Letting it go lets in every address of it with no ban of its own; the ones it was folded from, if any, stay banned as themselves.'
        : 'Let this address reach the VPN again, now. It comes off the router at '
          + 'once and the ban stays in the history.');
      free.onclick = function () {
        var go = function () {
          api('blocked', {remove: a.through || a.ip}).then(function () {
            delete BANNED[a.ip];
            repaintBans(a.ip);
            toast((a.through || a.ip) + ' may come back', 'good');
            tick();
            findAgain();
          }).catch(oops);
        };
        /* The range asked about first, as everywhere else (1.10.200): one
           press let a whole /24 in, and said only the one address. */
        if (a.through) {
          confirmThen('Let the range in', htmlText(a.ip) + ' has no ban of its own: it is kept '
            + 'out because <b>' + htmlText(a.through) + '</b> is. Letting it go lets in every '
            + 'address of it with no ban of its own; the ones it was folded from, if any, stay '
            + 'banned as themselves.', 'Let ' + a.through + ' in', go, false);
        } else {
          go();
        }
      };
      doing.appendChild(free);
    } else {
      var ban = cmdButton('Ban it for good', 'ban', 'small danger');
      explain(ban, 'Keep this address out for good, now, without waiting for it to reach the '
        + 'bar. The router is told at once.');
      ban.onclick = function () {
        banNow(a.ip, 0, 'banned from the find box', function () { findAgain(); });
      };
      doing.appendChild(ban);
    }
    /* The whitelist is a setting: a full admin's, not a ban admin's. */
    if (ADMIN) {
    var never = cmdButton('Never ban it', 'shield', 'small');
    explain(never, 'Put this address under "never kept out": nothing here will ban it again, '
      + 'and if it is banned now it comes off at once.');
    never.onclick = function () {
      api('whitelist', {add: a.ip, note: 'from the find box'}).then(function (d) {
        toast(d.ip + ' will never be banned'
          + ((d.freed || []).length ? ' \u2014 and came off the router' : ''), 'good');
        tick();
        findAgain();
      }).catch(oops);
    };
    doing.appendChild(never);
    }
  }
  card.appendChild(doing);
  return card;
}

function findAgain() { paintFind(true); }

/* Which column the box found a word in, and what to ask the daemon for it
   by. The same map the cards use, the other way round: what the daemon
   calls a hit and what filters it. */
var FIND_WIN_COLUMN = {'account': 'account', 'machine': 'machine', 'address': 'ip',
                       'done by': 'by_who', 'program': 'process', 'object': 'object'};

/** A domain hit from the find box, opened as exactly those events.

    Opened over the window the BOX searched rather than over whatever the
    Domain page is set to, so the count at the top of the popup is the count
    that was pressed.

    An ACCOUNT is the exception, and opens its life instead: somebody who
    types a name into this box is asking about the account, and the first
    thing they want is who made it, who changed it, who unlocked it and who
    deleted it — not four hundred Kerberos tickets newest first. The events
    are one press further in. It is also the only answer there is for an
    account that no longer exists, which is the commonest thing to be looking
    for by name. */
function findPeekDomain(w) {
  if (w.what === 'account') { return winPeekLife(w.said, ''); }
  var column = FIND_WIN_COLUMN[w.what];
  var ask = {routine: '0'};
  if (column) ask[column] = w.said; else ask.q = w.said;
  var days = FIND.domainDays || 7;
  winPeekEvents(
    (w.what.charAt(0).toUpperCase() + w.what.slice(1)) + ' \u201c' + w.said + '\u201d',
    ask,
    'Everything the domain controllers wrote about it. The domain is never '
    + 'judged and never a ban \u2014 this is the half of a refusal that is '
    + 'written down on a controller and nowhere else.',
    w.what === 'account' ? w.said : '',
    /* A machine account is only in these lists when the tick box is on, and
       somebody who pressed one is asking about that machine. */
    {hours: days * 24, machines: /\$$/.test(String(w.said)),
     words: 'the last ' + days + ' day(s)'});
}

/* ==========================================================================
   What this person has looked for (1.10.151)
   --------------------------------------------------------------------------
   Under a line beneath the suggestions, when the box is empty: the searches
   they make most, the most used first - a handful only, so the box never
   needs a scroll bar. Each can be taken away with the cross that appears
   over it. Kept with their account (`user_finds`), carried in the export of
   their settings, and cleared in one go from the account popup. A search is
   remembered when it is acted on (a press, Enter) or its answer has been on
   the screen for a few seconds - not every word typed on the way.
   ========================================================================== */
var FINDS = (ME && Array.isArray(ME.finds)) ? ME.finds : [];
var FINDS_SHOWN = 8;
var FIND_KEEP_SOON = null;
var FIND_KEPT_LAST = {q: '', at: 0};

/** What a pressed row of the box is, so it can be done again: an address
    opened, a person looked up, a page or setting gone to - with the words
    it was found by and what kind of thing it is. */
function findPickOf(it) {
  if (!it) return null;
  if (it.name) return {kind: it.what || 'user name', act: 'person', target: it.name,
                       label: it.name};
  if (it.ip) return {kind: it.what && it.what !== 'address' ? 'address · ' + it.what
                       : 'address', act: 'ip', target: it.ip, label: it.text || it.ip};
  if (['page', 'settings', 'card', 'setting'].indexOf(it.what) >= 0) {
    return {kind: it.what + (it.where ? ' · ' + it.where : ''), act: 'place',
            target: it.text, label: it.text};
  }
  /* Anything else - a MAC, a switch, a command, something in the domain or
     on the firewall: the words it was found by and the line that was
     pressed, so that pressing it again finds it again and presses it. */
  if (it.text && FIND.q) {
    return {kind: it.what || 'found', act: 'redo',
            target: FIND.q + '\u0001' + it.text, label: it.text};
  }
  return null;
}
var FIND_REDO = null;     /* the line to press once a search done again answers */

function findRemember(q, pick) {
  q = String((pick && pick.label) || q || '').replace(/\s+/g, ' ').trim();
  if (q.length < 2) return;
  clearTimeout(FIND_KEEP_SOON);
  var key = pick ? pick.act + '|' + String(pick.target).toLowerCase() : 'q|' + q.toLowerCase();
  /* The same thing a second time within moments is once. */
  if (FIND_KEPT_LAST.q === key && Date.now() - FIND_KEPT_LAST.at < 15000) return;
  FIND_KEPT_LAST = {q: key, at: Date.now()};
  var ask = {add: q};
  if (pick) { ask.kind = pick.kind; ask.act = pick.act; ask.target = pick.target; }
  api('finds', ask).then(function (d) {
    FINDS = d.finds || [];
  }).catch(function () { /* a search not remembered is not worth an error */ });
}

/** Do again what a remembered search did. */
function findReplay(f) {
  var act = f[4], target = f[5];
  if (act === 'ip' && target) { closeFind(); lookUp(target); return true; }
  if (act === 'person' && target) {
    $('findinput').value = target;
    paintFind(true);
    lookUpPerson(target);
    return true;
  }
  if (act === 'place' && target) {
    var place = findPlaces().filter(function (p) { return p.text === target; })[0];
    if (place) { closeFind(); place.go(); return true; }
  }
  if (act === 'redo' && target && target.indexOf('\u0001') > 0) {
    var bits = target.split('\u0001');
    FIND_REDO = {text: bits[1], at: Date.now()};
    $('findinput').value = bits[0];
    FIND.at = 0;
    paintFind(true);
    return true;
  }
  return false;
}

/* A search done again from the history: once its answer is drawn, the line
   that was pressed last time is pressed again - if it is still there. */
function findRedoNow() {
  var want = FIND_REDO;
  FIND_REDO = null;
  if (!want || Date.now() - want.at > 30000) return;
  var row = FIND.rows.filter(function (r) {
    var t = r.querySelector('.ftext .mono') || r.querySelector('.ftext');
    return t && t.textContent.trim() === want.text;
  })[0];
  if (row) row.click();
}

function findHistoryInto(host) {
  if (!FINDS.length) return;
  var top = FINDS.slice().sort(function (a, b) {
    return (b[1] - a[1]) || (b[2] - a[2]);
  }).slice(0, FINDS_SHOWN);
  host.appendChild(el('div', 'findsep'));
  host.appendChild(el('div', 'findgroup', 'Your searches'));
  top.forEach(function (f) {
    var row = el('div', 'finditem findpast' + (FIND.rows.length === FIND.at ? ' on' : ''));
    row.appendChild(el('span', 'ficon', '↺'));
    row.appendChild(el('span', 'ftext', f[0]));
    /* What kind of thing it was, when it was a thing pressed. */
    if (f[3]) row.appendChild(el('span', 'fkind', f[3]));
    row.appendChild(el('span', 'fwhat', f[1] > 1 ? num(f[1]) + '×' : ''));
    var gone = el('button', 'fdel');
    gone.type = 'button';
    gone.setAttribute('aria-label', 'Take “' + f[0] + '” out of your searches');
    gone.innerHTML = iconMarkup('close', 13);
    gone.onclick = function (e) {
      e.stopPropagation();
      api('finds', {drop: f[0], act: f[4] || '', target: f[5] || ''}).then(function (d) {
        FINDS = d.finds || [];
        FIND.at = 0;
        paintFind(true);
        $('findinput').focus();
      }).catch(oops);
    };
    row.appendChild(gone);
    row.onclick = function () {
      findRemember(f[0], f[4] ? {kind: f[3], act: f[4], target: f[5], label: f[0]} : null);
      if (findReplay(f)) return;
      $('findinput').value = f[0];
      FIND.at = 0;
      paintFind(true);
      $('findinput').focus();
    };
    FIND.rows.push(row);
    host.appendChild(row);
  });
}

function paintFind(force) {
  var q = $('findinput').value.trim();
  var host = $('findlist');
  /* Unchanged - a space typed at the end: the list on screen stays, and so
     do the rows the arrows and Enter walk. They were emptied first, so the
     list was there and Enter looked the words up instead. (1.10.155) */
  if (q === FIND.q && !force) return;
  FIND.rows = [];
  FIND.q = q;
  clear(host);
  $('findsaid').textContent = '';
  /* Whatever was on its way for the words before is not for this box any
     more - an emptied one included: the answer for "1.2" landed under an
     empty box and Enter acted on it. (1.10.178) */
  ++FIND.seq;
  clearTimeout(FIND_KEEP_SOON);
  if (!q) {
    host.appendChild(el('div', 'findgroup', 'Try'));
    /* The domain line only where there is a domain being read: a hint that
       leads nowhere is worse than no hint. */
    var hints = [['an address', '185.136.15.20'], ['part of one', '138.226'],
                 ['a user name', 'INVALID']];
    if (STATUS && STATUS.winsec_on) {
      hints.push(['an account, a machine or a program in the domain', 'svc']);
    }
    if (STATUS && STATUS.fwlog_on) {
      hints.push(['a name, a person or a group on the firewall', 'microsoft']);
    }
    hints.push(['a page or a setting', 'router']);
    hints.forEach(function (pair) {
      var row = el('div', 'finditem');
      row.appendChild(el('span', 'ficon', '\u203a'));
      row.appendChild(el('span', 'ftext', pair[0]));
      /* An example of what to type is typed as it is: INVALID is the very
         word ISE writes, not one to translate. */
      row.appendChild(noI18n(el('span', 'fwhat', pair[1])));
      row.onclick = function () { $('findinput').value = pair[1]; paintFind(); };
      host.appendChild(row);
    });
    findHistoryInto(host);
    return;
  }
  /* The pages are here in the browser and answer instantly; the data is on
     the server. Both are drawn as they arrive rather than one waiting for
     the other. */
  var places = findMatch(findPlaces(), q);
  var seq = ++FIND.seq;
  clearTimeout(FIND_KEEP_SOON);
  api('find&q=' + encodeURIComponent(q), undefined, {lane: 'find'}).then(function (d) {
    if (seq !== FIND.seq) return;                  // somebody typed on
    /* An answer somebody has been looking at for a few seconds was a
       search worth remembering; one typed through on the way to another
       was not. */
    FIND_KEEP_SOON = setTimeout(function () {
      /* ...when the answer is the thing itself: one address, drawn whole. */
      if (seq === FIND.seq && !$('findback').hidden && d.address && d.address.ip) {
        findRemember(q, {kind: 'address', act: 'ip', target: d.address.ip,
                         label: d.address.ip});
      }
    }, 3000);
    noteBanned(d);
    clear(host);
    FIND.rows = [];
    var any = false;
    if (d.address) { host.appendChild(findAddressCard(d.address)); any = true; }
    var group = function (words, items) {
      if (!items.length) return;
      any = true;
      host.appendChild(el('div', 'findgroup', words));
      items.forEach(function (it) { host.appendChild(findRow(it, FIND.rows.length)); });
    };
    /* `failed` used to be the whole of what a suggestion could say, because
       the refusals were the only table this box looked in. It now looks in
       every one, so a line says how many times in all and which doors - and
       the doors are what tells two addresses apart at a glance. */
    group('Addresses', (d.addresses || []).map(function (a) {
      var state = (d.banned || {})[a.ip];
      var called = ((d.ptr || {})[a.ip] || {}).name || '';
      return {icon: '\u25c9', text: a.ip, mono: true,
              tail: (called ? called + ' \u00b7 ' : '')
                + num(a.tries) + ' record(s) \u00b7 ' + shortStamp(a.last)
                + ((a.doors || []).length
                   ? ' \u00b7 ' + a.doors.map(doorWords).join(', ') : '')
                + (state ? (state.carried === false ? (state.watched ? ' \u00b7 only watched'
                                                     : ' \u00b7 not carried')
                           : (state.forever ? ' \u00b7 banned for good' : ' \u00b7 banned')) : ''),
              what: a.country || 'address',
              ip: a.ip, go: function () { lookUp(a.ip); }};
    }));
    /* Addresses found by what they are CALLED. Nothing in any record holds
       the name, so this is the only way a machine can be looked up by the
       name somebody knows it by - and on a site with a reverse zone that is
       how people think of their machines. */
    group('Machines, by name', (d.machines || []).map(function (m) {
      var state = (d.banned || {})[m.ip];
      return {icon: '\u2317', text: m.name, mono: true,
              tail: m.ip + ' \u00b7 ' + shortStamp(m.last)
                + (state ? (state.carried === false ? (state.watched ? ' \u00b7 only watched'
                                                     : ' \u00b7 not carried')
                           : (state.forever ? ' \u00b7 banned for good' : ' \u00b7 banned')) : ''),
              what: 'a name in the reverse zone',
              ip: m.ip, go: function () { lookUp(m.ip); }};
    }));
    group('Banned now', (d.bans || []).map(function (b) {
      return {icon: '\u26d4', text: b.ip, mono: true,
              tail: (b.carried === false ? (b.watched ? 'only watched' : 'not carried')
                     : (b.forever ? 'for good' : 'on a clock')) + ' \u00b7 ' + (b.why || ''),
              what: 'banned', ip: b.ip, go: function () { lookUp(b.ip); }};
    }));
    /* Not "names being tried" any more: a name that has only ever signed in
       was not in here at all, which on any normal site is nearly everybody.
       A name goes to whichever page it actually has something on. */
    group('Names', (d.names || []).map(function (n) {
      /* Marked as a name, so that Enter asks about it rather than opening
         a list with it in the box. */
      var bits = [];
      if (n.signed_in) bits.push(num(n.signed_in) + ' signed in');
      if (n.tries) bits.push(num(n.tries) + ' refused');
      var mostly = n.signed_in && !n.tries ? 'logins' : 'failed';
      /* The door the name is actually at, on that side: an NPS machine or a
         tac_plus sitting is not behind whichever door was open last. */
      var at = ((n.doors || {})[mostly === 'logins' ? 'passed' : 'failed'] || [])[0];
      if (at && DOOR_SAYS[at]) {
        return {icon: '\u25cb', text: n.name, mono: true, name: n.name,
                tail: bits.join(' \u00b7 ') + ' \u00b7 ' + num(n.addresses) + ' address(es)'
                  + (n.last ? ' \u00b7 ' + shortStamp(n.last) : '')
                  + ' \u00b7 ' + ((n.doors || {})[mostly === 'logins' ? 'passed' : 'failed']
                                   || []).map(doorWords).join(', '),
                what: 'user name',
                go: function () {
                  goToRecords(mostly === 'logins' ? 'passed' : 'failed', at, n.name);
                }};
      }
      return {icon: '\u25cb', text: n.name, mono: true, name: n.name,
              tail: bits.join(' \u00b7 ') + ' \u00b7 ' + num(n.addresses) + ' address(es)'
                + (n.last ? ' \u00b7 ' + shortStamp(n.last) : ''),
              what: 'user name',
              go: function () {
                showTab(mostly === 'logins' ? 'logins' : 'failed');
                setTimeout(function () {
                  var box = $(mostly === 'logins' ? 'p-q' : 'f-q');
                  if (box) box.value = n.name;
                  if (mostly === 'logins') { PAGE.passed = 0; loadPassed(); }
                  else { PAGE.failed = 0; loadFailed(); }
                }, 80);
              }};
    }));
    /* ...and everything else the rows hold, from every module alike: a
       machine by its MAC, the address a machine was given, a network device
       by name, a command typed on one. Each goes to the door it is busiest
       at, with what was typed in that list's box. */
    var doorOf = function (kind) {
      if (kind === 'tacacs-cmd') return 'tacacs';
      if (kind === 'tacplus-cmd') return 'tacplus';
      return DOOR_SAYS[kind] ? kind : 'other';
    };
    var hits = function (o) {
      var bits = [];
      if (o.passed) bits.push(num(o.passed) + ' let through');
      if (o.failed) bits.push(num(o.failed) + ' refused');
      return bits.join(' \u00b7 ') + (o.last ? ' \u00b7 ' + shortStamp(o.last) : '')
        + ((o.kinds || []).length ? ' \u00b7 ' + o.kinds.map(doorWords).join(', ') : '');
    };
    var goOn = function (o, q) {
      return function () {
        var side = o.passed >= o.failed ? 'passed' : 'failed';
        /* The door it is busiest at ON THAT SIDE: a machine refused by MAB
           and let on by 802.1X is at two doors, and the sign-ins are not
           behind the door the refusals are. */
        var kinds = (o.kinds_by || {})[side] || o.kinds || [];
        goToRecords(side, doorOf(kinds[0]), q);
      };
    };
    group('Machines, by MAC', (d.macs || []).map(function (o) {
      return {icon: '\u25a3', text: o.said, mono: true,
              tail: (o.name && o.name !== o.said.replace(/-/g, '').toLowerCase()
                     ? o.name + ' \u00b7 ' : '') + hits(o),
              what: 'MAC address', go: goOn(o, o.said)};
    }));
    group('Addresses machines were given', (d.clients || []).map(function (o) {
      return {icon: '\u25ce', text: o.said, mono: true,
              tail: (o.name ? o.name + ' \u00b7 ' : '') + hits(o),
              what: 'a machine\u2019s own address', go: goOn(o, o.said)};
    }));
    group('Network devices', (d.devices || []).map(function (o) {
      return {icon: '\u25a6', text: o.said, mono: true, tail: hits(o),
              what: 'switch, controller or head end', go: goOn(o, o.said)};
    }));
    group('Commands typed on the kit', (d.commands || []).map(function (o) {
      return {icon: '\u203a', text: o.said, mono: true,
              tail: (o.name ? o.name + ' \u00b7 ' : '') + hits(o),
              what: 'a command', go: function () {
                goToRecords('passed', doorOf((o.kinds || [])[0]), o.name || '');
              }};
    }));
    /* ...and what the domain controllers have on it.

       The box says it looks through everything this machine has recorded,
       and on a site reading its controllers that is another quarter of a
       million events - the half of a refusal that is written down on a
       controller and nowhere else. A name that has never touched the VPN
       and is being hammered on the domain came back "nothing here matches".

       One line an answer rather than one line a place to go and look: what
       the thing IS, what it has been doing, and where from. Pressing it
       opens exactly those events, the same way pressing a card does. */
    FIND.domainDays = d.domain_days || 7;
    group('In the domain, the last ' + num(FIND.domainDays) + ' day(s)',
          (d.domain || []).map(function (w) {
      var bits = [];
      if (w.locked) bits.push(num(w.locked) + ' locked out');
      if (w.failed) bits.push(num(w.failed) + ' refused');
