  api('power').then(function (d) { PW.d = d; PW.failSince = 0; drawPower(); pwPollFor(); }).catch(oops);
}
function pwLive(d) { var p = (d || {}).plan || {}; return !!p.id && ['asked', 'going'].indexOf(p.state) >= 0; }
function pwPollFor() {
  var live = pwLive(PW.d) || PW.reload;
