    if (!pwLive(d)) {
      clearInterval(PW.poll); PW.poll = null;
      if (wasAway || PW.reload) {
        PW.reload = false;
        toast(d.plan && d.plan.how === 'poweroff' ? 'switched on again' : 'up again', 'good');
        setTimeout(function () { location.reload(); }, 2500);
      }
    }
