  if (p.state === 'back') return {k: 'ok', w: p.how === 'reboot' ? 'up again' : 'switched on again'};
  if (p.state === 'going') {
    if (p.how === 'poweroff') return {k: 'going', w: 'switching off'};
    if (d.now < (p.down_at || 0) + 15) return {k: 'going', w: 'going down'};
