      api('osup', undefined, {quiet: true}).then(function (d) { OU.d = d; OU.away = 0; drawOsup(true); if (!ouLive(d)) ouPoll(false); })
        .catch(function (e) { if (e && e.stopped && !e.busy) return; OU.away = OU.away || Date.now(); drawOsup(true); });
    }, 2500);
