}
function rbPutBackConfirm(what) {
  var pw = null;
  modal('Put this backup back?', function (outer) {
    var body = el('div', 'rb-box');
    outer.appendChild(body);
    var facts = [];
    if (what.when) facts.push(['Made', stamp(what.when)]);
    if (what.host) facts.push(['On', what.host]);
    if (what.manifest) {
      var m = what.manifest;
      facts = [['Made', m.made_words], ['On', m.host + ' (' + (m.fqdn || '') + ')'], ['isemon', m.isemon], ['Database', m.engine_words || m.engine], ['The copy in it', rbBytes(m.copy_bytes)]];
      if (m.what === 'config') facts[4] = ['The copy in it', rbBytes(m.config_bytes)];
    }
    var conf = what.what === 'config' || (what.manifest && what.manifest.what === 'config');
    if (facts.length) {
      var dl = el('dl', 'cert-kv');
      facts.forEach(function (f) { dl.appendChild(el('dt', '', f[0])); dl.appendChild(noI18n(el('dd', '', f[1] || '–'))); });
      body.appendChild(dl);
    }
    if (what.said) body.appendChild(noI18n(el('p', 'note warn', what.said)));
    if (conf) body.appendChild(el('p', 'note', 'This backup holds the configuration only. Its keys are put in place and the configuration is put back - the settings, the accounts, the whitelist and the bans, the certificate and the firewall of the pages, the destinations of the backups. Every log record here stays as it is.'));
    else body.appendChild(el('p', 'note warn', 'Everything in the database is replaced with what the backup holds - every record, the bans, the accounts, every setting, the certificate of the pages - and its keys are put in place. You sign in again afterwards, with an account the backup has. A copy of what is here now is made first (Settings → The database).'));
    pw = rbMask('', what.encrypted === false ? '(not locked)' : 'empty: the password of the backups set here');
    body.appendChild(wrField('Its password', pw, 'Only when it was locked with another password than the one set here now.'));
  }, [{words: 'No, leave it', close: true},
      {words: 'Put it back', cls: 'danger', icon: 'undo', close: true, go: function () {
        var ask = {action: 'restore', password: pw.value};
        if (what.upload) ask.upload = what.upload; else { ask.id = what.id; ask.name = what.name; }
        api('rbackup', ask).then(function (x) {
          toast(x.message, 'good');
          rbRestoreWatch(x.job_id);
        }).catch(oops);
      }}], true);
}
function rbRestoreWatch(jid) {
  modal('Putting the backup back', function (body) {
    var bar = el('div', 'prog');
    var fill = el('span');
    fill.id = 'rbr-fill';
    bar.appendChild(fill);
    body.appendChild(bar);
    var says = el('div', 'btnhelp');
    says.id = 'rbr-says';
    body.appendChild(says);
  }, [{words: 'Close', close: true}], true);
  var step = function () {
    api('job&id=' + encodeURIComponent(jid), undefined, {quiet: true}).then(function (d) {
      var j = d.job || {};
      if ($('rbr-fill')) $('rbr-fill').style.width = (j.total ? Math.round(100 * j.done_n / j.total) : 5) + '%';
      if ($('rbr-says')) $('rbr-says').textContent = j.last || '';
      if (!j.done) { setTimeout(step, 1000); return; }
      if (!j.ok) { if ($('rbr-says')) $('rbr-says').textContent = j.error; toast('putting it back failed: ' + j.error, 'bad'); return; }
      var r = j.result || {};
      if ($('rbr-says')) {
        var said = $('rbr-says');
        clear(said);
        said.appendChild(el('div', '', 'Put back.'));
        if ((r.carried || []).length) said.appendChild(noI18n(el('div', 'small', (r.carried || []).join(', '))));
        if (r.safety) said.appendChild(noI18n(el('div', 'small muted', r.safety)));
        /* A configuration put back says what it could not bring (1.10.238),
           and the page stays until it is read. */
        if (r.what === 'config') said.appendChild(el('div', 'small', r.message || ''));
      }
      toast('the backup is back', 'good');
      if (!(r.missing || []).length) setTimeout(function () { location.reload(); }, 4000);
    }).catch(function () {
      /* Who was signed in is what the backup says now: api() takes the page
         to the sign-in when the session is gone. */
      setTimeout(step, 2000);
    });
  };
  setTimeout(step, 500);
}
function rbPutBackFile() {
  var file = el('input');
  file.type = 'file';
  file.accept = '.enc,.gz';
  file.onchange = function () {
    var fl = file.files[0];
    if (!fl) return;
    toast('sending ' + fl.name + '…', 'good');
    fetch('?api=rbackup-upload', {method: 'POST', body: fl, credentials: 'same-origin',
                                  headers: {'X-Isemon-Rbackup': '1', 'Content-Type': 'application/octet-stream'}})
      .then(function (r) {
        return r.json().catch(function () {
          throw new Error('the server did not answer with anything readable (HTTP ' + r.status + ')');
        }).then(function (d) {
          if (!r.ok || d.ok === false) throw new Error(d.error || ('the server said ' + r.status));
          return d;
        });
      }).then(function (d) {
        rbPutBackConfirm({upload: d.upload, encrypted: d.locked, manifest: d.manifest, said: d.said,
                          what: /-config\.tar\.gz/.test(fl.name) ? 'config' : ''});
      }).catch(oops);
  };
  file.click();
}
</script>
<script nonce="<?= h($nonce) ?>">
/* ==========================================================================
   Firewall and access, Certificates and TLS, Upgrades (1.10.222)
   --------------------------------------------------------------------------
   Drawn as otp draws the same three: what is asked is kept by the daemon,
   root puts it in (isemon_web.py, isemon_upgrade.py) and says how it went.
   The firewall's changes wait for the save bar, as every setting does.
   ========================================================================== */
/* Changes of a pane that are not settings, saved by the same bar. */
var EXTRA_SAVES = {};
function extraPending(key, hooks) {
  EXTRA_SAVES[key] = hooks;
  markDirtyCount();
}
function extraDone(key) {
  delete EXTRA_SAVES[key];
  markDirtyCount();
}
function paneLive(name) {
  return TAB === 'settings' && PANE === name && $('pane-' + name) && !$('pane-' + name).hidden;
}
/* A promise of yes or no, from a popup. */
function askThen(title, words, buttonWords, danger) {
  return new Promise(function (ok) {
    var said = false;
    modal(title, function (body) {
      body.appendChild(el('p', 'note', words));
    }, [{words: 'No, leave it', close: true, go: function () { said = true; ok(false); }},
        {words: buttonWords, cls: danger ? 'danger' : 'primary', close: true,
         go: function () { said = true; ok(true); }}], true);
    var was = MODAL_CLOSE;
    MODAL_CLOSE = function () { if (was) was(); if (!said) ok(false); };
  });
}
function wrSwitch(on, onchange, disabled) {
  var wrap = el('label', 'sw');
  var input = document.createElement('input');
  input.type = 'checkbox';
  input.checked = !!on;
  input.disabled = !!disabled;
  wrap.appendChild(input);
  wrap.appendChild(el('span', 'knob'));
  wrap._input = input;
  wrap._get = function () { return input.checked; };
  if (onchange) input.addEventListener('change', function () { onchange(input.checked); });
  return wrap;
}
function wrSeg(opts, value, onpick, disabled) {
  var seg = el('div', 'seg');
  opts.forEach(function (o) {
    var b = el('button', '', o[1]);
    b.type = 'button';
    b.disabled = !!disabled;
    if (String(value) === String(o[0])) b.classList.add('on');
    b.onclick = function () {
      Array.prototype.forEach.call(seg.children, function (x) { x.classList.toggle('on', x === b); });
      onpick(o[0]);
    };
    seg.appendChild(b);
  });
  return seg;
}
function wrRow(words, says, control) {
  var row = el('div', 'arow');
  var t = el('div', 'arow-t');
  t.appendChild(el('div', 'arow-k', words));
  if (says) t.appendChild(el('div', 'arow-s', says));
  row.appendChild(t);
  var c = el('div', 'arow-c');
  c.appendChild(control);
  row.appendChild(c);
  return row;
}
function wrField(words, control, help) {
  /* A switch is a label of its own: one label inside another is not HTML. */
  var f = el(control && control.tagName === 'LABEL' ? 'div' : 'label', 'wr-field');
  f.appendChild(el('span', '', words));
  f.appendChild(control);
  if (help) f.appendChild(el('span', 'wr-help', help));
  return f;
}
function wrText(value, placeholder, cls) {
  var t = el('input', 'wr-in' + (cls ? ' ' + cls : ''));
  t.type = 'text';
  t.value = value || '';
  t.placeholder = placeholder || '';
  t.spellcheck = false;
  return t;
}
function wrSelect(opts, value) {
  var s = el('select', 'wr-in');
  opts.forEach(function (o) {
    var op = document.createElement('option');
    op.value = o[0];
    op.textContent = o[1];
    s.appendChild(op);
  });
  s.value = String(value);
  return s;
}
/* What root is doing, as a bar: the steps done, and in the long one - making
   DH parameters - the time gone against the time it usually takes. */
function wrProgress(p) {
  var box = el('div', 'cert-prog');
  var total = Number(p.total) || 5, step = Math.max(1, Number(p.step) || 1);
  var gone = Math.max(0, Date.now() / 1000 - (Number(p.at) || 0));
  var part = p.expect_s ? Math.min(0.95, gone / Number(p.expect_s)) : 0.5;
  var pct = Math.min(99, Math.round(((step - 1) + part) / total * 100));
  var head = el('div', 'cert-prog-h');
  head.appendChild(el('span', '', p.words || 'working'));
  head.appendChild(noI18n(el('b', '', pct + ' %')));
  box.appendChild(head);
  var bar = el('div', 'cert-prog-bar');
  var fill = el('span', '');
  fill.style.width = pct + '%';
  bar.appendChild(fill);
  box.appendChild(bar);
  box.appendChild(el('div', 'cert-prog-s', p.expect_s
    ? 'usually about ' + Math.max(1, Math.round(p.expect_s / 60)) + ' min'
    : 'step ' + step + ' of ' + total));
  return box;
}
/* Root's side, said in one line, and what to do when it failed. */
function wrRootLine(r, what, quiet) {
  var box = el('div', '');
  if (!r) return box;
  if (!r.helper) {
    box.appendChild(el('p', 'note warn', 'Root’s half of this is not installed on this machine '
      + 'yet (isemon-web.path): run ./install.sh --upgrade from the 1.10.222 package (or later) '
      + 'once. Until then what is saved here is kept, and put in as soon as it is there.'));
    return box;
  }
  if (r.progress) { box.appendChild(wrProgress(r.progress)); return box; }
  var line = el('div', 'fw-state');
  var tone, words;
  if (!r.asked) { tone = ''; words = 'nothing of ' + what + ' is asked of root - the files are as they were'; }
  else if (r.pending) { tone = 'warn'; words = 'waiting for root…'; }
  else if (r.state === 'failed' && !r.current) { tone = 'crit'; words = 'root did not put it in'; }
  else if (r.current) { tone = 'ok'; words = 'in place' + (r.at ? ' · ' + ago(r.at) : ''); }
  else { tone = 'warn'; words = 'not put in yet'; }
  line.appendChild(el('span', 'dot ' + tone));
  line.appendChild(el('span', '', words));
  box.appendChild(line);
  if (r.state === 'failed' && !r.current && (r.said || []).length) {
    var bad = el('div', 'note bad');
    bad.style.marginTop = '8px';
    bad.appendChild(el('b', '', 'What root said:'));
    bad.appendChild(noI18n(el('span', 'mono', r.said[r.said.length - 1])));
    if (ADMIN) {
      var again = cmdButton('Try again', 'refresh', 'small');
      again.onclick = function () {
        api('web-firewall', {action: 'retry'}).then(function (x) { toast(x.message, 'good'); }).catch(oops);
      };
      bad.appendChild(again);
    }
    box.appendChild(bad);
  }
  return box;
}

/* ---- Firewall and access ------------------------------------------------- */
var FW = {last: null, timer: null, fam: '4', draft: null, dirty: false, ver: 0, otherOpen: false};
function fwFromServer(d) {
  return JSON.parse(JSON.stringify({on: !!d.conf.on, off: d.conf.off || [], rules: d.conf.rules || [],
                                    logs: d.conf.logs || {any: true, from: []},
                                    otptls: d.conf.otptls || {any: true, from: []},
                                    access: d.access, access_changed: false}));
