  var ask = Promise.resolve(true);
  if (dr.on && !was) {
    ask = askThen('Let isemon look after the firewall',
      'isemon puts a chain of its own, ISEMON-IN, first in INPUT, for IPv4 and IPv6, and keeps it in '
      + '/etc/sysconfig/iptables and ip6tables. Your own rules stay as they are; ISEMON-IN only adds '
      + 'to them - what it does not let in goes on to them. SSH stays open (a rule of isemon’s, '
      + 'which you can turn off).', 'Turn it on');
  } else if (!dr.on && was) {
    ask = askThen('Take isemon’s rules away', 'The chain ISEMON-IN and its jump go; the rest of '
      + 'the firewall stays exactly as it is. Whatever only ISEMON-IN let in is then up to your own '
      + 'rules.', 'Take them away', true);
