  TLS.timer = setInterval(function () {
    if (!paneLive('tls')) { clearInterval(TLS.timer); return; }
    if (document.hidden) return;
    if ($('modal') && !$('modal').hidden) return;
    api('web-tls', undefined, {quiet: true}).then(drawTls).catch(function () {});
  }, 5000);
