                                         modern: 'TLS 1.3 only', custom: 'custom'}[s.preset || 'standard'] || s.preset));
    if (s.dh && s.dh !== 'none') chips.appendChild(noI18n(el('span', 'cchip', 'DH ' + s.dh)));
    if (s.hsts) chips.appendChild(el('span', 'cchip', 'HSTS ' + Math.round(s.hsts / 86400) + ' days'));
  } else {
    if (d.now && d.now.protocols) chips.appendChild(noI18n(el('span', 'cchip', d.now.protocols)));
