    var dhSel = wrSelect(DH, st.dh);
    dhSel.onchange = function () { st.dh = dhSel.value; paint(); };
    dhRow = wrRow('DH parameters', 'Only the DHE ciphers use them (Mozilla intermediate, or your own). An '
