    function send(file) {
      if (!file) return;
      $('up-drop-says').textContent = 'checking ' + file.name + ' (' + bytes(file.size) + ')…';
      upgradeSend(file).then(function (d) {
        toast(d.message || 'checked', 'good');
        $('up-drop-says').textContent = idle;
        drawUpgrade(d);
